def configure_console_errors() -> None:
    for stream in (sys.stdout, sys.stderr):
        reconfigure = getattr(stream, "reconfigure", None)
        if reconfigure is None:
            continue
        try:
            reconfigure(errors="backslashreplace")
        except OSError:
            pass

def utc_now() -> str:
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat()


def consecutive_ranges(values: Iterable[int]) -> list[tuple[int, int]]:
    ordered = sorted(set(values))
    if not ordered:
        return []
    ranges: list[tuple[int, int]] = []
    start = previous = ordered[0]
    for value in ordered[1:]:
        if value == previous + 1:
            previous = value
            continue
        ranges.append((start, previous))
        start = previous = value
    ranges.append((start, previous))
    return ranges


def compact_json_value(value: Any, limit: int = 180) -> str:
    rendered = json.dumps(value, ensure_ascii=False)
    if len(rendered) <= limit:
        return rendered
    return rendered[: limit - 3] + "..."


def exact_mismatch_context(text: str, index: int, radius: int = 72) -> str:
    start = max(0, index - radius)
    end = min(len(text), index + radius + 1)
    context = text[start:end]
    if start:
        context = "..." + context
    if end < len(text):
        context += "..."
    return json.dumps(context, ensure_ascii=False)


def exact_mismatch_detail(expected: Any, actual: Any) -> str:
    expected_text = expected if isinstance(expected, str) else str(expected)
    actual_text = actual if isinstance(actual, str) else str(actual)
    shared = min(len(expected_text), len(actual_text))
    index = next(
        (
            offset
            for offset in range(shared)
            if expected_text[offset] != actual_text[offset]
        ),
        shared,
    )
    prefix = expected_text[:index]
    line = prefix.count("\n") + 1
    last_newline = prefix.rfind("\n")
    column = index + 1 if last_newline < 0 else index - last_newline
    return (
        f"first difference at character {index + 1} "
        f"(line {line}, column {column}); "
        f"expected={exact_mismatch_context(expected_text, index)}; "
        f"actual={exact_mismatch_context(actual_text, index)}"
    )


def protocol_identity() -> dict[str, Any]:
    return {
        "skill_name": SKILL_NAME,
        "skill_version": SKILL_VERSION,
        "evidence_contract_version": EVIDENCE_CONTRACT_VERSION,
        "artifact_schema_version": SCHEMA_VERSION,
        "method_interface_schema_version": METHOD_INTERFACE_SCHEMA_VERSION,
        "closure_contract_version": CLOSURE_CONTRACT_VERSION,
        "validator_sha256": canonical_sha256({name: sha256_portable_text_file(Path(__file__).resolve().with_name(name))
            for name in ("proofcheck.py", "proofcheck_sources.py", "proofcheck_authoring.py", "proofcheck_reconcile.py")}),
    }


def context_protocol_identity(root: Path, manifest: dict[str, Any]) -> dict[str, Any]:
    """Retain an authenticated historical packet salt, never validation results."""
    current = protocol_identity()
    if "context_protocol" not in manifest:
        return current
    anchor = manifest["context_protocol"]
    if not isinstance(anchor, dict) or set(anchor) != {
        "protocol", "original_manifest_file", "original_manifest_sha256"
    }:
        raise ValueError("context_protocol requires protocol and its exact original manifest file/hash")
    identity = anchor.get("protocol")
    if not isinstance(identity, dict) or set(identity) != set(current):
        raise ValueError("context_protocol.protocol has missing or unknown identity fields")
    for field, expected in current.items():
        if field in {"skill_version", "validator_sha256"}:
            continue
        if type(identity.get(field)) is not type(expected) or identity.get(field) != expected:
            raise ValueError(f"context_protocol.protocol.{field} is incompatible with current contracts")
    if not is_nonempty_string(identity.get("skill_version")) or not isinstance(identity.get("validator_sha256"), str) or not SHA256_RE.fullmatch(identity["validator_sha256"]):
        raise ValueError("context_protocol needs a recorded skill version and validator SHA-256")
    digest = anchor.get("original_manifest_sha256")
    if not isinstance(digest, str) or not SHA256_RE.fullmatch(digest):
        raise ValueError("context_protocol original manifest SHA-256 is invalid")
    relative = f"audit/06_reports/history/context-protocol-{digest}.json"
    if anchor.get("original_manifest_file") != relative:
        raise ValueError("context_protocol original manifest must use its exact history path")
    errors: list[str] = []
    path, valid = canonical_artifact_path(root, relative, "Context protocol origin", errors)
    if not valid or path is None or not path.is_file() or sha256_file(path) != digest:
        raise ValueError("context_protocol original manifest is missing, redirected, or changed: " + "; ".join(errors))
    original, errors = load_json_object(path, "context protocol original manifest")
    if errors or original.get("schema_version") != SCHEMA_VERSION or "context_protocol" in original or not isinstance(original.get("protocol"), dict):
        raise ValueError("context_protocol original manifest must contain its unmodified first protocol")
    recorded = dict(original["protocol"])
    recorded.pop("challenge_contract_version", None)
    if recorded != identity:
        raise ValueError("context_protocol identity differs from its preserved original manifest")
    return dict(identity)


def report_module(name: str) -> Any:
    """Load a local component without adding a runtime dependency."""
    path = Path(__file__).resolve().with_name(name + ".py")
    key = "_stat_paper_" + name
    digest = sha256_portable_text_file(path)
    module = sys.modules.get(key)
    if module is None or getattr(module, "_loaded_digest", None) != digest:
        spec = importlib.util.spec_from_file_location(key, path)
        if spec is None or spec.loader is None:
            raise ValueError(f"Cannot load local component: {path}")
        module = importlib.util.module_from_spec(spec)
        sys.modules[key] = module
        spec.loader.exec_module(module)
        module._loaded_digest = digest
    return module


def report_renderer() -> Any:
    return report_module("proofcheck_report")


def source_fragment_support() -> Any:
    return report_module("proofcheck_sources")


def source_coverage_bounds(ledger: dict[str, Any]) -> tuple[Any, Any]:
    return source_fragment_support().bounds(ledger)


def source_unit_location(ledger: dict[str, Any], unit: dict[str, Any]) -> dict[str, Any]:
    """Map coverage positions to one exact, original manuscript source span."""
    return source_fragment_support().location(ledger, unit)


def locked_line_is_non_substantive(row: dict[str, Any]) -> bool:
    return isinstance(row, dict) and (row.get("include_directive") is True or row.get("proof_wrapper") is True or is_non_substantive(row.get("text", "")))


def report_api() -> Any:
    return SimpleNamespace(**globals())


def cmd_submit_unit(args: argparse.Namespace) -> int:
    result = report_module("proofcheck_authoring").submit_unit(
        report_api(), ledger_path=args.ledger, annotations_path=args.annotations,
        packet_path=args.packet)
    print(json.dumps(result, ensure_ascii=False, indent=2))
    return 0


def cmd_source_lookup(args: argparse.Namespace) -> int:
    result = report_module("proofcheck_authoring").source_lookup(
        report_api(), ledger_path=args.ledger, part=args.part, lines=args.lines,
        annotations_path=args.annotations, step_key=args.step_key,
        packet_path=args.packet, reference=args.reference)
    print(json.dumps(result, ensure_ascii=False, indent=2))
    return 0


def cmd_submit_reconciliation(args: argparse.Namespace) -> int:
    return report_module("proofcheck_reconcile").cmd_submit_reconciliation(args, globals())


def uses_html_report(manifest: dict[str, Any]) -> bool:
    value = manifest.get("report_contract")
    return isinstance(value, dict) and value.get("version") == 2


def preferred_report_path(manifest: dict[str, Any]) -> str:
    if uses_html_report(manifest):
        return report_module("proofcheck_release").primary_report(manifest)
    return "audit/06_reports/FINAL_REPORT.md"


def unchanged_final_delivery(root: Path) -> dict[str, Any] | None:
    """Return a current delivery without rewriting its historical bytes."""
    if not (root / "audit/06_reports/FINALIZATION.json").is_file():
        return None
    freshness = check_finalization_freshness(root)
    if not freshness.get("usable_finalization"):
        return None
    _, manifest, errors = load_audit_manifest(root)
    if errors:
        return None
    return {
        "audit_root": str(root), "delivery_status": "FINAL",
        "usable_finalization": True, "unchanged": True,
        "report": str(root / preferred_report_path(manifest)),
        "finalization_record": freshness["record"], "errors": 0,
    }


def cmd_report(args: argparse.Namespace) -> int:
    root = args.root.resolve()
    lock_error = migration_update_lock_error(root)
    if lock_error:
        raise ValueError(lock_error)
    result = unchanged_final_delivery(root)
    if result is None:
        result = report_module("proofcheck_release").render_working(report_api(), root)
    print(json.dumps(result, ensure_ascii=False, indent=2))
    return 0


def cmd_migrate_report(args: argparse.Namespace) -> int:
    root = args.root.resolve()
    lock_error = migration_update_lock_error(root)
    if lock_error:
        raise ValueError(lock_error)
    result = report_module("proofcheck_release").migrate(
        report_api(), root, markdown=bool(getattr(args, "markdown", False)),
        top_level=bool(getattr(args, "top_level", False)))
    print(json.dumps(result, ensure_ascii=False, indent=2))
    return 0


def challenge_contract_version(manifest: dict[str, Any]) -> int:
    protocol = manifest.get("protocol")
    value = protocol.get("challenge_contract_version", 1) if isinstance(protocol, dict) else 1
    if type(value) is not int or value not in {1, 2, 3}:
        raise ValueError("protocol.challenge_contract_version must be 1, 2, or 3")
    return value


def protocol_matches_current(value: Any) -> bool:
    """Allow only the declared optional challenge contract beside core identity."""
    if not isinstance(value, dict):
        return False
    core = dict(value)
    version = core.pop("challenge_contract_version", 1)
    return type(version) is int and version in {1, 2, 3} and core == protocol_identity()


def retain_challenge_contract(
    protocol: dict[str, Any], manifest: dict[str, Any]
) -> dict[str, Any]:
    result = dict(protocol)
    recorded = manifest.get("protocol")
    if isinstance(recorded, dict) and "challenge_contract_version" in recorded:
        result["challenge_contract_version"] = challenge_contract_version(manifest)
    return result



def sha256_text(text: str) -> str:
    return hashlib.sha256(text.encode("utf-8")).hexdigest()


_FILE_DIGEST_SNAPSHOT: ContextVar[
    dict[tuple[str, Path], str] | None
] = ContextVar("proofcheck_file_digest_snapshot", default=None)


@contextmanager
def gate_digest_snapshot():
    """Hash each file once within one read-only gate invocation."""
    existing = _FILE_DIGEST_SNAPSHOT.get()
    if existing is not None:
        yield
        return
    token = _FILE_DIGEST_SNAPSHOT.set({})
    try:
        yield
    finally:
        _FILE_DIGEST_SNAPSHOT.reset(token)


_GATE_CONTEXT_CACHE: ContextVar[dict[Any, Any] | None] = ContextVar(
    "proofcheck_gate_context_cache", default=None)


def _gate_argument_key(value: Any) -> Any:
    """Keep argument types distinct; unfamiliar iterable inputs bypass reuse."""
    if isinstance(value, Path):
        return ("path", str(value))
    if type(value) in (str, int, float, bool, type(None)):
        return (type(value).__name__, value)
    if isinstance(value, dict):
        return ("dict", tuple(sorted((key, _gate_argument_key(item)) for key, item in value.items())))
    if isinstance(value, (list, tuple)):
        return (type(value).__name__, tuple(_gate_argument_key(item) for item in value))
    raise TypeError("Unmemoized gate argument")


def gate_context_reader(function):
    """Reuse an immutable reader result only within the guarded full-gate call."""
    @functools.wraps(function)
    def read(*args, **kwargs):
        cache = _GATE_CONTEXT_CACHE.get()
        if cache is None or kwargs.get("dependency_registry_override") is not None:
            return function(*args, **kwargs)
        try:
            key = (function.__name__, _gate_argument_key(args), _gate_argument_key(kwargs))
        except (TypeError, ValueError):
            return function(*args, **kwargs)
        if key not in cache:
            cache[key] = function(*args, **kwargs)
        # Callers may add local diagnostics or narrow projections. Neither can
        # change the shared result seen by another consumer in this gate.
        return copy.deepcopy(cache[key])
    return read


@contextmanager
def gate_context_snapshot(root: Path):
    """Discard reuse before checking every captured input again from its bytes."""
    # A separately requested full gate never inherits an older digest snapshot.
    outer_digest = _FILE_DIGEST_SNAPSHOT.set(None)
    try:
        baseline = audit_state_manifest(root)
        token = _GATE_CONTEXT_CACHE.set({})
        observed: dict[tuple[str, Path], str] = {}
        try:
            with gate_digest_snapshot():
                try:
                    yield
                finally:
                    observed = dict(_FILE_DIGEST_SNAPSHOT.get() or {})
        finally:
            _GATE_CONTEXT_CACHE.reset(token)
            if audit_state_manifest(root) != baseline:
                raise ValueError("Audit inputs changed during finalization checking; rerun the check on a stable audit")
            # This also covers hashed sources and tool code outside the audit.
            # The per-gate digest cache has already ended, so these are new reads.
            for (kind, path), expected in observed.items():
                actual = sha256_file(path) if kind == "bytes" else sha256_portable_text_file(path)
                if actual != expected:
                    raise ValueError(f"Input changed during finalization checking: {path}; rerun the check")
    finally:
        _FILE_DIGEST_SNAPSHOT.reset(outer_digest)


def sha256_file(path: Path) -> str:
    snapshot = _FILE_DIGEST_SNAPSHOT.get()
    key = ("bytes", path.resolve())
    if snapshot is not None and key in snapshot:
        return snapshot[key]
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(chunk)
    value = digest.hexdigest()
    if snapshot is not None:
        snapshot[key] = value
    return value


def sha256_portable_text_file(path: Path) -> str:
    """Hash text bytes after normalizing platform newline conventions."""
    snapshot = _FILE_DIGEST_SNAPSHOT.get()
    key = ("portable_text", path.resolve())
    if snapshot is not None and key in snapshot:
        return snapshot[key]
    payload = path.read_bytes().replace(b"\r\n", b"\n").replace(b"\r", b"\n")
    value = hashlib.sha256(payload).hexdigest()
    if snapshot is not None:
        snapshot[key] = value
    return value


def canonical_sha256(value: Any) -> str:
    payload = json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    return sha256_text(payload)


SHA256_RE = re.compile(r"[0-9a-f]{64}$")


def canonical_primary_ledger_sha256(ledger: dict[str, Any]) -> str:
    """Hash primary audit evidence without self-referential challenger metadata."""
    return canonical_sha256(
        {
            key: value
            for key, value in ledger.items()
            if key != "independent_check"
        }
    )


def is_utc_timestamp(value: Any) -> bool:
    if not is_nonempty_string(value):
        return False
    try:
        parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError:
        return False
    return parsed.tzinfo is not None and parsed.utcoffset() == timezone.utc.utcoffset(parsed)


def audit_state_manifest(root: Path, excluded: Path | None = None) -> list[dict[str, str]]:
    # Sort by the canonical posix path string, never by Path objects: Path
    # ordering is case-insensitive on Windows and case-sensitive elsewhere,
    # so object ordering would give the same audit a different state hash on
    # each platform.
    rows: list[dict[str, str]] = []
    for path in sorted(
        (item for item in root.rglob("*") if item.is_file()),
        key=lambda item: item.relative_to(root).as_posix(),
    ):
        if excluded is not None and path.resolve() == excluded.resolve():
            continue
        relative = path.relative_to(root)
        if (
            len(relative.parts) == 4
            and relative.parts[:3] == ("audit", "06_reports", "history")
            and re.fullmatch(
                r"\.I-[0-9]{3}-origin\.json\.proofcheck\.(?:tmp|lock)",
                relative.name,
            )
        ):
            continue
        rows.append(
            {
                "file": relative.as_posix(),
                "sha256": sha256_file(path),
            }
        )
    return rows


def audit_state_sha256(root: Path, excluded: Path | None = None) -> str:
    return canonical_sha256(audit_state_manifest(root, excluded))


def _unique_sibling_temp_path(path: Path) -> Path:
    path.parent.mkdir(parents=True, exist_ok=True)
    descriptor, raw_path = tempfile.mkstemp(
        prefix=f".{path.name}.", suffix=".proofcheck.tmp", dir=str(path.parent)
    )
    os.close(descriptor)
    return Path(raw_path)


def atomic_write_text(path: Path, text: str) -> None:
    path = Path(path)
    temporary = _unique_sibling_temp_path(path)
    try:
        if temporary.is_symlink():
            raise ValueError(f"Refusing a symlinked proofcheck temp file: {temporary}")
        with temporary.open("w", encoding="utf-8", newline="\n") as stream:
            stream.write(text)
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temporary, path)
    finally:
        if temporary.exists():
            temporary.unlink()


def atomic_write_json(path: Path, value: Any) -> None:
    atomic_write_text(path, json.dumps(value, ensure_ascii=False, indent=2) + "\n")


def publish_no_overwrite(
    temporary: Path, destination: Path, description: str
) -> str:
    """Publish validated bytes without replacing an existing destination."""
    try:
        os.link(temporary, destination)
        return "hard_link"
    except FileExistsError as exc:
        raise FileExistsError(
            f"{description} appeared during creation and cannot be overwritten: "
            f"{destination}"
        ) from exc
    except OSError:
        pass

    if os.name == "nt":
        try:
            os.rename(temporary, destination)
            return "exclusive_rename"
        except FileExistsError as exc:
            raise FileExistsError(
                f"{description} appeared during creation and cannot be overwritten: "
                f"{destination}"
            ) from exc
        except OSError:
            pass

    created = False
    try:
        with destination.open("xb") as target:
            created = True
            with temporary.open("rb") as source:
                shutil.copyfileobj(source, target)
            target.flush()
            os.fsync(target.fileno())
        if sha256_file(destination) != sha256_file(temporary):
            raise OSError("exclusive-copy verification hash mismatch")
        return "exclusive_copy"
    except FileExistsError as exc:
        raise FileExistsError(
            f"{description} appeared during creation and cannot be overwritten: "
            f"{destination}"
        ) from exc
    except OSError as exc:
        cleanup_error: OSError | None = None
        if created and destination.exists():
            try:
                destination.unlink()
            except OSError as unlink_exc:
                cleanup_error = unlink_exc
        detail = f"; partial-output cleanup also failed: {cleanup_error}" if cleanup_error else ""
        raise OSError(
            f"Cannot publish {description} with verified no-overwrite semantics: "
            f"{destination}: {exc}{detail}"
        ) from exc


def atomic_create_json(path: Path, value: Any, description: str) -> None:
    """Create one JSON file without replacing an existing path."""
    path = Path(path)
    if path.exists():
        raise FileExistsError(f"{description} already exists: {path}")
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = _unique_sibling_temp_path(path)
    try:
        if temporary.is_symlink():
            raise ValueError(f"Refusing a symlinked {description} candidate: {temporary}")
        payload = json.dumps(value, ensure_ascii=False, indent=2) + "\n"
        with temporary.open("w", encoding="utf-8", newline="\n") as stream:
            stream.write(payload)
            stream.flush()
            os.fsync(stream.fileno())
        publish_no_overwrite(temporary, path, description)
    finally:
        if temporary.exists():
            temporary.unlink()


def migration_update_lock_path(root: Path) -> Path:
    return root.resolve() / ".proofcheck-migration.lock"


def migration_update_lock_error(root: Path) -> str | None:
    lock = migration_update_lock_path(root)
    redirect_kind = path_redirect_kind(lock)
    if redirect_kind is not None:
        return f"audit migration lock is redirected ({redirect_kind}): {lock}"
    if lock.exists():
        return (
            "audit migration is in progress or a stale lock remains: "
            f"{lock}. If no migration command is running, inspect the lock and "
            "audit state, then remove the lock manually and rerun"
        )
    return None


def acquire_migration_update_lock(
    root: Path, command: str
) -> tuple[Path, bytes]:
    lock = migration_update_lock_path(root)
    redirect_kind = path_redirect_kind(lock)
    if redirect_kind is not None:
        raise ValueError(
            f"Refusing a redirected audit migration lock ({redirect_kind}): {lock}"
        )
    record = {
        "transaction_schema_version": 1,
        "command": command,
        "process_id": os.getpid(),
        "created_utc": datetime.now(timezone.utc).isoformat(
            timespec="microseconds"
        ),
        "recovery": (
            "If no migration command is running, inspect this lock and the "
            "audit state, remove the lock manually, and rerun."
        ),
    }
    payload = (json.dumps(record, sort_keys=True) + "\n").encode("utf-8")
    try:
        descriptor = os.open(
            lock,
            os.O_CREAT
            | os.O_EXCL
            | os.O_WRONLY
            | getattr(os, "O_BINARY", 0),
        )
    except FileExistsError as exc:
        raise ValueError(migration_update_lock_error(root)) from exc
    try:
        offset = 0
        while offset < len(payload):
            written = os.write(descriptor, payload[offset:])
            if written <= 0:
                raise OSError(f"Cannot write audit migration lock: {lock}")
            offset += written
        os.fsync(descriptor)
    finally:
        os.close(descriptor)
    return lock, payload


def release_migration_update_lock(lock: Path, payload: bytes) -> None:
    if (
        path_redirect_kind(lock) is not None
        or not lock.is_file()
        or lock.read_bytes() != payload
    ):
        raise OSError(
            "Audit migration lock changed during the transaction; inspect and "
            f"remove it manually only after recovery: {lock}"
        )
    lock.unlink()


class MigrationRecoveryRequired(OSError):
    """A migration left recovery files or could not restore every live file."""


def audit_migration_locked(command: Any) -> Any:
    @functools.wraps(command)
    def locked(args: argparse.Namespace) -> int:
        root = args.root.resolve()
        lock, payload = acquire_migration_update_lock(root, command.__name__)
        release_lock = True
        try:
            return command(args)
        except MigrationRecoveryRequired:
            release_lock = False
            raise
        finally:
            if release_lock:
                release_migration_update_lock(lock, payload)

    return locked


def transactional_write_texts(
    writes: list[tuple[Path, str | bytes]],
    *,
    expected_sha256: dict[Path, str] | None = None,
    deletes: list[Path] | None = None,
    expected_absent: list[Path] | None = None,
) -> None:
    """Publish a group of files, restoring prior bytes on commit failure."""
    entries: list[dict[str, Any]] = []
    identities: set[str] = set()
    expected_records: dict[str, tuple[Path, str]] = {}
    absent_records = {os.path.normcase(os.path.abspath(p)): Path(p)
                      for p in (expected_absent or [])}
    for raw_path, digest in (expected_sha256 or {}).items():
        path = Path(raw_path)
        identity = os.path.normcase(os.path.abspath(path))
        if not isinstance(digest, str) or not SHA256_RE.fullmatch(digest):
            raise ValueError(
                f"Transactional expected digest is invalid for {path}"
            )
        if identity in expected_records:
            raise ValueError(f"Duplicate transactional baseline path: {path}")
        expected_records[identity] = (path, digest)
    if set(absent_records) & set(expected_records):
        raise ValueError("Transactional path cannot be both present and absent")
    write_identities = {os.path.normcase(os.path.abspath(p)) for p, _ in writes}
    if not set(absent_records) <= write_identities:
        raise ValueError("Expected-absent paths must be new write destinations")

    def validate_expected_baselines(selected: set[str] | None = None) -> None:
        for identity, path in absent_records.items():
            if selected is None or identity in selected:
                if path.exists() or path.is_symlink():
                    raise FileExistsError(f"Transactional new destination already exists: {path}")
        for identity, (path, digest) in expected_records.items():
            if selected is not None and identity not in selected:
                continue
            if path.is_symlink() or not path.is_file():
                raise ValueError(
                    f"Transactional baseline is missing or redirected: {path}"
                )
            if sha256_file(path) != digest:
                raise ValueError(
                    f"Transactional baseline changed before commit: {path}"
                )

    preserve_recovery_files = False
    commit_succeeded = False
    try:
        validate_expected_baselines()
        for raw_path, text in [*writes, *((p, None) for p in (deletes or []))]:
            path = Path(raw_path)
            identity = os.path.normcase(os.path.abspath(path))
            if identity in identities:
                raise ValueError(
                    f"Transactional text destinations must be distinct: {path}"
                )
            identities.add(identity)
            if text is None and identity not in expected_records:
                raise ValueError(f"Transactional deletion requires an expected digest: {path}")
            if path.is_symlink():
                raise ValueError(
                    f"Refusing a symlinked transactional destination: {path}"
                )
            if path.exists() and not path.is_file():
                raise ValueError(
                    f"Transactional text destination is not a file: {path}"
                )

            staged = _unique_sibling_temp_path(path) if text is not None else None
            entry: dict[str, Any] = {
                "path": path,
                "staged": staged,
                "backup": None,
                "existed": path.exists(),
                "identity": identity,
                "delete": text is None,
            }
            entries.append(entry)
            if staged is None:
                continue
            mode = "wb" if isinstance(text, bytes) else "w"
            options = {} if isinstance(text, bytes) else {"encoding": "utf-8", "newline": "\n"}
            with staged.open(mode, **options) as stream:
                stream.write(text)
                stream.flush()
                os.fsync(stream.fileno())

        validate_expected_baselines()
        for entry in entries:
            if not entry["existed"]:
                continue
            path = entry["path"]
            backup = _unique_sibling_temp_path(path)
            entry["backup"] = backup
            with path.open("rb") as source, backup.open("wb") as destination:
                shutil.copyfileobj(source, destination, length=1024 * 1024)
                destination.flush()
                os.fsync(destination.fileno())

        validate_expected_baselines()
        guard_identities = set(expected_records) - identities
        committed: list[dict[str, Any]] = []
        try:
            for entry in entries:
                validate_expected_baselines(
                    guard_identities | {entry["identity"]}
                )
                if entry["identity"] in absent_records:
                    publish_no_overwrite(entry["staged"], entry["path"], "Transactional new file")
                    committed.append(entry)
                else:
                    committed.append(entry)
                    if entry["delete"]:
                        entry["path"].unlink()
                    else:
                        os.replace(entry["staged"], entry["path"])
            validate_expected_baselines(guard_identities)
            commit_succeeded = True
        except BaseException as exc:
            rollback_errors: list[str] = []
            for entry in reversed(committed):
                path = entry["path"]
                try:
                    if entry["existed"]:
                        backup = entry["backup"]
                        if not isinstance(backup, Path):
                            raise OSError(
                                f"Missing transactional backup for {path}"
                            )
                        os.replace(backup, path)
                        entry["backup"] = None
                    elif path.exists():
                        path.unlink()
                except OSError as rollback_exc:
                    rollback_errors.append(f"{path}: {rollback_exc}")
            if rollback_errors:
                preserve_recovery_files = True
                recovery_files = sorted(
                    str(temporary)
                    for entry in entries
                    for key in ("staged", "backup")
                    if isinstance((temporary := entry.get(key)), Path)
                    and temporary.exists()
                )
                raise MigrationRecoveryRequired(
                    "Transactional text write failed and rollback was incomplete: "
                    + "; ".join(rollback_errors)
                    + ". Recovery files were preserved: "
                    + ", ".join(recovery_files)
                ) from exc
            raise
    finally:
        if not preserve_recovery_files:
            cleanup_errors: list[str] = []
            for entry in entries:
                for key in ("staged", "backup"):
                    temporary = entry.get(key)
                    if isinstance(temporary, Path) and temporary.exists():
                        try:
                            temporary.unlink()
                        except OSError as cleanup_exc:
                            cleanup_errors.append(f"{temporary}: {cleanup_exc}")
            if cleanup_errors:
                message = (
                    "Transactional temporary cleanup was incomplete: "
                    + "; ".join(cleanup_errors)
                )
                if commit_succeeded:
                    recovery_files = sorted(
                        str(temporary)
                        for entry in entries
                        for key in ("staged", "backup")
                        if isinstance((temporary := entry.get(key)), Path)
                        and temporary.exists()
                    )
                    raise MigrationRecoveryRequired(
                        message
                        + ". Live writes were committed; recovery files were "
                        "preserved: "
                        + ", ".join(recovery_files)
                    )
                raise OSError(message)


def atomic_copy_file(source: Path, destination: Path) -> None:
    temporary = _unique_sibling_temp_path(destination)
    try:
        with source.open("rb") as input_stream, temporary.open("wb") as output_stream:
            shutil.copyfileobj(input_stream, output_stream, length=1024 * 1024)
            output_stream.flush()
            os.fsync(output_stream.fileno())
        os.replace(temporary, destination)
    finally:
        if temporary.exists():
            temporary.unlink()


class TextArtifactReadError(UnicodeError):
    """A text artifact could not be decoded or read exactly."""


@gate_context_reader
def read_text(path: Path) -> str:
    try:
        if _GATE_CONTEXT_CACHE.get() is not None:
            payload = path.read_bytes()
            observed = hashlib.sha256(payload).hexdigest()
            snapshot = _FILE_DIGEST_SNAPSHOT.get()
            key = ("bytes", path.resolve())
            if snapshot is not None:
                if snapshot.setdefault(key, observed) != observed:
                    raise ValueError(f"Input changed during finalization checking: {path}")
            # Match read_text(encoding='utf-8-sig') and universal newline handling.
            return payload.decode("utf-8-sig").replace("\r\n", "\n").replace("\r", "\n")
        return path.read_text(encoding="utf-8-sig")
    except (OSError, UnicodeError) as exc:
        raise TextArtifactReadError(
            f"Unreadable UTF-8 text artifact {path}: {exc}"
        ) from exc


def read_lines(path: Path) -> list[str]:
    return read_text(path).splitlines()


def is_unescaped_tex_percent(text: str, index: int) -> bool:
    if index < 0 or index >= len(text) or text[index] != "%":
        return False
    backslashes = 0
    cursor = index - 1
    while cursor >= 0 and text[cursor] == "\\":
        backslashes += 1
        cursor -= 1
    return backslashes % 2 == 0


def strip_latex_comment(line: str) -> str:
    index = line.find("%")
    while index != -1:
        if is_unescaped_tex_percent(line, index):
            return line[:index]
        index = line.find("%", index + 1)
    return line


def mask_tex_range(characters: list[str], start: int, end: int) -> None:
    for index in range(max(0, start), min(len(characters), end)):
        if characters[index] != "\n":
            characters[index] = " "


def skip_tex_whitespace(text: str, start: int) -> int:
    cursor = start
    while cursor < len(text):
        if text[cursor].isspace():
            cursor += 1
            continue
        if is_unescaped_tex_percent(text, cursor):
            newline = text.find("\n", cursor)
            cursor = len(text) if newline < 0 else newline + 1
            continue
        break
    return cursor


def consume_tex_control_sequence(text: str, start: int) -> int | None:
    if start >= len(text) or text[start] != "\\":
        return None
    cursor = start + 1
    if cursor >= len(text):
        return None
    if text[cursor].isalnum() or text[cursor] in "@_:":
        while cursor < len(text) and (
            text[cursor].isalnum() or text[cursor] in "@_:"
        ):
            cursor += 1
        return cursor
    return cursor + 1


_TEX_GROUP_TRIGGER_RES = {
    ("{", "}"): re.compile(r"[%\\{}]"),
    ("[", "]"): re.compile(r"[%\\\[\]]"),
}


def consume_balanced_tex_group(
    text: str, start: int, opening: str, closing: str
) -> int | None:
    if start >= len(text) or text[start] != opening:
        return None
    trigger_re = _TEX_GROUP_TRIGGER_RES.get((opening, closing))
    if trigger_re is None:
        trigger_re = re.compile(
            f"[%\\\\{re.escape(opening)}{re.escape(closing)}]"
        )
    depth = 0
    cursor = start
    while cursor < len(text):
        char = text[cursor]
        if is_unescaped_tex_percent(text, cursor):
            newline = text.find("\n", cursor)
            cursor = len(text) if newline < 0 else newline + 1
            continue
        inline_verb = inline_verbatim_end(text, cursor)
        if inline_verb is not None:
            cursor = inline_verb[0]
            continue
        if (
            char == "\\"
            and cursor + 1 < len(text)
            and text[cursor + 1] in {opening, closing}
        ):
            cursor += 2
            continue
        if char == opening:
            depth += 1
        elif char == closing:
            depth -= 1
            if depth == 0:
                return cursor + 1
        # State can only change at "%", a backslash, or a delimiter, so
        # jump straight to the next such character.
        trigger = trigger_re.search(text, cursor + 1)
        cursor = trigger.start() if trigger is not None else len(text)
    return None


def inline_verbatim_end(text: str, start: int) -> tuple[int, bool] | None:
    """Return a common inline-verbatim span and whether it is terminated."""
    match = TEX_INLINE_VERB_COMMAND_RE.match(text, start)
    if match is None:
        return None
    command = match.group("command")
    line_end = text.find("\n", match.end())
    if line_end < 0:
        line_end = len(text)
    cursor = match.end()
    if command in {"Verb", "lstinline", "mintinline"}:
        cursor = skip_tex_whitespace(text, cursor)
        if cursor < line_end and text[cursor] == "[":
            options_end = consume_balanced_tex_group(text, cursor, "[", "]")
            if options_end is None or options_end > line_end:
                return line_end, False
            cursor = skip_tex_whitespace(text, options_end)
    if command == "mintinline":
        if cursor >= line_end or text[cursor] != "{":
            return line_end, False
        language_end = consume_balanced_tex_group(text, cursor, "{", "}")
        if language_end is None or language_end > line_end:
            return line_end, False
        cursor = skip_tex_whitespace(text, language_end)
    if cursor >= line_end:
        return line_end, False
    if command == "mintinline" and text[cursor] == "{":
        code_end = consume_balanced_tex_group(text, cursor, "{", "}")
        if code_end is None or code_end > line_end:
            return line_end, False
        return code_end, True
    delimiter = text[cursor]
    if delimiter.isspace() or delimiter.isalpha():
        return line_end, False
    closing = text.find(delimiter, cursor + 1, line_end)
    return (
        (closing + 1, True)
        if closing >= 0
        else (line_end, False)
    )


def consume_tex_definition_target(text: str, start: int) -> int | None:
    cursor = skip_tex_whitespace(text, start)
    if cursor < len(text) and text[cursor] == "{":
        return consume_balanced_tex_group(text, cursor, "{", "}")
    return consume_tex_control_sequence(text, cursor)


def consume_tex_optional_arguments(text: str, start: int) -> int | None:
    cursor = skip_tex_whitespace(text, start)
    while cursor < len(text) and text[cursor] == "[":
        group_end = consume_balanced_tex_group(text, cursor, "[", "]")
        if group_end is None:
            return None
        cursor = skip_tex_whitespace(text, group_end)
    return cursor


def consume_tex_required_groups(
    text: str, start: int, count: int
) -> int | None:
    cursor = skip_tex_whitespace(text, start)
    for _ in range(count):
        group_end = consume_balanced_tex_group(text, cursor, "{", "}")
        if group_end is None:
            return None
        cursor = skip_tex_whitespace(text, group_end)
    return cursor


def consume_tex_parameterized_definition_body(
    text: str, start: int
) -> int | None:
    """Find and consume a TeX definition body after its target."""
    cursor = start
    while cursor < len(text):
        if is_unescaped_tex_percent(text, cursor):
            newline = text.find("\n", cursor)
            cursor = len(text) if newline < 0 else newline + 1
            continue
        inline_verb = inline_verbatim_end(text, cursor)
        if inline_verb is not None:
            cursor = inline_verb[0]
            continue
        if (
            text[cursor] == "#"
            and cursor + 1 < len(text)
            and (text[cursor + 1].isdigit() or text[cursor + 1] == "#")
        ):
            cursor += 2
            continue
        if text[cursor] == "{":
            return consume_balanced_tex_group(text, cursor, "{", "}")
        cursor += 1
    return None


def tex_definition_end(text: str, match: re.Match[str]) -> int | None:
    command = match.group("command")
    cursor = match.end()
    if command in TEX_SIMPLE_CONDITIONAL_DEFINITIONS:
        cursor = skip_tex_whitespace(text, cursor)
        return consume_tex_control_sequence(text, cursor)
    if command in TEX_ALIAS_DEFINITIONS:
        cursor = skip_tex_whitespace(text, cursor)
        target_end = consume_tex_control_sequence(text, cursor)
        if target_end is None:
            return None
        cursor = skip_tex_whitespace(text, target_end)
        if cursor < len(text) and text[cursor] == "=":
            cursor = skip_tex_whitespace(text, cursor + 1)
        source_end = consume_tex_control_sequence(text, cursor)
        return source_end if source_end is not None else min(len(text), cursor + 1)
    if command in TEX_PRIMITIVE_DEFINITIONS or command.startswith("cs_"):
        cursor = skip_tex_whitespace(text, cursor)
        c_type = (
            command.startswith("cs_")
            and ":" in command
            and command.split(":", 1)[1].startswith("c")
        )
        target_end = (
            consume_balanced_tex_group(text, cursor, "{", "}")
            if c_type
            else consume_tex_control_sequence(text, cursor)
        )
        if target_end is None:
            return None
        return consume_tex_parameterized_definition_body(text, target_end)

    if command in TEX_NAMED_GROUP_DEFINITIONS:
        cursor = skip_tex_whitespace(text, cursor)
        target_end = consume_balanced_tex_group(text, cursor, "{", "}")
        if target_end is None:
            return None
        return consume_tex_parameterized_definition_body(text, target_end)

    if command in TEX_OPTION_FIRST_THEOREM_DEFINITIONS:
        cursor = consume_tex_optional_arguments(text, cursor)
        if cursor is None:
            return None
        return consume_balanced_tex_group(text, cursor, "{", "}")

    target_end = consume_tex_definition_target(text, cursor)
    if target_end is None:
        return None
    cursor = target_end
    if command in TEX_NEW_COMMAND_DEFINITIONS:
        cursor = consume_tex_optional_arguments(text, cursor)
        if cursor is None:
            return None
        return consume_balanced_tex_group(text, cursor, "{", "}")
    if command in TEX_NEW_ENVIRONMENT_DEFINITIONS:
        cursor = consume_tex_optional_arguments(text, cursor)
        if cursor is None:
            return None
        begin_end = consume_balanced_tex_group(text, cursor, "{", "}")
        if begin_end is None:
            return None
        cursor = skip_tex_whitespace(text, begin_end)
        return consume_balanced_tex_group(text, cursor, "{", "}")
    if command in TEX_DOCUMENT_COMMAND_DEFINITIONS:
        cursor = skip_tex_whitespace(text, cursor)
        argument_spec_end = consume_balanced_tex_group(text, cursor, "{", "}")
        if argument_spec_end is None:
            return None
        cursor = skip_tex_whitespace(text, argument_spec_end)
        return consume_balanced_tex_group(text, cursor, "{", "}")
    if command in TEX_DOCUMENT_ENVIRONMENT_DEFINITIONS:
        cursor = skip_tex_whitespace(text, cursor)
        argument_spec_end = consume_balanced_tex_group(text, cursor, "{", "}")
        if argument_spec_end is None:
            return None
        return consume_tex_required_groups(text, argument_spec_end, 2)
    paired_group_count = TEX_PAIRED_DELIMITER_DEFINITIONS.get(command)
    if paired_group_count is not None:
        cursor = consume_tex_optional_arguments(text, cursor)
        if cursor is None:
            return None
        return consume_tex_required_groups(text, cursor, paired_group_count)
    if command in TEX_THEOREM_DEFINITIONS:
        cursor = consume_tex_optional_arguments(text, cursor)
        if cursor is None:
            return None
        title_end = consume_balanced_tex_group(text, cursor, "{", "}")
        if title_end is None:
            return None
        return consume_tex_optional_arguments(text, title_end)
    return None


_TEX_MASK_CACHE: dict[
    tuple[str, str, bool, str], tuple[str, tuple[str, ...]]
] = {}
_TEX_MASK_CACHE_LIMIT = 512


def _cached_tex_mask(
    kind: str,
    text: str,
    preserve_theorem_declarations: bool,
    source_name: str,
    warnings: list[str] | None,
    compute,
) -> str:
    """Memoize a deterministic text mask, replaying its recorded warnings.

    The mask functions are pure given (text, flags, source_name): the masked
    output and the warning texts are fully determined by the inputs, so a
    bounded cache changes no observable behavior. Warnings are replayed with
    the same not-already-present check an uncached run performs.
    """
    key = (kind, text, preserve_theorem_declarations, source_name)
    cached = _TEX_MASK_CACHE.get(key)
    if cached is None:
        collected: list[str] = []
        masked = compute(collected)
        if len(_TEX_MASK_CACHE) >= _TEX_MASK_CACHE_LIMIT:
            _TEX_MASK_CACHE.clear()
        cached = (masked, tuple(collected))
        _TEX_MASK_CACHE[key] = cached
    masked, collected_warnings = cached
    if warnings is not None:
        for warning in collected_warnings:
            if warning not in warnings:
                warnings.append(warning)
    return masked


_TEXT_MEMO: dict[tuple[str, str], Any] = {}
_TEXT_MEMO_LIMIT = 512


def _memoize_text(kind: str, text: str, compute):
    """Memoize a pure function of one text; mutable results are deep-copied.

    Keys are the text itself, so equal content anywhere yields the same
    result and there is no file state to invalidate.
    """
    key = (kind, text)
    if key in _TEXT_MEMO:
        value = _TEXT_MEMO[key]
    else:
        value = compute()
        if len(_TEXT_MEMO) >= _TEXT_MEMO_LIMIT:
            _TEXT_MEMO.clear()
        _TEXT_MEMO[key] = value
    return value if isinstance(value, str) else copy.deepcopy(value)


def mask_nonexecuting_tex(
    text: str,
    *,
    preserve_theorem_declarations: bool = False,
    warnings: list[str] | None = None,
    source_name: str = "<source>",
) -> str:
    """Mask comments, definitions, and verbatim material in one lexical pass."""
    return _cached_tex_mask(
        "nonexecuting",
        text,
        preserve_theorem_declarations,
        source_name,
        warnings,
        lambda collected: _mask_nonexecuting_tex_impl(
            text,
            preserve_theorem_declarations=preserve_theorem_declarations,
            warnings=collected,
            source_name=source_name,
        ),
    )


def _mask_nonexecuting_tex_impl(
    text: str,
    *,
    preserve_theorem_declarations: bool = False,
    warnings: list[str] | None = None,
    source_name: str = "<source>",
) -> str:
    characters = list(text)
    cursor = 0
    while cursor < len(text):
        if is_unescaped_tex_percent(text, cursor):
            newline = text.find("\n", cursor)
            end = len(text) if newline < 0 else newline
            mask_tex_range(characters, cursor, end)
            cursor = end
            continue
        definition = TEX_DEFINITION_COMMAND_RE.match(text, cursor)
        if definition is not None:
            end = tex_definition_end(text, definition)
            if end is None:
                newline = text.find("\n", definition.end())
                end = len(text) if newline < 0 else newline
                if warnings is not None:
                    line, column = source_line_column(text, definition.start())
                    warning = (
                        "Malformed TeX definition requires manual review: "
                        f"{source_name}:{line}:{column}"
                    )
                    if warning not in warnings:
                        warnings.append(warning)
            if (
                preserve_theorem_declarations
                and definition.group("command")
                in TEX_THEOREM_DEFINITIONS
                | TEX_OPTION_FIRST_THEOREM_DEFINITIONS
            ):
                cursor = max(end, definition.end())
                continue
            mask_tex_range(characters, definition.start(), end)
            cursor = max(end, definition.end())
            continue
        inline_verb = inline_verbatim_end(text, cursor)
        if inline_verb is not None:
            end, terminated = inline_verb
            if not terminated and warnings is not None:
                line, column = source_line_column(text, cursor)
                warning = (
                    "Unterminated inline verbatim requires manual review: "
                    f"{source_name}:{line}:{column}"
                )
                if warning not in warnings:
                    warnings.append(warning)
            mask_tex_range(characters, cursor, end)
            cursor = max(end, cursor + 1)
            continue
        verbatim = TEX_VERBATIM_BEGIN_RE.match(text, cursor)
        if verbatim is not None:
            environment = verbatim.group("environment")
            end_re = re.compile(rf"\\end\s*\{{{re.escape(environment)}\}}")
            end_match = end_re.search(text, verbatim.end())
            end = end_match.end() if end_match is not None else len(text)
            if end_match is None and warnings is not None:
                line, column = source_line_column(text, verbatim.start())
                warning = (
                    "Unterminated verbatim-like environment requires manual review: "
                    f"{source_name}:{line}:{column}"
                )
                if warning not in warnings:
                    warnings.append(warning)
            mask_tex_range(characters, verbatim.start(), end)
            cursor = max(end, verbatim.end())
            continue
        # Every handler above can only fire at an unescaped "%" or a
        # backslash-led construct, so jumping to the next such character
        # skips ordinary text without changing which spans get masked.
        trigger = TEX_MASK_TRIGGER_RE.search(text, cursor + 1)
        cursor = trigger.start() if trigger is not None else len(text)
    return "".join(characters)


def named_argument_conditional(command: str) -> bool:
    """Return whether the control-sequence family uses bounded arguments."""
    return (
        command in ARGUMENT_CONDITIONAL_COMMANDS
        or command.startswith("If")
        or command.startswith("@if")
        or "_if" in command
        or ":" in command
    )


def argument_conditional_end(
    text: str, command: str, token_end: int
) -> int | None:
    """Return the end of a syntactically bounded argument conditional."""
    cursor = skip_tex_whitespace(text, token_end)
    while cursor < len(text):
        control_argument_end = consume_tex_control_sequence(text, cursor)
        if control_argument_end is None:
            break
        cursor = skip_tex_whitespace(text, control_argument_end)
    if command == "@ifnextchar" and cursor < len(text):
        if text[cursor] == "{":
            token_argument_end = consume_balanced_tex_group(
                text, cursor, "{", "}"
            )
            if token_argument_end is not None:
                cursor = skip_tex_whitespace(text, token_argument_end)
        else:
            cursor = skip_tex_whitespace(text, cursor + 1)
    group_count = 0
    while cursor < len(text) and text[cursor] == "{":
        group_end = consume_balanced_tex_group(text, cursor, "{", "}")
        if group_end is None:
            break
        group_count += 1
        cursor = skip_tex_whitespace(text, group_end)
    minimum_groups = 1 if named_argument_conditional(command) else 2
    return cursor if group_count >= minimum_groups else None


def conditional_uses_fi_syntax(
    command: str, text: str, token_end: int
) -> bool:
    r"""Distinguish primitive/custom \if...\fi controls from argument macros."""
    if command in TEX_FI_CONDITIONAL_COMMANDS:
        return True
    if named_argument_conditional(command):
        return False
    return argument_conditional_end(text, command, token_end) is None


def matched_tex_conditional_open_offsets(text: str) -> set[int]:
    """Return conditional-token offsets that have a structural \fi partner."""
    stack: list[int] = []
    matched: set[int] = set()
    for token in TEX_CONDITIONAL_RE.finditer(text):
        conditional = token.group("conditional")
        if (
            conditional is not None
            and conditional_uses_fi_syntax(conditional, text, token.end())
        ):
            stack.append(token.start())
        elif token.group("end") is not None and stack:
            matched.add(stack.pop())
    return matched


def unmatched_argument_conditional_ranges(
    text: str, matched_offsets: set[int]
) -> list[tuple[int, int]]:
    """Bound brace-argument conditionals that do not use TeX's \fi syntax."""
    ranges: list[tuple[int, int]] = []
    for token in TEX_CONDITIONAL_RE.finditer(text):
        conditional = token.group("conditional")
        if conditional is None or token.start() in matched_offsets:
            continue
        range_end = argument_conditional_end(
            text, conditional, token.end()
        )
        if range_end is not None:
            ranges.append((token.start(), range_end))
    return ranges


def mask_inactive_tex_branches(
    text: str,
    *,
    warnings: list[str] | None = None,
    source_name: str = "<source>",
) -> str:
    """Mask only branches statically known to be inactive, preserving offsets."""
    characters = list(text)
    conditional_stack: list[bool | None] = []
    matched_offsets = matched_tex_conditional_open_offsets(text)
    unless_pending = False
    cursor = 0

    def possibly_active() -> bool:
        return all(state is not False for state in conditional_stack)

    for token in TEX_CONDITIONAL_RE.finditer(text):
        active_before = possibly_active()
        if not active_before:
            mask_tex_range(characters, cursor, token.end())

        conditional = token.group("conditional")
        if conditional is not None:
            if conditional == "iftrue":
                state: bool | None = True
            elif conditional == "iffalse":
                state = False
            else:
                state = None
                if active_before and warnings is not None:
                    line, column = source_line_column(text, token.start())
                    warning = (
                        "Unknown TeX conditional preserves candidate structure "
                        "and requires manual review: "
                        f"{source_name}:{line}:{column}: \\{conditional}"
                    )
                    if warning not in warnings:
                        warnings.append(warning)
            if unless_pending and state is not None:
                state = not state
            if state is not None or token.start() in matched_offsets:
                conditional_stack.append(state)
            unless_pending = False
        elif token.group("unless") is not None:
            unless_pending = active_before
        elif token.group("branch") is not None:
            unless_pending = False
            if conditional_stack:
                state = conditional_stack[-1]
                conditional_stack[-1] = None if state is None else not state
        elif token.group("end") is not None:
            unless_pending = False
            if conditional_stack:
                conditional_stack.pop()
        cursor = token.end()

    if not possibly_active():
        mask_tex_range(characters, cursor, len(text))
    return "".join(characters)


def mask_structural_tex(
    text: str,
    *,
    preserve_theorem_declarations: bool = False,
    warnings: list[str] | None = None,
    source_name: str = "<source>",
) -> str:
    """Mask nonexecuting structural TeX without changing source positions."""

    def compute(collected: list[str]) -> str:
        nonexecuting = mask_nonexecuting_tex(
            text,
            preserve_theorem_declarations=preserve_theorem_declarations,
            warnings=collected,
            source_name=source_name,
        )
        structural = mask_inactive_tex_branches(
            nonexecuting,
            warnings=collected,
            source_name=source_name,
        )
        if not preserve_theorem_declarations:
            warn_tex_source_selection(structural, source_name, collected)
        return structural

    return _cached_tex_mask(
        "structural",
        text,
        preserve_theorem_declarations,
        source_name,
        warnings,
        compute,
    )


def warn_tex_source_selection(
    structural: str, source_name: str, warnings: list[str]
) -> None:
    """Flag literal build controls without choosing the reviewed audit scope."""
    cursor = 0
    while (cursor := structural.find("\\", cursor)) >= 0:
        end = consume_tex_control_sequence(structural, cursor)
        if end is None:
            break
        command = structural[cursor + 1:end]
        start = skip_tex_whitespace(structural, end)
        group_end = (consume_balanced_tex_group(structural, start, "{", "}")
                     if command in {"end", "includeonly"} else None)
        value = structural[start + 1:group_end - 1].strip() if group_end else None
        warning = None
        if command == "includeonly":
            line, column = source_line_column(structural, cursor)
            selection = "{" + value + "}" if value is not None else " (nonliteral selection)"
            warning = (
                f"TeX source selection requires manual review: {source_name}:{line}:{column}: "
                f"\\includeonly{selection}. Candidate source discovery retains all includes; "
                "confirm whether the audit covers the selected build or the full manuscript, "
                "and record any excluded results with their source-selection evidence before proof review."
            )
        elif command == "end" and value == "document":
            if structural[group_end:].strip():
                line, column = source_line_column(structural, cursor)
                warning = (
                    f"TeX source selection requires manual review: {source_name}:{line}:{column}: "
                    "content follows \\end{document} and may be inactive in the manuscript build. "
                    "The parser retains this candidate content; inspect the following source, "
                    "record explicit scope exclusions for abandoned material, or supply the intended manuscript source."
                )
            if warning is not None and warning not in warnings:
                warnings.append(warning)
            break
        if warning is not None and warning not in warnings:
            warnings.append(warning)
        cursor = end


def mask_tex_literals_for_definition_scan(text: str) -> str:
    """Mask comments and verbatim material without masking definitions."""
    return _memoize_text(
        "definition_scan_literals",
        text,
        lambda: _mask_tex_literals_for_definition_scan_uncached(text),
    )


def _mask_tex_literals_for_definition_scan_uncached(text: str) -> str:
    masked = mask_latex_comments(text)
    characters = list(masked)
    cursor = 0
    while cursor < len(masked):
        inline_verb = inline_verbatim_end(masked, cursor)
        if inline_verb is not None:
            end, _ = inline_verb
            mask_tex_range(characters, cursor, end)
            cursor = max(end, cursor + 1)
            continue
        verbatim = TEX_VERBATIM_BEGIN_RE.match(masked, cursor)
        if verbatim is not None:
            environment = verbatim.group("environment")
            end_match = re.compile(
                rf"\\end\s*\{{{re.escape(environment)}\}}"
            ).search(masked, verbatim.end())
            end = end_match.end() if end_match is not None else len(masked)
            mask_tex_range(characters, cursor, end)
            cursor = max(end, cursor + 1)
            continue
        # Both handlers above fire only at backslash-led commands.
        backslash = masked.find("\\", cursor + 1)
        cursor = backslash if backslash >= 0 else len(masked)
    return "".join(characters)


def tex_definition_body_spans(
    text: str, definition: re.Match[str]
) -> list[tuple[int, int]]:
    """Return executable body groups for a supported TeX definition."""
    command = definition.group("command")
    if (
        command in TEX_PRIMITIVE_DEFINITIONS
        or command in TEX_NAMED_GROUP_DEFINITIONS
        or command in TEX_NEW_COMMAND_DEFINITIONS
        or command in TEX_DOCUMENT_COMMAND_DEFINITIONS
        or command.startswith("cs_")
    ):
        body_count = 1
    elif (
        command in TEX_NEW_ENVIRONMENT_DEFINITIONS
        or command in TEX_DOCUMENT_ENVIRONMENT_DEFINITIONS
    ):
        body_count = 2
    elif command in TEX_PAIRED_DELIMITER_DEFINITIONS:
        body_count = TEX_PAIRED_DELIMITER_DEFINITIONS[command]
    else:
        return []
    definition_end = tex_definition_end(text, definition)
    if definition_end is None:
        return []
    groups: list[tuple[int, int]] = []
    cursor = definition.end()
    while cursor < definition_end:
        if text[cursor] != "{":
            cursor += 1
            continue
        group_end = consume_balanced_tex_group(text, cursor, "{", "}")
        if group_end is None or group_end > definition_end:
            break
        groups.append((cursor + 1, group_end - 1))
        cursor = group_end
    return groups[-body_count:] if len(groups) >= body_count else []


def warn_definition_body_inclusions(
    text: str,
    *,
    source_name: str,
    warnings: list[str],
) -> None:
    _cached_tex_mask(
        "definition_body_inclusions",
        text,
        False,
        source_name,
        warnings,
        lambda collected: (
            _warn_definition_body_inclusions_uncached(
                text, source_name=source_name, warnings=collected
            )
            or ""
        ),
    )


def _warn_definition_body_inclusions_uncached(
    text: str,
    *,
    source_name: str,
    warnings: list[str],
) -> None:
    """Flag possibly active source inclusions hidden inside definitions."""
    scanned_text = mask_tex_literals_for_definition_scan(text)
    definitions: list[tuple[re.Match[str], int]] = []
    cursor = 0
    while cursor < len(scanned_text):
        definition = TEX_DEFINITION_COMMAND_RE.search(scanned_text, cursor)
        if definition is None:
            break
        definition_end = tex_definition_end(scanned_text, definition)
        if definition_end is None:
            cursor = definition.end()
            continue
        definitions.append((definition, definition_end))
        cursor = max(definition_end, definition.end())

    conditional_characters = list(scanned_text)
    for definition, definition_end in definitions:
        mask_tex_range(
            conditional_characters, definition.start(), definition_end
        )
        conditional_characters[definition.start()] = "D"
    active_markers = mask_inactive_tex_branches(
        "".join(conditional_characters),
        source_name=source_name,
    )

    for definition, definition_end in definitions:
        if active_markers[definition.start()] != "D":
            continue
        for body_start, body_end in tex_definition_body_spans(
            scanned_text, definition
        ):
            for inclusion in DEFINITION_BODY_INCLUSION_RE.finditer(
                scanned_text, body_start, body_end
            ):
                line, column = source_line_column(text, inclusion.start())
                warning = (
                    "TeX macro/environment definition body contains a source "
                    "inclusion command and requires manual review: "
                    f"{source_name}:{line}:{column}: "
                    f"\\{inclusion.group('command')}"
                )
                if warning not in warnings:
                    warnings.append(warning)


def relative_or_absolute(path: Path, base: Path) -> str:
    try:
        return Path(os.path.relpath(path.resolve(), base.resolve())).as_posix()
    except ValueError:
        return path.resolve().as_posix()


def source_path_identity(path: Path, base: Path | None = None) -> str:
    """Serialize a source path with an optional relocatable identity base."""
    if base is None:
        return str(path.resolve())
    return relative_or_absolute(path, base)


def resolve_stored_path(value: str, base: Path) -> Path:
    if not is_nonempty_string(value):
        raise ValueError("Stored path must be a nonempty string")
    windows_drive = bool(re.match(r"^[A-Za-z]:[\\/]", value))
    windows_drive_relative = bool(re.match(r"^[A-Za-z]:(?![\\/])", value))
    windows_unc = value.startswith("\\\\") or value.startswith("//")
    posix_absolute = value.startswith("/") and not windows_unc
    if windows_drive_relative:
        raise ValueError(f"Drive-relative stored path is unsupported: {value}")
    if (windows_drive or windows_unc) and os.name != "nt":
        raise ValueError(f"Foreign Windows absolute path cannot be resolved here: {value}")
    if posix_absolute and os.name == "nt":
        raise ValueError(f"Foreign POSIX absolute path cannot be resolved here: {value}")
    if windows_drive or windows_unc or posix_absolute:
        return Path(value).resolve()
    candidate = Path(
        *[part for part in re.split(r"[\\/]", value) if part not in {"", "."}]
    )
    return (base / candidate).resolve()


CANONICAL_MANIFEST_ARTIFACT_PATHS = {
    "inventory_file": "audit/01_index/theorem_inventory.json",
    "dependency_registry": "audit/03_dependencies/DEPENDENCY_REGISTRY.json",
    "method_interface_registry": (
        "audit/03_dependencies/METHOD_INTERFACE_REGISTRY.json"
    ),
    "finalization_record": "audit/06_reports/FINALIZATION.json",
}


def path_redirect_kind(path: Path) -> str | None:
    """Identify filesystem redirections without assuming one operating system."""
    try:
        if path.is_symlink():
            return "symlink"
        is_junction = getattr(path, "is_junction", None)
        if callable(is_junction) and is_junction():
            return "junction"
        lexical = os.path.normcase(os.path.abspath(path))
        resolved = os.path.normcase(os.path.realpath(path))
        if lexical != resolved:
            return "filesystem redirection"
    except OSError:
        return "uninspectable filesystem redirection"
    return None


def canonical_artifact_path(
    root: Path,
    relative: str,
    label: str,
    errors: list[str],
) -> tuple[Path, bool]:
    """Return one fixed audit path after rejecting redirected components."""
    resolved_root = root.resolve()
    parts = tuple(part for part in relative.split("/") if part)
    candidate = resolved_root.joinpath(*parts)
    valid = True
    current = resolved_root
    for part in parts:
        current = current / part
        redirect_kind = path_redirect_kind(current)
        if redirect_kind is not None:
            message = (
                f"Canonical {label} location traverses a {redirect_kind}: {current}"
            )
            if message not in errors:
                errors.append(message)
            valid = False
    try:
        candidate.resolve(strict=False).relative_to(resolved_root)
    except (OSError, ValueError):
        message = f"Canonical {label} location resolves outside the audit root"
        if message not in errors:
            errors.append(message)
        valid = False
    return candidate, valid


PORTABLE_ARTIFACT_SEGMENT_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9._-]*$")
WINDOWS_RESERVED_ARTIFACT_STEMS = {
    "CON",
    "PRN",
    "AUX",
    "NUL",
    *(f"COM{index}" for index in range(1, 10)),
    *(f"LPT{index}" for index in range(1, 10)),
}


def portable_artifact_segment(value: str) -> bool:
    if (
        PORTABLE_ARTIFACT_SEGMENT_RE.fullmatch(value) is None
        or value.endswith(".")
    ):
        return False
    return value.split(".", 1)[0].upper() not in WINDOWS_RESERVED_ARTIFACT_STEMS


def challenge_artifact_reference_parts(value: Any) -> tuple[str, ...] | None:
    """Return a portable canonical challenge path, or None when invalid."""
    if not is_nonempty_string(value) or "\\" in value:
        return None
    parts = tuple(str(value).split("/"))
    if (
        len(parts) < 3
        or parts[:2] != ("audit", "05_adversarial")
        or any(
            not part
            or part in {".", ".."}
            or not portable_artifact_segment(part)
            for part in parts[2:]
        )
    ):
        return None
    return parts


def canonical_challenge_artifact_path(
    root: Path,
    value: Any,
    label: str,
    errors: list[str],
) -> tuple[Path | None, bool]:
    """Resolve one portable challenge artifact inside canonical audit state."""
    parts = challenge_artifact_reference_parts(value)
    if parts is None:
        errors.append(
            f"{label} must be a portable audit-relative path under "
            "audit/05_adversarial"
        )
        return None, False
    relative = "/".join(parts)
    path, valid = canonical_artifact_path(
        root, relative, "challenge artifact", errors
    )
    return path, valid


def manifest_canonical_artifact_path(
    manifest: dict[str, Any],
    root: Path,
    field: str,
    label: str,
    errors: list[str],
) -> tuple[Path, bool]:
    """Validate a manifest pointer and return only its fixed canonical target."""
    relative = CANONICAL_MANIFEST_ARTIFACT_PATHS[field]
    canonical, valid = canonical_artifact_path(root, relative, label, errors)
    value = manifest.get(field)
    if not is_nonempty_string(value):
        errors.append(f"manifest.{field} must be a nonempty path")
        return canonical, False
    normalized = value.replace("\\", "/")
    if normalized != relative:
        errors.append(
            f"manifest.{field} must resolve to {relative} through the canonical "
            "root-relative path"
        )
        return canonical, False
    try:
        resolved = resolve_stored_path(value, root)
    except ValueError as exc:
        errors.append(f"manifest.{field} is invalid: {exc}")
        return canonical, False
    if resolved != canonical:
        errors.append(f"manifest.{field} must resolve to {relative}")
        return canonical, False
    return canonical, valid


def load_audit_manifest(
    root: Path,
) -> tuple[Path, dict[str, Any], list[str]]:
    """Load the fixed audit manifest without following redirected components."""
    errors: list[str] = []
    path, valid = canonical_artifact_path(
        root, "AUDIT_MANIFEST.json", "audit manifest", errors
    )
    if not valid:
        return path, {}, errors
    manifest, read_errors = load_json_object(path, "audit manifest")
    errors.extend(read_errors)
    if not read_errors and "context_protocol" in manifest:
        try:
            context_protocol_identity(root, manifest)
        except (OSError, ValueError, UnicodeError) as exc:
            errors.append(str(exc))
    return path, manifest, errors


def audit_internal_redirect_errors(root: Path) -> list[str]:
    """Reject redirected files or directories inside canonical audit state."""
    errors: list[str] = []
    resolved_root = root.resolve()
    pending = [resolved_root]
    while pending:
        directory = pending.pop()
        try:
            children = list(directory.iterdir())
        except OSError as exc:
            errors.append(f"Cannot inspect audit directory safely: {directory}: {exc}")
            continue
        for child in children:
            redirect_kind = path_redirect_kind(child)
            if redirect_kind is not None:
                errors.append(
                    f"Audit state contains a redirected {redirect_kind}: {child}"
                )
                continue
            try:
                relative = child.relative_to(resolved_root)
            except ValueError:
                relative = None
            confined_archive_transaction = (
                relative is not None
                and len(relative.parts) == 4
                and relative.parts[:3] == ("audit", "06_reports", "history")
                and re.fullmatch(
                    r"\.I-[0-9]{3}-origin\.json\.proofcheck\.(?:tmp|lock)",
                    relative.name,
                )
                is not None
            )
            if (
                child.name.endswith(".proofcheck.tmp")
                and not confined_archive_transaction
            ):
                errors.append(
                    "Audit state contains interrupted transaction residue; remove "
                    f"or recover it before continuing: {child}"
                )
                continue
            try:
                is_directory = child.is_dir()
            except OSError as exc:
                errors.append(f"Cannot inspect audit artifact safely: {child}: {exc}")
                continue
            if is_directory:
                pending.append(child)
    return errors


def is_int(value: Any) -> bool:
    return isinstance(value, int) and not isinstance(value, bool)


def is_nonempty_string(value: Any) -> bool:
    return isinstance(value, str) and bool(value.strip())


def is_enum_value(value: Any, allowed: Iterable[str]) -> bool:
    return isinstance(value, str) and value in allowed


@functools.lru_cache(maxsize=4096)
def is_ignorable_marker_character(value: str) -> bool:
    codepoint = ord(value)
    return (
        unicodedata.category(value) == "Cf"
        or codepoint == 0x034F
        or 0x115F <= codepoint <= 0x1160
        or 0x17B4 <= codepoint <= 0x17B5
        or 0x180B <= codepoint <= 0x180F
        or codepoint in {0x2800, 0x3164, 0xFFA0}
        or 0xFE00 <= codepoint <= 0xFE0F
        or 0xE0100 <= codepoint <= 0xE01EF
    )


def normalized_marker(value: Any) -> str | None:
    if not isinstance(value, str):
        return None
    text = unicodedata.normalize("NFKC", value)
    if not text.isascii():
        # No ASCII character is ignorable (format-class and the listed
        # codepoints all sit above U+007F), so pure-ASCII text skips the
        # per-character filter unchanged.
        text = "".join(
            char for char in text if not is_ignorable_marker_character(char)
        )
    text = text.strip().lower()
    previous: str | None = None
    while text != previous:
        previous = text
        wrapper = re.fullmatch(r"\\[a-z@]+\*?\s*\{(.*)\}", text, re.DOTALL)
        if wrapper is not None:
            text = wrapper.group(1).strip()
            continue
        while text and text[0] not in "\\{}" and (
            text[0].isspace() or unicodedata.category(text[0])[0] in {"P", "S"}
        ):
            text = text[1:]
        while text and text[-1] not in "\\{}" and (
            text[-1].isspace() or unicodedata.category(text[-1])[0] in {"P", "S"}
        ):
            text = text[:-1]
    return text


def is_explicit_absence(value: Any) -> bool:
    markers = {
        "none",
        "n/a",
        "not applicable",
        "not-applicable",
        "not_applicable",
    }
    if isinstance(value, str):
        return normalized_marker(value) in markers
    if isinstance(value, list) and value:
        return all(
            normalized_marker(item) in markers
            for item in value
        )
    return False


def is_unresolved_placeholder(value: Any) -> bool:
    unresolved_markers = {
        "unclear",
        "unknown",
        "unresolved",
        "tbd",
        "todo",
        "pending",
        "not checked",
        "not_checked",
    }
    marker = normalized_marker(value)
    return marker in unresolved_markers or bool(
        marker and re.match(r"^(?:todo|tbd)\b", marker)
    )


def is_forbidden_contract_placeholder(value: Any) -> bool:
    marker = normalized_marker(value)
    exact_unclear = (
        isinstance(value, str) and value.strip().lower() == "unclear"
    )
    prefix_match = (
        re.match(
            r"^(?:unclear|unknown|unresolved|pending|not[\s_-]*checked)",
            marker,
        )
        if marker
        else None
    )
    remainder = marker[prefix_match.end():].lstrip() if prefix_match else ""
    separator = remainder[:1]
    separator_name = unicodedata.name(separator, "") if separator else ""
    unresolved_prefix = bool(
        separator
        and (
            separator == ":"
            or "COLON" in separator_name
            or separator_name == "RATIO"
        )
    )
    return not exact_unclear and (
        is_unresolved_placeholder(value) or unresolved_prefix
    )


def is_substantive_string(value: Any) -> bool:
    return (
        is_nonempty_string(value)
        and not is_explicit_absence(value)
        and not is_unresolved_placeholder(value)
    )


def validate_string_list(
    value: Any,
    field: str,
    errors: list[str],
    *,
    substantive: bool = False,
    allow_empty: bool = False,
) -> list[str]:
    if not isinstance(value, list):
        errors.append(f"{field} must be a list")
        return []
    if not all(is_nonempty_string(item) for item in value):
        errors.append(f"{field} must contain only nonempty strings")
        return []
    if substantive and not all(is_substantive_string(item) for item in value):
        errors.append(
            f"{field} must contain substantive strings, not reserved placeholders"
        )
        return []
    if not allow_empty and not value:
        errors.append(f"{field} must not be empty")
    return value


def resolve_json_pointer(document: Any, pointer: Any) -> tuple[bool, Any]:
    if not isinstance(pointer, str) or not pointer.startswith("/"):
        return False, None
    current = document
    for raw_token in pointer[1:].split("/"):
        token = raw_token.replace("~1", "/").replace("~0", "~")
        if isinstance(current, dict):
            if token not in current:
                return False, None
            current = current[token]
        elif isinstance(current, list):
            if not token.isdigit():
                return False, None
            index = int(token)
            if index < 0 or index >= len(current):
                return False, None
            current = current[index]
        else:
            return False, None
    return True, current


def validate_aspect_matrix(
    value: Any,
    field: str,
    required_aspects: Iterable[str],
    allowed_statuses: set[str],
    final: bool,
    errors: list[str],
) -> dict[str, str]:
    required = tuple(required_aspects)
    required_set = set(required)
    if not isinstance(value, list):
        errors.append(f"{field} must be a list")
        return {}

    statuses: dict[str, str] = {}
    duplicates: set[str] = set()
    unexpected: set[str] = set()
    for index, record in enumerate(value, 1):
        prefix = f"{field}[{index}]"
        if not isinstance(record, dict):
            errors.append(f"{prefix} must be an object")
            continue
        aspect = record.get("aspect")
        status = record.get("status")
        if not is_nonempty_string(aspect):
            errors.append(f"{prefix}.aspect must be a nonempty string")
            continue
        if aspect not in required_set:
            unexpected.add(aspect)
            errors.append(f"{prefix}.aspect is invalid: {aspect!r}")
        elif aspect in statuses:
            duplicates.add(aspect)
        else:
            statuses[aspect] = status
        if not is_enum_value(status, allowed_statuses):
            errors.append(f"{prefix}.status is invalid: {status!r}")
        if not is_substantive_string(record.get("evidence")):
            errors.append(
                f"{prefix}.evidence must be a nonempty string and substantive, "
                "not a reserved placeholder"
            )

    missing = required_set - set(statuses)
    if final and (missing or duplicates or unexpected):
        details: list[str] = []
        if missing:
            details.append("missing " + ", ".join(sorted(missing)))
        if duplicates:
            details.append("duplicate " + ", ".join(sorted(duplicates)))
        if unexpected:
            details.append("unexpected " + ", ".join(sorted(unexpected)))
        errors.append(
            f"{field} must contain each required aspect exactly once"
            + (": " + "; ".join(details) if details else "")
        )
    return statuses


def normalized_evidence_template(value: Any) -> str:
    if not isinstance(value, str):
        return ""
    return re.sub(
        r"\s+",
        " ",
        unicodedata.normalize("NFKC", value).strip().casefold(),
    )


def validate_evidence_specificity(
    records: list[dict[str, str]], errors: list[str]
) -> None:
    """Reject only strong exact-template reuse signals, with bounded output."""
    diagnostics: list[str] = []
    grouped: dict[tuple[str, str], list[dict[str, str]]] = defaultdict(list)
    for record in records:
        template = normalized_evidence_template(record.get("text"))
        if template:
            grouped[(record.get("category", "evidence"), template)].append(record)

    for (category, template), rows in sorted(grouped.items()):
        step_ids = sorted({row.get("step_id", "") for row in rows if row.get("step_id")})
        claims = {
            normalized_evidence_template(row.get("claim"))
            for row in rows
            if normalized_evidence_template(row.get("claim"))
        }
        if category != "risk" and len(step_ids) >= 4 and len(claims) >= 3:
            diagnostics.append(
                f"Repeated {category} evidence template across {len(step_ids)} "
                f"unrelated steps; first affected step {step_ids[0]}: "
                f"{truncate(template, 120)}"
            )
        if category == "risk":
            by_step: dict[str, set[str]] = defaultdict(set)
            for row in rows:
                if row.get("step_id") and row.get("aspect"):
                    by_step[row["step_id"]].add(row["aspect"])
            broad_step = next(
                (
                    (step_id, aspects)
                    for step_id, aspects in sorted(by_step.items())
                    if len(aspects) >= 3
                ),
                None,
            )
            if broad_step is not None:
                diagnostics.append(
                    f"Repeated risk evidence template across {len(broad_step[1])} "
                    f"distinct aspects in {broad_step[0]}: {truncate(template, 120)}"
                )
            applicable_steps = sorted(
                {
                    row.get("step_id", "")
                    for row in rows
                    if row.get("step_id") and row.get("status") != "not_applicable"
                }
            )
            if len(applicable_steps) >= 4 and len(claims) >= 3:
                diagnostics.append(
                    f"Repeated applicable risk evidence template across "
                    f"{len(applicable_steps)} unrelated steps; first affected step "
                    f"{applicable_steps[0]}: {truncate(template, 120)}"
                )
    if diagnostics:
        errors.extend(diagnostics[:10])
        if len(diagnostics) > 10:
            errors.append(
                f"Evidence-specificity diagnostics omitted {len(diagnostics) - 10} "
                "additional repeated templates"
            )


MATH_SEGMENT_RE = re.compile(
    r"\$[^$]+\$|\\\((?:.(?!\\\)))*.?\\\)|\\\[(?:.(?!\\\]))*.?\\\]"
)
SUBSCRIPTED_MATH_TOKEN_RE = re.compile(r"[A-Za-z](?:_\{[^{}]{1,40}\}|_[A-Za-z0-9])")
PLAIN_MATH_IDENTIFIER_RE = re.compile(r"(?<![\\A-Za-z])[A-Za-z][A-Za-z0-9]*")


def extract_step_math_tokens(text: str, *, whole_math: bool) -> set[str]:
    """Collect the mathematical object names visible in one locked source unit.

    Tokens are subscripted identifiers such as ``X_{n,j}`` or ``m_n`` and plain
    identifiers inside math segments. TeX control-sequence names are excluded.
    ``whole_math`` also covers an interior fragment whose enclosing display is
    known from the locked source. A unit with no math yields no token.
    """
    if whole_math:
        segments = [text]
    else:
        segments = [match.group(0) for match in MATH_SEGMENT_RE.finditer(text)]
    tokens: set[str] = set()
    for segment in segments:
        segment = TOKEN_RE.sub(lambda match: " " * len(match.group(0)), segment)
        masked = re.sub(
            r"\\[A-Za-z]+", lambda match: " " * len(match.group(0)), segment
        )
        for match in SUBSCRIPTED_MATH_TOKEN_RE.finditer(masked):
            tokens.add(match.group(0))
        for match in PLAIN_MATH_IDENTIFIER_RE.finditer(masked):
            tokens.add(match.group(0))
    return tokens


def collect_step_evidence_texts(step: dict[str, Any]) -> list[str]:
    """Gather the authored evidence prose of one step, excluding the literal
    transcription and the restatement, for evidence anchoring."""
    texts: list[str] = []
    checks = step.get("checks")
    if isinstance(checks, dict):
        atomicity = checks.get("atomicity")
        if isinstance(atomicity, dict) and isinstance(
            atomicity.get("evidence"), str
        ):
            texts.append(atomicity["evidence"])
        adversarial = checks.get("adversarial")
        if isinstance(adversarial, list):
            texts.extend(item for item in adversarial if isinstance(item, str))
    inference = step.get("inference")
    moves = inference.get("moves") if isinstance(inference, dict) else None
    if isinstance(moves, list):
        for move in moves:
            if not isinstance(move, dict):
                continue
            if isinstance(move.get("justification"), str):
                texts.append(move["justification"])
            failure = move.get("failure")
            if isinstance(failure, dict) and isinstance(
                failure.get("evidence"), str
            ):
                texts.append(failure["evidence"])
    risk_checks = step.get("risk_checks")
    if isinstance(risk_checks, list):
        texts.extend(
            record["evidence"]
            for record in risk_checks
            if isinstance(record, dict) and isinstance(record.get("evidence"), str)
        )
    return texts


def evidence_names_source_object(tokens: set[str], texts: list[str]) -> bool:
    combined = "\n".join(texts)
    for token in tokens:
        if "_" in token:
            if token in combined:
                return True
            stripped = token.replace("{", "").replace("}", "")
            if stripped != token and stripped in combined:
                return True
            base = token[0]
            if re.search(rf"(?<![A-Za-z]){re.escape(base)}(?![A-Za-z])", combined):
                return True
        elif re.search(
            rf"(?<![A-Za-z]){re.escape(token)}(?![A-Za-z])", combined
        ):
            return True
    return False


def validate_evidence_anchoring(
    records: list[dict[str, Any]], errors: list[str]
) -> None:
    """Require each inferential step's authored evidence to name at least one
    mathematical object from its own locked source unit."""
    diagnostics: list[str] = []
    for record in records:
        tokens = record.get("tokens")
        if not isinstance(tokens, set) or not tokens:
            continue
        texts = record.get("texts")
        texts = texts if isinstance(texts, list) else []
        if not evidence_names_source_object(tokens, texts):
            sample = ", ".join(sorted(tokens)[:6])
            diagnostics.append(
                f"{record.get('step_id')}: step evidence never names a "
                "mathematical object from its locked source unit; anchor the "
                f"justification, adversarial, or risk evidence to it (e.g. {sample})"
            )
    if diagnostics:
        errors.extend(diagnostics[:10])
        if len(diagnostics) > 10:
            errors.append(
                f"Evidence-anchoring diagnostics omitted {len(diagnostics) - 10} "
                "additional unanchored steps"
            )


def failure_computation_shape_errors(computation: Any, field: str) -> list[str]:
    """Validate the structural shape of one failure.computation record.

    The record either instantiates a refuting computation (script, command,
    and output excerpt, with the script hash locked) or records a substantive
    reason why the failure cannot be instantiated numerically. Shape checks
    never establish that the computation itself is mathematically meaningful.
    """
    errors: list[str] = []
    if not isinstance(computation, dict):
        return [f"{field} must be an object"]
    status = computation.get("status")
    if status not in FAILURE_COMPUTATION_STATUSES:
        errors.append(
            f"{field}.status must be 'instantiated' or 'not_instantiable'"
        )
        return errors
    if status == "instantiated":
        allowed = FAILURE_COMPUTATION_INSTANTIATED_FIELDS
        script_file = computation.get("script_file")
        if not is_nonempty_string(script_file):
            errors.append(f"{field}.script_file must be a nonempty relative path")
        elif Path(str(script_file)).is_absolute() or "\\" in str(script_file):
            errors.append(
                f"{field}.script_file must be a relative path using '/' separators"
            )
        script_sha256 = computation.get("script_sha256")
        if not isinstance(script_sha256, str) or not SHA256_RE.fullmatch(
            script_sha256
        ):
            errors.append(f"{field}.script_sha256 must be a SHA-256 digest")
        for name in ("command", "output_excerpt"):
            if not is_substantive_string(computation.get(name)):
                errors.append(f"{field}.{name} must be nonempty and substantive")
    else:
        allowed = FAILURE_COMPUTATION_NOT_INSTANTIABLE_FIELDS
        if not is_substantive_string(computation.get("reason")):
            errors.append(f"{field}.reason must be nonempty and substantive")
    unknown = set(computation) - allowed
    if unknown:
        errors.append(
            f"{field} has unknown fields: {', '.join(sorted(unknown))}"
        )
    return errors


def validate_failure_computation_artifacts(
    steps: Any, ledger_path: Path, errors: list[str]
) -> None:
    """Check that every instantiated failure computation resolves to a real,
    hash-locked script inside the audit's adversarial directory."""
    audit_root = containing_audit_root(ledger_path)
    adversarial_root = (
        (audit_root / "audit" / "05_adversarial").resolve()
        if audit_root is not None
        else None
    )
    steps = steps if isinstance(steps, list) else []
    for step in steps:
        if not isinstance(step, dict):
            continue
        step_id = str(step.get("id", "?"))
        inference = step.get("inference")
        moves = inference.get("moves") if isinstance(inference, dict) else None
        if not isinstance(moves, list):
            continue
        for move in moves:
            if not isinstance(move, dict):
                continue
            failure = move.get("failure")
            if not isinstance(failure, dict):
                continue
            computation = failure.get("computation")
            if not isinstance(computation, dict):
                continue
            if computation.get("status") != "instantiated":
                continue
            field = f"{step_id}.failure.computation"
            script_file = computation.get("script_file")
            script_sha256 = computation.get("script_sha256")
            if not is_nonempty_string(script_file) or not isinstance(
                script_sha256, str
            ):
                continue
            if Path(str(script_file)).is_absolute():
                continue
            resolved = (ledger_path.parent / str(script_file)).resolve()
            if adversarial_root is not None and not resolved.is_relative_to(
                adversarial_root
            ):
                errors.append(
                    f"{field}.script_file must resolve inside "
                    "audit/05_adversarial"
                )
                continue
            if not resolved.is_file():
                errors.append(
                    f"{field}.script_file not found: {script_file}"
                )
                continue
            if sha256_file(resolved) != script_sha256:
                errors.append(
                    f"{field}.script_sha256 does not match the current script file"
                )


def near_duplicate_evidence_warnings(
    annotations: dict[str, Any], limit: int = 8
) -> list[str]:
    """Advisory near-duplicate detection for authored annotation evidence.

    Exact template reuse is rejected by the final evidence-specificity gate;
    this warning surfaces lightly paraphrased boilerplate early, before
    compilation. It never fails the check on its own.
    """
    records: list[tuple[str, str, str, str]] = []
    steps = annotations.get("steps")
    steps = steps if isinstance(steps, list) else []
    for step in steps:
        if not isinstance(step, dict):
            continue
        key = str(step.get("key", ""))
        candidates: list[tuple[str, Any]] = [
            ("atomicity_evidence", step.get("atomicity_evidence")),
            ("justification", step.get("justification")),
            ("not_applicable_basis", step.get("not_applicable_basis")),
        ]
        adversarial = step.get("adversarial")
        if isinstance(adversarial, list):
            candidates.extend(("adversarial", item) for item in adversarial)
        risks = step.get("risks")
        if isinstance(risks, dict):
            candidates.extend(
                (f"risks/{aspect}", record.get("evidence"))
                for aspect, record in risks.items()
                if isinstance(record, dict)
            )
        for field, value in candidates:
            template = normalized_evidence_template(value)
            if template:
                records.append((key, field, template, str(value)))
    warnings: list[str] = []
    seen_pairs: set[tuple[str, str]] = set()
    for left_index in range(len(records)):
        if len(warnings) >= limit:
            break
        left_key, left_field, left_template, _ = records[left_index]
        for right_index in range(left_index + 1, len(records)):
            right_key, right_field, right_template, _ = records[right_index]
            if left_key == right_key:
                continue
            if left_template == right_template:
                if (
                    left_field == "not_applicable_basis"
                    and right_field == "not_applicable_basis"
                ):
                    warnings.append(
                        "near_duplicate_evidence: identical not_applicable_basis "
                        f"is reused by {left_key} and {right_key}; make the basis "
                        "specific to each step"
                    )
                    if len(warnings) >= limit:
                        break
                continue
            pair = (left_template, right_template)
            if pair in seen_pairs:
                continue
            matcher = difflib.SequenceMatcher(
                None, left_template, right_template, autojunk=False
            )
            if (
                matcher.real_quick_ratio() >= 0.9
                and matcher.quick_ratio() >= 0.9
                and matcher.ratio() >= 0.9
            ):
                seen_pairs.add(pair)
                warnings.append(
                    "near_duplicate_evidence: "
                    f"{left_key}/{left_field} and {right_key}/{right_field} are "
                    ">=90% similar; replace shared boilerplate with step-specific "
                    f"evidence: {truncate(left_template, 100)}"
                )
                if len(warnings) >= limit:
                    break
    return warnings


def load_json_object(path: Path, description: str) -> tuple[dict[str, Any], list[str]]:
    try:
        data = json.loads(read_text(path))
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        return {}, [f"Cannot read {description} {path}: {exc}"]
    if not isinstance(data, dict):
        return {}, [f"{description} must be a JSON object: {path}"]
    return data, []


def locked_span(
    source: Path, start: int, end: int, base: Path, *, role: str | None = None
) -> dict[str, Any]:
    lines = read_lines(source)
    selected = lines[start - 1 : end]
    record: dict[str, Any] = {
        "file": relative_or_absolute(source, base),
        "start_line": start,
        "end_line": end,
        "sha256": sha256_text("\n".join(selected)),
    }
    if role is not None:
        record["role"] = role
    return record


def validate_locked_span(
    span: Any,
    base: Path,
    prefix: str,
    errors: list[str],
    *,
    require_role: bool = False,
) -> None:
    if not isinstance(span, dict):
        errors.append(f"{prefix} must be an object")
        return
    if require_role and not is_nonempty_string(span.get("role")):
        errors.append(f"{prefix}.role must be a nonempty string")
    file_value = span.get("file")
    start = span.get("start_line")
    end = span.get("end_line")
    digest = span.get("sha256")
    if not is_nonempty_string(file_value) or not is_int(start) or not is_int(end):
        errors.append(f"{prefix} needs file, integer start_line, and integer end_line")
        return
    if start < 1 or end < start or end - start + 1 > MAX_UNIT_LINES:
        errors.append(f"{prefix} has invalid range {start}-{end}")
        return
    source = resolve_stored_path(file_value, base)
    if not source.is_file():
        errors.append(f"{prefix} source file not found: {source}")
        return
    lines = read_lines(source)
    if end > len(lines):
        errors.append(f"{prefix} ends at {end}, but source has {len(lines)} lines")
        return
    current = sha256_text("\n".join(lines[start - 1 : end]))
    if not is_nonempty_string(digest) or digest != current:
        errors.append(f"{prefix} source drift: SHA-256 does not match")


def resolved_span_metadata(span: Any, base: Path) -> dict[str, Any] | None:
    if not isinstance(span, dict):
        return None
    if not is_nonempty_string(span.get("file")):
        return None
    if not is_int(span.get("start_line")) or not is_int(span.get("end_line")):
        return None
    return {
        "file": str(resolve_stored_path(span["file"], base)),
        "start_line": span["start_line"],
        "end_line": span["end_line"],
        "role": span.get("role"),
    }


def locked_span_contains_label(span: Any, base: Path, label: str) -> bool:
    metadata = resolved_span_metadata(span, base)
    if metadata is None:
        return False
    source = Path(metadata["file"])
    start = metadata["start_line"]
    end = metadata["end_line"]
    if not source.is_file() or start < 1 or end < start:
        return False
    lines = read_lines(source)
    if end > len(lines):
        return False
    labels: set[str] = set()
    conditional_stack: list[bool | None] = []
    unless_pending = False
    clean_text = mask_nonexecuting_tex("\n".join(lines))
    matched_offsets = matched_tex_conditional_open_offsets(clean_text)
    uncertain_ranges = unmatched_argument_conditional_ranges(
        clean_text, matched_offsets
    )
    for token in TEX_CONDITIONAL_LABEL_RE.finditer(clean_text):
        active_before = all(state is not False for state in conditional_stack)
        conditional = token.group("conditional")
        if conditional is not None:
            if conditional == "iftrue":
                state: bool | None = True
            elif conditional == "iffalse":
                state = False
            else:
                state = None
            if unless_pending and state is not None:
                state = not state
            if state is not None or token.start() in matched_offsets:
                conditional_stack.append(state)
            unless_pending = False
        elif token.group("unless") is not None:
            unless_pending = active_before
        elif token.group("branch") is not None:
            unless_pending = False
            if conditional_stack:
                state = conditional_stack[-1]
                conditional_stack[-1] = None if state is None else not state
        elif token.group("end") is not None:
            unless_pending = False
            if conditional_stack:
                conditional_stack.pop()
        elif token.group("label") is not None:
            line_number, _ = source_line_column(clean_text, token.start())
            argument_conditional = any(
                range_start <= token.start() < range_end
                for range_start, range_end in uncertain_ranges
            )
            if (
                start <= line_number <= end
                and not unless_pending
                and not argument_conditional
                and all(state is True for state in conditional_stack)
            ):
                labels.add(token.group("label"))
    return label in labels


def find_cycle(graph: dict[str, set[str]]) -> list[str] | None:
    state: dict[str, int] = {}
    stack: list[str] = []

    def visit(node: str) -> list[str] | None:
        state[node] = 1
        stack.append(node)
        for dependency in sorted(graph.get(node, set())):
            if dependency not in graph:
                continue
            if state.get(dependency, 0) == 0:
                cycle = visit(dependency)
                if cycle:
                    return cycle
            elif state.get(dependency) == 1:
                index = stack.index(dependency)
                return stack[index:] + [dependency]
        stack.pop()
        state[node] = 2
        return None

    for node in sorted(graph):
        if state.get(node, 0) == 0:
            cycle = visit(node)
            if cycle:
                return cycle
    return None


def split_reference_keys(raw: str) -> list[str]:
    return [item.strip() for item in raw.split(",") if item.strip()]


def mask_latex_comments(text: str) -> str:
    """Mask comments while preserving offsets and line endings."""
    return _memoize_text(
        "latex_comments", text, lambda: _mask_latex_comments_uncached(text)
    )


def _mask_latex_comments_uncached(text: str) -> str:
    characters = list(text)
    offset = 0
    for line in text.splitlines(keepends=True):
        clean = strip_latex_comment(line)
        if len(clean) < len(line):
            mask_tex_range(characters, offset + len(clean), offset + len(line))
        offset += len(line)
    return "".join(characters)


def source_line_column(text: str, offset: int, start_line: int = 1) -> tuple[int, int]:
    line = start_line + text.count("\n", 0, offset)
    last_newline = text.rfind("\n", 0, offset)
    column = offset + 1 if last_newline < 0 else offset - last_newline
    return line, column


SECTION_LEVELS = {
    "part": 0,
    "chapter": 1,
    "section": 2,
    "subsection": 3,
    "subsubsection": 4,
}


def scan_section_headings(text: str) -> list[dict[str, Any]]:
    """Parse static LaTeX section titles with balanced nested braces."""
    return _memoize_text(
        "section_headings", text, lambda: _scan_section_headings_uncached(text)
    )


def _scan_section_headings_uncached(text: str) -> list[dict[str, Any]]:
    masked = mask_structural_tex(text)
    headings: list[dict[str, Any]] = []
    for match in SECTION_COMMAND_START_RE.finditer(masked):
        opening = skip_tex_whitespace(masked, match.end())
        if opening < len(masked) and masked[opening] == "[":
            short_title_end = consume_balanced_tex_group(
                masked, opening, "[", "]"
            )
            if short_title_end is None:
                continue
            opening = skip_tex_whitespace(masked, short_title_end)
        if opening >= len(masked) or masked[opening] != "{":
            continue
        group_end = consume_balanced_tex_group(masked, opening, "{", "}")
        if group_end is None:
            continue
        start_line, start_column = source_line_column(text, match.start())
        end_line, end_column = source_line_column(text, group_end - 1)
        title = text[opening + 1 : group_end - 1]
        masked_title = masked[opening + 1 : group_end - 1]
        title_references, _ = scan_reference_occurrences(
            masked_title,
            Path("section-heading.tex"),
            Path("."),
            structural_context="section_heading",
        )
        static_targets = sorted(
            {
                str(reference.get("target"))
                for reference in title_references
                if reference.get("resolution_status") != "dynamic"
                and is_nonempty_string(reference.get("target"))
            }
        )
        command = match.group("command")
        headings.append(
            {
                "command": command,
                "level": SECTION_LEVELS[command],
                "title": title,
                "target_labels": static_targets,
                "start_line": start_line,
                "start_column": start_column,
                "end_line": end_line,
                "end_column": end_column,
            }
        )
    return headings


def scan_reference_occurrences(
    text: str,
    path: Path,
    base: Path,
    *,
    start_line: int = 1,
    structural_context: str = "source",
) -> tuple[list[dict[str, Any]], list[str]]:
    """Return exact static reference occurrences, including bracket hyperrefs."""
    relative_file = relative_or_absolute(path, base)
    warnings: list[str] = []
    masked = mask_structural_tex(
        text,
        warnings=warnings,
        source_name=relative_file,
    )
    matches = sorted(
        [*REFERENCE_COMMAND_RE.finditer(masked), *HYPERREF_COMMAND_RE.finditer(masked)],
        key=lambda match: match.start(),
    )
    occurrences: list[dict[str, Any]] = []
    handled_starts = {match.start() for match in matches}
    for match in matches:
        command = match.group("command")
        cursor = skip_tex_whitespace(masked, match.end())
        opening, closing = ("[", "]") if command == "hyperref" else ("{", "}")
        line, column = source_line_column(text, match.start(), start_line)
        group_count = 2 if command in RANGE_REFERENCE_COMMANDS else 1
        target_groups: list[list[str]] = []
        group_end: int | None = None
        for group_index in range(1, group_count + 1):
            group_end = consume_balanced_tex_group(
                masked, cursor, opening, closing
            )
            if group_end is None:
                warnings.append(
                    f"Malformed or dynamic \\{command} argument {group_index} "
                    "requires manual review: "
                    f"{relative_file}:{line}:{column}"
                )
                break
            raw_targets = text[cursor + 1 : group_end - 1]
            targets = split_reference_keys(raw_targets)
            target_groups.append(targets)
            if not targets:
                warnings.append(
                    f"Empty \\{command} argument {group_index} requires manual "
                    f"review: {relative_file}:{line}:{column}"
                )
            if command in RANGE_REFERENCE_COMMANDS and len(targets) != 1:
                warnings.append(
                    f"\\{command} argument {group_index} must resolve to exactly "
                    "one static target: "
                    f"{relative_file}:{line}:{column}"
                )
            cursor = skip_tex_whitespace(masked, group_end)
        targets = [
            target
            for target_group in target_groups
            for target in target_group
        ]
        if command == "hyperref":
            display_cursor = (
                skip_tex_whitespace(masked, group_end)
                if group_end is not None
                else cursor
            )
            if consume_balanced_tex_group(masked, display_cursor, "{", "}") is None:
                warnings.append(
                    "Malformed or dynamic \\hyperref display text requires manual "
                    f"review: {relative_file}:{line}:{column}"
                )
        for key_index, target in enumerate(targets, 1):
            dynamic = '\\' in target or '#' in target
            if dynamic:
                warnings.append(
                    f"Dynamic \\{command} target requires manual review: "
                    f"{relative_file}:{line}:{column}: {target}"
                )
            identity = {
                "file": relative_file,
                "line": line,
                "column": column,
                "command": command,
                "target": target,
                "key_index": key_index,
            }
            occurrences.append(
                {
                    "occurrence_id": "R-" + canonical_sha256(identity)[:16],
                    "command": command,
                    "target": target,
                    "file": relative_file,
                    "line": line,
                    "column": column,
                    "structural_context": structural_context,
                    "resolution_status": "dynamic" if dynamic else "unresolved",
                    "owner_unit_id": None,
                    "owner_region": None,
                }
            )
    for match in REF_LIKE_COMMAND_RE.finditer(masked):
        command = match.group("command")
        if (
            match.start() in handled_starts
            or command in REFERENCE_CONFIGURATION_COMMANDS
        ):
            continue
        line, column = source_line_column(text, match.start(), start_line)
        warning = (
            f"Unsupported reference-like command \\{command} requires manual "
            f"review: {relative_file}:{line}:{column}"
        )
        if warning not in warnings:
            warnings.append(warning)
    return occurrences, list(dict.fromkeys(warnings))


def scan_label_occurrences(
    text: str,
    path: Path,
    base: Path,
    *,
    start_line: int = 1,
) -> list[dict[str, Any]]:
    masked = mask_structural_tex(text)
    relative_file = relative_or_absolute(path, base)
    result: list[dict[str, Any]] = []
    for match in LABEL_RE.finditer(masked):
        line, column = source_line_column(text, match.start(), start_line)
        result.append(
            {
                "target": match.group(1).strip(),
                "file": relative_file,
                "line": line,
                "column": column,
            }
        )
    return result


def proof_optional_title_span(
    block: list[str], start_line: int = 1
) -> dict[str, Any] | None:
    text = "\n".join(block)
    masked = mask_structural_tex(text)
    # The caller supplies an already recognized complete proof environment.
    begin = re.search(r"\\begin\s*\{[^}]+\}", masked)
    if begin is None:
        return None
    cursor = skip_tex_whitespace(masked, begin.end())
    end = consume_balanced_tex_group(masked, cursor, "[", "]")
    if end is None:
        return None
    first_line, first_column = source_line_column(
        text, cursor + 1, start_line
    )
    last_offset = max(cursor + 1, end - 2)
    last_line, last_column = source_line_column(
        text, last_offset, start_line
    )
    return {
        "text": text[cursor + 1 : end - 1],
        "start_line": first_line,
        "start_column": first_column,
        "end_line": last_line,
        "end_column": last_column,
    }


def proof_optional_title(block: list[str]) -> str | None:
    span = proof_optional_title_span(block)
    return span.get("text") if isinstance(span, dict) else None


def occurrence_in_title(
    occurrence: dict[str, Any], title_span: dict[str, Any] | None
) -> bool:
    if not isinstance(title_span, dict):
        return False
    line = occurrence.get("line")
    column = occurrence.get("column")
    if not is_int(line) or not is_int(column):
        return False
    start = (title_span["start_line"], title_span["start_column"])
    end = (title_span["end_line"], title_span["end_column"])
    return start <= (line, column) <= end


def scan_span_evidence(
    path: Path,
    start_line: int,
    end_line: int,
    base: Path,
    *,
    structural_context: str = "proof_body",
    expand_inclusions: bool = True,
) -> dict[str, Any]:
    lines = read_lines(path)
    if not (1 <= start_line <= end_line <= len(lines)):
        raise ValueError(f"Invalid source span {path}:{start_line}-{end_line}")
    if expand_inclusions:
        try:
            expanded = source_fragment_support().expand(
                report_api(), path, start_line, end_line, base
            )
        except (OSError, ValueError) as exc:
            return {"reference_occurrences": [], "dependencies": [], "citations": [], "warnings": [str(exc)]}
        if expanded["has_inclusion"]:
            results = [scan_span_evidence(
                resolve_stored_path(fragment["file"], base), fragment["start_line"],
                fragment["end_line"], base, structural_context=structural_context,
                expand_inclusions=False,
            ) for fragment in expanded["fragments"]]
            for fragment, result in zip(expanded["fragments"], results):
                for occurrence in result["reference_occurrences"]:
                    occurrence["source_position"] = fragment["sequence_start"] + occurrence["line"] - fragment["start_line"]
            return {
                "reference_occurrences": [row for result in results for row in result["reference_occurrences"]],
                "dependencies": sorted({row for result in results for row in result["dependencies"]}),
                "citations": sorted({row for result in results for row in result["citations"]}),
                "warnings": sorted({row for result in results for row in result["warnings"]}),
            }
    selected = lines[start_line - 1 : end_line]
    text = "\n".join(selected)
    occurrences, warnings = scan_reference_occurrences(
        text,
        path,
        base,
        start_line=start_line,
        structural_context=structural_context,
    )
    citations: list[str] = []
    masked_lines = mask_structural_tex(text).split("\n")
    for line_number, clean in enumerate(masked_lines, start_line):
        handled_citations: set[int] = set()
        for match in CITE_RE.finditer(clean):
            handled_citations.add(match.start())
            citations.extend(split_reference_keys(match.group(1)))
        for match in CITATION_COMMAND_RE.finditer(clean):
            if match.start() not in handled_citations:
                warnings.append(
                    "Unsupported citation command requires manual review: "
                    f"{relative_or_absolute(path, base)}:{line_number}: "
                    f"{match.group(0)}"
                )
    return {
        "reference_occurrences": occurrences,
        "dependencies": sorted({row["target"] for row in occurrences}),
        "citations": sorted(set(citations)),
        "warnings": warnings,
    }


def scan_unit_statement_evidence(
    unit: dict[str, Any], base: Path
) -> dict[str, Any]:
    statement = unit.get("statement")
    if not isinstance(statement, dict):
        raise ValueError("Invalid reviewed statement range")
    path = resolve_stored_path(str(statement.get("file")), base)
    start_line = statement.get("start_line")
    end_line = statement.get("end_line")
    if not is_int(start_line) or not is_int(end_line):
        raise ValueError("Invalid reviewed statement range")
    return scan_span_evidence(
        path,
        start_line,
        end_line,
        base,
        structural_context="formal_statement",
    )


def reviewed_unit_reference_occurrences(
    unit: dict[str, Any],
    base: Path,
    label_owners: dict[str, dict[str, Any]],
) -> list[dict[str, Any]]:
    """Return one owner-decorated occurrence list for statement and proof."""
    statement_rows = scan_unit_statement_evidence(unit, base).get(
        "reference_occurrences", []
    )
    proof_rows = unit.get("reference_occurrences", [])
    by_id: dict[str, dict[str, Any]] = {}
    for row in [*statement_rows, *proof_rows]:
        if not isinstance(row, dict) or not is_nonempty_string(
            row.get("occurrence_id")
        ):
            continue
        occurrence = dict(row)
        owner = label_owners.get(str(occurrence.get("target")))
        if isinstance(owner, dict):
            occurrence["resolution_status"] = owner.get("status")
            occurrence["owner_unit_id"] = owner.get("owner_unit_id")
            occurrence["owner_region"] = owner.get("owner_region")
        else:
            occurrence["resolution_status"] = "missing"
            occurrence.pop("owner_unit_id", None)
            occurrence.pop("owner_region", None)
        by_id[str(occurrence["occurrence_id"])] = occurrence
    return list(by_id.values())


def display_math_spans(lines: list[str]) -> list[dict[str, Any]]:
    text = "\n".join(lines)
    masked = mask_structural_tex(text)
    stack: list[dict[str, Any]] = []
    spans: list[dict[str, Any]] = []
    for token in TOKEN_RE.finditer(masked):
        action, environment = token.group(1), token.group(2)
        if environment.rstrip("*") not in DISPLAY_MATH_ENVIRONMENTS:
            continue
        if action == "begin":
            stack.append({"environment": environment, "offset": token.start()})
            continue
        match_index = next(
            (
                index
                for index in range(len(stack) - 1, -1, -1)
                if stack[index]["environment"] == environment
            ),
            None,
        )
        if match_index is None:
            continue
        opened = stack.pop(match_index)
        start_line, start_column = source_line_column(text, opened["offset"])
        end_offset = max(token.start(), token.end() - 1)
        end_line, end_column = source_line_column(text, end_offset)
        spans.append(
            {
                "environment": environment,
                "start_line": start_line,
                "start_column": start_column,
                "end_line": end_line,
                "end_column": end_column,
                "length": token.end() - opened["offset"],
            }
        )
    # Keep ordinary display delimiters local to this helper: the shared
    # environment scanner also discovers theorem and proof structure.
    opened_delimiter: dict[str, Any] | None = None
    inline_dollar = False
    consumed_end = 0
    for token in re.finditer(r"(?=(\\[\[\]]|\$\$?))", masked):
        if token.start() < consumed_end:
            continue
        backslashes = 0
        cursor = token.start() - 1
        while cursor >= 0 and masked[cursor] == "\\":
            backslashes += 1
            cursor -= 1
        if backslashes % 2:
            continue
        delimiter = token.group(1)
        token_end = token.start() + len(delimiter)
        if inline_dollar and delimiter.startswith("$"):
            # The closing inline dollar cannot also open a display. Leave any
            # adjacent dollar for the next token, as in $x$$y$ or $x$$$y$$.
            inline_dollar = False
            consumed_end = token.start() + 1
            continue
        consumed_end = token_end
        if delimiter == "$":
            inline_dollar = True
            continue
        if inline_dollar:
            continue
        if opened_delimiter is None:
            if delimiter != r"\]":
                opened_delimiter = {
                    "delimiter": delimiter, "offset": token.start(), "valid": True
                }
            continue
        closing = r"\]" if opened_delimiter["delimiter"] == r"\[" else "$$"
        if delimiter != closing:
            # Nested or mixed delimiters are malformed. Do not manufacture a
            # complete span from a partial match within that display.
            opened_delimiter["valid"] = False
            continue
        if opened_delimiter["valid"]:
            start_line, start_column = source_line_column(text, opened_delimiter["offset"])
            end_line, end_column = source_line_column(text, token_end - 1)
            spans.append({
                "environment": opened_delimiter["delimiter"],
                "start_line": start_line,
                "start_column": start_column,
                "end_line": end_line,
                "end_column": end_column,
                "length": token_end - opened_delimiter["offset"],
            })
        opened_delimiter = None
    return spans


def display_math_contains_lines(
    spans: list[dict[str, Any]], masked_lines: list[str], start: int, end: int
) -> bool:
    """Whether all active content in a physical line range lies in one display."""
    content_lines = [
        (number, masked_lines[number - 1])
        for number in range(start, end + 1)
        if 1 <= number <= len(masked_lines) and masked_lines[number - 1].strip()
    ]
    if not content_lines:
        return False
    first, first_text = content_lines[0]
    last, last_text = content_lines[-1]
    first_position = (first, len(first_text) - len(first_text.lstrip()) + 1)
    last_position = (last, len(last_text.rstrip()))
    return any(
        span["start_line"] <= start <= end <= span["end_line"]
        and (span["start_line"], span["start_column"]) <= first_position
        and last_position <= (span["end_line"], span["end_column"])
        for span in spans
    )


def proof_heading_gaps(
    source_lines: dict[Path, list[str]],
    units: Iterable[dict[str, Any]],
    base: Path,
) -> list[dict[str, Any]]:
    resolved_source_lines = {
        path.resolve(): lines for path, lines in source_lines.items()
    }
    barriers: dict[Path, list[tuple[int, int]]] = defaultdict(list)
    for unit in units:
        for region_name in ("statement", "proof"):
            region = unit.get(region_name)
            if not isinstance(region, dict):
                continue
            file_value = region.get("file")
            start_line = region.get("start_line")
            end_line = region.get("end_line")
            if (
                not is_nonempty_string(file_value)
                or not is_int(start_line)
                or not is_int(end_line)
            ):
                continue
            path = resolve_stored_path(file_value, base).resolve()
            if path in resolved_source_lines:
                barriers[path].append((start_line, end_line))

    gaps: list[dict[str, Any]] = []
    for path, lines in resolved_source_lines.items():
        barriers[path].extend(proof_environment_spans(path))
        merged_barriers: list[list[int]] = []
        for start_line, end_line in sorted(barriers[path]):
            if start_line > end_line:
                continue
            if merged_barriers and start_line <= merged_barriers[-1][1] + 1:
                merged_barriers[-1][1] = max(
                    merged_barriers[-1][1], end_line
                )
            else:
                merged_barriers.append([start_line, end_line])

        text = "\n".join(lines)
        headings = [
            {
                **heading,
                "line": heading["start_line"],
            }
            for heading in scan_section_headings(text)
        ]
        for heading_index, heading in enumerate(headings):
            if not re.search(r"\bproofs?\b", heading["title"], re.IGNORECASE):
                continue
            next_heading = (
                headings[heading_index + 1]
                if heading_index + 1 < len(headings)
                else None
            )
            section_end = (
                next_heading["line"] - 1
                if next_heading is not None
                else len(lines)
            )
            cursor = heading["line"] + 1
            for barrier_start, barrier_end in merged_barriers:
                if barrier_end < cursor:
                    continue
                if barrier_start > section_end:
                    break
                if cursor < barrier_start:
                    gaps.append(
                        {
                            "file": relative_or_absolute(path, base),
                            "start_line": cursor,
                            "end_line": min(barrier_start - 1, section_end),
                            "heading_line": heading["line"],
                        }
                    )
                cursor = max(cursor, barrier_end + 1)
                if cursor > section_end:
                    break
            if cursor <= section_end:
                gaps.append(
                    {
                        "file": relative_or_absolute(path, base),
                        "start_line": cursor,
                        "end_line": section_end,
                        "heading_line": heading["line"],
                    }
                )
    return gaps


def build_unowned_label_support_index(
    source_lines: dict[Path, list[str]],
    units: Iterable[dict[str, Any]],
    label_owners: dict[str, dict[str, Any]],
    base: Path,
) -> dict[str, dict[str, Any]]:
    resolved_source_lines = {
        path.resolve(): lines for path, lines in source_lines.items()
    }
    gaps_by_file: dict[Path, list[dict[str, Any]]] = defaultdict(list)
    for gap in proof_heading_gaps(resolved_source_lines, units, base):
        path = resolve_stored_path(gap["file"], base).resolve()
        gaps_by_file[path].append(gap)
    math_spans = {
        path: display_math_spans(lines)
        for path, lines in resolved_source_lines.items()
    }

    result: dict[str, dict[str, Any]] = {}
    for target, owner in sorted(label_owners.items()):
        locations = owner.get("locations")
        if owner.get("status") != "unowned" or not isinstance(locations, list):
            continue
        if len(locations) != 1 or not isinstance(locations[0], dict):
            continue
        location = locations[0]
        file_value = location.get("file")
        line = location.get("line")
        column = location.get("column")
        if (
            not is_nonempty_string(file_value)
            or not is_int(line)
            or not is_int(column)
        ):
            continue
        path = resolve_stored_path(file_value, base).resolve()
        if path not in resolved_source_lines:
            continue
        containing_blocks = [
            block
            for block in math_spans.get(path, [])
            if (block["start_line"], block["start_column"])
            <= (line, column)
            <= (block["end_line"], block["end_column"])
        ]
        if not containing_blocks:
            continue
        block = min(containing_blocks, key=lambda item: item["length"])
        containing_gaps = [
            gap
            for gap in gaps_by_file.get(path, [])
            if gap["start_line"] <= block["start_line"]
            and block["end_line"] <= gap["end_line"]
        ]
        if not containing_gaps:
            continue
        gap = max(
            containing_gaps,
            key=lambda item: (item["heading_line"], item["start_line"]),
        )
        selected = resolved_source_lines[path][
            gap["start_line"] - 1 : block["end_line"]
        ]
        occurrences, _ = scan_reference_occurrences(
            "\n".join(selected),
            path,
            base,
            start_line=gap["start_line"],
            structural_context="unowned_support_region",
        )
        occurrences = [
            occurrence
            for occurrence in occurrences
            if (occurrence["line"], occurrence["column"])
            <= (block["end_line"], block["end_column"])
        ]
        result[target] = {
            "reference_occurrences": occurrences,
            "region": {
                "file": relative_or_absolute(path, base),
                "start_line": gap["start_line"],
                "end_line": block["end_line"],
            },
        }
    return result


def resolve_candidate_internal_dependency_paths(
    unit_id: str,
    occurrences: Iterable[dict[str, Any]],
    label_owners: dict[str, dict[str, Any]],
    support_index: dict[str, dict[str, Any]],
) -> list[dict[str, Any]]:
    pending = [
        (str(occurrence.get("target")), [dict(occurrence)], frozenset())
        for occurrence in occurrences
        if isinstance(occurrence, dict)
        and is_nonempty_string(occurrence.get("target"))
    ]
    paths: list[dict[str, Any]] = []
    while pending:
        target, chain, visited_labels = pending.pop()
        if target in visited_labels:
            continue
        next_visited = visited_labels | {target}
        owner = label_owners.get(target)
        if not isinstance(owner, dict):
            continue
        owner_unit_id = owner.get("owner_unit_id")
        if owner.get("status") == "unique" and is_nonempty_string(owner_unit_id):
            if owner_unit_id != unit_id:
                paths.append(
                    {
                        "candidate_id": str(owner_unit_id),
                        "reference_chain": chain,
                    }
                )
            continue
        if owner.get("status") != "unowned":
            continue
        support = support_index.get(target)
        if not isinstance(support, dict):
            continue
        for occurrence in support.get("reference_occurrences", []):
            if isinstance(occurrence, dict) and is_nonempty_string(
                occurrence.get("target")
            ):
                pending.append(
                    (
                        str(occurrence["target"]),
                        [*chain, dict(occurrence)],
                        next_visited,
                    )
                )
    unique: dict[str, dict[str, Any]] = {}
    for path in paths:
        identity = canonical_sha256(path)
        unique[identity] = path
    return sorted(
        unique.values(),
        key=lambda row: (
            str(row.get("candidate_id", "")),
            canonical_sha256(row),
        ),
    )


def resolve_candidate_internal_dependencies(
    unit_id: str,
    occurrences: Iterable[dict[str, Any]],
    label_owners: dict[str, dict[str, Any]],
    support_index: dict[str, dict[str, Any]],
) -> list[str]:
    return sorted(
        {
            str(path["candidate_id"])
            for path in resolve_candidate_internal_dependency_paths(
                unit_id, occurrences, label_owners, support_index
            )
        }
    )


PROOF_TERMINATOR_TOKEN_RE = re.compile(
    r"(?:\\hfill\s*)?(?P<marker>\\BlackBox|\\qed(?:here)?|\\QED|"
    r"\\(?:black)?square|\$\s*\\(?:Box|square|blacksquare)\s*\$)"
)
DISPLAY_CLOSING_ENVIRONMENTS = DISPLAY_MATH_ENVIRONMENTS | {
    "aligned",
    "alignedat",
    "array",
    "cases",
    "gathered",
    "matrix",
    "pmatrix",
    "smallmatrix",
    "split",
}


def same_line_display_closers_are_structural(value: str) -> bool:
    cursor = 0
    found = False
    while cursor < len(value):
        match = re.match(r"\s*\\end\s*\{([^}]+)\}", value[cursor:])
        if match is None:
            return False
        if match.group(1).rstrip("*") not in DISPLAY_CLOSING_ENVIRONMENTS:
            return False
        cursor += match.end()
        found = True
    return found


def proof_terminator_kind(raw_line: str) -> str | None:
    clean = strip_latex_comment(raw_line).strip()
    if re.fullmatch(r"\\end\s*\{proof\}", clean):
        return "proof_environment_end"
    matches = list(PROOF_TERMINATOR_TOKEN_RE.finditer(clean))
    if not matches:
        return None
    if len(matches) != 1:
        return "multiple_qed_markers"
    marker = matches[0].group("marker")
    suffix = clean[matches[0].end() :]
    if suffix and not (
        marker == r"\qedhere"
        and same_line_display_closers_are_structural(suffix)
    ):
        return None
    if marker == r"\qedhere":
        return "qed_here_marker"
    return "qed_marker"


def proof_terminal_region_end(
    lines: list[str], marker_line: int, section_end: int, boundary_kind: str
) -> int:
    r"""Include only display closers structurally required after \qedhere."""
    if boundary_kind != "qed_here_marker":
        return marker_line
    region_end = marker_line
    cursor = marker_line + 1
    while cursor <= section_end:
        clean = strip_latex_comment(lines[cursor - 1]).strip()
        if not clean:
            cursor += 1
            continue
        if clean == r"\]":
            region_end = cursor
            cursor += 1
            continue
        closing = re.fullmatch(r"\\end\s*\{([^}]+)\}", clean)
        if (
            closing is None
            or closing.group(1).rstrip("*") not in DISPLAY_CLOSING_ENVIRONMENTS
        ):
            break
        region_end = cursor
        cursor += 1
    return region_end


def proof_tail_is_structural(
    lines: list[str], start_line: int, end_line: int, *, allow_epilogue: bool
) -> bool:
    """Return whether a post-proof tail contains no unheaded manuscript prose."""
    bibliography_depth = 0
    for line_number in range(start_line, end_line + 1):
        clean = strip_latex_comment(lines[line_number - 1]).strip()
        if not clean:
            continue
        if re.fullmatch(r"\\begin\s*\{thebibliography\}(?:\{[^}]*\})?", clean):
            if not allow_epilogue:
                return False
            bibliography_depth += 1
            continue
        if bibliography_depth:
            if re.fullmatch(r"\\end\s*\{thebibliography\}", clean):
                bibliography_depth -= 1
            continue
        if re.fullmatch(
            r"\\(?:phantomsection|label\s*\{[^}]+\}|clearpage|newpage|"
            r"FloatBarrier)",
            clean,
        ):
            continue
        if allow_epilogue and re.fullmatch(
            r"\\(?:bibliographystyle\s*\{[^}]+\}|bibliography\s*\{[^}]+\}|"
            r"printbibliography(?:\[[^]]*\])?|end\s*\{document\}|"
            r"vskip\s+[^%]+|vspace\*?\s*\{[^}]+\}|"
            r"smallskip|medskip|bigskip|pagebreak(?:\[[^]]*\])?|"
            r"nopagebreak(?:\[[^]]*\])?)",
            clean,
        ):
            continue
        return False
    return bibliography_depth == 0


def analyze_proof_region(
    path: Path,
    anchor_line: int,
    *,
    target_unit_id: str | None = None,
    max_heading_distance: int = 4,
    source_files: Iterable[Path] | None = None,
) -> dict[str, Any]:
    """Return one canonical proof region or a structured rejection reason."""
    lines = read_lines(path)
    if not 1 <= anchor_line <= len(lines):
        return {
            "status": "invalid",
            "reason": "anchor_out_of_range",
            "start_line": anchor_line,
            "end_line": None,
        }
    structural_lines = mask_structural_tex("\n".join(lines)).split("\n")

    exact_environments = sorted(
        (start, end)
        for start, end in proof_environment_spans(path, source_files=source_files)
        if start == anchor_line
    )
    if len(exact_environments) == 1:
        start_line, end_line = exact_environments[0]
        return {
            "status": "accepted",
            "method": "proof_environment",
            "start_line": start_line,
            "end_line": end_line,
            "header_span": None,
            "target_labels": [],
            "boundary": {
                "kind": "proof_environment_end",
                "line": end_line,
                "evidence": strip_latex_comment(lines[end_line - 1]).strip(),
            },
            "reason": None,
        }

    headings = scan_section_headings("\n".join(lines))
    candidates = [
        heading
        for heading in headings
        if anchor_line <= heading["start_line"] <= anchor_line + max_heading_distance
        and re.search(r"\bproofs?\b", heading["title"], re.IGNORECASE)
    ]
    if target_unit_id is not None:
        candidates = [
            heading
            for heading in candidates
            if heading["target_labels"] == [target_unit_id]
        ]
    if len(candidates) != 1:
        return {
            "status": "ambiguous",
            "reason": (
                "named_heading_target_not_unique"
                if target_unit_id is not None
                else "named_heading_not_unique"
            ),
            "start_line": anchor_line,
            "end_line": None,
            "candidate_count": len(candidates),
        }

    heading = candidates[0]
    later_boundary = next(
        (
            other
            for other in headings
            if other["start_line"] > heading["start_line"]
            and other["level"] <= heading["level"]
        ),
        None,
    )
    section_end = (
        later_boundary["start_line"] - 1
        if later_boundary is not None
        else len(lines)
    )
    terminators = [
        (line_number, proof_terminator_kind(structural_lines[line_number - 1]))
        for line_number in range(heading["end_line"], section_end + 1)
        if proof_terminator_kind(structural_lines[line_number - 1]) is not None
    ]
    if terminators:
        if (
            len(terminators) != 1
            or any(kind == "multiple_qed_markers" for _, kind in terminators)
        ):
            return {
                "status": "ambiguous",
                "reason": "multiple_terminal_markers",
                "start_line": anchor_line,
                "end_line": None,
                "terminator_lines": [line for line, _ in terminators],
            }
        acceptable = [
            (
                line_number,
                proof_terminal_region_end(
                    structural_lines, line_number, section_end, kind
                ),
                kind,
            )
            for line_number, kind in terminators
            if proof_tail_is_structural(
                structural_lines,
                proof_terminal_region_end(
                    structural_lines, line_number, section_end, kind
                )
                + 1,
                section_end,
                allow_epilogue=later_boundary is None,
            )
        ]
        if len(acceptable) != 1:
            return {
                "status": "ambiguous",
                "reason": "terminator_followed_by_substantive_or_ambiguous_tail",
                "start_line": anchor_line,
                "end_line": None,
                "terminator_lines": [line for line, _ in terminators],
            }
        marker_line, end_line, boundary_kind = acceptable[0]
    elif later_boundary is not None:
        end_line = section_end
        while end_line >= heading["end_line"] and proof_tail_is_structural(
            structural_lines, end_line, end_line, allow_epilogue=False
        ):
            end_line -= 1
        boundary_kind = "next_heading"
    else:
        return {
            "status": "unbounded",
            "reason": "named_heading_at_eof_requires_terminal_marker",
            "start_line": anchor_line,
            "end_line": None,
        }
    if end_line < heading["end_line"]:
        return {
            "status": "invalid",
            "reason": "empty_named_proof_region",
            "start_line": anchor_line,
            "end_line": None,
        }
    return {
        "status": "accepted",
        "method": "named_heading",
        "start_line": anchor_line,
        "end_line": end_line,
        "header_span": {
            "start_line": heading["start_line"],
            "start_column": heading["start_column"],
            "end_line": heading["end_line"],
            "end_column": heading["end_column"],
            "text": heading["title"],
        },
        "target_labels": heading["target_labels"],
        "boundary": {
            "kind": boundary_kind,
            "line": end_line,
            "marker_line": marker_line if terminators else None,
            "evidence": strip_latex_comment(lines[end_line - 1]).strip(),
        },
        "reason": None,
    }


def bounded_proof_region(
    path: Path,
    anchor_line: int,
    *,
    target_unit_id: str | None = None,
    max_heading_distance: int = 4,
    source_files: Iterable[Path] | None = None,
) -> dict[str, Any] | None:
    region = analyze_proof_region(
        path,
        anchor_line,
        target_unit_id=target_unit_id,
        max_heading_distance=max_heading_distance,
        source_files=source_files,
    )
    return region if region.get("status") == "accepted" else None


def canonical_location(value: Any) -> dict[str, Any] | None:
    if value is None:
        return None
    if not isinstance(value, dict):
        return {}
    return {
        "file": value.get("file"),
        "start_line": value.get("start_line"),
        "end_line": value.get("end_line"),
    }


def source_span_sha256(path: Path, start_line: int, end_line: int) -> str:
    lines = read_lines(path)
    if not (1 <= start_line <= end_line <= len(lines)):
        raise ValueError(f"Invalid source span {path}:{start_line}-{end_line}")
    return sha256_text("\n".join(lines[start_line - 1 : end_line]))


def proof_alias_names(source_files: Iterable[Path]) -> set[str]:
    """Recognize literal wrappers whose bodies only open and close proof."""
    names = {"proof"}
    for path in source_files:
        try:
            text = mask_tex_literals_for_definition_scan("\n".join(read_lines(path)))
        except TextArtifactReadError:
            # The snapshot and parser-warning review retain unreadable context;
            # it cannot supply an automatically recognized proof alias.
            continue
        declarations = []
        conditional_skeleton = list(text)
        cursor = 0
        for declaration in TEX_DEFINITION_COMMAND_RE.finditer(text):
            if declaration.start() < cursor:
                continue
            end = tex_definition_end(text, declaration)
            cursor = end if end is not None else len(text)
            declarations.append(declaration)
            # Keep a marker at the declaration, masking its body so a literal
            # conditional inside a macro does not change its enclosing branch.
            mask_tex_range(conditional_skeleton, declaration.start() + 1, cursor)
        active_declarations = mask_inactive_tex_branches("".join(conditional_skeleton))
        for declaration in declarations:
            if active_declarations[declaration.start()] != "\\":
                continue
            if declaration.group("command") not in TEX_NEW_ENVIRONMENT_DEFINITIONS:
                continue
            bodies = tex_definition_body_spans(text, declaration)
            target = re.match(r"\s*\{([^}]+)\}", text[declaration.end():])
            if target is None or len(bodies) != 2:
                continue
            if target.group(1) != "proof":
                names.discard(target.group(1))
            begin, close = (text[start:stop].strip() for start, stop in bodies)
            if re.fullmatch(r"\\begin\s*\{proof\}(?:\s*\[[^]]*\])?", begin) and re.fullmatch(r"\\end\s*\{proof\}", close):
                names.add(target.group(1))
    return names


def theorem_environment_catalog(source_lines: dict[Path, list[str]], base: Path) -> dict[str, dict[str, Any]]:
    """Preserve a literal declaration's role without interpreting arbitrary TeX."""
    catalog = {name: {"kind": name} for name in FORMAL_ENVIRONMENTS}
    for path, lines in source_lines.items():
        text = mask_structural_tex("\n".join(lines), preserve_theorem_declarations=True)
        for declaration in TEX_DEFINITION_COMMAND_RE.finditer(text):
            command = declaration.group("command")
            if command not in TEX_THEOREM_DEFINITIONS | TEX_OPTION_FIRST_THEOREM_DEFINITIONS:
                continue
            cursor = skip_tex_whitespace(text, declaration.end())
            options_start = cursor
            if command in TEX_OPTION_FIRST_THEOREM_DEFINITIONS:
                cursor = consume_tex_optional_arguments(text, cursor)
            if cursor is None:
                continue
            target_end = consume_balanced_tex_group(text, cursor, "{", "}")
            if target_end is None:
                continue
            environment = text[cursor + 1:target_end - 1].strip()
            if command in TEX_OPTION_FIRST_THEOREM_DEFINITIONS:
                title_match = re.search(r"(?:^|[\[,])\s*name\s*=\s*(?:\{([^}]+)\}|([^,\]]+))", text[options_start:cursor])
                title = (title_match.group(1) or title_match.group(2)).strip() if title_match else environment
                end = target_end
            else:
                title_start = consume_tex_optional_arguments(text, target_end)
                end = consume_balanced_tex_group(text, title_start, "{", "}") if title_start is not None else None
                if end is None:
                    continue
                title = text[title_start + 1:end - 1].strip()
            role = title.casefold().rstrip("s")
            kind = role if role in FORMAL_ENVIRONMENTS else None
            start_line, _ = source_line_column(text, declaration.start())
            end_line, _ = source_line_column(text, end - 1)
            catalog[environment] = {"kind": kind, "title": title, "declaration": {
                "file": relative_or_absolute(path, base), "start_line": start_line,
                "end_line": end_line, "sha256": source_span_sha256(path, start_line, end_line),
            }}
    return catalog


def proof_environment_spans(path: Path, *, source_files: Iterable[Path] | None = None) -> set[tuple[int, int]]:
    spans: set[tuple[int, int]] = set()
    stack: list[tuple[str, int]] = []
    environments = proof_alias_names(source_files if source_files is not None else [path])
    text = "\n".join(read_lines(path))
    masked = mask_structural_tex(text)
    for token in TOKEN_RE.finditer(masked):
        action, environment = token.group(1), token.group(2)
        if environment not in environments:
            continue
        line_number, _ = source_line_column(text, token.start())
        if action == "begin":
            stack.append((environment, line_number))
        elif stack and stack[-1][0] == environment:
            spans.add((stack.pop()[1], line_number))
    return spans


def proof_span_has_safe_boundary(
    path: Path,
    start_line: int,
    end_line: int,
    *,
    target_unit_id: str | None = None,
    source_files: Iterable[Path] | None = None,
) -> bool:
    region = bounded_proof_region(
        path, start_line, target_unit_id=target_unit_id, source_files=source_files
    )
    return bool(
        isinstance(region, dict)
        and region.get("start_line") == start_line
        and region.get("end_line") == end_line
    )


def span_contains_location(
    span: Any,
    file_value: Any,
    line_value: Any,
    base: Path | None = None,
) -> bool:
    same_file = bool(
        isinstance(span, dict) and span.get("file") == file_value
    )
    if (
        base is not None
        and isinstance(span, dict)
        and is_nonempty_string(span.get("file"))
        and is_nonempty_string(file_value)
    ):
        same_file = (
            resolve_stored_path(span["file"], base)
            == resolve_stored_path(file_value, base)
        )
    contained = bool(
        isinstance(span, dict)
        and same_file
        and is_int(span.get("start_line"))
        and is_int(span.get("end_line"))
        and is_int(line_value)
        and span["start_line"] <= line_value <= span["end_line"]
    )
    if not contained and base is not None and isinstance(span, dict) and is_int(line_value):
        try:
            path = resolve_stored_path(span["file"], base)
            first, last = span["start_line"], span["end_line"]
            selected = "\n".join(read_lines(path)[first - 1:last])
            if INCLUSION_COMMAND_RE.search(selected):
                expanded = source_fragment_support().expand(report_api(), path, first, last, base)
                return any(fragment["file"] == relative_or_absolute(resolve_stored_path(file_value, base), base)
                           and fragment["start_line"] <= line_value <= fragment["end_line"]
                           for fragment in expanded["fragments"])
        except (KeyError, OSError, TypeError, ValueError):
            return False
    return contained


def reviewed_label_owners(
    cross_references: dict[str, Any],
    unit_inventory: dict[str, dict[str, Any]],
    base: Path,
) -> dict[str, dict[str, Any]]:
    owners: dict[str, dict[str, Any]] = {}
    labels = cross_references.get("labels")
    if not isinstance(labels, dict):
        return owners
    for target, raw_locations in sorted(labels.items()):
        locations = (
            raw_locations
            if isinstance(raw_locations, list)
            else []
        )
        if len(locations) != 1:
            owners[target] = {
                "status": "duplicate",
                "owner_unit_id": None,
                "owner_region": None,
                "locations": locations,
            }
            continue
        location = locations[0] if isinstance(locations[0], dict) else {}
        candidates: list[tuple[str, str]] = []
        for unit_id, unit in unit_inventory.items():
            for region in ("statement", "proof"):
                if span_contains_location(
                    unit.get(region),
                    location.get("file"),
                    location.get("line"),
                    base,
                ):
                    candidates.append((unit_id, region))
        unique_candidates = sorted(set(candidates))
        if len(unique_candidates) == 1:
            owner_unit_id, owner_region = unique_candidates[0]
            status = "unique"
        elif unique_candidates:
            owner_unit_id, owner_region, status = None, None, "ambiguous"
        else:
            owner_unit_id, owner_region, status = None, None, "unowned"
        owners[target] = {
            "status": status,
            "owner_unit_id": owner_unit_id,
            "owner_region": owner_region,
            "locations": locations,
        }
    return owners


def reviewed_span_evidence(
    unit_id: str,
    unit: dict[str, Any],
    base: Path,
    label_owners: dict[str, dict[str, Any]],
    support_index: dict[str, dict[str, Any]] | None = None,
    *,
    statement_as_primary: bool = False,
    source_files: Iterable[Path] | None = None,
) -> dict[str, Any]:
    statement_evidence = scan_unit_statement_evidence(unit, base)
    proof = unit.get("proof")
    if not isinstance(proof, dict):
        evidence = (
            {
                field: list(statement_evidence[field])
                for field in (
                    "reference_occurrences",
                    "dependencies",
                    "citations",
                    "warnings",
                )
            }
            if statement_as_primary
            else {
                "reference_occurrences": [],
                "dependencies": [],
                "citations": [],
                "warnings": [],
            }
        )
        title_span = None
    else:
        path = resolve_stored_path(str(proof.get("file")), base)
        start_line = proof.get("start_line")
        end_line = proof.get("end_line")
        if not is_int(start_line) or not is_int(end_line):
            raise ValueError(f"Invalid reviewed proof range for {unit_id}")
        evidence = scan_span_evidence(path, start_line, end_line, base)
        lines = read_lines(path)[start_line - 1 : end_line]
        proof_sources = list(source_files) if source_files is not None else collect_tex_files(path)[0]
        if (start_line, end_line) in proof_environment_spans(path, source_files=proof_sources):
            title_span = proof_optional_title_span(lines, start_line)
        else:
            analyzed = analyze_proof_region(
                path,
                start_line,
                target_unit_id=unit_id,
            )
            title_span = (
                analyzed.get("header_span")
                if analyzed.get("status") == "accepted"
                and analyzed.get("method") == "named_heading"
                and analyzed.get("end_line") == end_line
                else None
            )
        title = (
            title_span.get("text")
            if isinstance(title_span, dict)
            else None
        )
        if title is not None:
            _, title_warnings = scan_reference_occurrences(
                title,
                path,
                base,
                start_line=title_span["start_line"],
                structural_context="proof_header",
            )
            evidence["warnings"].extend(title_warnings)
    for occurrence in evidence["reference_occurrences"]:
        if occurrence_in_title(occurrence, title_span):
            occurrence["structural_context"] = "proof_header"
        owner = label_owners.get(occurrence.get("target"))
        if owner is None:
            occurrence["resolution_status"] = "missing"
            continue
        occurrence["resolution_status"] = owner.get("status")
        occurrence["owner_unit_id"] = owner.get("owner_unit_id")
        occurrence["owner_region"] = owner.get("owner_region")
    evidence["candidate_internal_dependencies"] = (
        resolve_candidate_internal_dependencies(
            unit_id,
            [
                *statement_evidence["reference_occurrences"],
                *evidence["reference_occurrences"],
            ],
            label_owners,
            support_index or {},
        )
    )
    if not statement_as_primary:
        evidence["warnings"].extend(statement_evidence["warnings"])
    evidence["warnings"] = sorted(set(evidence["warnings"]))
    return evidence


def last_substantive_line(path: Path, start_line: int, end_line: int) -> int:
    lines = read_lines(path)
    for line_number in range(min(end_line, len(lines)), start_line - 1, -1):
        clean = strip_latex_comment(lines[line_number - 1]).strip()
        if clean and not re.fullmatch(r"\\end\s*\{proof\}", clean):
            return line_number
    return start_line


def expanded_last_substantive_position(expanded: dict[str, Any]) -> int:
    substantive = [row["line"] for row in expanded["lines"] if not locked_line_is_non_substantive(row)]
    return substantive[-1] if substantive else expanded["lines"][0]["line"]


def discover_source_closure(
    root: Path,
    *,
    additional_files: Iterable[Path] | None = None,
    fls_file: Path | None = None,
    project_root: Path | None = None,
    warning_path_base: Path | None = None,
) -> dict[str, Any]:
    root = root.resolve()
    project_root = (project_root or root.parent).resolve()
    warning_path_base = (
        warning_path_base.resolve() if warning_path_base is not None else None
    )
    ordered: list[Path] = []
    visited: set[Path] = set()
    active: set[Path] = set()
    warnings: list[str] = []
    outside_project_inputs: set[str] = set()

    def shown(path: Path) -> str:
        return source_path_identity(path, warning_path_base)

    def local_candidates(
        requested: str, suffix: str, source: Path, line_number: int
    ) -> list[Path]:
        raw = requested.strip()
        if "\\" in raw or "#" in raw:
            warnings.append(
                "Dynamic class or package requires manual review: "
                f"{shown(source)}:{line_number}: {raw}"
            )
            return []
        requested_path = Path(raw)
        explicit_local_reference = (
            requested_path.is_absolute()
            or raw.startswith("./")
            or requested_path.parent != Path(".")
            or requested_path.suffix != ""
        )
        value = requested_path
        if value.suffix == "":
            value = value.with_suffix(suffix)
        if value.is_absolute():
            candidates = [value.resolve()] if value.is_file() else []
        else:
            search_roots = [source.parent.resolve()]
            if project_root not in search_roots:
                search_roots.append(project_root)
            candidates = []
            for search_root in search_roots:
                candidate = (search_root / value).resolve()
                if candidate.is_file() and candidate not in candidates:
                    candidates.append(candidate)
        if len(candidates) > 1:
            warnings.append(
                "Ambiguous local class or package resolution requires manual review: "
                f"{shown(source)}:{line_number}: {raw}: "
                + ", ".join(shown(item) for item in candidates)
            )
        if not candidates and explicit_local_reference:
            warnings.append(
                "Explicit local class or package not found: "
                f"{shown(source)}:{line_number}: {raw}"
            )
        return candidates

    def visit(path: Path) -> None:
        path = path.resolve()
        if path in active:
            warnings.append(f"Include cycle detected at {shown(path)}")
            return
        if path in visited:
            return
        if not path.is_file():
            warnings.append(f"Included file not found: {shown(path)}")
            return

        visited.add(path)
        active.add(path)
        ordered.append(path)
        try:
            lines = read_lines(path)
        except UnicodeError as exc:
            warnings.append(f"Cannot decode {shown(path)} as UTF-8: {exc}")
            active.remove(path)
            return

        source_text = "\n".join(lines)
        warn_definition_body_inclusions(
            source_text,
            source_name=shown(path),
            warnings=warnings,
        )
        structural_lines = mask_structural_tex(
            source_text,
            warnings=warnings,
            source_name=shown(path),
        ).split("\n")
        for line_number, clean in enumerate(structural_lines, 1):
            handled_positions: set[int] = set()

            def include(raw: str, position: int) -> None:
                handled_positions.add(position)
                raw = raw.strip()
                if "\\" in raw or "#" in raw:
                    warnings.append(
                        "Dynamic include requires manual review: "
                        f"{shown(path)}:{line_number}: {raw}"
                    )
                    return
                include_path = Path(raw)
                if include_path.suffix == "":
                    include_path = include_path.with_suffix(".tex")
                if include_path.is_absolute():
                    candidates = (
                        [include_path.resolve()] if include_path.is_file() else []
                    )
                else:
                    search_roots = [path.parent.resolve()]
                    if project_root not in search_roots:
                        search_roots.append(project_root)
                    candidates = []
                    for search_root in search_roots:
                        candidate = (search_root / include_path).resolve()
                        if candidate.is_file() and candidate not in candidates:
                            candidates.append(candidate)
                if len(candidates) > 1:
                    warnings.append(
                        "Ambiguous include resolution requires manual review: "
                        f"{shown(path)}:{line_number}: {raw}: "
                        + ", ".join(shown(item) for item in candidates)
                    )
                if not candidates:
                    warnings.append(
                        "Included file not found: "
                        f"{shown(path)}:{line_number}: {raw}"
                    )
                for candidate in candidates:
                    visit(candidate)

            for match in INCLUDE_RE.finditer(clean):
                include(match.group(1), match.start())
            for match in UNBRACED_INPUT_RE.finditer(clean):
                include(match.group(1), match.start())
            for match in SUBFILE_RE.finditer(clean):
                include(match.group(1), match.start())
            for match in IMPORT_RE.finditer(clean):
                handled_positions.add(match.start())
                directory, filename = match.group(1).strip(), match.group(2).strip()
                include(str(Path(directory) / filename), match.start())
            for match in CLASS_RE.finditer(clean):
                handled_positions.add(match.start())
                for candidate in local_candidates(
                    match.group(1), ".cls", path, line_number
                ):
                    visit(candidate)
            for match in PACKAGE_RE.finditer(clean):
                handled_positions.add(match.start())
                for package in split_reference_keys(match.group(1)):
                    for candidate in local_candidates(
                        package, ".sty", path, line_number
                    ):
                        visit(candidate)
            for match in INCLUSION_COMMAND_RE.finditer(clean):
                if match.start() not in handled_positions:
                    warnings.append(
                        "Unresolved inclusion command requires manual review: "
                        f"{shown(path)}:{line_number}: {truncate(clean)}"
                    )

        active.remove(path)

    visit(root)
    for additional in additional_files or []:
        additional_path = additional.resolve()
        if not additional_path.is_file():
            warnings.append(
                f"Additional source file not found: {shown(additional_path)}"
            )
            continue
        visit(additional_path)

    if fls_file is not None:
        fls_path = fls_file.resolve()
        if not fls_path.is_file():
            warnings.append(f"Recorder file not found: {shown(fls_path)}")
        else:
            working_directory = project_root
            fls_input_paths: set[Path] = set()
            try:
                fls_lines = read_lines(fls_path)
            except UnicodeError as exc:
                warnings.append(
                    f"Cannot decode recorder file {shown(fls_path)} as UTF-8: {exc}"
                )
                fls_lines = []
            for raw_line in fls_lines:
                if raw_line.startswith("PWD "):
                    candidate = Path(raw_line[4:].strip().strip("'\""))
                    if not candidate.is_absolute():
                        candidate = fls_path.parent / candidate
                    working_directory = candidate.resolve()
                    continue
                if not raw_line.startswith("INPUT "):
                    continue
                raw_input = raw_line[6:].strip().strip("'\"")
                candidate = Path(raw_input)
                if not candidate.is_absolute():
                    candidate = working_directory / candidate
                candidate = candidate.resolve()
                fls_input_paths.add(candidate)
                if candidate.suffix.lower() not in FLS_SOURCE_SUFFIXES:
                    continue
                if not candidate.is_relative_to(project_root):
                    outside_project_inputs.add(str(candidate))
                    warnings.append(
                        "Recorder source input outside project root requires manual "
                        "review and explicit promotion if load-bearing: "
                        f"{shown(candidate)}"
                    )
                    continue
                if candidate.is_file():
                    visit(candidate)
                else:
                    warnings.append(f"Recorder input not found: {shown(candidate)}")
            if root not in fls_input_paths:
                warnings.append(
                    f"Recorder trace does not include the main paper: {shown(root)}"
                )

    return {
        "files": ordered,
        "warnings": sorted(set(warnings)),
        "outside_project_inputs": sorted(outside_project_inputs),
    }


def collect_tex_files(
    root: Path,
    *,
    additional_files: Iterable[Path] | None = None,
    fls_file: Path | None = None,
    project_root: Path | None = None,
    warning_path_base: Path | None = None,
) -> tuple[list[Path], list[str]]:
    closure = discover_source_closure(
        root,
        additional_files=additional_files,
        fls_file=fls_file,
        project_root=project_root,
        warning_path_base=warning_path_base,
    )
    return closure["files"], closure["warnings"]


def parse_manifest_source_discovery(
    manifest: dict[str, Any], root: Path, errors: list[str]
) -> tuple[list[Path], Path | None, Path | None, list[str]]:
    discovery = manifest.get("source_discovery")
    if discovery is None:
        discovery = {"additional_files": [], "fls": None}
    if not isinstance(discovery, dict):
        errors.append("manifest.source_discovery must be an object")
        discovery = {"additional_files": [], "fls": None}

    additional_files: list[Path] = []
    additional_records = discovery.get("additional_files", [])
    if not isinstance(additional_records, list):
        errors.append("source_discovery.additional_files must be a list")
        additional_records = []
    seen_additional: set[Path] = set()
    for index, record in enumerate(additional_records, 1):
        prefix = f"source_discovery.additional_files[{index}]"
        if not isinstance(record, dict):
            errors.append(f"{prefix} must be an object")
            continue
        file_value = record.get("file")
        if not is_nonempty_string(file_value):
            errors.append(f"{prefix}.file must be a nonempty string")
            continue
        path = resolve_stored_path(file_value, root)
        if path in seen_additional:
            errors.append(f"Duplicate additional source file: {path}")
        seen_additional.add(path)
        additional_files.append(path)
        if not path.is_file():
            errors.append(f"Additional source file not found: {path}")
        for field in ("reason", "evidence"):
            if not is_nonempty_string(record.get(field)):
                errors.append(f"{prefix}.{field} must be a nonempty string")

    fls_path: Path | None = None
    project_root: Path | None = None
    recorded_outside: list[str] = []
    fls_record = discovery.get("fls")
    if fls_record is not None:
        if not isinstance(fls_record, dict):
            errors.append("source_discovery.fls must be null or an object")
        else:
            fls_value = fls_record.get("file")
            project_value = fls_record.get("project_root")
            digest = fls_record.get("sha256")
            if not is_nonempty_string(fls_value):
                errors.append("source_discovery.fls.file must be a nonempty string")
            else:
                fls_path = resolve_stored_path(fls_value, root)
                if not fls_path.is_file():
                    errors.append(f"Recorder file not found: {fls_path}")
                elif not is_nonempty_string(digest) or sha256_file(fls_path) != digest:
                    errors.append("Recorder file drift: SHA-256 does not match")
            if not is_nonempty_string(project_value):
                errors.append(
                    "source_discovery.fls.project_root must be a nonempty string"
                )
            else:
                project_root = resolve_stored_path(project_value, root)
                if not project_root.is_dir():
                    errors.append(
                        f"Recorder project root is not a directory: {project_root}"
                    )
            outside = fls_record.get("outside_project_inputs")
            if not isinstance(outside, list) or not all(
                is_nonempty_string(item) for item in outside
            ):
                errors.append(
                    "source_discovery.fls.outside_project_inputs must be a string list"
                )
            else:
                recorded_outside = outside
                if len(recorded_outside) != len(set(recorded_outside)):
                    errors.append(
                        "source_discovery.fls.outside_project_inputs contains duplicates"
                    )

    return additional_files, fls_path, project_root, recorded_outside



def location(path: Path, line: int, base: Path) -> dict[str, Any]:
    return {"file": relative_or_absolute(path, base), "line": line}


def truncate(text: str, limit: int = 300) -> str:
    compact = " ".join(text.split())
    return compact if len(compact) <= limit else compact[: limit - 3] + "..."


def readable_source_lines(
    files: Iterable[Path],
    warnings: list[str],
    path_identity_base: Path | None = None,
) -> dict[Path, list[str]]:
    result: dict[Path, list[str]] = {}
    for path in files:
        try:
            result[path] = read_lines(path)
        except UnicodeError as exc:
            warning = (
                f"Cannot decode {source_path_identity(path, path_identity_base)} "
                f"as UTF-8: {exc}"
            )
            if warning not in warnings:
                warnings.append(warning)
    return result


def inventory_identity_errors(units: list[dict[str, Any]]) -> list[str]:
    """Give source locations for identities that cannot support an audit."""
    by_id: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for unit in units:
        by_id[unit["id"]].append(unit)
    return [
        f"Duplicate proof-unit identity {unit_id!r}: "
        + ", ".join(f"{unit['statement']['file']}:{unit['statement']['start_line']}"
                    for unit in matches)
        + ". Give these results distinct manuscript labels before creating an audit."
        for unit_id, matches in by_id.items() if len(matches) > 1
    ]


@gate_context_reader
def scan_formal_units(
    root: Path,
    *,
    source_files: Iterable[Path] | None = None,
    source_warnings: Iterable[str] | None = None,
    path_identity_base: Path | None = None,
) -> dict[str, Any]:
    if source_files is None:
        files, warnings = collect_tex_files(
            root, warning_path_base=path_identity_base
        )
    else:
        files, warnings = list(source_files), list(source_warnings or [])
    base = root.resolve().parent
    path_identity_base = (
        path_identity_base.resolve() if path_identity_base is not None else None
    )

    def shown(path: Path) -> str:
        return source_path_identity(path, path_identity_base)

    source_lines = readable_source_lines(files, warnings, path_identity_base)
    environment_catalog = theorem_environment_catalog(source_lines, base)
    environments = set(environment_catalog)
    proof_environments = proof_alias_names(source_lines)
    masked_source_lines: dict[Path, list[str]] = {}
    for path, lines in source_lines.items():
        text = "\n".join(lines)
        masked_text = mask_structural_tex(
            text,
            warnings=warnings,
            source_name=shown(path),
        )
        masked_source_lines[path] = masked_text.split("\n") if lines else []

    units: list[dict[str, Any]] = []
    proofs: list[dict[str, Any]] = []
    label_occurrences: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for path, lines in source_lines.items():
        for row in scan_label_occurrences("\n".join(lines), path, base):
            if is_nonempty_string(row.get("target")):
                label_occurrences[row["target"]].append(row)

    for path, lines in source_lines.items():
        formal_stack: list[dict[str, Any]] = []
        proof_stack: list[tuple[str, int]] = []
        masked_lines = masked_source_lines[path]
        masked_text = "\n".join(masked_lines)
        line_offsets = [0]
        for line in masked_lines:
            line_offsets.append(line_offsets[-1] + len(line) + 1)

        for line_number, clean in enumerate(masked_lines, 1):
            for token in TOKEN_RE.finditer(clean):
                action, environment = token.group(1), token.group(2)
                if environment in environments or environment in {"restatable", "restatable*"}:
                    if action == "begin":
                        cursor = skip_tex_whitespace(masked_text, line_offsets[line_number - 1] + token.end())
                        title_end = consume_balanced_tex_group(masked_text, cursor, "[", "]")
                        title = masked_text[cursor + 1:title_end - 1] if title_end is not None else None
                        cursor = skip_tex_whitespace(masked_text, title_end) if title_end is not None else cursor
                        formal_environment = environment
                        restatement_command = None
                        if environment in {"restatable", "restatable*"}:
                            type_end = consume_balanced_tex_group(masked_text, cursor, "{", "}")
                            if type_end is not None:
                                formal_environment = masked_text[cursor + 1:type_end - 1].strip()
                                cursor = skip_tex_whitespace(masked_text, type_end)
                            command_end = consume_balanced_tex_group(masked_text, cursor, "{", "}")
                            restatement_command = masked_text[cursor + 1:command_end - 1].strip() if command_end is not None else None
                            if formal_environment not in environments or not isinstance(restatement_command, str) or not re.fullmatch(r"[A-Za-z@]+", restatement_command):
                                warnings.append(f"Unsupported restatable declaration at {shown(path)}:{line_number}; use a literal declared theorem type and command, or reconcile the omitted result with a source-bound manual_unit override")
                                continue
                        formal_stack.append(
                            {"environment": environment, "formal_environment": formal_environment,
                             "start": line_number, "title": title, "restatement_command": restatement_command}
                        )
                    else:
                        match_index = next(
                            (
                                index
                                for index in range(len(formal_stack) - 1, -1, -1)
                                if formal_stack[index]["environment"] == environment
                            ),
                            None,
                        )
                        if match_index is None:
                            warnings.append(
                                "Unmatched "
                                f"\\end{{{environment}}}: {shown(path)}:{line_number}"
                            )
                            continue
                        opened = formal_stack.pop(match_index)
                        block = lines[opened["start"] - 1 : line_number]
                        masked_block = masked_lines[
                            opened["start"] - 1 : line_number
                        ]
                        labels = [
                            key
                            for block_line in masked_block
                            for key in LABEL_RE.findall(block_line)
                        ]
                        label = labels[0] if labels else None
                        formal_environment = opened["formal_environment"]
                        declaration = environment_catalog[formal_environment]
                        semantic_kind = declaration.get("kind")
                        units.append(
                            {
                                "id": label
                                or f"{formal_environment}:{path.name}:{opened['start']}",
                                "environment": formal_environment,
                                "semantic_kind": semantic_kind,
                                "statement_title": opened["title"],
                                **({"environment_declaration": declaration["declaration"]} if "declaration" in declaration else {}),
                                **({"restatable": {"command": opened["restatement_command"], "wrapper": opened["environment"]}, "restatements": []} if opened["restatement_command"] else {}),
                                "proof_required": semantic_kind not in NON_PROOF_ENVIRONMENTS,
                                "label": label,
                                "statement": {
                                    "file": relative_or_absolute(path, base),
                                    "start_line": opened["start"],
                                    "end_line": line_number,
                                },
                                "statement_excerpt": truncate("\n".join(block)),
                                "proof": None,
                                "proof_redirects": [],
                                "proof_association": {
                                    "status": "unassociated",
                                    "method": "none",
                                    "target": None,
                                    "evidence_occurrence_ids": [],
                                },
                                "reference_occurrences": [],
                                "dependencies": [],
                                "candidate_internal_dependencies": [],
                                "citations": [],
                            }
                        )

                if environment in proof_environments:
                    if action == "begin":
                        proof_stack.append((environment, line_number))
                    elif proof_stack and proof_stack[-1][0] == environment:
                        proof_start = proof_stack.pop()[1]
                        block = lines[proof_start - 1 : line_number]
                        title_span = proof_optional_title_span(
                            block, proof_start
                        )
                        title = (
                            title_span.get("text")
                            if isinstance(title_span, dict)
                            else None
                        )
                        title_occurrences: list[dict[str, Any]] = []
                        title_warnings: list[str] = []
                        if title is not None:
                            title_occurrences, title_warnings = (
                                scan_reference_occurrences(
                                    title,
                                    path,
                                    base,
                                    start_line=title_span["start_line"],
                                    structural_context="proof_header",
                                )
                            )
                            warnings.extend(title_warnings)
                        evidence = scan_span_evidence(
                            path,
                            proof_start,
                            line_number,
                            base,
                        )
                        warnings.extend(evidence["warnings"])
                        title_targets = sorted(
                            {
                                row["target"]
                                for row in title_occurrences
                                if is_nonempty_string(row.get("target"))
                            }
                        )
                        for occurrence in evidence["reference_occurrences"]:
                            if occurrence_in_title(occurrence, title_span):
                                occurrence["structural_context"] = "proof_header"
                        proofs.append(
                            {
                                "file_path": path,
                                "start_line": proof_start,
                                "end_line": line_number,
                                "title": title,
                                "title_targets": title_targets,
                                "evidence": evidence,
                                "association_method": "named_environment",
                                "assigned": False,
                            }
                        )
                    else:
                        warnings.append(
                            f"Unmatched \\end{{{environment}}}: {shown(path)}:{line_number}"
                        )

        for opened in formal_stack:
            warnings.append(
                "Unclosed "
                f"\\begin{{{opened['environment']}}}: "
                f"{shown(path)}:{opened['start']}"
            )
        for environment, proof_start in proof_stack:
            warnings.append(
                f"Unclosed \\begin{{{environment}}}: {shown(path)}:{proof_start}; restore the complete proof boundary before assigning its source range"
            )

    units.sort(
        key=lambda item: (
            item["statement"]["file"],
            item["statement"]["start_line"],
        )
    )

    # Preserve existing generated identities unless there is an actual collision.
    # Relative source paths remain identical when a portable audit is relocated.
    identity_counts = Counter(unit["id"] for unit in units)
    for unit in units:
        if unit["label"] is None and identity_counts[unit["id"]] > 1:
            statement = unit["statement"]
            unit["id"] = f"{unit['environment']}:{statement['file']}:{statement['start_line']}"
    warnings.extend(inventory_identity_errors(units))
    units_by_id = {unit["id"]: unit for unit in units}
    restatement_owners: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for unit in units:
        if isinstance(unit.get("restatable"), dict):
            restatement_owners[unit["restatable"]["command"]].append(unit)
    for command, owners in restatement_owners.items():
        if len(owners) != 1:
            warnings.append(f"Restatement command \\{command} names multiple original results; reconcile the source inventory")
            continue
        for path, masked_lines in masked_source_lines.items():
            for line_number, clean in enumerate(masked_lines, 1):
                if re.fullmatch(rf"\s*\\{re.escape(command)}\*?\s*", clean):
                    owners[0]["restatements"].append({"file": relative_or_absolute(path, base), "start_line": line_number, "end_line": line_number, "sha256": source_span_sha256(path, line_number, line_number)})

    def proof_location(proof: dict[str, Any]) -> dict[str, Any]:
        return {
            "file": relative_or_absolute(proof["file_path"], base),
            "start_line": proof["start_line"],
            "end_line": proof["end_line"],
        }

    def attach_proof(
        unit: dict[str, Any],
        proof: dict[str, Any],
        *,
        method: str,
        status: str = "associated",
        evidence_occurrence_ids: Iterable[str] = (),
    ) -> None:
        evidence = proof["evidence"]
        unit["proof"] = proof_location(proof)
        unit["proof_association"] = {
            "status": status,
            "method": method,
            "target": unit["id"],
            "evidence_occurrence_ids": sorted(set(evidence_occurrence_ids)),
        }
        unit["reference_occurrences"] = [
            dict(row) for row in evidence["reference_occurrences"]
        ]
        unit["dependencies"] = list(evidence["dependencies"])
        unit["citations"] = list(evidence["citations"])
        proof["assigned"] = True

    def adjacent_unit(proof: dict[str, Any]) -> dict[str, Any] | None:
        proof_file = relative_or_absolute(proof["file_path"], base)
        candidates = [
            unit
            for unit in units
            if unit["statement"]["file"] == proof_file
            and unit.get("proof_required") is True
            and unit["statement"]["end_line"] <= proof["start_line"]
        ]
        if not candidates:
            return None
        candidate = max(candidates, key=lambda item: item["statement"]["end_line"])
        intervening = [
            other
            for other in units
            if other["statement"]["file"] == proof_file
            and candidate["statement"]["end_line"]
            < other["statement"]["start_line"]
            < proof["start_line"]
        ]
        if intervening:
            return None
        candidate_path = proof["file_path"]
        separation = masked_source_lines[candidate_path][
            candidate["statement"]["end_line"] : proof["start_line"] - 1
        ]
        if any(line.strip() for line in separation):
            return None
        return candidate

    # Add uniquely targeted manual proof headings through the same canonical
    # region analyzer used by finalization. When a named section contains one
    # unnamed explicit proof environment, retain that exact environment as the
    # proof span and use the section title only as association evidence.
    for path, lines in source_lines.items():
        headings = scan_section_headings("\n".join(lines))
        for heading in headings:
            if not re.search(r"\bproofs?\b", heading["title"], re.IGNORECASE):
                continue
            if re.fullmatch(r"\s*Proofs\s*", heading["title"], re.IGNORECASE):
                continue
            targets = [
                target
                for target in heading["target_labels"]
                if target in units_by_id
            ]
            if len(targets) != 1 or heading["target_labels"] != targets:
                warnings.append(
                    "Named proof heading does not resolve to exactly one formal "
                    f"result: {relative_or_absolute(path, base)}:"
                    f"{heading['start_line']}"
                )
                continue
            target = targets[0]
            next_heading = next(
                (
                    other
                    for other in headings
                    if other["start_line"] > heading["start_line"]
                ),
                None,
            )
            direct_body_end = (
                next_heading["start_line"] - 1
                if next_heading is not None
                else len(lines)
            )
            unnamed_environments = [
                proof
                for proof in proofs
                if proof["file_path"].resolve() == path.resolve()
                and proof.get("title") is None
                and heading["end_line"] < proof["start_line"]
                and proof["end_line"] <= direct_body_end
            ]
            if len(unnamed_environments) == 1:
                proof = unnamed_environments[0]
                heading_evidence = scan_span_evidence(
                    path,
                    heading["start_line"],
                    heading["end_line"],
                    base,
                    structural_context="proof_header",
                )
                warnings.extend(heading_evidence["warnings"])
                header_span = {
                    "start_line": heading["start_line"],
                    "start_column": heading["start_column"],
                    "end_line": heading["end_line"],
                    "end_column": heading["end_column"],
                }
                proof["title"] = heading["title"]
                proof["title_targets"] = [target]
                proof["association_method"] = "named_heading"
                proof["association_evidence_occurrence_ids"] = sorted(
                    occurrence["occurrence_id"]
                    for occurrence in heading_evidence["reference_occurrences"]
                    if occurrence.get("target") == target
                    and occurrence_in_title(occurrence, header_span)
                )
                continue
            region = analyze_proof_region(
                path,
                heading["start_line"],
                target_unit_id=target,
                source_files=source_lines,
            )
            if region.get("status") != "accepted":
                warnings.append(
                    "Named proof heading has no canonical complete boundary: "
                    f"{relative_or_absolute(path, base)}:"
                    f"{heading['start_line']} ({region.get('reason')})"
                )
                continue
            if any(
                proof["file_path"].resolve() == path.resolve()
                and region["start_line"] <= proof["start_line"] <= region["end_line"]
                for proof in proofs
            ):
                continue
            evidence = scan_span_evidence(
                path,
                region["start_line"],
                region["end_line"],
                base,
            )
            warnings.extend(evidence["warnings"])
            header_span = region.get("header_span")
            for occurrence in evidence["reference_occurrences"]:
                if occurrence_in_title(occurrence, header_span):
                    occurrence["structural_context"] = "proof_header"
            proofs.append(
                {
                    "file_path": path,
                    "start_line": region["start_line"],
                    "end_line": region["end_line"],
                    "title": heading["title"],
                    "title_targets": [target],
                    "evidence": evidence,
                    "association_method": "named_heading",
                    "assigned": False,
                }
            )

    ordered_proofs = sorted(
        proofs, key=lambda item: (str(item["file_path"]), item["start_line"])
    )

    # Explicit proof titles take precedence over physical adjacency.
    for proof in ordered_proofs:
        if proof.get("title") is None:
            continue
        targets = sorted(
            {
                target
                for target in proof.get("title_targets", [])
                if target in units_by_id
            }
        )
        proof_file = relative_or_absolute(proof["file_path"], base)
        if len(targets) != 1:
            warnings.append(
                "Named proof header does not resolve to exactly one formal result: "
                f"{proof_file}:{proof['start_line']}"
            )
            continue
        unit = units_by_id[targets[0]]
        if unit.get("proof") is not None:
            warnings.append(
                f"Multiple named proofs target {unit['id']}: "
                f"{proof_file}:{proof['start_line']}"
            )
            continue
        evidence_ids = proof.get("association_evidence_occurrence_ids")
        if not isinstance(evidence_ids, list):
            evidence_ids = [
                row["occurrence_id"]
                for row in proof["evidence"]["reference_occurrences"]
                if row.get("target") == unit["id"]
                and row.get("structural_context") == "proof_header"
            ]
        attach_proof(
            unit,
            proof,
            method=proof.get("association_method", "named_environment"),
            evidence_occurrence_ids=evidence_ids,
        )

    # A generated restatement is an alias of the original result, not a new
    # obligation. Its immediately following proof can supply the original.
    for proof in ordered_proofs:
        if proof.get("assigned") or proof.get("title") is not None:
            continue
        proof_file = relative_or_absolute(proof["file_path"], base)
        candidates = [unit for unit in units for restatement in unit.get("restatements", [])
                      if restatement["file"] == proof_file and restatement["end_line"] < proof["start_line"]
                      and not any(line.strip() for line in masked_source_lines[proof["file_path"]][restatement["end_line"]:proof["start_line"] - 1])]
        if len(candidates) == 1 and candidates[0].get("proof") is None:
            attach_proof(candidates[0], proof, method="restatement_adjacency")

    # Recognize only strict navigation-only forwarding proofs.
    for proof in ordered_proofs:
        if proof.get("assigned") or proof.get("title") is not None:
            continue
        unit = adjacent_unit(proof)
        if unit is None:
            continue
        evidence = proof["evidence"]
        occurrences = evidence["reference_occurrences"]
        hyper_occurrences = [
            row for row in occurrences if row.get("command") == "hyperref"
        ]
        result_targets = {
            row["target"]
            for row in occurrences
            if row.get("target") in units_by_id
        }
        block = masked_source_lines[proof["file_path"]][
            proof["start_line"] - 1 : proof["end_line"]
        ]
        compact = " ".join(
            line.strip()
            for line in block[1:-1]
            if line.strip()
        )
        has_math_signal = bool(
            re.search(
                r"\$|\\\(|\\\[|\\begin\s*\{(?:align|equation|gather|multline)",
                compact,
            )
            or "=" in compact
        )
        strict_redirect = (
            len({row["target"] for row in hyper_occurrences}) == 1
            and result_targets == {unit["id"]}
            and not evidence["citations"]
            and bool(re.match(r"^\s*See\b", compact, re.IGNORECASE))
            and not has_math_signal
        )
        if not strict_redirect:
            continue
        anchor = hyper_occurrences[0]["target"]
        anchors = label_occurrences.get(anchor, [])
        if len(anchors) != 1:
            warnings.append(
                f"Forwarding proof target {anchor} is missing or nonunique for "
                f"{unit['id']}"
            )
            continue
        anchor_path = resolve_stored_path(anchors[0]["file"], base)
        region = bounded_proof_region(anchor_path, anchors[0]["line"])
        if region is None:
            warnings.append(
                f"Forwarding proof target {anchor} has no uniquely bounded proof "
                f"region for {unit['id']}"
            )
            continue
        conflicting_named = [
            other
            for other in ordered_proofs
            if other["file_path"].resolve() == anchor_path.resolve()
            and region["start_line"] <= other["start_line"] <= region["end_line"]
            and any(
                target != unit["id"] and target in units_by_id
                for target in other.get("title_targets", [])
            )
        ]
        if conflicting_named:
            warnings.append(
                f"Forwarding proof target {anchor} encloses a named proof for "
                f"another result"
            )
            continue
        redirect = {
            **proof_location(proof),
            "target_anchor": anchor,
            "occurrence_id": hyper_occurrences[0]["occurrence_id"],
        }
        unit["proof_redirects"].append(redirect)
        proof["assigned"] = True
        if unit.get("proof") is None:
            redirected_proof = {
                "file_path": anchor_path,
                "start_line": region["start_line"],
                "end_line": region["end_line"],
                "evidence": scan_span_evidence(
                    anchor_path,
                    region["start_line"],
                    region["end_line"],
                    base,
                ),
                "assigned": False,
            }
            warnings.extend(redirected_proof["evidence"]["warnings"])
            attach_proof(
                unit,
                redirected_proof,
                method="redirect_anchor",
                status="review_required",
                evidence_occurrence_ids=[
                    hyper_occurrences[0]["occurrence_id"]
                ],
            )
            warnings.append(
                f"Redirected proof association requires rendered-source review: "
                f"{unit['id']} -> {anchor}"
            )

    # Remaining proof environments use conservative physical adjacency.
    for proof in ordered_proofs:
        if proof.get("assigned") or proof.get("title") is not None:
            continue
        proof_file = relative_or_absolute(proof["file_path"], base)
        unit = adjacent_unit(proof)
        if unit is None:
            warnings.append(
                f"Proof could not be associated with a formal statement: "
                f"{proof_file}:{proof['start_line']}"
            )
            continue
        if unit.get("proof") is not None:
            warnings.append(
                f"Additional proof could not be associated uniquely with {unit['id']}: "
                f"{proof_file}:{proof['start_line']}"
            )
            continue
        attach_proof(unit, proof, method="adjacent_environment")

    label_owners: dict[str, dict[str, Any]] = {}
    for target, locations in sorted(label_occurrences.items()):
        if len(locations) != 1:
            label_owners[target] = {
                "status": "duplicate",
                "owner_unit_id": None,
                "owner_region": None,
                "locations": locations,
            }
            continue
        row = locations[0]
        owners: list[tuple[str, str]] = []
        for unit in units:
            for region_name in ("statement", "proof"):
                span = unit.get(region_name)
                if span_contains_location(span, row["file"], row["line"], base):
                    owners.append((unit["id"], region_name))
        unique_owners = sorted(set(owners))
        if len(unique_owners) == 1:
            owner_unit_id, owner_region = unique_owners[0]
            status = "unique"
        elif unique_owners:
            owner_unit_id, owner_region, status = None, None, "ambiguous"
        else:
            owner_unit_id, owner_region, status = None, None, "unowned"
        label_owners[target] = {
            "status": status,
            "owner_unit_id": owner_unit_id,
            "owner_region": owner_region,
            "locations": locations,
        }

    support_index = build_unowned_label_support_index(
        source_lines, units, label_owners, base
    )
    for unit in units:
        statement_evidence = scan_unit_statement_evidence(unit, base)
        warnings.extend(statement_evidence["warnings"])
        for occurrence in unit["reference_occurrences"]:
            owner = label_owners.get(occurrence["target"])
            if owner is None:
                occurrence["resolution_status"] = "missing"
            else:
                occurrence["resolution_status"] = owner["status"]
                occurrence["owner_unit_id"] = owner["owner_unit_id"]
                occurrence["owner_region"] = owner["owner_region"]
        unit["candidate_internal_dependencies"] = (
            resolve_candidate_internal_dependencies(
                unit["id"],
                [
                    *statement_evidence["reference_occurrences"],
                    *unit["reference_occurrences"],
                ],
                label_owners,
                support_index,
            )
        )

    for unit in units:
        if (
            unit.get("proof_required") is True
            and unit.get("proof") is None
        ):
            statement = unit["statement"]
            warnings.append(
                f"Proof-required result has no associated proof: {unit['id']} at "
                f"{statement['file']}:{statement['start_line']}"
            )

    return {
        "schema_version": SCHEMA_VERSION,
        "root_file": source_path_identity(root, path_identity_base),
        "files": [relative_or_absolute(path, base) for path in files],
        "formal_environments": sorted(environments),
        "units": units,
        "label_owners": label_owners,
        "warnings": warnings,
    }


def scan_cross_references(
    root: Path,
    *,
    source_files: Iterable[Path] | None = None,
    source_warnings: Iterable[str] | None = None,
    path_identity_base: Path | None = None,
) -> dict[str, Any]:
    if source_files is None:
        files, warnings = collect_tex_files(
            root, warning_path_base=path_identity_base
        )
    else:
        files, warnings = list(source_files), list(source_warnings or [])
    base = root.resolve().parent
    path_identity_base = (
        path_identity_base.resolve() if path_identity_base is not None else None
    )
    labels: dict[str, list[dict[str, Any]]] = defaultdict(list)
    references: dict[str, list[dict[str, Any]]] = defaultdict(list)
    occurrences: list[dict[str, Any]] = []

    source_lines = readable_source_lines(files, warnings, path_identity_base)
    for path, lines in source_lines.items():
        text = "\n".join(lines)
        mask_structural_tex(
            text,
            warnings=warnings,
            source_name=source_path_identity(path, path_identity_base),
        )
        for row in scan_label_occurrences(text, path, base):
            labels[row["target"]].append(
                {
                    "file": row["file"],
                    "line": row["line"],
                    "column": row["column"],
                }
            )
        file_occurrences, file_warnings = scan_reference_occurrences(
            text, path, base
        )
        warnings.extend(file_warnings)
        for row in file_occurrences:
            occurrences.append(row)
            references[row["target"]].append(
                {
                    "file": row["file"],
                    "line": row["line"],
                    "column": row["column"],
                    "command": row["command"],
                    "occurrence_id": row["occurrence_id"],
                }
            )

    label_keys = set(labels)
    reference_keys = set(references)
    return {
        "schema_version": SCHEMA_VERSION,
        "root_file": source_path_identity(root, path_identity_base),
        "files": [relative_or_absolute(path, base) for path in files],
        "counts": {
            "unique_labels": len(label_keys),
            "unique_references": len(reference_keys),
            "broken_references": len(reference_keys - label_keys),
            "orphan_labels": len(label_keys - reference_keys),
            "duplicate_labels": sum(1 for value in labels.values() if len(value) > 1),
        },
        "broken_references": {
            key: references[key] for key in sorted(reference_keys - label_keys)
        },
        "orphan_labels": {
            key: labels[key] for key in sorted(label_keys - reference_keys)
        },
        "duplicate_labels": {
            key: value for key, value in sorted(labels.items()) if len(value) > 1
        },
        "labels": dict(sorted(labels.items())),
        "references": dict(sorted(references.items())),
        "occurrences": occurrences,
        "warnings": warnings,
    }


def cross_reference_anomalies(data: dict[str, Any]) -> list[dict[str, Any]]:
    """Return the exact parser-detected anomalies that require human review."""
    anomalies: list[dict[str, Any]] = []
    for kind, field in (
        ("broken_reference", "broken_references"),
        ("duplicate_label", "duplicate_labels"),
    ):
        records = data.get(field)
        if not isinstance(records, dict):
            continue
        for key, locations in sorted(records.items()):
            anomalies.append(
                {
                    "kind": kind,
                    "key": key,
                    "locations": locations if isinstance(locations, list) else [],
                }
            )
    return anomalies


def validate_cross_reference_reviews(
    value: Any,
    cross_references: dict[str, Any],
    in_scope: list[str],
    errors: list[str],
) -> dict[str, Any]:
    expected = {
        (row["kind"], row["key"]): row
        for row in cross_reference_anomalies(cross_references)
    }
    if not isinstance(value, list):
        errors.append("manifest.cross_reference_reviews must be a list")
        value = []
    seen: set[tuple[str, str]] = set()
    issue_ids: set[str] = set()
    affected_units: set[str] = set()
    statuses: list[str] = []
    for index, review in enumerate(value, 1):
        prefix = f"cross_reference_reviews[{index}]"
        if not isinstance(review, dict):
            errors.append(f"{prefix} must be an object")
            continue
        kind = review.get("kind")
        key = review.get("key")
        identity = (kind, key)
        if not is_nonempty_string(kind) or not is_nonempty_string(key):
            errors.append(f"{prefix}.kind and .key must be nonempty strings")
            continue
        if identity in seen:
            errors.append(f"Duplicate cross-reference review: {kind}/{key}")
        seen.add(identity)
        expected_row = expected.get(identity)
        if expected_row is None:
            errors.append(f"{prefix}: stale cross-reference anomaly review")
        elif review.get("locations") != expected_row.get("locations"):
            errors.append(f"{prefix}.locations do not match the current anomaly")
        status = review.get("status")
        if not is_enum_value(status, CROSS_REFERENCE_REVIEW_STATUSES):
            errors.append(f"{prefix}.status is invalid")
        else:
            statuses.append(status)
        if not is_substantive_string(review.get("evidence")):
            errors.append(f"{prefix}.evidence must be nonempty and substantive")
        affected = review.get("affected_units")
        if not isinstance(affected, list) or not all(
            is_nonempty_string(item) for item in affected
        ):
            errors.append(f"{prefix}.affected_units must be a string list")
            affected = []
        elif len(affected) != len(set(affected)):
            errors.append(f"{prefix}.affected_units contains duplicates")
        unknown = set(affected) - set(in_scope)
        if unknown:
            errors.append(
                f"{prefix}.affected_units names results outside scope: "
                + ", ".join(sorted(unknown))
            )
        row_issues = validate_issue_id_list(
            review.get("issue_ids"), f"{prefix}.issue_ids", errors
        )
        issue_ids.update(row_issues)
        if is_enum_value(status, {"defect", "inconclusive"}):
            affected_units.update(affected)
        if status == "passed" and (affected or row_issues):
            errors.append(f"{prefix}: a passed anomaly review must be clean")
        if is_enum_value(status, {"defect", "inconclusive"}) and not row_issues:
            errors.append(f"{prefix}: {status} requires canonical issue_ids")
    missing = set(expected) - seen
    if missing:
        errors.append(
            "manifest.cross_reference_reviews is missing current anomalies: "
            + ", ".join(f"{kind}/{key}" for kind, key in sorted(missing))
        )
    return {
        "defect": "defect" in statuses,
        "inconclusive": "inconclusive" in statuses,
        "issue_ids": issue_ids,
        "affected_units": affected_units,
    }


def markdown_inline_text(value: Any) -> str:
    """Normalize generated Markdown free text to one physical line."""
    return "".join(
        (
            " "
            if unicodedata.category(character) in {"Cc", "Zl", "Zp"}
            else (
                "\uFFFD"
                if unicodedata.category(character) == "Cs"
                else character
            )
        )
        for character in str(value)
    )


def escape_markdown(value: Any) -> str:
    return markdown_inline_text(value).replace("|", "\\|")


def escape_markdown_heading(value: Any) -> str:
    """Render heading text without creating active raw HTML."""
    return (
        markdown_inline_text(value)
        .replace("&", "&amp;")
        .replace("<", "&lt;")
        .replace(">", "&gt;")
    )


def index_markdown(data: dict[str, Any]) -> str:
    rows = [
        "# Formal Proof-Unit Inventory",
        "",
        "| ID | Type | Proof required | Statement | Proof | Direct references | Citations |",
        "|---|---|---|---|---|---|---|",
    ]
    for unit in data["units"]:
        statement = unit["statement"]
        statement_location = (
            f"{statement['file']}:{statement['start_line']}-{statement['end_line']}"
        )
        if unit["proof"]:
            proof = unit["proof"]
            proof_location = f"{proof['file']}:{proof['start_line']}-{proof['end_line']}"
        else:
            proof_location = "not associated"
        rows.append(
            "| "
            + " | ".join(
                escape_markdown(value)
                for value in (
                    unit["id"],
                    unit["environment"],
                    unit.get("proof_required"),
                    statement_location,
                    proof_location,
                    ", ".join(unit["dependencies"]) or "none found",
                    ", ".join(unit.get("citations", [])) or "none found",
                )
            )
            + " |"
        )
    rows.extend(["", f"**Units found:** {len(data['units'])}", ""])
    if data["warnings"]:
        rows.extend(["## Parser warnings", ""])
        rows.extend(f"- {escape_markdown(warning)}" for warning in data["warnings"])
        rows.append("")
    return "\n".join(rows)


def locations_text(values: Iterable[dict[str, Any]]) -> str:
    return ", ".join(f"{item['file']}:{item['line']}" for item in values)


def crossref_markdown(data: dict[str, Any]) -> str:
    rows = ["# Cross-Reference Audit", ""]
    sections = (
        ("Broken references", "broken_references"),
        ("Duplicate labels", "duplicate_labels"),
        ("Orphan labels", "orphan_labels"),
    )
    for title, key in sections:
        rows.extend([f"## {title}", "", "| Key | Locations |", "|---|---|"])
        values = data[key]
        if values:
            rows.extend(
                f"| {escape_markdown(name)} | {escape_markdown(locations_text(items))} |"
                for name, items in values.items()
            )
        else:
            rows.append("| None | None found |")
        rows.append("")
    rows.extend(["## Counts", "", "| Metric | Count |", "|---|---|"])
    rows.extend(
        f"| {escape_markdown(name)} | {value} |"
        for name, value in data["counts"].items()
    )
    rows.append("")
    if data["warnings"]:
        rows.extend(["## Parser warnings", ""])
        rows.extend(f"- {escape_markdown(warning)}" for warning in data["warnings"])
        rows.append("")
    return "\n".join(rows)


def workflow_id_list(value: Any) -> str:
    if not isinstance(value, list):
        return "none"
    values = [str(item) for item in value if is_nonempty_string(item)]
    return ", ".join(values) if values else "none"


def workflow_location(value: Any) -> str:
    if not isinstance(value, dict):
        return "none"
    file_value = value.get("file")
    start = value.get("start_line")
    end = value.get("end_line")
    if not is_nonempty_string(file_value) or not is_int(start) or not is_int(end):
        return "invalid"
    shown = str(file_value).replace("\\", "/")
    return f"{shown}:{start}" if start == end else f"{shown}:{start}-{end}"


def workflow_unit_status(unit_id: str, progress: dict[str, Any]) -> str:
    blocked = progress.get("blocked_units")
    if isinstance(blocked, dict) and unit_id in blocked:
        return "blocked"
    for field, status in (
        ("completed_units", "completed"),
        ("conditional_units", "conditional"),
        ("in_progress_units", "in_progress"),
        ("not_started_units", "not_started"),
    ):
        values = progress.get(field)
        if isinstance(values, list) and unit_id in values:
            return status
    if progress.get("active_unit") == unit_id:
        return "active"
    return "unclassified"


def workflow_registry_rows(registry: dict[str, Any]) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    internal = registry.get("internal_uses")
    if not isinstance(internal, list):
        raise ValueError(
            "Cannot render workflow views: dependency registry internal_uses "
            "must be a list"
        )
    for index, value in enumerate(internal, 1):
            if not isinstance(value, dict):
                raise ValueError(
                    f"Cannot render workflow views: internal_uses[{index}] must be an object"
                )
            if not is_nonempty_string(value.get("dependent_unit")) or not is_nonempty_string(
                value.get("dependency_id")
            ):
                raise ValueError(
                    "Cannot render workflow views: "
                    f"internal_uses[{index}] dependent_unit and dependency_id "
                    "must be nonempty strings"
                )
            rows.append(
                {
                    "use_id": value.get("use_id"),
                    "prerequisite": value.get("dependency_id"),
                    "conclusion": value.get("dependency_conclusion_id"),
                    "dependent": value.get("dependent_unit"),
                    "status": value.get("status"),
                    "issue_ids": value.get("issue_ids"),
                    "kind": "internal_result",
                }
            )
    external = registry.get("external_results")
    if not isinstance(external, list):
        raise ValueError(
            "Cannot render workflow views: dependency registry external_results "
            "must be a list"
        )
    for result_index, result in enumerate(external, 1):
            if not isinstance(result, dict):
                raise ValueError(
                    "Cannot render workflow views: "
                    f"external_results[{result_index}] must be an object"
                )
            result_id = result.get("id")
            uses = result.get("uses")
            if not isinstance(uses, list):
                raise ValueError(
                    "Cannot render workflow views: "
                    f"external_results[{result_index}].uses must be a list"
                )
            for use_index, value in enumerate(uses, 1):
                if not isinstance(value, dict):
                    raise ValueError(
                        "Cannot render workflow views: "
                        f"external_results[{result_index}].uses[{use_index}] "
                        "must be an object"
                    )
                if not is_nonempty_string(result_id) or not is_nonempty_string(
                    value.get("dependent_unit")
                ):
                    raise ValueError(
                        "Cannot render workflow views: external dependency result IDs "
                        "and dependent_unit values must be nonempty strings"
                    )
                rows.append(
                    {
                        "use_id": value.get("use_id"),
                        "prerequisite": result_id,
                        "conclusion": value.get("dependency_conclusion")
                        or result.get("exact_statement"),
                        "dependent": value.get("dependent_unit"),
                        "status": value.get("status"),
                        "issue_ids": value.get("issue_ids"),
                        "kind": "external_result",
                    }
                )
    return sorted(
        rows,
        key=lambda row: (
            str(row.get("dependent", "")),
            str(row.get("use_id", "")),
            str(row.get("prerequisite", "")),
        ),
    )


def workflow_topological_layers(
    unit_ids: Iterable[str], rows: list[dict[str, Any]]
) -> tuple[list[list[str]], bool]:
    nodes = sorted(set(unit_ids))
    node_set = set(nodes)
    prerequisites: dict[str, set[str]] = {unit_id: set() for unit_id in nodes}
    for row in rows:
        if row.get("kind") != "internal_result":
            continue
        dependent = row.get("dependent")
        prerequisite = row.get("prerequisite")
        if not is_nonempty_string(dependent) or not is_nonempty_string(prerequisite):
            raise ValueError(
                "Cannot render workflow views: internal dependency endpoints must "
                "be nonempty strings"
            )
        if dependent in node_set and prerequisite in node_set:
            prerequisites[str(dependent)].add(str(prerequisite))
    remaining = set(nodes)
    completed: set[str] = set()
    layers: list[list[str]] = []
    while remaining:
        ready = sorted(
            unit_id
            for unit_id in remaining
            if prerequisites[unit_id].issubset(completed)
        )
        if not ready:
            layers.append(sorted(remaining))
            return layers, True
        layers.append(ready)
        completed.update(ready)
        remaining.difference_update(ready)
    return layers, False


def load_workflow_records(root: Path) -> dict[str, Any]:
    root = root.resolve()
    errors = audit_internal_redirect_errors(root)
    _, manifest, manifest_errors = load_audit_manifest(root)
    errors.extend(manifest_errors)
    if manifest_errors:
        raise ValueError("Cannot load workflow views: " + "; ".join(errors))

    records: dict[str, Any] = {"manifest": manifest, "root": root}
    for field, label, key in (
        ("inventory_file", "proof-unit inventory", "inventory"),
        ("dependency_registry", "dependency registry", "dependency_registry"),
        (
            "method_interface_registry",
            "method-interface registry",
            "interface_registry",
        ),
    ):
        path, valid = manifest_canonical_artifact_path(
            manifest, root, field, label, errors
        )
        if not valid:
            continue
        value, read_errors = load_json_object(path, label)
        errors.extend(read_errors)
        if not read_errors:
            records[key] = value
            records[f"{key}_path"] = path

    progress_path, progress_valid = canonical_artifact_path(
        root, "PROGRESS.json", "progress record", errors
    )
    if progress_valid:
        progress, progress_errors = load_json_object(
            progress_path, "progress record"
        )
        errors.extend(progress_errors)
        if not progress_errors:
            records["progress"] = progress
    _, issues, _, issue_errors = load_issue_log(root)
    errors.extend(issue_errors)
    if not issue_errors:
        seen_issue_ids: set[str] = set()
        for index, issue in enumerate(issues, 1):
            prefix = f"Issue record {index}"
            if not isinstance(issue, dict):
                errors.append(f"{prefix} must be an object")
                continue
            issue_id = issue.get("id")
            if not isinstance(issue_id, str) or not ISSUE_ID_RE.fullmatch(issue_id):
                errors.append(f"{prefix} has an invalid ID")
                continue
            if issue_id in seen_issue_ids:
                errors.append(f"Duplicate issue ID {issue_id}")
            seen_issue_ids.add(issue_id)
            if issue.get("severity") not in ISSUE_SEVERITIES:
                errors.append(f"{issue_id} has invalid severity")
            if issue.get("status") not in ISSUE_STATUSES:
                errors.append(f"{issue_id} has invalid status")
            if not isinstance(issue.get("load_bearing"), bool):
                errors.append(f"{issue_id}.load_bearing must be boolean")
            affected = issue.get("affected_results")
            if not isinstance(affected, list) or not affected or not all(
                is_nonempty_string(value) for value in affected
            ):
                errors.append(f"{issue_id}.affected_results is invalid")
            historical = issue.get("historical_origin")
            if isinstance(historical, dict):
                required = historical.get("required_challenges", [])
                if not isinstance(required, list) or not all(
                    is_nonempty_string(value) for value in required
                ):
                    errors.append(
                        f"{issue_id}.historical_origin.required_challenges is invalid"
                    )
        records["issues"] = issues
    if errors:
        raise ValueError("Cannot load workflow views: " + "; ".join(errors))
    return records


def workflow_priority_sets(
    records: dict[str, Any]
) -> tuple[set[str], set[str], set[str]]:
    manifest = records["manifest"]
    scope = manifest.get("audit_scope")
    scope = scope if isinstance(scope, dict) else {}
    declared = {
        str(value)
        for value in scope.get("critical_units", [])
        if is_nonempty_string(value)
    }
    _, severe_by_unit = required_challenge_requirements(
        manifest, records.get("issues", [])
    )
    issue_promoted = set(severe_by_unit)
    return declared, issue_promoted - declared, declared | issue_promoted


def workflow_dependency_mapping_readiness(
    records: dict[str, Any]
) -> tuple[bool, list[str]]:
    manifest = records["manifest"]
    registry = records["dependency_registry"]
    inventory_path = records.get("inventory_path")
    scope = manifest.get("audit_scope")
    scope = scope if isinstance(scope, dict) else {}
    in_scope = [
        str(value)
        for value in scope.get("in_scope_units", [])
        if is_nonempty_string(value)
    ]
    snapshot = manifest.get("source_snapshot")
    snapshot_id = snapshot.get("sha256") if isinstance(snapshot, dict) else None
    errors: list[str] = []
    validate_dependency_registry_review(
        registry,
        source_snapshot_sha256=snapshot_id,
        inventory_sha256=(
            sha256_file(inventory_path)
            if isinstance(inventory_path, Path) and inventory_path.is_file()
            else ""
        ),
        in_scope=in_scope,
        errors=errors,
    )
    root = records.get("root")
    if isinstance(root, Path):
        errors.extend(packet_dependency_structure_errors(registry, root))
    else:
        errors.append("Workflow records do not identify the canonical audit root")

    in_scope_set = set(in_scope)
    internal_rows = registry.get("internal_uses")
    if isinstance(internal_rows, list):
        for index, row in enumerate(internal_rows, 1):
            if not isinstance(row, dict):
                continue
            for field in ("dependent_unit", "dependency_id"):
                endpoint = row.get(field)
                if (
                    is_nonempty_string(endpoint)
                    and endpoint not in in_scope_set
                ):
                    errors.append(
                        f"internal_uses[{index}].{field} must name an in-scope unit"
                    )
    external_results = registry.get("external_results")
    if isinstance(external_results, list):
        for result_index, result in enumerate(external_results, 1):
            if not isinstance(result, dict):
                continue
            uses = result.get("uses")
            if not isinstance(uses, list):
                continue
            for use_index, row in enumerate(uses, 1):
                if not isinstance(row, dict):
                    continue
                dependent = row.get("dependent_unit")
                if (
                    is_nonempty_string(dependent)
                    and dependent not in in_scope_set
                ):
                    errors.append(
                        "external_results"
                        f"[{result_index}].uses[{use_index}].dependent must name "
                        "an in-scope unit"
                    )
    return not errors, errors


@gate_context_reader
def packet_dependency_structure_errors(
    registry: dict[str, Any], root: Path
) -> list[str]:
    errors: list[str] = []
    final_primary_by_unit: dict[str, bool] = {}

    def allow_preliminary_step_ids(row: Any) -> bool:
        if not isinstance(row, dict) or not is_nonempty_string(
            row.get("dependent_unit")
        ):
            return False
        unit_id = str(row["dependent_unit"])
        if unit_id not in final_primary_by_unit:
            ledger_path, _ = packet_ledger(root, unit_id)
            if ledger_path is None:
                final_primary_by_unit[unit_id] = False
            else:
                ledger_errors, _ = check_ledger_data(
                    ledger_path, True, primary_only=True
                )
                final_primary_by_unit[unit_id] = not ledger_errors
        return not final_primary_by_unit[unit_id]

    internal_rows = registry.get("internal_uses")
    if not isinstance(internal_rows, list):
        return ["Dependency registry internal_uses must be a list"]
    for index, row in enumerate(internal_rows, 1):
        prefix = f"internal_uses[{index}]"
        validated = validate_dependency_use_identity(
            row,
            prefix,
            None,
            errors,
            allow_preliminary_step_ids=allow_preliminary_step_ids(row),
        )
        validate_compatibility_matrix(
            validated.get("compatibility_checks"),
            f"{prefix}.compatibility_checks",
            errors,
        )
        validate_issue_id_list(
            validated.get("issue_ids"), f"{prefix}.issue_ids", errors
        )
        if "use_site" in validated:
            validate_locked_span(
                validated.get("use_site"), root, f"{prefix}.use_site", errors
            )

    external_results, contract_hashes = validate_external_result_catalog(
        registry, root, errors
    )
    for result_id, result in external_results.items():
        uses = result.get("uses")
        if not isinstance(uses, list):
            errors.append(f"{result_id}.uses must be a list")
            continue
        for index, row in enumerate(uses, 1):
            prefix = f"{result_id}.uses[{index}]"
            validated = validate_dependency_use_identity(
                row,
                prefix,
                None,
                errors,
                allow_preliminary_step_ids=allow_preliminary_step_ids(row),
            )
            if validated.get("dependency_id") != result_id:
                errors.append(f"{prefix}.dependency_id must equal {result_id}")
            if validated.get("dependency_conclusion") != result.get("exact_statement"):
                errors.append(f"{prefix}.dependency_conclusion is stale or incorrect")
            if validated.get("dependency_contract_sha256") != contract_hashes.get(
                result_id
            ):
                errors.append(
                    f"{prefix}.dependency_contract_sha256 is stale or incorrect"
                )
            validate_compatibility_matrix(
                validated.get("compatibility_checks"),
                f"{prefix}.compatibility_checks",
                errors,
            )
            validate_prerequisite_map(
                validated.get("prerequisite_map"),
                root,
                f"{prefix}.prerequisite_map",
                errors,
            )
            validate_issue_id_list(
                validated.get("issue_ids"), f"{prefix}.issue_ids", errors
            )
            validate_string_list(
                validated.get("citation_keys"),
                f"{prefix}.citation_keys",
                errors,
                allow_empty=True,
            )
            if "use_site" in validated:
                validate_locked_span(
                    validated.get("use_site"), root, f"{prefix}.use_site", errors
                )
    return errors


def render_check_plan(records: dict[str, Any]) -> str:
    manifest = records["manifest"]
    inventory = records["inventory"]
    registry = records["dependency_registry"]
    interface_registry = records["interface_registry"]
    progress = records["progress"]
    scope = manifest.get("audit_scope")
    scope = scope if isinstance(scope, dict) else {}
    units = inventory.get("units")
    units = units if isinstance(units, list) else []
    dependency_rows = workflow_registry_rows(registry)
    direct_dependencies: dict[str, set[str]] = defaultdict(set)
    use_sites: dict[str, set[str]] = defaultdict(set)
    for row in dependency_rows:
        dependent = row.get("dependent")
        prerequisite = row.get("prerequisite")
        if is_nonempty_string(dependent) and is_nonempty_string(prerequisite):
            direct_dependencies[str(dependent)].add(str(prerequisite))
            use_sites[str(prerequisite)].add(str(dependent))
    declared_priority, promoted_priority, priority_units = workflow_priority_sets(
        records
    )
    exclusions = [
        row.get("id")
        for row in scope.get("excluded_units", [])
        if isinstance(row, dict)
    ]
    snapshot = manifest.get("source_snapshot")
    snapshot_id = snapshot.get("sha256") if isinstance(snapshot, dict) else None
    rows = [
        "# Proof-Check Plan",
        "",
        "> **GENERATED VIEW:** Run",
        "> `python \"<skill-root>/scripts/proofcheck.py\" sync-views --root <audit-root>`.",
        "> Do not edit this file or use it as canonical evidence.",
        "",
        "## Scope",
        "",
        f"- Source snapshot: {snapshot_id or 'not_set'}",
        f"- Audit depth: {scope.get('depth', 'not_set')}",
        f"- Target results: {workflow_id_list(scope.get('target_units'))}",
        f"- In-scope units: {workflow_id_list(scope.get('in_scope_units'))}",
        f"- Declared priority units: {workflow_id_list(sorted(declared_priority))}",
        f"- Issue-promoted priority units: {workflow_id_list(sorted(promoted_priority))}",
        f"- Combined priority units: {workflow_id_list(sorted(priority_units))}",
        f"- Explicit exclusions: {workflow_id_list(exclusions)}",
        f"- Source or parser limitations: {workflow_id_list(scope.get('source_or_parser_limits'))}",
        f"- Overall assessment: {scope.get('overall_assessment', 'not_set')}",
        "",
        "## Proof-unit inventory",
        "",
        "| Unit | Statement | Proof | Dependencies | Use sites | Priority basis | Status |",
        "|---|---|---|---|---|---|---|",
    ]
    for unit in sorted(
        (value for value in units if isinstance(value, dict)),
        key=lambda value: str(value.get("id", "")),
    ):
        unit_id = str(unit.get("id", ""))
        values = (
            unit_id,
            workflow_location(unit.get("statement")),
            workflow_location(unit.get("proof")),
            workflow_id_list(sorted(direct_dependencies.get(unit_id, set()))),
            workflow_id_list(sorted(use_sites.get(unit_id, set()))),
            (
                "declared"
                if unit_id in declared_priority
                else "issue_promoted"
                if unit_id in promoted_priority
                else "no"
            ),
            workflow_unit_status(unit_id, progress),
        )
        rows.append(
            "| " + " | ".join(escape_markdown(value) for value in values) + " |"
        )
    if not units:
        rows.append("| none | none | none | none | none | no | unclassified |")
    rows.extend(
        [
            "",
            "## Reviewed exceptions",
            "",
            "| Kind | Unit or key | Canonical disposition | Evidence or limitation |",
            "|---|---|---|---|",
        ]
    )
    exceptions: list[tuple[str, str, str, str]] = []
    for value in scope.get("excluded_units", []):
        if isinstance(value, dict):
            exceptions.append(
                (
                    "excluded_unit",
                    str(value.get("id", "")),
                    "excluded",
                    str(value.get("reason", "")),
                )
            )
    for value in scope.get("inventory_overrides", []):
        if isinstance(value, dict):
            exceptions.append(
                (
                    "inventory_override",
                    str(value.get("unit_id", "")),
                    str(value.get("kind", "")),
                    str(value.get("reason", "")),
                )
            )
    for index, value in enumerate(scope.get("source_or_parser_limits", []), 1):
        if is_nonempty_string(value):
            exceptions.append(("source_limit", f"L{index:03d}", "declared", value))
    if exceptions:
        for value in sorted(exceptions):
            rows.append(
                "| " + " | ".join(escape_markdown(item) for item in value) + " |"
            )
    else:
        rows.append("| none | none | none | none |")
    interface_scope = interface_registry.get("scope")
    interface_scope = interface_scope if isinstance(interface_scope, dict) else {}
    rows.extend(
        [
            "",
            "## Method-interface scope",
            "",
            f"- Trigger decision: {interface_scope.get('trigger', 'not_set')}",
            f"- In-scope interfaces: {workflow_id_list(scope.get('in_scope_interfaces'))}",
            "",
            "## Progress",
            "",
            f"- Current pass: {progress.get('current_pass', 'unknown')}",
            f"- Active unit: {progress.get('active_unit') or 'none'}",
            f"- Completed units: {workflow_id_list(progress.get('completed_units'))}",
            f"- Conditional units: {workflow_id_list(progress.get('conditional_units'))}",
            f"- Not-started units: {workflow_id_list(progress.get('not_started_units'))}",
            f"- Open high-priority issues: {workflow_id_list(progress.get('open_high_priority_issues'))}",
            f"- Next action: {progress.get('next_action') or 'not_set'}",
            "",
            "All detailed obligations, dependency uses, compatibility matrices, global",
            "checks, issue definitions, challenges, and completion gates remain canonical in",
            "JSON and are validated by `proofcheck.py`. They are intentionally not copied",
            "into this view.",
            "",
        ]
    )
    return "\n".join(rows)


def render_execution_order(records: dict[str, Any]) -> str:
    manifest = records["manifest"]
    inventory = records["inventory"]
    registry = records["dependency_registry"]
    progress = records["progress"]
    scope = manifest.get("audit_scope")
    scope = scope if isinstance(scope, dict) else {}
    units = inventory.get("units")
    units = units if isinstance(units, list) else []
    inventory_ids = [
        str(unit.get("id"))
        for unit in units
        if isinstance(unit, dict) and is_nonempty_string(unit.get("id"))
    ]
    scope_ids = [
        str(value)
        for value in scope.get("in_scope_units", [])
        if is_nonempty_string(value)
    ]
    unit_ids = scope_ids or inventory_ids
    dependency_rows = workflow_registry_rows(registry)
    layers, cyclic = workflow_topological_layers(unit_ids, dependency_rows)
    dependency_mapping_ready, dependency_mapping_errors = (
        workflow_dependency_mapping_readiness(records)
    )
    direct: dict[str, set[str]] = defaultdict(set)
    downstream: dict[str, set[str]] = defaultdict(set)
    for row in dependency_rows:
        if row.get("kind") != "internal_result":
            continue
        dependent = row.get("dependent")
        prerequisite = row.get("prerequisite")
        if is_nonempty_string(dependent) and is_nonempty_string(prerequisite):
            direct[str(dependent)].add(str(prerequisite))
            downstream[str(prerequisite)].add(str(dependent))
    rows = [
        "# Proof-Check Execution Order",
        "",
        "> **GENERATED VIEW:** Run",
        "> `python \"<skill-root>/scripts/proofcheck.py\" sync-views --root <audit-root>`.",
        "> Do not edit this file or use it as the dependency record.",
        "",
        "## Dependency layers",
        "",
        (
            "Prerequisites appear before dependents."
            if dependency_mapping_ready
            else "The displayed order is provisional until dependency mapping is reviewed and current."
        ),
        "Short, closely related units in one",
        "ready layer may share one model work packet only when every unit has a complete",
        "separate packet, separate annotations, and a separate compiled ledger.",
        "",
        "| Layer | Ready units | Gate | Status |",
        "|---|---|---|---|",
    ]
    for index, layer in enumerate(layers, 1):
        prerequisites = (
            sorted(set().union(*(direct.get(unit_id, set()) for unit_id in layer)))
            if layer
            else []
        )
        layer_statuses = [
            workflow_unit_status(unit_id, progress) for unit_id in layer
        ]
        status = (
            "blocked_dependency_mapping"
            if not dependency_mapping_ready
            else "cycle_or_unresolved"
            if cyclic and index == len(layers)
            else "completed"
            if layer_statuses
            and all(value == "completed" for value in layer_statuses)
            else "blocked"
            if "blocked" in layer_statuses
            else "in_progress"
            if any(
                value in {"active", "in_progress", "conditional"}
                for value in layer_statuses
            )
            else "ready"
        )
        values = (
            str(index),
            workflow_id_list(layer),
            (
                workflow_id_list(prerequisites)
                if dependency_mapping_ready
                else "review dependency mapping"
            ),
            status,
        )
        rows.append(
            "| " + " | ".join(escape_markdown(value) for value in values) + " |"
        )
    if not layers:
        rows.append("| none | none | none | not_set |")
    rows.extend(
        [
            "",
            "## Unit order",
            "",
            "| Order | Unit | Dependencies | Priority label | Status | Next action |",
            "|---|---|---|---|---|---|",
        ]
    )
    declared_priority, promoted_priority, _ = workflow_priority_sets(records)
    priority = 0
    for layer in layers:
        for unit_id in layer:
            priority += 1
            status = workflow_unit_status(unit_id, progress)
            if not dependency_mapping_ready:
                next_action = (
                    "Review and bind DEPENDENCY_REGISTRY.json before scheduling unit work."
                )
            elif status == "completed":
                next_action = "none"
            elif status == "blocked":
                next_action = "Resolve the recorded blocker."
            elif progress.get("active_unit") == unit_id:
                next_action = str(
                    progress.get("next_action") or "Continue the active unit."
                )
            else:
                incomplete = sorted(
                    dependency
                    for dependency in direct.get(unit_id, set())
                    if workflow_unit_status(dependency, progress) != "completed"
                )
                next_action = (
                    "Complete prerequisites: " + ", ".join(incomplete)
                    if incomplete
                    else "Generate a primary packet and check this unit."
                )
            values = (
                str(priority),
                unit_id,
                workflow_id_list(sorted(direct.get(unit_id, set()))),
                (
                    "declared"
                    if unit_id in declared_priority
                    else "issue_promoted"
                    if unit_id in promoted_priority
                    else "no"
                ),
                status,
                next_action,
            )
            rows.append(
                "| "
                + " | ".join(escape_markdown(value) for value in values)
                + " |"
            )
    if not layers:
        rows.append("| none | none | none | no | not_set | Establish scope. |")
    rows.extend(
        [
            "",
            "## Blocked work",
            "",
            "| Unit | Blocker | Required evidence | Downstream effect |",
            "|---|---|---|---|",
        ]
    )
    blocked = progress.get("blocked_units")
    if isinstance(blocked, dict) and blocked:
        for unit_id, value in sorted(blocked.items()):
            if isinstance(value, dict):
                blocker = value.get("reason") or "recorded blocker"
                required = value.get("required_evidence") or "see PROGRESS.json"
            else:
                blocker = value
                required = "see PROGRESS.json"
            values = (
                str(unit_id),
                str(blocker),
                str(required),
                workflow_id_list(sorted(downstream.get(str(unit_id), set()))),
            )
            rows.append(
                "| " + " | ".join(escape_markdown(item) for item in values) + " |"
            )
    else:
        rows.append("| none | none | none | none |")
    rows.extend(
        [
            "",
            "## Dependency mapping gate",
            "",
            f"- Status: {'ready' if dependency_mapping_ready else 'blocked'}",
            (
                "- Diagnostics: none"
                if not dependency_mapping_errors
                else "- Diagnostics: " + "; ".join(dependency_mapping_errors)
            ),
        ]
    )
    rows.extend(
        [
            "",
            "The canonical dependency uses, statuses, issue propagation, and progress state",
            "remain in `DEPENDENCY_REGISTRY.json`, the unit ledgers, `ISSUE_LOG.json`, and",
            "`PROGRESS.json`.",
            "",
        ]
    )
    return "\n".join(rows)


def render_dependency_graph(records: dict[str, Any]) -> str:
    registry = records["dependency_registry"]
    review = registry.get("review")
    review = review if isinstance(review, dict) else {}
    dependency_rows = workflow_registry_rows(registry)
    rows = [
        "# Proof Dependency View",
        "",
        "> **GENERATED VIEW:** Run",
        "> `python \"<skill-root>/scripts/proofcheck.py\" sync-views --root <audit-root>`.",
        "> Do not edit this file or use it as canonical dependency evidence.",
        "",
        "## Registry binding",
        "",
        f"- Closure contract version: {registry.get('closure_contract_version', 'not_set')}",
        f"- Review status: {review.get('status', 'not_set')}",
        f"- Source snapshot SHA256: {review.get('source_snapshot_sha256') or 'not_set'}",
        f"- Inventory SHA256: {review.get('inventory_sha256') or 'not_set'}",
        f"- In-scope units: {workflow_id_list(review.get('in_scope_units'))}",
        "",
        "## Dependency uses",
        "",
        "Arrows point from prerequisite to dependent result.",
        "",
        "| Use ID | Prerequisite | Conclusion | Dependent | Effective status | Issue IDs |",
        "|---|---|---|---|---|---|",
    ]
    if dependency_rows:
        for row in dependency_rows:
            conclusion = row.get("conclusion")
            if is_nonempty_string(conclusion):
                conclusion = truncate(str(conclusion).replace("\n", " "), 160)
            else:
                conclusion = "none"
            values = (
                str(row.get("use_id") or "none"),
                str(row.get("prerequisite") or "none"),
                str(conclusion),
                str(row.get("dependent") or "none"),
                str(row.get("status") or "not_set"),
                workflow_id_list(row.get("issue_ids")),
            )
            rows.append(
                "| " + " | ".join(escape_markdown(value) for value in values) + " |"
            )
    else:
        rows.append("| none | none | none | none | none | none |")
    internal_edges = [
        row
        for row in dependency_rows
        if row.get("kind") == "internal_result"
        and is_nonempty_string(row.get("prerequisite"))
        and is_nonempty_string(row.get("dependent"))
    ]
    rows.extend(["", "## Graph", "", "```text"])
    if internal_edges:
        rows.extend(
            f"{row['prerequisite']} -> {row['dependent']} "
            f"[{row.get('use_id') or 'no_use_id'}]"
            for row in internal_edges
        )
    else:
        rows.append("none")
    rows.extend(
        [
            "```",
            "",
            "The generated graph is derived from reviewed internal-use rows. External",
            "uses remain in the table and canonical registry but do not create internal",
            "graph edges.",
            "",
            "`DEPENDENCY_REGISTRY.json` and ledger `direct_dependencies` remain canonical.",
            "This view intentionally omits repeated needed forms, compatibility matrices,",
            "source evidence, and contract hashes.",
            "",
        ]
    )
    return "\n".join(rows)


def render_workflow_views(records: dict[str, Any]) -> dict[str, str]:
    return {
        "CHECK_PLAN.md": render_check_plan(records),
        "EXECUTION_ORDER.md": render_execution_order(records),
        "audit/03_dependencies/dependency_graph.md": render_dependency_graph(records),
    }


def expected_workflow_views(root: Path) -> dict[str, str]:
    return render_workflow_views(load_workflow_records(root))


def workflow_view_freshness(root: Path) -> dict[str, Any]:
    root = root.resolve()
    expected = expected_workflow_views(root)
    missing: list[str] = []
    stale: list[str] = []
    for relative, text in expected.items():
        path = root / Path(relative)
        if not path.is_file():
            missing.append(relative)
            continue
        if read_text(path) != text:
            stale.append(relative)
    return {
        "status": "current" if not missing and not stale else "stale",
        "missing": missing,
        "stale": stale,
    }


def sync_workflow_views(root: Path) -> dict[str, Any]:
    root = root.resolve()
    lock_error = migration_update_lock_error(root)
    if lock_error is not None:
        raise ValueError(lock_error)
    expected = expected_workflow_views(root)
    writes: list[tuple[Path, str]] = []
    unchanged: list[str] = []
    for relative, text in expected.items():
        path = root / Path(relative)
        if path.is_file() and read_text(path) == text:
            unchanged.append(relative)
        else:
            writes.append((path, text))
    if writes:
        transactional_write_texts(writes)
    return {
        "status": "synchronized",
        "changed": [path.relative_to(root).as_posix() for path, _ in writes],
        "unchanged": unchanged,
    }


def cmd_sync_views(args: argparse.Namespace) -> int:
    configure_console_errors()
    root = args.root.resolve()
    result = sync_workflow_views(root)
    result["command"] = "sync-views"
    result["audit_root"] = str(root)
    print(json.dumps(result, ensure_ascii=True, indent=2))
    return 0


def live_local_check_artifacts(root: Path, suffix: str) -> list[Path]:
    """Return only direct canonical proof artifacts, never history copies."""
    if suffix not in {".ledger.json", ".skeleton.json"}:
        raise ValueError(f"Unsupported live proof-artifact suffix: {suffix}")
    directory = root.resolve() / "audit" / "04_local_checks"
    if not directory.is_dir():
        return []
    return sorted(
        (path for path in directory.glob(f"*{suffix}") if path.is_file()),
        key=lambda path: path.name,
    )


def packet_unit_artifact(
    root: Path, unit_id: str, suffix: str, label: str
) -> tuple[Path | None, dict[str, Any] | None]:
    matches: list[tuple[Path, dict[str, Any]]] = []
    for path in live_local_check_artifacts(root, suffix):
        value, errors = load_json_object(path, label)
        if errors:
            raise ValueError("Cannot generate packet: " + "; ".join(errors))
        if value.get("unit_id") == unit_id:
            matches.append((path, value))
    if len(matches) > 1:
        raise ValueError(f"Cannot generate packet: duplicate {label}s for {unit_id}")
    return matches[0] if matches else (None, None)


def packet_ledger(
    root: Path, unit_id: str
) -> tuple[Path | None, dict[str, Any] | None]:
    return packet_unit_artifact(
        root, unit_id, ".ledger.json", "canonical proof-unit ledger"
    )


def packet_skeleton(
    root: Path, unit_id: str
) -> tuple[Path | None, dict[str, Any] | None]:
    return packet_unit_artifact(
        root, unit_id, ".skeleton.json", "source-locked skeleton"
    )


def packet_semantic_readiness(
    path: Path | None, ledger: dict[str, Any] | None, unit_id: str
) -> dict[str, Any]:
    if path is None or ledger is None:
        return {
            "ready": False,
            "reasons": ["No current proof-unit ledger or source-locked skeleton exists."],
        }
    reasons: list[str] = []
    if (
        ledger.get("schema_version") != SCHEMA_VERSION
        or ledger.get("evidence_contract_version") != EVIDENCE_CONTRACT_VERSION
    ):
        reasons.append("The semantic artifact uses an unsupported evidence schema.")
    if ledger.get("unit_id") != unit_id:
        reasons.append("The semantic artifact is bound to a different proof unit.")

    source_errors: list[str] = []
    source = ledger.get("source")
    if not isinstance(source, dict):
        source_errors.append("missing source object")
    else:
        try:
            start = source["start_line"]
            end = source["end_line"]
            file_value = source["file"]
            if (
                not is_int(start)
                or not is_int(end)
                or start < 1
                or end < start
                or not is_nonempty_string(file_value)
            ):
                raise ValueError("invalid source range")
            source_path = resolve_stored_path(str(file_value), path.parent)
            selected = source_fragment_support().current(report_api(), ledger, path.parent)
            if source.get("unit_sha256") != sha256_text("\n".join(selected)):
                raise ValueError("source unit hash is stale")
            locked = ledger.get("source_lines")
            if not isinstance(locked, list) or len(locked) != len(selected):
                raise ValueError("locked source line count is stale")
            for offset, (record, text) in enumerate(zip(locked, selected)):
                if (
                    not isinstance(record, dict)
                    or record.get("line") != start + offset
                    or record.get("text") != text
                    or record.get("sha256") != sha256_text(text)
                ):
                    raise ValueError("locked source lines are stale")
        except (KeyError, OSError, TypeError, ValueError) as exc:
            source_errors.append(str(exc))
    if source_errors:
        reasons.append("The proof-unit source lock is incomplete or stale: " + "; ".join(source_errors))

    obligation_errors: list[str] = []
    validate_obligation(ledger.get("obligation"), path, True, obligation_errors)
    if obligation_errors:
        reasons.append("The normalized obligation is incomplete or stale.")
    return {"ready": not reasons, "reasons": reasons}


def packet_inventory_binding_errors(
    paper_base: Path,
    unit: dict[str, Any],
    artifact_path: Path | None,
    artifact: dict[str, Any] | None,
) -> list[str]:
    if artifact_path is None or artifact is None:
        return []
    source = artifact.get("source")
    obligation = artifact.get("obligation")
    if not isinstance(source, dict) or not isinstance(obligation, dict):
        return ["semantic artifact lacks source or obligation bindings"]
    try:
        ledger_file = resolve_stored_path(str(source["file"]), artifact_path.parent)
        ledger_start = source["start_line"]
        ledger_end = source["end_line"]
        if not is_int(ledger_start) or not is_int(ledger_end):
            raise ValueError("invalid ledger source range")
    except (KeyError, TypeError, ValueError):
        return ["semantic artifact source binding is malformed"]

    proof = unit.get("proof")
    statement = unit.get("statement")
    if not isinstance(statement, dict):
        return ["inventory has no statement or proof binding"]
    try:
        statement_file = resolve_stored_path(str(statement["file"]), paper_base)
        statement_start = statement["start_line"]
        statement_end = statement["end_line"]
        proof_file = (
            resolve_stored_path(str(proof["file"]), paper_base)
            if isinstance(proof, dict)
            else statement_file
        )
        proof_start = proof["start_line"] if isinstance(proof, dict) else statement_start
        proof_end = proof["end_line"] if isinstance(proof, dict) else statement_end
        if not all(
            is_int(value)
            for value in (statement_start, statement_end, proof_start, proof_end)
        ):
            raise ValueError("invalid inventory source range")
    except (KeyError, TypeError, ValueError):
        return ["inventory statement or proof binding is malformed"]
    errors: list[str] = []
    coverage_mode = source.get("coverage_mode")
    if coverage_mode == "statement_and_proof":
        exact_binding = (
            statement_file == proof_file == ledger_file
            and ledger_start == min(statement_start, proof_start)
            and ledger_end == max(statement_end, proof_end)
        )
    elif coverage_mode in {"proof_with_separate_statement", "external_restatement"}:
        exact_binding = (
            ledger_file == proof_file
            and ledger_start == proof_start
            and ledger_end == proof_end
        )
    else:
        exact_binding = False
    if not exact_binding:
        errors.append(
            "semantic artifact source range does not exactly match the inventory proof contract"
        )

    statement_spans = obligation.get("statement_spans")
    matched_statement = False
    if isinstance(statement, dict) and isinstance(statement_spans, list):
        try:
            statement_file = resolve_stored_path(str(statement["file"]), paper_base)
            statement_start = statement["start_line"]
            statement_end = statement["end_line"]
        except (KeyError, TypeError, ValueError):
            statement_file = Path()
            statement_start = None
            statement_end = None
        for span in statement_spans:
            if not isinstance(span, dict):
                continue
            try:
                span_file = resolve_stored_path(str(span["file"]), artifact_path.parent)
            except (KeyError, TypeError, ValueError):
                continue
            if (
                span_file == statement_file
                and span.get("start_line") == statement_start
                and span.get("end_line") == statement_end
            ):
                matched_statement = True
                break
    if not matched_statement:
        errors.append(
            "normalized obligation statement span disagrees with the inventory statement"
        )
    errors.extend(source_fragment_support().statement_binding_errors(
        report_api(), statement, paper_base, statement_spans, artifact_path.parent))
    return errors


def packet_span_reference(
    value: dict[str, Any],
    source_base: Path,
    source_locations: dict[str, Any] | None,
    source_location_base: Path | None,
) -> str | None:
    """Return the narrowest packet source span containing a locked span."""
    if not isinstance(source_locations, dict) or not isinstance(
        source_location_base, Path
    ):
        return None
    file_value = value.get("file")
    start = value.get("start_line")
    end = value.get("end_line")
    if (
        not is_nonempty_string(file_value)
        or not is_int(start)
        or not is_int(end)
    ):
        return None
    try:
        locked_path = resolve_stored_path(str(file_value), source_base)
    except ValueError:
        return None
    candidates: list[tuple[int, str]] = []
    for name in ("statement", "proof"):
        parent = source_locations.get(name)
        if not isinstance(parent, dict):
            continue
        parent_file = parent.get("file")
        parent_start = parent.get("start_line")
        parent_end = parent.get("end_line")
        if not is_nonempty_string(parent_file):
            continue
        try:
            parent_path = resolve_stored_path(
                str(parent_file), source_location_base
            )
        except ValueError:
            continue
        if (
            locked_path == parent_path
            and is_int(parent_start)
            and is_int(parent_end)
            and parent_start <= start <= end <= parent_end
        ):
            candidates.append((parent_end - parent_start, f"/source/{name}"))
    return min(candidates)[1] if candidates else None


def packet_locked_span(
    value: Any,
    root: Path,
    source_base: Path,
    source_locations: dict[str, Any] | None = None,
    source_location_base: Path | None = None,
) -> dict[str, Any] | None:
    if not isinstance(value, dict):
        return None
    file_value = value.get("file")
    source_identity: dict[str, Any] | None = None
    locked_lines: list[dict[str, Any]] = []
    if is_nonempty_string(file_value):
        normalized_name = Path(str(file_value).replace("\\", "/")).name
        audit_relative = None
        try:
            source_path = resolve_stored_path(str(file_value), source_base)
            normalized_name = source_path.name
            audit_relative = source_path.relative_to(root).as_posix()
        except ValueError:
            pass
        try:
            source_path = resolve_stored_path(str(file_value), source_base)
            start = value.get("start_line")
            end = value.get("end_line")
            if is_int(start) and is_int(end) and source_path.is_file():
                lines = read_lines(source_path)
                if 1 <= start <= end <= len(lines):
                    locked_lines = [
                        {"line": number, "text": lines[number - 1]}
                        for number in range(start, end + 1)
                    ]
        except (OSError, UnicodeError, ValueError):
            locked_lines = []
        source_identity = {
            "name": normalized_name,
            "audit_relative_file": audit_relative,
        }
    projected = {
        "source": source_identity,
        "start_line": value.get("start_line"),
        "end_line": value.get("end_line"),
        "sha256": value.get("sha256"),
        "quote": value.get("quote"),
        "lines": locked_lines,
    }
    if "role" in value:
        projected["role"] = value.get("role")
    source_span_ref = packet_span_reference(
        value,
        source_base,
        source_locations,
        source_location_base,
    )
    if source_span_ref is not None:
        projected["source_span_ref"] = source_span_ref
        projected.pop("lines", None)
    return projected


def packet_obligation(
    value: Any,
    root: Path,
    source_base: Path,
    source_locations: dict[str, Any] | None = None,
    source_location_base: Path | None = None,
    *,
    mode: str = "primary",
) -> dict[str, Any] | None:
    if not isinstance(value, dict):
        return None
    projected = {
        field: value.get(field)
        for field in (
            "quantified_variables",
            "quantifier_scope",
            "probability_model",
            "hypotheses",
            "definitions",
            "conclusion",
            "uniformity",
            "regime",
            "constant_dependencies",
            "normalization_checks",
        )
    }
    projected["statement_spans"] = [
        span
        for row in value.get("statement_spans", [])
        if (
            span := packet_locked_span(
                row,
                root,
                source_base,
                source_locations,
                source_location_base,
            )
        )
        is not None
    ]
    projected["context_spans"] = [
        span
        for row in value.get("context_spans", [])
        if (
            span := packet_locked_span(
                row,
                root,
                source_base,
                source_locations,
                source_location_base,
            )
        )
        is not None
    ]
    conclusions: list[dict[str, Any]] = []
    raw_conclusions = value.get("conclusions")
    if isinstance(raw_conclusions, list):
        for row in raw_conclusions:
            if isinstance(row, dict):
                conclusions.append(
                    {
                        "id": row.get("id"),
                        "claim": row.get("claim"),
                        "applies_under": row.get("applies_under"),
                        "source_spans": [
                            span
                            for source_row in row.get("source_spans", [])
                            if (
                                span := packet_locked_span(
                                    source_row,
                                    root,
                                    source_base,
                                    source_locations,
                                    source_location_base,
                                )
                            )
                            is not None
                        ],
                        "normalization": row.get("normalization"),
                    }
                )
    projected["conclusions"] = conclusions
    if mode == "challenge":
        projected.pop("normalization_checks", None)
        for conclusion in conclusions:
            conclusion.pop("normalization", None)
    return projected


def packet_source_members(
    root: Path, manifest: dict[str, Any]
) -> list[tuple[Path, dict[str, Any]]]:
    snapshot = manifest.get("source_snapshot")
    rows = snapshot.get("files") if isinstance(snapshot, dict) else None
    if not isinstance(rows, list):
        raise ValueError("Cannot generate packet: source snapshot files are missing")
    members: list[tuple[Path, dict[str, Any]]] = []
    for index, row in enumerate(rows, 1):
        if not isinstance(row, dict) or not is_nonempty_string(row.get("file")):
            raise ValueError(f"Cannot generate packet: invalid source member {index}")
        members.append((resolve_stored_path(row["file"], root), row))
    return members


def packet_span(
    root: Path,
    source_base: Path,
    location: Any,
    members: list[tuple[Path, dict[str, Any]]],
    *,
    allow_locked_external: bool = False,
    expand_inclusions: bool = True,
) -> dict[str, Any] | None:
    if location is None:
        return None
    if not isinstance(location, dict):
        raise ValueError("Cannot generate packet: source location is malformed")
    file_value = location.get("file")
    start = location.get("start_line")
    end = location.get("end_line")
    if not is_nonempty_string(file_value) or not is_int(start) or not is_int(end):
        raise ValueError("Cannot generate packet: source location is incomplete")
    source = resolve_stored_path(str(file_value), source_base)
    if not source.is_file():
        raise FileNotFoundError(f"Cannot generate packet: source file is missing: {source}")
    lines = read_lines(source)
    if start < 1 or end < start or end > len(lines):
        raise ValueError("Cannot generate packet: source location is out of bounds")
    member_index = next(
        (index for index, (path, _) in enumerate(members, 1) if path == source),
        None,
    )
    if member_index is None and not allow_locked_external:
        raise ValueError("Cannot generate packet: source span is outside the snapshot")
    try:
        audit_relative = source.relative_to(root).as_posix()
    except ValueError:
        audit_relative = None
    selected = lines[start - 1 : end]
    if member_index is None:
        source_member = {
            "index": None,
            "name": source.name,
            "audit_relative_file": audit_relative,
            "file_sha256": sha256_file(source),
            "membership": "locked_external_evidence",
        }
    else:
        member = members[member_index - 1][1]
        source_member = {
            "index": member_index,
            "name": source.name,
            "audit_relative_file": audit_relative,
            "file_sha256": member.get("sha256"),
        }
    result = {
        "source_member": source_member,
        "start_line": start,
        "end_line": end,
        "span_sha256": sha256_text("\n".join(selected)),
        "lines": [
            {"line": number, "text": text}
            for number, text in enumerate(selected, start)
        ],
    }
    if expand_inclusions:
        expanded = source_fragment_support().expand(report_api(), source, start, end, source_base)
        if expanded["has_inclusion"]:
            result["source_fragments_version"] = expanded["version"]
            result["last_substantive_position"] = expanded_last_substantive_position(expanded)
            result["fragments"] = [packet_span(
                root, source_base, fragment, members,
                allow_locked_external=allow_locked_external, expand_inclusions=False,
            ) for fragment in expanded["fragments"]]
    return result


def packet_candidate_dependency_paths(
    inventory: dict[str, Any],
    unit: dict[str, Any],
    source_base: Path,
    root: Path,
    members: list[tuple[Path, dict[str, Any]]],
    reference_occurrences: list[dict[str, Any]] | None = None,
) -> list[dict[str, Any]]:
    """Reconstruct portable source paths for parser-promoted dependency candidates."""
    label_owners = inventory.get("label_owners")
    if not isinstance(label_owners, dict):
        raise ValueError("Cannot generate packet: inventory label_owners is malformed")
    raw_files = inventory.get("files")
    if not isinstance(raw_files, list) or not all(
        is_nonempty_string(value) for value in raw_files
    ):
        raise ValueError("Cannot generate packet: inventory files are malformed")
    source_paths: list[Path] = []
    for value in raw_files:
        path = resolve_stored_path(str(value), source_base)
        if not path.is_file():
            raise FileNotFoundError(
                f"Cannot generate packet: inventory source file is missing: {path}"
            )
        source_paths.append(path)
    source_lines = readable_source_lines(source_paths, [], source_base)
    units = inventory.get("units")
    if not isinstance(units, list):
        raise ValueError("Cannot generate packet: inventory units are malformed")
    units_by_id = {
        str(record.get("id")): record
        for record in units
        if isinstance(record, dict) and is_nonempty_string(record.get("id"))
    }
    support_index = build_unowned_label_support_index(
        source_lines, units, label_owners, source_base
    )
    reviewed_occurrences = (
        reference_occurrences
        if reference_occurrences is not None
        else reviewed_unit_reference_occurrences(unit, source_base, label_owners)
    )
    raw_paths = resolve_candidate_internal_dependency_paths(
        str(unit.get("id")),
        reviewed_occurrences,
        label_owners,
        support_index,
    )
    output: list[dict[str, Any]] = []
    for path_index, raw_path in enumerate(raw_paths, 1):
        chain_projection: list[dict[str, Any]] = []
        raw_chain = raw_path.get("reference_chain")
        if not isinstance(raw_chain, list) or not raw_chain:
            raise ValueError("Cannot generate packet: candidate path is malformed")
        for occurrence in raw_chain:
            if not isinstance(occurrence, dict):
                raise ValueError(
                    "Cannot generate packet: candidate occurrence is malformed"
                )
            file_value = occurrence.get("file")
            line_number = occurrence.get("line")
            if not is_nonempty_string(file_value) or not is_int(line_number):
                raise ValueError(
                    "Cannot generate packet: candidate occurrence lacks a source anchor"
                )
            source = resolve_stored_path(str(file_value), source_base)
            member_index = next(
                (
                    index
                    for index, (member_path, _) in enumerate(members, 1)
                    if member_path == source
                ),
                None,
            )
            if member_index is None:
                raise ValueError(
                    "Cannot generate packet: candidate occurrence is outside "
                    "the source snapshot"
                )
            lines = source_lines.get(source)
            if lines is None:
                lines = read_lines(source)
            if line_number < 1 or line_number > len(lines):
                raise ValueError(
                    "Cannot generate packet: candidate occurrence line is out of bounds"
                )
            member = members[member_index - 1][1]
            try:
                audit_relative = source.relative_to(root).as_posix()
            except ValueError:
                audit_relative = None
            owner = label_owners.get(str(occurrence.get("target")))
            owner = owner if isinstance(owner, dict) else {}
            owner_unit = units_by_id.get(str(owner.get("owner_unit_id")), {})
            text = lines[line_number - 1]
            chain_projection.append(
                {
                    "occurrence_id": occurrence.get("occurrence_id"),
                    "command": occurrence.get("command"),
                    "target": occurrence.get("target"),
                    "structural_context": occurrence.get("structural_context"),
                    "resolution_status": owner.get("status"),
                    "owner_unit_id": owner.get("owner_unit_id"),
                    "owner_region": owner.get("owner_region"),
                    "owner_proof_required": owner_unit.get("proof_required"),
                    "owner_environment": owner_unit.get("semantic_kind") or owner_unit.get("environment"),
                    "source_member": {
                        "index": member_index,
                        "name": source.name,
                        "audit_relative_file": audit_relative,
                        "file_sha256": member.get("sha256"),
                    },
                    "line": line_number,
                    "start_column": occurrence.get(
                        "start_column", occurrence.get("column")
                    ),
                    "end_column": occurrence.get("end_column"),
                    "text": text,
                }
            )
        output.append(
            {
                "path_id": f"CP{path_index:03d}",
                "candidate_id": raw_path.get("candidate_id"),
                "origin_occurrence_id": chain_projection[0][
                    "occurrence_id"
                ],
                "reference_chain": chain_projection,
            }
        )
    return output


def packet_downstream_use_sites(
    inventory: dict[str, Any],
    unit: dict[str, Any],
    cross_references: dict[str, Any],
    source_base: Path,
    root: Path,
    members: list[tuple[Path, dict[str, Any]]],
) -> list[dict[str, Any]]:
    """Project every canonical outside-unit reference to this result."""
    label_owners = inventory.get("label_owners")
    label_owners = label_owners if isinstance(label_owners, dict) else {}
    inventory_units = inventory.get("units")
    inventory_units = inventory_units if isinstance(inventory_units, list) else []
    occurrence_context = {
        occurrence.get("occurrence_id"): occurrence.get("structural_context")
        for reviewed_unit in inventory_units
        if isinstance(reviewed_unit, dict)
        for occurrence in reviewed_unit.get("reference_occurrences", [])
        if isinstance(occurrence, dict)
        and is_nonempty_string(occurrence.get("occurrence_id"))
    }
    redirect_spans = [
        redirect
        for reviewed_unit in inventory_units
        if isinstance(reviewed_unit, dict)
        for redirect in reviewed_unit.get("proof_redirects", [])
        if isinstance(reviewed_unit.get("proof_redirects"), list)
        and isinstance(redirect, dict)
    ]
    unit_id = str(unit.get("id"))
    projected: list[dict[str, Any]] = []
    occurrences = cross_references.get("occurrences")
    occurrences = occurrences if isinstance(occurrences, list) else []
    seen: set[str] = set()
    for occurrence in occurrences:
        if not isinstance(occurrence, dict):
            continue
        owner = label_owners.get(str(occurrence.get("target")))
        owner = owner if isinstance(owner, dict) else {}
        refers_to_unit = bool(
            occurrence.get("target") == unit_id
            or (
                owner.get("status") == "unique"
                and owner.get("owner_unit_id") == unit_id
            )
        )
        if not refers_to_unit:
            continue
        if span_contains_location(
            unit.get("statement"),
            occurrence.get("file"),
            occurrence.get("line"),
            source_base,
        ) or span_contains_location(
            unit.get("proof"),
            occurrence.get("file"),
            occurrence.get("line"),
            source_base,
        ):
            continue
        if occurrence_context.get(
            occurrence.get("occurrence_id")
        ) == "proof_header":
            continue
        if any(
            span_contains_location(
                redirect,
                occurrence.get("file"),
                occurrence.get("line"),
                source_base,
            )
            for redirect in redirect_spans
        ):
            continue
        file_value = occurrence.get("file")
        line_number = occurrence.get("line")
        if not is_nonempty_string(file_value) or not is_int(line_number):
            continue
        canonical_location = f"{file_value}:{line_number}"
        if canonical_location in seen:
            continue
        seen.add(canonical_location)
        source = resolve_stored_path(str(file_value), source_base)
        member_index = next(
            (
                index
                for index, (member_path, _) in enumerate(members, 1)
                if member_path == source
            ),
            None,
        )
        if member_index is None or not source.is_file():
            raise ValueError(
                "Cannot generate packet: downstream use is outside the "
                "source snapshot"
            )
        lines = read_lines(source)
        if line_number < 1 or line_number > len(lines):
            raise ValueError(
                "Cannot generate packet: downstream use line is out of bounds"
            )
        member = members[member_index - 1][1]
        try:
            audit_relative = source.relative_to(root).as_posix()
        except ValueError:
            audit_relative = None
        text = lines[line_number - 1]
        projected.append(
            {
                "canonical_location": canonical_location,
                "occurrence_id": occurrence.get("occurrence_id"),
                "command": occurrence.get("command"),
                "target": occurrence.get("target"),
                "source_member": {
                    "index": member_index,
                    "name": source.name,
                    "audit_relative_file": audit_relative,
                    "file_sha256": member.get("sha256"),
                },
                "line": line_number,
                "text": text,
            }
        )
    return sorted(
        projected, key=lambda row: str(row.get("canonical_location", ""))
    )


def packet_inventory_projection(
    unit: dict[str, Any],
    candidate_paths: list[dict[str, Any]] | None = None,
    downstream_use_sites: list[dict[str, Any]] | None = None,
    reference_occurrences: list[dict[str, Any]] | None = None,
) -> dict[str, Any]:
    association = unit.get("proof_association")
    association_projection = None
    if isinstance(association, dict):
        association_projection = {
            field: association.get(field)
            for field in ("status", "method", "target", "evidence_occurrence_ids")
        }
    occurrences: list[dict[str, Any]] = []
    for row in (
        reference_occurrences
        if reference_occurrences is not None
        else unit.get("reference_occurrences", [])
    ):
        if isinstance(row, dict):
            occurrences.append(
                {
                    field: row.get(field)
                    for field in (
                        "occurrence_id",
                        "command",
                        "target",
                        "line",
                        "source_position",
                        "start_column",
                        "end_column",
                        "structural_context",
                        "resolution_status",
                        "owner_unit_id",
                        "owner_region",
                    )
                    if field in row
                }
            )
    candidate_ids: set[str] = set()
    for row in unit.get("candidate_internal_dependencies", []):
        if is_nonempty_string(row):
            candidate_ids.add(str(row))
        elif isinstance(row, dict):
            for field in ("dependency_id", "id", "owner_unit_id", "target"):
                if is_nonempty_string(row.get(field)):
                    candidate_ids.add(str(row[field]))
    return {
        "environment": unit.get("environment"),
        "proof_required": unit.get("proof_required"),
        "proof_association": association_projection,
        "reference_occurrences": occurrences,
        "candidate_internal_dependency_ids": sorted(candidate_ids),
        "candidate_dependency_paths": list(candidate_paths or []),
        "downstream_use_sites": list(downstream_use_sites or []),
        "citation_keys": sorted(
            str(value)
            for value in unit.get("citations", [])
            if is_nonempty_string(value)
        ),
    }


def packet_candidate_reconciliation(
    unit: dict[str, Any],
    registry: dict[str, Any],
    semantic_artifact: dict[str, Any] | None,
    candidate_paths: list[dict[str, Any]] | None = None,
) -> dict[str, Any]:
    candidate_ids = set(
        packet_inventory_projection(unit)["candidate_internal_dependency_ids"]
    )
    registry_mapped_ids = {
        str(row.get("dependency_id"))
        for row in registry.get("internal_uses", [])
        if isinstance(row, dict)
        and row.get("dependent_unit") == unit.get("id")
        and is_nonempty_string(row.get("dependency_id"))
    }
    review = (
        semantic_artifact.get("review")
        if isinstance(semantic_artifact, dict)
        else None
    )
    ledger_dependency_ids: set[str] = set()
    if isinstance(review, dict):
        ledger_dependency_ids.update(
            str(row.get("id"))
            for row in review.get("direct_dependencies", [])
            if (
                isinstance(row, dict)
                and row.get("kind") == "internal_result"
                and is_nonempty_string(row.get("id"))
            )
        )
    candidate_dispositions = {
        str(row.get("candidate_id")): row
        for row in (
            review.get("candidate_dependency_dispositions", [])
            if isinstance(review, dict)
            else []
        )
        if isinstance(row, dict) and is_nonempty_string(row.get("candidate_id"))
    }
    path_ids_by_candidate: dict[str, list[str]] = defaultdict(list)
    for path in candidate_paths or []:
        if not isinstance(path, dict):
            continue
        candidate_id = path.get("candidate_id")
        path_id = path.get("path_id")
        if is_nonempty_string(candidate_id) and is_nonempty_string(
            path_id
        ):
            path_ids_by_candidate[str(candidate_id)].append(
                str(path_id)
            )
    explicit_non_dependencies: set[str] = set()
    nondependency_roles = {
        "navigation",
        "non_load_bearing",
        "obligation_context",
    }
    for candidate_id in candidate_ids - registry_mapped_ids:
        disposition = candidate_dispositions.get(candidate_id)
        expected_path_ids = sorted(path_ids_by_candidate.get(candidate_id, []))
        if (
            isinstance(disposition, dict)
            and disposition.get("disposition") in nondependency_roles
            and sorted(disposition.get("path_ids", [])) == expected_path_ids
            and expected_path_ids
        ):
            explicit_non_dependencies.add(candidate_id)
    unresolved = sorted(
        candidate_ids - registry_mapped_ids - explicit_non_dependencies
    )
    ledger_only = sorted(ledger_dependency_ids - registry_mapped_ids)
    return {
        "status": (
            "complete" if not unresolved and not ledger_only else "pending"
        ),
        "candidate_internal_dependency_ids": sorted(candidate_ids),
        "registry_mapped_dependency_ids": sorted(
            candidate_ids & registry_mapped_ids
        ),
        "explicit_nondependency_ids": sorted(explicit_non_dependencies),
        "unresolved_candidate_ids": unresolved,
        "ledger_only_internal_dependency_ids": ledger_only,
    }


def packet_candidate_reconciliation_projection(
    reconciliation: dict[str, Any], mode: str
) -> dict[str, Any]:
    """Hide the primary reviewer's candidate classifications from a challenger."""
    if mode == "primary":
        return reconciliation
    candidate_ids = list(
        reconciliation.get("candidate_internal_dependency_ids", [])
    )
    mapped_ids = list(
        reconciliation.get("registry_mapped_dependency_ids", [])
    )
    return {
        "candidate_internal_dependency_ids": candidate_ids,
        "registry_mapped_dependency_ids": mapped_ids,
        "candidate_ids_without_registry_contract": sorted(
            set(candidate_ids) - set(mapped_ids)
        ),
    }


def compact_dependencies_from_packet(
    dependency_projection: Any,
) -> list[dict[str, Any]]:
    """Project registry-backed packet uses into the compact annotation schema."""
    if not isinstance(dependency_projection, dict):
        raise ValueError("Packet dependencies must be an object")
    output: list[dict[str, Any]] = []
    for field, kind in (
        ("direct_internal_uses", "internal_result"),
        ("direct_external_uses", "external_result"),
    ):
        rows = dependency_projection.get(field)
        if not isinstance(rows, list):
            raise ValueError(f"Packet dependencies.{field} must be a list")
        for index, row in enumerate(rows, 1):
            if not isinstance(row, dict):
                raise ValueError(
                    f"Packet dependencies.{field}[{index}] must be an object"
                )
            compact = {
                "id": row.get("dependency_id"),
                "use_id": row.get("use_id"),
                "kind": kind,
                "status": row.get("status"),
                "needed_form": row.get("needed_form"),
                "compatibility_check": row.get("compatibility_check"),
            }
            if kind == "internal_result":
                compact["conclusion_id"] = row.get(
                    "dependency_conclusion_id"
                )
                if "statement_support_sha256" in row:
                    compact["statement_support_sha256"] = row["statement_support_sha256"]
            output.append(compact)
    return sorted(output, key=lambda row: str(row.get("use_id", "")))


def packet_dependency_alignment(
    semantic_artifact: dict[str, Any] | None,
    dependency_projection: dict[str, Any],
    *,
    primary_record_ready: bool,
) -> dict[str, Any]:
    """Compare a final primary ledger with the registry-backed packet contracts."""
    expected = compact_dependencies_from_packet(dependency_projection)
    if not primary_record_ready or not isinstance(semantic_artifact, dict):
        return {
            "status": "pending_primary_record",
            "expected_use_ids": [
                str(row.get("use_id")) for row in expected
            ],
            "mismatches": [],
        }
    review = semantic_artifact.get("review")
    raw_actual = (
        review.get("direct_dependencies", [])
        if isinstance(review, dict)
        else []
    )
    actual: list[dict[str, Any]] = []
    if isinstance(raw_actual, list):
        for row in raw_actual:
            if not isinstance(row, dict):
                continue
            compact = {
                field: row.get(field)
                for field in (
                    "id",
                    "use_id",
                    "kind",
                    "status",
                    "needed_form",
                    "compatibility_check",
                )
            }
            if row.get("kind") == "internal_result":
                compact["conclusion_id"] = row.get("conclusion_id")
                if "statement_support_sha256" in row:
                    compact["statement_support_sha256"] = row["statement_support_sha256"]
            actual.append(compact)
    actual = sorted(actual, key=lambda row: str(row.get("use_id", "")))
    mismatches: list[str] = []
    expected_by_use = {
        str(row.get("use_id")): row for row in expected
    }
    actual_by_use = {
        str(row.get("use_id")): row for row in actual
    }
    for use_id in sorted(set(expected_by_use) | set(actual_by_use)):
        if use_id not in expected_by_use:
            mismatches.append(f"{use_id}: missing registry contract")
        elif use_id not in actual_by_use:
            mismatches.append(f"{use_id}: missing primary-ledger use")
        elif expected_by_use[use_id] != actual_by_use[use_id]:
            fields = sorted(
                field
                for field in set(expected_by_use[use_id])
                | set(actual_by_use[use_id])
                if expected_by_use[use_id].get(field)
                != actual_by_use[use_id].get(field)
            )
            mismatches.append(
                f"{use_id}: fields differ: {', '.join(fields)}"
            )
    return {
        "status": "complete" if not mismatches else "mismatch",
        "expected_use_ids": sorted(expected_by_use),
        "mismatches": mismatches,
    }


def packet_dependency_use(
    row: dict[str, Any],
    root: Path,
    mode: str,
    *,
    external: bool = False,
    source_status: str | None = None,
) -> dict[str, Any]:
    common_fields = (
        "dependent_unit",
        "use_id",
        "dependency_id",
        "dependency_conclusion_id",
        "dependency_conclusion",
        "dependency_contract_sha256",
        "statement_support_sha256",
        "needed_form",
        "step_ids",
    )
    projected = {field: row.get(field) for field in common_fields if field in row}
    if external:
        projected["citation_keys"] = row.get("citation_keys")
    if "statement_support_sha256" in row:
        projected["statement_support_conditions"] = [
            {**{key: value for key, value in condition.items() if key != "status"},
             **({"status": condition.get("status")} if mode == "primary" else {})}
            for condition in row.get("statement_support_conditions", []) if isinstance(condition, dict)
        ]
    use_site = packet_locked_span(row.get("use_site"), root, root)
    if use_site is not None:
        projected["use_site"] = use_site
    if mode == "primary":
        if source_status is not None:
            projected["source_status"] = source_status
        for field in (
            "compatibility_check",
            "compatibility_checks",
            "status",
            "issue_ids",
        ):
            projected[field] = row.get(field)
    if external:
        prerequisite_rows: list[dict[str, Any]] = []
        raw_prerequisites = row.get("prerequisite_map")
        if isinstance(raw_prerequisites, list):
            for prerequisite in raw_prerequisites:
                if not isinstance(prerequisite, dict):
                    continue
                fields = ("prerequisite", "manuscript_evidence", "status", "issue_ids") if mode == "primary" else ("prerequisite", "manuscript_evidence")
                item = {field: prerequisite.get(field) for field in fields}
                for span_field in ("evidence_spans", "source_evidence_spans"):
                    item[span_field] = [span for source_row in prerequisite.get(span_field, [])
                                       if (span := packet_locked_span(source_row, root, root)) is not None]
                prerequisite_rows.append(item)
        projected["prerequisite_map"] = prerequisite_rows
    return projected


def packet_prerequisite_contract(
    root: Path,
    ledger_path: Path,
    ledger: dict[str, Any],
    conclusion_id: str,
) -> dict[str, Any]:
    """Expose the inspected conditions and source behind an internal contract."""
    obligation = ledger.get("obligation")
    contract = (
        conclusion_contract_payload(obligation, conclusion_id)
        if isinstance(obligation, dict)
        else None
    )
    if not isinstance(contract, dict):
        raise ValueError("Cannot generate packet: prerequisite conclusion is missing")
    _, manifest, errors = load_audit_manifest(root)
    if errors:
        raise ValueError("Cannot generate prerequisite context: " + "; ".join(errors))
    members = packet_source_members(root, manifest)

    def spans(value: Any, label: str, *, required: bool = False) -> list[dict[str, Any]]:
        if not isinstance(value, list) or (required and not value):
            raise ValueError(f"Cannot generate packet: prerequisite {label} is missing")
        projected: list[dict[str, Any]] = []
        for row in value:
            span_errors: list[str] = []
            validate_locked_span(row, ledger_path.parent, label, span_errors)
            if span_errors:
                raise ValueError(
                    "Cannot generate packet: prerequisite context is missing or stale: "
                    + "; ".join(span_errors)
                )
            source = packet_span(root, ledger_path.parent, row, members)
            if source is None:
                raise ValueError(f"Cannot generate packet: prerequisite {label} is missing")
            if isinstance(row, dict) and "role" in row:
                source["role"] = row["role"]
            projected.append(source)
        return projected

    applicability = contract.get("applicability")
    if not isinstance(applicability, list) or any(
        not isinstance(row, dict) or row.get("resolved") is None
        for row in applicability
    ):
        raise ValueError("Cannot generate packet: prerequisite applicability is unresolved")
    return {
        "contract_ref": f"{ledger.get('unit_id')}/{conclusion_id}",
        "dependency_id": ledger.get("unit_id"),
        "conclusion_id": conclusion_id,
        "contract_sha256": canonical_sha256(contract),
        "claim": contract["claim"],
        "applicability": applicability,
        "statement_spans": spans(obligation.get("statement_spans"), "statement", required=True),
        "conclusion_spans": spans(contract.get("source_spans"), "conclusion source", required=True),
        "context_spans": spans(obligation.get("context_spans"), "context"),
    }


def packet_dependency_projection(
    registry: dict[str, Any],
    root: Path,
    unit_id: str,
    mode: str,
    current_artifact: dict[str, Any] | None,
) -> dict[str, Any]:
    direct_internal: list[dict[str, Any]] = []
    internal_contracts: dict[tuple[str, str], dict[str, Any]] = {}
    downstream_internal: list[dict[str, Any]] = []
    internal_rows = registry.get("internal_uses")
    internal_rows = internal_rows if isinstance(internal_rows, list) else []
    for row in internal_rows:
        if not isinstance(row, dict):
            continue
        if row.get("dependent_unit") == unit_id:
            dependency_path, dependency_ledger = packet_ledger(
                root, str(row.get("dependency_id", ""))
            )
            if dependency_path is None:
                raise ValueError(
                    "Cannot generate packet: direct internal dependency has no "
                    "canonical ledger"
                )
            dependency_errors, dependency_summary = check_ledger_data(
                dependency_path, True, primary_only=True
            )
            if dependency_errors:
                raise ValueError(
                    "Cannot generate packet: direct internal dependency ledger is "
                    "not locally final: " + "; ".join(dependency_errors[:6])
                )
            conclusion_id = str(row.get("dependency_conclusion_id", ""))
            conclusion_record = next(
                (
                    value
                    for value in dependency_summary.get(
                        "obligation_conclusions", []
                    )
                    if isinstance(value, dict)
                    and value.get("id") == conclusion_id
                ),
                None,
            )
            if (
                not isinstance(conclusion_record, dict)
                or row.get("dependency_conclusion")
                != conclusion_record.get("claim")
                or row.get("dependency_contract_sha256")
                != conclusion_record.get("contract_sha256")
            ):
                raise ValueError(
                    "Cannot generate packet: direct internal dependency contract "
                    "is stale or incorrect"
                )
            projected = packet_dependency_use(
                row,
                root,
                mode,
                source_status=internal_dependency_status(
                    dependency_summary,
                    conclusion_id,
                ),
            )
            if "statement_support_sha256" in row:
                support_errors: list[str] = []
                support_status, selected_support = statement_support_use_status(dependency_summary, conclusion_id, row, root, support_errors)
                if support_errors:
                    raise ValueError("Cannot generate packet: " + "; ".join(support_errors))
                if mode == "primary":
                    projected["source_status"] = support_status
                projected["statement_support_contract"] = {
                    "claim": selected_support["claim"], "extra_conditions": selected_support["extra_conditions"],
                    "statement_support_sha256": selected_support["sha256"],
                }
            key = (str(row.get("dependency_id")), conclusion_id)
            if key not in internal_contracts:
                internal_contracts[key] = packet_prerequisite_contract(
                    root, dependency_path, dependency_ledger, conclusion_id
                )
            projected["contract_ref"] = internal_contracts[key]["contract_ref"]
            direct_internal.append(projected)
        if row.get("dependency_id") == unit_id:
            obligation = (
                current_artifact.get("obligation")
                if isinstance(current_artifact, dict)
                else None
            )
            conclusion_id = row.get("dependency_conclusion_id")
            contract_payload = (
                conclusion_contract_payload(obligation, str(conclusion_id))
                if isinstance(obligation, dict)
                and is_nonempty_string(conclusion_id)
                else None
            )
            if (
                not isinstance(contract_payload, dict)
                or row.get("dependency_conclusion")
                != contract_payload.get("claim")
                or row.get("dependency_contract_sha256")
                != canonical_sha256(contract_payload)
            ):
                raise ValueError(
                    "Cannot generate packet: downstream internal dependency contract "
                    "is stale or incorrect"
                )
            projected = packet_dependency_use(row, root, mode)
            downstream_internal.append(projected)

    direct_external: list[dict[str, Any]] = []
    external_results: list[dict[str, Any]] = []
    result_rows = registry.get("external_results")
    result_rows = result_rows if isinstance(result_rows, list) else []
    for result in result_rows:
        if not isinstance(result, dict):
            continue
        raw_uses = result.get("uses")
        raw_uses = raw_uses if isinstance(raw_uses, list) else []
        uses = [
            row
            for row in raw_uses
            if isinstance(row, dict) and row.get("dependent_unit") == unit_id
        ]
        if not uses:
            continue
        expected_contract_hash = canonical_sha256(external_result_contract(result))
        if any(
            row.get("dependency_conclusion") != result.get("exact_statement")
            or row.get("dependency_contract_sha256") != expected_contract_hash
            for row in uses
        ):
            raise ValueError(
                "Cannot generate packet: direct external dependency contract is "
                "stale or incorrect"
            )
        projected_uses = [
            packet_dependency_use(
                row,
                root,
                mode,
                external=True,
                source_status=(
                    str(result.get("status"))
                    if is_nonempty_string(result.get("status"))
                    else None
                ),
            )
            for row in uses
        ]
        direct_external.extend(projected_uses)
        evidence_rows: list[dict[str, Any]] = []
        raw_evidence = result.get("source_evidence")
        raw_evidence = raw_evidence if isinstance(raw_evidence, list) else []
        for index, evidence in enumerate(raw_evidence, 1):
            if not isinstance(evidence, dict):
                continue
            audit_relative = None
            file_value = evidence.get("file")
            file_name = None
            if is_nonempty_string(file_value):
                try:
                    evidence_path = resolve_stored_path(str(file_value), root)
                    if (
                        not evidence_path.is_file()
                        or evidence.get("sha256") != sha256_file(evidence_path)
                    ):
                        raise ValueError("external source evidence is stale")
                except ValueError:
                    raise ValueError(
                        "Cannot generate packet: direct external source evidence "
                        "is missing or stale"
                    )
                file_name = evidence_path.name
                try:
                    audit_relative = evidence_path.relative_to(root).as_posix()
                except ValueError:
                    audit_relative = None
            evidence_projection = {
                    "evidence_id": f"{result.get('id')}:E{index:03d}",
                    "name": file_name,
                    "audit_relative_file": audit_relative,
                    "sha256": evidence.get("sha256"),
                    "locator": evidence.get("locator"),
                    "role": evidence.get("role"),
                }
            if file_name is not None and evidence_path.suffix.lower() in {".txt", ".tex", ".md"}:
                evidence_lines = read_lines(evidence_path)
                if evidence_lines:
                    evidence_projection["source_span"] = packet_span(
                        root, root, {"file": str(evidence_path), "start_line": 1, "end_line": len(evidence_lines)},
                        [], allow_locked_external=True)
            evidence_rows.append(evidence_projection)
        result_projection = {
            field: result.get(field)
            for field in (
                "id",
                "source_identity",
                "version",
                "theorem_location",
                "exact_statement",
            )
        } | {"source_evidence": evidence_rows, "uses": projected_uses}
        if mode == "primary":
            result_projection["status"] = result.get("status")
            result_projection["issue_ids"] = result.get("issue_ids")
        external_results.append(result_projection)
    return {
        "registry_binding": {
            "closure_contract_version": registry.get("closure_contract_version"),
        },
        "internal_contracts": [internal_contracts[key] for key in sorted(internal_contracts)],
        "direct_internal_uses": sorted(
            direct_internal, key=lambda row: str(row.get("use_id", ""))
        ),
        "direct_external_uses": sorted(
            direct_external, key=lambda row: str(row.get("use_id", ""))
        ),
        "downstream_internal_uses": sorted(
            downstream_internal,
            key=lambda row: (
                str(row.get("dependent_unit", "")),
                str(row.get("use_id", "")),
            ),
        ),
        "external_results": sorted(
            external_results, key=lambda row: str(row.get("id", ""))
        ),
    }


def packet_issue_ledger(
    root: Path, unit_id: Any
) -> tuple[Path, dict[str, Any]]:
    if not is_nonempty_string(unit_id):
        raise ValueError("Cannot generate packet: issue target has no unit ID")
    path, ledger = packet_ledger(root, str(unit_id))
    if path is None or ledger is None:
        raise ValueError(
            "Cannot generate packet: issue target ledger is missing for "
            f"{unit_id}"
        )
    return path, ledger


def packet_issue_locked_anchor(
    root: Path,
    source_base: Path,
    span: Any,
    members: list[tuple[Path, dict[str, Any]]],
    *,
    allow_locked_external: bool = False,
) -> dict[str, Any]:
    projection = packet_span(
        root,
        source_base,
        span,
        members,
        allow_locked_external=allow_locked_external,
    )
    if projection is None:
        raise ValueError("Cannot generate packet: issue target span is missing")
    expected_sha256 = span.get("sha256") if isinstance(span, dict) else None
    if (
        is_nonempty_string(expected_sha256)
        and expected_sha256 != projection["span_sha256"]
    ):
        raise ValueError("Cannot generate packet: issue target span is stale")
    if isinstance(span, dict) and "role" in span:
        projection["role"] = span.get("role")
    return projection


def packet_issue_step_anchor(
    root: Path,
    ledger_path: Path,
    ledger: dict[str, Any],
    step: dict[str, Any],
    members: list[tuple[Path, dict[str, Any]]],
) -> dict[str, Any]:
    source_unit_id = step.get("source_unit_id")
    source_unit = next(
        (
            row
            for row in ledger.get("source_units", [])
            if isinstance(row, dict) and row.get("id") == source_unit_id
        ),
        None,
    )
    line_range = source_unit.get("lines") if isinstance(source_unit, dict) else None
    source = ledger.get("source")
    if (
        not isinstance(source, dict)
        or not is_nonempty_string(source.get("file"))
        or not isinstance(line_range, list)
        or len(line_range) != 2
        or not all(is_int(value) for value in line_range)
    ):
        raise ValueError(
            "Cannot generate packet: issue target step lacks an exact source unit"
        )
    location = source_unit_location(ledger, source_unit)
    projection = packet_span(root, ledger_path.parent, location, members)
    if projection is None:
        raise ValueError("Cannot generate packet: issue target step is unanchored")
    source_sha256 = source_unit.get("source_sha256")
    if (
        is_nonempty_string(source_sha256)
        and source_sha256 != projection["span_sha256"]
    ):
        raise ValueError("Cannot generate packet: issue target source unit is stale")
    projection["source_unit_id"] = source_unit_id
    return projection


def packet_issue_contract_target(
    root: Path,
    ref: dict[str, Any],
    members: list[tuple[Path, dict[str, Any]]],
) -> dict[str, Any]:
    ledger_path, ledger = packet_issue_ledger(root, ref.get("unit_id"))
    kind = ref.get("kind")
    reference = canonical_issue_ref_identity(ref)
    if kind == "conclusion":
        matches = [
            row
            for row in ledger.get("obligation", {}).get("conclusions", [])
            if isinstance(row, dict)
            and row.get("id") == ref.get("conclusion_id")
        ]
        if len(matches) != 1:
            raise ValueError(
                "Cannot generate packet: issue conclusion contract is unresolved"
            )
        conclusion = matches[0]
        raw_spans = conclusion.get("source_spans")
        if not isinstance(raw_spans, list) or not raw_spans:
            raise ValueError(
                "Cannot generate packet: issue conclusion contract is unanchored"
            )
        conditions: list[dict[str, Any]] = []
        for pointer in conclusion.get("applies_under", []):
            found, value = resolve_json_pointer(
                ledger.get("obligation"), pointer
            )
            if not found:
                raise ValueError(
                    "Cannot generate packet: issue conclusion condition is unresolved"
                )
            conditions.append({"pointer": pointer, "value": value})
        return {
            "reference": reference,
            "claim": conclusion.get("claim"),
            "conditions": conditions,
            "source_anchors": [
                packet_issue_locked_anchor(
                    root, ledger_path.parent, span, members
                )
                for span in raw_spans
            ],
        }
    if kind == "obligation_pointer":
        found, value = resolve_json_pointer(
            ledger.get("obligation"), ref.get("pointer")
        )
        if not found:
            raise ValueError(
                "Cannot generate packet: issue obligation contract is unresolved"
            )
        statement_spans = ledger.get("obligation", {}).get(
            "statement_spans", []
        )
        if not isinstance(statement_spans, list) or not statement_spans:
            raise ValueError(
                "Cannot generate packet: issue obligation contract is unanchored"
            )
        return {
            "reference": reference,
            "value": value,
            "source_anchors": [
                packet_issue_locked_anchor(
                    root, ledger_path.parent, span, members
                )
                for span in statement_spans
            ],
        }
    if kind == "dependency_use":
        dependencies = ledger.get("review", {}).get(
            "direct_dependencies", []
        )
        matches = [
            row
            for row in dependencies
            if isinstance(row, dict) and row.get("use_id") == ref.get("use_id")
        ] if isinstance(dependencies, list) else []
        if len(matches) != 1:
            raise ValueError(
                "Cannot generate packet: issue dependency contract is unresolved"
            )
        dependency = matches[0]
        anchors: list[dict[str, Any]] = []
        for step_id in dependency.get("step_ids", []):
            step = next(
                (
                    row
                    for row in ledger.get("steps", [])
                    if isinstance(row, dict) and row.get("id") == step_id
                ),
                None,
            )
            if not isinstance(step, dict):
                raise ValueError(
                    "Cannot generate packet: issue dependency step is unresolved"
                )
            anchors.append(
                packet_issue_step_anchor(
                    root, ledger_path, ledger, step, members
                )
            )
        return {
            "reference": reference,
            "dependency_id": dependency.get("dependency_id"),
            "dependency_conclusion_id": dependency.get(
                "dependency_conclusion_id"
            ),
            "dependency_conclusion": dependency.get(
                "dependency_conclusion"
            ),
            "dependency_contract_sha256": dependency.get(
                "dependency_contract_sha256"
            ),
            "needed_form": dependency.get("needed_form"),
            "source_anchors": anchors,
        }
    raise ValueError("Cannot generate packet: issue contract kind is invalid")


def packet_issue_evidence_anchors(
    root: Path,
    spans: Any,
    members: list[tuple[Path, dict[str, Any]]],
) -> list[dict[str, Any]]:
    if not isinstance(spans, list):
        return []
    return [
        packet_issue_locked_anchor(
            root,
            root,
            span,
            members,
            allow_locked_external=True,
        )
        for span in spans
        if isinstance(span, dict)
    ]


def packet_issue_premise_origin(
    root: Path,
    ledger_path: Path,
    ledger: dict[str, Any],
    step: dict[str, Any],
    premise: dict[str, Any],
    members: list[tuple[Path, dict[str, Any]]],
) -> dict[str, Any]:
    origin = premise.get("origin")
    if not isinstance(origin, dict):
        raise ValueError("Cannot generate packet: issue premise origin is missing")
    kind = origin.get("kind")
    reference = origin.get("reference")
    projected: dict[str, Any] = {
        "kind": kind,
        "reference": reference,
    }
    if kind == "obligation":
        anchor = origin.get("anchor")
        anchor = anchor if isinstance(anchor, dict) else {}
        anchor_field = {
            "statement_span": "statement_spans",
            "context_span": "context_spans",
        }.get(anchor.get("kind"))
        anchor_index = anchor.get("index")
        spans = (
            ledger.get("obligation", {}).get(anchor_field, [])
            if isinstance(anchor_field, str)
            else []
        )
        if (
            not isinstance(spans, list)
            or not is_int(anchor_index)
            or anchor_index < 1
            or anchor_index > len(spans)
        ):
            raise ValueError(
                "Cannot generate packet: issue premise obligation anchor is invalid"
            )
        projected["anchor"] = {
            "kind": anchor.get("kind"),
            "index": anchor_index,
            "source": packet_issue_locked_anchor(
                root, ledger_path.parent, spans[anchor_index - 1], members
            ),
        }
    elif kind == "prior_step":
        prior_step = next(
            (
                row
                for row in ledger.get("steps", [])
                if isinstance(row, dict) and row.get("id") == reference
            ),
            None,
        )
        if not isinstance(prior_step, dict):
            raise ValueError(
                "Cannot generate packet: issue premise prior step is unresolved"
            )
        projected["source"] = packet_issue_step_anchor(
            root, ledger_path, ledger, prior_step, members
        )
    elif kind in {"internal_result", "external_result"}:
        step_dependencies = step.get("dependencies")
        step_dependencies = (
            step_dependencies if isinstance(step_dependencies, list) else []
        )
        dependencies = [
            row
            for row in step_dependencies
            if isinstance(row, dict)
            and row.get("use_id") == reference
        ]
        if len(dependencies) != 1:
            raise ValueError(
                "Cannot generate packet: issue premise dependency is unresolved"
            )
        dependency = dependencies[0]
        projected.update(
            {
                "use_id": dependency.get("use_id"),
                "dependency_id": dependency.get("id"),
                "dependency_conclusion_id": dependency.get("conclusion_id"),
                "needed_form": dependency.get("needed_form"),
            }
        )
    else:
        raise ValueError("Cannot generate packet: issue premise origin kind is invalid")
    if is_nonempty_string(premise.get("source_reference_id")):
        projected["source_reference"] = {
            "target": premise.get("source_reference_id"),
            "occurrence_id": premise.get("source_reference_occurrence_id"),
        }
    return projected


def packet_issue_origin_target(
    root: Path,
    issue: dict[str, Any],
    records: dict[str, Any],
    members: list[tuple[Path, dict[str, Any]]],
) -> dict[str, Any]:
    origin = issue.get("origin_ref")
    resolution = issue.get("current_resolution")
    if issue.get("status") == "resolved":
        if (
            isinstance(resolution, dict)
            and isinstance(resolution.get("current_ref"), dict)
        ):
            origin = resolution["current_ref"]
        elif (
            isinstance(resolution, dict)
            and resolution.get("disposition") == "removed"
        ):
            archive_errors: list[str] = []
            archive = load_resolution_archive(issue, root, archive_errors)
            if archive is None or archive_errors:
                raise ValueError(
                    "Cannot generate packet: removed issue archive is invalid: "
                    + "; ".join(archive_errors[:8])
                )
            archived_issue = archive.get("issue_record")
            archived_issue = (
                archived_issue if isinstance(archived_issue, dict) else {}
            )
            original_identity = canonical_issue_ref_identity(
                archived_issue.get("origin_ref")
            )
            retired = resolution.get("retired_dependency_uses")
            retired = retired if isinstance(retired, list) else []
            anchors = packet_issue_evidence_anchors(
                root, resolution.get("evidence_spans"), members
            )
            if not anchors:
                raise ValueError(
                    "Cannot generate packet: removed issue target lacks current "
                    "source evidence"
                )
            return {
                "kind": "current_absence",
                "archived_reference_identity_sha256": canonical_sha256(
                    original_identity
                ),
                "affected_result": issue.get("affected_result"),
                "retired_dependency_use_ids": sorted(
                    str(row.get("use_id"))
                    for row in retired
                    if isinstance(row, dict)
                    and is_nonempty_string(row.get("use_id"))
                ),
                "source_anchors": anchors,
            }
        else:
            raise ValueError(
                "Cannot generate packet: resolved issue has no current target"
            )
    if not isinstance(origin, dict):
        raise ValueError("Cannot generate packet: issue origin is malformed")
    kind = origin.get("kind")
    reference = canonical_issue_ref_identity(origin)
    if kind == "ledger_move":
        ledger_path, ledger = packet_issue_ledger(root, origin.get("unit_id"))
        step = next(
            (
                row
                for row in ledger.get("steps", [])
                if isinstance(row, dict)
                and row.get("id") == origin.get("step_id")
            ),
            None,
        )
        moves = (
            step.get("inference", {}).get("moves", [])
            if isinstance(step, dict)
            and isinstance(step.get("inference"), dict)
            else []
        )
        matching_moves = [
            row
            for row in moves
            if isinstance(row, dict) and row.get("id") == origin.get("move_id")
        ]
        if not isinstance(step, dict) or len(matching_moves) != 1:
            raise ValueError(
                "Cannot generate packet: issue ledger-move origin is unresolved"
            )
        move = matching_moves[0]
        premise_ids = set(move.get("premise_ids", []))
        prior_move_ids = set(move.get("prior_move_ids", []))
        premise_rows = step.get("premise_uses")
        premise_rows = premise_rows if isinstance(premise_rows, list) else []
        return {
            "reference": reference,
            "source_anchor": packet_issue_step_anchor(
                root, ledger_path, ledger, step, members
            ),
            "goal": step.get("goal"),
            "claim": move.get("claim"),
            "rule": move.get("rule"),
            "premises": [
                {
                    "id": row.get("id"),
                    "role": row.get("role"),
                    "claim": row.get("claim"),
                    "origin": packet_issue_premise_origin(
                        root, ledger_path, ledger, step, row, members
                    ),
                }
                for row in premise_rows
                if isinstance(row, dict) and row.get("id") in premise_ids
            ],
            "prior_moves": [
                {"id": row.get("id"), "claim": row.get("claim")}
                for row in moves
                if isinstance(row, dict) and row.get("id") in prior_move_ids
            ],
        }
    if kind in {"obligation_pointer", "dependency_use"}:
        contract_ref = dict(origin)
        return packet_issue_contract_target(root, contract_ref, members)
    if kind == "interface_record":
        interface_id = origin.get("interface_id")
        registry = records.get("interface_registry")
        rows = registry.get("interfaces") if isinstance(registry, dict) else []
        matches = [
            row
            for row in rows
            if isinstance(row, dict) and row.get("id") == interface_id
        ] if isinstance(rows, list) else []
        if len(matches) != 1:
            raise ValueError(
                "Cannot generate packet: issue interface origin is unresolved"
            )
        interface = matches[0]
        target_relation = interface.get("target_relation")
        target_relation = (
            target_relation if isinstance(target_relation, dict) else {}
        )
        implementation = interface.get("implementation_relation")
        implementation = implementation if isinstance(implementation, dict) else {}
        comparisons = implementation.get("comparisons")
        comparisons = comparisons if isinstance(comparisons, list) else []
        provenance = implementation.get("execution_provenance")
        provenance = provenance if isinstance(provenance, dict) else {}
        sample_laws = interface.get("fitting_sample_laws")
        sample_laws = sample_laws if isinstance(sample_laws, list) else []
        return {
            "reference": reference,
            "kind": interface.get("kind"),
            "affected_results": interface.get("affected_results"),
            "implementation_required_for_claim": interface.get(
                "implementation_required_for_claim"
            ),
            "execution_provenance_required_for_claim": interface.get(
                "execution_provenance_required_for_claim"
            ),
            "population_target": interface.get("population_target"),
            "identification_identity": interface.get(
                "identification_identity"
            ),
            "fitting_sample_laws": [
                {
                    "role": row.get("role"),
                    "law": row.get("law"),
                    "reference_law": row.get("reference_law"),
                    "source_anchors": packet_issue_evidence_anchors(
                        root, row.get("evidence_spans"), members
                    ),
                }
                for row in sample_laws
                if isinstance(row, dict)
            ],
            "marginal_relationships": interface.get(
                "marginal_relationships"
            ),
            "evaluation_sites": interface.get("evaluation_sites"),
            "downstream_uses": interface.get("downstream_uses"),
            "target_assumptions": target_relation.get("assumptions"),
            "target_source_anchors": packet_issue_evidence_anchors(
                root, target_relation.get("evidence_spans"), members
            ),
            "implementation_revision": implementation.get("revision"),
            "implementation_source_anchors": packet_issue_evidence_anchors(
                root, implementation.get("evidence_spans"), members
            ),
            "comparison_targets": [
                {
                    "to": row.get("to"),
                    "source_anchors": packet_issue_evidence_anchors(
                        root, row.get("evidence_spans"), members
                    ),
                }
                for row in comparisons
                if isinstance(row, dict)
            ],
            "execution_source_anchors": packet_issue_evidence_anchors(
                root, provenance.get("evidence_spans"), members
            ),
            "origin_source_anchors": packet_issue_evidence_anchors(
                root, origin.get("evidence_spans"), members
            ),
        }
    if kind == "global_check":
        completion = records["manifest"].get("completion")
        global_pass = (
            completion.get("global_consistency_pass")
            if isinstance(completion, dict)
            else None
        )
        rows = global_pass.get("checks") if isinstance(global_pass, dict) else []
        matches = [
            row
            for row in rows
            if isinstance(row, dict) and row.get("aspect") == origin.get("aspect")
        ] if isinstance(rows, list) else []
        if len(matches) != 1:
            raise ValueError(
                "Cannot generate packet: issue global-check origin is unresolved"
            )
        return {
            "reference": reference,
            "aspect": matches[0].get("aspect"),
            "affected_units": matches[0].get("affected_units"),
            "source_anchors": packet_issue_evidence_anchors(
                root, origin.get("evidence_spans"), members
            ),
        }
    raise ValueError("Cannot generate packet: issue origin kind is invalid")


def packet_issue_propagation(
    root: Path,
    issue: dict[str, Any],
    registry: dict[str, Any],
    members: list[tuple[Path, dict[str, Any]]],
    challenged_unit: str,
    *,
    pending_step_anchor_unit: str | None = None,
) -> dict[str, Any]:
    affected = {
        str(value)
        for value in issue.get("affected_results", [])
        if is_nonempty_string(value)
    }
    internal_rows = registry.get("internal_uses")
    internal_rows = internal_rows if isinstance(internal_rows, list) else []
    external_results = registry.get("external_results")
    external_results = (
        external_results if isinstance(external_results, list) else []
    )
    root_result = issue.get("affected_result")
    if challenged_unit == root_result:
        return {
            "root_affected_result": root_result,
            "challenged_unit": challenged_unit,
            "uses": [],
        }
    historical = issue.get("historical_origin")
    historical_challenges = (
        historical.get("required_challenges", [])
        if isinstance(historical, dict)
        else []
    )
    if (
        issue.get("status") == "resolved"
        and challenged_unit in historical_challenges
        and challenged_unit not in affected
    ):
        resolution = issue.get("current_resolution")
        if not isinstance(resolution, dict):
            raise ValueError(
                "Cannot generate packet: historical challenge lacks current "
                "resolution evidence"
            )
        retired_rows = resolution.get("retired_dependency_uses")
        retired_rows = retired_rows if isinstance(retired_rows, list) else []
        retired = sorted(
            (
                {
                    "use_id": row.get("use_id"),
                    "prior_edge_sha256": row.get("prior_edge_sha256"),
                }
                for row in retired_rows
                if isinstance(row, dict)
                and is_nonempty_string(row.get("use_id"))
            ),
            key=lambda row: str(row.get("use_id", "")),
        )
        if not retired:
            raise ValueError(
                "Cannot generate packet: historical challenge has no retired "
                "dependency-use identity"
            )
        archived_errors: list[str] = []
        archive = load_resolution_archive(issue, root, archived_errors)
        if archive is None or archived_errors:
            raise ValueError(
                "Cannot generate packet: historical challenge archive is invalid: "
                + "; ".join(archived_errors[:8])
            )
        prior_artifacts = archive.get("prior_artifacts")
        prior_artifacts = (
            prior_artifacts if isinstance(prior_artifacts, dict) else {}
        )
        registry_errors: list[str] = []
        decoded_registry = sealed_json_object(
            prior_artifacts.get("dependency_registry"),
            "historical challenge prior dependency registry",
            registry_errors,
        )
        if decoded_registry is None or registry_errors:
            raise ValueError(
                "Cannot generate packet: historical dependency registry is "
                "invalid: " + "; ".join(registry_errors[:8])
            )
        _, _, prior_registry = decoded_registry
        prior_internal = prior_registry.get("internal_uses")
        prior_internal = prior_internal if isinstance(prior_internal, list) else []
        archived_issue = archive.get("issue_record")
        archived_issue = archived_issue if isinstance(archived_issue, dict) else {}
        archived_affected = {
            str(value)
            for value in archived_issue.get("affected_results", [])
            if is_nonempty_string(value)
        }
        archived_hashes = {
            str(row.get("use_id")): row.get("edge_sha256")
            for row in archive.get("required_closure", {}).get(
                "dependency_uses", []
            )
            if isinstance(row, dict)
            and is_nonempty_string(row.get("use_id"))
        }
        retired_by_id = {str(row["use_id"]): row for row in retired}
        if len(retired_by_id) != len(retired):
            raise ValueError(
                "Cannot generate packet: historical challenge has duplicate "
                "retired dependency-use identities"
            )
        for use_id, row in retired_by_id.items():
            if row.get("prior_edge_sha256") != archived_hashes.get(use_id):
                raise ValueError(
                    "Cannot generate packet: retired dependency-use identity "
                    f"{use_id} disagrees with the sealed archive"
                )
        current_dependency_edges = [
            row for row in internal_rows if isinstance(row, dict)
        ]
        for result in external_results:
            if not isinstance(result, dict):
                continue
            uses = result.get("uses")
            if not isinstance(uses, list):
                continue
            current_dependency_edges.extend(
                row for row in uses if isinstance(row, dict)
            )
        current_issue_use_ids = {
            str(row.get("use_id"))
            for row in issue_recheck_edges(issue, current_dependency_edges)
            if is_nonempty_string(row.get("use_id"))
        }
        still_present = sorted(
            row["use_id"]
            for row in retired
            if row["use_id"] in current_issue_use_ids
        )
        if still_present:
            raise ValueError(
                "Cannot generate packet: retired issue dependency uses remain "
                "in the current issue closure: " + ", ".join(still_present)
            )
        prior_path_rows = [
            row
            for row in prior_internal
            if isinstance(row, dict)
            and row.get("dependency_id") in archived_affected
            and row.get("dependent_unit") in archived_affected
        ]
        forward = {str(root_result)}
        changed = True
        while changed:
            changed = False
            for row in prior_path_rows:
                if (
                    row.get("dependency_id") in forward
                    and row.get("dependent_unit") not in forward
                ):
                    forward.add(str(row.get("dependent_unit")))
                    changed = True
        reverse = {challenged_unit}
        changed = True
        while changed:
            changed = False
            for row in prior_path_rows:
                if (
                    row.get("dependent_unit") in reverse
                    and row.get("dependency_id") not in reverse
                ):
                    reverse.add(str(row.get("dependency_id")))
                    changed = True
        prior_path = [
            row
            for row in prior_path_rows
            if row.get("dependency_id") in forward
            and row.get("dependent_unit") in reverse
        ]
        if challenged_unit not in forward or not prior_path:
            raise ValueError(
                "Cannot generate packet: sealed historical propagation path "
                "to challenged unit is unresolved"
            )
        retired_path_edges: list[dict[str, Any]] = []
        for edge in prior_path:
            use_id = str(edge.get("use_id"))
            retirement = retired_by_id.get(use_id)
            if retirement is None:
                continue
            edge_sha256 = str(retirement.get("prior_edge_sha256"))
            retired_path_edges.append(
                {
                    "kind": "internal_result",
                    "use_id": edge.get("use_id"),
                    "prior_edge_sha256": edge_sha256,
                    "dependency_id": edge.get("dependency_id"),
                    "dependency_conclusion_id": edge.get(
                        "dependency_conclusion_id"
                    ),
                    "dependent_unit": edge.get("dependent_unit"),
                    "needed_form": edge.get("needed_form"),
                    "dependency_conclusion": edge.get(
                        "dependency_conclusion"
                    ),
                    "dependency_contract_sha256": edge.get(
                        "dependency_contract_sha256"
                    ),
                    "step_ids": sorted(
                        str(value)
                        for value in edge.get("step_ids", [])
                        if is_nonempty_string(value)
                    ),
                }
            )
        if not retired_path_edges:
            raise ValueError(
                "Cannot generate packet: no retired dependency use cuts the "
                "sealed historical path to the challenged unit"
            )
        current_path_rows = [
            row
            for row in internal_rows
            if isinstance(row, dict)
            and is_nonempty_string(row.get("dependency_id"))
            and is_nonempty_string(row.get("dependent_unit"))
        ]
        current_forward = {str(root_result)}
        changed = True
        while changed:
            changed = False
            for row in current_path_rows:
                if (
                    row.get("dependency_id") in current_forward
                    and row.get("dependent_unit") not in current_forward
                ):
                    current_forward.add(str(row.get("dependent_unit")))
                    changed = True
        current_reverse = {challenged_unit}
        changed = True
        while changed:
            changed = False
            for row in current_path_rows:
                if (
                    row.get("dependent_unit") in current_reverse
                    and row.get("dependency_id") not in current_reverse
                ):
                    current_reverse.add(str(row.get("dependency_id")))
                    changed = True
        current_selected = [
            row
            for row in current_path_rows
            if row.get("dependency_id") in current_forward
            and row.get("dependent_unit") in current_reverse
        ]
        current_route_uses: list[dict[str, Any]] = []
        if challenged_unit in current_forward:
            for row in current_selected:
                dependent_unit = str(row.get("dependent_unit"))
                source_anchors: list[dict[str, Any]] = []
                if dependent_unit != pending_step_anchor_unit:
                    ledger_path, ledger = packet_issue_ledger(root, dependent_unit)
                    for step_id in row.get("step_ids", []):
                        step = next(
                            (
                                value
                                for value in ledger.get("steps", [])
                                if isinstance(value, dict)
                                and value.get("id") == step_id
                            ),
                            None,
                        )
                        if not isinstance(step, dict):
                            raise ValueError(
                                "Cannot generate packet: current historical "
                                "challenge route step is unresolved"
                            )
                        source_anchors.append(
                            packet_issue_step_anchor(
                                root, ledger_path, ledger, step, members
                            )
                        )
                current_route_uses.append(
                    {
                        "kind": "internal_result",
                        "use_id": row.get("use_id"),
                        "dependency_id": row.get("dependency_id"),
                        "dependency_conclusion_id": row.get(
                            "dependency_conclusion_id"
                        ),
                        "dependent_unit": dependent_unit,
                        "needed_form": row.get("needed_form"),
                        "dependency_conclusion": row.get(
                            "dependency_conclusion"
                        ),
                        "dependency_contract_sha256": row.get(
                            "dependency_contract_sha256"
                        ),
                        "source_anchors": source_anchors,
                    }
                )
        anchors = packet_issue_evidence_anchors(
            root, resolution.get("evidence_spans"), members
        )
        if not anchors:
            raise ValueError(
                "Cannot generate packet: historical challenge lacks current "
                "retirement source evidence"
            )
        return {
            "root_affected_result": root_result,
            "challenged_unit": challenged_unit,
            "uses": [],
            "current_route": {
                "path_present": challenged_unit in current_forward,
                "uses": sorted(
                    current_route_uses,
                    key=lambda row: (
                        str(row.get("dependent_unit", "")),
                        str(row.get("use_id", "")),
                    ),
                ),
            },
            "retirement": {
                "kind": "historical_path_retirement",
                "archived_reference_identity_sha256": canonical_sha256(
                    canonical_issue_ref_identity(archived_issue.get("origin_ref"))
                ),
                "retired_path_edges": sorted(
                    retired_path_edges,
                    key=lambda row: (
                        str(row.get("dependent_unit", "")),
                        str(row.get("use_id", "")),
                    ),
                ),
                "current_issue_closure_absent_use_ids": sorted(
                    str(row.get("use_id")) for row in retired_path_edges
                ),
                "current_resolution_source_anchors": anchors,
            },
        }
    internal_path_rows = [
        row
        for row in internal_rows
        if isinstance(row, dict)
        and row.get("dependency_id") in affected
        and row.get("dependent_unit") in affected
    ]
    forward = {str(root_result)}
    changed = True
    while changed:
        changed = False
        for row in internal_path_rows:
            if (
                row.get("dependency_id") in forward
                and row.get("dependent_unit") not in forward
            ):
                forward.add(str(row.get("dependent_unit")))
                changed = True
    reverse = {challenged_unit}
    changed = True
    while changed:
        changed = False
        for row in internal_path_rows:
            if (
                row.get("dependent_unit") in reverse
                and row.get("dependency_id") not in reverse
            ):
                reverse.add(str(row.get("dependency_id")))
                changed = True
    selected_rows = [
        row
        for row in internal_path_rows
        if row.get("dependency_id") in forward
        and row.get("dependent_unit") in reverse
    ]
    if challenged_unit not in forward or not selected_rows:
        raise ValueError(
            "Cannot generate packet: issue propagation path to challenged unit "
            "is unresolved"
        )
    projected: list[dict[str, Any]] = []
    for row in selected_rows:
        dependency_id = row.get("dependency_id")
        dependent_unit = row.get("dependent_unit")
        source_anchors: list[dict[str, Any]] = []
        if dependent_unit != pending_step_anchor_unit:
            ledger_path, ledger = packet_issue_ledger(root, dependent_unit)
            for step_id in row.get("step_ids", []):
                step = next(
                    (
                        value
                        for value in ledger.get("steps", [])
                        if isinstance(value, dict) and value.get("id") == step_id
                    ),
                    None,
                )
                if not isinstance(step, dict):
                    raise ValueError(
                        "Cannot generate packet: issue propagation step is unresolved"
                    )
                source_anchors.append(
                    packet_issue_step_anchor(
                        root, ledger_path, ledger, step, members
                    )
                )
        projected.append(
            {
                "kind": "internal_result",
                "use_id": row.get("use_id"),
                "dependency_id": dependency_id,
                "dependency_conclusion_id": row.get(
                    "dependency_conclusion_id"
                ),
                "dependent_unit": dependent_unit,
                "needed_form": row.get("needed_form"),
                "dependency_conclusion": row.get("dependency_conclusion"),
                "dependency_contract_sha256": row.get(
                    "dependency_contract_sha256"
                ),
                "source_anchors": source_anchors,
            }
        )
    return {
        "root_affected_result": root_result,
        "challenged_unit": challenged_unit,
        "uses": sorted(
            projected,
            key=lambda row: (
                str(row.get("dependent_unit", "")),
                str(row.get("use_id", "")),
            ),
        ),
    }


def packet_issue_triggers(
    root: Path,
    manifest: dict[str, Any],
    unit_id: str,
    mode: str,
    *,
    records: dict[str, Any],
    members: list[tuple[Path, dict[str, Any]]],
    work_context_inputs_only: bool = False,
) -> list[dict[str, Any]]:
    _, issues, schema_version, errors = load_issue_log(root)
    if errors:
        raise ValueError("Cannot generate packet: " + "; ".join(errors))
    if schema_version != SCHEMA_VERSION:
        raise ValueError("Cannot generate packet: issue log must use current schema")
    seen: set[str] = set()
    for index, issue in enumerate(issues, 1):
        if not isinstance(issue, dict):
            raise ValueError(
                f"Cannot generate packet: issue record {index} must be an object"
            )
        issue_id = issue.get("id")
        if not isinstance(issue_id, str) or not ISSUE_ID_RE.fullmatch(issue_id):
            raise ValueError(
                f"Cannot generate packet: issue record {index} has an invalid ID"
            )
        if issue_id in seen:
            raise ValueError(f"Cannot generate packet: duplicate issue ID {issue_id}")
        seen.add(issue_id)
        if issue.get("severity") not in ISSUE_SEVERITIES:
            raise ValueError(f"Cannot generate packet: {issue_id} has invalid severity")
        if issue.get("status") not in ISSUE_STATUSES:
            raise ValueError(f"Cannot generate packet: {issue_id} has invalid status")
        if not isinstance(issue.get("load_bearing"), bool):
            raise ValueError(
                f"Cannot generate packet: {issue_id}.load_bearing must be boolean"
            )
        affected = issue.get("affected_results")
        if (
            not isinstance(affected, list)
            or not affected
            or not all(is_nonempty_string(value) for value in affected)
        ):
            raise ValueError(
                f"Cannot generate packet: {issue_id}.affected_results is invalid"
            )
        historical = issue.get("historical_origin")
        if isinstance(historical, dict):
            required = historical.get("required_challenges", [])
            if not isinstance(required, list) or not all(
                is_nonempty_string(value) for value in required
            ):
                raise ValueError(
                    f"Cannot generate packet: {issue_id} historical challenges are invalid"
                )
    selected: list[dict[str, Any]] = []
    required_challenge_issues: set[str] = set()
    if mode == "challenge":
        _, severe_by_unit = required_challenge_requirements(manifest, issues)
        required_challenge_issues = severe_by_unit.get(unit_id, set())
    for issue in issues:
        if not isinstance(issue, dict):
            continue
        if mode == "challenge":
            if issue.get("id") not in required_challenge_issues:
                continue
        else:
            affected = issue.get("affected_results")
            if not isinstance(affected, list) or unit_id not in affected:
                continue
        origin_ref = issue.get("origin_ref")
        if (
            work_context_inputs_only
            and isinstance(origin_ref, dict)
            and origin_ref.get("kind")
            in {"ledger_move", "obligation_pointer", "dependency_use"}
            and origin_ref.get("unit_id") == unit_id
        ):
            continue
        contract_refs = issue.get("contract_refs")
        affected_results = issue.get("affected_results")
        if (
            not isinstance(origin_ref, dict)
            or not isinstance(contract_refs, list)
            or not all(isinstance(row, dict) for row in contract_refs)
            or not isinstance(affected_results, list)
            or not all(
                is_nonempty_string(value) for value in affected_results
            )
        ):
            raise ValueError(
                "Cannot generate packet: "
                f"{issue.get('id')} lacks a structured target contract"
            )
        contracts: list[dict[str, Any]] = []
        for row in contract_refs:
            if mode == "primary" and row.get("unit_id") == unit_id:
                contract = {
                    "reference": canonical_issue_ref_identity(row),
                    "status": "pending_current_unit",
                }
            else:
                contract = packet_issue_contract_target(root, row, members)
            contract["contract_sha256"] = canonical_sha256(contract)
            contracts.append(contract)
        contracts.sort(
            key=lambda contract: canonical_sha256(contract.get("reference"))
        )
        propagation = packet_issue_propagation(
            root,
            issue,
            records["dependency_registry"],
            members,
            unit_id,
            pending_step_anchor_unit=(unit_id if mode == "primary" else None),
        )
        target_contract = {
            "current_target": packet_issue_origin_target(
                root, issue, records, members
            ),
            "contracts": contracts,
            "propagation": propagation,
        }
        projected_issue = {
            "id": issue.get("id"),
            "target_contract": target_contract,
            "target_contract_sha256": canonical_sha256(target_contract),
        }
        if mode == "primary":
            projected_issue.update(
                {
                    "severity": issue.get("severity"),
                    "status": issue.get("status"),
                    "finding_status": issue.get("finding_status"),
                    "invalidation_kind": issue.get("invalidation_kind"),
                    "summary": issue.get("summary"),
                }
            )
        selected.append(projected_issue)
    return sorted(selected, key=lambda row: str(row.get("id", "")))


def packet_wip_resume(
    ledger: dict[str, Any] | None, ledger_path: Path | None
) -> dict[str, Any]:
    if not isinstance(ledger, dict):
        return {"included": False, "semantic_record": None}
    if not isinstance(ledger_path, Path) or not ledger_path.is_file():
        raise ValueError("Cannot project WIP without its canonical ledger file")
    return {
        "included": True,
        "ledger_sha256": sha256_file(ledger_path),
        "work_context_sha256": ledger.get("work_context_sha256"),
        "semantic_record": {
            "source_units": ledger.get("source_units"),
            "steps": ledger.get("steps"),
            "review": ledger.get("review"),
        },
    }


def packet_semantic_dependencies(value: Any) -> Any:
    """Keep dependency inputs while omitting deterministic or future mirrors."""
    if not isinstance(value, dict):
        return value
    projected = json.loads(json.dumps(value, ensure_ascii=False))
    for rows in projected.values():
        if not isinstance(rows, list):
            continue
        for row in rows:
            if isinstance(row, dict):
                row.pop("step_ids", None)
    for row in projected.get("downstream_internal_uses", []):
        if not isinstance(row, dict):
            continue
        for field in (
            "compatibility_check",
            "compatibility_checks",
            "status",
            "issue_ids",
            "statement_support_sha256",
            "statement_support_conditions",
            "statement_support_contract",
        ):
            row.pop(field, None)
    for result in projected.get("external_results", []):
        if not isinstance(result, dict):
            continue
        for row in result.get("uses", []):
            if isinstance(row, dict):
                row.pop("step_ids", None)
    return projected


def packet_relevant_source_projection(value: Any) -> Any:
    """Keep locked excerpts while separating whole-file provenance metadata."""
    if isinstance(value, list):
        return [packet_relevant_source_projection(item) for item in value]
    if not isinstance(value, dict):
        return value
    projected = {
        key: packet_relevant_source_projection(item) for key, item in value.items()
    }
    member = projected.get("source_member")
    if isinstance(member, dict):
        member.pop("file_sha256", None)
        member.pop("index", None)
    return projected


@gate_context_reader
def packet_shared_source_context_sha256(
    root: Path, paper: Path, members: list[tuple[Path, dict[str, Any]]]
) -> str:
    """Conservatively retain global prose, declarations, and local configuration.

    Fresh source indexing prevents an outdated inventory from hiding shared
    context. Only plain unrelated regions with ordinary structural delimiters
    are omitted. Any other command, including an indirect or unknown macro,
    retains the entire region so changed multi-line arguments also invalidate.
    Category changes, structural overrides, and unknown package/class effects
    disable exclusions throughout the closure, including apparently plain text.
    This is a conservative source closure, not a full TeX interpreter.
    """
    source_lines: dict[Path, list[str] | None] = {}
    configuration_uncertain = False
    structural_names = {"begin", "end", "label", "theorem", "lemma", "proposition",
                        "corollary", "claim", "fact", "proof"}
    structural_names.update("end" + name for name in tuple(structural_names))
    category_or_hook = re.compile(
        r"\\(?:catcode|mathcode|lccode|uccode|delcode|csname|scantokens|"
        r"every[A-Za-z]*|AtBegin[A-Za-z]*|AtEnd[A-Za-z]*|AddToHook|"
        r"BeforeBeginEnvironment|AfterEndEnvironment|pretocmd|apptocmd|patchcmd|"
        r"ExplSyntaxOn|usepackage|RequirePackage|documentclass|LoadClass|InputIfFileExists)\b")
    for path, _ in members:
        try:
            source_lines[path] = read_lines(path)
        except TextArtifactReadError:
            source_lines[path] = None
            configuration_uncertain = True
            continue
        text = "\n".join(source_lines[path])
        if path.suffix.lower() != ".tex" or "^^" in text or category_or_hook.search(text):
            configuration_uncertain = True
        for match in TEX_DEFINITION_COMMAND_RE.finditer(mask_tex_literals_for_definition_scan(text)):
            target = re.match(r"\s*\{?\s*\\([A-Za-z@]+)", text[match.end():])
            if (match.group("command") not in TEX_NEW_COMMAND_DEFINITIONS
                    or target is None or target.group(1) in structural_names):
                configuration_uncertain = True
    fresh_inventory = scan_formal_units(
        paper,
        source_files=[path for path, _ in members],
        path_identity_base=paper.parent,
    )
    owned: dict[Path, set[int]] = defaultdict(set)
    regions: dict[Path, list[tuple[int, int]]] = defaultdict(list)
    for unit in fresh_inventory.get("units", []):
        if (
            not isinstance(unit, dict)
            or str(unit.get("environment", "")).rstrip("*") in NON_PROOF_ENVIRONMENTS
            or not isinstance(unit.get("proof"), dict)
        ):
            # Assumptions, definitions, remarks, and unassociated statements
            # can govern other units even without an explicit result use.
            continue
        for field in ("statement", "proof"):
            span = unit.get(field) if isinstance(unit, dict) else None
            if not isinstance(span, dict) or not is_nonempty_string(span.get("file")):
                continue
            start, end = span.get("start_line"), span.get("end_line")
            if is_int(start) and is_int(end) and 1 <= start <= end:
                path = resolve_stored_path(span["file"], paper.parent)
                owned[path].update(range(start, end + 1))
                regions[path].append((start, end))
    shared: list[dict[str, Any]] = []
    for path, _ in members:
        try:
            relative = path.relative_to(root).as_posix()
        except ValueError:
            relative = path.relative_to(paper.parent).as_posix() if path.is_relative_to(paper.parent) else path.name
        lines = source_lines[path]
        if lines is None:
            # Source discovery still requires review of its decoding warning.
            # Retain every byte in work identity even when text is unavailable.
            shared.append({"file": relative, "unreadable_text_sha256": sha256_file(path)})
            continue
        text = "\n".join(lines)
        definition_lines: set[int] = set()
        if path.suffix.lower() == ".tex":
            for first, last in regions[path]:
                region = "\n".join(lines[first - 1:last])
                plain = re.sub(r"\\(?:begin|end)\{(?:theorem|lemma|proposition|corollary|claim|fact|proof)\*?\}|\\label\{[A-Za-z0-9:_./-]+\}", "", region)
                if "\\" in plain or "^^" in plain or plain.count("{") != plain.count("}"):
                    definition_lines.update(range(first, last + 1))
            definition_scan = mask_tex_literals_for_definition_scan(text)
            for match in TEX_DEFINITION_COMMAND_RE.finditer(definition_scan):
                end = tex_definition_end(definition_scan, match)
                # An unparsed declaration conservatively retains the rest of
                # its file, rather than assuming its effects are local.
                end = len(text) if end is None else end
                first = text.count("\n", 0, match.start()) + 1
                last = text.count("\n", 0, end) + 1
                definition_lines.update(range(first, last + 1))
        selected = [
            line for number, line in enumerate(lines, 1)
            if configuration_uncertain or path.suffix.lower() != ".tex"
            or number not in owned[path]
            or number in definition_lines
        ]
        if selected:
            shared.append({"file": relative, "text": selected})
    return canonical_sha256(shared)


def context_packet_semantic_projection(packet: dict[str, Any]) -> dict[str, Any]:
    """Project only fields that can change a unit's semantic audit judgment."""
    projected = {
        key: value
        for key, value in packet.items()
        if key
        not in {
            "resume",
            "operational_binding",
            "operational_binding_sha256",
            "source_snapshot_sha256",
        }
    }
    projected["dependencies"] = packet_semantic_dependencies(
        packet.get("dependencies")
    )
    projected = packet_relevant_source_projection(projected)
    binding = projected.get("context_binding")
    if isinstance(binding, dict):
        binding.pop("source_snapshot_sha256", None)
        projected["context_binding_sha256"] = canonical_sha256(binding)
    return projected


@gate_context_reader
def build_context_packet(
    root: Path, unit_id: str, mode: str, *, for_recompile: bool = False,
    dependency_registry_override: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Derive one portable model packet from current canonical audit state."""
    root = root.resolve()
    lock_error = migration_update_lock_error(root)
    if lock_error is not None:
        raise ValueError(lock_error)
    if mode not in {"primary", "challenge"}:
        raise ValueError("Packet mode must be primary or challenge")
    if for_recompile and mode != "primary":
        raise ValueError("packet --for-recompile requires --mode primary")
    records = load_workflow_records(root)
    # Submission validates an unpublished registry projection through the same
    # packet builder. No command-line input can select this internal override.
    if dependency_registry_override is not None:
        records["dependency_registry"] = dependency_registry_override
    manifest = records["manifest"]
    if manifest.get("schema_version") != SCHEMA_VERSION:
        raise ValueError(
            "Cannot generate packet: audit manifest schema is not current"
        )
    if not protocol_matches_current(manifest.get("protocol")):
        raise ValueError(
            "Cannot generate packet: recorded proofcheck protocol is stale; "
            "run revalidate-protocol first"
        )
    freshness_errors = source_snapshot_freshness_errors(root, manifest)
    if freshness_errors:
        raise ValueError(
            "Cannot generate packet from stale source state: "
            + "; ".join(freshness_errors)
        )
    calibration_receipt = current_calibration_receipt(root)
    inventory = records["inventory"]
    units = inventory.get("units")
    if not isinstance(units, list):
        raise ValueError("Cannot generate packet: inventory units are missing")
    matches = [
        unit
        for unit in units
        if isinstance(unit, dict) and unit.get("id") == unit_id
    ]
    if len(matches) != 1:
        raise ValueError(
            f"Cannot generate packet: unknown or duplicate unit {unit_id}"
        )
    unit = matches[0]
    paper_value = manifest.get("paper_file")
    if not is_nonempty_string(paper_value):
        raise ValueError("Cannot generate packet: manifest paper_file is missing")
    paper = resolve_stored_path(str(paper_value), root)
    members = packet_source_members(root, manifest)
    statement = packet_span(root, paper.parent, unit.get("statement"), members)
    proof = packet_span(root, paper.parent, unit.get("proof"), members)
    label_owners = inventory.get("label_owners")
    if not isinstance(label_owners, dict):
        raise ValueError("Cannot generate packet: inventory label_owners is malformed")
    reviewed_occurrences = reviewed_unit_reference_occurrences(
        unit, paper.parent, label_owners
    )
    candidate_paths = packet_candidate_dependency_paths(
        inventory,
        unit,
        paper.parent,
        root,
        members,
        reviewed_occurrences,
    )
    packet_cross_references = scan_cross_references(
        paper,
        source_files=[path for path, _ in members],
        source_warnings=[],
        path_identity_base=paper.parent,
    )
    downstream_use_sites = packet_downstream_use_sites(
        inventory,
        unit,
        packet_cross_references,
        paper.parent,
        root,
        members,
    )
    ledger_path, ledger = packet_ledger(root, unit_id)
    skeleton_path, skeleton = packet_skeleton(root, unit_id)
    semantic_path = ledger_path
    semantic_artifact = ledger
    semantic_kind = "canonical_ledger" if ledger is not None else None
    if for_recompile:
        if skeleton_path is None or skeleton is None:
            raise ValueError(
                "packet --for-recompile requires exactly one current canonical "
                "source-locked skeleton"
            )
        validate_compile_skeleton(skeleton, skeleton_path)
    if mode == "primary" and (for_recompile or semantic_artifact is None):
        semantic_path = skeleton_path
        semantic_artifact = skeleton
        semantic_kind = "source_locked_skeleton" if skeleton is not None else None
    readiness = packet_semantic_readiness(
        semantic_path, semantic_artifact, unit_id
    )
    inventory_binding_errors = packet_inventory_binding_errors(
        paper.parent, unit, semantic_path, semantic_artifact
    )
    if inventory_binding_errors:
        readiness = {
            "ready": False,
            "reasons": [
                *readiness["reasons"],
                "The semantic artifact disagrees with the reviewed inventory source binding.",
            ],
        }
    workflow_registry_rows(records["dependency_registry"])
    dependency_structure_errors = packet_dependency_structure_errors(
        records["dependency_registry"], root
    )
    if dependency_structure_errors:
        raise ValueError(
            "Cannot generate packet from malformed dependency contracts: "
            + "; ".join(dependency_structure_errors[:12])
        )
    dependency_mapping_ready, dependency_context_errors = (
        workflow_dependency_mapping_readiness(records)
    )
    primary_record_errors: list[str] = []
    primary_record_ready = False
    wip_validation_errors: list[str] = []
    wip_local_record_ready = False
    if ledger_path is not None:
        primary_record_errors, primary_summary = check_ledger_data(
            ledger_path, True, primary_only=True
        )
        if primary_summary:
            unit_inventory = {row["id"]: row for row in units
                              if isinstance(row, dict) and is_nonempty_string(row.get("id"))}
            validate_primary_reference_roles(
                unit_id, unit, primary_summary, reviewed_occurrences,
                unit_inventory, paper.parent, primary_record_errors,
            )
            validate_primary_candidate_references(
                root, inventory, unit_id, unit, primary_summary, unit_inventory,
                paper.parent, reviewed_occurrences, members,
                records["dependency_registry"].get("internal_uses", []),
                primary_record_errors, candidate_paths=candidate_paths,
            )
        primary_record_ready = not primary_record_errors
        wip_validation_errors, _ = check_ledger_data(ledger_path, False)
        wip_local_record_ready = not wip_validation_errors
    source = {"statement": statement, "proof": proof}
    if isinstance(semantic_artifact, dict) and isinstance(semantic_artifact.get("source_fragments"), dict):
        source["coverage"] = {
            "version": semantic_artifact["source_fragments"]["version"],
            "indexing": "ordered_source_lines",
            "instruction": "Annotation lines are coverage positions. Use the original source spans below for manuscript locations; check every included physical line.",
            "fragments": [{
                "positions": [fragment["sequence_start"], fragment["sequence_end"]],
                "source": packet_span(root, semantic_path.parent, fragment, members, expand_inclusions=False),
            } for fragment in semantic_artifact["source_fragments"]["fragments"]],
        }
    snapshot = manifest.get("source_snapshot")
    source_snapshot_id = (
        snapshot.get("sha256") if isinstance(snapshot, dict) else None
    )
    progress = records["progress"]
    obligation_value = (
        semantic_artifact.get("obligation")
        if isinstance(semantic_artifact, dict)
        else None
    )
    obligation_digest = (
        canonical_sha256(obligation_value)
        if readiness["ready"] and isinstance(obligation_value, dict)
        else None
    )
    source_binding_sha256 = canonical_sha256(packet_relevant_source_projection(source))
    source_context_sha256 = packet_shared_source_context_sha256(root, paper, members)
    dependency_projection = packet_dependency_projection(
        records["dependency_registry"],
        root,
        unit_id,
        mode,
        semantic_artifact,
    )
    alignment_dependency_projection = (
        dependency_projection
        if mode == "primary"
        else packet_dependency_projection(
            records["dependency_registry"],
            root,
            unit_id,
            "primary",
            semantic_artifact,
        )
    )
    candidate_reconciliation = packet_candidate_reconciliation(
        unit,
        records["dependency_registry"],
        semantic_artifact,
        candidate_paths,
    )
    dependency_alignment = packet_dependency_alignment(
        semantic_artifact,
        alignment_dependency_projection,
        primary_record_ready=primary_record_ready,
    )
    alignment_ready = (
        not primary_record_ready
        or dependency_alignment["status"] == "complete"
    )
    dependency_context_ready = (
        dependency_mapping_ready
        and candidate_reconciliation["status"] == "complete"
        and alignment_ready
    )
    primary_work_packet_ready = readiness["ready"] and dependency_mapping_ready
    semantic_review_ready = readiness["ready"] and dependency_context_ready
    semantic_review_reasons = list(readiness["reasons"])
    if not dependency_mapping_ready:
        semantic_review_reasons.append(
            "The dependency registry review is incomplete or stale."
        )
    if candidate_reconciliation["status"] != "complete":
        semantic_review_reasons.append(
            "Candidate internal dependencies still require semantic reconciliation."
        )
    if not alignment_ready:
        semantic_review_reasons.append(
            "The primary ledger direct dependencies disagree with the registry."
        )
    if mode == "challenge":
        if ledger is None:
            raise ValueError(
                "Challenge packet requires exactly one current canonical proof-unit ledger"
            )
        if not semantic_review_ready:
            raise ValueError(
                "Challenge packet requires current source, obligation, and dependency "
                "context: " + "; ".join(semantic_review_reasons)
            )
        if not primary_record_ready:
            raise ValueError(
                "Challenge packet requires a locally final primary ledger: "
                + "; ".join(primary_record_errors[:8])
            )
    issue_triggers = packet_issue_triggers(
        root,
        manifest,
        unit_id,
        mode,
        records=records,
        members=members,
    )
    issue_path, _, _, _ = load_issue_log(root)
    semantic_artifact_projection = {
        "kind": semantic_kind,
        "audit_relative_file": (
            semantic_path.relative_to(root).as_posix()
            if semantic_path is not None
            else None
        ),
        "primary_ledger_sha256": (
            canonical_primary_ledger_sha256(ledger)
            if primary_record_ready and isinstance(ledger, dict)
            else None
        ),
    }
    obligation_projection = packet_obligation(
        obligation_value,
        root,
        semantic_path.parent if semantic_path is not None else root,
        {
            "statement": unit.get("statement"),
            "proof": unit.get("proof"),
        },
        paper.parent,
        mode=mode,
    )
    work_obligation_projection = (
        packet_obligation(
            obligation_value,
            root,
            semantic_path.parent if semantic_path is not None else root,
            {"statement": unit.get("statement"), "proof": unit.get("proof")},
            paper.parent,
            mode="primary",
        )
        if mode == "challenge"
        else obligation_projection
    )
    inventory_projection = packet_inventory_projection(
        unit,
        candidate_paths,
        downstream_use_sites,
        reviewed_occurrences,
    )
    candidate_projection = packet_candidate_reconciliation_projection(
        candidate_reconciliation, mode
    )
    alignment_projection = (
        dependency_alignment
        if mode == "primary"
        else {"status": "registry_contracts_bound"}
    )
    work_context_sha256: str | None = None
    wip_record_ready = False
    wip_reuse_errors: list[str] = []
    primary_issue_inputs = packet_issue_triggers(
        root,
        manifest,
        unit_id,
        "primary",
        records=records,
        members=members,
        work_context_inputs_only=True,
    )
    work_context = {
        "unit_id": unit_id,
        "protocol": context_protocol_identity(root, manifest),
        "source_context_sha256": source_context_sha256,
        "calibration_receipt_sha256": calibration_receipt["sha256"],
        "source_binding_sha256": source_binding_sha256,
        "obligation_sha256": obligation_digest,
        "obligation_projection_sha256": canonical_sha256(
            work_obligation_projection
        ),
        "inventory_projection_sha256": canonical_sha256(
            packet_relevant_source_projection(inventory_projection)
        ),
        "dependency_projection_sha256": canonical_sha256(
            packet_relevant_source_projection(
                packet_semantic_dependencies(alignment_dependency_projection)
            )
        ),
        "issue_triggers_sha256": canonical_sha256(
            packet_relevant_source_projection(primary_issue_inputs)
        ),
        "risk_aspects_sha256": canonical_sha256(list(RISK_ASPECTS)),
    }
    expected_work_context_sha256 = canonical_sha256(work_context)
    if mode == "primary":
        work_context_sha256 = expected_work_context_sha256
        wip_record_ready = bool(
            wip_local_record_ready
            and isinstance(ledger, dict)
            and ledger.get("work_context_sha256") == work_context_sha256
        )
        wip_reuse_errors = list(wip_validation_errors)
        if (
            ledger is not None
            and not primary_record_ready
            and wip_local_record_ready
            and not wip_record_ready
        ):
            wip_reuse_errors.append(
                "Partial ledger work_context_sha256 is missing or stale"
            )
    elif (
        not isinstance(ledger, dict)
        or ledger.get("work_context_sha256") != expected_work_context_sha256
    ):
        raise ValueError(
            "Challenge packet requires a primary ledger recompiled under the "
            "current calibration-bound work context"
        )
    readiness_projection = {
        "source_obligation_ready": readiness["ready"],
        "dependency_mapping_ready": dependency_mapping_ready,
        "dependency_context_ready": dependency_context_ready,
        "primary_work_packet_ready": primary_work_packet_ready,
        "primary_record_ready": primary_record_ready,
        "semantic_review_ready": semantic_review_ready,
        "semantic_review_reasons": semantic_review_reasons,
    }
    resume_projection: dict[str, Any] | None = None
    if mode == "primary":
        resume_projection = {
            "ledger_present": ledger is not None,
            "skeleton_present": skeleton is not None,
            "ledger_audit_relative_file": (
                ledger_path.relative_to(root).as_posix()
                if ledger_path
                else None
            ),
            "skeleton_audit_relative_file": (
                skeleton_path.relative_to(root).as_posix()
                if skeleton_path
                else None
            ),
            "progress_status": workflow_unit_status(unit_id, progress),
            "active_unit": progress.get("active_unit") == unit_id,
            "next_action": progress.get("next_action"),
            "wip": (
                packet_wip_resume(ledger, ledger_path)
                if ledger is not None
                and not primary_record_ready
                and wip_record_ready
                else {
                    "included": False,
                    "semantic_record": None,
                    "reason": (
                        "primary record is complete"
                        if primary_record_ready
                        else "partial ledger failed validation or context binding"
                        if ledger is not None
                        else "no partial canonical ledger"
                    ),
                }
            ),
            "wip_record_ready": wip_record_ready,
            "wip_validation_error_count": len(wip_reuse_errors),
        }
    context_binding = {
        "unit_id": unit_id,
        "mode": mode,
        "protocol_sha256": canonical_sha256(context_protocol_identity(root, manifest)),
        "source_snapshot_sha256": source_snapshot_id,
        "source_context_sha256": source_context_sha256,
        "calibration_receipt_sha256": calibration_receipt["sha256"],
        "source_binding_sha256": source_binding_sha256,
        "obligation_sha256": obligation_digest,
        "semantic_artifact_sha256": canonical_sha256(
            semantic_artifact_projection
        ),
        "obligation_projection_sha256": canonical_sha256(
            obligation_projection
        ),
        "inventory_projection_sha256": canonical_sha256(
            packet_relevant_source_projection(inventory_projection)
        ),
        "dependency_projection_sha256": canonical_sha256(
            packet_relevant_source_projection(
                packet_semantic_dependencies(dependency_projection)
            )
        ),
        "issue_triggers_sha256": canonical_sha256(
            packet_relevant_source_projection(issue_triggers)
        ),
        "candidate_reconciliation_sha256": canonical_sha256(
            candidate_projection
        ),
        "dependency_alignment_sha256": canonical_sha256(
            alignment_projection
        ),
        "risk_aspects_sha256": canonical_sha256(list(RISK_ASPECTS)),
        "readiness_sha256": canonical_sha256(readiness_projection),
    }
    if mode == "primary":
        context_binding.update(
            {
                "work_context_sha256": work_context_sha256,
            }
        )
    operational_binding = {
        "manifest_sha256": sha256_file(root / "AUDIT_MANIFEST.json"),
        "inventory_sha256": sha256_file(records["inventory_path"]),
        "dependency_registry_sha256": sha256_file(
            records["dependency_registry_path"]
        ),
        "issue_log_sha256": sha256_file(issue_path),
        "progress_sha256": sha256_file(root / "PROGRESS.json"),
        "semantic_artifact_file_sha256": (
            sha256_file(semantic_path)
            if semantic_path is not None and semantic_path.is_file()
            else None
        ),
        "readiness_sha256": canonical_sha256(readiness_projection),
        "resume_sha256": (
            canonical_sha256(resume_projection)
            if resume_projection is not None
            else None
        ),
    }
    packet: dict[str, Any] = {
        "schema_version": CONTEXT_PACKET_SCHEMA_VERSION,
        "challenge_contract_version": challenge_contract_version(manifest),
        "kind": "stat-paper-proofcheck-context-packet",
        "mode": mode,
        "unit_id": unit_id,
        "source_snapshot_sha256": source_snapshot_id,
        "source_context_sha256": source_context_sha256,
        "source_binding_sha256": source_binding_sha256,
        "context_binding": context_binding,
        "context_binding_sha256": canonical_sha256(context_binding),
        "operational_binding": operational_binding,
        "operational_binding_sha256": canonical_sha256(
            operational_binding
        ),
        **readiness_projection,
        "semantic_artifact": semantic_artifact_projection,
        "source": source,
        "obligation_sha256": obligation_digest,
        "obligation": obligation_projection,
        "inventory": inventory_projection,
        "candidate_dependency_reconciliation": candidate_projection,
        "dependency_alignment": alignment_projection,
        "dependencies": dependency_projection,
        "issue_triggers": issue_triggers,
        "risk_aspects": list(RISK_ASPECTS),
    }
    if resume_projection is not None:
        assert work_context_sha256 is not None
        packet["work_context_sha256"] = work_context_sha256
        packet["resume"] = resume_projection
    return packet


def cmd_packet(args: argparse.Namespace) -> int:
    configure_console_errors()
    root = args.root.resolve()
    output = args.output.resolve()
    if output.is_relative_to(root):
        raise ValueError("Packet output must be outside the canonical audit root")
    if output.exists() and not args.force:
        raise FileExistsError(f"Packet exists; use --force to replace it: {output}")
    if args.mode == "statement-support":
        if getattr(args, "for_recompile", False):
            raise ValueError("--for-recompile is available only for primary packets")
        packet = build_statement_support_packet(root, args.unit_id)
    else:
        packet = build_context_packet(
            root, args.unit_id, args.mode,
            for_recompile=bool(getattr(args, "for_recompile", False)),
        )
    _, manifest, manifest_errors = load_audit_manifest(root)
    if manifest_errors:
        raise ValueError("Cannot generate packet: " + "; ".join(manifest_errors))
    if output in {
        path for path, _ in packet_source_members(root, manifest)
    }:
        raise ValueError("Packet output must not overwrite a snapshotted source file")
    atomic_write_json(output, packet)
    print(
        json.dumps(
            {
                "command": "packet",
                "status": "written",
                "mode": args.mode,
                "unit_id": args.unit_id,
                "packet": str(output),
                "source_binding_sha256": packet.get("source_binding_sha256"),
            },
            ensure_ascii=True,
            indent=2,
        )
    )
    return 0


def challenge_input_projection(packet: dict[str, Any]) -> dict[str, Any]:
    """Blinded mathematical inputs, excluding reconciled primary output metadata."""
    binding = packet.get("context_binding") or {}
    return packet_relevant_source_projection({
        "unit_id": packet.get("unit_id"),
        "challenge_contract_version": packet.get("challenge_contract_version", 2),
        "protocol_sha256": binding.get("protocol_sha256"),
        "calibration_receipt_sha256": binding.get("calibration_receipt_sha256"),
        "source_context_sha256": packet.get("source_context_sha256"),
        **{
            field: packet.get(field)
            for field in (
                "source", "obligation", "inventory",
                "candidate_dependency_reconciliation", "issue_triggers", "risk_aspects",
            )
        },
        "dependencies": packet_semantic_dependencies(packet.get("dependencies")),
    })


def initial_challenge_reference(unit_id: str, input_sha256: str) -> str:
    return (
        "audit/05_adversarial/initial-"
        + canonical_sha256(unit_id)[:16] + "-" + input_sha256 + ".json"
    )


def challenge_source_spans(packet: dict[str, Any]) -> dict[str, dict[str, Any]]:
    """Index locked excerpts only in canonical mathematical packet sections."""
    spans: dict[str, dict[str, Any]] = {}

    def visit(value: Any, pointer: str) -> None:
        if isinstance(value, list):
            for index, item in enumerate(value):
                visit(item, f"{pointer}/{index}")
        elif isinstance(value, dict):
            lines = value.get("lines")
            identity = value.get("source_member", value.get("source"))
            digest = value.get("span_sha256", value.get("sha256"))
            start, end = value.get("start_line"), value.get("end_line")
            if (
                isinstance(identity, dict) and is_nonempty_string(identity.get("name"))
                and is_int(start) and is_int(end) and start >= 1 and end >= start
                and isinstance(lines, list) and len(lines) == end - start + 1
                and all(isinstance(row, dict) and row.get("line") == start + index
                        and isinstance(row.get("text"), str) for index, row in enumerate(lines))
                and digest == sha256_text("\n".join(row["text"] for row in lines))
            ):
                spans[pointer] = value
                if "fragments" not in value:
                    return
            for key, item in value.items():
                escaped = str(key).replace("~", "~0").replace("/", "~1")
                visit(item, f"{pointer}/{escaped}")

    for field in ("source", "dependencies", "issue_triggers"):
        visit(packet.get(field), f"/{field}")
    return spans


def primary_challenge_snapshot(ledger: dict[str, Any]) -> dict[str, Any]:
    """Preserve the actual pre-reconciliation position without guessing history."""
    review = ledger.get("review") or {}
    obligation = ledger.get("obligation") or {}
    claims = {row.get("id"): row.get("claim") for row in obligation.get("conclusions", [])
              if isinstance(row, dict)}
    steps = {row.get("id"): row for row in ledger.get("steps", []) if isinstance(row, dict)}
    rows = []
    for result in review.get("conclusion_results", []):
        if not isinstance(result, dict):
            continue
        support = result.get("support") or {}
        step = steps.get(support.get("step_id"), {})
        rows.append({
            "conclusion_id": result.get("conclusion_id"),
            "claim": claims.get(result.get("conclusion_id")),
            "argument_status": result.get("argument_status"),
            "statement_status": result.get("statement_status"),
            "verdict": step.get("status"),
            "support": json.loads(json.dumps(support)),
        })
    return {"unit_status": review.get("unit_status"), "conclusions": rows}


def initial_conclusion_reconciliation_errors(
    initial: dict[str, Any], ledger: dict[str, Any], challenge: dict[str, Any]
) -> list[str]:
    response = initial.get("response") or {}
    initial_rows = response.get("conclusions") or []
    if not isinstance(initial_rows, list) or any(not isinstance(row, dict) or not is_nonempty_string(row.get("conclusion_id")) for row in initial_rows):
        return ["Initial conclusions must be well-formed records with explicit IDs"]
    final = primary_challenge_snapshot(ledger)
    final_rows = final["conclusions"]
    expected_ids = [row.get("id") for row in (ledger.get("obligation") or {}).get("conclusions", [])
                    if isinstance(row, dict)]
    initial_ids = [row.get("conclusion_id") for row in initial_rows if isinstance(row, dict)]
    final_ids = [row.get("conclusion_id") for row in final_rows]
    if (not expected_ids or not all(is_nonempty_string(value) for value in expected_ids)
            or len(set(expected_ids)) != len(expected_ids)
            or sorted(initial_ids) != sorted(expected_ids) or sorted(final_ids) != sorted(expected_ids)):
        return ["Initial and final primary conclusions must contain the same IDs exactly once; renew changed obligations"]
    final_by_id = {row["conclusion_id"]: row for row in final_rows}
    fields = ("verdict", "argument_status", "statement_status") if response.get("response_schema_version") == 2 else ("verdict",)
    changed = [f"{row['conclusion_id']}.{field}" for row in initial_rows for field in fields
               if row.get(field) != final_by_id[row["conclusion_id"]].get(field)]
    before = initial.get("primary_snapshot")
    if isinstance(before, dict) and before != final:
        changed.append("primary pre-reconciliation judgment/support")
    if changed and (not challenge.get("disagreements") or not is_substantive_string(challenge.get("resolution"))):
        return ["Changed conclusion judgments require explicit disagreement and resolution: " + ", ".join(changed)]
    return []


def validate_initial_challenge_response(
    response: Any, packet: dict[str, Any]
) -> list[str]:
    """Require conclusion-specific judgments and exact packet source anchors."""
    errors: list[str] = []
    if not isinstance(response, dict):
        return ["Initial challenge response must be an object"]
    fields = {
        "response_schema_version", "unit_id", "independence_level",
        "challenger_verdict", "conclusions", "issue_assessments",
    }
    if set(response) != fields:
        errors.append("Initial challenge response needs exactly: " + ", ".join(sorted(fields)))
    required_version = 2 if packet.get("challenge_contract_version", 2) >= 3 else 1
    if type(response.get("response_schema_version")) is not int or response.get("response_schema_version") != required_version:
        errors.append(f"Initial challenge response_schema_version must be {required_version} for this challenge contract")
    if response.get("unit_id") != packet.get("unit_id"):
        errors.append("Initial challenge unit_id disagrees with its packet")
    if not is_enum_value(response.get("independence_level"), INDEPENDENCE_LEVELS - {"none"}):
        errors.append("Initial challenge needs a declared independence_level")
    if not is_enum_value(response.get("challenger_verdict"), UNIT_STATUSES - {"not_checked"}):
        errors.append("Initial challenge needs a checked challenger_verdict")
    obligation = packet.get("obligation") or {}
    expected_ids = [row.get("id") for row in obligation.get("conclusions", []) if isinstance(row, dict)]
    conclusions = response.get("conclusions")
    if not isinstance(conclusions, list):
        conclusions = []
        errors.append("Initial challenge conclusions must be a list")
    actual_ids: list[str] = []
    verdicts: list[str] = []
    canonical_spans = challenge_source_spans(packet)
    for index, row in enumerate(conclusions, 1):
        prefix = f"Initial challenge conclusions[{index}]"
        if not isinstance(row, dict):
            errors.append(f"{prefix} must be an object")
            continue
        conclusion_fields = {"conclusion_id", "verdict", "decisive_reason", "source_refs"}
        if required_version == 2:
            conclusion_fields.update({"argument_status", "statement_status"})
            if not is_enum_value(row.get("argument_status"), ARGUMENT_STATUSES - {"not_checked"}):
                errors.append(f"{prefix}.argument_status must be a checked argument judgment")
            if not is_enum_value(row.get("statement_status"), STATEMENT_STATUSES - {"not_assessed"}):
                errors.append(f"{prefix}.statement_status must be an assessed statement judgment")
        if set(row) != conclusion_fields:
            errors.append(f"{prefix} needs exactly: " + ", ".join(sorted(conclusion_fields)))
        actual_ids.append(str(row.get("conclusion_id")))
        if not is_enum_value(row.get("verdict"), UNIT_STATUSES - {"not_checked"}):
            errors.append(f"{prefix}.verdict must be a checked judgment")
        else:
            verdicts.append(row["verdict"])
        if not is_substantive_string(row.get("decisive_reason")):
            errors.append(f"{prefix}.decisive_reason must explain the mathematical judgment")
        refs = row.get("source_refs")
        if not isinstance(refs, list) or not refs:
            errors.append(f"{prefix}.source_refs must anchor its reason to exact packet source")
            continue
        for ref_index, ref in enumerate(refs, 1):
            label = f"{prefix}.source_refs[{ref_index}]"
            if not isinstance(ref, dict) or set(ref) != {"packet_pointer", "start_line", "end_line"}:
                errors.append(f"{label} needs packet_pointer, start_line, and end_line")
                continue
            span = canonical_spans.get(str(ref.get("packet_pointer")))
            if span is None:
                errors.append(f"{label} must reference a canonical locked source span, not operational metadata")
            source_lines = span.get("lines") if isinstance(span, dict) else None
            start, end = ref.get("start_line"), ref.get("end_line")
            line_numbers = {
                item.get("line") for item in source_lines
                if isinstance(item, dict) and is_int(item.get("line")) and isinstance(item.get("text"), str)
            } if isinstance(source_lines, list) else set()
            if (
                not is_int(start) or not is_int(end) or start > end
                or not line_numbers or start < min(line_numbers) or end > max(line_numbers)
                or end - start + 1 > len(line_numbers)
                or any(number not in line_numbers for number in range(start, end + 1))
            ):
                errors.append(f"{label} must select existing source lines in its packet span")
    if (not expected_ids or not all(is_nonempty_string(value) for value in expected_ids)
            or len(set(expected_ids)) != len(expected_ids) or sorted(actual_ids) != sorted(expected_ids)):
        errors.append("Initial challenge must assess every packet conclusion exactly once")
    if len(verdicts) == len(conclusions) and verdicts and expected_unit_status(verdicts) != response.get("challenger_verdict"):
        errors.append("Initial challenger_verdict disagrees with its conclusion verdicts")
    triggers = packet.get("issue_triggers") or []
    expected_issue_ids = sorted(row.get("id") for row in triggers if isinstance(row, dict))
    assessments = response.get("issue_assessments")
    if not isinstance(assessments, list):
        assessments = []
        errors.append("Initial challenge issue_assessments must be a list")
    actual_issue_ids: list[str] = []
    for index, row in enumerate(assessments, 1):
        prefix = f"Initial challenge issue_assessments[{index}]"
        if not isinstance(row, dict) or set(row) != {
            "issue_id", "assessment", "target_assessment", "downstream_assessment"
        }:
            errors.append(f"{prefix} needs the issue ID, assessment, target and downstream reasons")
            continue
        actual_issue_ids.append(str(row.get("issue_id")))
        if row.get("assessment") not in {"confirmed", "not_confirmed", "unclear"}:
            errors.append(f"{prefix}.assessment is invalid")
        for field in ("target_assessment", "downstream_assessment"):
            if not is_substantive_string(row.get(field)):
                errors.append(f"{prefix}.{field} must explain the independent judgment")
    if sorted(actual_issue_ids) != expected_issue_ids:
        errors.append("Initial challenge must assess exactly the packet issue targets")
    return errors


def load_initial_challenge(
    root: Path, unit_id: str, packet: dict[str, Any], challenge: dict[str, Any] | None = None
) -> tuple[dict[str, Any], dict[str, str], list[str]]:
    input_digest = canonical_sha256(challenge_input_projection(packet))
    relative = initial_challenge_reference(unit_id, input_digest)
    errors: list[str] = []
    path, valid = canonical_challenge_artifact_path(root, relative, "Initial challenge", errors)
    if not valid or path is None or not path.is_file():
        return {}, {}, [*errors, f"{unit_id}: record-challenge must preserve the initial response for the current packet"]
    record, read_errors = load_json_object(path, "initial challenge")
    errors.extend(read_errors)
    reference = {"artifact": relative, "sha256": sha256_file(path), "input_sha256": input_digest}
    if challenge is None:
        _, current_ledger = packet_ledger(root, unit_id)
        challenge = current_ledger.get("independent_check") if isinstance(current_ledger, dict) else None
    existing = challenge.get("initial_response") if isinstance(challenge, dict) else None
    if not isinstance(existing, dict):
        errors.append(f"{unit_id}: initial challenge reference is missing; preserve the record-challenge ledger binding")
    if (
        isinstance(existing, dict)
        and existing.get("input_sha256") == input_digest
        and existing != reference
    ):
        errors.append(f"{unit_id}: initial challenge binding changed; the original response cannot be rebound")
    fields = {"initial_challenge_schema_version", "unit_id", "input_sha256", "packet_sha256", "packet", "response", "recorded_utc", "record_payload_sha256"}
    record_version = record.get("initial_challenge_schema_version")
    if record_version == 2:
        fields.update({"primary_snapshot", "superseded_review"})
    if set(record) != fields or type(record_version) is not int or record_version not in {1, 2}:
        errors.append(f"{unit_id}: initial challenge record has an invalid schema")
    if record_version == 2 and not isinstance(record.get("primary_snapshot"), dict):
        errors.append(f"{unit_id}: initial challenge must retain its primary snapshot")
    if packet.get("challenge_contract_version", 2) >= 3 and record_version != 2:
        errors.append(f"{unit_id}: renew the initial challenge to preserve both judgment dimensions and the primary snapshot")
    payload = {key: value for key, value in record.items() if key != "record_payload_sha256"}
    if record.get("record_payload_sha256") != canonical_sha256(payload):
        errors.append(f"{unit_id}: initial challenge payload hash does not match")
    saved_packet = record.get("packet")
    if not isinstance(saved_packet, dict) or saved_packet.get("mode") != "challenge":
        errors.append(f"{unit_id}: initial challenge did not preserve a challenge packet")
    else:
        if record.get("packet_sha256") != canonical_sha256(saved_packet):
            errors.append(f"{unit_id}: preserved challenge packet hash does not match")
        if (
            record.get("input_sha256") != input_digest
            or canonical_sha256(challenge_input_projection(saved_packet)) != input_digest
        ):
            errors.append(f"{unit_id}: initial challenge source or semantic inputs are stale")
        errors.extend(validate_initial_challenge_response(record.get("response"), saved_packet))
    if record.get("unit_id") != unit_id or not is_utc_timestamp(record.get("recorded_utc")):
        errors.append(f"{unit_id}: initial challenge identity or time is invalid")
    previous = record.get("superseded_review")
    visited = {relative}
    while previous is not None:
        if not isinstance(previous, dict) or not isinstance(previous.get("initial_response"), dict):
            errors.append(f"{unit_id}: superseded initial review is malformed")
            break
        previous_ref = previous["initial_response"]
        previous_path, valid = canonical_challenge_artifact_path(root, previous_ref.get("artifact"), "Superseded initial challenge", errors)
        if (not valid or previous_path is None or not previous_path.is_file()
                or previous_ref.get("sha256") != sha256_file(previous_path)
                or previous_ref.get("artifact") in visited):
            errors.append(f"{unit_id}: superseded initial response is missing, changed, or cyclic")
            break
        visited.add(previous_ref["artifact"])
        reconciliation = previous.get("reconciliation_artifact")
        if reconciliation is not None:
            reconciliation_path, valid = canonical_challenge_artifact_path(root, reconciliation.get("artifact") if isinstance(reconciliation, dict) else None, "Superseded reconciliation", errors)
            if not valid or reconciliation_path is None or not reconciliation_path.is_file() or reconciliation.get("sha256") != sha256_file(reconciliation_path):
                errors.append(f"{unit_id}: superseded reconciliation is missing or changed")
        previous_record, read_errors = load_json_object(previous_path, "superseded initial challenge")
        errors.extend(read_errors)
        if previous_record.get("unit_id") != unit_id or previous_record.get("input_sha256") != previous_ref.get("input_sha256"):
            errors.append(f"{unit_id}: superseded response has the wrong unit or input identity")
        previous = previous_record.get("superseded_review")
    return record, reference, errors


def cmd_record_challenge(args: argparse.Namespace) -> int:
    """Preserve the exact blinded packet and first response without overwriting."""
    root = args.root.resolve()
    _, manifest, errors = load_audit_manifest(root)
    errors.extend(audit_internal_redirect_errors(root))
    if errors:
        raise ValueError("Cannot record challenge: " + "; ".join(errors))
    if challenge_contract_version(manifest) < 2:
        raise ValueError("record-challenge requires protocol.challenge_contract_version 2 or 3; explicitly upgrade the audit")
    baseline = audit_state_manifest(root)
    packet, errors = load_json_object(args.packet.resolve(), "consumed challenge packet")
    response, response_errors = load_json_object(args.response.resolve(), "initial challenge response")
    errors.extend(response_errors)
    if packet.get("mode") != "challenge" or packet.get("unit_id") != args.unit_id:
        errors.append("record-challenge requires the exact assigned unit's challenge packet")
    current_packet = build_context_packet(root, args.unit_id, "challenge")
    if context_packet_semantic_projection(packet) != context_packet_semantic_projection(current_packet):
        errors.append("Consumed challenge packet is stale or differs from current canonical context")
    if packet.get("challenge_contract_version", 2) != challenge_contract_version(manifest):
        errors.append("Consumed challenge packet has a different challenge contract")
    if challenge_source_spans(packet) != challenge_source_spans(current_packet):
        errors.append("Consumed challenge source identities or excerpts differ from canonical locked source")
    for field in ("context_binding", "operational_binding"):
        if packet.get(field + "_sha256") != canonical_sha256(packet.get(field)):
            errors.append(f"Consumed challenge packet {field} hash does not match")
    errors.extend(validate_initial_challenge_response(response, packet))
    if errors:
        raise ValueError("Cannot record challenge: " + "; ".join(errors))
    input_digest = canonical_sha256(challenge_input_projection(packet))
    relative = initial_challenge_reference(args.unit_id, input_digest)
    path, valid = canonical_challenge_artifact_path(root, relative, "Initial challenge", errors)
    if not valid or path is None:
        raise ValueError("Cannot record challenge: " + "; ".join(errors))
    record = {
        "initial_challenge_schema_version": 2,
        "unit_id": args.unit_id,
        "input_sha256": input_digest,
        "packet_sha256": canonical_sha256(packet),
        "packet": packet,
        "response": response,
        "recorded_utc": utc_now(),
    }
    ledger_path, ledger = packet_ledger(root, args.unit_id)
    if ledger_path is None or not isinstance(ledger, dict) or not isinstance(ledger.get("independent_check"), dict):
        raise ValueError("Cannot record challenge without the current canonical ledger and independent_check")
    record["primary_snapshot"] = primary_challenge_snapshot(ledger)
    record["superseded_review"] = None
    history_write: tuple[Path, str] | None = None
    prior_check = ledger["independent_check"]
    prior_ref = prior_check.get("initial_response")
    if isinstance(prior_ref, dict) and prior_ref.get("artifact") != relative:
        prior_path, valid = canonical_challenge_artifact_path(root, prior_ref.get("artifact"), "Prior initial challenge", errors)
        if not valid or prior_path is None or not prior_path.is_file() or sha256_file(prior_path) != prior_ref.get("sha256"):
            raise ValueError("Cannot supersede a missing or changed initial response; restore its recorded evidence")
        historical = {"initial_response": json.loads(json.dumps(prior_ref)),
                      "independent_check": json.loads(json.dumps(prior_check)),
                      "reconciliation_artifact": None}
        if prior_check.get("status") in {"agreed", "resolved"}:
            prior_artifact, valid = canonical_challenge_artifact_path(root, prior_check.get("artifact"), "Prior reconciliation", errors)
            if not valid or prior_artifact is None or not prior_artifact.is_file() or sha256_file(prior_artifact) != prior_check.get("challenge_artifact_sha256"):
                raise ValueError("Cannot supersede missing or changed bound reconciliation evidence")
            history_name = f"audit/05_adversarial/history-{sha256_file(prior_artifact)}.md"
            historical["reconciliation_artifact"] = {"artifact": history_name, "sha256": sha256_file(prior_artifact)}
            history_write = (root / history_name, prior_artifact.read_bytes().decode("utf-8"))
        record["superseded_review"] = historical
    record["record_payload_sha256"] = canonical_sha256(record)
    original_ledger_bytes = ledger_path.read_bytes()
    record_text = json.dumps(record, ensure_ascii=False, indent=2) + "\n"
    reference = {"artifact": relative, "sha256": sha256_text(record_text), "input_sha256": input_digest}
    ledger["independent_check"]["initial_response"] = reference
    ledger_text = json.dumps(ledger, ensure_ascii=False, indent=2) + "\n"
    lock, lock_payload = acquire_migration_update_lock(root, "cmd_record_challenge")
    history_created = False
    try:
        if audit_state_manifest(root, lock) != baseline:
            raise ValueError("Audit changed while preserving the initial challenge; regenerate its packet")
        if path.exists():
            raise FileExistsError(f"initial challenge response already exists: {path}")
        if history_write is not None:
            history_path, history_text = history_write
            if history_path.exists():
                if sha256_file(history_path) != sha256_text(history_text):
                    raise ValueError("Superseded reconciliation history changed")
            else:
                atomic_create_text(history_path, history_text)
                history_created = True
        # Anchor the exact bytes before publishing them. An interruption leaves
        # a missing evidence artifact, never an unanchored usable first record.
        transactional_write_texts(
            [(ledger_path, ledger_text)],
            expected_sha256={ledger_path: hashlib.sha256(original_ledger_bytes).hexdigest()},
        )
        try:
            atomic_create_json(path, record, "initial challenge response")
        except BaseException:
            transactional_write_texts(
                [(ledger_path, original_ledger_bytes)],
                expected_sha256={ledger_path: sha256_text(ledger_text)},
            )
            raise
    except BaseException:
        if history_created and history_write is not None:
            history_write[0].unlink()
        raise
    finally:
        release_migration_update_lock(lock, lock_payload)
    print(json.dumps({"command": "record-challenge", "status": "written", "artifact": relative, "sha256": sha256_file(path)}, indent=2))
    return 0


def build_statement_support_packet(root: Path, unit_id: str) -> dict[str, Any]:
    ordinary = build_context_packet(root, unit_id, "challenge")
    path, ledger = packet_ledger(root, unit_id)
    if path is None or not isinstance(ledger, dict):
        raise ValueError("Statement-support packet requires a canonical primary ledger")
    initial, reference, errors = load_initial_challenge(root, unit_id, ordinary, ledger.get("independent_check") or {})
    if errors or not initial or not reference:
        raise ValueError("Preserve the initial blind written-proof response before exposing the supplement: " + "; ".join(errors))
    proposals = statement_support_proposals(ledger)
    if not proposals:
        raise ValueError("This unit has no checked statement supplement to review")
    packet = {
        "schema_version": 1, "kind": "stat-paper-proofcheck-statement-support-packet",
        "mode": "statement-support", "unit_id": unit_id,
        "source_binding_sha256": ordinary.get("source_binding_sha256"),
        "initial_response": reference,
        "source": ordinary["source"], "obligation": ordinary["obligation"],
        "dependencies": ordinary["dependencies"],
        "statement_supports": proposals,
        "review_instruction": (
            "Independently check each proposed derivation against the exact original target, "
            "stated assumptions, complete premises, and explicit extra conditions. Accept only "
            "the claim under those conditions. Preserve the separate initial written-proof "
            "assessment. A checked supplement does not apply a manuscript repair."
        ),
    }
    changes = statement_support_changes(root, ledger)
    if changes:
        packet["suggested_changes"] = changes
    return packet


def cmd_record_statement_support(args: argparse.Namespace) -> int:
    root = args.root.resolve()
    redirect_errors = audit_internal_redirect_errors(root)
    if redirect_errors:
        raise ValueError("Cannot record statement support: " + "; ".join(redirect_errors))
    expected = build_statement_support_packet(root, args.unit_id)
    packet, packet_errors = load_json_object(args.packet, "statement-support packet")
    response, response_errors = load_json_object(args.response, "statement-support response")
    errors = [*packet_errors, *response_errors]
    if packet != expected:
        errors.append("Statement-support packet is not the exact current generated packet")
    errors.extend(statement_support_response_errors(response, packet))
    if errors:
        raise ValueError("Cannot record statement support: " + "; ".join(errors))
    path, ledger = packet_ledger(root, args.unit_id)
    if path is None:
        raise ValueError("Statement-support review has no unique ledger")
    original_ledger_bytes = path.read_bytes()
    baseline = hashlib.sha256(original_ledger_bytes).hexdigest()
    challenge = ledger.get("independent_check") or {}
    old = challenge.get("statement_support_review")
    if old is not None:
        old_errors: list[str] = []
        old_path, old_valid = canonical_challenge_artifact_path(root, old.get("artifact") if isinstance(old, dict) else None, "Prior statement-support review", old_errors)
        if not old_valid or old_path is None or not old_path.is_file() or sha256_file(old_path) != old.get("sha256"):
            raise ValueError("Cannot supersede missing or altered statement-support review evidence; restore its recorded bytes")
        _, old_errors = load_statement_support_review(root, ledger)
        if not old_errors:
            raise ValueError("A current immutable statement-support review already exists; retain it")
        history = challenge.setdefault("statement_support_review_history", [])
        if not isinstance(history, list):
            raise ValueError("statement_support_review_history must be a list")
        if old not in history:
            history.append(old)
    relative = "audit/05_adversarial/statement-support-" + canonical_sha256(args.unit_id)[:16] + "-" + canonical_sha256(packet) + ".json"
    destination = root / relative
    if destination.exists():
        raise FileExistsError("Refusing to overwrite preserved statement-support review: " + str(destination))
    record = {"schema_version": 1, "unit_id": args.unit_id, "packet": packet, "response": response,
              "recorded_utc": datetime.now(timezone.utc).isoformat()}
    record_text = json.dumps(record, ensure_ascii=False, indent=2) + "\n"
    challenge["statement_support_review"] = {"artifact": relative, "sha256": sha256_text(record_text)}
    ledger["independent_check"] = challenge
    ledger_text = json.dumps(ledger, ensure_ascii=False, indent=2) + "\n"
    lock, payload = acquire_migration_update_lock(root, "cmd_record_statement_support")
    try:
        if destination.exists():
            raise FileExistsError("Statement-support response already exists")
        transactional_write_texts(
            [(path, ledger_text)], expected_sha256={path: baseline},
        )
        try:
            atomic_create_json(destination, record, "statement-support response")
        except BaseException:
            transactional_write_texts([(path, original_ledger_bytes)], expected_sha256={path: sha256_text(ledger_text)})
            raise
    finally:
        release_migration_update_lock(lock, payload)
    print(json.dumps({"command": "record-statement-support", "status": "written", "artifact": relative,
                      "sha256": challenge["statement_support_review"]["sha256"]}, indent=2))
    return 0


def prepare_challenge_binding(
    root: Path,
    unit_id: str,
    *,
    ledger_override: dict[str, Any] | None = None,
    artifact_text: str | None = None,
) -> dict[str, Any]:
    """Validate and prepare a reconciliation without publishing either file."""
    root = root.resolve()
    redirect_errors = audit_internal_redirect_errors(root)
    if redirect_errors:
        raise ValueError("Cannot bind challenge: " + "; ".join(redirect_errors))
    matches: list[tuple[Path, dict[str, Any], str]] = []
    for ledger_path in live_local_check_artifacts(root, ".ledger.json"):
        ledger_baseline_sha256 = sha256_file(ledger_path)
        ledger, ledger_errors = load_json_object(ledger_path, "proof ledger")
        if ledger_errors:
            continue
        if sha256_file(ledger_path) != ledger_baseline_sha256:
            if ledger.get("unit_id") == unit_id:
                raise ValueError(
                    f"Proof ledger changed while bind-challenge read {unit_id}"
                )
            continue
        if ledger.get("unit_id") == unit_id:
            matches.append((ledger_path, ledger, ledger_baseline_sha256))
    if len(matches) != 1:
        raise ValueError(
            "bind-challenge requires exactly one ledger for "
            f"{unit_id}; found {len(matches)}"
        )
    ledger_path, ledger, ledger_baseline_sha256 = matches[0]
    if ledger_override is not None:
        if canonical_primary_ledger_sha256(ledger_override) != canonical_primary_ledger_sha256(ledger):
            raise ValueError("Reconciliation cannot change primary proof evidence; revise and validate the primary ledger first")
        ledger = json.loads(json.dumps(ledger_override))
    if ledger.get("schema_version") != SCHEMA_VERSION:
        raise ValueError(
            "bind-challenge requires a current-schema ledger for "
            f"{unit_id}"
        )
    challenge = ledger.get("independent_check")
    if not isinstance(challenge, dict):
        raise ValueError(
            f"bind-challenge requires an independent_check object for {unit_id}"
        )
    _, manifest, manifest_errors = load_audit_manifest(root)
    _, issues, issue_schema, issue_errors = load_issue_log(root)
    if manifest_errors or issue_errors or issue_schema != SCHEMA_VERSION:
        raise ValueError(
            "Cannot bind challenge: "
            + "; ".join(
                [
                    *manifest_errors,
                    *issue_errors,
                    *(
                        ["ISSUE_LOG.json must use the current schema"]
                        if issue_schema != SCHEMA_VERSION
                        else []
                    ),
                ]
            )
        )
    required_units, severe_by_unit = required_challenge_requirements(
        manifest, issues
    )
    if unit_id not in required_units:
        raise ValueError(
            f"bind-challenge requires an in-scope unit: {unit_id}"
        )
    packet = build_context_packet(root, unit_id, "challenge")
    if challenge_contract_version(manifest) >= 2:
        initial, initial_reference, initial_errors = load_initial_challenge(
            root, unit_id, packet, challenge
        )
        if initial_errors:
            raise ValueError("Cannot bind challenge: " + "; ".join(initial_errors))
        conclusion_errors = initial_conclusion_reconciliation_errors(initial, ledger, challenge)
        if conclusion_errors:
            raise ValueError("Cannot bind challenge: " + "; ".join(conclusion_errors))
        initial_response = initial["response"]
        for field, pending in (("challenger_verdict", "not_checked"), ("independence_level", "none")):
            existing_value = challenge.get(field)
            if existing_value not in {None, pending, initial_response[field]}:
                raise ValueError(f"Cannot bind challenge: {field} differs from the preserved initial response")
            challenge[field] = initial_response[field]
        challenge["initial_response"] = initial_reference
        initial_assessments = initial_response["issue_assessments"]
        if not challenge.get("issue_assessments"):
            challenge["issue_assessments"] = json.loads(json.dumps(initial_assessments))
        final_assessments = [
            {key: value for key, value in row.items() if key != "target_contract_sha256"}
            for row in challenge.get("issue_assessments", []) if isinstance(row, dict)
        ]
        if final_assessments != initial_assessments and (not challenge.get("disagreements") or not is_substantive_string(challenge.get("resolution"))):
            raise ValueError("Cannot bind challenge: changed issue assessments require explicit disagreement and resolution")
    required_issue_ids = sorted(severe_by_unit.get(unit_id, set()))
    trigger_hashes = {
        str(row.get("id")): row.get("target_contract_sha256")
        for row in packet.get("issue_triggers", [])
        if isinstance(row, dict) and is_nonempty_string(row.get("id"))
    }
    assessments = challenge.get("issue_assessments")
    if isinstance(assessments, list):
        for assessment in assessments:
            if not isinstance(assessment, dict):
                continue
            issue_id = assessment.get("issue_id")
            if issue_id in trigger_hashes:
                assessment["target_contract_sha256"] = trigger_hashes[issue_id]
    review = ledger.get("review")
    support_results = [row for row in (review or {}).get("conclusion_results", []) if isinstance(row, dict) and "statement_support" in row]
    if support_results:
        support_acceptance, support_errors = load_statement_support_review(root, ledger)
        if support_errors or any(support_acceptance.get(row["conclusion_id"]) != "accepted" for row in support_results):
            raise ValueError("Cannot bind challenge: every claimed statement supplement needs its current accepted immutable review; " + "; ".join(support_errors))
    final_verdict = review.get("unit_status") if isinstance(review, dict) else None
    if not is_enum_value(final_verdict, UNIT_STATUSES - {"not_checked"}):
        raise ValueError(
            f"bind-challenge requires a final primary verdict for {unit_id}"
        )
    disagreements = challenge.get("disagreements")
    disagreements = disagreements if isinstance(disagreements, list) else []
    challenger_verdict = challenge.get("challenger_verdict")
    reconciled_verdict = challenge.get("reconciled_verdict")
    if not is_enum_value(
        reconciled_verdict, UNIT_STATUSES - {"not_checked"}
    ):
        raise ValueError(
            "bind-challenge requires an explicit reconciled verdict"
        )
    if reconciled_verdict != final_verdict:
        raise ValueError(
            "Cannot bind challenge: reconciled_verdict must match the final "
            "primary ledger verdict; revise and recheck the primary ledger if "
            "the reconciliation changed its judgment"
        )
    if challenger_verdict == final_verdict and not disagreements:
        challenge_status = "agreed"
        challenge["resolution"] = ""
    elif disagreements and is_substantive_string(challenge.get("resolution")):
        challenge_status = "resolved"
    else:
        raise ValueError(
            "Cannot bind challenge: record no disagreements when the verdicts "
            "agree, or record substantive disagreements and a resolution"
        )
    snapshot = manifest.get("source_snapshot")
    snapshot_id = snapshot.get("sha256") if isinstance(snapshot, dict) else None
    challenge.update(
        {
            "required": True,
            "status": challenge_status,
            "covered_issue_ids": required_issue_ids,
            "source_snapshot_sha256": snapshot_id,
            "challenged_ledger_sha256": canonical_primary_ledger_sha256(ledger),
            "challenge_context_sha256": packet.get("context_binding_sha256"),
            "challenge_artifact_sha256": "",
            "generated_utc": datetime.now(timezone.utc).isoformat().replace(
                "+00:00", "Z"
            ),
        }
    )
    validation_probe = json.loads(json.dumps(challenge, ensure_ascii=False))
    validation_probe["challenge_artifact_sha256"] = "0" * 64
    validation_errors: list[str] = []
    validate_independent_check(
        validation_probe,
        True,
        validation_errors,
        primary_ledger_sha256=canonical_primary_ledger_sha256(ledger),
        current_contract=True,
    )
    validation_errors.extend(
        challenge_semantic_freshness_errors(
            root,
            unit_id,
            challenge,
            required_issue_ids,
        )
    )
    if validation_errors:
        raise ValueError(
            "Cannot bind challenge: " + "; ".join(validation_errors[:12])
        )
    artifact_path, artifact_valid = canonical_challenge_artifact_path(
        root,
        challenge.get("artifact"),
        f"In-scope unit {unit_id} challenger artifact",
        validation_errors,
    )
    if not artifact_valid or artifact_path is None:
        raise ValueError(
            "Cannot bind challenge: " + "; ".join(validation_errors[:12])
        )
    expected_sha256 = {ledger_path: ledger_baseline_sha256}
    if artifact_path.is_file():
        artifact_baseline_sha256 = sha256_file(artifact_path)
        if artifact_text is None:
            artifact_text = read_text(artifact_path)
        if sha256_file(artifact_path) != artifact_baseline_sha256:
            raise ValueError(f"Challenger artifact changed while bind-challenge read {unit_id}")
        expected_sha256[artifact_path] = artifact_baseline_sha256
    elif artifact_text is None:
        raise FileNotFoundError(f"Challenger artifact not found: {artifact_path}")
    bound_text = upsert_challenge_artifact_binding(
        artifact_text, unit_id, challenge
    )
    challenge["challenge_artifact_sha256"] = sha256_text(bound_text)
    return {"ledger_path": ledger_path, "ledger": ledger,
            "artifact_path": artifact_path, "artifact_text": bound_text,
            "expected_sha256": expected_sha256}


def cmd_bind_challenge(args: argparse.Namespace) -> int:
    """Complete derived challenge fields and bind the fixed artifact."""
    root = args.root.resolve()
    prepared = prepare_challenge_binding(root, args.unit_id)
    ledger_path, ledger = prepared["ledger_path"], prepared["ledger"]
    artifact_path, bound_text = prepared["artifact_path"], prepared["artifact_text"]
    challenge = ledger["independent_check"]
    lock, lock_payload = acquire_migration_update_lock(
        root, "cmd_bind_challenge"
    )
    release_lock = True
    try:
        transactional_write_texts(
            [
                (artifact_path, bound_text),
                (
                    ledger_path,
                    json.dumps(ledger, ensure_ascii=False, indent=2) + "\n",
                ),
            ],
            expected_sha256=prepared["expected_sha256"],
        )
    except MigrationRecoveryRequired:
        release_lock = False
        raise
    finally:
        if release_lock:
            release_migration_update_lock(lock, lock_payload)
    print(
        json.dumps(
            {
                "command": "bind-challenge",
                "status": "written",
                "unit_id": args.unit_id,
                "ledger": str(ledger_path),
                "artifact": str(artifact_path),
                "challenge_artifact_sha256": challenge[
                    "challenge_artifact_sha256"
                ],
            },
            ensure_ascii=True,
            indent=2,
        )
    )
    return 0


def serialize(data: dict[str, Any], output_format: str) -> str:
    if output_format == "json":
        return json.dumps(data, ensure_ascii=False, indent=2) + "\n"
    raise ValueError(f"Unsupported format: {output_format}")


def write_or_print(text: str, output: Path | None, force: bool = False) -> None:
    if output is None:
        print(text, end="")
        return
    output = output.resolve()
    if output.exists() and not force:
        raise FileExistsError(f"Output exists; use --force to replace it: {output}")
    atomic_write_text(output, text)


def copy_template(skill_root: Path, name: str, destination: Path) -> None:
    source = skill_root / "assets" / "templates" / name
    if not source.is_file():
        raise FileNotFoundError(f"Bundled template not found: {source}")
    atomic_copy_file(source, destination)


PDF_TRANSCRIPTION_WARNING = (
    "PDF transcription input requires a complete manual theorem/proof inventory, "
    "page-map review, and visual comparison against the hash-locked publisher PDF "
    "before finalization."
)


def resolve_source_discovery_inputs(
    paper: Path,
    input_kind: str,
    *,
    additional_source: Any = None,
    fls: Path | None = None,
    project_root: Path | None = None,
) -> tuple[Path, list[tuple[Path, str, str]], Path | None]:
    """Validate scaffold-compatible source-discovery inputs without writing."""
    resolved_root = (
        project_root.resolve() if isinstance(project_root, Path) else paper.parent
    )
    if not resolved_root.is_dir():
        raise FileNotFoundError(f"Project root not found: {resolved_root}")
    if not paper.is_relative_to(resolved_root):
        raise ValueError("Project root must contain the main paper")
    if input_kind == "pdf_transcription" and (additional_source or fls is not None):
        raise ValueError(
            "pdf_transcription does not accept LaTeX additional-source or FLS inputs"
        )

    entries: list[tuple[Path, str, str]] = []
    seen: set[Path] = set()
    for index, raw_entry in enumerate(additional_source or [], 1):
        if not isinstance(raw_entry, (list, tuple)) or len(raw_entry) != 3:
            raise ValueError(
                f"Additional source {index} must provide PATH, REASON, and EVIDENCE"
            )
        raw_path, raw_reason, raw_evidence = raw_entry
        reason = str(raw_reason).strip()
        evidence = str(raw_evidence).strip()
        if not reason or not evidence:
            raise ValueError(
                f"Additional source {index} requires nonempty reason and evidence"
            )
        candidate = Path(raw_path)
        if not candidate.is_absolute():
            candidate = paper.parent / candidate
        candidate = candidate.resolve()
        if not candidate.is_file():
            raise FileNotFoundError(f"Additional source file not found: {candidate}")
        if candidate in seen:
            raise ValueError(f"Duplicate additional source file: {candidate}")
        seen.add(candidate)
        entries.append((candidate, reason, evidence))

    resolved_fls = fls.resolve() if isinstance(fls, Path) else None
    if resolved_fls is not None and not resolved_fls.is_file():
        raise FileNotFoundError(f"Recorder file not found: {resolved_fls}")
    return resolved_root, entries, resolved_fls


def _build_scaffold(args: argparse.Namespace, output: Path) -> dict[str, Any]:
    paper = args.paper.resolve()
    output = output.resolve()
    if not paper.is_file():
        raise FileNotFoundError(f"Paper source not found: {paper}")
    input_kind = getattr(args, "input_kind", "latex")
    if input_kind not in {"latex", "pdf_transcription"}:
        raise ValueError("input_kind must be latex or pdf_transcription")
    if paper.suffix.lower() == ".pdf":
        raise ValueError(
            "Raw PDF cannot be used as parsed source; provide LaTeX or a "
            "UTF-8 PDF transcription with --input-kind pdf_transcription"
        )
    portable_sources = bool(getattr(args, "portable_sources", False))
    publisher_arg = getattr(args, "publisher_pdf", None)
    publisher_pdf = (
        publisher_arg.resolve() if isinstance(publisher_arg, Path) else None
    )
    visual_review_status = getattr(args, "visual_review_status", "not_started")
    visual_review_notes = getattr(args, "visual_review_notes", "") or ""
    if visual_review_status not in {"not_started", "partial", "complete"}:
        raise ValueError("visual_review_status is invalid")
    if visual_review_status == "complete":
        raise ValueError(
            "Scaffold cannot assert a complete visual review; first record reviewed_pages, "
            "substantive notes, and completed_utc after the actual review"
        )
    if input_kind == "pdf_transcription":
        if publisher_pdf is None or not publisher_pdf.is_file():
            raise FileNotFoundError(
                "pdf_transcription requires an existing --publisher-pdf"
            )
        if publisher_pdf.suffix.lower() != ".pdf":
            raise ValueError("--publisher-pdf must name a PDF file")
    elif publisher_pdf is not None:
        raise ValueError("--publisher-pdf applies only to pdf_transcription input")

    project_root, additional_entries, fls_path = resolve_source_discovery_inputs(
        paper,
        input_kind,
        additional_source=getattr(args, "additional_source", None),
        fls=getattr(args, "fls", None),
        project_root=getattr(args, "project_root", None),
    )
    additional_paths = [entry[0] for entry in additional_entries]
    additional_records = [
        {
            "file": relative_or_absolute(path, output),
            "reason": reason,
            "evidence": evidence,
        }
        for path, reason, evidence in additional_entries
    ]

    directories = [
        output / "audit" / "01_index",
        output / "audit" / "02_ledgers",
        output / "audit" / "03_dependencies",
        output / "audit" / "04_local_checks",
        output / "audit" / "05_adversarial",
        output / "audit" / "06_reports",
    ]
    if portable_sources:
        directories.insert(0, output / "audit" / "00_sources")
    for directory in directories:
        directory.mkdir(parents=True, exist_ok=False)

    skill_root = Path(__file__).resolve().parent.parent
    copy_template(skill_root, "CHECK_PLAN.md", output / "CHECK_PLAN.md")
    copy_template(skill_root, "EXECUTION_ORDER.md", output / "EXECUTION_ORDER.md")
    copy_template(
        skill_root,
        "DEPENDENCY_GRAPH.md",
        output / "audit" / "03_dependencies" / "dependency_graph.md",
    )
    if getattr(args, "report_format", "html") == "markdown":
        copy_template(
            skill_root, "FINAL_REPORT.md",
            output / "audit" / "06_reports" / "FINAL_REPORT.md")
    original_paper = paper
    original_project_root = project_root
    original_additional_paths = list(additional_paths)
    original_fls_path = fls_path
    if input_kind == "latex":
        closure = discover_source_closure(
            paper,
            additional_files=additional_paths,
            fls_file=fls_path,
            project_root=project_root,
            warning_path_base=paper.parent if portable_sources else None,
        )
        source_files = closure["files"]
        source_warnings = closure["warnings"]
    else:
        closure = {
            "files": [paper],
            "warnings": [PDF_TRANSCRIPTION_WARNING],
            "outside_project_inputs": [],
        }
        source_files = [paper]
        source_warnings = [PDF_TRANSCRIPTION_WARNING]

    publisher_authoritative = publisher_pdf
    if portable_sources:
        outside_project_sources = [
            source
            for source in source_files
            if not source.resolve().is_relative_to(original_project_root)
        ]
        if outside_project_sources:
            raise ValueError(
                "--portable-sources cannot preserve relative source topology outside "
                "--project-root; rerun with a broader --project-root containing: "
                + ", ".join(path.as_posix() for path in outside_project_sources)
            )
        source_map: dict[Path, Path] = {}
        portable_root = output / "audit" / "00_sources"
        for source in source_files:
            source = source.resolve()
            if input_kind == "pdf_transcription" and source == original_paper:
                destination = portable_root / "transcription" / source.name
            elif source.is_relative_to(original_project_root):
                destination = (
                    portable_root
                    / "project"
                    / source.relative_to(original_project_root)
                )
            else:  # Guarded above; retained as a defensive invariant.
                raise ValueError(f"Unconfined portable source: {source.as_posix()}")
            atomic_copy_file(source, destination)
            source_map[source] = destination.resolve()
        paper = source_map[original_paper]
        source_files = [source_map[path.resolve()] for path in source_files]
        additional_paths = [
            source_map[path.resolve()] for path in original_additional_paths
        ]
        additional_records = [
            {**record, "file": relative_or_absolute(path, output)}
            for record, path in zip(additional_records, additional_paths)
        ]
        project_root = portable_root / "project"
        fls_path = None
        if publisher_pdf is not None:
            publisher_authoritative = portable_root / "publisher" / publisher_pdf.name
            atomic_copy_file(publisher_pdf, publisher_authoritative)
        if input_kind == "latex":
            source_files, source_warnings = rediscover_portable_source_closure(
                paper,
                source_files,
                additional_paths,
                output,
                source_warnings,
            )
            unconfined_bundle_sources = [
                path
                for path in source_files
                if not path.is_relative_to(portable_root)
            ]
            if unconfined_bundle_sources:
                raise ValueError(
                    "--portable-sources found an absolute or otherwise "
                    "nonrelocatable inclusion after bundling: "
                    + ", ".join(
                        path.as_posix() for path in unconfined_bundle_sources
                    )
                )
    inventory = scan_formal_units(
        paper,
        source_files=source_files,
        source_warnings=source_warnings,
        path_identity_base=paper.parent if portable_sources else None,
    )
    identity_errors = inventory_identity_errors(inventory["units"])
    if identity_errors:
        raise ValueError("Cannot create audit: " + "; ".join(identity_errors))
    cross_references = scan_cross_references(
        paper,
        source_files=source_files,
        source_warnings=source_warnings,
        path_identity_base=paper.parent if portable_sources else None,
    )
    paper_value = relative_or_absolute(paper, output)
    parser_warnings = sorted(
        set(inventory.get("warnings", []))
        | set(cross_references.get("warnings", []))
        | set(source_warnings)
    )
    source_snapshot_files = [
        {
            "file": relative_or_absolute(path, output),
            "sha256": sha256_file(path),
        }
        for path in source_files
    ]
    fls_record = None
    if fls_path is not None:
        fls_record = {
            "file": relative_or_absolute(fls_path, output),
            "sha256": sha256_file(fls_path) if fls_path.is_file() else None,
            "project_root": relative_or_absolute(project_root, output),
            "outside_project_inputs": closure["outside_project_inputs"],
        }
    publisher_record = None
    if publisher_authoritative is not None and publisher_pdf is not None:
        publisher_record = {
            "file": relative_or_absolute(publisher_authoritative, output),
            "sha256": sha256_file(publisher_authoritative),
            "size_bytes": publisher_authoritative.stat().st_size,
            "original_location": publisher_pdf.as_posix(),
        }
    input_provenance = {
        "kind": input_kind,
        "authoritative_source": paper_value,
        "portable_sources": portable_sources,
        "original_locations": {
            "authoritative": False,
            "paper": original_paper.as_posix(),
            "project_root": original_project_root.as_posix(),
            "additional_sources": [
                path.as_posix() for path in original_additional_paths
            ],
            "fls": original_fls_path.as_posix() if original_fls_path else None,
            "fls_sha256": (
                sha256_file(original_fls_path) if original_fls_path else None
            ),
            "publisher_pdf": publisher_pdf.as_posix() if publisher_pdf else None,
        },
        "manual_inventory_required": input_kind == "pdf_transcription",
        "publisher_pdf": publisher_record,
        "visual_review": {
            "status": visual_review_status,
            "notes": visual_review_notes.strip(),
            "reviewed_pages": [],
            "completed_utc": None,
        },
    }
    manifest = {
        "schema_version": SCHEMA_VERSION,
        "protocol": protocol_identity(),
        "paper_file": paper_value,
        "input_provenance": input_provenance,
        "created_utc": utc_now(),
        "inventory_file": "audit/01_index/theorem_inventory.json",
        "dependency_registry": "audit/03_dependencies/DEPENDENCY_REGISTRY.json",
        "method_interface_registry": (
            "audit/03_dependencies/METHOD_INTERFACE_REGISTRY.json"
        ),
        "finalization_record": "audit/06_reports/FINALIZATION.json",
        "source_snapshot": {
            "files": source_snapshot_files,
            "sha256": canonical_sha256(source_snapshot_files),
        },
        "source_discovery": {
            "additional_files": additional_records,
            "fls": fls_record,
            "portable_fixed_closure": portable_sources,
            "recorded_warnings": source_warnings if portable_sources else [],
        },
        "parser_warnings": parser_warnings,
        "parser_warning_reviews": [
            {
                "warning": warning,
                "disposition": "unreviewed",
                "affected_units": [],
                "evidence": "",
            }
            for warning in parser_warnings
        ],
        "cross_reference_reviews": [
            {
                **anomaly,
                "status": "not_reviewed",
                "evidence": "",
                "affected_units": [],
                "issue_ids": [],
            }
            for anomaly in cross_reference_anomalies(cross_references)
        ],
        "audit_scope": {
            "status": "not_set",
            "depth": "not_set",
            "overall_assessment": "not_set",
            "target_units": [],
            "in_scope_units": [],
            "critical_units": [],
            "in_scope_interfaces": [],
            "excluded_units": [],
            "inventory_overrides": [],
            "source_or_parser_limits": [],
        },
        "completion": {
            "inventory_reviewed": False,
            "parser_warnings_reviewed": False,
            "dependency_registry_reviewed": False,
            "method_interface_registry_reviewed": False,
            "global_consistency_pass": {
                "status": "not_checked",
                "checks": [
                    {
                        "aspect": aspect,
                        "status": "not_checked",
                        "evidence": "",
                        "affected_units": [],
                        "issue_ids": [],
                    }
                    for aspect in GLOBAL_CONSISTENCY_ASPECTS
                ],
            },
            "adversarial_pass": {
                "status": "not_checked",
                "evidence": [],
            },
            "final_report_ready": False,
        },
        "report_deliverables": [],
        "notes": [],
    }
    manifest["protocol"]["challenge_contract_version"] = 3
    if getattr(args, "report_format", "html") == "html":
        release = report_module("proofcheck_release")
        manifest["report_contract"] = release.contract(report_api())
        manifest["report_context"] = {}
        manifest["report_deliverables"] = release.declarations(manifest)
    progress = {
        "schema_version": SCHEMA_VERSION,
        "paper_file": paper_value,
        "source_snapshot_sha256": manifest["source_snapshot"]["sha256"],
        "status": "in_progress",
        "current_pass": 1,
        "active_unit": None,
        "completed_units": [],
        "conditional_units": [],
        "in_progress_units": [],
        "blocked_units": {},
        "not_started_units": [unit["id"] for unit in inventory["units"]],
        "open_high_priority_issues": [],
        "source_or_parser_limits": [],
        "next_action": (
            (
                "Manually inventory every theorem, lemma, assumption, and proof; "
                "complete the publisher-PDF page map and visual review; then "
                "establish audited targets, scope, and depth."
            )
            if input_kind == "pdf_transcription"
            else (
                "Review CHECK_PLAN.md, confirm the source closure, and establish "
                "audited targets, scope, and depth."
            )
        ),
        "updated_utc": utc_now(),
    }
    issue_log = {"schema_version": SCHEMA_VERSION, "issues": []}
    dependency_registry = {
        "schema_version": SCHEMA_VERSION,
        "closure_contract_version": CLOSURE_CONTRACT_VERSION,
        "review": {
            "status": "not_reviewed",
            "source_snapshot_sha256": "",
            "inventory_sha256": "",
            "in_scope_units": [],
            "evidence": [],
        },
        "internal_uses": [],
        "external_results": [],
    }
    method_interface_registry = {
        "schema_version": METHOD_INTERFACE_SCHEMA_VERSION,
        "scope": {
            "status": "not_set",
            "trigger": "not_set",
            "reason": "",
        },
        "interfaces": [],
    }
    atomic_write_json(output / "AUDIT_MANIFEST.json", manifest)
    atomic_write_json(output / "PROGRESS.json", progress)
    atomic_write_json(output / "audit" / "06_reports" / "ISSUE_LOG.json", issue_log)
    atomic_write_text(
        output / "audit" / "06_reports" / "ISSUE_SUMMARY.md",
        render_issue_summary([]),
    )
    atomic_write_json(
        output / "audit" / "01_index" / "theorem_inventory.json", inventory
    )
    atomic_write_text(
        output / "audit" / "01_index" / "theorem_inventory.md",
        index_markdown(inventory),
    )
    atomic_write_json(
        output / "audit" / "01_index" / "cross_reference_audit.json",
        cross_references,
    )
    atomic_write_text(
        output / "audit" / "01_index" / "cross_reference_audit.md",
        crossref_markdown(cross_references),
    )
    atomic_write_json(
        output / "audit" / "03_dependencies" / "DEPENDENCY_REGISTRY.json",
        dependency_registry,
    )
    atomic_write_json(
        output / "audit" / "03_dependencies" / "METHOD_INTERFACE_REGISTRY.json",
        method_interface_registry,
    )
    sync_workflow_views(output)

    if uses_html_report(manifest):
        report_module("proofcheck_release").render_working(report_api(), output)

    return {
        "audit_root": str(output),
        "paper_file": paper_value,
        "source_files": len(source_files),
        "proof_units": len(inventory["units"]),
        "parser_warnings": len(parser_warnings),
        "input_kind": input_kind,
        "portable_sources": portable_sources,
    }


def _remove_scaffold_staging(staging: Path, parent: Path, prefix: str) -> None:
    resolved_parent = parent.resolve()
    resolved_staging = staging.resolve()
    try:
        resolved_staging.relative_to(resolved_parent)
    except ValueError as exc:
        raise ValueError(f"Refusing to clean unconfined scaffold stage: {staging}") from exc
    if resolved_staging.parent != resolved_parent or not staging.name.startswith(prefix):
        raise ValueError(f"Refusing to clean unexpected scaffold stage: {staging}")
    if staging.is_symlink():
        staging.unlink(missing_ok=True)
    elif staging.exists():
        shutil.rmtree(staging)


def cmd_scaffold(args: argparse.Namespace) -> int:
    output = args.output.resolve()
    if output.exists():
        raise FileExistsError(f"Refusing to overwrite existing audit root: {output}")
    output.parent.mkdir(parents=True, exist_ok=True)
    prefix = f".{output.name}."
    staging = Path(
        tempfile.mkdtemp(
            prefix=prefix,
            suffix=".proofcheck.stage",
            dir=str(output.parent),
        )
    )
    staged_args = argparse.Namespace(**vars(args))
    staged_args.output = staging
    try:
        result = _build_scaffold(staged_args, staging)
        if output.exists():
            raise FileExistsError(f"Refusing to overwrite existing audit root: {output}")
        os.replace(staging, output)
    finally:
        if staging.exists() or staging.is_symlink():
            _remove_scaffold_staging(staging, output.parent, prefix)
    result["audit_root"] = str(output)
    print(json.dumps(result, ensure_ascii=False, indent=2))
    return 0


def cmd_index(args: argparse.Namespace) -> int:
    if not args.file.is_file():
        raise FileNotFoundError(f"LaTeX source not found: {args.file}")
    if args.file.suffix.lower() == ".pdf":
        raise ValueError("Raw PDF cannot be indexed as parsed source")
    data = scan_formal_units(args.file)
    text = index_markdown(data) if args.format == "markdown" else serialize(data, "json")
    write_or_print(text, args.output, args.force)
    return 0


def crossref_refresh_hint(root: Path) -> str:
    return (
        "for unchanged locked sources, run: "
        f'python "{Path(__file__).resolve()}" crossref --root "{root}"'
    )


@audit_migration_locked
def refresh_audit_crossref(args: argparse.Namespace) -> int:
    """Regenerate both canonical views without renewing sources or judgments."""
    root = args.root.resolve()
    errors: list[str] = []
    manifest_path, valid = canonical_artifact_path(
        root, "AUDIT_MANIFEST.json", "audit manifest", errors
    )
    if not valid or not manifest_path.is_file():
        raise ValueError("Cannot refresh cross-references: " + "; ".join(
            errors or [f"Audit manifest not found: {manifest_path}"]
        ))
    guards = {manifest_path: sha256_file(manifest_path)}
    _, manifest, manifest_errors = load_audit_manifest(root)
    errors.extend(manifest_errors)
    errors.extend(source_snapshot_freshness_errors(root, manifest))
    paths = []
    absent = []
    for suffix in ("json", "md"):
        path, _ = canonical_artifact_path(
            root, f"audit/01_index/cross_reference_audit.{suffix}",
            f"cross-reference audit {suffix}", errors,
        )
        paths.append(path)
        if path.is_file():
            guards[path] = sha256_file(path)
        elif not path.exists():
            absent.append(path)
    if errors:
        raise ValueError("Cannot refresh cross-references: " + "; ".join(errors))

    paper = resolve_stored_path(manifest["paper_file"], root)
    members = packet_source_members(root, manifest)
    guards.update({path: row["sha256"] for path, row in members})
    additional, fls, project_root, _ = parse_manifest_source_discovery(
        manifest, root, errors
    )
    if fls is not None:
        guards[fls] = manifest["source_discovery"]["fls"]["sha256"]
    portable = manifest.get("input_provenance", {}).get("portable_sources") is True
    if portable:
        warnings = manifest.get("source_discovery", {}).get("recorded_warnings", [])
        if not isinstance(warnings, list) or not all(isinstance(item, str) for item in warnings):
            errors.append("source_discovery.recorded_warnings must be a string list")
        files = [path for path, _ in members]
        if manifest["input_provenance"]["kind"] == "latex" and not errors:
            files, warnings = rediscover_portable_source_closure(
                paper, files, additional, root, warnings
            )
    else:
        closure = discover_source_closure(
            paper, additional_files=additional, fls_file=fls,
            project_root=project_root or paper.parent,
        )
        files, warnings = closure["files"], closure["warnings"]
    if errors:
        raise ValueError("Cannot refresh cross-references: " + "; ".join(errors))
    data = scan_cross_references(
        paper, source_files=files, source_warnings=warnings,
        path_identity_base=paper.parent if portable else None,
    )
    errors = source_snapshot_freshness_errors(root, manifest)
    if errors:
        raise ValueError("Cannot refresh cross-references: " + "; ".join(errors))
    transactional_write_texts(
        [(paths[0], serialize(data, "json")), (paths[1], crossref_markdown(data))],
        expected_sha256=guards, expected_absent=absent,
    )
    print(json.dumps({
        "command": "crossref", "status": "refreshed", "audit_root": str(root),
        "outputs": [relative_or_absolute(path, root) for path in paths],
        "next_action": "Resume audit checks; a finalized audit still requires finalize and delivery-check.",
    }, indent=2))
    return 0


def cmd_crossref(args: argparse.Namespace) -> int:
    if getattr(args, "root", None) is not None:
        if (getattr(args, "file", None) is not None or args.output is not None
                or args.format != "json" or args.force):
            raise ValueError("crossref --root refreshes both canonical files; do not combine it with --file, --output, --format markdown, or --force")
        return refresh_audit_crossref(args)
    if not args.file.is_file():
        raise FileNotFoundError(f"LaTeX source not found: {args.file}")
    if args.file.suffix.lower() == ".pdf":
        raise ValueError("Raw PDF cannot be scanned as parsed source")
    data = scan_cross_references(args.file)
    text = (
        crossref_markdown(data)
        if args.format == "markdown"
        else serialize(data, "json")
    )
    write_or_print(text, args.output, args.force)
    return 0


def cmd_extract(args: argparse.Namespace) -> int:
    source = args.file.resolve()
    output = args.output.resolve()
    audit_root = containing_audit_root(output)
    if audit_root is not None:
        lock_error = migration_update_lock_error(audit_root)
        if lock_error is not None:
            raise ValueError(lock_error)
    if not source.is_file():
        raise FileNotFoundError(f"Source file not found: {source}")
    if source.suffix.lower() == ".pdf":
        raise ValueError("Raw PDF cannot be extracted as parsed source")
    if output == source:
        raise ValueError("Ledger output must not overwrite the source file")
    if output.exists() and not args.force:
        raise FileExistsError(f"Ledger exists; use --force to replace it: {output}")
    lines = read_lines(source)
    if args.start < 1 or args.end < args.start or args.end > len(lines):
        raise ValueError(
            f"Invalid inclusive range {args.start}-{args.end}; source has {len(lines)} lines"
        )
    statement_start = getattr(args, "statement_start", None)
    statement_end = getattr(args, "statement_end", None)
    statement_file_value = getattr(args, "statement_file", None)
    if (statement_start is None) != (statement_end is None):
        raise ValueError("Provide both --statement-start and --statement-end")
    statement_source = (
        statement_file_value.resolve() if statement_file_value is not None else source
    )
    if statement_start is not None:
        if not statement_source.is_file():
            raise FileNotFoundError(f"Statement source not found: {statement_source}")
        if statement_source.suffix.lower() == ".pdf":
            raise ValueError("Raw PDF cannot be used as parsed statement source")
        statement_lines = read_lines(statement_source)
        if not (
            1 <= statement_start <= statement_end <= len(statement_lines)
        ):
            raise ValueError(
                "The statement range must be valid in its declared source file"
            )
    statement_is_covered = (
        statement_start is not None
        and statement_source == source
        and args.start <= statement_start <= statement_end <= args.end
    )
    coverage_mode = (
        "statement_and_proof"
        if statement_is_covered
        else "proof_with_separate_statement"
    )
    separate_statement_reason = getattr(args, "separate_statement_reason", None) or ""
    selected = lines[args.start - 1 : args.end]
    output.parent.mkdir(parents=True, exist_ok=True)
    ledger = {
        "schema_version": SCHEMA_VERSION,
        "evidence_contract_version": EVIDENCE_CONTRACT_VERSION,
        "unit_id": args.unit_id,
        "source": {
            "file": relative_or_absolute(source, output.parent),
            "start_line": args.start,
            "end_line": args.end,
            "unit_sha256": sha256_text("\n".join(selected)),
            "coverage_mode": coverage_mode,
            "separate_statement_reason": separate_statement_reason,
        },
        "source_lines": [
            {
                "line": line_number,
                "sha256": sha256_text(text),
                "text": text,
            }
            for line_number, text in enumerate(selected, args.start)
        ],
        "source_units": [
            {
                "id": f"U{offset:03d}",
                "lines": [line_number, line_number],
                "kind": (
                    "non_substantive" if is_non_substantive(text) else "one_line"
                ),
                "source_sha256": sha256_text(text),
                "partition_evidence": (
                    "The locked line is blank, comment-only, or a proof wrapper."
                    if is_non_substantive(text)
                    else "This source unit is exactly one locked physical line."
                ),
            }
            for offset, (line_number, text) in enumerate(
                enumerate(selected, args.start), 1
            )
        ],
        "obligation": {
            "statement_spans": (
                [
                    locked_span(
                        statement_source,
                        statement_start,
                        statement_end,
                        output.parent,
                    )
                ]
                if statement_start is not None
                else []
            ),
            "quantified_variables": [],
            "quantifier_scope": "",
            "probability_model": "",
            "hypotheses": [],
            "definitions": [],
            "conclusion": "",
            "conclusions": [],
            "uniformity": "",
            "regime": "",
            "constant_dependencies": [],
            "context_spans": [],
            "normalization_checks": [],
        },
        "review": {
            "unit_status": "not_checked",
            "conclusion_step_id": "",
            "conclusion_results": [],
            "contract_fidelity": "not_checked",
            "argument_status": "not_checked",
            "statement_status": "not_assessed",
            "dependency_closure": "not_checked",
            "explicit_assumptions": [],
            "inherited_assumptions": [],
            "direct_dependencies": [],
            "source_reference_dispositions": [],
            "candidate_dependency_dispositions": [],
            "citation_dispositions": [],
            "use_sites": [],
            "verification_basis": [],
            "reviewer_notes": [],
        },
        "independent_check": {
            "required": False,
            "status": "not_required",
            "independence_level": "none",
            "challenger_verdict": "not_checked",
            "reconciled_verdict": "not_checked",
            "artifact": "",
            "covered_issue_ids": [],
            "source_snapshot_sha256": "",
            "challenged_ledger_sha256": "",
            "challenge_context_sha256": "",
            "challenge_artifact_sha256": "",
            "issue_assessments": [],
            "generated_utc": "",
            "disagreements": [],
            "resolution": "",
        },
        "steps": [],
    }
    extraction_project_root = source.parent
    if audit_root is not None:
        extraction_manifest, extraction_errors = load_json_object(audit_root / "AUDIT_MANIFEST.json", "manifest")
        if not extraction_errors and is_nonempty_string(extraction_manifest.get("paper_file")):
            extraction_project_root = resolve_stored_path(extraction_manifest["paper_file"], audit_root).parent
    source_fragment_support().lock(report_api(), ledger, source, args.start, args.end,
                                   output.parent, project_root=extraction_project_root)
    if statement_start is not None:
        statement_expansion = source_fragment_support().expand(
            report_api(), statement_source, statement_start, statement_end,
            output.parent, project_root=extraction_project_root)
        if statement_expansion["has_inclusion"]:
            ledger["obligation"]["statement_spans"].extend(
                locked_span(resolve_stored_path(fragment["file"], output.parent),
                            fragment["start_line"], fragment["end_line"], output.parent)
                for fragment in statement_expansion["fragments"]
                if resolve_stored_path(fragment["file"], output.parent) != statement_source)
    atomic_write_json(output, ledger)
    print(
        json.dumps(
            {
                "ledger": str(output),
                "unit_id": args.unit_id,
                "source_range": f"{args.start}-{args.end}",
                "physical_lines": len(ledger["source_lines"]),
                "artifact_state": "source_locked_skeleton",
                "finalizable": False,
                "next_action": (
                    "Complete the normalized obligation, partition every source "
                    "line into checked steps, and run ledger-check --final."
                ),
            },
            indent=2,
        )
    )
    return 0


COMPACT_ANNOTATION_TOP_LEVEL_FIELDS = {
    "annotation_schema_version",
    "unit_id",
    "source_unit_sha256",
    "obligation_sha256",
    "context_binding_sha256",
    "calibration_receipt_sha256",
    "source_groups",
    "dependencies",
    "steps",
    "conclusions",
    "review",
}


def containing_audit_root(path: Path) -> Path | None:
    for candidate in (path.parent, *path.parents):
        if (
            (candidate / "AUDIT_MANIFEST.json").is_file()
            and (candidate / "audit").is_dir()
        ):
            return candidate.resolve()
    return None


def validate_current_primary_packet(
    ledger: dict[str, Any],
    ledger_path: Path,
    packet_path: Path,
) -> dict[str, Any]:
    packet, packet_errors = load_json_object(packet_path, "primary context packet")
    if packet_errors:
        raise ValueError(packet_errors[0])
    if packet.get("schema_version") != CONTEXT_PACKET_SCHEMA_VERSION:
        raise ValueError(
            "Compiler packet has an unsupported context-packet schema version"
        )
    if packet.get("kind") != "stat-paper-proofcheck-context-packet":
        raise ValueError("Compiler packet has an unsupported kind")
    if packet.get("mode") != "primary":
        raise ValueError("compile-annotations requires a primary context packet")
    if packet.get("unit_id") != ledger.get("unit_id"):
        raise ValueError("Compiler packet unit_id does not match the skeleton")
    if packet.get("source_obligation_ready") is not True:
        raise ValueError("Compiler packet source and obligation are not ready")
    if packet.get("primary_work_packet_ready") is not True:
        raise ValueError("Compiler packet is not ready for primary semantic work")
    audit_root = containing_audit_root(ledger_path)
    if audit_root is None:
        raise ValueError(
            "compile-annotations requires a source-locked skeleton inside a "
            "canonical proofcheck audit root"
        )
    if packet_path.is_relative_to(audit_root):
        raise ValueError(
            "The compiler packet must remain outside the canonical audit root"
        )
    artifact = packet.get("semantic_artifact")
    expected_relative = ledger_path.relative_to(audit_root).as_posix()
    if (
        not isinstance(artifact, dict)
        or artifact.get("kind") != "source_locked_skeleton"
        or artifact.get("audit_relative_file") != expected_relative
    ):
        raise ValueError("Compiler packet does not bind this source-locked skeleton")
    # Discover the canonical input independently; never select a path supplied
    # by the packet. Existing ledgers remain live for issue/dependency targets.
    skeleton_path, skeleton = packet_skeleton(
        audit_root, str(ledger.get("unit_id"))
    )
    if skeleton_path != ledger_path or skeleton != ledger:
        raise ValueError(
            "Compiler packet requires the actual current canonical source-locked skeleton"
        )
    expected_packet = build_context_packet(
        audit_root, str(ledger.get("unit_id")), "primary", for_recompile=True
    )
    context_binding = packet.get("context_binding")
    if (
        not isinstance(context_binding, dict)
        or packet.get("context_binding_sha256")
        != canonical_sha256(context_binding)
    ):
        raise ValueError(
            "Compiler packet context binding is malformed or was modified"
        )
    operational_binding = packet.get("operational_binding")
    if (
        not isinstance(operational_binding, dict)
        or packet.get("operational_binding_sha256")
        != canonical_sha256(operational_binding)
    ):
        raise ValueError(
            "Compiler packet operational binding is malformed or was modified"
        )
    if expected_packet.get("source_obligation_ready") is not True:
        raise ValueError("Current source and obligation are not ready")
    if expected_packet.get("primary_work_packet_ready") is not True:
        raise ValueError("Current audit state is not ready for primary semantic work")
    packet_semantic = context_packet_semantic_projection(packet)
    expected_semantic = context_packet_semantic_projection(expected_packet)
    if packet_semantic != expected_semantic:
        differing_fields = sorted(
            field
            for field in set(packet_semantic) | set(expected_semantic)
            if packet_semantic.get(field) != expected_semantic.get(field)
        )
        raise ValueError(
            "Compiler packet semantic context is stale or was modified; "
            "regenerate it from the canonical audit state. Differing fields: "
            + ", ".join(differing_fields)
        )
    obligation_hash = canonical_sha256(ledger.get("obligation"))
    if packet.get("obligation_sha256") != obligation_hash:
        raise ValueError("Compiler packet obligation_sha256 binding is stale")
    validated_packet = dict(packet)
    validated_packet["_submitted_operational_binding_sha256"] = packet.get(
        "operational_binding_sha256"
    )
    validated_packet["_operational_binding_drift"] = packet.get(
        "operational_binding_sha256"
    ) != expected_packet.get("operational_binding_sha256")
    validated_packet["operational_binding"] = expected_packet.get(
        "operational_binding"
    )
    validated_packet["operational_binding_sha256"] = expected_packet.get(
        "operational_binding_sha256"
    )
    validated_packet["dependencies"] = expected_packet.get("dependencies")
    return validated_packet


def validate_compiler_context_packet(
    ledger: dict[str, Any],
    ledger_path: Path,
    annotations: dict[str, Any],
    packet_path: Path,
) -> dict[str, Any]:
    packet = validate_current_primary_packet(
        ledger,
        ledger_path,
        packet_path,
    )
    dependencies = packet.get("dependencies")
    if not isinstance(dependencies, dict):
        raise ValueError("Compiler packet dependencies are malformed")
    preliminary_uses: list[str] = []
    for field in ("direct_internal_uses", "direct_external_uses"):
        rows = dependencies.get(field)
        if not isinstance(rows, list):
            raise ValueError(f"Compiler packet dependencies.{field} is malformed")
        for index, row in enumerate(rows, 1):
            if not isinstance(row, dict):
                raise ValueError(
                    f"Compiler packet dependencies.{field}[{index}] is malformed"
                )
            step_ids = row.get("step_ids")
            if (
                row.get("status") == "unchecked"
                or not isinstance(step_ids, list)
                or not step_ids
            ):
                preliminary_uses.append(
                    str(row.get("use_id") or f"{field}[{index}]")
                )
    if preliminary_uses:
        raise ValueError(
            "compile-annotations requires every direct dependency row to bind "
            "exact step_ids and a non-unchecked status; complete the dependency "
            "registry and regenerate the packet: "
            + ", ".join(preliminary_uses)
        )
    if annotations.get("context_binding_sha256") != packet.get(
        "context_binding_sha256"
    ):
        raise ValueError(
            "annotations.context_binding_sha256 does not match the primary packet"
        )
    context_binding = packet.get("context_binding")
    calibration_receipt_sha256 = (
        context_binding.get("calibration_receipt_sha256")
        if isinstance(context_binding, dict)
        else None
    )
    if annotations.get("calibration_receipt_sha256") != calibration_receipt_sha256:
        raise ValueError(
            "annotations.calibration_receipt_sha256 does not match the "
            "primary packet; create a fresh annotation scaffold and fully "
            "re-review every judgment"
        )
    return packet


def annotation_object(
    value: Any,
    field: str,
    *,
    required: Iterable[str],
    optional: Iterable[str] = (),
) -> dict[str, Any]:
    """Return one strict compact-annotation object or fail on a typo."""
    if not isinstance(value, dict):
        raise ValueError(f"{field} must be an object")
    required_set = set(required)
    allowed = required_set | set(optional)
    missing = sorted(required_set - set(value))
    unknown = sorted(set(value) - allowed)
    if missing:
        raise ValueError(f"{field} is missing fields: {', '.join(missing)}")
    if unknown:
        raise ValueError(f"{field} has unknown fields: {', '.join(unknown)}")
    return value


def annotation_string_list(
    value: Any,
    field: str,
    *,
    allow_empty: bool = True,
) -> list[str]:
    if not isinstance(value, list) or not all(
        is_substantive_string(item) for item in value
    ):
        raise ValueError(f"{field} must be a list of substantive strings")
    if not allow_empty and not value:
        raise ValueError(f"{field} must not be empty")
    return list(value)


def validate_compile_skeleton(
    ledger: dict[str, Any], ledger_path: Path
) -> None:
    """Restrict compact compilation to a fresh, normalized extract skeleton."""
    if ledger.get("schema_version") != SCHEMA_VERSION:
        raise ValueError(
            f"compile-annotations requires artifact schema {SCHEMA_VERSION}"
        )
    if ledger.get("evidence_contract_version") != EVIDENCE_CONTRACT_VERSION:
        raise ValueError(
            "compile-annotations requires the current evidence contract"
        )
    if "migration" in ledger:
        raise ValueError("compile-annotations does not accept a migrated ledger")
    if ledger.get("steps") != []:
        raise ValueError(
            "compile-annotations requires a fresh extracted skeleton with empty steps"
        )

    review = ledger.get("review")
    if not isinstance(review, dict):
        raise ValueError("The extracted skeleton review must be an object")
    expected_review_scalars = {
        "unit_status": "not_checked",
        "conclusion_step_id": "",
        "contract_fidelity": "not_checked",
        "argument_status": "not_checked",
        "statement_status": "not_assessed",
        "dependency_closure": "not_checked",
    }
    expected_review_lists = (
        "conclusion_results",
        "explicit_assumptions",
        "inherited_assumptions",
        "direct_dependencies",
        "source_reference_dispositions",
        "candidate_dependency_dispositions",
        "citation_dispositions",
        "use_sites",
        "verification_basis",
        "reviewer_notes",
    )
    for field, expected in expected_review_scalars.items():
        if review.get(field) != expected:
            raise ValueError(
                f"compile-annotations requires fresh review.{field}={expected!r}"
            )
    for field in expected_review_lists:
        if review.get(field) != []:
            raise ValueError(
                f"compile-annotations requires fresh empty review.{field}"
            )

    independent = ledger.get("independent_check")
    if not isinstance(independent, dict):
        raise ValueError("The extracted skeleton independent_check must be an object")
    expected_independent = {
        "required": False,
        "status": "not_required",
        "independence_level": "none",
        "challenger_verdict": "not_checked",
        "reconciled_verdict": "not_checked",
        "artifact": "",
        "covered_issue_ids": [],
        "source_snapshot_sha256": "",
        "challenged_ledger_sha256": "",
        "challenge_context_sha256": "",
        "challenge_artifact_sha256": "",
        "issue_assessments": [],
        "generated_utc": "",
        "disagreements": [],
        "resolution": "",
    }
    for field, expected in expected_independent.items():
        if independent.get(field) != expected:
            raise ValueError(
                "compile-annotations requires a fresh non-required challenge; "
                f"independent_check.{field} must be {expected!r}"
            )

    obligation_errors: list[str] = []
    validate_obligation(ledger.get("obligation"), ledger_path, True, obligation_errors)
    if obligation_errors:
        shown = "; ".join(obligation_errors[:8])
        suffix = (
            f"; and {len(obligation_errors) - 8} more"
            if len(obligation_errors) > 8
            else ""
        )
        raise ValueError(
            "compile-annotations requires a completed normalized obligation: "
            + shown
            + suffix
        )


def annotation_scaffold_data(
    ledger: dict[str, Any], packet: dict[str, Any]
) -> dict[str, Any]:
    """Build a deterministic draft with mechanics filled and judgments null."""
    source = ledger.get("source")
    source_lines = ledger.get("source_lines")
    if not isinstance(source, dict) or not isinstance(source_lines, list):
        raise ValueError("The extracted skeleton has no locked source records")
    dependencies = compact_dependencies_from_packet(packet.get("dependencies"))
    steps: list[dict[str, Any]] = []
    for row in source_lines:
        if (
            not isinstance(row, dict)
            or not is_int(row.get("line"))
            or not isinstance(row.get("text"), str)
        ):
            raise ValueError("The extracted skeleton has malformed source lines")
        if locked_line_is_non_substantive(row) if "source_fragments" in ledger else is_non_substantive(row["text"]):
            continue
        line_number = int(row["line"])
        steps.append(
            {
                "key": f"line-{line_number:06d}",
                "lines": [line_number, line_number],
                "mode": None,
                "kind": None,
                "goal": None,
                "claim": None,
                "literal": (
                    (f"Coverage position {line_number}, {row['file']} line {row['source_line']}, says exactly: {row['text'].rstrip()}"
                     if "source_fragments" in ledger else f"Line {line_number} says exactly: {row['text'].rstrip()}")
                ),
                "atomicity_evidence": None,
                "adversarial": None,
                "risks": {
                    aspect: {"status": None, "evidence": None}
                    for aspect in RISK_ASPECTS
                },
                "inputs": None,
                "side_conditions": None,
                "status": None,
                "issue_ids": None,
            }
        )

    obligation = packet.get("obligation")
    raw_conclusions = (
        obligation.get("conclusions", [])
        if isinstance(obligation, dict)
        else []
    )
    conclusions = [
        {
            "conclusion_id": row.get("id"),
            "support_step": None,
            "contract_fidelity": None,
            "statement_status": None,
            "issue_ids": None,
        }
        for row in raw_conclusions
        if isinstance(row, dict)
    ]
    inventory = packet.get("inventory")
    inventory = inventory if isinstance(inventory, dict) else {}
    occurrences = inventory.get("reference_occurrences", [])
    occurrences = occurrences if isinstance(occurrences, list) else []
    source_dispositions = [
        {
            "occurrence_id": row.get("occurrence_id"),
            "target": row.get("target"),
            "command": row.get("command"),
            "disposition": None,
            "evidence": None,
        }
        for row in occurrences
        if isinstance(row, dict)
    ]
    candidate_paths = inventory.get("candidate_dependency_paths", [])
    candidate_paths = candidate_paths if isinstance(candidate_paths, list) else []
    paths_by_candidate: dict[str, list[str]] = defaultdict(list)
    for row in candidate_paths:
        if (
            isinstance(row, dict)
            and is_nonempty_string(row.get("candidate_id"))
            and is_nonempty_string(row.get("path_id"))
        ):
            paths_by_candidate[str(row["candidate_id"])].append(
                str(row["path_id"])
            )
    candidate_ids = inventory.get("candidate_internal_dependency_ids", [])
    candidate_ids = candidate_ids if isinstance(candidate_ids, list) else []
    candidate_dispositions = [
        {
            "candidate_id": str(candidate_id),
            "path_ids": sorted(paths_by_candidate.get(str(candidate_id), [])),
            "disposition": None,
            "evidence": None,
        }
        for candidate_id in candidate_ids
        if is_nonempty_string(candidate_id)
    ]
    citation_keys = inventory.get("citation_keys", [])
    citation_keys = citation_keys if isinstance(citation_keys, list) else []
    citation_dispositions = [
        {"key": str(key), "disposition": None, "evidence": None}
        for key in citation_keys
        if is_nonempty_string(key)
    ]
    context_binding = packet.get("context_binding")
    calibration_receipt_sha256 = (
        context_binding.get("calibration_receipt_sha256")
        if isinstance(context_binding, dict)
        else None
    )
    return {
        "annotation_schema_version": SEMANTIC_ANNOTATION_SCHEMA_VERSION,
        "unit_id": ledger.get("unit_id"),
        "source_unit_sha256": source.get("unit_sha256"),
        "obligation_sha256": packet.get("obligation_sha256"),
        "context_binding_sha256": packet.get("context_binding_sha256"),
        "calibration_receipt_sha256": calibration_receipt_sha256,
        "source_groups": [],
        "dependencies": dependencies,
        "steps": steps,
        "conclusions": conclusions,
        "review": {
            "explicit_assumptions": None,
            "inherited_assumptions": None,
            "source_reference_dispositions": source_dispositions,
            "candidate_dependency_dispositions": candidate_dispositions,
            "citation_dispositions": citation_dispositions,
            "verification_basis": None,
            "reviewer_notes": [],
        },
    }


def cmd_annotation_scaffold(args: argparse.Namespace) -> int:
    configure_console_errors()
    ledger_path = args.ledger.resolve()
    packet_path = args.packet.resolve()
    output_path = args.output.resolve()
    if not ledger_path.is_file():
        raise FileNotFoundError(f"Extracted ledger not found: {ledger_path}")
    if not packet_path.is_file():
        raise FileNotFoundError(f"Primary context packet not found: {packet_path}")
    if not ledger_path.name.endswith(".skeleton.json"):
        raise ValueError("Annotation scaffold input must end in .skeleton.json")
    if not output_path.name.endswith(".annotations.json"):
        raise ValueError("Annotation scaffold output must end in .annotations.json")
    if output_path in {ledger_path, packet_path}:
        raise ValueError("Annotation scaffold output must be a distinct file")
    ledger, ledger_errors = load_json_object(ledger_path, "extracted ledger")
    if ledger_errors:
        raise ValueError(ledger_errors[0])
    validate_compile_skeleton(ledger, ledger_path)
    audit_root = containing_audit_root(ledger_path)
    if audit_root is None:
        raise ValueError(
            "annotation-scaffold requires a skeleton inside a canonical audit root"
        )
    if output_path.is_relative_to(audit_root):
        raise ValueError("Annotation scaffold output must remain outside the audit root")
    packet = validate_current_primary_packet(ledger, ledger_path, packet_path)
    scaffold = annotation_scaffold_data(ledger, packet)
    atomic_create_json(output_path, scaffold, "Annotation scaffold")
    print(
        json.dumps(
            {
                "command": "annotation-scaffold",
                "status": "written",
                "unit_id": ledger.get("unit_id"),
                "annotations": output_path.as_posix(),
                "source_steps": len(scaffold["steps"]),
                "dependencies": len(scaffold["dependencies"]),
                "conclusions": len(scaffold["conclusions"]),
                "context_binding_sha256": packet.get(
                    "context_binding_sha256"
                ),
            },
            ensure_ascii=True,
            indent=2,
        )
    )
    return 0


def cmd_rebind_annotations(args: argparse.Namespace) -> int:
    """Mechanically copy current packet binding hashes into an annotation file.

    Rebinding is deterministic bookkeeping only. It never edits a judgment,
    and it does not certify that the authored judgments remain valid for the
    regenerated packet; the checker must confirm that separately whenever the
    semantic context changed.
    """
    configure_console_errors()
    annotations_path = args.annotations.resolve()
    packet_path = args.packet.resolve()
    if not annotations_path.is_file():
        raise FileNotFoundError(
            f"Compact annotations not found: {annotations_path}"
        )
    if not annotations_path.name.endswith(".annotations.json"):
        raise ValueError("rebind-annotations input must end in .annotations.json")
    if not packet_path.is_file():
        raise FileNotFoundError(f"Context packet not found: {packet_path}")
    annotations, annotation_errors = load_json_object(
        annotations_path, "compact annotations"
    )
    if annotation_errors:
        raise ValueError(annotation_errors[0])
    packet, packet_errors = load_json_object(packet_path, "context packet")
    if packet_errors:
        raise ValueError(packet_errors[0])
    if packet.get("mode") != "primary":
        raise ValueError("rebind-annotations requires a primary context packet")
    annotation_unit = annotations.get("unit_id")
    packet_unit = packet.get("unit_id")
    if (
        not is_nonempty_string(annotation_unit)
        or annotation_unit != packet_unit
    ):
        raise ValueError(
            "rebind-annotations unit mismatch: annotations name "
            f"{annotation_unit!r} but the packet names {packet_unit!r}"
        )
    audit_root = containing_audit_root(annotations_path)
    if audit_root is not None:
        raise ValueError(
            "Compact annotations must remain outside the canonical audit root"
        )
    obligation_sha256 = packet.get("obligation_sha256")
    context_binding_sha256 = packet.get("context_binding_sha256")
    context_binding = packet.get("context_binding")
    if (
        not isinstance(context_binding, dict)
        or packet.get("context_binding_sha256")
        != canonical_sha256(context_binding)
    ):
        raise ValueError("The packet context binding is malformed or modified")
    calibration_receipt_sha256 = context_binding.get(
        "calibration_receipt_sha256"
    )
    if not is_nonempty_string(obligation_sha256) or not is_nonempty_string(
        context_binding_sha256
    ) or not (
        isinstance(calibration_receipt_sha256, str)
        and SHA256_RE.fullmatch(calibration_receipt_sha256)
    ):
        raise ValueError("The packet does not carry complete binding hashes")
    previous_calibration = annotations.get("calibration_receipt_sha256")
    if previous_calibration != calibration_receipt_sha256:
        raise ValueError(
            "rebind-annotations refuses a changed or missing calibration "
            "receipt; create a fresh annotation scaffold and fully re-review "
            "every judgment under the new calibration"
        )
    previous = {
        "obligation_sha256": annotations.get("obligation_sha256"),
        "context_binding_sha256": annotations.get("context_binding_sha256"),
        "source_unit_sha256": annotations.get("source_unit_sha256"),
    }
    annotations["obligation_sha256"] = obligation_sha256
    annotations["context_binding_sha256"] = context_binding_sha256
    updated_fields = ["context_binding_sha256", "obligation_sha256"]
    if args.skeleton is not None:
        skeleton_path = args.skeleton.resolve()
        if not skeleton_path.is_file():
            raise FileNotFoundError(
                f"Extracted skeleton not found: {skeleton_path}"
            )
        skeleton, skeleton_errors = load_json_object(
            skeleton_path, "extracted skeleton"
        )
        if skeleton_errors:
            raise ValueError(skeleton_errors[0])
        if skeleton.get("unit_id") != annotation_unit:
            raise ValueError(
                "rebind-annotations skeleton unit mismatch: the skeleton names "
                f"{skeleton.get('unit_id')!r}"
            )
        source = skeleton.get("source")
        unit_sha256 = (
            source.get("unit_sha256") if isinstance(source, dict) else None
        )
        if not is_nonempty_string(unit_sha256):
            raise ValueError("The skeleton does not carry source.unit_sha256")
        annotations["source_unit_sha256"] = unit_sha256
        updated_fields.append("source_unit_sha256")
    atomic_write_json(annotations_path, annotations)
    changed = sorted(
        field
        for field in updated_fields
        if previous.get(field) != annotations.get(field)
    )
    print(
        json.dumps(
            {
                "command": "rebind-annotations",
                "status": "rebound",
                "unit_id": annotation_unit,
                "annotations": annotations_path.as_posix(),
                "updated_fields": sorted(updated_fields),
                "changed_fields": changed,
                "obligation_sha256": obligation_sha256,
                "context_binding_sha256": context_binding_sha256,
                "calibration_receipt_sha256": calibration_receipt_sha256,
                "judgment_review_required": bool(changed),
                "note": (
                    "Rebinding copies current binding hashes only. Confirm that "
                    "every authored judgment remains valid for the regenerated "
                    "packet before compiling."
                ),
            },
            ensure_ascii=True,
            indent=2,
        )
    )
    return 0


def json_pointer_child(pointer: str, token: Any) -> str:
    escaped = str(token).replace("~", "~0").replace("/", "~1")
    return f"{pointer}/{escaped}" if pointer else f"/{escaped}"


def append_annotation_diagnostic(
    diagnostics: list[dict[str, str]],
    pointer: str,
    code: str,
    message: str,
    *,
    document: str = "annotations",
) -> None:
    diagnostics.append(
        {
            "document": document,
            "pointer": pointer,
            "code": code,
            "message": message,
        }
    )


def annotation_object_diagnostics(
    value: Any,
    pointer: str,
    diagnostics: list[dict[str, str]],
    *,
    required: Iterable[str],
    optional: Iterable[str] = (),
) -> bool:
    if not isinstance(value, dict):
        append_annotation_diagnostic(
            diagnostics, pointer, "wrong_type", "must be an object"
        )
        return False
    required_set = set(required)
    allowed = required_set | set(optional)
    for field in sorted(required_set - set(value)):
        append_annotation_diagnostic(
            diagnostics,
            json_pointer_child(pointer, field),
            "missing_field",
            f"required field is missing; missing fields: {field}",
        )
    for field in sorted(set(value) - allowed):
        append_annotation_diagnostic(
            diagnostics,
            json_pointer_child(pointer, field),
            "unknown_field",
            "field is not part of compact annotation schema "
            f"{SEMANTIC_ANNOTATION_SCHEMA_VERSION}; "
            f"unknown fields: {field}",
        )
    return True


def annotation_null_diagnostics(
    value: Any,
    pointer: str,
    diagnostics: list[dict[str, str]],
) -> None:
    if value is None:
        append_annotation_diagnostic(
            diagnostics,
            pointer,
            "incomplete_judgment",
            "replace null with an authored judgment",
        )
    elif isinstance(value, dict):
        for key in sorted(value):
            annotation_null_diagnostics(
                value[key], json_pointer_child(pointer, key), diagnostics
            )
    elif isinstance(value, list):
        for index, item in enumerate(value):
            annotation_null_diagnostics(
                item, json_pointer_child(pointer, index), diagnostics
            )


def annotation_enum_diagnostic(
    value: Any,
    pointer: str,
    allowed: Iterable[str],
    diagnostics: list[dict[str, str]],
) -> None:
    allowed_values = set(allowed)
    if value is not None and (
        not isinstance(value, str) or value not in allowed_values
    ):
        append_annotation_diagnostic(
            diagnostics,
            pointer,
            "invalid_enum",
            "must be one of: " + ", ".join(sorted(allowed_values)),
        )


def annotation_string_diagnostic(
    value: Any,
    pointer: str,
    diagnostics: list[dict[str, str]],
    *,
    substantive: bool = True,
) -> None:
    if value is None:
        return
    valid = is_substantive_string(value) if substantive else is_nonempty_string(value)
    if not valid:
        append_annotation_diagnostic(
            diagnostics,
            pointer,
            "invalid_string",
            "must be substantive" if substantive else "must be nonempty",
        )


def annotation_string_list_diagnostics(
    value: Any,
    pointer: str,
    diagnostics: list[dict[str, str]],
    *,
    allow_empty: bool = True,
    pattern: re.Pattern[str] | None = None,
) -> None:
    if value is None:
        return
    if not isinstance(value, list):
        append_annotation_diagnostic(
            diagnostics, pointer, "wrong_type", "must be a list"
        )
        return
    if not allow_empty and not value:
        append_annotation_diagnostic(
            diagnostics, pointer, "empty_list", "must be a nonempty list"
        )
    seen: set[str] = set()
    for index, item in enumerate(value):
        item_pointer = json_pointer_child(pointer, index)
        if not is_substantive_string(item) or (
            pattern is not None and not pattern.fullmatch(str(item))
        ):
            append_annotation_diagnostic(
                diagnostics,
                item_pointer,
                "invalid_id" if pattern is not None else "invalid_string",
                "has an invalid identifier" if pattern is not None else "must be substantive",
            )
            continue
        if str(item) in seen:
            append_annotation_diagnostic(
                diagnostics, item_pointer, "duplicate_id", f"duplicate value {item}"
            )
        seen.add(str(item))


def annotation_range_diagnostic(
    value: Any, pointer: str, diagnostics: list[dict[str, str]]
) -> None:
    if value is not None and (
        not isinstance(value, list)
        or len(value) != 2
        or not all(is_int(item) for item in value)
    ):
        append_annotation_diagnostic(
            diagnostics, pointer, "invalid_range", "must be [start, end]"
        )


def annotation_identity_diagnostics(
    actual: Any,
    expected: list[dict[str, Any]],
    pointer: str,
    identity_field: str,
    deterministic_fields: Iterable[str],
    diagnostics: list[dict[str, str]],
    *,
    unordered_fields: Iterable[str] = (),
) -> None:
    if not isinstance(actual, list):
        append_annotation_diagnostic(
            diagnostics, pointer, "wrong_type", "must be a list"
        )
        return
    expected_by_id = {
        str(row.get(identity_field)): row
        for row in expected
        if isinstance(row, dict)
    }
    actual_by_id: dict[str, tuple[int, dict[str, Any]]] = {}
    for index, row in enumerate(actual):
        item_pointer = json_pointer_child(pointer, index)
        if not isinstance(row, dict):
            append_annotation_diagnostic(
                diagnostics, item_pointer, "wrong_type", "must be an object"
            )
            continue
        identity = row.get(identity_field)
        if not is_nonempty_string(identity):
            append_annotation_diagnostic(
                diagnostics,
                json_pointer_child(item_pointer, identity_field),
                "invalid_id",
                f"must identify one packet {identity_field}",
            )
            continue
        identity = str(identity)
        if identity in actual_by_id:
            append_annotation_diagnostic(
                diagnostics,
                json_pointer_child(item_pointer, identity_field),
                "duplicate_id",
                f"duplicate {identity_field} {identity}",
            )
            continue
        actual_by_id[identity] = (index, row)
    for identity in sorted(set(expected_by_id) - set(actual_by_id)):
        append_annotation_diagnostic(
            diagnostics,
            pointer,
            "missing_packet_record",
            f"missing packet {identity_field} {identity}",
        )
    for identity in sorted(set(actual_by_id) - set(expected_by_id)):
        index, _ = actual_by_id[identity]
        append_annotation_diagnostic(
            diagnostics,
            json_pointer_child(pointer, index),
            "stale_packet_record",
            f"{identity_field} {identity} is not present in the packet",
        )
    for identity in sorted(set(actual_by_id) & set(expected_by_id)):
        index, row = actual_by_id[identity]
        expected_row = expected_by_id[identity]
        unordered = set(unordered_fields)
        for field in deterministic_fields:
            actual_value = row.get(field)
            expected_value = expected_row.get(field)
            if (
                field in unordered
                and isinstance(actual_value, list)
                and isinstance(expected_value, list)
            ):
                actual_value = sorted(actual_value, key=str)
                expected_value = sorted(expected_value, key=str)
            if actual_value != expected_value:
                append_annotation_diagnostic(
                    diagnostics,
                    json_pointer_child(
                        json_pointer_child(pointer, index), field
                    ),
                    "packet_mismatch",
                    f"must exactly match packet {identity_field} {identity}",
                )


def annotation_preflight_diagnostics(
    ledger: dict[str, Any],
    ledger_path: Path,
    annotations: dict[str, Any],
    packet: dict[str, Any],
    *,
    deep_validation: bool = True,
) -> list[dict[str, str]]:
    diagnostics: list[dict[str, str]] = []
    expected = annotation_scaffold_data(ledger, packet)
    if annotation_object_diagnostics(
        annotations,
        "",
        diagnostics,
        required=COMPACT_ANNOTATION_TOP_LEVEL_FIELDS,
    ):
        for field in (
            "annotation_schema_version",
            "unit_id",
            "source_unit_sha256",
            "obligation_sha256",
            "context_binding_sha256",
            "calibration_receipt_sha256",
        ):
            if field in annotations and annotations.get(field) != expected.get(field):
                append_annotation_diagnostic(
                    diagnostics,
                    json_pointer_child("", field),
                    "binding_mismatch",
                    "must exactly match the current skeleton and primary packet",
                )

    source_groups = annotations.get("source_groups")
    if isinstance(source_groups, list):
        source = ledger.get("source")
        source_start, source_end = source_coverage_bounds(ledger)
        previous_group_end = source_start - 1 if is_int(source_start) else None
        for index, group in enumerate(source_groups):
            pointer = f"/source_groups/{index}"
            if annotation_object_diagnostics(
                group,
                pointer,
                diagnostics,
                required=("lines", "kind", "partition_evidence"),
            ):
                annotation_range_diagnostic(
                    group.get("lines"), f"{pointer}/lines", diagnostics
                )
                line_range = group.get("lines")
                if (
                    isinstance(line_range, list)
                    and len(line_range) == 2
                    and all(is_int(item) for item in line_range)
                    and is_int(source_start)
                    and is_int(source_end)
                ):
                    group_start, group_end = line_range
                    if (
                        group_start < source_start
                        or group_end > source_end
                        or group_end <= group_start
                    ):
                        append_annotation_diagnostic(
                            diagnostics,
                            f"{pointer}/lines",
                            "invalid_range",
                            f"must be a multiline range inside {source_start}-{source_end}",
                        )
                    elif (
                        previous_group_end is not None
                        and group_start <= previous_group_end
                    ):
                        append_annotation_diagnostic(
                            diagnostics,
                            f"{pointer}/lines",
                            "overlapping_range",
                            "source groups must be disjoint and in source order",
                        )
                    previous_group_end = max(previous_group_end, group_end)
                annotation_enum_diagnostic(
                    group.get("kind"),
                    f"{pointer}/kind",
                    {"continued_sentence", "continued_display"},
                    diagnostics,
                )
                annotation_string_diagnostic(
                    group.get("partition_evidence"),
                    f"{pointer}/partition_evidence",
                    diagnostics,
                )
    elif "source_groups" in annotations:
        append_annotation_diagnostic(
            diagnostics, "/source_groups", "wrong_type", "must be a list"
        )

    actual_dependencies = annotations.get("dependencies")
    annotation_identity_diagnostics(
        actual_dependencies,
        expected["dependencies"],
        "/dependencies",
        "use_id",
        (
            "id",
            "use_id",
            "kind",
            "status",
            "needed_form",
            "compatibility_check",
            "conclusion_id",
        ),
        diagnostics,
    )
    if isinstance(actual_dependencies, list):
        for index, row in enumerate(actual_dependencies):
            pointer = f"/dependencies/{index}"
            if annotation_object_diagnostics(
                row,
                pointer,
                diagnostics,
                required=(
                    "id",
                    "use_id",
                    "kind",
                    "status",
                    "needed_form",
                    "compatibility_check",
                ),
                optional=("conclusion_id", "statement_support_sha256"),
            ):
                annotation_string_diagnostic(
                    row.get("id"), f"{pointer}/id", diagnostics
                )
                annotation_string_diagnostic(
                    row.get("use_id"),
                    f"{pointer}/use_id",
                    diagnostics,
                    substantive=False,
                )
                if row.get("use_id") is not None and (
                    not isinstance(row.get("use_id"), str)
                    or not DEPENDENCY_USE_ID_RE.fullmatch(row["use_id"])
                ):
                    append_annotation_diagnostic(
                        diagnostics,
                        f"{pointer}/use_id",
                        "invalid_id",
                        "must identify a dependency use such as D001",
                    )
                annotation_enum_diagnostic(
                    row.get("kind"),
                    f"{pointer}/kind",
                    {"internal_result", "external_result"},
                    diagnostics,
                )
                annotation_enum_diagnostic(
                    row.get("status"),
                    f"{pointer}/status",
                    DEPENDENCY_STATUSES - {"not_applicable"},
                    diagnostics,
                )
                for field in ("needed_form", "compatibility_check"):
                    annotation_string_diagnostic(
                        row.get(field), f"{pointer}/{field}", diagnostics
                    )
                if row.get("kind") == "internal_result":
                    conclusion_id = row.get("conclusion_id")
                    if conclusion_id is not None and (
                        not isinstance(conclusion_id, str)
                        or not CONCLUSION_ID_RE.fullmatch(conclusion_id)
                    ):
                        append_annotation_diagnostic(
                            diagnostics,
                            f"{pointer}/conclusion_id",
                            "invalid_id",
                            "must identify a conclusion such as C001",
                        )

    step_key_positions: dict[str, int] = {}
    steps = annotations.get("steps")
    if not isinstance(steps, list):
        if "steps" in annotations:
            append_annotation_diagnostic(
                diagnostics, "/steps", "wrong_type", "must be a list"
            )
    else:
        step_key_positions = {
            str(step.get("key")): index
            for index, step in enumerate(steps)
            if isinstance(step, dict) and is_nonempty_string(step.get("key"))
        }
        dependency_use_ids = {
            str(row.get("use_id"))
            for row in actual_dependencies
            if isinstance(row, dict) and is_nonempty_string(row.get("use_id"))
        } if isinstance(actual_dependencies, list) else set()
        seen_keys: set[str] = set()
        for index, step in enumerate(steps):
            pointer = f"/steps/{index}"
            if not annotation_object_diagnostics(
                step,
                pointer,
                diagnostics,
                required=COMPACT_STEP_FIELDS - COMPACT_STEP_OPTIONAL_FIELDS,
                optional=COMPACT_STEP_OPTIONAL_FIELDS,
            ):
                continue
            key = step.get("key")
            if is_nonempty_string(key):
                if str(key) in seen_keys:
                    append_annotation_diagnostic(
                        diagnostics,
                        f"{pointer}/key",
                        "duplicate_id",
                        f"duplicate step key {key}",
                    )
                seen_keys.add(str(key))
            elif key is not None:
                annotation_string_diagnostic(
                    key, f"{pointer}/key", diagnostics, substantive=False
                )
            annotation_range_diagnostic(
                step.get("lines"), f"{pointer}/lines", diagnostics
            )
            annotation_enum_diagnostic(
                step.get("mode"),
                f"{pointer}/mode",
                {"noninferential", "derivation", "reuse"},
                diagnostics,
            )
            annotation_enum_diagnostic(
                step.get("kind"), f"{pointer}/kind", STEP_KINDS, diagnostics
            )
            annotation_enum_diagnostic(
                step.get("status"),
                f"{pointer}/status",
                STEP_STATUSES - {"non_substantive"},
                diagnostics,
            )
            for field in ("goal", "claim", "literal", "atomicity_evidence"):
                annotation_string_diagnostic(
                    step.get(field), f"{pointer}/{field}", diagnostics
                )
            annotation_string_list_diagnostics(
                step.get("adversarial"),
                f"{pointer}/adversarial",
                diagnostics,
                allow_empty=False,
            )
            annotation_string_list_diagnostics(
                step.get("issue_ids"),
                f"{pointer}/issue_ids",
                diagnostics,
                pattern=ISSUE_ID_RE,
            )
            risks = step.get("risks")
            if annotation_object_diagnostics(
                risks,
                f"{pointer}/risks",
                diagnostics,
                required=RISK_ASPECTS,
            ):
                shorthand_aspects: list[str] = []
                for aspect in RISK_ASPECTS:
                    if aspect in risks:
                        risk = risks[aspect]
                        if isinstance(risk, str):
                            if risk == "not_applicable":
                                shorthand_aspects.append(aspect)
                            else:
                                append_annotation_diagnostic(
                                    diagnostics,
                                    f"{pointer}/risks/{aspect}",
                                    "invalid_enum",
                                    "string shorthand must be exactly not_applicable",
                                )
                        elif annotation_object_diagnostics(
                            risk,
                            f"{pointer}/risks/{aspect}",
                            diagnostics,
                            required=("status", "evidence"),
                        ):
                            annotation_enum_diagnostic(
                                risk.get("status"),
                                f"{pointer}/risks/{aspect}/status",
                                RISK_STATUSES,
                                diagnostics,
                            )
                            annotation_string_diagnostic(
                                risk.get("evidence"),
                                f"{pointer}/risks/{aspect}/evidence",
                                diagnostics,
                            )
                basis_pointer = f"{pointer}/not_applicable_basis"
                if shorthand_aspects:
                    if "not_applicable_basis" not in step:
                        append_annotation_diagnostic(
                            diagnostics,
                            basis_pointer,
                            "missing_field",
                            "required when any risk uses not_applicable shorthand",
                        )
                    else:
                        annotation_string_diagnostic(
                            step.get("not_applicable_basis"),
                            basis_pointer,
                            diagnostics,
                        )
                elif "not_applicable_basis" in step:
                    annotation_string_diagnostic(
                        step.get("not_applicable_basis"),
                        basis_pointer,
                        diagnostics,
                    )
                    append_annotation_diagnostic(
                        diagnostics,
                        basis_pointer,
                        "unused_field",
                        "remove this field unless at least one risk uses the "
                        "not_applicable shorthand",
                    )
            inputs = step.get("inputs")
            if isinstance(inputs, list):
                for input_index, compact_input in enumerate(inputs):
                    input_pointer = f"{pointer}/inputs/{input_index}"
                    if annotation_object_diagnostics(
                        compact_input,
                        input_pointer,
                        diagnostics,
                        required=("kind", "reference", "role", "evidence"),
                        optional=(
                            "anchor",
                            "compatibility_check",
                            "source_reference_id",
                            "source_reference_occurrence_id",
                        ),
                    ) and isinstance(compact_input, dict):
                        annotation_enum_diagnostic(
                            compact_input.get("kind"),
                            f"{input_pointer}/kind",
                            {"obligation", "prior_step", "dependency"},
                            diagnostics,
                        )
                        annotation_string_diagnostic(
                            compact_input.get("reference"),
                            f"{input_pointer}/reference",
                            diagnostics,
                            substantive=False,
                        )
                        annotation_enum_diagnostic(
                            compact_input.get("role"),
                            f"{input_pointer}/role",
                            PREMISE_ROLES,
                            diagnostics,
                        )
                        annotation_string_diagnostic(
                            compact_input.get("evidence"),
                            f"{input_pointer}/evidence",
                            diagnostics,
                        )
                        if "compatibility_check" in compact_input:
                            annotation_string_diagnostic(
                                compact_input.get("compatibility_check"),
                                f"{input_pointer}/compatibility_check",
                                diagnostics,
                            )
                        if "anchor" in compact_input:
                            anchor = compact_input.get("anchor")
                            if annotation_object_diagnostics(
                                anchor,
                                f"{input_pointer}/anchor",
                                diagnostics,
                                required=("kind", "index"),
                            ) and compact_input.get("kind") == "obligation":
                                annotation_enum_diagnostic(
                                    anchor.get("kind"),
                                    f"{input_pointer}/anchor/kind",
                                    {"statement_span", "context_span"},
                                    diagnostics,
                                )
                                if not is_int(anchor.get("index")) or anchor["index"] < 1:
                                    append_annotation_diagnostic(
                                        diagnostics,
                                        f"{input_pointer}/anchor/index",
                                        "invalid_value",
                                        "must be a positive one-based integer (not a Boolean)",
                                    )
                        input_kind = compact_input.get("kind")
                        reference = compact_input.get("reference")
                        if input_kind == "obligation":
                            if "anchor" not in compact_input:
                                append_annotation_diagnostic(
                                    diagnostics,
                                    f"{input_pointer}/anchor",
                                    "missing_conditional_field",
                                    "an obligation input requires an exact anchor",
                                )
                            if "compatibility_check" in compact_input:
                                append_annotation_diagnostic(
                                    diagnostics,
                                    f"{input_pointer}/compatibility_check",
                                    "forbidden_conditional_field",
                                    "an obligation input cannot carry compatibility_check",
                                )
                        elif input_kind == "prior_step":
                            if "anchor" in compact_input:
                                append_annotation_diagnostic(
                                    diagnostics,
                                    f"{input_pointer}/anchor",
                                    "forbidden_conditional_field",
                                    "a prior-step input cannot carry an anchor",
                                )
                            if "compatibility_check" not in compact_input:
                                append_annotation_diagnostic(
                                    diagnostics,
                                    f"{input_pointer}/compatibility_check",
                                    "missing_conditional_field",
                                    "a prior-step input requires compatibility_check",
                                )
                            reference_position = step_key_positions.get(str(reference))
                            if reference_position is None:
                                append_annotation_diagnostic(
                                    diagnostics,
                                    f"{input_pointer}/reference",
                                    "unknown_reference",
                                    "does not identify a compact step key",
                                )
                            elif reference_position >= index:
                                append_annotation_diagnostic(
                                    diagnostics,
                                    f"{input_pointer}/reference",
                                    "forward_reference",
                                    "must identify a step established earlier",
                                )
                            elif steps[reference_position].get("mode") == "noninferential":
                                append_annotation_diagnostic(
                                    diagnostics,
                                    f"{input_pointer}/reference",
                                    "unsupported_premise_root",
                                    f"step {reference} is noninferential and cannot supply "
                                    "a factual premise; link the normalized premise or "
                                    "record an introduction inference in that step",
                                )
                        elif input_kind == "dependency":
                            for field in ("anchor", "compatibility_check"):
                                if field in compact_input:
                                    append_annotation_diagnostic(
                                        diagnostics,
                                        f"{input_pointer}/{field}",
                                        "forbidden_conditional_field",
                                        f"a dependency input cannot carry {field}",
                                    )
                            if str(reference) not in dependency_use_ids:
                                append_annotation_diagnostic(
                                    diagnostics,
                                    f"{input_pointer}/reference",
                                    "unknown_reference",
                                    "does not identify a direct dependency use",
                                )
                        source_id = compact_input.get("source_reference_id")
                        occurrence_id = compact_input.get(
                            "source_reference_occurrence_id"
                        )
                        if bool(is_nonempty_string(source_id)) != bool(
                            is_nonempty_string(occurrence_id)
                        ):
                            append_annotation_diagnostic(
                                diagnostics,
                                input_pointer,
                                "incomplete_reference_pair",
                                "source-reference anchoring requires both IDs",
                            )
            elif inputs is not None:
                append_annotation_diagnostic(
                    diagnostics,
                    f"{pointer}/inputs",
                    "wrong_type",
                    "must be a list",
                )
            side_conditions = step.get("side_conditions")
            if isinstance(side_conditions, list):
                for condition_index, condition in enumerate(side_conditions):
                    condition_pointer = (
                        f"{pointer}/side_conditions/{condition_index}"
                    )
                    if annotation_object_diagnostics(
                        condition,
                        condition_pointer,
                        diagnostics,
                        required=("condition", "status"),
                        optional=("discharge",),
                    ):
                        annotation_string_diagnostic(
                            condition.get("condition"),
                            f"{condition_pointer}/condition",
                            diagnostics,
                        )
                        annotation_enum_diagnostic(
                            condition.get("status"),
                            f"{condition_pointer}/status",
                            {"open", "discharged"},
                            diagnostics,
                        )
                        status = condition.get("status")
                        if status == "open" and "discharge" in condition:
                            append_annotation_diagnostic(
                                diagnostics,
                                f"{condition_pointer}/discharge",
                                "forbidden_conditional_field",
                                "an open condition cannot have a discharge",
                            )
                        if status == "discharged" and "discharge" not in condition:
                            append_annotation_diagnostic(
                                diagnostics,
                                f"{condition_pointer}/discharge",
                                "missing_conditional_field",
                                "a discharged condition requires discharge evidence",
                            )
                        discharge = condition.get("discharge")
                        if status == "discharged" and annotation_object_diagnostics(
                            discharge,
                            f"{condition_pointer}/discharge",
                            diagnostics,
                            required=("sources", "rule", "evidence"),
                        ):
                            annotation_string_diagnostic(
                                discharge.get("rule"),
                                f"{condition_pointer}/discharge/rule",
                                diagnostics,
                            )
                            annotation_string_diagnostic(
                                discharge.get("evidence"),
                                f"{condition_pointer}/discharge/evidence",
                                diagnostics,
                            )
                            sources = discharge.get("sources")
                            if not isinstance(sources, list) or not sources:
                                append_annotation_diagnostic(
                                    diagnostics,
                                    f"{condition_pointer}/discharge/sources",
                                    "wrong_type",
                                    "must be a nonempty list",
                                )
                            else:
                                for source_index, source in enumerate(sources):
                                    source_pointer = (
                                        f"{condition_pointer}/discharge/sources/"
                                        f"{source_index}"
                                    )
                                    if annotation_object_diagnostics(
                                        source,
                                        source_pointer,
                                        diagnostics,
                                        required=("input", "contribution"),
                                    ):
                                        input_number = source.get("input")
                                        if not is_int(input_number) or input_number < 1:
                                            append_annotation_diagnostic(
                                                diagnostics,
                                                f"{source_pointer}/input",
                                                "invalid_id",
                                                "must identify one compact input",
                                            )
                                        annotation_string_diagnostic(
                                            source.get("contribution"),
                                            f"{source_pointer}/contribution",
                                            diagnostics,
                                        )
            elif side_conditions is not None:
                append_annotation_diagnostic(
                    diagnostics,
                    f"{pointer}/side_conditions",
                    "wrong_type",
                    "must be a list",
                )
            if isinstance(step, dict):
                mode = step.get("mode")
                if mode in {"derivation", "reuse"}:
                    for field in ("rule", "justification"):
                        if field not in step:
                            append_annotation_diagnostic(
                                diagnostics,
                                f"{pointer}/{field}",
                                "missing_conditional_field",
                                f"{field} must be authored for every move "
                                f"in {mode} mode",
                            )
                        else:
                            annotation_string_diagnostic(
                                step.get(field), f"{pointer}/{field}", diagnostics
                            )
                elif mode == "noninferential":
                    for field in ("rule", "justification", "failure"):
                        if field in step:
                            append_annotation_diagnostic(
                                diagnostics,
                                f"{pointer}/{field}",
                                "forbidden_conditional_field",
                                f"{field} is not allowed for noninferential mode",
                            )
                if "failure" in step:
                    if annotation_object_diagnostics(
                        step.get("failure"),
                        f"{pointer}/failure",
                        diagnostics,
                        required=("kind", "issue_id", "evidence"),
                        optional=("target", "computation"),
                    ):
                        failure = step["failure"]
                        annotation_enum_diagnostic(
                            failure.get("kind"),
                            f"{pointer}/failure/kind",
                            MOVE_FAILURE_KINDS,
                            diagnostics,
                        )
                        annotation_string_diagnostic(
                            failure.get("evidence"),
                            f"{pointer}/failure/evidence",
                            diagnostics,
                        )
                        issue_id = failure.get("issue_id")
                        if issue_id is not None and (
                            not isinstance(issue_id, str)
                            or not ISSUE_ID_RE.fullmatch(issue_id)
                        ):
                            append_annotation_diagnostic(
                                diagnostics,
                                f"{pointer}/failure/issue_id",
                                "invalid_id",
                                "must identify an issue such as I-001",
                            )
                        if "target" in failure:
                            annotation_string_diagnostic(
                                failure.get("target"),
                                f"{pointer}/failure/target",
                                diagnostics,
                            )
                        if failure.get("kind") in REFUTATION_FAILURE_KINDS and (
                            "computation" not in failure
                        ):
                            append_annotation_diagnostic(
                                diagnostics,
                                f"{pointer}/failure/computation",
                                "missing_conditional_field",
                                "a counterexample or contradiction failure "
                                "requires a computation record: instantiate "
                                "it as a hash-locked script under "
                                "audit/05_adversarial, or record status "
                                "not_instantiable with a substantive reason",
                            )
                        if "computation" in failure:
                            for message in failure_computation_shape_errors(
                                failure.get("computation"),
                                f"{pointer}/failure/computation",
                            ):
                                append_annotation_diagnostic(
                                    diagnostics,
                                    f"{pointer}/failure/computation",
                                    "invalid_computation",
                                    message,
                                )

    conclusions = annotations.get("conclusions")
    annotation_identity_diagnostics(
        conclusions,
        expected["conclusions"],
        "/conclusions",
        "conclusion_id",
        ("conclusion_id",),
        diagnostics,
    )
    if isinstance(conclusions, list):
        for index, row in enumerate(conclusions):
            pointer = f"/conclusions/{index}"
            if annotation_object_diagnostics(
                row,
                pointer,
                diagnostics,
                required=(
                    "conclusion_id",
                    "support_step",
                    "contract_fidelity",
                    "statement_status",
                    "issue_ids",
                ),
                optional=("statement_support",),
            ):
                annotation_string_diagnostic(
                    row.get("support_step"),
                    f"{pointer}/support_step",
                    diagnostics,
                    substantive=False,
                )
                support_step = row.get("support_step")
                if (
                    support_step is not None
                    and str(support_step) not in step_key_positions
                ):
                    append_annotation_diagnostic(
                        diagnostics,
                        f"{pointer}/support_step",
                        "unknown_reference",
                        "does not identify a compact step key",
                    )
                annotation_enum_diagnostic(
                    row.get("contract_fidelity"),
                    f"{pointer}/contract_fidelity",
                    UNIT_STATUSES,
                    diagnostics,
                )
                annotation_enum_diagnostic(
                    row.get("statement_status"),
                    f"{pointer}/statement_status",
                    STATEMENT_STATUSES,
                    diagnostics,
                )
                annotation_string_list_diagnostics(
                    row.get("issue_ids"),
                    f"{pointer}/issue_ids",
                    diagnostics,
                    pattern=ISSUE_ID_RE,
                )

    review = annotations.get("review")
    review_fields = (
        "explicit_assumptions",
        "inherited_assumptions",
        "source_reference_dispositions",
        "candidate_dependency_dispositions",
        "citation_dispositions",
        "verification_basis",
        "reviewer_notes",
    )
    if annotation_object_diagnostics(
        review, "/review", diagnostics, required=review_fields
    ):
        source_rows = review.get("source_reference_dispositions")
        annotation_identity_diagnostics(
            source_rows,
            expected["review"]["source_reference_dispositions"],
            "/review/source_reference_dispositions",
            "occurrence_id",
            ("occurrence_id", "target", "command"),
            diagnostics,
        )
        if isinstance(source_rows, list):
            for index, row in enumerate(source_rows):
                pointer = f"/review/source_reference_dispositions/{index}"
                if annotation_object_diagnostics(
                    row,
                    pointer,
                    diagnostics,
                    required=(
                        "occurrence_id",
                        "target",
                        "command",
                        "disposition",
                        "evidence",
                    ),
                    optional=("dependency_use_id",),
                ):
                    annotation_enum_diagnostic(
                        row.get("disposition"),
                        f"{pointer}/disposition",
                        {
                            "internal_result",
                            "obligation_context",
                            "local_step",
                            "own_result_identification",
                            "navigation",
                            "non_load_bearing",
                            "unresolved",
                        },
                        diagnostics,
                    )
                    annotation_string_diagnostic(
                        row.get("evidence"), f"{pointer}/evidence", diagnostics
                    )
                    disposition = row.get("disposition")
                    if disposition == "internal_result":
                        use_id = row.get("dependency_use_id")
                        if (
                            not isinstance(use_id, str)
                            or not DEPENDENCY_USE_ID_RE.fullmatch(use_id)
                        ):
                            append_annotation_diagnostic(
                                diagnostics,
                                f"{pointer}/dependency_use_id",
                                "missing_conditional_field",
                                "internal_result requires a dependency use such as D001",
                            )
                    elif "dependency_use_id" in row:
                        append_annotation_diagnostic(
                            diagnostics,
                            f"{pointer}/dependency_use_id",
                            "forbidden_conditional_field",
                            "dependency_use_id is allowed only for internal_result",
                        )
        candidate_rows = review.get("candidate_dependency_dispositions")
        annotation_identity_diagnostics(
            candidate_rows,
            expected["review"]["candidate_dependency_dispositions"],
            "/review/candidate_dependency_dispositions",
            "candidate_id",
            ("candidate_id", "path_ids"),
            diagnostics,
            unordered_fields=("path_ids",),
        )
        if isinstance(candidate_rows, list):
            for index, row in enumerate(candidate_rows):
                pointer = f"/review/candidate_dependency_dispositions/{index}"
                if annotation_object_diagnostics(
                    row,
                    pointer,
                    diagnostics,
                    required=(
                        "candidate_id",
                        "path_ids",
                        "disposition",
                        "evidence",
                    ),
                    optional=("dependency_use_id",),
                ):
                    annotation_string_list_diagnostics(
                        row.get("path_ids"),
                        f"{pointer}/path_ids",
                        diagnostics,
                        allow_empty=False,
                        pattern=CANDIDATE_PATH_ID_RE,
                    )
                    annotation_enum_diagnostic(
                        row.get("disposition"),
                        f"{pointer}/disposition",
                        {
                            "internal_result",
                            "obligation_context",
                            "navigation",
                            "non_load_bearing",
                        },
                        diagnostics,
                    )
                    annotation_string_diagnostic(
                        row.get("evidence"), f"{pointer}/evidence", diagnostics
                    )
                    disposition = row.get("disposition")
                    if disposition == "internal_result":
                        use_id = row.get("dependency_use_id")
                        if (
                            not isinstance(use_id, str)
                            or not DEPENDENCY_USE_ID_RE.fullmatch(use_id)
                        ):
                            append_annotation_diagnostic(
                                diagnostics,
                                f"{pointer}/dependency_use_id",
                                "missing_conditional_field",
                                "internal_result requires a dependency use such as D001",
                            )
                    elif "dependency_use_id" in row:
                        append_annotation_diagnostic(
                            diagnostics,
                            f"{pointer}/dependency_use_id",
                            "forbidden_conditional_field",
                            "dependency_use_id is allowed only for internal_result",
                        )
        citation_rows = review.get("citation_dispositions")
        annotation_identity_diagnostics(
            citation_rows,
            expected["review"]["citation_dispositions"],
            "/review/citation_dispositions",
            "key",
            ("key",),
            diagnostics,
        )
        if isinstance(citation_rows, list):
            for index, row in enumerate(citation_rows):
                pointer = f"/review/citation_dispositions/{index}"
                if annotation_object_diagnostics(
                    row,
                    pointer,
                    diagnostics,
                    required=("key", "disposition", "evidence"),
                    optional=("dependency_id", "dependency_use_id"),
                ):
                    annotation_enum_diagnostic(
                        row.get("disposition"),
                        f"{pointer}/disposition",
                        {"external_result", "bibliographic_only", "unresolved"},
                        diagnostics,
                    )
                    annotation_string_diagnostic(
                        row.get("evidence"), f"{pointer}/evidence", diagnostics
                    )
                    disposition = row.get("disposition")
                    if disposition == "external_result":
                        for field in ("dependency_id", "dependency_use_id"):
                            if not is_nonempty_string(row.get(field)):
                                append_annotation_diagnostic(
                                    diagnostics,
                                    f"{pointer}/{field}",
                                    "missing_conditional_field",
                                    f"external_result requires {field}",
                                )
                    else:
                        for field in ("dependency_id", "dependency_use_id"):
                            if field in row:
                                append_annotation_diagnostic(
                                    diagnostics,
                                    f"{pointer}/{field}",
                                    "forbidden_conditional_field",
                                    f"{field} is allowed only for external_result",
                                )
        for field in (
            "explicit_assumptions",
            "inherited_assumptions",
            "verification_basis",
            "reviewer_notes",
        ):
            value = review.get(field)
            if value is not None and not isinstance(value, list):
                append_annotation_diagnostic(
                    diagnostics,
                    f"/review/{field}",
                    "wrong_type",
                    "must be a list",
                )
            else:
                annotation_string_list_diagnostics(
                    value,
                    f"/review/{field}",
                    diagnostics,
                    allow_empty=field != "verification_basis",
                )

    annotation_null_diagnostics(annotations, "", diagnostics)
    unique: dict[tuple[str, str, str, str], dict[str, str]] = {}
    for diagnostic in diagnostics:
        key = (
            diagnostic["document"],
            diagnostic["pointer"],
            diagnostic["code"],
            diagnostic["message"],
        )
        unique.setdefault(key, diagnostic)
    ordered = sorted(
        unique.values(),
        key=lambda row: (
            row["document"],
            row["pointer"],
            row["code"],
            row["message"],
        ),
    )
    if ordered or not deep_validation:
        return ordered
    try:
        candidate = compile_annotation_data(
            ledger, annotations, ledger_path, packet
        )
    except (OSError, UnicodeError, ValueError) as exc:
        return [
            {
                "document": "annotations",
                "pointer": "",
                "code": "semantic_compile_error",
                "message": str(exc),
            }
        ]
    temporary = _unique_sibling_temp_path(ledger_path)
    try:
        payload = json.dumps(candidate, ensure_ascii=False, indent=2) + "\n"
        with temporary.open("w", encoding="utf-8", newline="\n") as stream:
            stream.write(payload)
            stream.flush()
            os.fsync(stream.fileno())
        validation_errors, summary = check_ledger_data(temporary, True)
    finally:
        if temporary.exists():
            temporary.unlink()
    return [
        {
            "document": "compiled_ledger",
            "pointer": "",
            "code": "final_ledger_error",
            "message": message,
        }
        for message in validation_errors
    ] + (compiled_dependency_binding_diagnostics(candidate, summary, packet, annotations)
         if not validation_errors else [])


def cmd_annotation_check(args: argparse.Namespace) -> int:
    configure_console_errors()
    ledger_path = args.ledger.resolve()
    annotations_path = args.annotations.resolve()
    packet_path = args.packet.resolve()
    diagnostics: list[dict[str, str]] = []
    ledger: dict[str, Any] = {}
    annotations: dict[str, Any] = {}
    packet: dict[str, Any] = {}
    if not ledger_path.is_file():
        append_annotation_diagnostic(
            diagnostics,
            "",
            "missing_file",
            f"extracted skeleton not found: {ledger_path}",
            document="skeleton",
        )
    else:
        ledger, errors = load_json_object(ledger_path, "extracted ledger")
        for message in errors:
            append_annotation_diagnostic(
                diagnostics,
                "",
                "invalid_json",
                message,
                document="skeleton",
            )
    if not annotations_path.is_file():
        append_annotation_diagnostic(
            diagnostics,
            "",
            "missing_file",
            f"compact annotations not found: {annotations_path}",
        )
    else:
        annotations, errors = load_json_object(
            annotations_path, "compact annotations"
        )
        for message in errors:
            append_annotation_diagnostic(
                diagnostics, "", "invalid_json", message
            )
    if not packet_path.is_file():
        append_annotation_diagnostic(
            diagnostics,
            "",
            "missing_file",
            f"primary context packet not found: {packet_path}",
            document="packet",
        )
    audit_root = containing_audit_root(ledger_path) if ledger_path.is_file() else None
    if audit_root is not None and annotations_path.is_relative_to(audit_root):
        append_annotation_diagnostic(
            diagnostics,
            "",
            "invalid_annotation_path",
            "compact annotations must remain outside the canonical audit root",
        )
    if not diagnostics:
        try:
            validate_compile_skeleton(ledger, ledger_path)
        except (OSError, UnicodeError, ValueError) as exc:
            append_annotation_diagnostic(
                diagnostics,
                "",
                "invalid_skeleton",
                str(exc),
                document="skeleton",
            )
        try:
            packet = validate_current_primary_packet(
                ledger, ledger_path, packet_path
            )
        except (OSError, UnicodeError, ValueError) as exc:
            append_annotation_diagnostic(
                diagnostics,
                "",
                "invalid_packet",
                str(exc),
                document="packet",
            )
    if not diagnostics:
        diagnostics.extend(
            annotation_preflight_diagnostics(
                ledger, ledger_path, annotations, packet
            )
        )
    diagnostics = sorted(
        diagnostics,
        key=lambda row: (
            row["document"],
            row["pointer"],
            row["code"],
            row["message"],
        ),
    )
    counts = Counter(row["code"] for row in diagnostics)
    warnings = near_duplicate_evidence_warnings(annotations)
    result = {
        "command": "annotation-check",
        "status": "passed" if not diagnostics else "failed",
        "compile_ready": not diagnostics,
        "unit_id": ledger.get("unit_id"),
        "annotation_schema_version": annotations.get(
            "annotation_schema_version"
        ),
        "skeleton_sha256": (
            sha256_file(ledger_path) if ledger_path.is_file() else None
        ),
        "packet_sha256": (
            sha256_file(packet_path) if packet_path.is_file() else None
        ),
        "annotation_sha256": (
            sha256_file(annotations_path)
            if annotations_path.is_file()
            else None
        ),
        "error_count": len(diagnostics),
        "counts_by_code": dict(sorted(counts.items())),
        "diagnostics": diagnostics,
        "warning_count": len(warnings),
        "warnings": warnings,
    }
    if getattr(args, "json", False):
        print(json.dumps(result, ensure_ascii=True, indent=2))
    elif diagnostics:
        print(
            f"annotation-check failed with {len(diagnostics)} diagnostic(s)."
        )
        for row in diagnostics:
            rendered_pointer = row["pointer"] or "/"
            print(
                f"{row['document']}{rendered_pointer}: "
                f"{row['code']}: {row['message']}"
            )
        if diagnostics:
            print(
                "Compare field shapes against "
                "assets/templates/AUDIT_RECORD_EXAMPLES.json."
            )
        for warning in warnings:
            print(f"warning: {warning}")
    else:
        print("annotation-check passed: annotations are compile-ready.")
        for warning in warnings:
            print(f"warning: {warning}")
    return 0 if not diagnostics else 1


def build_compiled_source_units(
    ledger: dict[str, Any], source_groups: Any
) -> tuple[list[dict[str, Any]], dict[tuple[int, int], str]]:
    source = ledger.get("source")
    source_lines = ledger.get("source_lines")
    if not isinstance(source, dict) or not isinstance(source_lines, list):
        raise ValueError("The extracted skeleton has no locked source records")
    start, end = source_coverage_bounds(ledger)
    if not is_int(start) or not is_int(end) or start < 1 or end < start:
        raise ValueError("The extracted skeleton has an invalid source range")
    if len(source_lines) != end - start + 1:
        raise ValueError("The extracted skeleton source_lines are incomplete")
    if not isinstance(source_groups, list):
        raise ValueError("source_groups must be a list")

    groups: list[dict[str, Any]] = []
    previous_end = start - 1
    for index, raw_group in enumerate(source_groups, 1):
        field = f"source_groups[{index}]"
        group = annotation_object(
            raw_group,
            field,
            required=("lines", "kind", "partition_evidence"),
        )
        line_range = group["lines"]
        if (
            not isinstance(line_range, list)
            or len(line_range) != 2
            or not all(is_int(item) for item in line_range)
        ):
            raise ValueError(f"{field}.lines must be [start, end]")
        group_start, group_end = line_range
        if group_start < start or group_end > end or group_end <= group_start:
            raise ValueError(
                f"{field}.lines must be a multiline range inside {start}-{end}"
            )
        if group_start <= previous_end:
            raise ValueError("source_groups must be disjoint and in source order")
        previous_end = group_end
        if group["kind"] not in {"continued_sentence", "continued_display"}:
            raise ValueError(
                f"{field}.kind must be continued_sentence or continued_display"
            )
        if not is_substantive_string(group["partition_evidence"]):
            raise ValueError(f"{field}.partition_evidence must be substantive")
        groups.append(group)

    groups_by_start = {group["lines"][0]: group for group in groups}
    units: list[dict[str, Any]] = []
    ranges: dict[tuple[int, int], str] = {}
    line_number = start
    while line_number <= end:
        group = groups_by_start.get(line_number)
        if group is not None:
            unit_start, unit_end = group["lines"]
            kind = group["kind"]
            evidence = group["partition_evidence"]
        else:
            unit_start = unit_end = line_number
            row = source_lines[line_number - start]
            text = row.get("text") if isinstance(row, dict) else None
            if not isinstance(text, str):
                raise ValueError(
                    f"The extracted skeleton has malformed source line {line_number}"
                )
            kind = "non_substantive" if locked_line_is_non_substantive(row) else "one_line"
            evidence = (
                f"Locked line {line_number} is mechanically non-substantive."
                if kind == "non_substantive"
                else f"This source unit is exactly locked physical line {line_number}."
            )
        texts = [
            source_lines[current - start].get("text", "")
            for current in range(unit_start, unit_end + 1)
        ]
        unit_id = f"U{len(units) + 1:03d}"
        units.append(
            {
                "id": unit_id,
                "lines": [unit_start, unit_end],
                "kind": kind,
                "source_sha256": sha256_text("\n".join(texts)),
                "partition_evidence": evidence,
            }
        )
        ranges[(unit_start, unit_end)] = unit_id
        if "source_fragments" in ledger:
            units[-1]["source_span"] = source_unit_location(ledger, units[-1])
        line_number = unit_end + 1
    return units, ranges


def expand_compact_risks(
    value: Any,
    field: str,
    not_applicable_basis: Any = None,
) -> list[dict[str, str]]:
    risks = annotation_object(value, field, required=RISK_ASPECTS)
    expanded: list[dict[str, str]] = []
    shorthand_aspects: list[str] = []
    for aspect in RISK_ASPECTS:
        if risks[aspect] == "not_applicable":
            shorthand_aspects.append(aspect)
            continue
        record = annotation_object(
            risks[aspect],
            f"{field}.{aspect}",
            required=("status", "evidence"),
        )
        if record["status"] not in RISK_STATUSES:
            raise ValueError(f"{field}.{aspect}.status is invalid")
        if not is_substantive_string(record["evidence"]):
            raise ValueError(f"{field}.{aspect}.evidence must be substantive")
        expanded.append(
            {
                "aspect": aspect,
                "status": record["status"],
                "evidence": record["evidence"],
            }
        )
    if shorthand_aspects:
        if not is_substantive_string(not_applicable_basis):
            raise ValueError(
                f"{field} uses not_applicable shorthand but its step has no "
                "substantive not_applicable_basis"
            )
        by_aspect = {record["aspect"]: record for record in expanded}
        for aspect in shorthand_aspects:
            by_aspect[aspect] = {
                "aspect": aspect,
                "status": "not_applicable",
                "evidence": (
                    f"{aspect} is not applicable to this step: "
                    f"{not_applicable_basis}"
                ),
            }
        expanded = [by_aspect[aspect] for aspect in RISK_ASPECTS]
    elif not_applicable_basis is not None:
        raise ValueError(
            f"{field} has not_applicable_basis but uses no not_applicable shorthand"
        )
    return expanded


def load_compact_dependencies(value: Any) -> tuple[list[dict[str, Any]], dict[str, dict[str, Any]]]:
    if not isinstance(value, list):
        raise ValueError("dependencies must be a list")
    records: list[dict[str, Any]] = []
    by_use: dict[str, dict[str, Any]] = {}
    for index, raw_record in enumerate(value, 1):
        field = f"dependencies[{index}]"
        record = annotation_object(
            raw_record,
            field,
            required=(
                "id",
                "use_id",
                "kind",
                "status",
                "needed_form",
                "compatibility_check",
            ),
            optional=("conclusion_id", "statement_support_sha256"),
        )
        if record["kind"] not in {"internal_result", "external_result"}:
            raise ValueError(f"{field}.kind must be an internal or external result")
        use_id = record["use_id"]
        if not isinstance(use_id, str) or not DEPENDENCY_USE_ID_RE.fullmatch(use_id):
            raise ValueError(f"{field}.use_id must match D001")
        if use_id in by_use:
            raise ValueError(f"Duplicate compact dependency use {use_id}")
        if record["status"] not in DEPENDENCY_STATUSES - {"not_applicable"}:
            raise ValueError(f"{field}.status is invalid")
        for semantic_field in ("id", "needed_form", "compatibility_check"):
            if not is_substantive_string(record[semantic_field]):
                raise ValueError(f"{field}.{semantic_field} must be substantive")
        if record["kind"] == "internal_result":
            conclusion_id = record.get("conclusion_id")
            if (
                not isinstance(conclusion_id, str)
                or not CONCLUSION_ID_RE.fullmatch(conclusion_id)
            ):
                raise ValueError(
                    f"{field}.conclusion_id must identify the internal conclusion"
                )
        elif "conclusion_id" in record:
            raise ValueError(
                f"{field}.conclusion_id is not allowed for an external result"
            )
        copied = {
            key: record[key]
            for key in (
                "id",
                "use_id",
                "kind",
                "conclusion_id",
                "status",
                "needed_form",
                "compatibility_check",
                "statement_support_sha256",
            )
            if key in record
        }
        records.append(copied)
        by_use[use_id] = copied
    return records, by_use


COMPACT_STEP_FIELDS = {
    "key",
    "lines",
    "mode",
    "kind",
    "goal",
    "claim",
    "literal",
    "atomicity_evidence",
    "adversarial",
    "risks",
    "inputs",
    "side_conditions",
    "status",
    "issue_ids",
    "rule",
    "justification",
    "failure",
    "not_applicable_basis",
}
COMPACT_STEP_OPTIONAL_FIELDS = {
    "rule",
    "justification",
    "failure",
    "not_applicable_basis",
}


def compact_issue_ids(value: Any, field: str) -> list[str]:
    if not isinstance(value, list) or not all(
        isinstance(issue_id, str) and ISSUE_ID_RE.fullmatch(issue_id)
        for issue_id in value
    ):
        raise ValueError(f"{field} must contain issue IDs such as I-001")
    if len(value) != len(set(value)):
        raise ValueError(f"{field} contains duplicate issue IDs")
    return list(value)


def prepare_compact_step_plans(
    value: Any,
    source_units: list[dict[str, Any]],
    source_ranges: dict[tuple[int, int], str],
) -> tuple[list[dict[str, Any]], dict[str, str]]:
    if not isinstance(value, list):
        raise ValueError("steps must be a list")
    units_by_id = {unit["id"]: unit for unit in source_units}
    unit_order = {unit["id"]: index for index, unit in enumerate(source_units, 1)}
    plans: list[dict[str, Any]] = []
    seen_keys: set[str] = set()
    for index, raw_step in enumerate(value, 1):
        field = f"steps[{index}]"
        step = annotation_object(
            raw_step,
            field,
            required=COMPACT_STEP_FIELDS - COMPACT_STEP_OPTIONAL_FIELDS,
            optional=COMPACT_STEP_OPTIONAL_FIELDS,
        )
        key = step["key"]
        if not is_nonempty_string(key):
            raise ValueError(f"{field}.key must be nonempty")
        if key in seen_keys:
            raise ValueError(f"Duplicate compact step key {key}")
        seen_keys.add(key)
        line_range = step["lines"]
        if (
            not isinstance(line_range, list)
            or len(line_range) != 2
            or not all(is_int(item) for item in line_range)
        ):
            raise ValueError(f"{field}.lines must be [start, end]")
        source_unit_id = source_ranges.get((line_range[0], line_range[1]))
        if source_unit_id is None:
            raise ValueError(
                f"{field}.lines must exactly match one compiled source unit"
            )
        if units_by_id[source_unit_id]["kind"] == "non_substantive":
            raise ValueError(f"{field} cannot annotate a non-substantive source unit")
        if step["mode"] not in {"noninferential", "derivation", "reuse"}:
            raise ValueError(f"{field}.mode is invalid")
        if step["kind"] not in STEP_KINDS:
            raise ValueError(f"{field}.kind is invalid")
        if step["status"] not in STEP_STATUSES - {"non_substantive"}:
            raise ValueError(f"{field}.status is invalid")
        for semantic_field in (
            "goal",
            "claim",
            "literal",
            "atomicity_evidence",
        ):
            if not is_substantive_string(step[semantic_field]):
                raise ValueError(f"{field}.{semantic_field} must be substantive")
        annotation_string_list(
            step["adversarial"], f"{field}.adversarial", allow_empty=False
        )
        expand_compact_risks(
            step["risks"],
            f"{field}.risks",
            step.get("not_applicable_basis"),
        )
        if not isinstance(step["inputs"], list):
            raise ValueError(f"{field}.inputs must be a list")
        if not isinstance(step["side_conditions"], list):
            raise ValueError(f"{field}.side_conditions must be a list")
        compact_issue_ids(step["issue_ids"], f"{field}.issue_ids")
        if step["mode"] == "noninferential":
            if step["kind"] not in {"statement", "setup", "definition"}:
                raise ValueError(
                    f"{field}: noninferential mode requires statement, setup, or definition"
                )
            if step["inputs"] or step["side_conditions"]:
                raise ValueError(
                    f"{field}: noninferential mode cannot have inputs or side conditions"
                )
            if any(name in step for name in ("rule", "justification", "failure")):
                raise ValueError(
                    f"{field}: noninferential mode cannot have a move or failure"
                )
        else:
            for semantic_field in ("rule", "justification"):
                if not is_substantive_string(step.get(semantic_field)):
                    raise ValueError(
                        f"{field}.{semantic_field} must be authored for every move"
                    )
        plans.append(
            {
                **step,
                "source_unit_id": source_unit_id,
                "annotation_position": index,
            }
        )

    plans.sort(
        key=lambda plan: (
            unit_order[plan["source_unit_id"]],
            plan["annotation_position"],
        )
    )
    plans_by_unit: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for plan in plans:
        plans_by_unit[plan["source_unit_id"]].append(plan)
    missing_units = [
        unit["id"]
        for unit in source_units
        if unit["kind"] != "non_substantive" and not plans_by_unit.get(unit["id"])
    ]
    if missing_units:
        raise ValueError(
            "Compact annotations omit substantive source units: "
            + ", ".join(missing_units[:8])
        )

    key_to_step_id: dict[str, str] = {}
    for unit in source_units:
        unit_plans = plans_by_unit.get(unit["id"], [])
        base_id = "S" + unit["id"][1:]
        for offset, plan in enumerate(unit_plans):
            step_id = base_id if offset == 0 else f"{base_id}.{offset}"
            plan["compiled_id"] = step_id
            key_to_step_id[plan["key"]] = step_id
    return plans, key_to_step_id


def compact_move_failure(value: Any, field: str) -> dict[str, Any]:
    failure = annotation_object(
        value,
        field,
        required=("kind", "issue_id", "evidence"),
        optional=("target", "computation"),
    )
    if failure["kind"] not in MOVE_FAILURE_KINDS:
        raise ValueError(f"{field}.kind is invalid")
    if (
        not isinstance(failure["issue_id"], str)
        or not ISSUE_ID_RE.fullmatch(failure["issue_id"])
    ):
        raise ValueError(f"{field}.issue_id must match I-001")
    if not is_substantive_string(failure["evidence"]):
        raise ValueError(f"{field}.evidence must be substantive")
    if "target" in failure and not is_substantive_string(failure["target"]):
        raise ValueError(f"{field}.target must be substantive")
    if "computation" in failure:
        shape_errors = failure_computation_shape_errors(
            failure["computation"], f"{field}.computation"
        )
        if shape_errors:
            raise ValueError(shape_errors[0])
    return dict(failure)


def build_compact_side_conditions(
    value: list[Any],
    field: str,
    premise_ids: list[str],
) -> list[dict[str, Any]]:
    conditions: list[dict[str, Any]] = []
    for index, raw_condition in enumerate(value, 1):
        item_field = f"{field}[{index}]"
        condition = annotation_object(
            raw_condition,
            item_field,
            required=("condition", "status"),
            optional=("discharge",),
        )
        if not is_substantive_string(condition["condition"]):
            raise ValueError(f"{item_field}.condition must be substantive")
        if condition["status"] not in {"open", "discharged"}:
            raise ValueError(f"{item_field}.status is invalid")
        output: dict[str, Any] = {
            "id": f"SC{index:03d}",
            "condition": condition["condition"],
            "generated_by": "M001",
            "status": condition["status"],
        }
        if condition["status"] == "open":
            if "discharge" in condition:
                raise ValueError(f"{item_field}: an open condition cannot have discharge")
        else:
            discharge = annotation_object(
                condition.get("discharge"),
                f"{item_field}.discharge",
                required=("sources", "rule", "evidence"),
            )
            if not isinstance(discharge["sources"], list) or not discharge["sources"]:
                raise ValueError(
                    f"{item_field}.discharge.sources must be a nonempty list"
                )
            sources: list[dict[str, Any]] = []
            for source_index, raw_source in enumerate(discharge["sources"], 1):
                source_field = f"{item_field}.discharge.sources[{source_index}]"
                source = annotation_object(
                    raw_source,
                    source_field,
                    required=("input", "contribution"),
                )
                input_index = source["input"]
                if (
                    not is_int(input_index)
                    or input_index < 1
                    or input_index > len(premise_ids)
                ):
                    raise ValueError(
                        f"{source_field}.input must identify one compact input"
                    )
                if not is_substantive_string(source["contribution"]):
                    raise ValueError(
                        f"{source_field}.contribution must be substantive"
                    )
                sources.append(
                    {
                        "kind": "premise",
                        "reference": premise_ids[input_index - 1],
                        "contribution": source["contribution"],
                    }
                )
            if not is_substantive_string(discharge["rule"]):
                raise ValueError(f"{item_field}.discharge.rule must be substantive")
            if not is_substantive_string(discharge["evidence"]):
                raise ValueError(
                    f"{item_field}.discharge.evidence must be substantive"
                )
            output["discharge"] = {
                "sources": sources,
                "rule": discharge["rule"],
                "evidence": discharge["evidence"],
            }
        conditions.append(output)
    return conditions


def build_compact_steps(
    ledger: dict[str, Any],
    source_units: list[dict[str, Any]],
    plans: list[dict[str, Any]],
    key_to_step_id: dict[str, str],
    dependencies_by_use: dict[str, dict[str, Any]],
) -> tuple[list[dict[str, Any]], dict[str, dict[str, Any]]]:
    obligation = ledger.get("obligation")
    if not isinstance(obligation, dict):
        raise ValueError("The extracted skeleton has no normalized obligation")
    plans_by_unit: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for plan in plans:
        plans_by_unit[plan["source_unit_id"]].append(plan)

    steps: list[dict[str, Any]] = []
    built_by_key: dict[str, dict[str, Any]] = {}
    for unit in source_units:
        unit_id = unit["id"]
        base_step_id = "S" + unit_id[1:]
        if unit["kind"] == "non_substantive":
            steps.append(
                {
                    "id": base_step_id,
                    "source_unit_id": unit_id,
                    "kind": "other",
                    "status": "non_substantive",
                    "issue_ids": [],
                }
            )
            continue

        for plan in plans_by_unit[unit_id]:
            field = f"step {plan['key']}"
            premise_uses: list[dict[str, Any]] = []
            step_dependencies: list[dict[str, Any]] = []
            seen_dependency_keys: set[str] = set()
            for input_index, raw_input in enumerate(plan["inputs"], 1):
                input_field = f"{field}.inputs[{input_index}]"
                compact_input = annotation_object(
                    raw_input,
                    input_field,
                    required=("kind", "reference", "role", "evidence"),
                    optional=(
                        "anchor",
                        "compatibility_check",
                        "source_reference_id",
                        "source_reference_occurrence_id",
                    ),
                )
                input_kind = compact_input["kind"]
                reference = compact_input["reference"]
                if input_kind not in {"obligation", "prior_step", "dependency"}:
                    raise ValueError(f"{input_field}.kind is invalid")
                if not is_nonempty_string(reference):
                    raise ValueError(f"{input_field}.reference must be nonempty")
                if compact_input["role"] not in PREMISE_ROLES:
                    raise ValueError(f"{input_field}.role is invalid")
                if not is_substantive_string(compact_input["evidence"]):
                    raise ValueError(f"{input_field}.evidence must be substantive")
                source_reference_id = compact_input.get("source_reference_id")
                source_occurrence_id = compact_input.get(
                    "source_reference_occurrence_id"
                )
                if bool(is_nonempty_string(source_reference_id)) != bool(
                    is_nonempty_string(source_occurrence_id)
                ):
                    raise ValueError(
                        f"{input_field} source reference anchoring requires both IDs"
                    )

                if input_kind == "obligation":
                    if "compatibility_check" in compact_input:
                        raise ValueError(
                            f"{input_field}.compatibility_check is not allowed for an obligation"
                        )
                    anchor = annotation_object(
                        compact_input.get("anchor"),
                        f"{input_field}.anchor",
                        required=("kind", "index"),
                    )
                    found, claim = resolve_json_pointer(obligation, reference)
                    root_name = (
                        reference[1:].split("/", 1)[0]
                        if reference.startswith("/")
                        else ""
                    )
                    if (
                        root_name not in OBLIGATION_PREMISE_ROOTS
                        or not found
                        or not isinstance(claim, str)
                        or not is_substantive_string(claim)
                    ):
                        raise ValueError(
                            f"{input_field}.reference must resolve to one substantive scalar premise"
                        )
                    origin = {
                        "kind": "obligation",
                        "reference": reference,
                        "anchor": dict(anchor),
                    }
                elif input_kind == "prior_step":
                    if "anchor" in compact_input:
                        raise ValueError(
                            f"{input_field}.anchor is not allowed for a prior step"
                        )
                    if not is_substantive_string(
                        compact_input.get("compatibility_check")
                    ):
                        raise ValueError(
                            f"{input_field}.compatibility_check must be authored"
                        )
                    prior = built_by_key.get(reference)
                    if prior is None:
                        if reference in key_to_step_id:
                            raise ValueError(
                                f"{input_field} references a step not established earlier"
                            )
                        raise ValueError(f"{input_field} references unknown step {reference}")
                    if not is_nonempty_string(
                        prior.get("inference", {}).get("conclusion_move")
                    ):
                        raise ValueError(
                            f"{input_field} cannot use noninferential step {reference} "
                            "as a factual premise; link the normalized premise or "
                            "record an introduction inference in that step"
                        )
                    claim = prior["restatement"]
                    prior_id = prior["id"]
                    dependency = {
                        "id": prior_id,
                        "kind": "step",
                        "status": STEP_TO_DEPENDENCY_STATUS[prior["status"]],
                        "needed_form": claim,
                        "compatibility_check": compact_input[
                            "compatibility_check"
                        ],
                    }
                    if prior_id not in seen_dependency_keys:
                        step_dependencies.append(dependency)
                        seen_dependency_keys.add(prior_id)
                    origin = {"kind": "prior_step", "reference": prior_id}
                else:
                    if "anchor" in compact_input or "compatibility_check" in compact_input:
                        raise ValueError(
                            f"{input_field} duplicates fields owned by the dependency catalog"
                        )
                    dependency = dependencies_by_use.get(reference)
                    if dependency is None:
                        raise ValueError(
                            f"{input_field} references unknown dependency use {reference}"
                        )
                    claim = dependency["needed_form"]
                    if reference not in seen_dependency_keys:
                        step_dependencies.append(dict(dependency))
                        seen_dependency_keys.add(reference)
                    origin = {
                        "kind": dependency["kind"],
                        "reference": reference,
                    }

                premise: dict[str, Any] = {
                    "id": f"P{input_index:03d}",
                    "role": compact_input["role"],
                    "claim": claim,
                    "origin": origin,
                    "evidence": compact_input["evidence"],
                }
                if is_nonempty_string(source_reference_id):
                    premise["source_reference_id"] = source_reference_id
                    premise["source_reference_occurrence_id"] = source_occurrence_id
                premise_uses.append(premise)

            risks = expand_compact_risks(
                plan["risks"],
                f"{field}.risks",
                plan.get("not_applicable_basis"),
            )
            issue_ids = compact_issue_ids(plan["issue_ids"], f"{field}.issue_ids")
            common: dict[str, Any] = {
                "id": plan["compiled_id"],
                "source_unit_id": unit_id,
                "kind": plan["kind"],
                "goal": plan["goal"],
                "restatement": plan["claim"],
                "premise_uses": premise_uses,
                "dependencies": step_dependencies,
                "checks": {
                    "literal": plan["literal"],
                    "atomicity": {
                        "status": (
                            "non_inferential"
                            if plan["mode"] == "noninferential"
                            else "single_move"
                        ),
                        "evidence": plan["atomicity_evidence"],
                    },
                    "adversarial": list(plan["adversarial"]),
                },
                "side_conditions": [],
                "risk_checks": risks,
                "conditions": [],
                "status": plan["status"],
                "issue_ids": issue_ids,
            }
            if plan["mode"] == "noninferential":
                common["inference"] = {"moves": [], "conclusion_move": None}
            else:
                common["support_role"] = plan["mode"]
                move: dict[str, Any] = {
                    "id": "M001",
                    "claim": plan["claim"],
                    "rule": plan["rule"],
                    "premise_ids": [premise["id"] for premise in premise_uses],
                    "prior_move_ids": [],
                    "justification": plan["justification"],
                }
                if "failure" in plan:
                    move["failure"] = compact_move_failure(
                        plan["failure"], f"{field}.failure"
                    )
                common["inference"] = {
                    "moves": [move],
                    "conclusion_move": "M001",
                }
                side_conditions = build_compact_side_conditions(
                    plan["side_conditions"],
                    f"{field}.side_conditions",
                    [premise["id"] for premise in premise_uses],
                )
                common["side_conditions"] = side_conditions
                if plan["status"] == "conditionally_verified":
                    derived_conditions: list[dict[str, str]] = [
                        {
                            "kind": "side_condition",
                            "reference": condition["id"],
                            "condition": condition["condition"],
                        }
                        for condition in side_conditions
                        if condition["status"] == "open"
                    ]
                    for dependency in step_dependencies:
                        if dependency["status"] in {"conditional", "unchecked"}:
                            dependency_reference = (
                                dependency["id"]
                                if dependency["kind"] == "step"
                                else dependency["use_id"]
                            )
                            derived_conditions.append(
                                {
                                    "kind": "dependency",
                                    "reference": dependency_reference,
                                    "condition": (
                                        f"Dependency {dependency_reference} remains "
                                        f"{dependency['status']} for the needed form: "
                                        f"{dependency['needed_form']}"
                                    ),
                                }
                            )
                    derived_conditions.extend(
                        {
                            "kind": "risk_check",
                            "reference": risk["aspect"],
                            "condition": risk["evidence"],
                        }
                        for risk in risks
                        if risk["status"] == "open"
                    )
                    common["conditions"] = derived_conditions
            steps.append(common)
            built_by_key[plan["key"]] = common
    return steps, built_by_key


def build_compact_reference_dispositions(
    value: Any, steps: list[dict[str, Any]]
) -> list[dict[str, Any]]:
    if not isinstance(value, list):
        raise ValueError("review.source_reference_dispositions must be a list")
    premises = [
        (step["id"], premise)
        for step in steps
        if isinstance(step, dict)
        for premise in step.get("premise_uses", [])
        if isinstance(premise, dict)
    ]
    output: list[dict[str, Any]] = []
    seen: set[str] = set()
    for index, raw_record in enumerate(value, 1):
        field = f"review.source_reference_dispositions[{index}]"
        record = annotation_object(
            raw_record,
            field,
            required=("occurrence_id", "target", "command", "disposition", "evidence"),
            optional=("dependency_use_id",),
        )
        occurrence_id = record["occurrence_id"]
        if not is_nonempty_string(occurrence_id) or not occurrence_id.startswith("R-"):
            raise ValueError(f"{field}.occurrence_id must be a parser occurrence ID")
        if occurrence_id in seen:
            raise ValueError(f"Duplicate source reference occurrence {occurrence_id}")
        seen.add(occurrence_id)
        for name in ("target", "command", "evidence"):
            if not is_substantive_string(record[name]):
                raise ValueError(f"{field}.{name} must be substantive")
        disposition = record["disposition"]
        allowed = {
            "internal_result",
            "obligation_context",
            "local_step",
            "own_result_identification",
            "navigation",
            "non_load_bearing",
            "unresolved",
        }
        if disposition not in allowed:
            raise ValueError(f"{field}.disposition is invalid")
        copied = {
            "occurrence_id": occurrence_id,
            "target": record["target"],
            "command": record["command"],
            "disposition": disposition,
            "evidence": record["evidence"],
        }
        premise_roles = {"internal_result", "obligation_context", "local_step"}
        if disposition in premise_roles:
            links = [
                {"step_id": step_id, "premise_id": premise["id"]}
                for step_id, premise in premises
                if premise.get("source_reference_occurrence_id") == occurrence_id
                and premise.get("source_reference_id") == record["target"]
            ]
            if not links:
                raise ValueError(
                    f"{field} has no compact premise carrying its exact occurrence"
                )
            copied["premise_links"] = links
            if disposition == "internal_result":
                use_id = record.get("dependency_use_id")
                if not is_nonempty_string(use_id):
                    raise ValueError(f"{field}.dependency_use_id is required")
                copied["dependency_use_id"] = use_id
            elif "dependency_use_id" in record:
                raise ValueError(
                    f"{field}.dependency_use_id is allowed only for internal_result"
                )
        elif "dependency_use_id" in record:
            raise ValueError(
                f"{field}.dependency_use_id is allowed only for internal_result"
            )
        output.append(copied)
    return output


def build_compact_candidate_dispositions(
    value: Any,
) -> list[dict[str, Any]]:
    if not isinstance(value, list):
        raise ValueError(
            "review.candidate_dependency_dispositions must be a list"
        )
    output: list[dict[str, Any]] = []
    seen: set[str] = set()
    nondependency_roles = {
        "navigation",
        "non_load_bearing",
        "obligation_context",
    }
    for index, raw_record in enumerate(value, 1):
        field = f"review.candidate_dependency_dispositions[{index}]"
        record = annotation_object(
            raw_record,
            field,
            required=(
                "candidate_id",
                "path_ids",
                "disposition",
                "evidence",
            ),
            optional=("dependency_use_id",),
        )
        candidate_id = record["candidate_id"]
        if not is_substantive_string(candidate_id):
            raise ValueError(f"{field}.candidate_id must be substantive")
        if candidate_id in seen:
            raise ValueError(
                f"Duplicate candidate dependency disposition {candidate_id}"
            )
        seen.add(str(candidate_id))
        path_ids = annotation_string_list(
            record["path_ids"], f"{field}.path_ids", allow_empty=False
        )
        if len(path_ids) != len(set(path_ids)) or not all(
            CANDIDATE_PATH_ID_RE.fullmatch(path_id) for path_id in path_ids
        ):
            raise ValueError(
                f"{field}.path_ids must contain unique IDs such as CP001"
            )
        disposition = record["disposition"]
        if disposition not in {"internal_result", *nondependency_roles}:
            raise ValueError(f"{field}.disposition is invalid")
        if not is_substantive_string(record["evidence"]):
            raise ValueError(f"{field}.evidence must be substantive")
        copied = {
            "candidate_id": str(candidate_id),
            "path_ids": path_ids,
            "disposition": disposition,
            "evidence": record["evidence"],
        }
        if disposition == "internal_result":
            use_id = record.get("dependency_use_id")
            if not isinstance(use_id, str) or not DEPENDENCY_USE_ID_RE.fullmatch(
                use_id
            ):
                raise ValueError(
                    f"{field}.dependency_use_id must match D001"
                )
            copied["dependency_use_id"] = use_id
        elif "dependency_use_id" in record:
            raise ValueError(
                f"{field}.dependency_use_id is allowed only for internal_result"
            )
        output.append(copied)
    return output


def build_compact_citation_dispositions(value: Any) -> list[dict[str, Any]]:
    if not isinstance(value, list):
        raise ValueError("review.citation_dispositions must be a list")
    output: list[dict[str, Any]] = []
    seen: set[str] = set()
    for index, raw_record in enumerate(value, 1):
        field = f"review.citation_dispositions[{index}]"
        record = annotation_object(
            raw_record,
            field,
            required=("key", "disposition", "evidence"),
            optional=("dependency_id", "dependency_use_id"),
        )
        key = record["key"]
        if not is_nonempty_string(key):
            raise ValueError(f"{field}.key must be nonempty")
        if key in seen:
            raise ValueError(f"Duplicate citation disposition {key}")
        seen.add(key)
        if record["disposition"] not in {
            "external_result",
            "bibliographic_only",
            "unresolved",
        }:
            raise ValueError(f"{field}.disposition is invalid")
        if not is_substantive_string(record["evidence"]):
            raise ValueError(f"{field}.evidence must be substantive")
        if record["disposition"] == "external_result":
            for name in ("dependency_id", "dependency_use_id"):
                if not is_nonempty_string(record.get(name)):
                    raise ValueError(f"{field}.{name} is required")
        elif "dependency_id" in record or "dependency_use_id" in record:
            raise ValueError(
                f"{field} dependency fields are allowed only for external_result"
            )
        output.append(dict(record))
    return output


def build_compact_review(
    ledger: dict[str, Any],
    value: Any,
    compact_conclusions: Any,
    steps: list[dict[str, Any]],
    built_by_key: dict[str, dict[str, Any]],
    direct_dependencies: list[dict[str, Any]],
    expected_use_sites: list[str],
) -> dict[str, Any]:
    review_input = annotation_object(
        value,
        "review",
        required=(
            "explicit_assumptions",
            "inherited_assumptions",
            "source_reference_dispositions",
            "candidate_dependency_dispositions",
            "citation_dispositions",
            "verification_basis",
            "reviewer_notes",
        ),
    )
    for field in (
        "explicit_assumptions",
        "inherited_assumptions",
        "reviewer_notes",
    ):
        annotation_string_list(review_input[field], f"review.{field}")
    annotation_string_list(
        review_input["verification_basis"],
        "review.verification_basis",
        allow_empty=False,
    )
    source_dispositions = build_compact_reference_dispositions(
        review_input["source_reference_dispositions"], steps
    )
    candidate_dispositions = build_compact_candidate_dispositions(
        review_input["candidate_dependency_dispositions"]
    )
    citation_dispositions = build_compact_citation_dispositions(
        review_input["citation_dispositions"]
    )

    if not isinstance(compact_conclusions, list):
        raise ValueError("conclusions must be a list")
    obligation = ledger.get("obligation")
    obligation_conclusions = (
        obligation.get("conclusions", []) if isinstance(obligation, dict) else []
    )
    ordered_ids = [
        record.get("id")
        for record in obligation_conclusions
        if isinstance(record, dict) and is_nonempty_string(record.get("id"))
    ]
    compact_by_id: dict[str, dict[str, Any]] = {}
    for index, raw_record in enumerate(compact_conclusions, 1):
        field = f"conclusions[{index}]"
        record = annotation_object(
            raw_record,
            field,
            required=(
                "conclusion_id",
                "support_step",
                "contract_fidelity",
                "statement_status",
                "issue_ids",
            ),
            optional=("statement_support",),
        )
        conclusion_id = record["conclusion_id"]
        if conclusion_id in compact_by_id:
            raise ValueError(f"Duplicate compact conclusion {conclusion_id}")
        if conclusion_id not in ordered_ids:
            raise ValueError(f"{field}.conclusion_id is unknown")
        if record["contract_fidelity"] not in UNIT_STATUSES:
            raise ValueError(f"{field}.contract_fidelity is invalid")
        if record["statement_status"] not in STATEMENT_STATUSES:
            raise ValueError(f"{field}.statement_status is invalid")
        compact_issue_ids(record["issue_ids"], f"{field}.issue_ids")
        if record["support_step"] not in built_by_key:
            raise ValueError(f"{field}.support_step is unknown")
        compact_by_id[conclusion_id] = record
    if set(compact_by_id) != set(ordered_ids):
        missing = sorted(set(ordered_ids) - set(compact_by_id))
        raise ValueError(
            "Compact conclusions must cover every normalized conclusion"
            + (": " + ", ".join(missing) if missing else "")
        )

    ledger_for_closure = {**ledger, "steps": steps}
    steps_by_id = {step["id"]: step for step in steps}
    direct_by_use = {record["use_id"]: record for record in direct_dependencies}
    conclusion_results: list[dict[str, Any]] = []
    argument_map = {
        "verified": "valid",
        "conditionally_verified": "conditional",
        "gap": "gap",
        "incorrect": "invalid",
        "unclear": "unclear",
        "not_checked": "not_checked",
    }
    closure_map = {
        "verified": "verified",
        "conditional": "conditionally_verified",
        "gap": "gap",
        "incorrect": "incorrect",
        "unclear": "unclear",
        "unchecked": "not_checked",
    }
    for conclusion_id in ordered_ids:
        compact = compact_by_id[conclusion_id]
        support_step = built_by_key[compact["support_step"]]
        support_step_id = support_step["id"]
        inference = support_step.get("inference")
        support_move_id = (
            inference.get("conclusion_move") if isinstance(inference, dict) else None
        )
        if not is_nonempty_string(support_move_id):
            raise ValueError(
                f"Conclusion {conclusion_id} support_step must be inferential"
            )
        closure = ledger_support_contract_closure(
            ledger_for_closure, support_step_id, support_move_id
        )
        dependency_use_ids = sorted(closure["dependency_uses"])
        dependency_state = combine_dependency_statuses(
            direct_by_use[use_id]["status"]
            for use_id in dependency_use_ids
            if use_id in direct_by_use
        )
        closure_issues = {
            issue_id
            for step_id, _ in closure["move_keys"]
            for issue_id in steps_by_id.get(step_id, {}).get("issue_ids", [])
            if is_nonempty_string(issue_id)
        }
        issue_ids = list(compact["issue_ids"])
        issue_ids.extend(sorted(closure_issues - set(issue_ids)))
        conclusion_results.append(
            {
                "conclusion_id": conclusion_id,
                "support": {
                    "step_id": support_step_id,
                    "move_id": support_move_id,
                },
                "contract_fidelity": compact["contract_fidelity"],
                "argument_status": argument_map[support_step["status"]],
                "statement_status": compact["statement_status"],
                "dependency_closure": closure_map[dependency_state],
                "dependency_use_ids": dependency_use_ids,
                "issue_ids": issue_ids,
            }
        )
        if "statement_support" in compact:
            supplied = annotation_object(
                compact["statement_support"], f"Conclusion {conclusion_id}.statement_support",
                required=("support_step", "extra_conditions", "evidence"),
            )
            supplied_step = built_by_key.get(supplied["support_step"])
            if not isinstance(supplied_step, dict):
                raise ValueError(f"Conclusion {conclusion_id}.statement_support.support_step is unknown")
            conclusion_results[-1]["statement_support"] = {
                "schema_version": 1,
                "support": {"step_id": supplied_step["id"], "move_id": (supplied_step.get("inference") or {}).get("conclusion_move")},
                "target_contract_sha256": canonical_sha256(conclusion_contract_payload(ledger["obligation"], conclusion_id)),
                "extra_conditions": supplied["extra_conditions"], "evidence": supplied["evidence"],
            }

    step_statuses = [
        step["status"] for step in steps if step["status"] != "non_substantive"
    ]
    unit_status = expected_unit_status(step_statuses)
    statement_rank = {
        "established": 0,
        "conditional": 1,
        "not_assessed": 2,
        "unclear": 3,
        "not_established": 4,
        "refuted": 5,
    }
    unit_statement_status = max(
        (record["statement_status"] for record in conclusion_results),
        key=lambda status: statement_rank[status],
    )
    unit_contract = expected_unit_status(
        [record["contract_fidelity"] for record in conclusion_results]
    )
    unit_closure = expected_unit_status(
        [record["dependency_closure"] for record in conclusion_results]
    )
    return {
        "unit_status": unit_status,
        "conclusion_step_id": (
            conclusion_results[0]["support"]["step_id"]
            if len(conclusion_results) == 1
            else ""
        ),
        "conclusion_results": conclusion_results,
        "contract_fidelity": unit_contract,
        "argument_status": argument_map[unit_status],
        "statement_status": unit_statement_status,
        "dependency_closure": unit_closure,
        "explicit_assumptions": list(review_input["explicit_assumptions"]),
        "inherited_assumptions": list(review_input["inherited_assumptions"]),
        "direct_dependencies": [dict(record) for record in direct_dependencies],
        "source_reference_dispositions": source_dispositions,
        "candidate_dependency_dispositions": candidate_dispositions,
        "citation_dispositions": citation_dispositions,
        "use_sites": list(expected_use_sites),
        "verification_basis": list(review_input["verification_basis"]),
        "reviewer_notes": list(review_input["reviewer_notes"]),
    }


def validate_compiled_candidate_reconciliation(
    packet: dict[str, Any], candidate: dict[str, Any]
) -> None:
    """Match every parser candidate and provenance path to one authored disposition."""
    reconciliation = packet.get("candidate_dependency_reconciliation")
    if not isinstance(reconciliation, dict):
        raise ValueError(
            "Primary packet candidate_dependency_reconciliation is malformed"
        )
    candidate_ids = reconciliation.get(
        "candidate_internal_dependency_ids"
    )
    mapped_ids = reconciliation.get("registry_mapped_dependency_ids")
    if not isinstance(candidate_ids, list) or not all(
        is_nonempty_string(value) for value in candidate_ids
    ):
        raise ValueError(
            "Primary packet candidate IDs must be a string list"
        )
    if not isinstance(mapped_ids, list) or not all(
        is_nonempty_string(value) for value in mapped_ids
    ):
        raise ValueError(
            "Primary packet registry-mapped candidate IDs must be a string list"
        )
    inventory = packet.get("inventory")
    candidate_paths = (
        inventory.get("candidate_dependency_paths", [])
        if isinstance(inventory, dict)
        else []
    )
    path_ids_by_candidate: dict[str, list[str]] = defaultdict(list)
    if isinstance(candidate_paths, list):
        for path in candidate_paths:
            candidate_id = (
                path.get("candidate_id")
                if isinstance(path, dict)
                else None
            )
            path_id = (
                path.get("path_id") if isinstance(path, dict) else None
            )
            if (
                is_nonempty_string(candidate_id)
                and is_nonempty_string(path_id)
            ):
                path_ids_by_candidate[str(candidate_id)].append(
                    str(path_id)
                )
    review = candidate.get("review")
    dispositions = (
        review.get("candidate_dependency_dispositions", [])
        if isinstance(review, dict)
        else []
    )
    dispositions_by_id = {
        str(row.get("candidate_id")): row
        for row in dispositions
        if isinstance(row, dict)
        and is_nonempty_string(row.get("candidate_id"))
    }
    if set(dispositions_by_id) != set(candidate_ids):
        missing = sorted(set(candidate_ids) - set(dispositions_by_id))
        stale = sorted(set(dispositions_by_id) - set(candidate_ids))
        details = []
        if missing:
            details.append("missing " + ", ".join(missing))
        if stale:
            details.append("stale " + ", ".join(stale))
        raise ValueError(
            "Candidate dependency dispositions must cover exactly the primary "
            "packet candidates: " + "; ".join(details)
        )
    expected_dependencies = compact_dependencies_from_packet(
        packet.get("dependencies")
    )
    internal_by_use = {
        str(row.get("use_id")): row
        for row in expected_dependencies
        if row.get("kind") == "internal_result"
    }
    nondependency_roles = {
        "navigation",
        "non_load_bearing",
        "obligation_context",
    }
    errors: list[str] = []
    mapped_set = set(mapped_ids)
    for candidate_id in candidate_ids:
        disposition = dispositions_by_id[str(candidate_id)]
        expected_paths = sorted(
            path_ids_by_candidate.get(str(candidate_id), [])
        )
        if not expected_paths:
            errors.append(f"{candidate_id}: packet has no provenance path")
            continue
        if sorted(disposition.get("path_ids", [])) != expected_paths:
            errors.append(
                f"{candidate_id}: path_ids do not match the packet"
            )
        role = disposition.get("disposition")
        if candidate_id in mapped_set:
            use_id = disposition.get("dependency_use_id")
            dependency = internal_by_use.get(str(use_id))
            if (
                role != "internal_result"
                or dependency is None
                or dependency.get("id") != candidate_id
            ):
                errors.append(
                    f"{candidate_id}: registry-backed candidate must map to "
                    "its exact internal dependency use"
                )
        elif role not in nondependency_roles:
            errors.append(
                f"{candidate_id}: candidate without a registry contract "
                "requires an explicit nondependency disposition"
            )
    if errors:
        raise ValueError(
            "Compact annotations did not reconcile packet dependency "
            "candidates: " + "; ".join(errors)
        )


def validate_compiled_packet_dispositions(
    packet: dict[str, Any], candidate: dict[str, Any]
) -> None:
    """Apply audit-wide source-reference and citation closure before writing."""
    inventory = packet.get("inventory")
    if not isinstance(inventory, dict):
        raise ValueError("Primary packet inventory is malformed")
    review = candidate.get("review")
    if not isinstance(review, dict):
        raise ValueError("Compiled candidate review is malformed")
    expected_dependencies = compact_dependencies_from_packet(
        packet.get("dependencies")
    )
    dependencies_by_use = {
        str(row.get("use_id")): row for row in expected_dependencies
    }

    occurrences = inventory.get("reference_occurrences")
    if not isinstance(occurrences, list) or not all(
        isinstance(row, dict)
        and is_nonempty_string(row.get("occurrence_id"))
        for row in occurrences
    ):
        raise ValueError(
            "Primary packet reference_occurrences are malformed"
        )
    expected_occurrences = {
        str(row["occurrence_id"]): row for row in occurrences
    }
    dispositions = review.get("source_reference_dispositions")
    disposition_rows = dispositions if isinstance(dispositions, list) else []
    actual_dispositions = {
        str(row.get("occurrence_id")): row
        for row in disposition_rows
        if isinstance(row, dict)
        and is_nonempty_string(row.get("occurrence_id"))
    }
    if set(actual_dispositions) != set(expected_occurrences):
        missing = sorted(set(expected_occurrences) - set(actual_dispositions))
        stale = sorted(set(actual_dispositions) - set(expected_occurrences))
        details = []
        if missing:
            details.append("missing " + ", ".join(missing))
        if stale:
            details.append("stale " + ", ".join(stale))
        raise ValueError(
            "Source-reference dispositions must cover exactly the packet "
            "statement-or-proof occurrences: " + "; ".join(details)
        )

    proof = packet.get("source")
    proof = proof.get("proof") if isinstance(proof, dict) else None
    proof_start = proof.get("start_line") if isinstance(proof, dict) else 0
    proof_last = proof_start if is_int(proof_start) else 0
    proof_lines = proof.get("lines") if isinstance(proof, dict) else []
    if isinstance(proof_lines, list):
        for row in proof_lines:
            if not isinstance(row, dict) or not is_int(row.get("line")):
                continue
            clean = strip_latex_comment(str(row.get("text", ""))).strip()
            if clean and not re.fullmatch(r"\\end\s*\{proof\}", clean):
                proof_last = int(row["line"])
    if isinstance(proof, dict) and is_int(proof.get("last_substantive_position")):
        proof_last = proof["last_substantive_position"]

    candidate_paths = inventory.get("candidate_dependency_paths", [])
    candidate_paths = (
        candidate_paths if isinstance(candidate_paths, list) else []
    )
    foreign_nonproof_occurrences = {
        str(occurrence.get("occurrence_id"))
        for path in candidate_paths
        if isinstance(path, dict)
        for occurrence in path.get("reference_chain", [])
        if isinstance(occurrence, dict)
        and occurrence.get("owner_proof_required") is False
        and occurrence.get("owner_environment")
        in OBLIGATION_CONTEXT_ENVIRONMENTS
        and occurrence.get("owner_region") == "statement"
        and is_nonempty_string(occurrence.get("occurrence_id"))
    }
    errors: list[str] = []
    for occurrence_id, occurrence in expected_occurrences.items():
        disposition = actual_dispositions[occurrence_id]
        if (
            disposition.get("target") != occurrence.get("target")
            or disposition.get("command") != occurrence.get("command")
        ):
            errors.append(f"{occurrence_id}: target or command differs")
            continue
        role = disposition.get("disposition")
        owner_status = occurrence.get("resolution_status")
        owner_unit_id = occurrence.get("owner_unit_id")
        owner_region = occurrence.get("owner_region")
        target = occurrence.get("target")
        if role == "internal_result":
            use_id = str(disposition.get("dependency_use_id"))
            dependency = dependencies_by_use.get(use_id)
            if (
                owner_status != "unique"
                or not is_nonempty_string(owner_unit_id)
                or owner_unit_id == packet.get("unit_id")
                or dependency is None
                or dependency.get("kind") != "internal_result"
                or dependency.get("id") != owner_unit_id
                or occurrence_id in foreign_nonproof_occurrences
            ):
                errors.append(
                    f"{occurrence_id}: internal_result does not map to "
                    "the exact foreign owner and packet use"
                )
        elif role == "local_step":
            if (
                owner_status != "unique"
                or owner_unit_id != packet.get("unit_id")
            ):
                errors.append(
                    f"{occurrence_id}: local_step does not name this unit"
                )
        elif role == "obligation_context":
            if owner_status == "unique":
                owned_statement = (
                    owner_unit_id == packet.get("unit_id")
                    and owner_region == "statement"
                )
                reviewed_foreign_context = (
                    owner_unit_id != packet.get("unit_id")
                    and occurrence_id in foreign_nonproof_occurrences
                )
                if not owned_statement and not reviewed_foreign_context:
                    errors.append(
                        f"{occurrence_id}: obligation_context must name this "
                        "unit's statement or a reviewed foreign non-proof unit"
                    )
        elif role == "own_result_identification":
            closing = bool(
                occurrence.get("structural_context") == "proof_header"
                or (
                    is_int(occurrence.get("source_position", occurrence.get("line")))
                    and occurrence.get("source_position", occurrence.get("line"))
                    >= max(int(proof_start or 0), proof_last - 2)
                )
            )
            if (
                owner_status != "unique"
                or owner_unit_id != packet.get("unit_id")
                or target != packet.get("unit_id")
                or not closing
            ):
                errors.append(
                    f"{occurrence_id}: own_result_identification is invalid"
                )
        elif role == "navigation":
            if occurrence.get("command") != "hyperref":
                errors.append(
                    f"{occurrence_id}: navigation requires hyperref"
                )
        elif role == "non_load_bearing":
            if (
                owner_status == "unique"
                and owner_unit_id == packet.get("unit_id")
                and target == packet.get("unit_id")
                and occurrence.get("structural_context") != "proof_header"
                and (
                    not is_int(occurrence.get("source_position", occurrence.get("line")))
                    or occurrence.get("source_position", occurrence.get("line"))
                    < max(int(proof_start or 0), proof_last - 2)
                )
            ):
                errors.append(
                    f"{occurrence_id}: mid-proof self-reference is load-bearing"
                )
        elif role == "unresolved":
            if review.get("unit_status") == "verified":
                errors.append(
                    f"{occurrence_id}: verified unit cannot leave it unresolved"
                )
        if (
            owner_status
            in {"missing", "duplicate", "ambiguous", "dynamic", "unowned"}
            and role
            not in {"unresolved", "navigation", "non_load_bearing"}
            and not (
                owner_status == "unowned"
                and role == "obligation_context"
            )
        ):
            errors.append(
                f"{occurrence_id}: unresolved owner cannot serve role {role}"
            )

    expected_citations = inventory.get("citation_keys")
    if not isinstance(expected_citations, list) or not all(
        is_nonempty_string(value) for value in expected_citations
    ):
        raise ValueError("Primary packet citation_keys are malformed")
    citation_rows = review.get("citation_dispositions")
    citation_rows = citation_rows if isinstance(citation_rows, list) else []
    actual_citations = {
        str(row.get("key")): row
        for row in citation_rows
        if isinstance(row, dict)
        and is_nonempty_string(row.get("key"))
    }
    if set(actual_citations) != set(expected_citations):
        missing = sorted(set(expected_citations) - set(actual_citations))
        stale = sorted(set(actual_citations) - set(expected_citations))
        details = []
        if missing:
            details.append("missing " + ", ".join(missing))
        if stale:
            details.append("stale " + ", ".join(stale))
        errors.append(
            "citation dispositions differ from packet citations: "
            + "; ".join(details)
        )
    for citation, disposition in actual_citations.items():
        role = disposition.get("disposition")
        if role == "external_result":
            use_id = str(disposition.get("dependency_use_id"))
            dependency = dependencies_by_use.get(use_id)
            if (
                dependency is None
                or dependency.get("kind") != "external_result"
                or dependency.get("id")
                != disposition.get("dependency_id")
            ):
                errors.append(
                    f"{citation}: external_result does not map to its exact "
                    "packet use"
                )
        elif role == "unresolved" and review.get("unit_status") == "verified":
            errors.append(
                f"{citation}: verified unit cannot leave it unresolved"
            )

    path_by_id = {
        str(row.get("path_id")): row
        for row in candidate_paths
        if isinstance(row, dict)
        and is_nonempty_string(row.get("path_id"))
    }
    candidate_rows = review.get("candidate_dependency_dispositions", [])
    candidate_rows = (
        candidate_rows if isinstance(candidate_rows, list) else []
    )
    for disposition in candidate_rows:
        if (
            not isinstance(disposition, dict)
            or disposition.get("disposition") == "internal_result"
        ):
            continue
        for path_id in disposition.get("path_ids", []):
            path = path_by_id.get(str(path_id))
            chain = path.get("reference_chain") if isinstance(path, dict) else None
            root_occurrence = (
                chain[0]
                if isinstance(chain, list)
                and chain
                and isinstance(chain[0], dict)
                else {}
            )
            role = disposition.get("disposition")
            if role == "navigation":
                if root_occurrence.get("command") != "hyperref":
                    errors.append(
                        f"{path_id}: navigation candidate requires hyperref"
                    )
            elif role == "obligation_context":
                root_disposition = actual_dispositions.get(
                    str(root_occurrence.get("occurrence_id"))
                )
                if (
                    root_occurrence.get("owner_proof_required") is not False
                    or root_occurrence.get("owner_environment")
                    not in OBLIGATION_CONTEXT_ENVIRONMENTS
                    or root_occurrence.get("owner_region") != "statement"
                    or root_occurrence.get("owner_unit_id")
                    != disposition.get("candidate_id")
                    or not isinstance(root_disposition, dict)
                    or root_disposition.get("disposition")
                    != "obligation_context"
                ):
                    errors.append(
                        f"{path_id}: obligation_context candidate must resolve "
                        "through its exact premise-bearing occurrence to a "
                        "reviewed foreign non-proof unit"
                    )
            elif role != "non_load_bearing":
                errors.append(
                    f"{path_id}: foreign dependency candidate without a "
                    "registry edge may only be obligation_context, navigation, "
                    "or non_load_bearing"
                )
    if errors:
        raise ValueError(
            "Compact packet disposition closure failed: "
            + "; ".join(errors)
        )


def compile_annotation_data(
    ledger: dict[str, Any],
    annotations: dict[str, Any],
    ledger_path: Path,
    packet: dict[str, Any] | None = None,
) -> dict[str, Any]:
    validate_compile_skeleton(ledger, ledger_path)
    annotation_object(
        annotations,
        "annotations",
        required=COMPACT_ANNOTATION_TOP_LEVEL_FIELDS,
    )
    version = annotations["annotation_schema_version"]
    if not is_int(version) or version != SEMANTIC_ANNOTATION_SCHEMA_VERSION:
        raise ValueError(
            "annotations.annotation_schema_version must be "
            f"{SEMANTIC_ANNOTATION_SCHEMA_VERSION}"
        )
    if annotations["unit_id"] != ledger.get("unit_id"):
        raise ValueError("annotations.unit_id does not match the extracted skeleton")
    source = ledger.get("source")
    expected_source_hash = source.get("unit_sha256") if isinstance(source, dict) else None
    supplied_source_hash = annotations["source_unit_sha256"]
    if (
        not isinstance(supplied_source_hash, str)
        or not SHA256_RE.fullmatch(supplied_source_hash)
        or supplied_source_hash != expected_source_hash
    ):
        raise ValueError(
            "annotations.source_unit_sha256 does not match the locked source unit"
        )
    supplied_obligation_hash = annotations["obligation_sha256"]
    expected_obligation_hash = canonical_sha256(ledger.get("obligation"))
    if (
        not isinstance(supplied_obligation_hash, str)
        or not SHA256_RE.fullmatch(supplied_obligation_hash)
        or supplied_obligation_hash != expected_obligation_hash
    ):
        raise ValueError(
            "annotations.obligation_sha256 does not match the normalized obligation"
        )
    if packet is not None:
        context_binding = packet.get("context_binding")
        expected_calibration_receipt = (
            context_binding.get("calibration_receipt_sha256")
            if isinstance(context_binding, dict)
            else None
        )
        supplied_calibration_receipt = annotations[
            "calibration_receipt_sha256"
        ]
        if (
            not isinstance(supplied_calibration_receipt, str)
            or not SHA256_RE.fullmatch(supplied_calibration_receipt)
            or supplied_calibration_receipt != expected_calibration_receipt
        ):
            raise ValueError(
                "annotations.calibration_receipt_sha256 does not match the "
                "primary packet; create a fresh annotation scaffold and fully "
                "re-review every judgment"
            )

    source_units, source_ranges = build_compiled_source_units(
        ledger, annotations["source_groups"]
    )
    direct_dependencies, dependencies_by_use = load_compact_dependencies(
        annotations["dependencies"]
    )
    if packet is not None:
        expected_dependencies = compact_dependencies_from_packet(
            packet.get("dependencies")
        )
        normalized_dependencies = sorted(
            direct_dependencies, key=lambda row: str(row.get("use_id", ""))
        )
        if normalized_dependencies != expected_dependencies:
            expected_by_use = {
                str(row.get("use_id")): row
                for row in expected_dependencies
            }
            actual_by_use = {
                str(row.get("use_id")): row
                for row in normalized_dependencies
            }
            differences: list[str] = []
            for use_id in sorted(set(expected_by_use) | set(actual_by_use)):
                if use_id not in expected_by_use:
                    differences.append(f"{use_id}: not in packet")
                elif use_id not in actual_by_use:
                    differences.append(f"{use_id}: missing from annotations")
                else:
                    fields = sorted(
                        field
                        for field in set(expected_by_use[use_id])
                        | set(actual_by_use[use_id])
                        if expected_by_use[use_id].get(field)
                        != actual_by_use[use_id].get(field)
                    )
                    if fields:
                        differences.append(
                            f"{use_id}: fields differ: {', '.join(fields)}"
                        )
            raise ValueError(
                "annotations.dependencies must exactly match the primary "
                "packet's registry-backed direct uses: "
                + "; ".join(differences)
            )
    plans, key_to_step_id = prepare_compact_step_plans(
        annotations["steps"], source_units, source_ranges
    )
    steps, built_by_key = build_compact_steps(
        ledger,
        source_units,
        plans,
        key_to_step_id,
        dependencies_by_use,
    )
    expected_use_sites: list[str] = []
    if packet is not None:
        inventory_projection = packet.get("inventory")
        raw_use_sites = (
            inventory_projection.get("downstream_use_sites", [])
            if isinstance(inventory_projection, dict)
            else []
        )
        if not isinstance(raw_use_sites, list) or not all(
            isinstance(row, dict)
            and is_nonempty_string(row.get("canonical_location"))
            for row in raw_use_sites
        ):
            raise ValueError(
                "Primary packet downstream_use_sites are malformed"
            )
        expected_use_sites = sorted(
            str(row["canonical_location"]) for row in raw_use_sites
        )
    review = build_compact_review(
        ledger,
        annotations["review"],
        annotations["conclusions"],
        steps,
        built_by_key,
        direct_dependencies,
        expected_use_sites,
    )
    candidate = {
        **ledger,
        "source_units": source_units,
        "review": review,
        "steps": steps,
    }
    if packet is not None:
        work_context_sha256 = packet.get("work_context_sha256")
        if (
            not isinstance(work_context_sha256, str)
            or not SHA256_RE.fullmatch(work_context_sha256)
        ):
            raise ValueError(
                "Primary packet does not carry a valid work_context_sha256"
            )
        candidate["work_context_sha256"] = work_context_sha256
        validate_compiled_candidate_reconciliation(packet, candidate)
        validate_compiled_packet_dispositions(packet, candidate)
    return candidate


def compiled_dependency_binding_diagnostics(
    candidate: dict[str, Any], summary: dict[str, Any],
    packet: dict[str, Any], annotations: dict[str, Any],
) -> list[dict[str, str]]:
    """One exact-use gate shared by preflight, compilation, and submission."""
    diagnostics: list[dict[str, str]] = []
    errors: list[str] = []
    unit_id = str(candidate.get("unit_id", ""))
    invoking = expected_result_uses({unit_id: summary}, errors)
    projection = packet.get("dependencies")
    if not isinstance(projection, dict):
        errors.append("Compiler packet dependencies are malformed")
        projection = {}
    for message in errors:
        append_annotation_diagnostic(
            diagnostics, "/dependencies", "dependency_binding_error", message
        )
    seen: set[str] = set()
    for field in ("direct_internal_uses", "direct_external_uses"):
        rows = projection.get(field, [])
        if not isinstance(rows, list):
            append_annotation_diagnostic(
                diagnostics, "/dependencies", "dependency_binding_error",
                f"Compiler packet dependencies.{field} is malformed",
            )
            continue
        for index, row in enumerate(rows, 1):
            use = row if isinstance(row, dict) else {}
            use_id = str(use.get("use_id", ""))
            prefix = f"dependencies.{field}[{index}] ({use_id or 'unnamed use'})"
            expected = invoking.get((unit_id, use_id))
            row_errors: list[str] = []
            if use_id in seen:
                row_errors.append(f"{prefix}: duplicate dependency use")
            seen.add(use_id)
            if expected is None:
                row_errors.append(f"{prefix} is not invoked by the compiled ledger")
            else:
                validate_dependency_use_identity(use, prefix, expected, row_errors)
                if use.get("status") != expected.get("status"):
                    row_errors.append(f"{prefix}.status disagrees with the compiled ledger")
            sites = [
                (f"/steps/{step_index}/inputs/{input_index}/reference", step.get("key"))
                for step_index, step in enumerate(annotations.get("steps", []))
                if isinstance(step, dict)
                for input_index, premise in enumerate(step.get("inputs", []))
                if isinstance(premise, dict) and premise.get("kind") == "dependency"
                and premise.get("reference") == use_id
            ]
            for message in row_errors:
                for pointer, key in sites or [("/dependencies", None)]:
                    append_annotation_diagnostic(
                        diagnostics, pointer, "dependency_binding_error",
                        message + (f"; draft step {key!r}" if key else ""),
                    )
    for _, use_id in sorted(invoking):
        if use_id not in seen:
            append_annotation_diagnostic(
                diagnostics, "/dependencies", "dependency_binding_error",
                f"{use_id}: compiled invocation is missing from the current registry",
            )
    return diagnostics


def cmd_compile_annotations(args: argparse.Namespace) -> int:
    configure_console_errors()
    ledger_path = args.ledger.resolve()
    annotations_path = args.annotations.resolve()
    packet_value = getattr(args, "packet", None)
    if not isinstance(packet_value, Path):
        raise ValueError("compile-annotations requires --packet")
    packet_path = packet_value.resolve()
    output_path = args.output.resolve()
    if not ledger_path.is_file():
        raise FileNotFoundError(f"Extracted ledger not found: {ledger_path}")
    if not annotations_path.is_file():
        raise FileNotFoundError(f"Compact annotations not found: {annotations_path}")
    if not packet_path.is_file():
        raise FileNotFoundError(f"Primary context packet not found: {packet_path}")
    if ledger_path == annotations_path:
        raise ValueError("The ledger and compact annotation files must be distinct")
    if not ledger_path.name.endswith(".skeleton.json"):
        raise ValueError(
            "Compact compiler input must end in .skeleton.json so canonical ledger "
            "discovery cannot treat the unfinished input as audit evidence"
        )
    expected_output_name = (
        ledger_path.name[: -len(".skeleton.json")] + ".ledger.json"
    )
    expected_output_path = ledger_path.with_name(expected_output_name)
    if not output_path.name.endswith(".ledger.json"):
        raise ValueError(
            "Compiled output must end in .ledger.json; "
            f"required canonical sibling path: {expected_output_path}"
        )
    if output_path.name != expected_output_name:
        raise ValueError(
            "Compiled output basename must equal the skeleton basename with "
            ".skeleton.json replaced by .ledger.json; "
            f"required canonical sibling path: {expected_output_path}"
        )
    if output_path == ledger_path:
        raise ValueError("Compiled output must not overwrite the extracted ledger")
    if output_path == annotations_path:
        raise ValueError("Compiled output must not overwrite compact annotations")
    if output_path == packet_path:
        raise ValueError("Compiled output must not overwrite the primary context packet")
    if output_path.parent != ledger_path.parent:
        raise ValueError(
            "Compiled output must be in the extracted ledger directory so locked "
            "relative paths retain their identity; "
            f"required canonical sibling path: {expected_output_path}"
        )
    if output_path.exists():
        raise FileExistsError(
            "Compiled ledger already exists and cannot be overwritten in place; "
            f"preserve or archive it before creating a new audit record: {output_path}"
        )

    audit_root = containing_audit_root(ledger_path)
    if audit_root is None:
        raise ValueError(
            "compile-annotations requires a skeleton inside a canonical audit root"
        )
    if annotations_path.is_relative_to(audit_root):
        raise ValueError(
            "Compact annotations must remain outside the canonical audit root"
        )
    try:
        current_calibration_receipt(audit_root)
    except (OSError, UnicodeError, ValueError) as exc:
        raise ValueError(
            "compile-annotations requires a current passing balanced checker "
            "calibration before publishing checker-authored proof evidence: "
            + str(exc)
        ) from exc

    ledger, ledger_errors = load_json_object(ledger_path, "extracted ledger")
    if ledger_errors:
        raise ValueError(ledger_errors[0])
    annotations, annotation_errors = load_json_object(
        annotations_path, "compact annotations"
    )
    if annotation_errors:
        raise ValueError(annotation_errors[0])
    packet = validate_compiler_context_packet(
        ledger, ledger_path, annotations, packet_path
    )
    preflight = annotation_preflight_diagnostics(
        ledger,
        ledger_path,
        annotations,
        packet,
        deep_validation=False,
    )
    if preflight:
        shown = "; ".join(
            f"{row['pointer']} {row['code']}: {row['message']}"
            for row in preflight[:12]
        )
        suffix = (
            f"; and {len(preflight) - 12} more"
            if len(preflight) > 12
            else ""
        )
        raise ValueError(
            "Compact annotation preflight failed: " + shown + suffix
        )
    candidate = compile_annotation_data(
        ledger, annotations, ledger_path, packet
    )

    source = candidate.get("source")
    source_file = source.get("file") if isinstance(source, dict) else None
    if is_nonempty_string(source_file):
        if output_path == resolve_stored_path(source_file, ledger_path.parent):
            raise ValueError("Compiled output must not overwrite the locked source")

    temporary = _unique_sibling_temp_path(output_path)
    try:
        if temporary.is_symlink():
            raise ValueError(f"Refusing a symlinked compiler candidate: {temporary}")
        payload = json.dumps(candidate, ensure_ascii=False, indent=2) + "\n"
        with temporary.open("w", encoding="utf-8", newline="\n") as stream:
            stream.write(payload)
            stream.flush()
            os.fsync(stream.fileno())
        validation_errors, summary = check_ledger_data(temporary, True)
        if validation_errors:
            shown = "; ".join(validation_errors[:12])
            suffix = (
                f"; and {len(validation_errors) - 12} more"
                if len(validation_errors) > 12
                else ""
            )
            raise ValueError(
                "Compiled ledger failed full final validation: " + shown + suffix
            )
        dependency_binding_errors = [row["message"] for row in
            compiled_dependency_binding_diagnostics(candidate, summary, packet, annotations)]
        if dependency_binding_errors:
            shown = "; ".join(dependency_binding_errors[:12])
            suffix = (
                f"; and {len(dependency_binding_errors) - 12} more"
                if len(dependency_binding_errors) > 12
                else ""
            )
            raise ValueError(
                "Compiled ledger dependency binding disagrees with the current "
                "registry: " + shown + suffix
            )
        publication_method = publish_no_overwrite(
            temporary, output_path, "Compiled ledger"
        )
    finally:
        if temporary.exists():
            temporary.unlink()

    print(
        json.dumps(
            {
                "command": "compile-annotations",
                "ledger": output_path.as_posix(),
                "unit_id": candidate.get("unit_id"),
                "annotation_schema_version": SEMANTIC_ANNOTATION_SCHEMA_VERSION,
                "source_units": len(candidate["source_units"]),
                "steps": len(candidate["steps"]),
                "semantic_steps": sum(
                    step.get("status") != "non_substantive"
                    for step in candidate["steps"]
                ),
                "annotation_sha256": sha256_file(annotations_path),
                "packet_sha256": sha256_file(packet_path),
                "obligation_sha256": annotations["obligation_sha256"],
                "context_binding_sha256": packet["context_binding_sha256"],
                "work_context_sha256": candidate["work_context_sha256"],
                "operational_binding_sha256": packet[
                    "operational_binding_sha256"
                ],
                "submitted_operational_binding_sha256": packet[
                    "_submitted_operational_binding_sha256"
                ],
                "operational_binding_drift": packet[
                    "_operational_binding_drift"
                ],
                "primary_ledger_sha256": canonical_primary_ledger_sha256(candidate),
                "validation": summary["validation_scope"][
                    "local_record_integrity"
                ],
                "artifact_state": "compiled_schema5_ledger",
                "publication_method": publication_method,
            },
            ensure_ascii=True,
            indent=2,
        )
    )
    return 0


def cmd_migrate_ledger(args: argparse.Namespace) -> int:
    source_path = args.ledger.resolve()
    output_path = args.output.resolve()
    if not source_path.is_file():
        raise FileNotFoundError(f"Legacy ledger not found: {source_path}")
    if source_path == output_path:
        raise ValueError(
            "Migration must write a separate file so the legacy record remains inspectable"
        )
    if output_path.exists() and not args.force:
        raise FileExistsError(
            f"Migration output exists; use --force to replace it: {output_path}"
        )
    legacy, read_errors = load_json_object(source_path, "legacy ledger")
    if read_errors:
        raise ValueError(read_errors[0])
    if legacy.get("schema_version") != LEGACY_SCHEMA_VERSION:
        raise ValueError("migrate-ledger accepts only artifact schema 4")
    source_lines = legacy.get("source_lines")
    if not isinstance(source_lines, list) or not source_lines:
        raise ValueError("Legacy ledger has no locked source_lines")
    source_units: list[dict[str, Any]] = []
    for index, row in enumerate(source_lines, 1):
        if (
            not isinstance(row, dict)
            or not is_int(row.get("line"))
            or not isinstance(row.get("text"), str)
        ):
            raise ValueError(f"Legacy source_lines[{index}] is malformed")
        text = row["text"]
        source_units.append(
            {
                "id": f"U{index:03d}",
                "lines": [row["line"], row["line"]],
                "kind": (
                    "non_substantive" if is_non_substantive(text) else "one_line"
                ),
                "source_sha256": sha256_text(text),
                "partition_evidence": (
                    "The locked line is blank, comment-only, or a proof wrapper."
                    if is_non_substantive(text)
                    else "This migration unit is exactly one locked physical line."
                ),
            }
        )
    migrated = {
        **legacy,
        "schema_version": SCHEMA_VERSION,
        "evidence_contract_version": EVIDENCE_CONTRACT_VERSION,
        "source_units": source_units,
        "review": {
            "unit_status": "not_checked",
            "conclusion_step_id": "",
            "conclusion_results": [],
            "contract_fidelity": "not_checked",
            "argument_status": "not_checked",
            "statement_status": "not_assessed",
            "dependency_closure": "not_checked",
            "explicit_assumptions": [],
            "inherited_assumptions": [],
            "direct_dependencies": [],
            "source_reference_dispositions": [],
            "candidate_dependency_dispositions": [],
            "citation_dispositions": [],
            "use_sites": [],
            "verification_basis": [],
            "reviewer_notes": [],
        },
        "independent_check": {
            "required": False,
            "status": "not_required",
            "independence_level": "none",
            "challenger_verdict": "not_checked",
            "reconciled_verdict": "not_checked",
            "artifact": "",
            "covered_issue_ids": [],
            "source_snapshot_sha256": "",
            "challenged_ledger_sha256": "",
            "challenge_context_sha256": "",
            "challenge_artifact_sha256": "",
            "issue_assessments": [],
            "generated_utc": "",
            "disagreements": [],
            "resolution": "",
        },
        "steps": [],
        "migration": {
            "from_schema_version": LEGACY_SCHEMA_VERSION,
            "from_evidence_contract_version": legacy.get(
                "evidence_contract_version"
            ),
            "legacy_ledger_sha256": sha256_file(source_path),
            "legacy_step_count": len(legacy.get("steps", []))
            if isinstance(legacy.get("steps"), list)
            else 0,
            "status": "requires_manual_recheck",
            "recheck_evidence": "",
            "rechecked_utc": "",
        },
    }
    atomic_write_json(output_path, migrated)
    print(
        json.dumps(
            {
                "legacy_ledger": str(source_path),
                "migrated_ledger": str(output_path),
                "artifact_schema_version": SCHEMA_VERSION,
                "artifact_state": "requires_manual_recheck",
                "next_action": (
                    "Rebuild atomic steps against source_units, rerun every "
                    "mathematical check, then set migration.status to rechecked "
                    "with evidence and UTC time."
                ),
            },
            indent=2,
        )
    )
    return 0


def is_non_substantive(text: str) -> bool:
    stripped = text.strip()
    if not stripped or stripped.startswith("%"):
        return True
    return bool(
        re.fullmatch(
            r"\\(?:begin|end)\{proof\}(?:\[[^]]*\])?|\\qed(?:here)?",
            stripped,
        )
    )


def validate_source_units(
    value: Any,
    *,
    start: int,
    end: int,
    selected_lines: list[str],
    source_records: list[dict[str, Any]] | None = None,
    final: bool,
    errors: list[str],
) -> tuple[
    dict[str, dict[str, Any]],
    dict[int, list[str]],
    dict[str, int],
]:
    """Validate exact physical coverage independently of inferential steps."""
    if not isinstance(value, list):
        errors.append("source_units must be a list under artifact schema 5")
        return {}, defaultdict(list), {}
    units: dict[str, dict[str, Any]] = {}
    coverage: dict[int, list[str]] = defaultdict(list)
    order: dict[str, int] = {}
    previous_end = start - 1
    display_spans = display_math_spans(selected_lines)
    masked_lines = mask_structural_tex("\n".join(selected_lines)).split("\n")
    for index, record in enumerate(value, 1):
        prefix = f"source_units[{index}]"
        if not isinstance(record, dict):
            errors.append(f"{prefix} must be an object")
            continue
        unit_id = record.get("id")
        if not isinstance(unit_id, str) or not SOURCE_UNIT_ID_RE.fullmatch(unit_id):
            errors.append(f"{prefix}.id must match U001")
            continue
        if unit_id in units:
            errors.append(f"Duplicate source unit id: {unit_id}")
            continue
        units[unit_id] = record
        order[unit_id] = index
        line_range = record.get("lines")
        if (
            not isinstance(line_range, list)
            or len(line_range) != 2
            or not all(is_int(item) for item in line_range)
        ):
            errors.append(f"{prefix}.lines must be [start, end]")
            continue
        unit_start, unit_end = line_range
        if unit_start > unit_end or unit_start < start or unit_end > end:
            errors.append(
                f"{prefix}.lines {unit_start}-{unit_end} lies outside {start}-{end}"
            )
            continue
        if unit_start <= previous_end:
            errors.append(f"{prefix} must follow prior source units in source order")
        previous_end = max(previous_end, unit_end)
        for line_number in range(unit_start, unit_end + 1):
            coverage[line_number].append(unit_id)
        kind = record.get("kind")
        if not is_enum_value(kind, SOURCE_UNIT_KINDS):
            errors.append(f"{prefix}.kind is invalid: {kind!r}")
            continue
        local_start = unit_start - start
        local_end = unit_end - start + 1
        texts = selected_lines[local_start:local_end]
        if len(texts) != unit_end - unit_start + 1:
            continue
        expected_hash = sha256_text("\n".join(texts))
        if record.get("source_sha256") != expected_hash:
            errors.append(f"{prefix}.source_sha256 does not match locked source")
        if final and not is_substantive_string(record.get("partition_evidence")):
            errors.append(f"{prefix}.partition_evidence must be substantive")
        if kind == "one_line" and unit_start != unit_end:
            errors.append(f"{prefix}: one_line must cover exactly one physical line")
        substantive_flags = [locked_line_is_non_substantive(row) for row in source_records[local_start:local_end]] if source_records is not None else [is_non_substantive(text) for text in texts]
        if kind == "non_substantive":
            if not all(substantive_flags):
                errors.append(f"{prefix}: non_substantive covers mathematical content")
        else:
            if all(substantive_flags):
                errors.append(f"{prefix}: substantive source unit has no content")
        if kind == "continued_sentence":
            if unit_start == unit_end:
                errors.append(f"{prefix}: continued_sentence must span multiple lines")
            if any(not strip_latex_comment(text).strip() for text in texts):
                errors.append(
                    f"{prefix}: continued_sentence cannot cross a blank or "
                    "comment-only separator"
                )
        if kind == "continued_display":
            if unit_start == unit_end:
                errors.append(f"{prefix}: continued_display must span multiple lines")
            if not display_math_contains_lines(
                display_spans, masked_lines, local_start + 1, local_end
            ):
                errors.append(
                    f"{prefix}: continued_display must lie inside one complete "
                    "recognized display environment"
                )

    for first, last in consecutive_ranges(
        line_number
        for line_number in range(start, end + 1)
        if not coverage.get(line_number)
    ):
        label = str(first) if first == last else f"{first}-{last}"
        errors.append(f"Uncovered source-unit lines: {label}")
    for first, last in consecutive_ranges(
        line_number
        for line_number in range(start, end + 1)
        if len(coverage.get(line_number, [])) > 1
    ):
        label = str(first) if first == last else f"{first}-{last}"
        errors.append(f"Multiply covered source-unit lines: {label}")
    return units, coverage, order


def expected_unit_status(statuses: list[str]) -> str:
    substantive = [status for status in statuses if status != "non_substantive"]
    if not substantive or "not_checked" in substantive:
        return "not_checked"
    if "incorrect" in substantive:
        return "incorrect"
    if "gap" in substantive:
        return "gap"
    if "unclear" in substantive:
        return "unclear"
    if "conditionally_verified" in substantive:
        return "conditionally_verified"
    if all(status == "verified" for status in substantive):
        return "verified"
    return "not_checked"


def conclusion_contract_payload(
    obligation: dict[str, Any], conclusion_id: str
) -> dict[str, Any] | None:
    conclusions = obligation.get("conclusions")
    if not isinstance(conclusions, list):
        return None
    record = next(
        (
            item
            for item in conclusions
            if isinstance(item, dict) and item.get("id") == conclusion_id
        ),
        None,
    )
    if record is None:
        return None
    applicability: list[dict[str, Any]] = []
    pointers = record.get("applies_under")
    if isinstance(pointers, list):
        for pointer in pointers:
            found, value = resolve_json_pointer(obligation, pointer)
            applicability.append(
                {
                    "pointer": pointer,
                    "resolved": value if found else None,
                }
            )
    return {
        "id": record.get("id"),
        "claim": record.get("claim"),
        "source_spans": record.get("source_spans"),
        "applicability": applicability,
    }


def statement_support_projection(
    ledger: dict[str, Any], result: dict[str, Any], errors: list[str],
    *, provisional: bool = False,
) -> dict[str, Any] | None:
    """Check a separate reconstruction using the ordinary checked move graph."""
    value = result.get("statement_support")
    if value is None:
        return None
    prefix = f"conclusion {result.get('conclusion_id')}.statement_support"
    fields = {"schema_version", "support", "target_contract_sha256", "extra_conditions", "evidence"}
    before = len(errors)
    if not isinstance(value, dict) or set(value) != fields or type(value.get("schema_version")) is not int or value.get("schema_version") != 1:
        errors.append(f"{prefix} requires the version-1 checked-support fields")
        return None
    obligation = ledger.get("obligation") or {}
    contract = conclusion_contract_payload(obligation, str(result.get("conclusion_id")))
    if not contract or value.get("target_contract_sha256") != canonical_sha256(contract):
        errors.append(f"{prefix}.target_contract_sha256 is stale or names a different conclusion")
    if not is_substantive_string(value.get("evidence")):
        errors.append(f"{prefix}.evidence must explain the supplied reconstruction")
    support = value.get("support")
    if (not isinstance(support, dict) or set(support) != {"step_id", "move_id"}
            or not all(is_nonempty_string(support.get(key)) for key in ("step_id", "move_id"))):
        errors.append(f"{prefix}.support must identify one checked move")
        return None
    if support == result.get("support"):
        errors.append(f"{prefix} must preserve a distinct written-argument support move")
    steps = {step.get("id"): step for step in ledger.get("steps", []) if isinstance(step, dict)}
    step = steps.get(support["step_id"], {})
    moves = (step.get("inference") or {}).get("moves", [])
    move = next((row for row in moves if isinstance(row, dict) and row.get("id") == support["move_id"]), None)
    if not move or step.get("support_role") != "derivation":
        errors.append(f"{prefix} must name an ordinary checked derivation move")
        return None
    if contract and move.get("claim") != contract.get("claim"):
        errors.append(f"{prefix} move must reach the exact original conclusion claim")
    closure = ledger_support_contract_closure(ledger, support["step_id"], support["move_id"])
    closure_ids = {key[0] for key in closure["move_keys"]}
    closure_steps = [step for step in ledger.get("steps", []) if isinstance(step, dict) and step.get("id") in closure_ids]
    conditions: list[str] = []
    for member in closure_steps:
        if member.get("status") not in {"verified", "conditionally_verified"}:
            errors.append(f"{prefix} inherits a nonverified move {member.get('id')}")
        for cause in member.get("conditions", []):
            inherited_side_condition = (isinstance(cause, dict) and cause.get("kind") == "dependency"
                                        and cause.get("reference") in closure_ids)
            if isinstance(cause, dict) and cause.get("kind") != "side_condition" and not inherited_side_condition:
                errors.append(f"{prefix} cannot replace unchecked dependencies or risks with extra conditions")
        for condition in member.get("side_conditions", []):
            if isinstance(condition, dict) and condition.get("status") == "open":
                text = condition.get("condition")
                if is_substantive_string(text) and text not in conditions:
                    conditions.append(text)
    extra = value.get("extra_conditions")
    if extra != conditions:
        errors.append(f"{prefix}.extra_conditions must exactly list its open side conditions in support order")
    direct = {row.get("use_id"): row for row in (ledger.get("review") or {}).get("direct_dependencies", []) if isinstance(row, dict)}
    dependency_ids = sorted(closure["dependency_uses"])
    for use_id in dependency_ids:
        if direct.get(use_id, {}).get("status") != "verified":
            errors.append(f"{prefix} requires checked dependency {use_id}")
    allowed = {row.get("pointer") for row in (contract or {}).get("applicability", []) if isinstance(row, dict)}
    if closure["obligation_pointers"] - allowed:
        errors.append(f"{prefix} uses assumptions outside the exact conclusion contract")
    if result.get("contract_fidelity") != "verified":
        errors.append(f"{prefix} requires verified original contract fidelity")
    if result.get("statement_status") == "established" and conditions:
        errors.append(f"{prefix}: extra conditions cannot establish the unrestricted statement")
    if result.get("statement_status") == "refuted" and not conditions:
        errors.append(f"{prefix}: an unrestricted supplement cannot coexist with a refutation of the same target")
    payload = {
        "unit_id": ledger.get("unit_id"), "source": ledger.get("source"),
        "work_context_sha256": ledger.get("work_context_sha256"),
        "contract": contract, "statement_support": value,
        "steps": closure_steps, "dependencies": [direct.get(key) for key in dependency_ids],
    }
    return {
        **value, "sha256": canonical_sha256(payload), "claim": (contract or {}).get("claim"),
        "status": "conditional" if conditions else "verified",
        "dependency_use_ids": dependency_ids, "dependency_closure": "verified",
        "acceptance": "pending", "provisional": provisional,
        "valid": len(errors) == before,
    }


def statement_support_proposals(ledger: dict[str, Any]) -> list[dict[str, Any]]:
    """Expose proposed mathematics, not the primary judgment, for separate review."""
    proposals = []
    for result in (ledger.get("review") or {}).get("conclusion_results", []):
        if not isinstance(result, dict) or "statement_support" not in result:
            continue
        errors: list[str] = []
        support = statement_support_projection(ledger, result, errors)
        if errors or support is None:
            raise ValueError("Invalid statement support: " + "; ".join(errors))
        closure = ledger_support_contract_closure(ledger, support["support"]["step_id"], support["support"]["move_id"])
        ids = {key[0] for key in closure["move_keys"]}
        proposed_steps = []
        source_units = {row.get("id"): row for row in ledger.get("source_units", []) if isinstance(row, dict)}
        for step in ledger.get("steps", []):
            if step.get("id") not in ids:
                continue
            proposed_steps.append({
                "step_id": step.get("id"), "source_unit_id": step.get("source_unit_id"),
                "source_span": source_unit_location(ledger, source_units.get(step.get("source_unit_id"), {})),
                "claim": step.get("restatement"),
                "premises": step.get("premise_uses", []),
                "moves": [{key: row.get(key) for key in ("id", "claim", "rule", "justification", "premise_ids", "prior_move_ids")}
                          for row in (step.get("inference") or {}).get("moves", []) if isinstance(row, dict)],
                "side_conditions": [{key: row.get(key) for key in ("id", "condition", "generated_by", "discharge")}
                                    for row in step.get("side_conditions", []) if isinstance(row, dict)],
            })
        proposals.append({
            "conclusion_id": result["conclusion_id"], "statement_support_sha256": support["sha256"],
            "target": conclusion_contract_payload(ledger["obligation"], result["conclusion_id"]),
            "extra_conditions": support["extra_conditions"],
            "reconstruction": support["evidence"], "steps": proposed_steps,
        })
    return proposals


def statement_support_response_errors(response: Any, packet: dict[str, Any]) -> list[str]:
    errors: list[str] = []
    fields = {"response_schema_version", "unit_id", "packet_sha256", "independence_level", "assessments"}
    if packet.get("suggested_changes"):
        fields.add("change_assessments")
    if not isinstance(response, dict) or set(response) != fields:
        return ["Statement-support response requires exactly: " + ", ".join(sorted(fields))]
    if type(response.get("response_schema_version")) is not int or response["response_schema_version"] != 1:
        errors.append("Statement-support response_schema_version must be 1")
    if response.get("unit_id") != packet.get("unit_id") or response.get("packet_sha256") != canonical_sha256(packet):
        errors.append("Statement-support response must bind the exact consumed packet and unit")
    if not is_enum_value(response.get("independence_level"), INDEPENDENCE_LEVELS - {"none"}):
        errors.append("Statement-support review needs a declared independent context")
    proposals = packet.get("statement_supports")
    if not isinstance(proposals, list) or not proposals or any(not isinstance(row, dict) or not is_nonempty_string(row.get("conclusion_id")) or not is_nonempty_string(row.get("statement_support_sha256")) for row in proposals):
        return [*errors, "Statement-support packet needs exact nonempty proposal targets"]
    expected = {row["conclusion_id"]: row["statement_support_sha256"] for row in proposals}
    seen = []
    rows = response.get("assessments")
    if not isinstance(rows, list):
        return [*errors, "Statement-support assessments must be a list"]
    for row in rows:
        if not isinstance(row, dict) or set(row) != {"conclusion_id", "statement_support_sha256", "assessment", "reason"}:
            errors.append("Each support assessment requires conclusion_id, statement_support_sha256, assessment, reason")
            continue
        key = row.get("conclusion_id")
        seen.append(key)
        if not isinstance(key, str) or key not in expected or row.get("statement_support_sha256") != expected.get(key):
            errors.append("Statement-support assessment has a stale or unknown exact target")
        if not is_enum_value(row.get("assessment"), {"accepted", "rejected", "unclear"}):
            errors.append("Statement-support assessment must be accepted, rejected, or unclear")
        if not is_substantive_string(row.get("reason")):
            errors.append("Statement-support assessment needs its checked mathematical reason")
    if sorted(str(key) for key in seen) != sorted(expected):
        errors.append("Statement-support review must assess exactly every proposed support")
    if packet.get("suggested_changes"):
        changes = packet["suggested_changes"]
        assessed = response.get("change_assessments")
        expected_changes = {(row["issue_id"], row["change_index"]): row["sha256"] for row in changes}
        seen_changes = []
        if not isinstance(assessed, list):
            errors.append("Statement-support change_assessments must be a list")
            assessed = []
        for row in assessed:
            if not isinstance(row, dict) or set(row) != {"issue_id", "change_index", "sha256", "assessment", "reason"}:
                errors.append("Each change assessment requires issue_id, change_index, sha256, assessment, and reason")
                continue
            key = (str(row.get("issue_id")), row.get("change_index"))
            if not is_int(key[1]) or key not in expected_changes or row.get("sha256") != expected_changes.get(key):
                errors.append("Suggested-change assessment does not bind the exact proposal and source target")
            seen_changes.append(key)
            if not is_enum_value(row.get("assessment"), {"accepted", "rejected", "unclear"}) or not is_substantive_string(row.get("reason")):
                errors.append("Suggested-change assessment requires accepted/rejected/unclear and its mathematical reason")
        if sorted((str(a), str(b)) for a, b in seen_changes) != sorted((str(a), str(b)) for a, b in expected_changes):
            errors.append("Statement-support review must assess exactly every linked suggested change")
    return errors


def statement_support_changes(root: Path, ledger: dict[str, Any]) -> list[dict[str, Any]]:
    _, issues, _, errors = load_issue_log(root)
    if errors:
        raise ValueError("Cannot inspect linked suggested changes: " + "; ".join(errors))
    rows = []
    for issue in issues:
        for index, change in enumerate(issue.get("suggested_changes", []), 1):
            if not isinstance(change, dict):
                continue
            reference = change.get("statement_support_ref")
            if not isinstance(reference, dict) or reference.get("unit_id") != ledger.get("unit_id"):
                continue
            payload = {key: value for key, value in change.items() if key != "verification_status"}
            rows.append({"issue_id": issue.get("id"), "change_index": index,
                         "sha256": canonical_sha256(payload), "change": payload})
    return rows


def load_statement_support_review(root: Path, ledger: dict[str, Any]) -> tuple[dict[str, str], list[str]]:
    """Read the immutable supplemental response; coordinator flags supply no support."""
    check = ledger.get("independent_check") or {}
    reference = check.get("statement_support_review")
    if reference is None:
        return {}, []
    errors: list[str] = []
    history = check.get("statement_support_review_history", [])
    if not isinstance(history, list):
        errors.append("statement_support_review_history must preserve a list of exact references")
        history = []
    seen_history = set()
    for prior in history:
        if not isinstance(prior, dict) or set(prior) != {"artifact", "sha256"}:
            errors.append("Historical statement-support review must retain its artifact and digest")
            continue
        historical_path, historical_valid = canonical_challenge_artifact_path(root, prior.get("artifact"), "Historical statement-support review", errors)
        if (not historical_valid or historical_path is None or not historical_path.is_file()
                or sha256_file(historical_path) != prior.get("sha256") or prior.get("artifact") in seen_history):
            errors.append("Historical statement-support review is missing, altered, or duplicated")
        seen_history.add(prior.get("artifact"))
    if not isinstance(reference, dict) or set(reference) != {"artifact", "sha256"}:
        return {}, ["statement_support_review needs an artifact and exact sha256"]
    path, valid = canonical_challenge_artifact_path(root, reference.get("artifact"), "Statement-support review", errors)
    if not valid or path is None or not path.is_file():
        return {}, [*errors, "Statement-support review artifact is unavailable"]
    if reference.get("sha256") != sha256_file(path):
        return {}, ["Statement-support review artifact is stale or altered"]
    record, read_errors = load_json_object(path, "statement-support review")
    if read_errors:
        return {}, read_errors
    packet = record.get("packet")
    if not isinstance(packet, dict) or packet.get("kind") != "stat-paper-proofcheck-statement-support-packet":
        return {}, ["Statement-support review has no authenticated proposal packet"]
    try:
        expected = statement_support_proposals(ledger)
    except ValueError as exc:
        return {}, [str(exc)]
    if packet.get("statement_supports") != expected or packet.get("unit_id") != ledger.get("unit_id"):
        errors.append("Statement-support review is stale relative to its current target, conditions, or checked derivation")
    if packet.get("initial_response") != (ledger.get("independent_check") or {}).get("initial_response"):
        errors.append("Statement-support review must preserve the current initial blind response")
    try:
        if packet.get("suggested_changes", []) != statement_support_changes(root, ledger):
            errors.append("Statement-support review is stale relative to its linked suggested changes")
    except ValueError as exc:
        errors.append(str(exc))
    errors.extend(statement_support_response_errors(record.get("response"), packet))
    if errors:
        return {}, errors
    return {row["conclusion_id"]: row["assessment"] for row in record["response"]["assessments"]}, []


def checked_suggested_change_errors(
    issue: dict[str, Any], change: dict[str, Any], index: int, root: Path,
    ledgers: dict[str, dict[str, Any]],
) -> list[str]:
    prefix = f"{issue.get('id')}.suggested_changes[{index}]"
    reference = change.get("statement_support_ref")
    if not isinstance(reference, dict) or set(reference) != {"unit_id", "conclusion_id", "sha256"}:
        return [f"{prefix}: unapplied verified_sufficient needs an exact statement_support_ref"]
    ledger = ledgers.get(str(reference.get("unit_id")))
    if ledger is None or reference.get("unit_id") != issue.get("affected_result"):
        return [f"{prefix}: checked proposal must support the root affected result"]
    result = next((row for row in (ledger.get("review") or {}).get("conclusion_results", []) if isinstance(row, dict) and row.get("conclusion_id") == reference.get("conclusion_id")), {})
    errors: list[str] = []
    support = statement_support_projection(ledger, result, errors)
    if support is None or support.get("sha256") != reference.get("sha256"):
        errors.append(f"{prefix}: proposal support is missing or stale")
    acceptance, review_errors = load_statement_support_review(root, ledger)
    errors.extend(review_errors)
    if acceptance.get(str(reference.get("conclusion_id"))) != "accepted":
        errors.append(f"{prefix}: proposal requires an accepted immutable support review")
    review_ref = (ledger.get("independent_check") or {}).get("statement_support_review")
    if not errors and isinstance(review_ref, dict):
        record, record_errors = load_json_object(root / review_ref["artifact"], "statement-support review")
        errors.extend(record_errors)
        payload = {key: value for key, value in change.items() if key != "verification_status"}
        matches = [row for row in (record.get("response") or {}).get("change_assessments", [])
                   if isinstance(row, dict) and row.get("issue_id") == issue.get("id") and row.get("change_index") == index
                   and row.get("sha256") == canonical_sha256(payload) and row.get("assessment") == "accepted"]
        if len(matches) != 1:
            errors.append(f"{prefix}: accepted proof support alone does not verify this exact proposed edit")
    return errors


def validate_conclusion_records(
    obligation: dict[str, Any],
    ledger_path: Path,
    final: bool,
    errors: list[str],
) -> list[dict[str, Any]]:
    value = obligation.get("conclusions")
    if value is None and not final:
        return []
    if not isinstance(value, list):
        errors.append("obligation.conclusions must be an ordered list")
        return []
    if final and not value:
        errors.append("obligation.conclusions must contain at least one conclusion")
    statement_metadata = [
        metadata
        for span in obligation.get("statement_spans", [])
        if (metadata := resolved_span_metadata(span, ledger_path.parent)) is not None
    ] if isinstance(obligation.get("statement_spans"), list) else []
    seen: set[str] = set()
    records: list[dict[str, Any]] = []
    for index, record in enumerate(value, 1):
        prefix = f"obligation.conclusions[{index}]"
        if not isinstance(record, dict):
            errors.append(f"{prefix} must be an object")
            continue
        conclusion_id = record.get("id")
        if (
            not isinstance(conclusion_id, str)
            or not CONCLUSION_ID_RE.fullmatch(conclusion_id)
        ):
            errors.append(f"{prefix}.id must match C001")
        elif conclusion_id in seen:
            errors.append(f"duplicate conclusion id {conclusion_id}")
        else:
            seen.add(conclusion_id)
        claim = record.get("claim")
        if not is_substantive_string(claim):
            errors.append(f"{prefix}.claim must be substantive")
        if "reader_description" in record:
            description = record["reader_description"]
            if (not is_substantive_string(description) or len(description) > 120
                    or any(char in description for char in "\r\n")):
                errors.append(f"{prefix}.reader_description must be substantive single-line text of at most 120 characters")
        spans = record.get("source_spans")
        if not isinstance(spans, list) or (final and not spans):
            errors.append(f"{prefix}.source_spans must be a nonempty list")
            spans = []
        for span_index, span in enumerate(spans, 1):
            validate_locked_span(
                span,
                ledger_path.parent,
                f"{prefix}.source_spans[{span_index}]",
                errors,
            )
            metadata = resolved_span_metadata(span, ledger_path.parent)
            if metadata is not None and statement_metadata and not any(
                Path(parent["file"]).resolve() == Path(metadata["file"]).resolve()
                and parent["start_line"] <= metadata["start_line"]
                and metadata["end_line"] <= parent["end_line"]
                for parent in statement_metadata
            ):
                errors.append(
                    f"{prefix}.source_spans[{span_index}] is outside the locked "
                    "statement spans"
                )
        pointers = record.get("applies_under")
        if not isinstance(pointers, list) or not all(
            is_nonempty_string(pointer) for pointer in pointers
        ):
            errors.append(f"{prefix}.applies_under must be a JSON Pointer list")
            pointers = []
        if len(pointers) != len(set(pointers)):
            errors.append(f"{prefix}.applies_under contains duplicates")
        for pointer in pointers:
            root_name = (
                pointer[1:].split("/", 1)[0]
                if isinstance(pointer, str) and pointer.startswith("/")
                else ""
            )
            found, resolved = resolve_json_pointer(obligation, pointer)
            if (
                root_name not in OBLIGATION_PREMISE_ROOTS
                or not found
                or isinstance(resolved, (list, dict))
                or resolved in (None, "")
            ):
                errors.append(
                    f"{prefix}.applies_under has unresolved scalar pointer {pointer}"
                )
        normalization = record.get("normalization")
        if not isinstance(normalization, dict):
            errors.append(f"{prefix}.normalization must be an object")
        else:
            if not is_enum_value(
                normalization.get("status"), {"checked", "unclear"}
            ):
                errors.append(f"{prefix}.normalization.status is invalid")
            if not is_substantive_string(normalization.get("evidence")):
                errors.append(
                    f"{prefix}.normalization.evidence must be substantive"
                )
        records.append(record)
    if (
        final
        and len(records) == 1
        and is_substantive_string(records[0].get("claim"))
        and obligation.get("conclusion") != records[0].get("claim")
    ):
        errors.append(
            "For one conclusion, obligation.conclusion must exactly match "
            "obligation.conclusions[1].claim"
        )
    return records


def validate_obligation(
    obligation: Any, ledger_path: Path, final: bool, errors: list[str]
) -> dict[str, str]:
    if not isinstance(obligation, dict):
        errors.append("obligation must be an object")
        return {}

    spans = obligation.get("statement_spans")
    if not isinstance(spans, list):
        errors.append("obligation.statement_spans must be a list")
        spans = []
    if final and not spans:
        errors.append("obligation.statement_spans must identify the exact theorem statement")
    for index, span in enumerate(spans, 1):
        validate_locked_span(
            span,
            ledger_path.parent,
            f"obligation.statement_spans[{index}]",
            errors,
        )

    variables = obligation.get("quantified_variables")
    if not isinstance(variables, list):
        errors.append("obligation.quantified_variables must be an ordered list")
    else:
        seen_symbols: set[str] = set()
        for index, variable in enumerate(variables, 1):
            prefix = f"obligation.quantified_variables[{index}]"
            if not isinstance(variable, dict):
                errors.append(f"{prefix} must be an object")
                continue
            for field in ("symbol", "type", "domain"):
                field_value = variable.get(field)
                if not is_nonempty_string(field_value):
                    errors.append(f"{prefix}.{field} must be a nonempty string")
                elif final and is_explicit_absence(field_value):
                    errors.append(
                        f"{prefix}.{field} cannot use an absence marker"
                    )
                elif final and is_forbidden_contract_placeholder(field_value):
                    errors.append(
                        f"{prefix}.{field} cannot use an unresolved placeholder"
                    )
            symbol = variable.get("symbol")
            if is_nonempty_string(symbol):
                if symbol in seen_symbols:
                    errors.append(f"duplicate quantified variable symbol {symbol}")
                seen_symbols.add(symbol)
            if (
                final or "quantifier" in variable
            ) and not is_enum_value(variable.get("quantifier"), QUANTIFIER_KINDS):
                errors.append(
                    f"{prefix}.quantifier must be one of {sorted(QUANTIFIER_KINDS)}"
                )

    contexts = obligation.get("context_spans")
    if not isinstance(contexts, list):
        errors.append("obligation.context_spans must be a list")
        contexts = []
    for index, span in enumerate(contexts, 1):
        validate_locked_span(
            span,
            ledger_path.parent,
            f"obligation.context_spans[{index}]",
            errors,
            require_role=True,
        )

    validate_conclusion_records(obligation, ledger_path, final, errors)

    if not final and "normalization_checks" not in obligation:
        normalization: dict[str, str] = {}
    else:
        normalization = validate_aspect_matrix(
            obligation.get("normalization_checks"),
            "obligation.normalization_checks",
            NORMALIZATION_ASPECTS,
            NORMALIZATION_STATUSES,
            final,
            errors,
        )

    if not final:
        return normalization
    for field in ("quantifier_scope", "probability_model", "conclusion"):
        field_value = obligation.get(field)
        if not is_nonempty_string(field_value):
            errors.append(f"obligation.{field} must be a nonempty string")
        elif is_forbidden_contract_placeholder(field_value):
            errors.append(
                f"obligation.{field} cannot use an unresolved placeholder"
            )
    for field in ("quantifier_scope", "conclusion"):
        if is_explicit_absence(obligation.get(field)):
            errors.append(f"obligation.{field} cannot use an absence marker")
    for field in ("hypotheses", "definitions", "constant_dependencies"):
        values = validate_string_list(
            obligation.get(field), f"obligation.{field}", errors
        )
        for index, item in enumerate(values, 1):
            if is_forbidden_contract_placeholder(item):
                errors.append(
                    f"obligation.{field}[{index}] cannot use an unresolved "
                    "placeholder"
                )
            if (
                is_explicit_absence(item)
                and normalization.get(field) != "not_applicable"
            ):
                errors.append(
                    f"obligation.{field}[{index}] cannot use an absence marker "
                    "unless the field is not_applicable"
                )
    if not is_enum_value(obligation.get("uniformity"), {
        "pointwise",
        "uniform",
        "mixed",
        "not_applicable",
        "unclear",
    }):
        errors.append(
            "obligation.uniformity has an invalid or missing value; expected one of "
            "pointwise, uniform, mixed, not_applicable, unclear"
        )
    if not is_enum_value(obligation.get("regime"), {
        "finite_sample",
        "asymptotic",
        "both",
        "not_applicable",
        "unclear",
    }):
        errors.append(
            "obligation.regime has an invalid or missing value; expected one of "
            "finite_sample, asymptotic, both, not_applicable, unclear"
        )
    for aspect in ("uniformity", "regime"):
        if (
            obligation.get(aspect) == "unclear"
            and normalization.get(aspect) != "unclear"
        ):
            errors.append(
                f"obligation.{aspect} is unclear but its normalization check is not"
            )
    for aspect in ("quantifiers_and_domains", "conclusion"):
        if normalization.get(aspect) == "not_applicable":
            errors.append(
                f"obligation.normalization_checks[{aspect}] cannot be "
                "not_applicable"
            )

    normalization_fields = {
        "probability_model": "probability_model",
        "hypotheses": "hypotheses",
        "definitions": "definitions",
        "uniformity": "uniformity",
        "regime": "regime",
        "constant_dependencies": "constant_dependencies",
    }
    for aspect, field in normalization_fields.items():
        normalization_status = normalization.get(aspect)
        field_is_absent = is_explicit_absence(obligation.get(field))
        if normalization_status == "not_applicable" and not field_is_absent:
            errors.append(
                f"obligation.normalization_checks[{aspect}] is not_applicable "
                f"but obligation.{field} is substantive"
            )
        elif normalization_status != "not_applicable" and field_is_absent:
            errors.append(
                f"obligation.normalization_checks[{aspect}] is "
                f"{normalization_status!r} but obligation.{field} records only "
                "absence"
            )

    unclear_fields = {
        "quantifier_scope": "quantifiers_and_domains",
        "probability_model": "probability_model",
        "conclusion": "conclusion",
        "uniformity": "uniformity",
        "regime": "regime",
    }
    for field, aspect in unclear_fields.items():
        field_value = obligation.get(field)
        if (
            isinstance(field_value, str)
            and field_value.strip().lower() == "unclear"
            and normalization.get(aspect) != "unclear"
        ):
            errors.append(
                f"obligation.{field} is unclear but its normalization check is not"
            )
    for field in ("hypotheses", "definitions", "constant_dependencies"):
        values = obligation.get(field)
        if (
            isinstance(values, list)
            and any(
                isinstance(item, str) and item.strip().lower() == "unclear"
                for item in values
            )
            and normalization.get(field) != "unclear"
        ):
            errors.append(
                f"obligation.{field} contains an unclear item but its "
                "normalization check is not"
            )
    if isinstance(variables, list):
        variable_is_unclear = any(
            isinstance(variable, dict)
            and any(
                isinstance(variable.get(field), str)
                and variable[field].strip().lower() == "unclear"
                for field in ("symbol", "type", "domain", "quantifier")
            )
            for variable in variables
        )
        if (
            variable_is_unclear
            and normalization.get("quantifiers_and_domains") != "unclear"
        ):
            errors.append(
                "obligation.quantified_variables contains an unclear item but its "
                "normalization check is not"
            )
    return normalization


def validate_dependency_record(
    dependency: Any,
    prefix: str,
    final: bool,
    errors: list[str],
) -> dict[str, Any] | None:
    if not isinstance(dependency, dict):
        errors.append(f"{prefix} must be an object")
        return None
    dependency_id = dependency.get("id")
    kind = dependency.get("kind")
    status = dependency.get("status")
    if not is_nonempty_string(dependency_id):
        errors.append(f"{prefix}.id must be a nonempty string")
    if not is_enum_value(kind, DEPENDENCY_KINDS):
        errors.append(f"{prefix}.kind must be one of {sorted(DEPENDENCY_KINDS)}")
    if not is_enum_value(status, DEPENDENCY_STATUSES):
        errors.append(f"{prefix}.status is invalid: {status!r}")
    use_id = dependency.get("use_id")
    if is_enum_value(kind, {"internal_result", "external_result"}):
        if (
            not isinstance(use_id, str)
            or not DEPENDENCY_USE_ID_RE.fullmatch(use_id)
        ):
            errors.append(f"{prefix}.use_id must match D001 for a result use")
    elif kind == "step" and use_id is not None:
        errors.append(f"{prefix}.use_id is not allowed for a step dependency")
    if kind == "internal_result":
        conclusion_id = dependency.get("conclusion_id")
        if (
            not isinstance(conclusion_id, str)
            or not CONCLUSION_ID_RE.fullmatch(conclusion_id)
        ):
            errors.append(
                f"{prefix}.conclusion_id must identify the exact dependency "
                "conclusion"
            )
    if "statement_support_sha256" in dependency:
        if kind != "internal_result" or not isinstance(dependency["statement_support_sha256"], str) or not SHA256_RE.fullmatch(dependency["statement_support_sha256"]):
            errors.append(f"{prefix}.statement_support_sha256 requires an exact internal supplemental support digest")
    elif kind == "external_result" and dependency.get("conclusion_id") is not None:
        errors.append(
            f"{prefix}.conclusion_id is reserved for internal result conclusions"
        )
    if final and is_enum_value(kind, DEPENDENCY_KINDS):
        if not is_substantive_string(dependency.get("needed_form")):
            errors.append(
                f"{prefix}.needed_form must state the exact form used and cannot "
                "be a reserved placeholder"
            )
        if not is_substantive_string(dependency.get("compatibility_check")):
            errors.append(
                f"{prefix}.compatibility_check must map the result to this use "
                "and cannot be a reserved placeholder"
            )
    return dependency


def validate_independent_check(
    value: Any,
    final: bool,
    errors: list[str],
    *,
    primary_ledger_sha256: str | None = None,
    current_contract: bool = True,
) -> dict[str, Any]:
    if not isinstance(value, dict):
        errors.append("independent_check must be an object")
        return {}
    if not isinstance(value.get("required"), bool):
        errors.append("independent_check.required must be true or false")
    if not is_enum_value(value.get("status"), INDEPENDENT_CHECK_STATUSES):
        errors.append("independent_check.status is invalid")
    if not is_enum_value(value.get("independence_level"), INDEPENDENCE_LEVELS):
        errors.append("independent_check.independence_level is invalid")
    if not is_enum_value(value.get("challenger_verdict"), UNIT_STATUSES):
        errors.append("independent_check.challenger_verdict is invalid")
    reconciled_verdict = value.get("reconciled_verdict")
    if not is_enum_value(reconciled_verdict, UNIT_STATUSES):
        errors.append("independent_check.reconciled_verdict is invalid")
    disagreements = value.get("disagreements")
    if not isinstance(disagreements, list) or not all(
        is_substantive_string(item) for item in disagreements
    ):
        errors.append("independent_check.disagreements must contain substantive strings")
    covered_issue_ids = value.get("covered_issue_ids")
    if current_contract:
        if not isinstance(covered_issue_ids, list) or not all(
            isinstance(issue_id, str) and ISSUE_ID_RE.fullmatch(issue_id)
            for issue_id in covered_issue_ids
        ):
            errors.append(
                "independent_check.covered_issue_ids must contain canonical issue IDs"
            )
            covered_issue_ids = []
        elif len(covered_issue_ids) != len(set(covered_issue_ids)):
            errors.append("independent_check.covered_issue_ids contains duplicates")
    issue_assessments = value.get("issue_assessments")
    assessment_ids: list[str] = []
    if issue_assessments is None and not current_contract:
        issue_assessments = []
    elif not isinstance(issue_assessments, list):
        errors.append("independent_check.issue_assessments must be a list")
        issue_assessments = []
    for index, assessment in enumerate(issue_assessments, 1):
        prefix = f"independent_check.issue_assessments[{index}]"
        if not isinstance(assessment, dict):
            errors.append(f"{prefix} must be an object")
            continue
        expected_fields = {
            "issue_id",
            "target_contract_sha256",
            "assessment",
            "target_assessment",
            "downstream_assessment",
        }
        missing = expected_fields - set(assessment)
        unknown = set(assessment) - expected_fields
        if missing:
            errors.append(
                f"{prefix} is missing fields: {', '.join(sorted(missing))}"
            )
        if unknown:
            errors.append(
                f"{prefix} has unknown fields: {', '.join(sorted(unknown))}"
            )
        issue_id = assessment.get("issue_id")
        if not isinstance(issue_id, str) or not ISSUE_ID_RE.fullmatch(issue_id):
            errors.append(f"{prefix}.issue_id must be canonical")
        else:
            assessment_ids.append(issue_id)
        digest = assessment.get("target_contract_sha256")
        if not isinstance(digest, str) or not SHA256_RE.fullmatch(digest):
            errors.append(
                f"{prefix}.target_contract_sha256 must be a SHA-256 digest"
            )
        if assessment.get("assessment") not in {
            "confirmed",
            "not_confirmed",
            "unclear",
        }:
            errors.append(f"{prefix}.assessment is invalid")
        for field in ("target_assessment", "downstream_assessment"):
            if not is_substantive_string(assessment.get(field)):
                errors.append(f"{prefix}.{field} must be substantive")
    if len(assessment_ids) != len(set(assessment_ids)):
        errors.append(
            "independent_check.issue_assessments contains duplicate issue IDs"
        )
    if final and value.get("required"):
        if not is_enum_value(value.get("status"), {"agreed", "resolved"}):
            errors.append("required independent check must be agreed or resolved")
        if not is_enum_value(
            value.get("independence_level"), INDEPENDENCE_LEVELS - {"none"}
        ):
            errors.append("required independent check needs a genuine independence level")
        if not is_substantive_string(value.get("artifact")):
            errors.append("required independent check needs an artifact reference")
        elif challenge_artifact_reference_parts(value.get("artifact")) is None:
            errors.append(
                "required independent check artifact must be a portable "
                "audit-relative path under audit/05_adversarial"
            )
        if value.get("challenger_verdict") == "not_checked":
            errors.append("required independent check needs a checked challenger verdict")
        if value.get("reconciled_verdict") == "not_checked":
            errors.append("required independent check needs a reconciled verdict")
        if value.get("status") == "agreed":
            if disagreements:
                errors.append("agreed independent check must have no disagreements")
            if value.get("resolution") != "":
                errors.append("agreed independent check must have an empty resolution")
            if value.get("challenger_verdict") != reconciled_verdict:
                errors.append(
                    "agreed independent check requires identical challenger and "
                    "reconciled verdicts"
                )
        if value.get("status") == "resolved":
            if not disagreements:
                errors.append(
                    "resolved independent check must record at least one substantive "
                    "disagreement"
                )
            if not is_substantive_string(value.get("resolution")):
                errors.append(
                    "resolved independent disagreement needs a resolution record"
                )
        if current_contract:
            for field in (
                "source_snapshot_sha256",
                "challenged_ledger_sha256",
                "challenge_context_sha256",
                "challenge_artifact_sha256",
            ):
                if not isinstance(value.get(field), str) or not SHA256_RE.fullmatch(
                    value[field]
                ):
                    errors.append(f"required independent check needs valid {field}")
            if (
                primary_ledger_sha256 is not None
                and value.get("challenged_ledger_sha256") != primary_ledger_sha256
            ):
                errors.append(
                    "independent_check.challenged_ledger_sha256 is stale relative "
                    "to the primary ledger evidence"
                )
            if not is_utc_timestamp(value.get("generated_utc")):
                errors.append("required independent check needs a valid generated_utc")
            if sorted(assessment_ids) != sorted(covered_issue_ids):
                errors.append(
                    "independent_check.issue_assessments must cover exactly "
                    "covered_issue_ids"
                )
    elif final and issue_assessments:
        errors.append(
            "non-required independent check cannot contain issue assessments"
        )
    return value


def prior_step_establishes_statement_label(
    ledger: dict[str, Any] | None,
    ledger_dir: Path,
    step_id: str,
    claim: str | None,
    move_id: str | None,
    label: str,
) -> bool:
    """Resolve a statement label through its recorded earlier proof support."""
    if ledger is None or not is_nonempty_string(claim) or not is_nonempty_string(move_id):
        return False
    obligation = ledger.get("obligation")
    review = ledger.get("review")
    if not isinstance(obligation, dict) or not isinstance(review, dict):
        return False
    conclusions = obligation.get("conclusions")
    results = review.get("conclusion_results")
    statement_spans = obligation.get("statement_spans")
    if not all(isinstance(rows, list) for rows in (conclusions, results, statement_spans)):
        return False
    statement_metadata = [
        metadata for span in statement_spans
        if (metadata := resolved_span_metadata(span, ledger_dir)) is not None
    ]
    for conclusion in conclusions:
        if not isinstance(conclusion, dict) or conclusion.get("claim") != claim:
            continue
        matching_results = [
            result for result in results
            if isinstance(result, dict)
            and result.get("conclusion_id") == conclusion.get("id")
        ]
        if len(matching_results) != 1:
            continue
        support = matching_results[0].get("support")
        if not isinstance(support, dict) or (
            support.get("step_id") != step_id or support.get("move_id") != move_id
        ):
            continue
        spans = conclusion.get("source_spans")
        if not isinstance(spans, list):
            continue
        for span in spans:
            metadata = resolved_span_metadata(span, ledger_dir)
            if metadata is None or not any(
                Path(parent["file"]) == Path(metadata["file"])
                and parent["start_line"] <= metadata["start_line"]
                and metadata["end_line"] <= parent["end_line"]
                for parent in statement_metadata
            ):
                continue
            span_errors: list[str] = []
            validate_locked_span(span, ledger_dir, "statement conclusion", span_errors)
            if not span_errors and locked_span_contains_label(span, ledger_dir, label):
                return True
    return False


def validate_premise_uses(
    value: Any,
    prefix: str,
    obligation: Any,
    ledger_dir: Path,
    dependencies_by_id: dict[str, dict[str, Any]],
    prior_step_statuses: dict[str, str],
    prior_step_kinds: dict[str, str],
    prior_step_claims: dict[str, str],
    prior_step_ranges: dict[str, tuple[int, int]],
    prior_step_conclusion_moves: dict[str, str | None],
    source_path: Path,
    final: bool,
    errors: list[str],
    source_ledger: dict[str, Any] | None = None,
) -> tuple[dict[str, dict[str, Any]], set[str]]:
    if value is None and not final:
        return {}, set()
    if not isinstance(value, list):
        errors.append(f"{prefix}.premise_uses must be a list")
        return {}, set()

    premises: dict[str, dict[str, Any]] = {}
    used_dependencies: set[str] = set()
    for index, premise in enumerate(value, 1):
        item_prefix = f"{prefix}.premise_uses[{index}]"
        if not isinstance(premise, dict):
            errors.append(f"{item_prefix} must be an object")
            continue
        premise_id = premise.get("id")
        if not isinstance(premise_id, str) or not PREMISE_ID_RE.fullmatch(premise_id):
            errors.append(f"{item_prefix}.id must match P001")
            continue
        if premise_id in premises:
            errors.append(f"{prefix}: duplicate premise id {premise_id}")
            continue
        premises[premise_id] = premise
        if not is_enum_value(premise.get("role"), PREMISE_ROLES):
            errors.append(f"{item_prefix}.role is invalid")
        if not is_substantive_string(premise.get("claim")):
            errors.append(
                f"{item_prefix}.claim must be a nonempty string and cannot be a "
                "reserved placeholder"
            )
        if not is_substantive_string(premise.get("evidence")):
            errors.append(
                f"{item_prefix}.evidence must be a nonempty string and cannot be "
                "a reserved placeholder"
            )
        source_reference_id = premise.get("source_reference_id")
        source_occurrence_id = premise.get("source_reference_occurrence_id")
        if (
            "source_reference_id" in premise
            and not is_nonempty_string(source_reference_id)
        ):
            errors.append(f"{item_prefix}.source_reference_id must be nonempty")
        if (
            "source_reference_occurrence_id" in premise
            and not is_nonempty_string(source_occurrence_id)
        ):
            errors.append(
                f"{item_prefix}.source_reference_occurrence_id must be nonempty"
            )
        if final and bool(is_nonempty_string(source_reference_id)) != bool(
            is_nonempty_string(source_occurrence_id)
        ):
            errors.append(
                f"{item_prefix} source reference anchoring requires both target "
                "and occurrence IDs"
            )

        origin = premise.get("origin")
        if not isinstance(origin, dict):
            errors.append(f"{item_prefix}.origin must be an object")
            continue
        kind = origin.get("kind")
        reference = origin.get("reference")
        if not is_enum_value(kind, PREMISE_ORIGIN_KINDS):
            errors.append(f"{item_prefix}.origin.kind is invalid")
            continue
        if not is_nonempty_string(reference):
            errors.append(f"{item_prefix}.origin.reference must be a nonempty string")
            continue

        if is_nonempty_string(source_reference_id) and kind not in {
            "obligation",
            "prior_step",
            "internal_result",
        }:
            errors.append(
                f"{item_prefix}.source_reference_id requires an obligation, "
                "prior-step, or internal-result origin with an exact anchor"
            )

        if kind == "obligation":
            root_name = reference[1:].split("/", 1)[0] if reference.startswith("/") else ""
            found, resolved = resolve_json_pointer(obligation, reference)
            if root_name not in OBLIGATION_PREMISE_ROOTS or not found:
                errors.append(
                    f"{item_prefix} has unresolved obligation premise {reference}"
                )
            elif isinstance(resolved, (list, dict)) or resolved in (None, ""):
                errors.append(
                    f"{item_prefix} obligation premise must resolve to one concrete item"
                )
            elif isinstance(resolved, str) and (
                is_explicit_absence(resolved)
                or resolved.strip().lower() == "unclear"
            ):
                errors.append(
                    f"{item_prefix} cannot use an absence or unresolved marker "
                    "as a premise"
                )
            elif isinstance(resolved, str) and premise.get("claim") != resolved:
                errors.append(
                    f"{item_prefix}.claim must exactly match its string-valued "
                    "obligation premise; "
                    + exact_mismatch_detail(resolved, premise.get("claim"))
                )

            anchor = origin.get("anchor")
            if not isinstance(anchor, dict):
                errors.append(f"{item_prefix}.origin.anchor must be an object")
                continue
            anchor_kind = anchor.get("kind")
            anchor_index = anchor.get("index")
            anchor_field = (
                {
                    "statement_span": "statement_spans",
                    "context_span": "context_spans",
                }.get(anchor_kind)
                if isinstance(anchor_kind, str)
                else None
            )
            if anchor_field is None or not is_int(anchor_index) or anchor_index < 1:
                errors.append(
                    f"{item_prefix}.origin.anchor needs statement_span or "
                    "context_span and a one-based index"
                )
                continue
            anchor_values = (
                obligation.get(anchor_field, []) if isinstance(obligation, dict) else []
            )
            if not isinstance(anchor_values, list) or anchor_index > len(anchor_values):
                errors.append(f"{item_prefix}.origin.anchor is out of range")
            elif (
                is_nonempty_string(source_reference_id)
                and not locked_span_contains_label(
                    anchor_values[anchor_index - 1],
                    ledger_dir,
                    source_reference_id,
                )
            ):
                errors.append(
                    f"{item_prefix}.source_reference_id {source_reference_id} "
                    "is not contained in its locked anchor"
                )
        elif kind == "prior_step":
            dependency = dependencies_by_id.get(reference)
            if dependency is None or dependency.get("kind") != "step":
                errors.append(
                    f"{item_prefix} premise step {reference} is not declared "
                    "by this step"
                )
            else:
                used_dependencies.add(reference)
                if final and premise.get("claim") != dependency.get("needed_form"):
                    errors.append(
                        f"{item_prefix}.claim must exactly match dependency "
                        f"{reference} needed_form; "
                        + exact_mismatch_detail(
                            dependency.get("needed_form"), premise.get("claim")
                        )
                    )
                prior_claim = prior_step_claims.get(reference)
                if final and not is_nonempty_string(prior_claim):
                    errors.append(
                        f"{item_prefix} premise step {reference} has no exact "
                        "prior claim"
                    )
                elif final and dependency.get("needed_form") != prior_claim:
                    errors.append(
                        f"{item_prefix} dependency {reference} needed_form must "
                        "exactly match the prior step restatement; "
                        + exact_mismatch_detail(
                            prior_claim, dependency.get("needed_form")
                        )
                    )
            if reference not in prior_step_statuses:
                errors.append(
                    f"{item_prefix} premise step {reference} is not established "
                    "before use"
                )
            elif prior_step_statuses[reference] == "non_substantive":
                errors.append(
                    f"{item_prefix} cannot use non_substantive step {reference} "
                    "as a premise"
                )
            elif prior_step_kinds.get(reference) == "statement":
                errors.append(
                    f"{item_prefix} cannot use the theorem statement step "
                    f"{reference} as a premise"
                )
            elif final and not is_nonempty_string(
                prior_step_conclusion_moves.get(reference)
            ):
                errors.append(
                    f"{item_prefix} cannot use non-inferential or unsupported step "
                    f"{reference} as a factual premise; link the normalized premise "
                    "or record an introduction inference in that step"
                )
            if is_nonempty_string(source_reference_id):
                prior_range = prior_step_ranges.get(reference)
                label_in_prior_step = prior_range is not None and locked_span_contains_label(
                    source_unit_location(source_ledger, {"lines": list(prior_range)}) if source_ledger is not None else {
                        "file": relative_or_absolute(source_path, ledger_dir),
                        "start_line": prior_range[0],
                        "end_line": prior_range[1],
                    },
                    ledger_dir,
                    source_reference_id,
                )
                if not label_in_prior_step and not prior_step_establishes_statement_label(
                    source_ledger,
                    ledger_dir,
                    reference,
                    prior_step_claims.get(reference),
                    prior_step_conclusion_moves.get(reference),
                    source_reference_id,
                ):
                    errors.append(
                        f"{item_prefix}.source_reference_id {source_reference_id} "
                        f"is not active inside earlier step {reference} "
                        "or a statement conclusion it establishes"
                    )
        else:
            dependency = dependencies_by_id.get(reference)
            if dependency is None or dependency.get("kind") != kind:
                errors.append(
                    f"{item_prefix} premise dependency {reference} is not declared "
                    "by this step"
                )
            else:
                used_dependencies.add(reference)
                if final and premise.get("claim") != dependency.get("needed_form"):
                    errors.append(
                        f"{item_prefix}.claim must exactly match dependency "
                        f"{reference} needed_form; "
                        + exact_mismatch_detail(
                            dependency.get("needed_form"), premise.get("claim")
                        )
                    )

    return premises, used_dependencies


def validate_inference_record(
    value: Any,
    prefix: str,
    restatement: Any,
    premises: dict[str, dict[str, Any]],
    atomicity_status: Any,
    step_status: Any,
    step_issue_ids: set[str],
    covered_lines: list[int],
    one_move_contract: bool,
    final: bool,
    errors: list[str],
) -> tuple[dict[str, int], set[str], set[str]]:
    if value is None and not final:
        return {}, set(), set()
    if not isinstance(value, dict):
        errors.append(f"{prefix}.inference must be an object")
        return {}, set(), set()
    moves = value.get("moves")
    if not isinstance(moves, list):
        errors.append(f"{prefix}.inference.moves must be a list")
        moves = []

    move_ids: dict[str, int] = {}
    failed_move_ids: set[str] = set()
    ordered_move_ids: list[str] = []
    used_premises: set[str] = set()
    for index, move in enumerate(moves, 1):
        move_prefix = f"{prefix}.inference.moves[{index}]"
        if not isinstance(move, dict):
            errors.append(f"{move_prefix} must be an object")
            continue
        move_id = move.get("id")
        if not isinstance(move_id, str) or not MOVE_ID_RE.fullmatch(move_id):
            errors.append(f"{move_prefix}.id must match M001")
            continue
        if move_id in move_ids:
            errors.append(f"{prefix}: duplicate inference move id {move_id}")
            continue
        move_ids[move_id] = index
        ordered_move_ids.append(move_id)
        if (
            final
            and atomicity_status == "source_indivisible_chain"
            and len(covered_lines) > 1
        ):
            source_range = move.get("source_line_range")
            if (
                not isinstance(source_range, list)
                or len(source_range) != 2
                or not all(is_int(item) for item in source_range)
            ):
                errors.append(
                    f"{move_prefix}.source_line_range must be [start, end] "
                    "for a multiline indivisible source unit"
                )
            elif (
                source_range[0] > source_range[1]
                or source_range[0] < covered_lines[0]
                or source_range[1] > covered_lines[-1]
            ):
                errors.append(
                    f"{move_prefix}.source_line_range lies outside the step"
                )
        for field in ("claim", "rule", "justification"):
            if not is_substantive_string(move.get(field)):
                errors.append(
                    f"{move_prefix}.{field} must be a nonempty string and cannot "
                    "be a reserved placeholder"
                )

        failure = move.get("failure")
        failure_supports_zero_input = False
        if failure is not None:
            failed_move_ids.add(move_id)
            if not is_enum_value(step_status, FAILED_STEP_STATUSES):
                errors.append(
                    f"{move_prefix}.failure is allowed only on a failed or "
                    "unclear step"
                )
            if not isinstance(failure, dict):
                errors.append(f"{move_prefix}.failure must be an object")
            else:
                failure_kind = failure.get("kind")
                failure_issue_id = failure.get("issue_id")
                failure_evidence = failure.get("evidence")
                valid_failure_kind = (
                    isinstance(failure_kind, str)
                    and failure_kind in MOVE_FAILURE_KINDS
                )
                if not valid_failure_kind:
                    errors.append(f"{move_prefix}.failure.kind is invalid")
                elif step_status != MOVE_FAILURE_STEP_STATUSES[failure_kind]:
                    errors.append(
                        f"{move_prefix}.failure.kind {failure_kind} requires "
                        f"step status {MOVE_FAILURE_STEP_STATUSES[failure_kind]}"
                    )
                valid_failure_issue = (
                    isinstance(failure_issue_id, str)
                    and bool(ISSUE_ID_RE.fullmatch(failure_issue_id))
                    and failure_issue_id in step_issue_ids
                )
                if not valid_failure_issue:
                    errors.append(
                        f"{move_prefix}.failure.issue_id must reference a "
                        "step issue_id"
                    )
                if not is_substantive_string(failure_evidence):
                    errors.append(
                        f"{move_prefix}.failure.evidence must be nonempty and substantive"
                    )
                computation = failure.get("computation")
                if computation is not None:
                    errors.extend(
                        failure_computation_shape_errors(
                            computation, f"{move_prefix}.failure.computation"
                        )
                    )
                elif (
                    final
                    and one_move_contract
                    and valid_failure_kind
                    and failure_kind in REFUTATION_FAILURE_KINDS
                ):
                    errors.append(
                        f"{move_prefix}.failure.computation is required for a "
                        f"{failure_kind} failure: instantiate the failure "
                        "numerically as a hash-locked script under "
                        "audit/05_adversarial, or record status "
                        "not_instantiable with a substantive reason"
                    )
                failure_supports_zero_input = (
                    valid_failure_kind
                    and failure_kind in ZERO_INPUT_FAILURE_KINDS
                    and step_status == MOVE_FAILURE_STEP_STATUSES[failure_kind]
                    and valid_failure_issue
                    and is_substantive_string(failure_evidence)
                )

        premise_ids = move.get("premise_ids")
        if not isinstance(premise_ids, list) or not all(
            isinstance(item, str) for item in premise_ids
        ):
            errors.append(f"{move_prefix}.premise_ids must be a list of premise IDs")
            premise_ids = []
        if len(premise_ids) != len(set(premise_ids)):
            errors.append(f"{move_prefix}.premise_ids contains duplicates")
        for premise_id in premise_ids:
            if premise_id not in premises:
                errors.append(f"{move_prefix} uses unknown premise {premise_id}")
            else:
                used_premises.add(premise_id)

        prior_move_ids = move.get("prior_move_ids")
        if not isinstance(prior_move_ids, list) or not all(
            isinstance(item, str) for item in prior_move_ids
        ):
            errors.append(
                f"{move_prefix}.prior_move_ids must be a list of earlier move IDs"
            )
            prior_move_ids = []
        if len(prior_move_ids) != len(set(prior_move_ids)):
            errors.append(f"{move_prefix}.prior_move_ids contains duplicates")
        for prior_id in prior_move_ids:
            if prior_id not in set(ordered_move_ids[:-1]):
                errors.append(
                    f"{move_prefix} inference move {prior_id} is not established "
                    "before use"
                )
        if final and not premise_ids and not prior_move_ids:
            if is_enum_value(step_status, FAILED_STEP_STATUSES):
                if not failure_supports_zero_input:
                    errors.append(
                        f"{move_prefix} zero-input failed move requires a "
                        "zero-input-compatible failure kind, evidence, and "
                        "step issue link"
                    )
            else:
                errors.append(
                    f"{move_prefix} must use at least one premise or earlier move"
                )

    conclusion_move = value.get("conclusion_move")
    if atomicity_status == "non_inferential":
        if moves:
            errors.append(f"{prefix}: non_inferential step cannot contain inference moves")
        if premises:
            errors.append(f"{prefix}: non_inferential step cannot declare premise uses")
        if conclusion_move is not None:
            errors.append(f"{prefix}: non_inferential step needs null conclusion_move")
    else:
        if one_move_contract and len(moves) != 1:
            errors.append(
                f"{prefix}: schema-5 inferential step must contain exactly one move"
            )
        elif atomicity_status == "single_move" and len(moves) != 1:
            errors.append(f"{prefix}: single_move step must contain exactly one move")
        if atomicity_status == "source_indivisible_chain" and len(moves) < 2:
            errors.append(
                f"{prefix}: source_indivisible_chain must contain at least two moves"
            )
        if (
            atomicity_status == "source_indivisible_chain"
            and len(covered_lines) > 1
            and moves
        ):
            ranges = [
                move.get("source_line_range")
                for move in moves
                if isinstance(move, dict)
                and isinstance(move.get("source_line_range"), list)
                and len(move["source_line_range"]) == 2
                and all(is_int(item) for item in move["source_line_range"])
            ]
            if len(ranges) == len(moves):
                if any(
                    current[0] < previous[0] or current[1] < previous[1]
                    for previous, current in zip(ranges, ranges[1:])
                ):
                    errors.append(
                        f"{prefix}: source_line_range records must follow source order"
                    )
                represented = {
                    line
                    for source_range in ranges
                    for line in range(source_range[0], source_range[1] + 1)
                }
                if represented != set(covered_lines):
                    errors.append(
                        f"{prefix}: multiline indivisible moves do not represent "
                        "every covered source line"
                    )
        if ordered_move_ids:
            if conclusion_move != ordered_move_ids[-1]:
                errors.append(
                    f"{prefix}.inference.conclusion_move must be the final move"
                )
            final_move = moves[-1] if isinstance(moves[-1], dict) else {}
            if final_move.get("claim") != restatement:
                errors.append(
                    f"{prefix}: final inference claim must exactly match restatement; "
                    + exact_mismatch_detail(restatement, final_move.get("claim"))
                )
        elif final:
            errors.append(f"{prefix}: inferential step needs at least one move")
    return move_ids, used_premises, failed_move_ids


def validate_move_reachability(
    inference: Any,
    side_conditions: Any,
    extra_roots: Iterable[str],
    prefix: str,
    final: bool,
    errors: list[str],
) -> None:
    if not final or not isinstance(inference, dict):
        return
    moves = inference.get("moves")
    if not isinstance(moves, list):
        return

    graph: dict[str, set[str]] = {}
    for move in moves:
        if not isinstance(move, dict):
            continue
        move_id = move.get("id")
        if not isinstance(move_id, str) or not MOVE_ID_RE.fullmatch(move_id):
            continue
        prior_move_ids = move.get("prior_move_ids")
        graph[move_id] = (
            {
                prior_id
                for prior_id in prior_move_ids
                if isinstance(prior_id, str) and prior_id in graph
            }
            if isinstance(prior_move_ids, list)
            else set()
        )

    if isinstance(side_conditions, list):
        for condition in side_conditions:
            if (
                not isinstance(condition, dict)
                or condition.get("status") != "discharged"
            ):
                continue
            generated_by = condition.get("generated_by")
            discharge = condition.get("discharge")
            if not isinstance(discharge, dict):
                continue
            sources = discharge.get("sources")
            if not isinstance(sources, list):
                continue
            for source in sources:
                if (
                    not isinstance(source, dict)
                    or source.get("kind") != "inference_move"
                ):
                    continue
                reference = source.get("reference")
                if (
                    isinstance(generated_by, str)
                    and isinstance(reference, str)
                    and generated_by in graph
                    and reference in graph
                ):
                    graph[generated_by].add(reference)

    conclusion_move = inference.get("conclusion_move")
    roots = {
        root
        for root in [conclusion_move, *extra_roots]
        if isinstance(root, str) and root in graph
    }
    if not roots:
        return
    reachable: set[str] = set()
    pending = list(roots)
    while pending:
        move_id = pending.pop()
        if move_id in reachable:
            continue
        reachable.add(move_id)
        pending.extend(graph.get(move_id, set()) - reachable)
    orphaned = sorted(set(graph) - reachable)
    if orphaned:
        errors.append(
            f"{prefix}: inference moves are not load-bearing for the conclusion: "
            + ", ".join(orphaned)
        )


def validate_side_conditions(
    value: Any,
    prefix: str,
    premises: dict[str, dict[str, Any]],
    move_ids: dict[str, int],
    failed_move_ids: set[str],
    final: bool,
    errors: list[str],
) -> tuple[set[str], set[str]]:
    if value is None and not final:
        return set(), set()
    if not isinstance(value, list):
        errors.append(f"{prefix}.side_conditions must be a list")
        return set(), set()
    seen: set[str] = set()
    open_ids: set[str] = set()
    discharge_premises: set[str] = set()
    for index, condition in enumerate(value, 1):
        item_prefix = f"{prefix}.side_conditions[{index}]"
        if not isinstance(condition, dict):
            errors.append(f"{item_prefix} must be an object")
            continue
        condition_id = condition.get("id")
        if (
            not isinstance(condition_id, str)
            or not SIDE_CONDITION_ID_RE.fullmatch(condition_id)
        ):
            errors.append(f"{item_prefix}.id must match SC001")
            continue
        if condition_id in seen:
            errors.append(f"{prefix}: duplicate side-condition id {condition_id}")
            continue
        seen.add(condition_id)
        if not is_substantive_string(condition.get("condition")):
            errors.append(
                f"{item_prefix}.condition must be a nonempty string and cannot be "
                "a reserved placeholder"
            )
        generated_by = condition.get("generated_by")
        if not is_nonempty_string(generated_by) or generated_by not in move_ids:
            errors.append(
                f"{item_prefix}.generated_by must name an inference move in this step"
            )
        status = condition.get("status")
        if not is_enum_value(status, {"discharged", "open"}):
            errors.append(f"{item_prefix}.status is invalid")
            continue
        if status == "open":
            open_ids.add(condition_id)
            if condition.get("discharge") not in (None, {}):
                errors.append(f"{item_prefix}: open condition cannot have a discharge")
            continue

        discharge = condition.get("discharge")
        if not isinstance(discharge, dict):
            errors.append(f"{item_prefix}.discharge must be an object")
            continue
        sources = discharge.get("sources")
        if not isinstance(sources, list) or not sources:
            errors.append(
                f"{item_prefix}.discharge.sources must be a nonempty list"
            )
            sources = []
        seen_sources: set[tuple[str, str]] = set()
        for source_index, source in enumerate(sources, 1):
            source_prefix = (
                f"{item_prefix}.discharge.sources[{source_index}]"
            )
            if not isinstance(source, dict):
                errors.append(f"{source_prefix} must be an object")
                continue
            kind = source.get("kind")
            reference = source.get("reference")
            if not is_enum_value(kind, DISCHARGE_KINDS):
                errors.append(f"{source_prefix}.kind is invalid")
                continue
            if not is_nonempty_string(reference):
                errors.append(f"{source_prefix}.reference must be nonempty")
                continue
            key = (kind, reference)
            if key in seen_sources:
                errors.append(
                    f"{item_prefix}.discharge contains duplicate source "
                    f"{kind}:{reference}"
                )
            seen_sources.add(key)
            if not is_substantive_string(source.get("contribution")):
                errors.append(
                    f"{source_prefix}.contribution must be substantive"
                )
            if kind == "premise":
                if reference not in premises:
                    errors.append(
                        f"{condition_id} has unknown discharge premise {reference}"
                    )
                else:
                    discharge_premises.add(reference)
            elif reference not in move_ids:
                errors.append(
                    f"{condition_id} has unknown discharge move {reference}"
                )
            elif reference in failed_move_ids:
                errors.append(
                    f"{condition_id} cannot use failed move {reference} as "
                    "discharge evidence"
                )
            elif (
                isinstance(generated_by, str)
                and generated_by in move_ids
                and move_ids[reference] >= move_ids[generated_by]
            ):
                errors.append(
                    f"{condition_id} discharge move {reference} is not established "
                    f"before generating move {generated_by}"
                )
        if not is_substantive_string(discharge.get("rule")):
            errors.append(
                f"{condition_id} discharge rule must be nonempty and substantive"
            )
        if not is_substantive_string(discharge.get("evidence")):
            errors.append(
                f"{condition_id} discharge evidence must be nonempty and substantive"
            )
    return open_ids, discharge_premises


def validate_condition_records(
    value: Any,
    prefix: str,
    unresolved: set[tuple[str, str]],
    status: Any,
    final: bool,
    errors: list[str],
) -> None:
    if value is None:
        value = []
    if not isinstance(value, list):
        errors.append(f"{prefix}.conditions must be a list")
        return
    seen: set[tuple[str, str]] = set()
    for index, condition in enumerate(value, 1):
        item_prefix = f"{prefix}.conditions[{index}]"
        if not isinstance(condition, dict):
            errors.append(f"{item_prefix} must be an object")
            continue
        kind = condition.get("kind")
        reference = condition.get("reference")
        if not is_enum_value(kind, CONDITION_KINDS):
            errors.append(f"{item_prefix}.kind is invalid")
            continue
        if not is_nonempty_string(reference):
            errors.append(f"{item_prefix}.reference must be nonempty")
            continue
        key = (kind, reference)
        if key in seen:
            errors.append(f"{prefix}: duplicate condition reference {kind}:{reference}")
        seen.add(key)
        if not is_substantive_string(condition.get("condition")):
            errors.append(
                f"{item_prefix}.condition must be a nonempty string and cannot be "
                "a reserved placeholder"
            )

    if not final:
        return
    if status == "conditionally_verified":
        missing = unresolved - seen
        extra = seen - unresolved
        if missing or extra or not unresolved:
            details: list[str] = []
            if missing:
                details.append(
                    "missing " + ", ".join(f"{kind}:{ref}" for kind, ref in sorted(missing))
                )
            if extra:
                details.append(
                    "unresolved target absent for "
                    + ", ".join(f"{kind}:{ref}" for kind, ref in sorted(extra))
                )
            if not unresolved:
                details.append("no unresolved cause exists")
            errors.append(
                f"{prefix}.conditions must match every unresolved conditional cause"
                + (": " + "; ".join(details) if details else "")
            )
    elif seen:
        errors.append(f"{prefix}: conditions are only allowed on conditionally_verified steps")


@gate_context_reader
def check_ledger_data(
    ledger_path: Path,
    final: bool = False,
    *,
    primary_only: bool = False,
) -> tuple[list[str], dict[str, Any]]:
    errors: list[str] = []
    try:
        ledger = json.loads(read_text(ledger_path))
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        return [f"Cannot read ledger {ledger_path}: {exc}"], {}
    if not isinstance(ledger, dict):
        return [f"Ledger root must be an object: {ledger_path}"], {}

    schema_version = ledger.get("schema_version")
    legacy_schema = schema_version == LEGACY_SCHEMA_VERSION
    if schema_version not in {SCHEMA_VERSION, LEGACY_SCHEMA_VERSION}:
        errors.append(
            f"Unsupported ledger schema_version {schema_version!r}; expected "
            f"{SCHEMA_VERSION}, or {LEGACY_SCHEMA_VERSION} for legacy inspection"
        )
    elif final and legacy_schema:
        errors.append(
            "upgrade_required: artifact schema 4 is inspection-only; migrate to "
            "schema 5 and recheck the proof before finalization"
        )
    evidence_contract_version = ledger.get("evidence_contract_version")
    if evidence_contract_version not in {
        EVIDENCE_CONTRACT_VERSION,
        PREVIOUS_EVIDENCE_CONTRACT_VERSION,
        LEGACY_EVIDENCE_CONTRACT_VERSION,
        None,
    }:
        errors.append(
            "Unsupported evidence_contract_version "
            f"{evidence_contract_version!r}; expected {EVIDENCE_CONTRACT_VERSION}, "
            f"or {PREVIOUS_EVIDENCE_CONTRACT_VERSION} or "
            f"{LEGACY_EVIDENCE_CONTRACT_VERSION} for legacy inspection"
        )
    elif final and evidence_contract_version != EVIDENCE_CONTRACT_VERSION:
        errors.append(
            "upgrade_required: final ledger requires evidence_contract_version "
            f"{EVIDENCE_CONTRACT_VERSION}; evidence contracts "
            f"{LEGACY_EVIDENCE_CONTRACT_VERSION} and "
            f"{PREVIOUS_EVIDENCE_CONTRACT_VERSION} are inspection-only"
        )
    work_context_sha256 = ledger.get("work_context_sha256")
    valid_work_context = bool(
        isinstance(work_context_sha256, str)
        and SHA256_RE.fullmatch(work_context_sha256)
    )
    if (
        final
        and schema_version == SCHEMA_VERSION
        and evidence_contract_version == EVIDENCE_CONTRACT_VERSION
        and not valid_work_context
    ):
        errors.append(
            "current final ledger requires a calibration-bound "
            "work_context_sha256"
        )
    elif work_context_sha256 is not None and not valid_work_context:
        errors.append("work_context_sha256 must be a SHA-256 digest when present")
    migration = ledger.get("migration")
    if schema_version == SCHEMA_VERSION and migration is not None:
        if not isinstance(migration, dict):
            errors.append("migration must be an object")
        else:
            if migration.get("from_schema_version") != LEGACY_SCHEMA_VERSION:
                errors.append("migration.from_schema_version must be 4")
            if not isinstance(
                migration.get("legacy_ledger_sha256"), str
            ) or not SHA256_RE.fullmatch(migration["legacy_ledger_sha256"]):
                errors.append("migration.legacy_ledger_sha256 must be a SHA-256")
            if migration.get("status") not in {
                "requires_manual_recheck",
                "rechecked",
            }:
                errors.append("migration.status is invalid")
            if final and migration.get("status") != "rechecked":
                errors.append(
                    "upgrade_required: migrated ledger still requires a full "
                    "manual atomic recheck"
                )
            if migration.get("status") == "rechecked":
                if not is_substantive_string(migration.get("recheck_evidence")):
                    errors.append("migration.recheck_evidence must be substantive")
                if not is_utc_timestamp(migration.get("rechecked_utc")):
                    errors.append("migration.rechecked_utc must be a valid UTC time")
    unit_id = ledger.get("unit_id")
    if not is_nonempty_string(unit_id):
        errors.append("unit_id must be a nonempty string")
        unit_id = None

    source_info = ledger.get("source")
    if not isinstance(source_info, dict):
        return ["Missing source object"], {}
    try:
        start_value = source_info["start_line"]
        end_value = source_info["end_line"]
        file_value = source_info["file"]
        if not is_int(start_value) or not is_int(end_value):
            raise TypeError("start_line and end_line must be integers")
        if not is_nonempty_string(file_value):
            raise TypeError("file must be a nonempty string")
        start = start_value
        end = end_value
        source = resolve_stored_path(file_value, ledger_path.parent)
    except (KeyError, TypeError, ValueError) as exc:
        return [f"Invalid source specification: {exc}"], {}
    coverage_mode = source_info.get("coverage_mode")
    if not is_enum_value(coverage_mode, {
        "statement_and_proof",
        "proof_with_separate_statement",
        "external_restatement",
    }):
        errors.append("source.coverage_mode is invalid or missing")
    external_restatement_use_id = source_info.get(
        "external_dependency_use_id"
    )
    if coverage_mode == "external_restatement":
        if (
            not is_nonempty_string(external_restatement_use_id)
            or not DEPENDENCY_USE_ID_RE.fullmatch(
                str(external_restatement_use_id)
            )
        ):
            errors.append(
                "source.external_dependency_use_id must match D001 for "
                "external_restatement coverage"
            )
    elif external_restatement_use_id is not None:
        errors.append(
            "source.external_dependency_use_id is allowed only for "
            "external_restatement coverage"
        )
    if (
        final
        and coverage_mode == "proof_with_separate_statement"
        and not is_substantive_string(source_info.get("separate_statement_reason"))
    ):
        errors.append(
            "source.separate_statement_reason is required when the statement is outside "
            "the ledger range"
        )

    valid_range = True
    if start < 1 or end < start:
        errors.append(f"Invalid source range: {start}-{end}")
        valid_range = False
    elif end - start + 1 > MAX_UNIT_LINES:
        errors.append(
            f"Source range contains more than {MAX_UNIT_LINES} physical lines; "
            "split the audit unit or inspect the range"
        )
        valid_range = False
    source_lines = ledger.get("source_lines")
    if not isinstance(source_lines, list):
        errors.append("source_lines must be a list")
        source_lines = []

    current_selected: list[str] = []
    if not source.is_file():
        errors.append(f"Source file not found: {source}")
    elif valid_range:
        try:
            current_selected = source_fragment_support().current(report_api(), ledger, ledger_path.parent)
        except (KeyError, OSError, TypeError, ValueError) as exc:
            errors.append(str(exc))
        else:
            current_hash = sha256_text("\n".join(current_selected))
            if current_hash != source_info.get("unit_sha256"):
                errors.append("Source drift: unit SHA-256 no longer matches the ledger")
    if "source_fragments" in ledger:
        start, end = source_coverage_bounds(ledger)
    if valid_range:
        expected_count = end - start + 1
        if len(source_lines) != expected_count:
            errors.append(
                f"source_lines must contain exactly {expected_count} ordered records"
            )
        for offset, item in enumerate(source_lines):
            line_number = start + offset
            if not isinstance(item, dict):
                errors.append(f"source_lines[{offset + 1}] must be an object")
                continue
            if item.get("line") != line_number:
                errors.append(
                    f"source_lines[{offset + 1}].line must be {line_number}"
                )
            text = item.get("text")
            if not isinstance(text, str) or item.get("sha256") != sha256_text(text):
                errors.append(f"Invalid locked text or hash at source line {line_number}")
            if current_selected and offset < len(current_selected):
                current_text = current_selected[offset]
                if text != current_text:
                    errors.append(
                        f"source_lines[{offset + 1}].text: Locked source mismatch "
                        f"at line {line_number}; " + exact_mismatch_detail(text, current_text)
                    )

    locked_selected = [
        item.get("text", "") if isinstance(item, dict) else ""
        for item in source_lines
    ]
    locked_display_spans = display_math_spans(locked_selected)
    locked_masked_lines = mask_structural_tex("\n".join(locked_selected)).split("\n")
    source_units: dict[str, dict[str, Any]] = {}
    source_unit_coverage: dict[int, list[str]] = defaultdict(list)
    source_unit_order: dict[str, int] = {}
    if schema_version == SCHEMA_VERSION and valid_range:
        source_units, source_unit_coverage, source_unit_order = validate_source_units(
            ledger.get("source_units"),
            start=start,
            end=end,
            selected_lines=locked_selected,
            source_records=source_lines if "source_fragments" in ledger else None,
            final=final,
            errors=errors,
        )
        if "source_fragments" in ledger:
            for source_unit in source_units.values():
                try:
                    expected_location = source_unit_location(ledger, source_unit)
                except (KeyError, TypeError, ValueError) as exc:
                    errors.append(str(exc))
                else:
                    if source_unit.get("source_span") != expected_location:
                        errors.append(f"{source_unit.get('id')}: source_span does not match its original source fragment")

    obligation = ledger.get("obligation")
    obligation_error_start = len(errors)
    normalization_statuses = validate_obligation(obligation, ledger_path, final, errors)
    obligation_ready = len(errors) == obligation_error_start
    obligation_statement_spans: list[dict[str, Any]] = []
    obligation_context_spans: list[dict[str, Any]] = []
    if isinstance(obligation, dict):
        statement_spans = obligation.get("statement_spans")
        if isinstance(statement_spans, list):
            for span in statement_spans:
                metadata = resolved_span_metadata(span, ledger_path.parent)
                if metadata:
                    obligation_statement_spans.append(metadata)
        context_spans = obligation.get("context_spans")
        if isinstance(context_spans, list):
            for span in context_spans:
                metadata = resolved_span_metadata(span, ledger_path.parent)
                if metadata:
                    obligation_context_spans.append(metadata)

    steps = ledger.get("steps")
    if not isinstance(steps, list):
        errors.append("steps must be a list")
        steps = []
    coverage: dict[int, list[str]] = (
        source_unit_coverage
        if schema_version == SCHEMA_VERSION
        else defaultdict(list)
    )
    source_unit_step_ids: dict[str, list[str]] = defaultdict(list)
    step_ids: set[str] = set()
    step_status_by_id: dict[str, str] = {}
    step_kind_by_id: dict[str, str] = {}
    step_claim_by_id: dict[str, str] = {}
    step_conclusion_move_by_id: dict[str, str | None] = {}
    step_support_role_by_id: dict[str, str] = {}
    premise_records_by_step: dict[str, dict[str, dict[str, Any]]] = {}
    step_ranges_by_id: dict[str, tuple[int, int]] = {}
    step_position_by_id: dict[str, int] = {}
    step_dependency_claims: list[tuple[str, str, str]] = []
    result_dependency_claims: list[dict[str, Any]] = []
    statuses: list[str] = []
    issue_references: set[str] = set()
    issue_links: list[dict[str, str]] = []
    evidence_specificity_records: list[dict[str, str]] = []
    evidence_anchoring_records: list[dict[str, Any]] = []
    previous_step_end = start - 1
    previous_source_unit_order = 0

    for index, step in enumerate(steps, 1):
        prefix = f"Step {index}"
        if not isinstance(step, dict):
            errors.append(f"{prefix} must be an object")
            continue
        step_id = step.get("id")
        if not isinstance(step_id, str) or not STEP_ID_RE.fullmatch(step_id):
            errors.append(f"{prefix} has invalid id; expected S001 or S001.1")
            step_id = f"invalid-{index}"
        elif step_id in step_ids:
            errors.append(f"Duplicate step id: {step_id}")
        step_ids.add(step_id)
        step_position_by_id[step_id] = index
        prefix = step_id

        covered_lines: list[int] = []
        if schema_version == SCHEMA_VERSION:
            if final and "lines" in step:
                errors.append(
                    f"{prefix}: schema-5 steps must reference source_unit_id, not lines"
                )
            source_unit_id = step.get("source_unit_id")
            source_unit = source_units.get(source_unit_id)
            if not isinstance(source_unit_id, str) or source_unit is None:
                errors.append(f"{prefix}.source_unit_id must reference one source unit")
            else:
                source_unit_step_ids[source_unit_id].append(step_id)
                line_range = source_unit.get("lines")
                if isinstance(line_range, list) and len(line_range) == 2:
                    step_start, step_end = line_range
                    covered_lines = list(range(step_start, step_end + 1))
                    step_ranges_by_id[step_id] = (step_start, step_end)
                unit_order = source_unit_order.get(source_unit_id, 0)
                if unit_order < previous_source_unit_order:
                    errors.append(f"{prefix}: steps must follow source-unit order")
                previous_source_unit_order = max(
                    previous_source_unit_order, unit_order
                )
        else:
            line_range = step.get("lines")
            if (
                not isinstance(line_range, list)
                or len(line_range) != 2
                or not all(is_int(value) for value in line_range)
            ):
                errors.append(f"{prefix}: lines must be [start, end]")
            else:
                step_start, step_end = line_range
                if step_start > step_end:
                    errors.append(f"{prefix}: line range is reversed")
                elif step_start < start or step_end > end:
                    errors.append(
                        f"{prefix}: line range {step_start}-{step_end} is outside "
                        f"{start}-{end}"
                    )
                else:
                    covered_lines = list(range(step_start, step_end + 1))
                    for line_number in covered_lines:
                        coverage[line_number].append(step_id)
                    if step_start <= previous_step_end:
                        errors.append(f"{prefix}: steps must appear in source order")
                    previous_step_end = max(previous_step_end, step_end)
                    step_ranges_by_id[step_id] = (step_start, step_end)

        kind = step.get("kind")
        if not is_enum_value(kind, STEP_KINDS):
            errors.append(f"{prefix}: invalid or missing kind {kind!r}")
        else:
            step_kind_by_id[step_id] = kind

        status = step.get("status")
        if not is_enum_value(status, STEP_STATUSES):
            errors.append(f"{prefix}: invalid status {status!r}")
        else:
            statuses.append(status)
            step_status_by_id[step_id] = status

        issue_ids = step.get("issue_ids", [])
        if not isinstance(issue_ids, list) or not all(
            isinstance(issue_id, str) and ISSUE_ID_RE.fullmatch(issue_id)
            for issue_id in issue_ids
        ):
            errors.append(f"{prefix}: issue_ids must contain IDs such as I-001")
            issue_ids = []
        issue_references.update(issue_ids)
        issue_links.extend(
            {"issue_id": issue_id, "step_id": step_id, "step_status": str(status)}
            for issue_id in issue_ids
        )

        if is_enum_value(status, {"gap", "incorrect", "unclear"}) and not issue_ids:
            errors.append(f"{prefix}: status {status} requires at least one issue ID")
        if final and status == "not_checked":
            errors.append(f"{prefix}: not_checked is not allowed with --final")

        if status == "non_substantive":
            if locked_selected and covered_lines:
                texts = [locked_selected[number - start] for number in covered_lines]
                if not all(locked_line_is_non_substantive(source_lines[number - start]) if "source_fragments" in ledger else is_non_substantive(locked_selected[number - start]) for number in covered_lines):
                    errors.append(
                        f"{prefix}: non_substantive covers prose or mathematical content"
                    )
            continue
        if (
            schema_version == SCHEMA_VERSION
            and isinstance(step.get("source_unit_id"), str)
            and source_units.get(step["source_unit_id"], {}).get("kind")
            == "non_substantive"
        ):
            errors.append(
                f"{prefix}: substantive step cannot reference a non_substantive "
                "source unit"
            )

        if final and status != "not_checked":
            restatement = step.get("restatement")
            if not is_substantive_string(restatement):
                errors.append(
                    f"{prefix}: substantive step needs a restatement that is not "
                    "a reserved placeholder"
                )
            if not is_substantive_string(step.get("goal")):
                errors.append(
                    f"{prefix}: substantive step needs its current goal, not a "
                    "reserved placeholder"
                )
        if is_substantive_string(step.get("restatement")):
            step_claim_by_id[step_id] = step["restatement"]


        if final and evidence_contract_version == EVIDENCE_CONTRACT_VERSION:
            legacy_fields = [
                field for field in ("required_facts", "assumptions") if field in step
            ]
            if legacy_fields:
                errors.append(
                    f"{prefix}: legacy free-text fields are not allowed by evidence "
                    f"contract {EVIDENCE_CONTRACT_VERSION}: "
                    + ", ".join(legacy_fields)
                )

        dependencies = step.get("dependencies", [])
        if not isinstance(dependencies, list):
            errors.append(f"{prefix}: dependencies must be a list")
            dependencies = []
        dependencies_by_id: dict[str, dict[str, Any]] = {}
        dependency_statuses: list[str] = []
        for dependency_index, dependency in enumerate(dependencies, 1):
            record = validate_dependency_record(
                dependency,
                f"{prefix}.dependencies[{dependency_index}]",
                final,
                errors,
            )
            if record is None:
                continue
            dependency_id = record.get("id")
            dependency_key = (
                dependency_id
                if record.get("kind") == "step"
                else record.get("use_id")
            )
            dependency_status = record.get("status")
            if is_nonempty_string(dependency_key):
                if dependency_key in dependencies_by_id:
                    errors.append(f"{prefix}: duplicate dependency use {dependency_key}")
                else:
                    dependencies_by_id[dependency_key] = record
            if is_enum_value(dependency_status, DEPENDENCY_STATUSES):
                dependency_statuses.append(dependency_status)
                if dependency_status == "not_applicable":
                    errors.append(
                        f"{prefix}: declared dependency {dependency_id} cannot be "
                        "not_applicable; omit it instead"
                    )
            if (
                is_nonempty_string(dependency_id)
                and is_enum_value(dependency_status, DEPENDENCY_STATUSES)
            ):
                if record.get("kind") == "step":
                    step_dependency_claims.append(
                        (prefix, dependency_id, dependency_status)
                    )
                elif is_enum_value(
                    record.get("kind"), {"internal_result", "external_result"}
                ):
                    result_dependency_claims.append(
                        {
                            "owner_step": prefix,
                            "use_id": record.get("use_id"),
                            "id": dependency_id,
                            "kind": record.get("kind"),
                            "conclusion_id": record.get("conclusion_id"),
                            "status": dependency_status,
                            "needed_form": record.get("needed_form"),
                            "compatibility_check": record.get("compatibility_check"),
                            **({"statement_support_sha256": record["statement_support_sha256"]} if "statement_support_sha256" in record else {}),
                        }
                    )

        checks = step.get("checks")
        atomicity_status: str | None = None
        if isinstance(checks, dict):
            draft_atomicity = checks.get("atomicity")
            if isinstance(draft_atomicity, dict):
                candidate = draft_atomicity.get("status")
                if is_enum_value(candidate, ATOMICITY_STATUSES):
                    atomicity_status = candidate
                elif (
                    not final
                    and schema_version == SCHEMA_VERSION
                    and candidate is not None
                ):
                    errors.append(
                        f"{prefix}.checks.atomicity.status is invalid"
                    )
            elif (
                not final
                and schema_version == SCHEMA_VERSION
                and draft_atomicity is not None
            ):
                errors.append(f"{prefix}.checks.atomicity must be an object")
        if final and status != "not_checked":
            if not isinstance(checks, dict):
                errors.append(f"{prefix}.checks must be an object")
            else:
                if not is_substantive_string(checks.get("literal")):
                    errors.append(f"{prefix}.checks.literal must be nonempty and substantive")
                elif schema_version == SCHEMA_VERSION:
                    evidence_specificity_records.append(
                        {
                            "category": "literal",
                            "text": checks["literal"],
                            "step_id": step_id,
                            "claim": str(step.get("restatement", "")),
                        }
                    )
                validate_string_list(
                    checks.get("adversarial"),
                    f"{prefix}.checks.adversarial",
                    errors,
                    substantive=True,
                )
                if schema_version == SCHEMA_VERSION and isinstance(
                    checks.get("adversarial"), list
                ):
                    evidence_specificity_records.extend(
                        {
                            "category": "adversarial",
                            "text": text,
                            "step_id": step_id,
                            "claim": str(step.get("restatement", "")),
                        }
                        for text in checks["adversarial"]
                        if is_substantive_string(text)
                    )
                atomicity = checks.get("atomicity")
                if not isinstance(atomicity, dict):
                    errors.append(f"{prefix}.checks.atomicity must be an object")
                else:
                    atomicity_status = atomicity.get("status")
                    if not is_enum_value(atomicity_status, ATOMICITY_STATUSES):
                        errors.append(f"{prefix}.checks.atomicity.status is invalid")
                    if not is_substantive_string(atomicity.get("evidence")):
                        errors.append(
                            f"{prefix}.checks.atomicity.evidence must be nonempty and substantive"
                        )
                    elif schema_version == SCHEMA_VERSION:
                        evidence_specificity_records.append(
                            {
                                "category": "atomicity",
                                "text": atomicity["evidence"],
                                "step_id": step_id,
                                "claim": str(step.get("restatement", "")),
                            }
                        )
                    if (
                        atomicity_status == "non_inferential"
                        and not is_enum_value(
                            kind, {"statement", "setup", "definition"}
                        )
                    ):
                        errors.append(
                            f"{prefix}: {kind} step must declare at least one "
                            "inferential move"
                        )
                    if (
                        atomicity_status == "source_indivisible_chain"
                    ):
                        if schema_version == SCHEMA_VERSION:
                            errors.append(
                                f"{prefix}: schema 5 replaces source_indivisible_chain "
                                "with shared source_unit_id atomic steps"
                            )
                        source_unit_kind = atomicity.get("source_unit_kind")
                        allowed_source_units = {
                            "one_line",
                            "continued_sentence",
                            "continued_display",
                        }
                        if not is_enum_value(
                            source_unit_kind, allowed_source_units
                        ):
                            errors.append(
                                f"{prefix}: source_indivisible_chain needs a valid "
                                "source_unit_kind"
                            )
                        if not is_substantive_string(
                            atomicity.get("partition_evidence")
                        ):
                            errors.append(
                                f"{prefix}: source_indivisible_chain needs "
                                "substantive partition_evidence"
                            )
                        if len(covered_lines) == 1 and source_unit_kind != "one_line":
                            errors.append(
                                f"{prefix}: one physical line requires "
                                "source_unit_kind one_line"
                            )
                        if len(covered_lines) > 1:
                            if source_unit_kind not in {
                                "continued_sentence",
                                "continued_display",
                            }:
                                errors.append(
                                    f"{prefix}: a multiline source unit must be a "
                                    "continued_sentence or continued_display"
                                )
                            texts = [
                                locked_selected[line - start]
                                for line in covered_lines
                            ] if locked_selected else []
                            if any(
                                not strip_latex_comment(text).strip()
                                for text in texts
                            ):
                                errors.append(
                                    f"{prefix}: a multiline indivisible source unit "
                                    "cannot cross a blank or comment-only separator"
                                )
                if "inferential" in checks:
                    errors.append(
                        f"{prefix}: checks.inferential is legacy free text; "
                        "use the structured inference record"
                    )

        support_role = step.get("support_role")
        if schema_version == SCHEMA_VERSION:
            if atomicity_status == "non_inferential":
                if support_role is not None:
                    errors.append(
                        f"{prefix}: non_inferential step must omit support_role"
                    )
            elif final and status != "not_checked":
                if not is_enum_value(support_role, SUPPORT_ROLES):
                    errors.append(
                        f"{prefix}.support_role must be derivation or reuse"
                    )
                else:
                    step_support_role_by_id[step_id] = support_role

        prior_statuses = {
            prior_id: prior_status
            for prior_id, prior_status in step_status_by_id.items()
            if prior_id != step_id
        }
        prior_kinds = {
            prior_id: prior_kind
            for prior_id, prior_kind in step_kind_by_id.items()
            if prior_id != step_id
        }
        prior_claims = {
            prior_id: prior_claim
            for prior_id, prior_claim in step_claim_by_id.items()
            if prior_id != step_id
        }
        premises, used_dependencies = validate_premise_uses(
            step.get("premise_uses"),
            prefix,
            obligation,
            ledger_path.parent,
            dependencies_by_id,
            prior_statuses,
            prior_kinds,
            prior_claims,
            {
                prior_id: prior_range
                for prior_id, prior_range in step_ranges_by_id.items()
                if prior_id != step_id
            },
            step_conclusion_move_by_id,
            source,
            final and status != "not_checked",
            errors,
            source_ledger=ledger,
        )
        premise_records_by_step[step_id] = premises
        premise_claims = [
            premise.get("claim")
            for premise in premises.values()
            if is_nonempty_string(premise.get("claim"))
        ]
        duplicate_claims = sorted(
            claim
            for claim, count in Counter(premise_claims).items()
            if count > 1
        )
        if schema_version == SCHEMA_VERSION and duplicate_claims:
            errors.append(
                f"{prefix}: duplicate exact premise claims are not independent "
                "support: " + "; ".join(duplicate_claims[:3])
            )
        exact_conclusion_premises = [
            premise
            for premise in premises.values()
            if premise.get("claim") == step.get("restatement")
        ]
        if (
            schema_version == SCHEMA_VERSION
            and support_role == "derivation"
            and exact_conclusion_premises
        ):
            errors.append(
                f"{prefix}: derivation premise already equals the current "
                "restatement; declare a reuse step or remove the circular premise"
            )
        if schema_version == SCHEMA_VERSION and support_role == "reuse":
            if len(exact_conclusion_premises) != 1:
                errors.append(
                    f"{prefix}: reuse step requires exactly one premise equal to "
                    "the current restatement"
                )
        move_ids, inference_premises, failed_move_ids = validate_inference_record(
            step.get("inference"),
            prefix,
            step.get("restatement"),
            premises,
            atomicity_status,
            status,
            set(issue_ids),
            covered_lines,
            schema_version == SCHEMA_VERSION,
            final and status != "not_checked",
            errors,
        )
        step_inference = step.get("inference")
        step_conclusion_move_by_id[step_id] = (
            step_inference.get("conclusion_move")
            if isinstance(step_inference, dict)
            else None
        )
        if schema_version == SCHEMA_VERSION:
            inference_value = step.get("inference")
            moves_value = (
                inference_value.get("moves")
                if isinstance(inference_value, dict)
                else None
            )
            if isinstance(moves_value, list):
                evidence_specificity_records.extend(
                    {
                        "category": "move justification",
                        "text": move["justification"],
                        "step_id": step_id,
                        "claim": str(step.get("restatement", "")),
                    }
                    for move in moves_value
                    if isinstance(move, dict)
                    and is_substantive_string(move.get("justification"))
                )
        open_side_condition_ids, discharge_premises = validate_side_conditions(
            step.get("side_conditions"),
            prefix,
            premises,
            move_ids,
            failed_move_ids,
            final and status != "not_checked",
            errors,
        )
        validate_move_reachability(
            step.get("inference"),
            step.get("side_conditions"),
            [
                support.get("move_id")
                for result in (
                    ledger.get("review", {}).get("conclusion_results", [])
                    if isinstance(ledger.get("review"), dict)
                    and isinstance(
                        ledger.get("review", {}).get("conclusion_results"),
                        list,
                    )
                    else []
                )
                if isinstance(result, dict)
                and isinstance(
                    support := result.get("support"), dict
                )
                and support.get("step_id") == step_id
                and is_nonempty_string(support.get("move_id"))
            ],
            prefix,
            final and status != "not_checked",
            errors,
        )
        risk_statuses = (
            validate_aspect_matrix(
                step.get("risk_checks"),
                f"{prefix}.risk_checks",
                RISK_ASPECTS,
                RISK_STATUSES,
                final and status != "not_checked",
                errors,
            )
            if final or "risk_checks" in step
            else {}
        )
        if schema_version == SCHEMA_VERSION and isinstance(
            step.get("risk_checks"), list
        ):
            evidence_specificity_records.extend(
                {
                    "category": "risk",
                    "text": record["evidence"],
                    "step_id": step_id,
                    "claim": str(step.get("restatement", "")),
                    "aspect": str(record.get("aspect", "")),
                    "status": str(record.get("status", "")),
                }
                for record in step["risk_checks"]
                if isinstance(record, dict)
                and is_substantive_string(record.get("evidence"))
            )
        if (
            final
            and schema_version == SCHEMA_VERSION
            and status != "not_checked"
            and step.get("support_role") in SUPPORT_ROLES
        ):
            anchor_unit = source_units.get(step.get("source_unit_id"))
            anchor_range = (
                anchor_unit.get("lines") if isinstance(anchor_unit, dict) else None
            )
            if (
                isinstance(anchor_range, list)
                and len(anchor_range) == 2
                and all(is_int(value) for value in anchor_range)
                and valid_range
            ):
                unit_text = "\n".join(
                    locked_masked_lines[anchor_range[0] - start : anchor_range[1] - start + 1]
                )
                evidence_anchoring_records.append(
                    {
                        "step_id": step_id,
                        "tokens": extract_step_math_tokens(
                            unit_text,
                            whole_math=(
                                anchor_unit.get("kind") == "continued_display"
                                or display_math_contains_lines(
                                    locked_display_spans, locked_masked_lines,
                                    anchor_range[0] - start + 1,
                                    anchor_range[1] - start + 1,
                                )
                            ),
                        ),
                        "texts": collect_step_evidence_texts(step),
                    }
                )

        unused_premises = set(premises) - inference_premises - discharge_premises
        if final and status != "not_checked" and unused_premises:
            errors.append(
                f"{prefix}: premise uses not consumed by an inference move or "
                "side-condition discharge: "
                + ", ".join(sorted(unused_premises))
            )
        unused_dependencies = set(dependencies_by_id) - used_dependencies
        if final and status != "not_checked" and unused_dependencies:
            errors.append(
                f"{prefix}: dependencies not used by premise_uses: "
                + ", ".join(sorted(unused_dependencies))
            )

        open_risks = {
            aspect for aspect, risk_status in risk_statuses.items()
            if risk_status == "open"
        }
        failed_risks = {
            aspect for aspect, risk_status in risk_statuses.items()
            if risk_status == "failed"
        }
        unclear_risks = {
            aspect for aspect, risk_status in risk_statuses.items()
            if risk_status == "unclear"
        }
        unresolved_causes = {
            ("side_condition", condition_id)
            for condition_id in open_side_condition_ids
        }
        unresolved_causes.update(
            ("dependency", dependency_id)
            for dependency_id, dependency in dependencies_by_id.items()
            if is_enum_value(
                dependency.get("status"), {"conditional", "unchecked"}
            )
        )
        unresolved_causes.update(
            ("risk_check", aspect) for aspect in open_risks
        )
        validate_condition_records(
            step.get("conditions"),
            prefix,
            unresolved_causes,
            status,
            final and status != "not_checked",
            errors,
        )

        if status == "verified":
            invalid_dependencies = [
                value for value in dependency_statuses if value != "verified"
            ]
            if invalid_dependencies:
                errors.append(
                    f"{prefix}: verified step has nonverified dependencies: "
                    + ", ".join(invalid_dependencies)
                )
            if open_side_condition_ids:
                errors.append(f"{prefix}: verified step has an open side condition")
            unresolved_risks = open_risks | failed_risks | unclear_risks
            if unresolved_risks:
                errors.append(
                    f"{prefix}: verified step has unresolved risk checks: "
                    + ", ".join(sorted(unresolved_risks))
                )

        if status == "conditionally_verified":
            invalid_dependencies = [
                value
                for value in dependency_statuses
                if is_enum_value(
                    value, {"gap", "incorrect", "unclear", "not_applicable"}
                )
            ]
            if invalid_dependencies:
                errors.append(
                    f"{prefix}: conditionally_verified cannot hide failed "
                    "dependencies: " + ", ".join(invalid_dependencies)
                )
            invalid_risks = failed_risks | unclear_risks
            if invalid_risks:
                errors.append(
                    f"{prefix}: conditionally_verified cannot hide failed or "
                    "unclear risk checks: " + ", ".join(sorted(invalid_risks))
                )

    if final and schema_version == SCHEMA_VERSION:
        validate_evidence_specificity(evidence_specificity_records, errors)
        validate_evidence_anchoring(evidence_anchoring_records, errors)
        validate_failure_computation_artifacts(steps, ledger_path, errors)

    dependency_status_from_step = STEP_TO_DEPENDENCY_STATUS
    step_graph: dict[str, set[str]] = {step_id: set() for step_id in step_ids}
    for owner, dependency_id, declared_dependency_status in step_dependency_claims:
        if dependency_id not in step_status_by_id:
            errors.append(f"{owner}: unknown step dependency {dependency_id}")
            continue
        step_graph.setdefault(owner, set()).add(dependency_id)
        owner_range = step_ranges_by_id.get(owner)
        dependency_range = step_ranges_by_id.get(dependency_id)
        dependency_not_prior = (
            step_position_by_id.get(dependency_id, 0)
            >= step_position_by_id.get(owner, 0)
            if schema_version == SCHEMA_VERSION
            else bool(
                owner_range is not None
                and dependency_range is not None
                and dependency_range[1] >= owner_range[0]
            )
        )
        if dependency_not_prior:
            errors.append(
                f"{owner}: step dependency {dependency_id} is not established before use"
            )
        actual_dependency_status = dependency_status_from_step[
            step_status_by_id[dependency_id]
        ]
        if declared_dependency_status != actual_dependency_status:
            errors.append(
                f"{owner}: dependency {dependency_id} is declared "
                f"{declared_dependency_status}, but its step status implies "
                f"{actual_dependency_status}"
            )

    cycle = find_cycle(step_graph)
    if cycle:
        errors.append("Step dependency cycle: " + " -> ".join(cycle))

    if final and schema_version == SCHEMA_VERSION:
        unrepresented_units = [
            unit_id
            for unit_id in source_units
            if not source_unit_step_ids.get(unit_id)
        ]
        if unrepresented_units:
            shown = ", ".join(unrepresented_units[:8])
            suffix = (
                f" and {len(unrepresented_units) - 8} more"
                if len(unrepresented_units) > 8
                else ""
            )
            errors.append(
                "Source units without any ledger step: " + shown + suffix
            )
        multiply_represented_non_substantive = [
            unit_id
            for unit_id, record in source_units.items()
            if record.get("kind") == "non_substantive"
            and len(source_unit_step_ids.get(unit_id, [])) > 1
        ]
        if multiply_represented_non_substantive:
            errors.append(
                "Non-substantive source units must have exactly one wrapper step: "
                + ", ".join(multiply_represented_non_substantive[:8])
            )

    if valid_range:
        uncovered = [
            line_number
            for line_number in range(start, end + 1)
            if not coverage.get(line_number, [])
        ]
        for first, last in consecutive_ranges(uncovered):
            if first == last:
                errors.append(f"Uncovered source line: {first}")
            else:
                errors.append(f"Uncovered source lines: {first}-{last}")
        for line_number in range(start, end + 1):
            owners = coverage.get(line_number, [])
            if len(owners) > 1:
                errors.append(
                    f"Multiply covered source line {line_number}: {', '.join(owners)}"
                )

    expected_status = expected_unit_status(statuses)
    review = ledger.get("review", {})
    if not isinstance(review, dict):
        errors.append("review must be an object")
        review = {}
    declared_status = review.get("unit_status")
    if not is_enum_value(declared_status, UNIT_STATUSES):
        errors.append(f"Invalid or missing review.unit_status: {declared_status!r}")
    if final and declared_status != expected_status:
        errors.append(
            f"Unit verdict mismatch: declared {declared_status!r}, expected {expected_status!r}"
        )
    if final and expected_status == "not_checked":
        errors.append("A final ledger must contain at least one checked substantive step")

    direct_dependencies: list[dict[str, Any]] = []
    direct_value = review.get("direct_dependencies")
    if not isinstance(direct_value, list):
        errors.append("review.direct_dependencies must be a list")
        direct_value = []
    seen_direct: set[str] = set()
    for index, dependency in enumerate(direct_value, 1):
        record = validate_dependency_record(
            dependency,
            f"review.direct_dependencies[{index}]",
            final,
            errors,
        )
        if record is None:
            continue
        if record.get("kind") == "step":
            errors.append("review.direct_dependencies cannot contain step dependencies")
        dependency_id = record.get("id")
        use_id = record.get("use_id")
        if is_nonempty_string(use_id):
            if use_id in seen_direct:
                errors.append(f"Duplicate direct dependency use: {use_id}")
            seen_direct.add(use_id)
            direct_dependencies.append(record)

    source_reference_dispositions: list[dict[str, Any]] = []
    disposition_value = review.get("source_reference_dispositions")
    if not isinstance(disposition_value, list):
        errors.append("review.source_reference_dispositions must be a list")
        disposition_value = []
    seen_dispositions: set[str] = set()
    context_premise_links: set[tuple[str, str, str, str]] = set()
    for index, disposition in enumerate(disposition_value, 1):
        prefix = f"review.source_reference_dispositions[{index}]"
        if not isinstance(disposition, dict):
            errors.append(f"{prefix} must be an object")
            continue
        occurrence_id = disposition.get("occurrence_id")
        target = disposition.get("target")
        command = disposition.get("command")
        if not is_nonempty_string(occurrence_id):
            errors.append(f"{prefix}.occurrence_id must be a nonempty string")
            continue
        if not occurrence_id.startswith("R-"):
            errors.append(f"{prefix}.occurrence_id must be a parser occurrence ID")
        if not is_nonempty_string(target) or not is_nonempty_string(command):
            errors.append(f"{prefix} requires target and command")
        if occurrence_id in seen_dispositions:
            errors.append(f"Duplicate source-reference disposition: {occurrence_id}")
        seen_dispositions.add(occurrence_id)
        disposition_status = disposition.get("disposition")
        if not is_enum_value(disposition_status, {
            "internal_result",
            "obligation_context",
            "local_step",
            "own_result_identification",
            "navigation",
            "non_load_bearing",
            "unresolved",
        }):
            errors.append(f"{prefix}.disposition is invalid")
        premise_links = disposition.get("premise_links")
        premise_roles = {"internal_result", "obligation_context", "local_step"}
        if final and is_enum_value(disposition_status, premise_roles):
            if not isinstance(premise_links, list) or not premise_links:
                errors.append(
                    f"{prefix} {disposition_status} requires nonempty premise_links"
                )
            else:
                seen_links: set[tuple[str, str]] = set()
                for link_index, link in enumerate(premise_links, 1):
                    link_prefix = f"{prefix}.premise_links[{link_index}]"
                    if not isinstance(link, dict):
                        errors.append(f"{link_prefix} must be an object")
                        continue
                    linked_step_id = link.get("step_id")
                    linked_premise_id = link.get("premise_id")
                    if not is_nonempty_string(
                        linked_step_id
                    ) or not is_nonempty_string(linked_premise_id):
                        errors.append(
                            f"{link_prefix} requires step_id and premise_id"
                        )
                        continue
                    link_key = (linked_step_id, linked_premise_id)
                    if link_key in seen_links:
                        errors.append(
                            f"{prefix} contains duplicate premise link "
                            f"{linked_step_id}/{linked_premise_id}"
                        )
                        continue
                    seen_links.add(link_key)
                    linked_premise = premise_records_by_step.get(
                        linked_step_id, {}
                    ).get(linked_premise_id)
                    if linked_premise is None:
                        errors.append(
                            f"{link_prefix} does not resolve to a premise"
                        )
                    elif (
                        linked_premise.get("source_reference_id") != target
                        or linked_premise.get(
                            "source_reference_occurrence_id"
                        )
                        != occurrence_id
                    ):
                        errors.append(
                            f"{link_prefix} is not named by the linked premise"
                        )
                    else:
                        context_premise_links.add(
                            (
                                occurrence_id,
                                target,
                                linked_step_id,
                                linked_premise_id,
                            )
                        )
                        origin = linked_premise.get("origin")
                        origin_kind = (
                            origin.get("kind")
                            if isinstance(origin, dict)
                            else None
                        )
                        expected_origin = {
                            "internal_result": "internal_result",
                            "obligation_context": "obligation",
                            "local_step": "prior_step",
                        }.get(disposition_status)
                        if origin_kind != expected_origin:
                            errors.append(
                                f"{link_prefix} origin does not match "
                                f"{disposition_status}"
                            )
            if disposition_status == "internal_result":
                dependency_use_id = disposition.get("dependency_use_id")
                if not is_nonempty_string(dependency_use_id):
                    errors.append(
                        f"{prefix}.dependency_use_id is required"
                    )
                else:
                    linked_origins = {
                        origin.get("reference")
                        for link in premise_links
                        if isinstance(link, dict)
                        and isinstance(
                            (
                                origin := premise_records_by_step.get(
                                    link.get("step_id"), {}
                                ).get(link.get("premise_id"), {}).get("origin")
                            ),
                            dict,
                        )
                    }
                    if linked_origins != {dependency_use_id}:
                        errors.append(
                            f"{prefix}.dependency_use_id does not match linked "
                            "premise origins"
                        )
        elif final and premise_links not in (None, []):
            errors.append(
                f"{prefix}.premise_links are allowed only for premise-bearing roles"
            )
        if not is_substantive_string(disposition.get("evidence")):
            errors.append(
                f"{prefix}.evidence must be a nonempty string and substantive, "
                "not a reserved placeholder"
            )
        source_reference_dispositions.append(disposition)

    candidate_dependency_dispositions: list[dict[str, Any]] = []
    try:
        candidate_dependency_dispositions = (
            build_compact_candidate_dispositions(
                review.get("candidate_dependency_dispositions", [])
            )
        )
    except ValueError as exc:
        errors.append(str(exc))
    direct_internal_by_use = {
        str(record.get("use_id")): record
        for record in direct_dependencies
        if (
            record.get("kind") == "internal_result"
            and is_nonempty_string(record.get("use_id"))
        )
    }
    for disposition in candidate_dependency_dispositions:
        if disposition.get("disposition") != "internal_result":
            continue
        use_id = str(disposition.get("dependency_use_id"))
        dependency = direct_internal_by_use.get(use_id)
        if (
            dependency is None
            or dependency.get("id") != disposition.get("candidate_id")
        ):
            errors.append(
                "Candidate dependency disposition "
                f"{disposition.get('candidate_id')} does not match its exact "
                "internal direct-dependency use"
            )

    if final:
        recorded_source_premises = {
            (
                source_occurrence_id,
                source_reference_id,
                step_id,
                premise_id,
            )
            for step_id, premises in premise_records_by_step.items()
            for premise_id, premise in premises.items()
            if is_nonempty_string(
                source_reference_id := premise.get("source_reference_id")
            )
            and is_nonempty_string(
                source_occurrence_id := premise.get(
                    "source_reference_occurrence_id"
                )
            )
        }
        missing_source_links = sorted(
            recorded_source_premises - context_premise_links
        )
        if missing_source_links:
            errors.append(
                "Premises with source reference anchors lack an exact occurrence "
                "link: "
                + ", ".join(
                    f"{occurrence_id}:{target}@{step_id}/{premise_id}"
                    for occurrence_id, target, step_id, premise_id
                    in missing_source_links
                )
            )

    citation_dispositions: list[dict[str, Any]] = []
    citation_value = review.get("citation_dispositions")
    if not isinstance(citation_value, list):
        errors.append("review.citation_dispositions must be a list")
        citation_value = []
    seen_citations: set[str] = set()
    for index, disposition in enumerate(citation_value, 1):
        prefix = f"review.citation_dispositions[{index}]"
        if not isinstance(disposition, dict):
            errors.append(f"{prefix} must be an object")
            continue
        citation_key = disposition.get("key")
        if not is_nonempty_string(citation_key):
            errors.append(f"{prefix}.key must be a nonempty string")
            continue
        if citation_key in seen_citations:
            errors.append(f"Duplicate citation disposition: {citation_key}")
        seen_citations.add(citation_key)
        disposition_status = disposition.get("disposition")
        if not is_enum_value(disposition_status, {
            "external_result",
            "bibliographic_only",
            "unresolved",
        }):
            errors.append(f"{prefix}.disposition is invalid")
        if disposition_status == "external_result":
            if not is_nonempty_string(disposition.get("dependency_id")):
                errors.append(f"{prefix}.dependency_id is required")
            if not is_nonempty_string(disposition.get("dependency_use_id")):
                errors.append(f"{prefix}.dependency_use_id is required")
        if not is_substantive_string(disposition.get("evidence")):
            errors.append(
                f"{prefix}.evidence must be a nonempty string and substantive, "
                "not a reserved placeholder"
            )
        citation_dispositions.append(disposition)

    if final:
        result_use_ids = {
            claim["use_id"]
            for claim in result_dependency_claims
            if is_nonempty_string(claim.get("use_id"))
        }
        missing_direct = sorted(result_use_ids - seen_direct)
        if missing_direct:
            errors.append(
                "Step result dependencies missing from review.direct_dependencies: "
                + ", ".join(missing_direct)
            )
        unused_direct = sorted(seen_direct - result_use_ids)
        if unused_direct:
            errors.append(
                "review.direct_dependencies contains unused results: "
                + ", ".join(unused_direct)
            )

        direct_by_id = {
            dependency.get("use_id"): dependency
            for dependency in direct_dependencies
            if is_nonempty_string(dependency.get("use_id"))
        }
        for claim in result_dependency_claims:
            dependency_id = claim.get("id")
            use_id = claim.get("use_id")
            direct_dependency = direct_by_id.get(use_id)
            if direct_dependency is None:
                continue
            for dependency_field in (
                "id",
                "use_id",
                "kind",
                "conclusion_id",
                "status",
                "needed_form",
                "compatibility_check",
                "statement_support_sha256",
            ):
                if direct_dependency.get(dependency_field) != claim.get(
                    dependency_field
                ):
                    errors.append(
                        f"{claim.get('owner_step')}: dependency use {use_id} "
                        f"{dependency_field} differs from "
                        "review.direct_dependencies"
                    )

    for field in ("explicit_assumptions", "inherited_assumptions", "use_sites"):
        validate_string_list(
            review.get(field),
            f"review.{field}",
            errors,
            substantive=True,
            allow_empty=True,
        )
    review_use_sites = (
        review.get("use_sites") if isinstance(review.get("use_sites"), list) else []
    )
    if final and declared_status != "not_checked":
        validate_string_list(
            review.get("verification_basis"),
            "review.verification_basis",
            errors,
            substantive=True,
        )
        validate_string_list(
            review.get("reviewer_notes"),
            "review.reviewer_notes",
            errors,
            substantive=True,
            allow_empty=True,
        )

    contract_status = review.get("contract_fidelity")
    dependency_closure = review.get("dependency_closure")
    argument_status = review.get("argument_status")
    statement_status = review.get("statement_status")
    if not is_enum_value(contract_status, UNIT_STATUSES):
        errors.append("review.contract_fidelity is invalid or missing")
    if not is_enum_value(dependency_closure, UNIT_STATUSES):
        errors.append("review.dependency_closure is invalid or missing")
    if not is_enum_value(argument_status, ARGUMENT_STATUSES):
        errors.append("review.argument_status is invalid or missing")
    if not is_enum_value(statement_status, STATEMENT_STATUSES):
        errors.append("review.statement_status is invalid or missing")

    conclusions = (
        obligation.get("conclusions", [])
        if isinstance(obligation, dict)
        else []
    )
    conclusions_by_id = {
        record.get("id"): record
        for record in conclusions
        if isinstance(record, dict) and is_nonempty_string(record.get("id"))
    } if isinstance(conclusions, list) else {}
    steps_by_id = {
        step.get("id"): step
        for step in steps
        if isinstance(step, dict) and is_nonempty_string(step.get("id"))
    }
    direct_by_use = {
        dependency.get("use_id"): dependency
        for dependency in direct_dependencies
        if isinstance(dependency, dict)
        and is_nonempty_string(dependency.get("use_id"))
    }

    def support_closure(
        support_step_id: str, support_move_id: str
    ) -> dict[str, set[str]]:
        pending: list[tuple[str, str]] = [(support_step_id, support_move_id)]
        visited: set[tuple[str, str]] = set()
        dependency_uses: set[str] = set()
        obligation_pointers: set[str] = set()
        closure_issues: set[str] = set()

        def consume_premise(step_id: str, premise_id: str) -> None:
            premise = premise_records_by_step.get(step_id, {}).get(premise_id)
            if not isinstance(premise, dict):
                return
            origin = premise.get("origin")
            if not isinstance(origin, dict):
                return
            kind = origin.get("kind")
            reference = origin.get("reference")
            if kind == "obligation" and is_nonempty_string(reference):
                obligation_pointers.add(reference)
            elif is_enum_value(
                kind, {"internal_result", "external_result"}
            ) and is_nonempty_string(reference):
                dependency_uses.add(reference)
            elif kind == "prior_step" and is_nonempty_string(reference):
                prior_step = steps_by_id.get(reference)
                inference = (
                    prior_step.get("inference")
                    if isinstance(prior_step, dict)
                    else None
                )
                prior_move = (
                    inference.get("conclusion_move")
                    if isinstance(inference, dict)
                    else None
                )
                if is_nonempty_string(prior_move):
                    pending.append((reference, prior_move))
                elif final:
                    errors.append(
                        f"{step_id} premise {premise_id}: support closure stops at "
                        f"{reference} without an introduction or derivation inference; "
                        "a non-inferential declaration cannot supply a factual root"
                    )

        while pending:
            step_id, move_id = pending.pop()
            key = (step_id, move_id)
            if key in visited:
                continue
            visited.add(key)
            step = steps_by_id.get(step_id)
            if not isinstance(step, dict):
                continue
            closure_issues.update(
                issue_id
                for issue_id in step.get("issue_ids", [])
                if is_nonempty_string(issue_id)
            )
            inference = step.get("inference")
            moves = inference.get("moves") if isinstance(inference, dict) else []
            move = next(
                (
                    row
                    for row in moves
                    if isinstance(row, dict) and row.get("id") == move_id
                ),
                None,
            ) if isinstance(moves, list) else None
            if not isinstance(move, dict):
                continue
            for prior_move_id in move.get("prior_move_ids", []):
                if is_nonempty_string(prior_move_id):
                    pending.append((step_id, prior_move_id))
            for premise_id in move.get("premise_ids", []):
                if is_nonempty_string(premise_id):
                    consume_premise(step_id, premise_id)
            side_conditions = step.get("side_conditions")
            if isinstance(side_conditions, list):
                for condition in side_conditions:
                    if (
                        not isinstance(condition, dict)
                        or condition.get("generated_by") != move_id
                        or condition.get("status") != "discharged"
                    ):
                        continue
                    discharge = condition.get("discharge")
                    sources = (
                        discharge.get("sources")
                        if isinstance(discharge, dict)
                        else []
                    )
                    if not isinstance(sources, list):
                        continue
                    for source in sources:
                        if not isinstance(source, dict):
                            continue
                        reference = source.get("reference")
                        if not is_nonempty_string(reference):
                            continue
                        if source.get("kind") == "premise":
                            consume_premise(step_id, reference)
                        elif source.get("kind") == "inference_move":
                            pending.append((step_id, reference))
        return {
            "dependency_uses": dependency_uses,
            "obligation_pointers": obligation_pointers,
            "issue_ids": closure_issues,
        }

    conclusion_results_value = review.get("conclusion_results")
    if not isinstance(conclusion_results_value, list):
        errors.append("review.conclusion_results must be an ordered list")
        conclusion_results_value = []
    seen_conclusion_results: set[str] = set()
    conclusion_result_records: list[dict[str, Any]] = []
    all_conclusion_dependency_uses: set[str] = set()
    support_acceptance: dict[str, str] = {}
    support_root = containing_audit_root(ledger_path)
    if support_root is not None:
        support_acceptance, support_review_errors = load_statement_support_review(support_root, ledger)
        if not primary_only:
            errors.extend(support_review_errors)
    for index, raw_result in enumerate(conclusion_results_value, 1):
        prefix = f"review.conclusion_results[{index}]"
        if not isinstance(raw_result, dict):
            errors.append(f"{prefix} must be an object")
            continue
        result = dict(raw_result)
        supplied = statement_support_projection(ledger, raw_result, errors, provisional=primary_only)
        if supplied is not None:
            supplied["acceptance"] = support_acceptance.get(str(result.get("conclusion_id")), "pending")
            result["statement_support"] = supplied
            all_conclusion_dependency_uses.update(supplied["dependency_use_ids"])
            if (final and not primary_only and (ledger.get("independent_check") or {}).get("required")
                    and supplied["acceptance"] != "accepted"):
                errors.append(f"{prefix}.statement_support requires a current accepted immutable supplemental review")
        conclusion_id = result.get("conclusion_id")
        if conclusion_id not in conclusions_by_id:
            errors.append(f"{prefix}.conclusion_id is unknown")
            continue
        if conclusion_id in seen_conclusion_results:
            errors.append(f"duplicate conclusion result {conclusion_id}")
        seen_conclusion_results.add(conclusion_id)
        conclusion_result_records.append(result)
        support = result.get("support")
        if not isinstance(support, dict):
            errors.append(f"{prefix}.support must be an object")
            continue
        step_id = support.get("step_id")
        move_id = support.get("move_id")
        step = steps_by_id.get(step_id)
        if (
            schema_version == SCHEMA_VERSION
            and step_support_role_by_id.get(str(step_id)) == "reuse"
        ):
            errors.append(
                f"{prefix}.support cannot use a reuse-only step to establish a "
                "canonical conclusion"
            )
        inference = step.get("inference") if isinstance(step, dict) else None
        moves = inference.get("moves") if isinstance(inference, dict) else None
        matching_moves = [
            move
            for move in moves
            if isinstance(move, dict) and move.get("id") == move_id
        ] if isinstance(moves, list) else []
        if len(matching_moves) != 1:
            errors.append(
                f"{prefix}.support must name exactly one checked inference move"
            )
            continue
        move = matching_moves[0]
        step_status = step.get("status")
        result_statement_status = result.get("statement_status")
        if not is_enum_value(result_statement_status, STATEMENT_STATUSES):
            errors.append(f"{prefix}.statement_status is invalid")
        claim = conclusions_by_id[conclusion_id].get("claim")
        if (
            result_statement_status in {"established", "conditional"}
            and supplied is None
            and move.get("claim") != claim
        ):
            errors.append(
                f"{prefix} support move must exactly match conclusion {conclusion_id}; "
                + exact_mismatch_detail(claim, move.get("claim"))
            )
        if result_statement_status == "refuted":
            failure = move.get("failure")
            if (
                not isinstance(failure, dict)
                or failure.get("kind") not in REFUTATION_FAILURE_KINDS
            ):
                errors.append(
                    f"{prefix}: a refuted conclusion requires a counterexample "
                    "or contradiction"
                )
            elif failure.get("target") != claim:
                errors.append(
                    f"{prefix}: refutation target must exactly match {conclusion_id}; "
                    + exact_mismatch_detail(claim, failure.get("target"))
                )
        statement_to_step_statuses = {
            "established": {"verified"},
            "conditional": {"conditionally_verified"},
            "refuted": {"incorrect"},
            "not_established": {"gap", "incorrect"},
            "unclear": {"unclear"},
            "not_assessed": {"not_checked"},
        }
        allowed_step_statuses = (
            statement_to_step_statuses.get(result_statement_status, set())
            if isinstance(result_statement_status, str)
            else set()
        )
        supplied_statement = supplied is not None and supplied.get("valid") and result_statement_status in {"established", "conditional"}
        if supplied_statement and result_statement_status == "conditional" and not supplied["extra_conditions"]:
            errors.append(f"{prefix}: a conditional supplemental statement requires explicit extra conditions")
        if not supplied_statement and not is_enum_value(step_status, allowed_step_statuses):
            errors.append(
                f"{prefix}.statement_status is inconsistent with support step "
                f"status {step_status!r}"
            )
        result_contract = result.get("contract_fidelity")
        result_argument = result.get("argument_status")
        result_closure = result.get("dependency_closure")
        if not is_enum_value(result_contract, UNIT_STATUSES):
            errors.append(f"{prefix}.contract_fidelity is invalid")
        if not is_enum_value(result_argument, ARGUMENT_STATUSES):
            errors.append(f"{prefix}.argument_status is invalid")
        if not is_enum_value(result_closure, UNIT_STATUSES):
            errors.append(f"{prefix}.dependency_closure is invalid")
        step_to_argument = {
            "verified": "valid",
            "conditionally_verified": "conditional",
            "gap": "gap",
            "incorrect": "invalid",
            "unclear": "unclear",
            "not_checked": "not_checked",
        }
        expected_result_argument = (
            step_to_argument.get(step_status)
            if isinstance(step_status, str)
            else None
        )
        if final and result_argument != expected_result_argument:
            errors.append(
                f"{prefix}.argument_status must match its support-step evidence"
            )
        if (
            final
            and result_statement_status in {"established", "refuted"}
            and result_contract != "verified"
        ):
            errors.append(
                f"{prefix}: {result_statement_status} requires verified "
                "contract fidelity"
            )
        closure = support_closure(str(step_id), str(move_id))
        dependency_use_ids = validate_string_list(
            result.get("dependency_use_ids"),
            f"{prefix}.dependency_use_ids",
            errors,
            allow_empty=True,
        )
        if len(dependency_use_ids) != len(set(dependency_use_ids)):
            errors.append(f"{prefix}.dependency_use_ids contains duplicates")
        if set(dependency_use_ids) != closure["dependency_uses"]:
            errors.append(
                f"{prefix}.dependency_use_ids do not match the support closure"
            )
        unknown_uses = set(dependency_use_ids) - set(direct_by_use)
        if unknown_uses:
            errors.append(
                f"{prefix}.dependency_use_ids name unknown uses: "
                + ", ".join(sorted(unknown_uses))
            )
        all_conclusion_dependency_uses.update(dependency_use_ids)
        dependency_state = combine_dependency_statuses(
            direct_by_use[use_id].get("status")
            for use_id in dependency_use_ids
            if use_id in direct_by_use
        )
        expected_result_closure = {
            "verified": "verified",
            "conditional": "conditionally_verified",
            "gap": "gap",
            "incorrect": "incorrect",
            "unclear": "unclear",
            "unchecked": "not_checked",
        }[dependency_state]
        if final and result_closure != expected_result_closure:
            errors.append(
                f"{prefix}.dependency_closure must match its exact dependency uses"
            )
        allowed_pointers = set(
            conclusions_by_id[conclusion_id].get("applies_under", [])
        )
        leaked_pointers = closure["obligation_pointers"] - allowed_pointers
        if leaked_pointers:
            errors.append(
                f"{prefix}: support closure uses assumptions outside "
                f"{conclusion_id}.applies_under: "
                + ", ".join(sorted(leaked_pointers))
            )
        result_issues = set(
            validate_issue_id_list(
                result.get("issue_ids"), f"{prefix}.issue_ids", errors
            )
        )
        if not closure["issue_ids"].issubset(result_issues):
            errors.append(
                f"{prefix}.issue_ids omit issues in the support closure"
            )

    missing_conclusion_results = set(conclusions_by_id) - seen_conclusion_results
    extra_conclusion_results = seen_conclusion_results - set(conclusions_by_id)
    if final and missing_conclusion_results:
        errors.append(
            "review.conclusion_results omits conclusions: "
            + ", ".join(sorted(missing_conclusion_results))
        )
    if extra_conclusion_results:
        errors.append(
            "review.conclusion_results contains unknown conclusions: "
            + ", ".join(sorted(extra_conclusion_results))
        )
    if final and all_conclusion_dependency_uses != set(direct_by_use):
        errors.append(
            "Every direct dependency use must belong to at least one conclusion "
            "support closure"
        )

    conclusion_step_id = review.get("conclusion_step_id")
    if len(conclusion_result_records) == 1:
        support = conclusion_result_records[0].get("support")
        support_step_id = (
            support.get("step_id") if isinstance(support, dict) else None
        )
        if final and conclusion_step_id != support_step_id:
            errors.append(
                "For one conclusion, review.conclusion_step_id must equal its "
                "support step"
            )
    elif final and is_nonempty_string(conclusion_step_id):
        errors.append(
            "review.conclusion_step_id must be empty for a multi-conclusion result"
        )

    statement_rank = {
        "established": 0,
        "conditional": 1,
        "not_assessed": 2,
        "unclear": 3,
        "not_established": 4,
        "refuted": 5,
    }
    result_statement_values = [
        result.get("statement_status")
        for result in conclusion_result_records
        if is_enum_value(result.get("statement_status"), STATEMENT_STATUSES)
    ]
    if final and result_statement_values:
        expected_statement_status = max(
            result_statement_values, key=lambda value: statement_rank[value]
        )
        if statement_status != expected_statement_status:
            errors.append(
                "review.statement_status must be the weakest conclusion judgment"
            )
    unresolved_normalization = {
        aspect
        for aspect, normalization_status in normalization_statuses.items()
        if not is_enum_value(normalization_status, {"checked", "not_applicable"})
    }
    if (
        final
        and is_enum_value(contract_status, {"verified", "conditionally_verified"})
        and unresolved_normalization
    ):
        errors.append(
            f"{contract_status} contract fidelity has unresolved "
            "normalization checks: "
            + ", ".join(sorted(unresolved_normalization))
        )
    if final:
        if contract_status == "not_checked":
            errors.append("Final ledger requires a contract-fidelity judgment")
        if dependency_closure == "not_checked":
            errors.append("Final ledger requires a dependency-closure judgment")
        if statement_status == "not_assessed":
            errors.append("Final ledger requires a separate statement-status judgment")

    if (
        final
        and is_enum_value(statement_status, {"established", "refuted"})
        and contract_status != "verified"
    ):
        errors.append(
            f"review.statement_status {statement_status} requires verified "
            "contract fidelity"
        )
    if (
        final
        and statement_status == "conditional"
        and not is_enum_value(
            contract_status, {"verified", "conditionally_verified"}
        )
    ):
        errors.append(
            "review.statement_status conditional requires verified or "
            "conditionally_verified contract fidelity"
        )

    expected_argument = {
        "verified": "valid",
        "conditionally_verified": "conditional",
        "gap": "gap",
        "incorrect": "invalid",
        "unclear": "unclear",
        "not_checked": "not_checked",
    }[expected_status]
    if final and argument_status != expected_argument:
        errors.append(
            f"review.argument_status {argument_status!r} does not match "
            f"the step evidence ({expected_argument!r})"
        )
    if final and declared_status == "verified":
        if contract_status != "verified":
            errors.append("verified unit requires verified contract fidelity")
        if dependency_closure != "verified":
            errors.append("verified unit requires verified dependency closure")
        if statement_status != "established":
            errors.append("verified unit requires statement_status established")
        invalid_direct = [
            record.get("status")
            for record in direct_dependencies
            if not is_enum_value(record.get("status"), {"verified", "not_applicable"})
        ]
        if invalid_direct:
            errors.append("verified unit has nonverified direct dependencies")
    if final and declared_status == "conditionally_verified":
        if not is_enum_value(contract_status, {"verified", "conditionally_verified"}):
            errors.append("conditional unit has failed or unchecked contract fidelity")
        if not is_enum_value(dependency_closure, {"verified", "conditionally_verified"}):
            errors.append("conditional unit has failed or unchecked dependency closure")
        if not is_enum_value(statement_status, {"established", "conditional"}):
            errors.append("conditional unit needs established or conditional statement status")
        failed_direct = [
            record.get("status")
            for record in direct_dependencies
            if is_enum_value(record.get("status"), {"gap", "incorrect", "unclear"})
        ]
        if failed_direct:
            errors.append("conditional unit cannot hide failed direct dependencies")

    raw_independent_check = ledger.get("independent_check")
    if primary_only:
        independent_check = (
            raw_independent_check
            if isinstance(raw_independent_check, dict)
            else {}
        )
    else:
        independent_check = validate_independent_check(
            raw_independent_check,
            final,
            errors,
            primary_ledger_sha256=canonical_primary_ledger_sha256(ledger),
            current_contract=schema_version == SCHEMA_VERSION,
        )
        if independent_check and not independent_check.get("required"):
            if independent_check.get("status") != "not_required":
                errors.append(
                    "non-required independent check must have status not_required"
                )
        if (
            final
            and independent_check.get("required")
            and independent_check.get("status") == "agreed"
            and independent_check.get("challenger_verdict") != declared_status
        ):
            errors.append(
                "independent_check marked agreed but challenger_verdict differs "
                "from unit_status"
            )
        if (
            final
            and independent_check.get("required")
            and is_enum_value(
                independent_check.get("status"), {"agreed", "resolved"}
            )
            and independent_check.get("reconciled_verdict") != declared_status
        ):
            errors.append(
                "independent_check.reconciled_verdict differs from the final "
                "unit_status"
            )

    summary = {
        "ledger": str(ledger_path),
        "unit_id": unit_id,
        "schema_version": schema_version,
        "evidence_contract_version": evidence_contract_version,
        "validation_mode": "final" if final else "draft",
        "validation_scope": {
            "local_record_integrity": (
                "failed"
                if errors
                else (
                    "passed"
                    if final
                    else (
                        "legacy_inspection_only"
                        if legacy_schema
                        else "inspection_only"
                    )
                )
            ),
            "audit_wide_dependency_resolution": (
                "not_performed; run finalize on the audit root"
            ),
        },
        "source_file": str(source),
        "source_reference": str(file_value),
        "source_start": source_info["start_line"],
        "source_end": source_info["end_line"],
        "source_range": f"{source_info['start_line']}-{source_info['end_line']}",
        "coverage_mode": coverage_mode,
        "external_restatement_use_id": (
            external_restatement_use_id
            if coverage_mode == "external_restatement"
            else None
        ),
        "physical_lines": max(0, end - start + 1),
        "steps": len(steps),
        "source_units": len(source_units) if schema_version == SCHEMA_VERSION else None,
        "step_ids": [
            step.get("id")
            for step in steps
            if isinstance(step, dict)
            and isinstance(step.get("id"), str)
            and STEP_ID_RE.fullmatch(step["id"])
        ],
        "obligation_sha256": (
            canonical_sha256(obligation) if isinstance(obligation, dict) else None
        ),
        "obligation_conclusion": (
            obligation.get("conclusion") if isinstance(obligation, dict) else None
        ),
        "obligation_conclusions": (
            [
                {
                    **record,
                    "contract_sha256": canonical_sha256(
                        conclusion_contract_payload(obligation, record["id"])
                    ),
                }
                for record in obligation.get("conclusions", [])
                if isinstance(record, dict)
                and is_nonempty_string(record.get("id"))
                and conclusion_contract_payload(obligation, record["id"])
                is not None
            ]
            if isinstance(obligation, dict)
            and isinstance(obligation.get("conclusions"), list)
            else []
        ),
        "obligation_normalization": (
            obligation.get("normalization_checks")
            if isinstance(obligation, dict)
            else None
        ),
        "obligation_ready": obligation_ready,
        "expected_unit_status": expected_status,
        "declared_unit_status": declared_status,
        "issue_references": sorted(issue_references),
        "issue_links": issue_links,
        "direct_dependencies": direct_dependencies,
        "source_reference_dispositions": source_reference_dispositions,
        "candidate_dependency_dispositions": (
            candidate_dependency_dispositions
        ),
        "citation_dispositions": citation_dispositions,
        "use_sites": review_use_sites,
        "result_dependency_claims": result_dependency_claims,
        "conclusion_results": conclusion_result_records,
        "review_components": {
            "contract_fidelity": contract_status,
            "argument_status": argument_status,
            "statement_status": statement_status,
            "dependency_closure": dependency_closure,
        },
        "obligation_statement_spans": obligation_statement_spans,
        "obligation_context_spans": obligation_context_spans,
        "independent_check": independent_check,
        "errors": len(errors),
    }
    return errors, summary


def cmd_ledger_check(args: argparse.Namespace) -> int:
    ledger_path = args.ledger.resolve()
    errors, summary = check_ledger_data(ledger_path, args.final)
    print(json.dumps(summary, ensure_ascii=False, indent=2))
    if errors:
        for error in errors:
            print(f"ERROR: {error}", file=sys.stderr)
        return 1
    return 0


def load_issue_log(
    root: Path,
) -> tuple[Path, list[dict[str, Any]], int | None, list[str]]:
    errors: list[str] = []
    path, path_valid = canonical_artifact_path(
        root,
        "audit/06_reports/ISSUE_LOG.json",
        "issue log",
        errors,
    )
    if not path_valid:
        return path, [], None, errors
    if not path.is_file():
        return path, [], None, [f"Canonical issue log not found: {path}"]
    try:
        data = json.loads(read_text(path))
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        return path, [], None, [f"Cannot read issue log: {exc}"]
    schema_version = data.get("schema_version") if isinstance(data, dict) else None
    issues = data.get("issues") if isinstance(data, dict) else None
    if schema_version not in {
        SCHEMA_VERSION,
        LEGACY_SCHEMA_VERSION,
    }:
        errors.append(
            f"ISSUE_LOG.json schema_version must be {SCHEMA_VERSION}, or "
            f"{LEGACY_SCHEMA_VERSION} for legacy inspection"
        )
    if not isinstance(issues, list):
        return path, [], schema_version, [
            *errors,
            "ISSUE_LOG.json must contain an issues list",
        ]
    return path, issues, schema_version, errors


RESOLUTION_ARCHIVE_STABLE_FIELDS = (
    "id",
    "severity",
    "confidence",
    "scope",
    "load_bearing",
    "origin_ref",
    "invalidation_kind",
    "affected_result",
    "summary",
    "interface_id",
    "finding_class",
    "affected_layer",
    "evidence_class",
    "resolution_evidence_needed",
)


def resolution_archive_payload_sha256(record: dict[str, Any]) -> str:
    payload = dict(record)
    payload.pop("archive_payload_sha256", None)
    return canonical_sha256(payload)


def confined_history_directory(root: Path) -> tuple[Path, list[str]]:
    """Return the lexical history directory after rejecting redirected ancestors."""
    resolved_root = root.resolve()
    parts = ("audit", "06_reports", "history")
    candidate = resolved_root.joinpath(*parts)
    errors: list[str] = []
    current = resolved_root
    for part in parts:
        current = current / part
        redirect_kind = path_redirect_kind(current)
        if current.exists() and redirect_kind == "symlink":
            errors.append(
                f"Resolution history ancestor cannot be a symlink: {current}"
            )
        elif current.exists() and redirect_kind is not None:
            errors.append(
                "Resolution history ancestor cannot be a filesystem "
                f"redirection ({redirect_kind}): {current}"
            )
    try:
        candidate.resolve(strict=False).relative_to(resolved_root)
    except ValueError:
        errors.append(
            "Resolution history directory resolves outside the audit root"
        )
    return candidate, errors


def proofcheck_temp_path(path: Path) -> Path:
    return path.with_name(f".{path.name}.proofcheck.tmp")


def proofcheck_lock_path(path: Path) -> Path:
    return path.with_name(f".{path.name}.proofcheck.lock")


def stage_text_for_atomic_commit(path: Path, text: str) -> Path:
    """Durably stage UTF-8 text beside its destination."""
    temporary = proofcheck_temp_path(path)
    if temporary.exists() and temporary.is_symlink():
        raise ValueError(f"Refusing a symlinked proofcheck temp file: {temporary}")
    with temporary.open(
        "w", encoding="utf-8", newline="\n"
    ) as stream:
        stream.write(text)
        stream.flush()
        os.fsync(stream.fileno())
    return temporary


def atomic_replace_text(path: Path, text: str) -> None:
    atomic_write_text(path, text)


def atomic_create_text(path: Path, text: str) -> None:
    """Idempotently create one complete file via a fixed staged payload."""
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = proofcheck_temp_path(path)
    lock = proofcheck_lock_path(path)
    expected_sha256 = sha256_text(text)
    lock_record = {
        "transaction_schema_version": 1,
        "target": path.name,
        "expected_sha256": expected_sha256,
    }

    def matching_file(candidate: Path) -> bool:
        return candidate.is_file() and sha256_file(candidate) == expected_sha256

    def read_matching_lock() -> bool:
        try:
            value = json.loads(read_text(lock))
        except (OSError, UnicodeError, json.JSONDecodeError):
            return False
        return (
            isinstance(value, dict)
            and value.get("transaction_schema_version") == 1
            and value.get("target") == path.name
            and value.get("expected_sha256") == expected_sha256
        )

    if path.is_symlink() or temporary.is_symlink() or lock.is_symlink():
        raise ValueError("Refusing a symlinked archive transaction path")
    if path.exists():
        if not matching_file(path):
            raise FileExistsError(path)
        if temporary.exists() and matching_file(temporary):
            temporary.unlink()
        if lock.exists() and read_matching_lock():
            lock.unlink()
        return

    lock_exists = lock.exists()
    if lock_exists and not read_matching_lock():
        raise FileExistsError(
            f"Archive transaction lock belongs to different or invalid content: {lock}"
        )
    if not lock_exists:
        try:
            descriptor = os.open(lock, os.O_CREAT | os.O_EXCL | os.O_WRONLY)
        except FileExistsError:
            if not read_matching_lock():
                raise
        else:
            try:
                payload = (json.dumps(lock_record, sort_keys=True) + "\n").encode(
                    "utf-8"
                )
                offset = 0
                while offset < len(payload):
                    written = os.write(descriptor, payload[offset:])
                    if written <= 0:
                        raise OSError(f"Cannot write archive transaction lock: {lock}")
                    offset += written
                os.fsync(descriptor)
            finally:
                os.close(descriptor)

    committed = False
    try:
        if not matching_file(temporary):
            atomic_write_text(temporary, text)
        if not matching_file(temporary):
            raise OSError(f"Archive staging hash mismatch: {temporary}")
        if path.exists():
            if not matching_file(path):
                raise FileExistsError(path)
        else:
            try:
                os.replace(temporary, path)
            except FileNotFoundError:
                if not matching_file(path):
                    raise
        if not matching_file(path):
            raise OSError(f"Archive commit hash mismatch: {path}")
        committed = True
    finally:
        if committed:
            if temporary.exists() and matching_file(temporary):
                temporary.unlink()
            if lock.exists() and read_matching_lock():
                lock.unlink()


def sealed_file_record(path: Path, stored_file: str) -> dict[str, str]:
    """Return one byte-exact, self-hashing archive record."""
    payload = path.read_bytes()
    return {
        "file": stored_file,
        "sha256": hashlib.sha256(payload).hexdigest(),
        "content_base64": base64.b64encode(payload).decode("ascii"),
    }


def decode_sealed_file_record(
    value: Any,
    label: str,
    errors: list[str],
) -> tuple[str, str, bytes] | None:
    """Validate one byte-exact archive record without touching live evidence."""
    if not isinstance(value, dict):
        errors.append(f"{label} must be an object")
        return None
    file_value = value.get("file")
    digest = value.get("sha256")
    payload = value.get("content_base64")
    if not is_nonempty_string(file_value):
        errors.append(f"{label}.file must be nonempty")
    if not isinstance(digest, str) or not SHA256_RE.fullmatch(digest):
        errors.append(f"{label}.sha256 is invalid")
    if not isinstance(payload, str):
        errors.append(f"{label}.content_base64 must be a string")
        return None
    try:
        raw = base64.b64decode(payload.encode("ascii"), validate=True)
    except (UnicodeEncodeError, binascii.Error, ValueError):
        errors.append(f"{label}.content_base64 is invalid")
        return None
    actual = hashlib.sha256(raw).hexdigest()
    if digest != actual:
        errors.append(f"{label}.sha256 does not match its byte-exact content")
    if not is_nonempty_string(file_value) or not isinstance(digest, str):
        return None
    return str(file_value), digest, raw


def sealed_json_object(
    value: Any,
    label: str,
    errors: list[str],
) -> tuple[str, str, dict[str, Any]] | None:
    decoded = decode_sealed_file_record(value, label, errors)
    if decoded is None:
        return None
    file_value, digest, raw = decoded
    try:
        parsed = json.loads(raw.decode("utf-8-sig"))
    except (UnicodeError, json.JSONDecodeError):
        errors.append(f"{label} is not valid UTF-8 JSON")
        return None
    if not isinstance(parsed, dict):
        errors.append(f"{label} JSON root must be an object")
        return None
    return file_value, digest, parsed


def finalization_artifact_hashes(
    prior_record: dict[str, Any],
    issue_id: str,
    errors: list[str],
) -> dict[str, str]:
    rows = prior_record.get("artifact_manifest")
    if not isinstance(rows, list):
        errors.append(
            f"{issue_id} prior finalization artifact_manifest must be a list"
        )
        return {}
    result: dict[str, str] = {}
    for index, row in enumerate(rows, 1):
        prefix = f"{issue_id} prior artifact_manifest[{index}]"
        if not isinstance(row, dict):
            errors.append(f"{prefix} must be an object")
            continue
        file_value = row.get("file")
        digest = row.get("sha256")
        if (
            not is_nonempty_string(file_value)
            or not isinstance(digest, str)
            or not SHA256_RE.fullmatch(digest)
        ):
            errors.append(f"{prefix} has an invalid file or sha256")
            continue
        if file_value in result:
            errors.append(f"{issue_id} prior artifact is duplicated: {file_value}")
        result[str(file_value)] = digest
    return result


def validate_sealed_audit_artifact(
    value: Any,
    label: str,
    expected_file: str,
    artifact_hashes: dict[str, str],
    errors: list[str],
) -> dict[str, Any] | None:
    decoded = sealed_json_object(value, label, errors)
    if decoded is None:
        return None
    file_value, digest, parsed = decoded
    if file_value != expected_file:
        errors.append(f"{label}.file must be {expected_file}")
    if artifact_hashes.get(file_value) != digest:
        errors.append(
            f"{label} bytes are not bound by the prior finalization manifest"
        )
    return parsed


def archived_ledger_step_projection(
    ledger: dict[str, Any], step_id: Any
) -> dict[str, Any] | None:
    """Project a source-locked step directly from a sealed ledger object."""
    step = next(
        (
            row
            for row in ledger.get("steps", [])
            if isinstance(row, dict) and row.get("id") == step_id
        ),
        None,
    )
    if not isinstance(step, dict):
        return None
    source_unit_id = step.get("source_unit_id")
    source_unit = next(
        (
            row
            for row in ledger.get("source_units", [])
            if isinstance(row, dict) and row.get("id") == source_unit_id
        ),
        None,
    )
    line_range = source_unit.get("lines") if isinstance(source_unit, dict) else None
    if (
        not isinstance(line_range, list)
        or len(line_range) != 2
        or not all(is_int(value) for value in line_range)
    ):
        return None
    start_line, end_line = line_range
    locked_rows = {
        row.get("line"): row.get("text")
        for row in ledger.get("source_lines", [])
        if isinstance(row, dict)
        and is_int(row.get("line"))
        and isinstance(row.get("text"), str)
    }
    if any(line not in locked_rows for line in range(start_line, end_line + 1)):
        return None
    quote = "\n".join(
        locked_rows[line] for line in range(start_line, end_line + 1)
    )
    source = ledger.get("source")
    file_value = source.get("file") if isinstance(source, dict) else None
    if "source_fragments" in ledger:
        location = source_unit_location(ledger, source_unit)
        file_value, start_line, end_line = location["file"], location["start_line"], location["end_line"]
    return {
        "step": step,
        "file": str(file_value),
        "start_line": start_line,
        "end_line": end_line,
        "sha256": sha256_text(quote),
        "quote": quote,
    }


def archived_ledger_move_failure_rows(
    issue: dict[str, Any],
    ledgers: dict[str, dict[str, Any]],
) -> list[list[str]] | None:
    """Recompute the exact report failure row for a sealed ledger-move issue."""
    origin = issue.get("origin_ref")
    if not isinstance(origin, dict) or origin.get("kind") != "ledger_move":
        return None
    unit_id = str(origin.get("unit_id", issue.get("affected_result")))
    ledger = ledgers.get(unit_id)
    if not isinstance(ledger, dict):
        return None
    step_projection = archived_ledger_step_projection(
        ledger, origin.get("step_id")
    )
    if step_projection is None:
        return None
    step = step_projection["step"]
    inference = step.get("inference")
    moves = inference.get("moves") if isinstance(inference, dict) else []
    move = next(
        (
            row
            for row in moves
            if isinstance(row, dict) and row.get("id") == origin.get("move_id")
        ),
        None,
    ) if isinstance(moves, list) else None
    if not isinstance(move, dict):
        return None
    premise_by_id = {
        row.get("id"): row
        for row in step.get("premise_uses", [])
        if isinstance(row, dict) and is_nonempty_string(row.get("id"))
    }
    premises = json.dumps(
        {
            "premises": [
                {
                    "id": premise_id,
                    "claim": premise_by_id.get(premise_id, {}).get("claim"),
                    "origin": premise_by_id.get(premise_id, {}).get("origin"),
                }
                for premise_id in move.get("premise_ids", [])
            ],
            "prior_moves": move.get("prior_move_ids", []),
        },
        ensure_ascii=False,
    )
    failure = move.get("failure")
    failure_evidence = (
        str(failure.get("evidence")) if isinstance(failure, dict) else "none"
    )
    failure_kind = (
        str(failure.get("kind"))
        if isinstance(failure, dict)
        else str(issue.get("invalidation_kind", "none"))
    )
    return [[
        (
            f"{step_projection['file']}:{step_projection['start_line']}-"
            f"{step_projection['end_line']}"
        ),
        str(step_projection["sha256"]),
        json.dumps(step_projection["quote"], ensure_ascii=False),
        unit_id,
        f"{origin.get('step_id')}/{origin.get('move_id')}",
        str(move.get("claim", "none")),
        str(move.get("rule", "none")),
        premises,
        failure_evidence,
        failure_kind,
    ]]


def sealed_prerequisite_status(value: Any) -> str:
    """Derive prerequisite applicability from a sealed, previously final row."""
    if not isinstance(value, list) or not value:
        return "unchecked"
    mapped = {
        "satisfied": "passed",
        "not_satisfied": "gap",
        "partial": "conditional",
        "unclear": "unclear",
    }
    statuses = [
        mapped.get(str(row.get("status")), "unchecked")
        for row in value
        if isinstance(row, dict)
    ]
    nonclean = [status for status in statuses if status != "passed"]
    return combine_dependency_statuses(nonclean) if nonclean else "passed"


def legacy_archived_dependency_edge_hashes(
    prior_registry: dict[str, Any],
    prior_report_text: str,
    issue_id: str,
    errors: list[str],
    edge_output: dict[str, dict[str, Any]] | None = None,
) -> dict[str, str]:
    """Reconstruct schema-one closure edges from its sealed report."""
    columns = [
        "Dependent",
        "Use ID",
        "Dependency",
        "Dependency conclusion",
        "Kind",
        "Source status",
        "Applicability status",
        "Effective status",
        "Issue IDs",
    ]
    section = report_section(prior_report_text, "## Dependency closure")
    tables = markdown_tables(section or "")
    table = next(
        (candidate for candidate in tables if candidate and candidate[0] == columns),
        None,
    )
    if table is None:
        errors.append(
            f"{issue_id} sealed prior report lacks the dependency-closure table"
        )
        return {}
    report_by_use: dict[str, list[str]] = {}
    for index, row in enumerate(table[2:], 1):
        if len(row) != len(columns):
            errors.append(
                f"{issue_id} sealed dependency row {index} has invalid width"
            )
            continue
        use_id = row[1]
        if not is_nonempty_string(use_id) or use_id in report_by_use:
            errors.append(
                f"{issue_id} sealed dependency report has an invalid or "
                f"duplicate use ID: {use_id}"
            )
            continue
        report_by_use[use_id] = row

    normalized_by_use: dict[str, dict[str, Any]] = {}

    def add_edge(
        use: Any,
        *,
        kind: str,
        dependency_id: Any,
        dependency_conclusion_id: Any,
        prerequisite_map: Any,
        source_evidence: Any,
        source_status: Any | None = None,
    ) -> None:
        if not isinstance(use, dict) or not is_nonempty_string(use.get("use_id")):
            return
        use_id = str(use["use_id"])
        if use_id in normalized_by_use:
            errors.append(
                f"{issue_id} sealed dependency registry duplicates use ID {use_id}"
            )
            return
        report_row = report_by_use.get(use_id)
        if report_row is None:
            errors.append(
                f"{issue_id} sealed dependency registry use {use_id} is absent "
                "from the prior report"
            )
            return
        expected_conclusion = (
            str(dependency_conclusion_id)
            if dependency_conclusion_id is not None
            else "none"
        )
        expected_identity = [
            str(use.get("dependent_unit")),
            use_id,
            str(dependency_id),
            expected_conclusion,
            kind,
        ]
        if report_row[:5] != expected_identity:
            errors.append(
                f"{issue_id} sealed dependency report identity disagrees with "
                f"registry use {use_id}"
            )
            return
        if source_status is not None and report_row[5] != source_status:
            errors.append(
                f"{issue_id} sealed dependency report source status disagrees "
                f"with registry use {use_id}"
            )
        if report_row[7] != str(use.get("status")):
            errors.append(
                f"{issue_id} sealed dependency report effective status disagrees "
                f"with registry use {use_id}"
            )
        if report_row[8] != canonical_id_field(use.get("issue_ids", [])):
            errors.append(
                f"{issue_id} sealed dependency report issue IDs disagree with "
                f"registry use {use_id}"
            )
        normalized_by_use[use_id] = {
            "dependent_unit": use.get("dependent_unit"),
            "use_id": use_id,
            "dependency_id": dependency_id,
            "dependency_conclusion_id": dependency_conclusion_id,
            "kind": kind,
            "source_status": report_row[5],
            "applicability_status": report_row[6],
            "effective_status": report_row[7],
            "step_ids": use.get("step_ids", []),
            "issue_ids": use.get("issue_ids", []),
            "compatibility_checks": use.get("compatibility_checks", []),
            "prerequisite_map": prerequisite_map,
            "source_evidence": source_evidence,
        }

    internal_rows = prior_registry.get("internal_uses")
    if isinstance(internal_rows, list):
        for use in internal_rows:
            add_edge(
                use,
                kind="internal_result",
                dependency_id=(
                    use.get("dependency_id") if isinstance(use, dict) else None
                ),
                dependency_conclusion_id=(
                    use.get("dependency_conclusion_id")
                    if isinstance(use, dict)
                    else None
                ),
                prerequisite_map=[],
                source_evidence=[],
            )
    external_results = prior_registry.get("external_results")
    if isinstance(external_results, list):
        for result in external_results:
            if not isinstance(result, dict):
                continue
            uses = result.get("uses")
            if not isinstance(uses, list):
                continue
            for use in uses:
                add_edge(
                    use,
                    kind="external_result",
                    dependency_id=result.get("id"),
                    dependency_conclusion_id=None,
                    prerequisite_map=(
                        use.get("prerequisite_map", [])
                        if isinstance(use, dict)
                        else []
                    ),
                    source_evidence=result.get("source_evidence", []),
                    source_status=result.get("status"),
                )
    if edge_output is not None:
        edge_output.update(normalized_by_use)
    return {
        use_id: canonical_sha256(edge)
        for use_id, edge in normalized_by_use.items()
    }


def archived_statement_support_summaries(
    ledgers: dict[str, dict[str, Any]], records: Any,
    artifact_hashes: dict[str, str], errors: list[str],
) -> dict[str, dict[str, Any]]:
    sealed = {}
    if not isinstance(records, list):
        errors.append("Archived statement_support_reviews must be a sealed-member list")
        records = []
    for record in records:
        decoded = sealed_json_object(record, "Archived supplemental review", errors)
        if decoded is None:
            continue
        name, digest, content = decoded
        if artifact_hashes.get(name) != digest or name in sealed:
            errors.append("Archived supplemental review bytes must be unique and bound by prior finalization")
        sealed[name] = (digest, content)
    expected_files = set()
    summaries = {}
    for unit_id, ledger in ledgers.items():
        raw_results = (ledger.get("review") or {}).get("conclusion_results", [])
        if not any(isinstance(row, dict) and "statement_support" in row for row in raw_results):
            continue
        check = ledger.get("independent_check") or {}
        for field in ("initial_response", "statement_support_review"):
            reference = check.get(field)
            if not isinstance(reference, dict) or reference.get("artifact") not in sealed:
                errors.append(f"Archived {unit_id} requires its sealed {field}")
                continue
            expected_files.add(reference["artifact"])
            if sealed[reference["artifact"]][0] != reference.get("sha256"):
                errors.append(f"Archived {unit_id} {field} disagrees with its sealed bytes")
        reference = check.get("statement_support_review") or {}
        record = sealed.get(reference.get("artifact"), (None, {}))[1]
        packet = record.get("packet") or {}
        before = len(errors)
        try:
            if packet.get("statement_supports") != statement_support_proposals(ledger):
                errors.append(f"Archived {unit_id} supplemental review has stale target or support")
        except ValueError as exc:
            errors.append(str(exc))
        if packet.get("initial_response") != check.get("initial_response"):
            errors.append(f"Archived {unit_id} supplemental review lost its original blind response")
        errors.extend(statement_support_response_errors(record.get("response"), packet))
        accepted = {row.get("conclusion_id"): row.get("assessment") for row in (record.get("response") or {}).get("assessments", []) if isinstance(row, dict)}
        results = []
        for raw in raw_results:
            result = dict(raw)
            support = statement_support_projection(ledger, raw, errors)
            if support is not None:
                support["acceptance"] = accepted.get(result.get("conclusion_id"), "pending") if len(errors) == before else "pending"
                if support["acceptance"] != "accepted":
                    errors.append(f"Archived {unit_id} support lacks accepted preserved review")
                result["statement_support"] = support
            results.append(result)
        summaries[unit_id] = {"conclusion_results": results}
    if set(sealed) != expected_files:
        errors.append("Archived supplemental review members must exactly cover the sealed support-bearing ledgers")
    return summaries


def archived_dependency_edge_hashes(
    prior_registry: dict[str, Any],
    ledgers: dict[str, dict[str, Any]],
    issue_id: str,
    errors: list[str],
    required_use_ids: set[str] | None = None,
    edge_output: dict[str, dict[str, Any]] | None = None,
    support_summaries: dict[str, dict[str, Any]] | None = None,
) -> dict[str, str]:
    """Reconstruct closure-edge hashes from sealed registry and ledger JSON."""
    normalized_by_use: dict[str, dict[str, Any]] = {}

    def add_edge(
        use: Any,
        *,
        kind: str,
        dependency_id: Any,
        dependency_conclusion_id: Any,
        prerequisite_map: Any,
        source_evidence: Any,
        source_status: Any,
    ) -> None:
        if not isinstance(use, dict) or not is_nonempty_string(use.get("use_id")):
            return
        use_id = str(use["use_id"])
        if required_use_ids is not None and use_id not in required_use_ids:
            return
        if use_id in normalized_by_use:
            errors.append(
                f"{issue_id} sealed dependency registry duplicates use ID {use_id}"
            )
            return
        local_errors: list[str] = []
        compatibility, _ = validate_compatibility_matrix(
            use.get("compatibility_checks"),
            f"sealed dependency {use_id}.compatibility_checks",
            local_errors,
        )
        errors.extend(f"{issue_id} {message}" for message in local_errors)
        applicability = compatibility
        if kind == "external_result":
            applicability = combine_dependency_statuses(
                (
                    compatibility,
                    sealed_prerequisite_status(prerequisite_map),
                )
            )
            if applicability == "verified":
                applicability = "passed"
        effective = combine_dependency_statuses(
            (str(source_status), applicability)
        )
        if use.get("status") != effective:
            errors.append(
                f"{issue_id} sealed dependency {use_id} status disagrees "
                f"with its source and applicability status"
            )
        normalized_by_use[use_id] = {
            "dependent_unit": use.get("dependent_unit"),
            "use_id": use_id,
            "dependency_id": dependency_id,
            "dependency_conclusion_id": dependency_conclusion_id,
            "kind": kind,
            "source_status": source_status,
            "applicability_status": applicability,
            "effective_status": effective,
            "step_ids": use.get("step_ids", []),
            "issue_ids": use.get("issue_ids", []),
            "compatibility_checks": use.get("compatibility_checks", []),
            "prerequisite_map": prerequisite_map,
            "source_evidence": source_evidence,
        }

    internal_rows = prior_registry.get("internal_uses")
    if isinstance(internal_rows, list):
        for use in internal_rows:
            if not isinstance(use, dict):
                continue
            if (
                required_use_ids is not None
                and str(use.get("use_id")) not in required_use_ids
            ):
                continue
            dependency_id = use.get("dependency_id")
            dependency_ledger = ledgers.get(str(dependency_id), {})
            dependency_review = dependency_ledger.get("review")
            dependency_summary = {
                "conclusion_results": (
                    dependency_review.get("conclusion_results", [])
                    if isinstance(dependency_review, dict)
                    else []
                )
            }
            if support_summaries and str(dependency_id) in support_summaries:
                dependency_summary = support_summaries[str(dependency_id)]
            conclusion_id = use.get("dependency_conclusion_id")
            source_status = internal_dependency_status(
                dependency_summary, str(conclusion_id)
            )
            selected_support = None
            if "statement_support_sha256" in use:
                selected_support = selected_statement_support(dependency_summary, str(conclusion_id), use["statement_support_sha256"])
                condition_rows = use.get("statement_support_conditions", [])
                if (selected_support is None or selected_support.get("acceptance") != "accepted"
                        or not isinstance(condition_rows, list)
                        or sorted(str(row.get("condition")) for row in condition_rows if isinstance(row, dict)) != sorted(selected_support.get("extra_conditions", []))):
                    errors.append(f"{issue_id} sealed selected support is missing, stale, or lacks its exact condition map")
                    source_status = "unchecked"
                else:
                    source_status = combine_dependency_statuses([
                        {"satisfied": "verified", "partial": "conditional", "not_satisfied": "incorrect", "unclear": "unclear"}.get(row.get("status"), "unchecked")
                        for row in condition_rows
                    ] or ["verified"])
            if not dependency_ledger:
                errors.append(
                    f"{issue_id} sealed dependency {use.get('use_id')} "
                    f"lacks source ledger {dependency_id}"
                )
            add_edge(
                use,
                kind="internal_result",
                dependency_id=dependency_id,
                dependency_conclusion_id=conclusion_id,
                prerequisite_map=[],
                source_evidence=[],
                source_status=source_status,
            )
            if selected_support is not None and str(use.get("use_id")) in normalized_by_use:
                normalized_by_use[str(use["use_id"])]["statement_support"] = selected_support
                normalized_by_use[str(use["use_id"])]["statement_support_conditions"] = use.get("statement_support_conditions", [])
    external_results = prior_registry.get("external_results")
    if isinstance(external_results, list):
        for result in external_results:
            if not isinstance(result, dict):
                continue
            uses = result.get("uses")
            if not isinstance(uses, list):
                continue
            for use in uses:
                add_edge(
                    use,
                    kind="external_result",
                    dependency_id=result.get("id"),
                    dependency_conclusion_id=None,
                    prerequisite_map=(
                        use.get("prerequisite_map", [])
                        if isinstance(use, dict)
                        else []
                    ),
                    source_evidence=result.get("source_evidence", []),
                    source_status=result.get("status"),
                )
    if edge_output is not None:
        edge_output.update(normalized_by_use)
    return {
        use_id: canonical_sha256(edge)
        for use_id, edge in normalized_by_use.items()
    }


def archived_structured_failure_rows(
    issue: dict[str, Any],
    ledgers: dict[str, dict[str, Any]],
    ledger_files: dict[str, str],
    dependency_edges: dict[str, dict[str, Any]],
    sealed_sources: dict[str, bytes],
    root: Path,
) -> list[list[str]] | None:
    """Rebuild dependency and obligation failures from sealed canonical JSON."""
    origin = issue.get("origin_ref")
    if not isinstance(origin, dict):
        return None
    kind = origin.get("kind")
    if kind not in {"dependency_use", "obligation_pointer"}:
        return None
    affected_result = str(issue.get("affected_result"))
    unit_id = str(origin.get("unit_id", affected_result))
    ledger = ledgers.get(unit_id)
    if not isinstance(ledger, dict):
        return None
    origin_reference = compact_json_value(
        {
            key: value
            for key, value in origin.items()
            if key != "evidence_spans"
        }
    )
    claim = "none"
    rule = str(kind)
    premises = "none"
    failure_evidence = "none"
    failure_kind = str(issue.get("invalidation_kind", "none"))
    projections: list[dict[str, Any]] = []

    if kind == "dependency_use":
        use_id = origin.get("use_id")
        direct_dependencies = ledger.get("review", {}).get(
            "direct_dependencies", []
        )
        matches = [
            row
            for row in direct_dependencies
            if isinstance(row, dict) and row.get("use_id") == use_id
        ] if isinstance(direct_dependencies, list) else []
        edge = dependency_edges.get(str(use_id))
        if len(matches) != 1 or not isinstance(edge, dict):
            return None
        direct = matches[0]
        owner_step = next(
            (
                step.get("id")
                for step in ledger.get("steps", [])
                if isinstance(step, dict)
                and step.get("status") != "non_substantive"
                and any(
                    isinstance(dependency, dict)
                    and dependency.get("use_id") == use_id
                    for dependency in step.get("dependencies", [])
                )
            ),
            None,
        )
        projection = archived_ledger_step_projection(ledger, owner_step)
        if projection is None:
            return None
        projections = [projection]
        claim = str(direct.get("needed_form", "none"))
        rule = str(direct.get("compatibility_check", "dependency_use"))
        premises = json.dumps(
            {
                "dependency_id": direct.get("id"),
                "conclusion_id": direct.get("conclusion_id"),
                "needed_form": direct.get("needed_form"),
            },
            ensure_ascii=False,
        )
        failure_evidence = json.dumps(
            {
                "source_status": edge.get("source_status"),
                "applicability_status": edge.get("applicability_status"),
                "effective_status": edge.get("effective_status"),
                "issue_ids": edge.get("issue_ids"),
                "nonpassing_compatibility_checks": [
                    {
                        "aspect": row.get("aspect"),
                        "status": row.get("status"),
                        "evidence": row.get("evidence"),
                        "issue_ids": row.get("issue_ids"),
                    }
                    for row in edge.get("compatibility_checks", [])
                    if isinstance(row, dict)
                    and row.get("status")
                    not in {"passed", "not_applicable"}
                ],
                "nonpassing_prerequisites": [
                    {
                        "prerequisite": row.get("prerequisite"),
                        "status": row.get("status"),
                        "manuscript_evidence": row.get(
                            "manuscript_evidence"
                        ),
                        "evidence_spans": row.get("evidence_spans"),
                        "issue_ids": row.get("issue_ids"),
                    }
                    for row in edge.get("prerequisite_map", [])
                    if isinstance(row, dict)
                    and row.get("status") != "satisfied"
                ],
                "source_evidence": (
                    edge.get("source_evidence", [])
                    if edge.get("source_status") != "verified"
                    else []
                ),
            },
            ensure_ascii=False,
        )
        failure_kind = str(direct.get("status", failure_kind))
    else:
        obligation = ledger.get("obligation")
        if not isinstance(obligation, dict):
            return None
        found, pointer_value = resolve_json_pointer(
            obligation, origin.get("pointer")
        )
        if not found:
            return None
        claim = json.dumps(pointer_value, ensure_ascii=False)
        premises = json.dumps(
            {"obligation_pointer": origin.get("pointer")},
            ensure_ascii=False,
        )
        failure_evidence = (
            "The issue is anchored to this exact normalized obligation "
            "field and its source-locked statement context."
        )
        spans = nested_locked_spans(pointer_value)
        if not spans:
            spans = [
                span
                for field in ("statement_spans", "context_spans")
                for span in (
                    obligation.get(field)
                    if isinstance(obligation.get(field), list)
                    else []
                )
                if isinstance(span, dict)
            ]
        ledger_file = ledger_files.get(unit_id)
        ledger_path = (
            resolve_stored_path(ledger_file, root)
            if is_nonempty_string(ledger_file)
            else None
        )
        for span in spans:
            file_value = span.get("file")
            start_line = span.get("start_line")
            end_line = span.get("end_line")
            if (
                ledger_path is None
                or not is_nonempty_string(file_value)
                or not is_int(start_line)
                or not is_int(end_line)
                or start_line < 1
                or end_line < start_line
            ):
                continue
            target = resolve_stored_path(str(file_value), ledger_path.parent)
            source_bytes = next(
                (
                    raw
                    for stored, raw in sealed_sources.items()
                    if resolve_stored_path(stored, root) == target
                ),
                None,
            )
            try:
                lines = (
                    source_bytes.decode("utf-8-sig").splitlines()
                    if source_bytes is not None
                    else []
                )
            except UnicodeError:
                lines = []
            if end_line > len(lines):
                continue
            quote = "\n".join(lines[start_line - 1 : end_line])
            projections.append(
                {
                    "file": str(file_value),
                    "start_line": start_line,
                    "end_line": end_line,
                    "sha256": sha256_text(quote),
                    "quote": quote,
                }
            )

    if not projections:
        return [[
            origin_reference,
            "none",
            "none",
            unit_id,
            origin_reference,
            claim,
            rule,
            premises,
            failure_evidence,
            failure_kind,
        ]]
    return [
        [
            f"{row['file']}:{row['start_line']}-{row['end_line']}",
            str(row["sha256"]),
            json.dumps(row["quote"], ensure_ascii=False),
            unit_id,
            origin_reference,
            claim,
            rule,
            premises,
            failure_evidence,
            failure_kind,
        ]
        for row in projections
    ]


def validate_resolution_archive_provenance(
    archive: dict[str, Any],
    archived_issue: dict[str, Any],
    prior_record: dict[str, Any],
    required_units: list[str],
    root: Path,
    issue_id: str,
    errors: list[str],
) -> dict[str, dict[str, Any]]:
    """Bind historical issue evidence to one passed, byte-exact audit state."""
    artifact_hashes = finalization_artifact_hashes(
        prior_record, issue_id, errors
    )
    prior_artifacts = archive.get("prior_artifacts")
    if not isinstance(prior_artifacts, dict):
        errors.append(f"{issue_id} resolution archive needs prior_artifacts")
        prior_artifacts = {}

    prior_manifest = validate_sealed_audit_artifact(
        prior_artifacts.get("manifest"),
        f"{issue_id} prior_artifacts.manifest",
        "AUDIT_MANIFEST.json",
        artifact_hashes,
        errors,
    )
    # The manifest binds challenge-contract metadata that older and current
    # finalization records may omit. Only that known representation difference
    # is permitted; explicit versions and all other fields must agree.
    archived_protocol = archive.get("protocol")
    manifest_protocol = prior_manifest.get("protocol") if isinstance(prior_manifest, dict) else None
    finalized_protocol = prior_record.get("protocol")
    expected_finalized = dict(archived_protocol) if isinstance(archived_protocol, dict) else {}
    if isinstance(finalized_protocol, dict) and "challenge_contract_version" not in finalized_protocol:
        expected_finalized.pop("challenge_contract_version", None)
    if (not isinstance(archived_protocol, dict)
            or archived_protocol != manifest_protocol
            or finalized_protocol != expected_finalized):
        errors.append(f"{issue_id} archived protocol disagrees with its bound prior manifest or finalization")
    if isinstance(prior_manifest, dict):
        try:
            challenge_contract_version(prior_manifest)
        except ValueError as exc:
            errors.append(f"{issue_id} archived protocol: {exc}")
    prior_issue_log = validate_sealed_audit_artifact(
        prior_artifacts.get("issue_log"),
        f"{issue_id} prior_artifacts.issue_log",
        "audit/06_reports/ISSUE_LOG.json",
        artifact_hashes,
        errors,
    )
    prior_report_text: str | None = None
    report_record = decode_sealed_file_record(
        prior_artifacts.get("final_report"),
        f"{issue_id} prior_artifacts.final_report",
        errors,
    )
    if report_record is not None:
        report_file, report_digest, report_bytes = report_record
        if report_file != preferred_report_path(prior_manifest or {}):
            errors.append(
                f"{issue_id} prior_artifacts.final_report.file is invalid"
            )
        if artifact_hashes.get(report_file) != report_digest:
            errors.append(
                f"{issue_id} prior_artifacts.final_report bytes are not bound "
                "by the prior finalization manifest"
            )
        try:
            decoded_report = report_bytes.decode("utf-8-sig")
            prior_report_text = (
                None if report_file.endswith(".html")
                else active_markdown_text(decoded_report))
        except UnicodeError:
            errors.append(
                f"{issue_id} prior_artifacts.final_report is not UTF-8"
            )

    inventory_file = (
        prior_manifest.get("inventory_file")
        if isinstance(prior_manifest, dict)
        else None
    )
    registry_file = (
        prior_manifest.get("dependency_registry")
        if isinstance(prior_manifest, dict)
        else None
    )
    interface_registry_file = (
        prior_manifest.get("method_interface_registry")
        if isinstance(prior_manifest, dict)
        else None
    )
    if not is_nonempty_string(inventory_file):
        errors.append(f"{issue_id} prior manifest inventory_file is invalid")
        inventory_file = "<invalid-inventory>"
    if not is_nonempty_string(registry_file):
        errors.append(
            f"{issue_id} prior manifest dependency_registry is invalid"
        )
        registry_file = "<invalid-registry>"
    if not is_nonempty_string(interface_registry_file):
        errors.append(
            f"{issue_id} prior manifest method_interface_registry is invalid"
        )
        interface_registry_file = "<invalid-interface-registry>"
    prior_inventory = validate_sealed_audit_artifact(
        prior_artifacts.get("inventory"),
        f"{issue_id} prior_artifacts.inventory",
        str(inventory_file),
        artifact_hashes,
        errors,
    )
    prior_registry = validate_sealed_audit_artifact(
        prior_artifacts.get("dependency_registry"),
        f"{issue_id} prior_artifacts.dependency_registry",
        str(registry_file),
        artifact_hashes,
        errors,
    )
    prior_interface_registry = validate_sealed_audit_artifact(
        prior_artifacts.get("method_interface_registry"),
        f"{issue_id} prior_artifacts.method_interface_registry",
        str(interface_registry_file),
        artifact_hashes,
        errors,
    )

    if isinstance(prior_manifest, dict):
        if prior_manifest.get("protocol") != archive.get("protocol"):
            errors.append(
                f"{issue_id} archived manifest protocol disagrees with archive"
            )
        snapshot = prior_manifest.get("source_snapshot")
        if (
            not isinstance(snapshot, dict)
            or snapshot.get("sha256")
            != archive.get("source_snapshot_sha256")
        ):
            errors.append(
                f"{issue_id} archived manifest source snapshot disagrees "
                "with archive"
            )
    if isinstance(prior_issue_log, dict):
        if prior_issue_log.get("schema_version") != SCHEMA_VERSION:
            errors.append(
                f"{issue_id} archived issue log must use schema {SCHEMA_VERSION}"
            )
        issue_rows = prior_issue_log.get("issues")
        matching_issues = [
            row
            for row in issue_rows
            if isinstance(row, dict) and row.get("id") == issue_id
        ] if isinstance(issue_rows, list) else []
        if len(matching_issues) != 1 or matching_issues[0] != archived_issue:
            errors.append(
                f"{issue_id} archived issue is not the exact prior issue-log member"
            )

    ledgers_value = prior_artifacts.get("ledgers")
    if not isinstance(ledgers_value, list):
        errors.append(f"{issue_id} prior_artifacts.ledgers must be a list")
        ledgers_value = []
    ledgers: dict[str, dict[str, Any]] = {}
    ledger_files: dict[str, str] = {}
    ledger_hashes: dict[str, str] = {}
    for index, value in enumerate(ledgers_value, 1):
        label = f"{issue_id} prior_artifacts.ledgers[{index}]"
        decoded = sealed_json_object(value, label, errors)
        if decoded is None:
            continue
        file_value, digest, ledger = decoded
        if artifact_hashes.get(file_value) != digest:
            errors.append(
                f"{label} bytes are not bound by the prior finalization manifest"
            )
        unit_id = ledger.get("unit_id")
        if not is_nonempty_string(unit_id):
            errors.append(f"{label} has no unit_id")
            continue
        if unit_id in ledgers:
            errors.append(f"{issue_id} archived ledger is duplicated: {unit_id}")
            continue
        ledgers[str(unit_id)] = ledger
        ledger_files[str(unit_id)] = file_value
        ledger_hashes[str(unit_id)] = digest
    if not set(required_units).issubset(ledgers):
        errors.append(
            f"{issue_id} archived ledgers must cover every required unit"
        )
    if archive.get("ledger_sha256s") != ledger_hashes:
        errors.append(
            f"{issue_id} archive ledger_sha256s disagree with sealed ledgers"
        )
    support_summaries = archived_statement_support_summaries(
        ledgers, prior_artifacts.get("statement_support_reviews", []), artifact_hashes, errors,
    )

    if isinstance(prior_artifacts.get("inventory"), dict):
        inventory_digest = prior_artifacts["inventory"].get("sha256")
        if archive.get("inventory_sha256") != inventory_digest:
            errors.append(
                f"{issue_id} archive inventory_sha256 disagrees with sealed inventory"
            )
    if isinstance(prior_artifacts.get("dependency_registry"), dict):
        registry_digest = prior_artifacts["dependency_registry"].get("sha256")
        if archive.get("dependency_registry_sha256") != registry_digest:
            errors.append(
                f"{issue_id} archive dependency_registry_sha256 disagrees "
                "with sealed registry"
            )
    normalized_edges: dict[str, dict[str, Any]] = {}
    legacy_archive_semantics = False
    required_closure = archive.get("required_closure")
    required_rows = (
        required_closure.get("dependency_uses")
        if isinstance(required_closure, dict)
        else []
    )
    required_use_ids = {
        str(row.get("use_id"))
        for row in required_rows
        if isinstance(row, dict) and is_nonempty_string(row.get("use_id"))
    } if isinstance(required_rows, list) else set()
    if prior_inventory is None or prior_registry is None:
        errors.append(
            f"{issue_id} resolution archive lacks a usable prior inventory "
            "or dependency registry"
        )
    else:
        internal_rows = prior_registry.get("internal_uses")
        support_units = {
            str(row.get("dependency_id"))
            for row in internal_rows
            if isinstance(row, dict)
            and row.get("use_id") in required_use_ids
            and is_nonempty_string(row.get("dependency_id"))
        } if isinstance(internal_rows, list) else set()
        expected_ledger_units = set(required_units) | support_units
        legacy_archive_semantics = bool(
            support_units - set(required_units)
            and set(ledgers) == set(required_units)
            and not protocol_matches_current(archive.get("protocol"))
            and prior_report_text is not None
        )
        if legacy_archive_semantics:
            normalized_edge_hashes = legacy_archived_dependency_edge_hashes(
                prior_registry,
                prior_report_text,
                issue_id,
                errors,
                normalized_edges,
            )
        else:
            normalized_edge_hashes = archived_dependency_edge_hashes(
                prior_registry,
                ledgers,
                issue_id,
                errors,
                required_use_ids,
                normalized_edges,
                support_summaries,
            )
        if isinstance(required_rows, list):
            for row in required_rows:
                if not isinstance(row, dict) or not is_nonempty_string(
                    row.get("use_id")
                ):
                    continue
                use_id = str(row["use_id"])
                if row.get("edge_sha256") != normalized_edge_hashes.get(use_id):
                    errors.append(
                        f"{issue_id} archived dependency edge hash for {use_id} "
                        "does not match the sealed normalized closure edge"
                    )
            if (
                not legacy_archive_semantics
                and set(ledgers) != expected_ledger_units
            ):
                errors.append(
                    f"{issue_id} archived ledgers must cover exactly the "
                    "required units and internal dependency sources"
                )

    prior_interfaces: dict[str, dict[str, Any]] = {}
    if isinstance(prior_interface_registry, dict):
        interface_rows = prior_interface_registry.get("interfaces")
        if not isinstance(interface_rows, list):
            errors.append(
                f"{issue_id} archived method-interface registry has no "
                "interfaces list"
            )
        else:
            for row in interface_rows:
                if not isinstance(row, dict) or not is_nonempty_string(
                    row.get("id")
                ):
                    continue
                interface_id = str(row["id"])
                if interface_id in prior_interfaces:
                    errors.append(
                        f"{issue_id} archived method-interface registry "
                        f"duplicates {interface_id}"
                    )
                    continue
                prior_interfaces[interface_id] = row

    prior_global_checks: dict[str, dict[str, Any]] = {}
    if isinstance(prior_manifest, dict):
        completion = prior_manifest.get("completion")
        global_pass = (
            completion.get("global_consistency_pass")
            if isinstance(completion, dict)
            else None
        )
        check_rows = (
            global_pass.get("checks")
            if isinstance(global_pass, dict)
            else None
        )
        if isinstance(check_rows, list):
            for row in check_rows:
                if not isinstance(row, dict) or not is_nonempty_string(
                    row.get("aspect")
                ):
                    continue
                aspect = str(row["aspect"])
                if aspect in prior_global_checks:
                    errors.append(
                        f"{issue_id} archived global consistency pass "
                        f"duplicates {aspect}"
                    )
                    continue
                prior_global_checks[aspect] = row

    source_rows = (
        prior_manifest.get("source_snapshot", {}).get("files", [])
        if isinstance(prior_manifest, dict)
        and isinstance(prior_manifest.get("source_snapshot"), dict)
        else []
    )
    expected_sources = {
        str(row.get("file")): row.get("sha256")
        for row in source_rows
        if isinstance(row, dict)
        and is_nonempty_string(row.get("file"))
        and isinstance(row.get("sha256"), str)
    } if isinstance(source_rows, list) else {}
    source_values = archive.get("prior_sources")
    if not isinstance(source_values, list):
        errors.append(f"{issue_id} prior_sources must be a list")
        source_values = []
    sealed_sources: dict[str, bytes] = {}
    for index, value in enumerate(source_values, 1):
        label = f"{issue_id} prior_sources[{index}]"
        decoded = decode_sealed_file_record(value, label, errors)
        if decoded is None:
            continue
        file_value, digest, raw = decoded
        if file_value in sealed_sources:
            errors.append(f"{issue_id} archived source is duplicated: {file_value}")
        sealed_sources[file_value] = raw
        if expected_sources.get(file_value) != digest:
            errors.append(
                f"{label} bytes disagree with the prior source snapshot"
            )
    if set(sealed_sources) != set(expected_sources):
        errors.append(
            f"{issue_id} prior_sources must cover the prior source snapshot exactly"
        )

    projection = archive.get("projection")
    if isinstance(projection, dict):
        recomputed_failure = archived_ledger_move_failure_rows(
            archived_issue, ledgers
        )
        if recomputed_failure is not None:
            if projection.get("failure") != recomputed_failure:
                errors.append(
                    f"{issue_id} archived failure projection does not match "
                    "the sealed ledger move"
                )
        elif archived_issue.get("origin_ref", {}).get("kind") in {
            "interface_record",
            "global_check",
        }:
            recomputed_nonledger_failure = archived_nonledger_failure_rows(
                archived_issue,
                prior_interfaces,
                prior_global_checks,
                sealed_sources,
            )
            if not recomputed_nonledger_failure:
                errors.append(
                    f"{issue_id} archived non-ledger origin cannot be "
                    "recomputed from sealed canonical records"
                )
            elif projection.get("failure") != recomputed_nonledger_failure:
                errors.append(
                    f"{issue_id} archived failure projection does not match "
                    "the sealed canonical origin record"
                )
        elif archived_issue.get("origin_ref", {}).get("kind") in {
            "dependency_use",
            "obligation_pointer",
        }:
            recomputed_structured_failure = archived_structured_failure_rows(
                archived_issue,
                ledgers,
                ledger_files,
                normalized_edges,
                sealed_sources,
                root,
            )
            if not recomputed_structured_failure:
                errors.append(
                    f"{issue_id} archived structured origin cannot be "
                    "recomputed from sealed canonical records"
                )
            elif projection.get("failure") != recomputed_structured_failure:
                errors.append(
                    f"{issue_id} archived failure projection does not match "
                    "the sealed canonical origin record"
                )
        else:
            errors.append(
                f"{issue_id} archived failure origin is unsupported"
            )
    return ledgers


def resolution_archive_path(
    issue_id: str, historical_origin: dict[str, Any], root: Path
) -> tuple[Path | None, list[str]]:
    errors: list[str] = []
    artifact = historical_origin.get("artifact")
    if not is_nonempty_string(artifact):
        return None, [f"{issue_id}.historical_origin.artifact must be a path"]
    path = resolve_stored_path(str(artifact), root)
    canonical_directory, confinement_errors = confined_history_directory(root)
    errors.extend(confinement_errors)
    resolved_directory = canonical_directory.resolve(strict=False)
    if (
        path.parent != resolved_directory
        or path.name != f"{issue_id}-origin.json"
    ):
        errors.append(
            f"{issue_id}.historical_origin.artifact must resolve to "
            f"audit/06_reports/history/{issue_id}-origin.json"
        )
    if path.is_symlink():
        errors.append(
            f"{issue_id}.historical_origin.artifact cannot use a symlink"
        )
    return path, errors


def load_resolution_archive(
    issue: dict[str, Any], root: Path, errors: list[str]
) -> dict[str, Any] | None:
    issue_id = str(issue.get("id", "<unknown>"))
    historical_origin = issue.get("historical_origin")
    if not isinstance(historical_origin, dict):
        errors.append(f"{issue_id}.historical_origin must be an object")
        return None
    artifact_path, path_errors = resolution_archive_path(
        issue_id, historical_origin, root
    )
    errors.extend(path_errors)
    if artifact_path is None or not artifact_path.is_file():
        errors.append(
            f"{issue_id}.historical_origin artifact is missing: {artifact_path}"
        )
        return None
    recorded_digest = historical_origin.get("sha256")
    actual_digest = sha256_file(artifact_path)
    if (
        not is_nonempty_string(recorded_digest)
        or recorded_digest != actual_digest
    ):
        errors.append(
            f"{issue_id}.historical_origin.sha256 does not match the archive"
        )
    archive, archive_errors = load_json_object(
        artifact_path, f"resolution archive for {issue_id}"
    )
    errors.extend(archive_errors)
    if archive_errors:
        return None
    if archive.get("archive_schema_version") != RESOLUTION_ARCHIVE_SCHEMA_VERSION:
        errors.append(
            f"{issue_id} resolution archive has an unsupported schema version"
        )
    if archive.get("archive_payload_sha256") != resolution_archive_payload_sha256(
        archive
    ):
        errors.append(
            f"{issue_id} resolution archive payload hash does not match"
        )
    if not is_utc_timestamp(archive.get("generated_utc")):
        errors.append(
            f"{issue_id} resolution archive generated_utc must be UTC"
        )

    archived_issue = archive.get("issue_record")
    if not isinstance(archived_issue, dict):
        errors.append(f"{issue_id} resolution archive needs issue_record")
        archived_issue = {}
    if archive.get("issue_record_sha256") != canonical_sha256(archived_issue):
        errors.append(
            f"{issue_id} resolution archive issue_record hash does not match"
        )
    if archived_issue.get("status") not in {"open", "deferred"}:
        errors.append(
            f"{issue_id} resolution archive must capture an open or deferred issue"
        )
    if archived_issue.get("finding_status") not in {"defect", "inconclusive"}:
        errors.append(
            f"{issue_id} resolution archive must capture an unresolved finding"
        )
    for field in RESOLUTION_ARCHIVE_STABLE_FIELDS:
        if archived_issue.get(field) != issue.get(field):
            errors.append(
                f"{issue_id} current {field} differs from the archived issue"
            )

    protocol = archive.get("protocol")
    if not isinstance(protocol, dict):
        errors.append(f"{issue_id} resolution archive protocol must be an object")
        protocol = {}
    unknown_protocol_fields = set(protocol) - set(protocol_identity()) - {"challenge_contract_version"}
    if unknown_protocol_fields:
        errors.append(f"{issue_id} resolution archive protocol has unsupported fields: "
                      + ", ".join(sorted(unknown_protocol_fields)))
    for field, expected in {
        "skill_name": SKILL_NAME,
        "artifact_schema_version": SCHEMA_VERSION,
        "evidence_contract_version": EVIDENCE_CONTRACT_VERSION,
        "method_interface_schema_version": METHOD_INTERFACE_SCHEMA_VERSION,
        "closure_contract_version": CLOSURE_CONTRACT_VERSION,
    }.items():
        if protocol.get(field) != expected:
            errors.append(
                f"{issue_id} resolution archive protocol.{field} is invalid"
            )
    if not is_nonempty_string(protocol.get("skill_version")):
        errors.append(
            f"{issue_id} resolution archive protocol.skill_version is invalid"
        )
    if not (
        isinstance(protocol.get("validator_sha256"), str)
        and SHA256_RE.fullmatch(protocol["validator_sha256"])
    ):
        errors.append(
            f"{issue_id} resolution archive validator_sha256 is invalid"
        )

    source_snapshot = archive.get("source_snapshot_sha256")
    if not is_nonempty_string(source_snapshot) or (
        historical_origin.get("source_snapshot_sha256") != source_snapshot
    ):
        errors.append(
            f"{issue_id}.historical_origin source snapshot disagrees with archive"
        )

    prior_record = archive.get("prior_finalization_record")
    if not isinstance(prior_record, dict):
        errors.append(
            f"{issue_id} resolution archive needs prior_finalization_record"
        )
        prior_record = {}
    if archive.get("prior_finalization_record_sha256") != canonical_sha256(
        prior_record
    ):
        errors.append(
            f"{issue_id} prior finalization record hash does not match"
        )
    if (
        prior_record.get("status") != "passed"
        or prior_record.get("errors") != []
        or prior_record.get("record_payload_sha256")
        != finalization_payload_sha256(prior_record)
        or prior_record.get("source_snapshot_sha256") != source_snapshot
    ):
        errors.append(
            f"{issue_id} resolution archive is not bound to a valid prior "
            "finalization record"
        )
    prior_manifest = prior_record.get("artifact_manifest")
    prior_issue_log_sha256 = archive.get("prior_issue_log_sha256")
    matching_issue_rows = [
        row
        for row in prior_manifest
        if isinstance(row, dict)
        and row.get("file") == "audit/06_reports/ISSUE_LOG.json"
    ] if isinstance(prior_manifest, list) else []
    if (
        len(matching_issue_rows) != 1
        or matching_issue_rows[0].get("sha256") != prior_issue_log_sha256
    ):
        errors.append(
            f"{issue_id} prior finalization does not bind the archived issue log"
        )

    projection = archive.get("projection")
    if not isinstance(projection, dict):
        errors.append(f"{issue_id} resolution archive projection must be an object")
        projection = {}
    if archive.get("projection_sha256") != canonical_sha256(projection):
        errors.append(
            f"{issue_id} resolution archive projection hash does not match"
        )
    for field in ("failure", "contract", "propagation", "severity"):
        if not isinstance(projection.get(field), list) or not projection[field]:
            errors.append(
                f"{issue_id} resolution archive projection.{field} must be nonempty"
            )

    required_closure = archive.get("required_closure")
    if not isinstance(required_closure, dict):
        errors.append(
            f"{issue_id} resolution archive required_closure must be an object"
        )
        required_closure = {}
    required_units = validate_string_list(
        required_closure.get("units"),
        f"{issue_id} archive required_closure.units",
        errors,
    )
    archived_affected = archived_issue.get("affected_results")
    if not isinstance(archived_affected, list):
        errors.append(
            f"{issue_id} archived issue affected_results must be a list"
        )
        archived_affected = []
    if required_units != sorted(
        item for item in archived_affected if is_nonempty_string(item)
    ):
        errors.append(
            f"{issue_id} archive required units must equal archived affected_results"
        )
    dependency_rows = required_closure.get("dependency_uses")
    if not isinstance(dependency_rows, list):
        errors.append(
            f"{issue_id} archive required_closure.dependency_uses must be a list"
        )
        dependency_rows = []
    dependency_ids: list[str] = []
    for row_index, row in enumerate(dependency_rows, 1):
        prefix = (
            f"{issue_id} archive required_closure.dependency_uses[{row_index}]"
        )
        if not isinstance(row, dict):
            errors.append(f"{prefix} must be an object")
            continue
        use_id = row.get("use_id")
        edge_digest = row.get("edge_sha256")
        if not (
            is_nonempty_string(use_id)
            and DEPENDENCY_USE_ID_RE.fullmatch(str(use_id))
        ):
            errors.append(f"{prefix}.use_id must match D001")
        else:
            dependency_ids.append(str(use_id))
        if not (
            isinstance(edge_digest, str) and SHA256_RE.fullmatch(edge_digest)
        ):
            errors.append(f"{prefix}.edge_sha256 is invalid")
    if dependency_ids != sorted(set(dependency_ids)):
        errors.append(
            f"{issue_id} archive dependency uses must be sorted and unique"
        )
    required_challenges = validate_string_list(
        required_closure.get("challenges"),
        f"{issue_id} archive required_closure.challenges",
        errors,
        allow_empty=True,
    )
    required_deliverables = validate_string_list(
        required_closure.get("report_deliverables"),
        f"{issue_id} archive required_closure.report_deliverables",
        errors,
        allow_empty=True,
    )
    for field, expected in (
        ("required_units", required_units),
        ("required_dependency_uses", dependency_ids),
        ("required_challenges", required_challenges),
        ("required_report_deliverables", required_deliverables),
    ):
        if historical_origin.get(field) != expected:
            errors.append(
                f"{issue_id}.historical_origin.{field} disagrees with archive"
            )

    ledger_hashes = archive.get("ledger_sha256s")
    if not isinstance(ledger_hashes, dict) or not set(required_units).issubset(
        ledger_hashes
    ):
        errors.append(
            f"{issue_id} archive ledger_sha256s must cover every required unit"
        )
    elif any(
        not isinstance(digest, str) or not SHA256_RE.fullmatch(digest)
        for digest in ledger_hashes.values()
    ):
        errors.append(f"{issue_id} archive ledger_sha256s contains an invalid hash")

    root_components = archive.get("root_components")
    if not isinstance(root_components, dict):
        errors.append(
            f"{issue_id} resolution archive root_components must be an object"
        )
        root_components = {}
    historical_component = {
        "proof_gap": ("argument_status", {"gap"}),
        "proof_invalid": ("argument_status", {"invalid"}),
        "statement_refuted": ("statement_status", {"refuted"}),
        "dependency_mismatch": (
            "dependency_closure",
            {"gap", "incorrect", "unclear"},
        ),
    }.get(archived_issue.get("invalidation_kind"))
    if historical_component is not None:
        component, allowed = historical_component
        if root_components.get(component) not in allowed:
            errors.append(
                f"{issue_id} archived invalidation disagrees with historical "
                f"{component}"
            )
    validate_resolution_archive_provenance(
        archive,
        archived_issue,
        prior_record,
        required_units,
        root,
        issue_id,
        errors,
    )
    archive["issue_record"] = archived_issue
    archive["projection"] = projection
    archive["required_closure"] = required_closure
    return archive


def issue_recheck_edges(
    issue: dict[str, Any], dependency_edges: Iterable[dict[str, Any]]
) -> list[dict[str, Any]]:
    """Return direct uses that must be rechecked for every affected unit."""
    affected_result = issue.get("affected_result")
    affected_results = {
        item
        for item in issue.get("affected_results", [])
        if is_nonempty_string(item)
    } if isinstance(issue.get("affected_results"), list) else set()
    origin = issue.get("origin_ref")
    origin_use = (
        origin.get("use_id")
        if isinstance(origin, dict)
        and origin.get("kind") == "dependency_use"
        and is_nonempty_string(origin.get("use_id"))
        else None
    )
    selected = [
        edge
        for edge in dependency_edges
        if isinstance(edge, dict)
        and is_nonempty_string(edge.get("use_id"))
        and (
            (
                edge.get("dependent_unit") in affected_results
            )
            or (
                origin_use is not None
                and edge.get("use_id") == origin_use
                and edge.get("dependent_unit") == affected_result
            )
        )
    ]
    return sorted(
        selected,
        key=lambda edge: (
            str(edge.get("use_id")),
            str(edge.get("dependent_unit")),
            str(edge.get("dependency_id")),
        ),
    )


def resolve_current_issue_ref(
    ref: Any,
    ledgers_by_unit: dict[str, dict[str, Any]],
    interfaces: dict[str, dict[str, Any]] | None,
    global_checks: dict[str, dict[str, Any]] | None,
) -> dict[str, Any] | None:
    if not isinstance(ref, dict):
        return None
    kind = ref.get("kind")
    unit_id = ref.get("unit_id")
    ledger = ledgers_by_unit.get(str(unit_id))
    if kind == "ledger_move" and isinstance(ledger, dict):
        step = next(
            (
                row
                for row in ledger.get("steps", [])
                if isinstance(row, dict) and row.get("id") == ref.get("step_id")
            ),
            None,
        )
        inference = (
            step.get("inference") if isinstance(step, dict) else None
        )
        moves = inference.get("moves") if isinstance(inference, dict) else []
        matches = [
            move
            for move in moves
            if isinstance(move, dict) and move.get("id") == ref.get("move_id")
        ] if isinstance(moves, list) else []
        if len(matches) == 1:
            return {"kind": kind, "step": step, "move": matches[0]}
    elif kind == "obligation_pointer" and isinstance(ledger, dict):
        found, value = resolve_json_pointer(
            ledger.get("obligation"), ref.get("pointer")
        )
        if found:
            return {"kind": kind, "value": value}
    elif kind == "dependency_use" and isinstance(ledger, dict):
        dependencies = ledger.get("review", {}).get("direct_dependencies", [])
        matches = [
            row
            for row in dependencies
            if isinstance(row, dict) and row.get("use_id") == ref.get("use_id")
        ] if isinstance(dependencies, list) else []
        if len(matches) == 1:
            return {"kind": kind, "dependency": matches[0]}
    elif kind == "interface_record":
        interface_id = ref.get("interface_id")
        if (
            is_nonempty_string(interface_id)
            and interfaces is not None
            and interface_id in interfaces
        ):
            return {"kind": kind, "interface": interfaces[interface_id]}
    elif kind == "global_check":
        aspect = ref.get("aspect")
        if (
            is_nonempty_string(aspect)
            and global_checks is not None
            and aspect in global_checks
        ):
            return {"kind": kind, "global_check": global_checks[aspect]}
    return None


def canonical_issue_ref_identity(ref: Any) -> dict[str, Any] | None:
    """Return the stable canonical identity of an issue reference."""
    if not isinstance(ref, dict):
        return None
    return {
        key: value
        for key, value in ref.items()
        if key != "evidence_spans"
    }


def validate_current_resolution(
    issue: dict[str, Any],
    archive: dict[str, Any],
    root: Path,
    errors: list[str],
    ledgers_by_unit: dict[str, dict[str, Any]],
    dependency_edges: list[dict[str, Any]],
    interfaces: dict[str, dict[str, Any]] | None,
    global_checks: dict[str, dict[str, Any]] | None,
) -> dict[str, list[str]]:
    issue_id = str(issue.get("id"))
    record = issue.get("current_resolution")
    if not isinstance(record, dict):
        errors.append(f"{issue_id}.current_resolution must be an object")
        record = {}
    disposition = record.get("disposition")
    if not is_enum_value(disposition, RESOLUTION_DISPOSITIONS):
        errors.append(f"{issue_id}.current_resolution.disposition is invalid")
    if not is_substantive_string(record.get("mapping")):
        errors.append(
            f"{issue_id}.current_resolution.mapping must explain the old-to-new "
            "relationship"
        )
    if record.get("verification_status") != "verified_sufficient":
        errors.append(
            f"{issue_id}.current_resolution.verification_status must be "
            "verified_sufficient"
        )
    evidence_spans = record.get("evidence_spans")
    validate_locked_span_list(
        evidence_spans,
        root,
        f"{issue_id}.current_resolution.evidence_spans",
        errors,
    )

    archived_closure = archive.get("required_closure")
    if not isinstance(archived_closure, dict):
        archived_closure = {}
    archived_units = sorted(
        item
        for item in archived_closure.get("units", [])
        if is_nonempty_string(item)
    )
    current_units = sorted(
        item
        for item in issue.get("affected_results", [])
        if is_nonempty_string(item)
    )
    required_units = sorted(set(archived_units) | set(current_units))
    required_rechecks = validate_string_list(
        record.get("required_rechecks"),
        f"{issue_id}.current_resolution.required_rechecks",
        errors,
    )
    if required_rechecks != required_units:
        errors.append(
            f"{issue_id}.current_resolution.required_rechecks must cover the "
            "historical-current affected union"
        )

    archived_dependency_rows = [
        row
        for row in archived_closure.get("dependency_uses", [])
        if isinstance(row, dict) and is_nonempty_string(row.get("use_id"))
    ]
    archived_dependency_hashes = {
        str(row["use_id"]): row.get("edge_sha256")
        for row in archived_dependency_rows
    }
    current_edges = issue_recheck_edges(issue, dependency_edges)
    current_dependency_ids = sorted(
        {
            str(edge["use_id"])
            for edge in current_edges
            if is_nonempty_string(edge.get("use_id"))
        }
    )
    required_dependency_ids = sorted(
        set(archived_dependency_hashes) | set(current_dependency_ids)
    )
    retired_ids = sorted(
        set(archived_dependency_hashes) - set(current_dependency_ids)
    )
    retirement_rows = record.get("retired_dependency_uses")
    if not isinstance(retirement_rows, list):
        errors.append(
            f"{issue_id}.current_resolution.retired_dependency_uses must be a list"
        )
        retirement_rows = []
    recorded_retired_ids: list[str] = []
    for row_index, row in enumerate(retirement_rows, 1):
        prefix = (
            f"{issue_id}.current_resolution.retired_dependency_uses[{row_index}]"
        )
        if not isinstance(row, dict):
            errors.append(f"{prefix} must be an object")
            continue
        use_id = row.get("use_id")
        if not (
            is_nonempty_string(use_id)
            and DEPENDENCY_USE_ID_RE.fullmatch(str(use_id))
        ):
            errors.append(f"{prefix}.use_id must match D001")
            continue
        recorded_retired_ids.append(str(use_id))
        if row.get("prior_edge_sha256") != archived_dependency_hashes.get(
            str(use_id)
        ):
            errors.append(
                f"{prefix}.prior_edge_sha256 does not match the archive"
            )
        for field in ("reason", "recheck_evidence"):
            if not is_substantive_string(row.get(field)):
                errors.append(f"{prefix}.{field} must be substantive")
    if recorded_retired_ids != retired_ids:
        errors.append(
            f"{issue_id}.current_resolution.retired_dependency_uses must equal "
            "the archived uses absent from the current dependency closure"
        )

    archived_issue = archive.get("issue_record")
    if not isinstance(archived_issue, dict):
        archived_issue = {}
    archived_origin = archived_issue.get("origin_ref")
    current_ref = record.get("current_ref")
    archived_ref_identity = canonical_issue_ref_identity(archived_origin)
    current_ref_identity = canonical_issue_ref_identity(current_ref)
    resolved_current_ref = resolve_current_issue_ref(
        current_ref, ledgers_by_unit, interfaces, global_checks
    )
    archived_ref_still_resolves = resolve_current_issue_ref(
        archived_origin, ledgers_by_unit, interfaces, global_checks
    )
    if disposition == "removed":
        if issue.get("affected_result") not in ledgers_by_unit:
            errors.append(
                f"{issue_id}.current_resolution removed may retire only the "
                "failed origin inside a retained affected result"
            )
        if current_ref is not None:
            errors.append(
                f"{issue_id}.current_resolution.current_ref must be null when removed"
            )
        if archived_ref_still_resolves is not None:
            errors.append(
                f"{issue_id}.current_resolution says removed but the archived "
                "origin still resolves"
            )
    else:
        if resolved_current_ref is None:
            errors.append(
                f"{issue_id}.current_resolution.current_ref does not resolve"
            )
        if (
            disposition == "repaired"
            and current_ref_identity != archived_ref_identity
        ):
            errors.append(
                f"{issue_id}.current_resolution repaired must retain the archived "
                "origin reference"
            )
        if (
            disposition == "replaced"
            and current_ref_identity == archived_ref_identity
        ):
            errors.append(
                f"{issue_id}.current_resolution replaced must name a new reference"
            )
        if isinstance(resolved_current_ref, dict):
            if resolved_current_ref.get("kind") == "ledger_move":
                step = resolved_current_ref.get("step")
                move = resolved_current_ref.get("move")
                if (
                    not isinstance(step, dict)
                    or step.get("status")
                    not in {"verified", "conditionally_verified"}
                    or not isinstance(move, dict)
                    or move.get("failure") is not None
                ):
                    errors.append(
                        f"{issue_id}.current_resolution ledger move is not clean"
                    )
            elif resolved_current_ref.get("kind") == "dependency_use":
                dependency = resolved_current_ref.get("dependency")
                if (
                    not isinstance(dependency, dict)
                    or dependency.get("status")
                    not in {"verified", "conditional", "not_applicable"}
                ):
                    errors.append(
                        f"{issue_id}.current_resolution dependency use is not clean"
                    )
            if not current_resolution_ref_is_connected(
                issue,
                current_ref,
                resolved_current_ref,
                ledgers_by_unit,
            ):
                errors.append(
                    f"{issue_id}.current_resolution.current_ref is not connected "
                    "to a current affected-result contract or support closure"
                )
    return {
        "required_units": required_units,
        "required_dependency_uses": required_dependency_ids,
        "retired_dependency_uses": retired_ids,
    }


def locked_span_identity(span: Any) -> tuple[Any, Any, Any, Any, Any] | None:
    if not isinstance(span, dict):
        return None
    fields = (
        span.get("file"),
        span.get("start_line"),
        span.get("end_line"),
        span.get("sha256"),
        span.get("role"),
    )
    if (
        not is_nonempty_string(fields[0])
        or not is_int(fields[1])
        or not is_int(fields[2])
        or not is_nonempty_string(fields[3])
    ):
        return None
    return fields


def nested_locked_spans(value: Any) -> list[dict[str, Any]]:
    spans: list[dict[str, Any]] = []
    if isinstance(value, dict):
        if locked_span_identity(value) is not None:
            spans.append(value)
        else:
            for nested in value.values():
                spans.extend(nested_locked_spans(nested))
    elif isinstance(value, list):
        for nested in value:
            spans.extend(nested_locked_spans(nested))
    return spans


def ledger_support_contract_closure(
    ledger: dict[str, Any], support_step_id: str, support_move_id: str
) -> dict[str, set[Any]]:
    """Return the exact backward support closure for one ledger move."""
    steps = [
        step
        for step in ledger.get("steps", [])
        if isinstance(step, dict) and is_nonempty_string(step.get("id"))
    ]
    steps_by_id = {str(step["id"]): step for step in steps}
    premises_by_step = {
        str(step["id"]): {
            str(premise["id"]): premise
            for premise in step.get("premise_uses", [])
            if isinstance(premise, dict)
            and is_nonempty_string(premise.get("id"))
        }
        for step in steps
    }
    pending: list[tuple[str, str]] = [(support_step_id, support_move_id)]
    move_keys: set[tuple[str, str]] = set()
    obligation_pointers: set[str] = set()
    dependency_uses: set[str] = set()

    def consume_premise(step_id: str, premise_id: str) -> None:
        premise = premises_by_step.get(step_id, {}).get(premise_id)
        origin = premise.get("origin") if isinstance(premise, dict) else None
        if not isinstance(origin, dict):
            return
        kind = origin.get("kind")
        reference = origin.get("reference")
        if kind == "obligation" and is_nonempty_string(reference):
            obligation_pointers.add(str(reference))
        elif is_enum_value(
            kind, {"internal_result", "external_result"}
        ) and is_nonempty_string(reference):
            dependency_uses.add(str(reference))
        elif kind == "prior_step" and is_nonempty_string(reference):
            prior_step = steps_by_id.get(str(reference))
            inference = (
                prior_step.get("inference")
                if isinstance(prior_step, dict)
                else None
            )
            prior_move = (
                inference.get("conclusion_move")
                if isinstance(inference, dict)
                else None
            )
            if is_nonempty_string(prior_move):
                pending.append((str(reference), str(prior_move)))

    while pending:
        step_id, move_id = pending.pop()
        key = (step_id, move_id)
        if key in move_keys:
            continue
        move_keys.add(key)
        step = steps_by_id.get(step_id)
        inference = step.get("inference") if isinstance(step, dict) else None
        moves = inference.get("moves") if isinstance(inference, dict) else []
        move = next(
            (
                row
                for row in moves
                if isinstance(row, dict) and row.get("id") == move_id
            ),
            None,
        ) if isinstance(moves, list) else None
        if not isinstance(move, dict):
            continue
        for prior_move_id in move.get("prior_move_ids", []):
            if is_nonempty_string(prior_move_id):
                pending.append((step_id, str(prior_move_id)))
        for premise_id in move.get("premise_ids", []):
            if is_nonempty_string(premise_id):
                consume_premise(step_id, str(premise_id))
        side_conditions = step.get("side_conditions")
        if not isinstance(side_conditions, list):
            continue
        for condition in side_conditions:
            if (
                not isinstance(condition, dict)
                or condition.get("generated_by") != move_id
                or condition.get("status") != "discharged"
            ):
                continue
            discharge = condition.get("discharge")
            sources = (
                discharge.get("sources")
                if isinstance(discharge, dict)
                else []
            )
            if not isinstance(sources, list):
                continue
            for source in sources:
                if not isinstance(source, dict):
                    continue
                reference = source.get("reference")
                if not is_nonempty_string(reference):
                    continue
                if source.get("kind") == "premise":
                    consume_premise(step_id, str(reference))
                elif source.get("kind") == "inference_move":
                    pending.append((step_id, str(reference)))
    return {
        "move_keys": move_keys,
        "obligation_pointers": obligation_pointers,
        "dependency_uses": dependency_uses,
    }


def current_resolution_ref_is_connected(
    issue: dict[str, Any],
    current_ref: Any,
    resolved_ref: dict[str, Any],
    ledgers_by_unit: dict[str, dict[str, Any]],
) -> bool:
    """Require the current repair reference to support the current root contract."""
    if not isinstance(current_ref, dict):
        return False
    kind = current_ref.get("kind")
    affected_result = issue.get("affected_result")
    if kind in {"ledger_move", "obligation_pointer", "dependency_use"}:
        if current_ref.get("unit_id") != affected_result:
            return False
    elif kind == "interface_record":
        interface = resolved_ref.get("interface")
        return (
            isinstance(interface, dict)
            and current_ref.get("interface_id") == issue.get("interface_id")
            and affected_result in interface.get("affected_results", [])
        )
    elif kind == "global_check":
        check = resolved_ref.get("global_check")
        current_contract_refs = issue.get("contract_refs")
        resolution = issue.get("current_resolution")
        evidence_spans = (
            resolution.get("evidence_spans")
            if isinstance(resolution, dict)
            else None
        )
        return (
            isinstance(check, dict)
            and check.get("aspect") == current_ref.get("aspect")
            and current_ref.get("aspect")
            == (
                issue.get("origin_ref", {}).get("aspect")
                if isinstance(issue.get("origin_ref"), dict)
                else None
            )
            and check.get("status") in {"passed", "not_applicable"}
            and isinstance(evidence_spans, list)
            and bool(evidence_spans)
            and isinstance(current_contract_refs, list)
            and any(
                isinstance(ref, dict)
                and ref.get("unit_id") == affected_result
                for ref in current_contract_refs
            )
        )
    else:
        return False

    ledger = ledgers_by_unit.get(str(affected_result))
    if not isinstance(ledger, dict):
        return False
    contract_refs = [
        ref
        for ref in issue.get("contract_refs", [])
        if isinstance(ref, dict) and ref.get("unit_id") == affected_result
    ] if isinstance(issue.get("contract_refs"), list) else []
    if not contract_refs:
        return False
    if kind == "obligation_pointer":
        return any(
            ref.get("kind") == "obligation_pointer"
            and ref.get("pointer") == current_ref.get("pointer")
            for ref in contract_refs
        )
    if kind == "dependency_use":
        return any(
            ref.get("kind") == "dependency_use"
            and ref.get("use_id") == current_ref.get("use_id")
            for ref in contract_refs
        )
    if kind != "ledger_move":
        return False

    step_id = str(current_ref.get("step_id"))
    move_id = str(current_ref.get("move_id"))
    move_key = (step_id, move_id)
    move_closure = ledger_support_contract_closure(
        ledger, step_id, move_id
    )
    linked_conclusions: set[str] = set()
    for result in ledger.get("review", {}).get("conclusion_results", []):
        if not isinstance(result, dict):
            continue
        support = result.get("support")
        if not isinstance(support, dict):
            continue
        support_closure = ledger_support_contract_closure(
            ledger,
            str(support.get("step_id")),
            str(support.get("move_id")),
        )
        conclusion_id = result.get("conclusion_id")
        if move_key in support_closure["move_keys"] and is_nonempty_string(
            conclusion_id
        ):
            linked_conclusions.add(str(conclusion_id))
    return any(
        (
            ref.get("kind") == "conclusion"
            and ref.get("conclusion_id") in linked_conclusions
        )
        or (
            ref.get("kind") == "obligation_pointer"
            and ref.get("pointer") in move_closure["obligation_pointers"]
        )
        or (
            ref.get("kind") == "dependency_use"
            and ref.get("use_id") in move_closure["dependency_uses"]
        )
        for ref in contract_refs
    )


def validate_repair_search(
    value: Any, severity: str | None, field: str
) -> list[str]:
    """Validate the bounded repair-attempt record grounding an S0/S1 grading.

    The record documents which repair strategies were actually attempted and
    where each fails, so that "no local repair established" (S0) versus "a
    plausible repair may exist" (S1) is an evidence-backed judgment rather
    than an assertion. It is diagnostic only: a surviving strategy never
    resolves the issue, lowers severity, or strengthens a verdict.
    """
    errors: list[str] = []
    if not isinstance(value, dict):
        return [f"{field} must be an object"]
    unknown = set(value) - {"strategies", "conclusion"}
    if unknown:
        errors.append(f"{field} has unknown fields: {', '.join(sorted(unknown))}")
    strategies = value.get("strategies")
    outcomes: list[str] = []
    if not isinstance(strategies, list) or not strategies:
        errors.append(f"{field}.strategies must be a nonempty list")
        strategies = []
    for index, strategy in enumerate(strategies, 1):
        prefix = f"{field}.strategies[{index}]"
        if not isinstance(strategy, dict):
            errors.append(f"{prefix} must be an object")
            continue
        unknown_fields = set(strategy) - REPAIR_SEARCH_STRATEGY_FIELDS
        missing_fields = REPAIR_SEARCH_STRATEGY_FIELDS - set(strategy)
        if unknown_fields:
            errors.append(
                f"{prefix} has unknown fields: {', '.join(sorted(unknown_fields))}"
            )
        if missing_fields:
            errors.append(
                f"{prefix} is missing fields: {', '.join(sorted(missing_fields))}"
            )
        for name in ("name", "attempt", "evidence"):
            if name in strategy and not is_substantive_string(strategy.get(name)):
                errors.append(f"{prefix}.{name} must be nonempty and substantive")
        outcome = strategy.get("outcome")
        if "outcome" in strategy:
            if not is_enum_value(outcome, REPAIR_SEARCH_OUTCOMES):
                errors.append(
                    f"{prefix}.outcome must be 'failed' or "
                    "'survives_local_inspection'"
                )
            else:
                outcomes.append(str(outcome))
    conclusion = value.get("conclusion")
    if not is_enum_value(conclusion, REPAIR_SEARCH_CONCLUSIONS):
        errors.append(
            f"{field}.conclusion must be 'no_local_repair_found' or "
            "'candidate_repair_exists'"
        )
        return errors
    if conclusion == "no_local_repair_found" and any(
        outcome != "failed" for outcome in outcomes
    ):
        errors.append(
            f"{field}: no_local_repair_found requires every attempted "
            "strategy to record outcome failed"
        )
    if conclusion == "candidate_repair_exists" and outcomes and not any(
        outcome == "survives_local_inspection" for outcome in outcomes
    ):
        errors.append(
            f"{field}: candidate_repair_exists requires at least one strategy "
            "with outcome survives_local_inspection"
        )
    if severity == "S0" and conclusion != "no_local_repair_found":
        errors.append(
            f"{field}: severity S0 requires conclusion no_local_repair_found; "
            "record candidate_repair_exists only with severity S1"
        )
    if severity == "S1" and conclusion != "candidate_repair_exists":
        errors.append(
            f"{field}: severity S1 requires conclusion candidate_repair_exists; "
            "an issue with no plausible repair on the main claim is S0"
        )
    return errors


def validate_repair_cost_fields(
    change: dict[str, Any],
    action: str | None,
    repair_search: dict[str, Any] | None,
    prefix: str,
) -> list[str]:
    """Validate the structured repair-cost classification of one suggested change.

    `repair_scope` records how far the edit reaches, `assumption_cost` how much
    stronger the hypotheses become, and `claim_cost` (weaken_claim only) what
    the conclusion gives up. These are diagnostic classifications for triage:
    they never certify a repair, lower severity, or strengthen a verdict, and
    only their internal coherence is machine-checked.
    """
    errors: list[str] = []
    repair_scope = change.get("repair_scope")
    if not is_enum_value(repair_scope, REPAIR_SCOPES):
        errors.append(
            f"{prefix}.repair_scope must be local_step, unit_statement, "
            "cross_unit, or global"
        )
        repair_scope = None
    assumption_cost = change.get("assumption_cost")
    if not is_enum_value(assumption_cost, ASSUMPTION_COSTS):
        errors.append(
            f"{prefix}.assumption_cost must be none, tightens_constant, "
            "adds_regularity_or_moment, changes_regime, or structural"
        )
        assumption_cost = None
    claim_cost = change.get("claim_cost")
    if action == "weaken_claim":
        if not is_enum_value(claim_cost, CLAIM_COSTS):
            errors.append(
                f"{prefix}.claim_cost is required for weaken_claim and must be "
                "restricts_scope, weakens_rate, loses_uniformity, or weakens_mode"
            )
            claim_cost = None
        elif claim_cost == "none":
            errors.append(
                f"{prefix}.claim_cost cannot be none for weaken_claim; a change "
                "that gives up nothing is not a weakened claim"
            )
    elif "claim_cost" in change:
        errors.append(
            f"{prefix}.claim_cost is allowed only for a weaken_claim action"
        )
    if action == "strengthen_assumption" and assumption_cost == "none":
        errors.append(
            f"{prefix}.assumption_cost cannot be none for strengthen_assumption; "
            "classify what the added hypothesis costs"
        )
    if action == "presentation_edit":
        if assumption_cost not in {None, "none"}:
            errors.append(
                f"{prefix}: a presentation_edit cannot carry an assumption cost"
            )
        if repair_scope not in {None, "local_step"}:
            errors.append(
                f"{prefix}: a presentation_edit must have repair_scope local_step"
            )
    if (
        isinstance(repair_search, dict)
        and repair_search.get("conclusion") == "no_local_repair_found"
        and repair_scope == "local_step"
        and assumption_cost == "none"
    ):
        errors.append(
            f"{prefix}: repair_scope local_step with assumption_cost none "
            "asserts exactly the local repair that this issue's repair_search "
            "concluded does not exist"
        )
    return errors


def validate_issues(
    issues: list[dict[str, Any]],
    referenced: set[str],
    final: bool = False,
    *,
    evidence_base: Path | None = None,
    interfaces: dict[str, dict[str, Any]] | None = None,
    source_snapshot_id: str | None = None,
    in_scope: Iterable[str] | None = None,
    reverse_graph: dict[str, set[str]] | None = None,
    ledger_summaries: Iterable[dict[str, Any]] | None = None,
    dependency_edges: Iterable[dict[str, Any]] | None = None,
    global_checks: dict[str, dict[str, Any]] | None = None,
) -> tuple[list[str], Counter[str]]:
    errors: list[str] = []
    seen: set[str] = set()
    counts: Counter[str] = Counter()
    summaries_by_unit = {
        summary.get("unit_id"): summary
        for summary in (ledger_summaries or [])
        if isinstance(summary, dict)
        and is_nonempty_string(summary.get("unit_id"))
    }
    ledgers_by_unit: dict[str, dict[str, Any]] = {}
    for unit_id, summary in summaries_by_unit.items():
        ledger_value = summary.get("ledger")
        if not is_nonempty_string(ledger_value):
            continue
        ledger, ledger_errors = load_json_object(
            Path(ledger_value), f"ledger for {unit_id}"
        )
        if not ledger_errors:
            ledgers_by_unit[str(unit_id)] = ledger
    backlink_sources: dict[str, set[str]] = defaultdict(set)
    for issue_id in referenced:
        backlink_sources[str(issue_id)].add("ledger step")
    for unit_id, summary in summaries_by_unit.items():
        for result in summary.get("conclusion_results", []):
            if not isinstance(result, dict):
                continue
            for issue_id in result.get("issue_ids", []):
                if is_nonempty_string(issue_id):
                    backlink_sources[str(issue_id)].add(
                        f"{unit_id} conclusion result"
                    )
        for dependency in summary.get("direct_dependencies", []):
            if not isinstance(dependency, dict):
                continue
            for issue_id in dependency.get("issue_ids", []):
                if is_nonempty_string(issue_id):
                    backlink_sources[str(issue_id)].add(
                        f"{unit_id} direct dependency"
                    )
    for edge in dependency_edges or []:
        if not isinstance(edge, dict):
            continue
        for issue_id in edge.get("issue_ids", []):
            if is_nonempty_string(issue_id):
                backlink_sources[str(issue_id)].add(
                    "canonical dependency edge"
                )
    for interface_id, interface in (interfaces or {}).items():
        if not isinstance(interface, dict):
            continue
        for issue_id in interface.get("issue_ids", []):
            if is_nonempty_string(issue_id):
                backlink_sources[str(issue_id)].add(
                    f"method interface {interface_id}"
                )
    for aspect, check in (global_checks or {}).items():
        if not isinstance(check, dict):
            continue
        for issue_id in check.get("issue_ids", []):
            if is_nonempty_string(issue_id):
                backlink_sources[str(issue_id)].add(
                    f"global check {aspect}"
                )
    all_referenced = set(backlink_sources)
    for index, issue in enumerate(issues, 1):
        prefix = f"Issue record {index}"
        if not isinstance(issue, dict):
            errors.append(f"{prefix} must be an object")
            continue
        issue_id = issue.get("id")
        if not isinstance(issue_id, str) or not ISSUE_ID_RE.fullmatch(issue_id):
            errors.append(f"{prefix} has invalid id; expected I-001")
            continue
        if issue_id in seen:
            errors.append(f"Duplicate issue id: {issue_id}")
        seen.add(issue_id)
        severity = issue.get("severity")
        confidence = issue.get("confidence")
        status = issue.get("status")
        finding_status = issue.get("finding_status")
        repair_search = issue.get("repair_search")
        resolution_archive: dict[str, Any] | None = None
        resolution_requirements: dict[str, list[str]] = {
            "required_units": [],
            "required_dependency_uses": [],
            "retired_dependency_uses": [],
        }
        if not is_enum_value(severity, ISSUE_SEVERITIES):
            errors.append(f"{issue_id}: invalid severity {severity!r}")
        else:
            counts[f"severity_{severity}"] += 1
        if not is_enum_value(confidence, ISSUE_CONFIDENCES):
            errors.append(f"{issue_id}: invalid confidence {confidence!r}")
        if not is_enum_value(status, ISSUE_STATUSES):
            errors.append(f"{issue_id}: invalid status {status!r}")
        else:
            counts[f"status_{status}"] += 1
        if not is_enum_value(finding_status, ISSUE_FINDING_STATUSES):
            errors.append(f"{issue_id}: invalid finding_status {finding_status!r}")
        elif status == "resolved" and finding_status != "resolved":
            errors.append(f"{issue_id}: resolved lifecycle status requires finding_status resolved")
        elif is_enum_value(status, {"open", "deferred"}) and finding_status == "resolved":
            errors.append(f"{issue_id}: an open or deferred issue cannot have finding_status resolved")
        if final and (
            status == "resolved" or "historical_origin" in issue
        ):
            if evidence_base is None:
                errors.append(
                    f"{issue_id}: historical_origin cannot be checked without "
                    "an audit root"
                )
            else:
                resolution_archive = load_resolution_archive(
                    issue, evidence_base, errors
                )
        for field in ("affected_result", "summary"):
            if not is_substantive_string(issue.get(field)):
                errors.append(f"{issue_id}: {field} must be nonempty and substantive")
        if final and isinstance(issue.get("summary"), str) and any(
            character in issue["summary"] for character in "\r\n"
        ):
            errors.append(
                f"{issue_id}: summary must be one line for the canonical finding heading"
            )
        if final:
            retired_fields = [
                field
                for field in (
                    "location",
                    "evidence",
                    "downstream_consequences",
                    "possible_repair",
                )
                if field in issue
            ]
            if retired_fields:
                errors.append(
                    f"{issue_id}: schema-5 issue uses retired authored prose fields: "
                    + ", ".join(retired_fields)
                )
        affected_result = issue.get("affected_result")
        scope_ids = set(in_scope) if in_scope is not None else None
        if scope_ids is not None and (
            not is_nonempty_string(affected_result) or affected_result not in scope_ids
        ):
            errors.append(f"{issue_id}: affected_result is outside the audited scope")
        affected_results = validate_string_list(
            issue.get("affected_results"),
            f"{issue_id}.affected_results",
            errors,
            allow_empty=False,
        )
        if len(affected_results) != len(set(affected_results)):
            errors.append(f"{issue_id}.affected_results contains duplicates")
        if scope_ids is not None:
            unknown_results = set(affected_results) - scope_ids
            if unknown_results:
                errors.append(
                    f"{issue_id}.affected_results names results outside scope: "
                    + ", ".join(sorted(unknown_results))
                )
        if reverse_graph is not None and is_nonempty_string(affected_result):
            expected_affected = {affected_result}
            if issue.get("load_bearing") is True:
                if dependency_edges is not None:
                    expected_affected.update(
                        str(edge.get("dependent_unit"))
                        for edge in dependency_edges
                        if isinstance(edge, dict)
                        and issue_id in edge.get("issue_ids", [])
                        and is_nonempty_string(edge.get("dependent_unit"))
                    )
                else:
                    frontier = [affected_result]
                    while frontier:
                        current = frontier.pop()
                        for dependent in reverse_graph.get(current, set()):
                            if dependent not in expected_affected:
                                expected_affected.add(dependent)
                                frontier.append(dependent)
            if affected_results != sorted(expected_affected):
                errors.append(
                    f"{issue_id}.affected_results must equal the "
                    "conclusion-specific dependency closure: "
                    + ", ".join(sorted(expected_affected))
                )
        if final:
            origin_ref = issue.get("origin_ref")
            if not isinstance(origin_ref, dict):
                errors.append(f"{issue_id}.origin_ref must be an object")
                origin_ref = {}
            origin_kind = origin_ref.get("kind")
            if not is_enum_value(origin_kind, ISSUE_ORIGIN_KINDS):
                errors.append(f"{issue_id}.origin_ref.kind is invalid")
            origin_unit_id = origin_ref.get("unit_id")
            origin_ledger = ledgers_by_unit.get(str(origin_unit_id))
            origin_move: dict[str, Any] | None = None
            origin_dependency: dict[str, Any] | None = None
            origin_dependency_edge: dict[str, Any] | None = None
            origin_interface: dict[str, Any] | None = None
            origin_global_check: dict[str, Any] | None = None
            if (
                status != "resolved"
                and origin_kind != "global_check"
                and origin_kind != "interface_record"
            ):
                if not is_nonempty_string(origin_unit_id) or origin_ledger is None:
                    errors.append(
                        f"{issue_id}.origin_ref must resolve one audited unit"
                    )
                elif origin_unit_id != affected_result:
                    errors.append(
                        f"{issue_id}.origin_ref unit_id must equal affected_result"
                    )
            if (
                status != "resolved"
                and origin_kind == "ledger_move"
                and origin_ledger is not None
            ):
                step_id = origin_ref.get("step_id")
                move_id = origin_ref.get("move_id")
                step = next(
                    (
                        row
                        for row in origin_ledger.get("steps", [])
                        if isinstance(row, dict) and row.get("id") == step_id
                    ),
                    None,
                )
                moves = (
                    step.get("inference", {}).get("moves", [])
                    if isinstance(step, dict)
                    and isinstance(step.get("inference"), dict)
                    else []
                )
                matching_moves = [
                    move
                    for move in moves
                    if isinstance(move, dict) and move.get("id") == move_id
                ]
                if len(matching_moves) != 1:
                    errors.append(
                        f"{issue_id}.origin_ref must resolve exactly one ledger move"
                    )
                else:
                    origin_move = matching_moves[0]
                if not isinstance(step, dict) or issue_id not in step.get("issue_ids", []):
                    errors.append(
                        f"{issue_id}.origin_ref ledger step must link back to the issue"
                    )
            elif (
                status != "resolved"
                and origin_kind == "obligation_pointer"
                and origin_ledger is not None
            ):
                found, _ = resolve_json_pointer(
                    origin_ledger.get("obligation"), origin_ref.get("pointer")
                )
                if not found:
                    errors.append(f"{issue_id}.origin_ref obligation pointer is unresolved")
            elif (
                status != "resolved"
                and origin_kind == "dependency_use"
                and origin_ledger is not None
            ):
                use_id = origin_ref.get("use_id")
                dependency_records = [
                    dependency
                    for step in origin_ledger.get("steps", [])
                    if isinstance(step, dict)
                    for dependency in step.get("dependencies", [])
                    if isinstance(dependency, dict)
                ] + [
                    dependency
                    for dependency in origin_ledger.get("review", {}).get(
                        "direct_dependencies", []
                    )
                    if isinstance(dependency, dict)
                ]
                matching_dependencies = [
                    dependency
                    for dependency in dependency_records
                    if dependency.get("use_id") == use_id
                ]
                if not matching_dependencies:
                    errors.append(f"{issue_id}.origin_ref dependency use is unresolved")
                else:
                    origin_dependency = matching_dependencies[0]
                matching_edges = [
                    edge
                    for edge in (dependency_edges or [])
                    if isinstance(edge, dict)
                    and edge.get("dependent_unit") == affected_result
                    and edge.get("use_id") == use_id
                ]
                if dependency_edges is not None:
                    if len(matching_edges) != 1:
                        errors.append(
                            f"{issue_id}.origin_ref dependency use must resolve "
                            "exactly one canonical registry edge"
                        )
                    else:
                        origin_dependency_edge = matching_edges[0]
                        if issue_id not in origin_dependency_edge.get(
                            "issue_ids", []
                        ):
                            errors.append(
                                f"{issue_id}.origin_ref dependency use must link "
                                "back through the canonical registry edge issue_ids"
                            )
            elif status != "resolved" and origin_kind == "interface_record":
                interface_id = origin_ref.get("interface_id")
                if (
                    not is_nonempty_string(interface_id)
                    or interfaces is None
                    or interface_id not in interfaces
                ):
                    errors.append(f"{issue_id}.origin_ref interface is unresolved")
                else:
                    origin_interface = interfaces[interface_id]
                    if issue.get("interface_id") != interface_id:
                        errors.append(
                            f"{issue_id}.origin_ref interface_id must equal "
                            "the issue interface_id"
                        )
                    if affected_result not in origin_interface.get(
                        "affected_results", []
                    ):
                        errors.append(
                            f"{issue_id}.origin_ref interface does not affect "
                            "affected_result"
                        )
                    if issue_id not in origin_interface.get("issue_ids", []):
                        errors.append(
                            f"{issue_id}.origin_ref interface must link back "
                            "through issue_ids"
                        )
                evidence_spans = origin_ref.get("evidence_spans")
                if not isinstance(evidence_spans, list) or not evidence_spans:
                    errors.append(
                        f"{issue_id}.origin_ref.evidence_spans must be a "
                        "nonempty list"
                    )
                    evidence_spans = []
                if evidence_base is None:
                    errors.append(
                        f"{issue_id}.origin_ref.evidence_spans cannot be source-checked"
                    )
                    validated_origin_spans: list[dict[str, Any]] = []
                else:
                    validated_origin_spans = validate_locked_span_list(
                        evidence_spans,
                        evidence_base,
                        f"{issue_id}.origin_ref.evidence_spans",
                        errors,
                        allow_empty=True,
                    )
                if origin_interface is not None and validated_origin_spans:
                    canonical_spans = {
                        identity
                        for span in nested_locked_spans(origin_interface)
                        if (identity := locked_span_identity(span)) is not None
                    }
                    for span_index, span in enumerate(validated_origin_spans, 1):
                        if locked_span_identity(span) not in canonical_spans:
                            errors.append(
                                f"{issue_id}.origin_ref.evidence_spans[{span_index}] "
                                "is not a canonical member of the interface record"
                            )
            elif status != "resolved" and origin_kind == "global_check":
                aspect = origin_ref.get("aspect")
                if not is_nonempty_string(aspect):
                    errors.append(
                        f"{issue_id}.origin_ref global aspect must be explicit"
                    )
                elif global_checks is None or aspect not in global_checks:
                    errors.append(
                        f"{issue_id}.origin_ref global aspect is unresolved"
                    )
                else:
                    origin_global_check = global_checks[aspect]
                    if issue_id not in origin_global_check.get("issue_ids", []):
                        errors.append(
                            f"{issue_id}.origin_ref global check must link back "
                            "through issue_ids"
                        )
                    if affected_result not in origin_global_check.get(
                        "affected_units", []
                    ):
                        errors.append(
                            f"{issue_id}.origin_ref global check does not name "
                            "affected_result"
                        )
                evidence_spans = origin_ref.get("evidence_spans")
                if not isinstance(evidence_spans, list) or not evidence_spans:
                    errors.append(
                        f"{issue_id}.origin_ref.evidence_spans must be a "
                        "nonempty list"
                    )
                    evidence_spans = []
                if evidence_base is None:
                    errors.append(
                        f"{issue_id}.origin_ref.evidence_spans cannot be source-checked"
                    )
                else:
                    validate_locked_span_list(
                        evidence_spans,
                        evidence_base,
                        f"{issue_id}.origin_ref.evidence_spans",
                        errors,
                        allow_empty=True,
                    )

            origin_move_closure: dict[str, set[Any]] = {
                "move_keys": set(),
                "obligation_pointers": set(),
                "dependency_uses": set(),
            }
            origin_linked_conclusions: set[str] = set()
            if (
                origin_kind == "ledger_move"
                and origin_ledger is not None
                and origin_move is not None
            ):
                origin_step_id = str(origin_ref.get("step_id"))
                origin_move_id = str(origin_ref.get("move_id"))
                origin_key = (origin_step_id, origin_move_id)
                origin_move_closure = ledger_support_contract_closure(
                    origin_ledger, origin_step_id, origin_move_id
                )
                for result in origin_ledger.get("review", {}).get(
                    "conclusion_results", []
                ):
                    support = (
                        result.get("support")
                        if isinstance(result, dict)
                        else None
                    )
                    if not isinstance(support, dict):
                        continue
                    result_closure = ledger_support_contract_closure(
                        origin_ledger,
                        str(support.get("step_id")),
                        str(support.get("move_id")),
                    )
                    if origin_key in result_closure["move_keys"] and (
                        is_nonempty_string(result.get("conclusion_id"))
                    ):
                        origin_linked_conclusions.add(
                            str(result["conclusion_id"])
                        )

            contract_refs = issue.get("contract_refs")
            if not isinstance(contract_refs, list) or not contract_refs:
                errors.append(f"{issue_id}.contract_refs must be a nonempty list")
                contract_refs = []
            seen_contract_refs: set[str] = set()
            contract_refs_on_root = 0
            exact_origin_contract = False
            root_contract_connected_to_origin = False
            for ref_index, contract_ref in enumerate(contract_refs, 1):
                ref_prefix = f"{issue_id}.contract_refs[{ref_index}]"
                if not isinstance(contract_ref, dict):
                    errors.append(f"{ref_prefix} must be an object")
                    continue
                ref_key = canonical_sha256(contract_ref)
                if ref_key in seen_contract_refs:
                    errors.append(f"{issue_id}.contract_refs contains duplicates")
                seen_contract_refs.add(ref_key)
                ref_kind = contract_ref.get("kind")
                if not is_enum_value(ref_kind, ISSUE_CONTRACT_REF_KINDS):
                    errors.append(f"{ref_prefix}.kind is invalid")
                    continue
                ref_unit_id = contract_ref.get("unit_id")
                if ref_unit_id == affected_result:
                    contract_refs_on_root += 1
                ref_ledger = ledgers_by_unit.get(str(ref_unit_id))
                if ref_ledger is None:
                    errors.append(f"{ref_prefix}.unit_id is unresolved")
                    continue
                if ref_kind == "conclusion":
                    conclusion_id = contract_ref.get("conclusion_id")
                    conclusions = ref_ledger.get("obligation", {}).get(
                        "conclusions", []
                    )
                    conclusion_matches = sum(
                        isinstance(row, dict) and row.get("id") == conclusion_id
                        for row in conclusions
                    )
                    if conclusion_matches != 1:
                        errors.append(f"{ref_prefix}.conclusion_id is unresolved")
                    elif (
                        status != "resolved"
                        and
                        origin_kind == "ledger_move"
                        and ref_unit_id == origin_unit_id
                    ):
                        if conclusion_id in origin_linked_conclusions:
                            root_contract_connected_to_origin = True
                        else:
                            errors.append(
                                f"{ref_prefix}.conclusion_id {conclusion_id} is "
                                "not linked back to the ledger-move origin "
                                "support closure"
                            )
                elif ref_kind == "obligation_pointer":
                    found, _ = resolve_json_pointer(
                        ref_ledger.get("obligation"), contract_ref.get("pointer")
                    )
                    if not found:
                        errors.append(f"{ref_prefix}.pointer is unresolved")
                    elif (
                        status != "resolved"
                        and
                        origin_kind == "ledger_move"
                        and ref_unit_id == origin_unit_id
                        and contract_ref.get("pointer")
                        in origin_move_closure["obligation_pointers"]
                    ):
                        root_contract_connected_to_origin = True
                    if (
                        status != "resolved"
                        and
                        origin_kind == "obligation_pointer"
                        and ref_unit_id == origin_unit_id
                        and contract_ref.get("pointer") == origin_ref.get("pointer")
                    ):
                        exact_origin_contract = True
                else:
                    use_id = contract_ref.get("use_id")
                    use_records = [
                        row
                        for row in ref_ledger.get("review", {}).get(
                            "direct_dependencies", []
                        )
                        if isinstance(row, dict)
                    ]
                    if sum(row.get("use_id") == use_id for row in use_records) != 1:
                        errors.append(f"{ref_prefix}.use_id is unresolved")
                    elif (
                        status != "resolved"
                        and
                        origin_kind == "ledger_move"
                        and ref_unit_id == origin_unit_id
                        and use_id in origin_move_closure["dependency_uses"]
                    ):
                        root_contract_connected_to_origin = True
                    if (
                        status != "resolved"
                        and
                        origin_kind == "dependency_use"
                        and ref_unit_id == origin_unit_id
                        and use_id == origin_ref.get("use_id")
                    ):
                        exact_origin_contract = True
            if contract_refs_on_root < 1:
                errors.append(
                    f"{issue_id}.contract_refs must include affected_result"
                )
            if (
                status != "resolved"
                and origin_kind in {"obligation_pointer", "dependency_use"}
                and not exact_origin_contract
            ):
                errors.append(
                    f"{issue_id}.contract_refs must include the exact origin_ref "
                    f"{'pointer' if origin_kind == 'obligation_pointer' else 'use_id'}"
                )
            if (
                status != "resolved"
                and
                origin_kind == "ledger_move"
                and origin_move is not None
                and not root_contract_connected_to_origin
            ):
                errors.append(
                    f"{issue_id}.contract_refs has no affected-result contract "
                    "linked back to the ledger-move origin support closure"
                )

            invalidation_kind = issue.get("invalidation_kind")
            if not is_enum_value(invalidation_kind, ISSUE_INVALIDATION_KINDS):
                errors.append(f"{issue_id}.invalidation_kind is invalid")
            root_summary = summaries_by_unit.get(str(affected_result), {})
            components = root_summary.get("review_components", {})
            required_component = {
                "proof_gap": ("argument_status", {"gap"}),
                "proof_invalid": ("argument_status", {"invalid"}),
                "statement_refuted": ("statement_status", {"refuted"}),
                "dependency_mismatch": (
                    "dependency_closure",
                    {"gap", "incorrect", "unclear"},
                ),
            }.get(invalidation_kind)
            if required_component is not None and status != "resolved":
                component, allowed = required_component
                if components.get(component) not in allowed:
                    errors.append(
                        f"{issue_id}.invalidation_kind disagrees with root "
                        f"{component}"
                    )
            if status == "resolved":
                clean_component = {
                    "proof_gap": ("argument_status", {"valid", "conditional"}),
                    "proof_invalid": (
                        "argument_status",
                        {"valid", "conditional"},
                    ),
                    "statement_refuted": (
                        "statement_status",
                        {"established", "conditional"},
                    ),
                    "dependency_mismatch": (
                        "dependency_closure",
                        {"verified", "conditionally_verified"},
                    ),
                }.get(invalidation_kind)
                if clean_component is not None:
                    component, allowed = clean_component
                    if components.get(component) not in allowed:
                        errors.append(
                            f"{issue_id}: resolved issue retains a nonclean root "
                            f"{component}"
                        )
            if invalidation_kind == "presentation_only" and issue.get("load_bearing"):
                errors.append(
                    f"{issue_id}: presentation_only cannot be load-bearing"
                )
            if (
                status != "resolved"
                and
                invalidation_kind in {"proof_gap", "proof_invalid"}
                and origin_kind == "ledger_move"
                and (
                    origin_move is None
                    or not isinstance(origin_move.get("failure"), dict)
                    or origin_move["failure"].get("issue_id") != issue_id
                )
            ):
                errors.append(
                    f"{issue_id}.origin_ref ledger move needs a matching "
                    "failure.issue_id for the proof failure"
                )
            if invalidation_kind == "dependency_mismatch":
                if origin_kind != "dependency_use":
                    errors.append(
                        f"{issue_id}.invalidation_kind dependency_mismatch "
                        "requires a dependency_use origin_ref"
                    )
                elif status in {"open", "deferred"}:
                    mismatch_statuses = (
                        {"gap", "incorrect"}
                        if finding_status == "defect"
                        else {"unclear"}
                        if finding_status == "inconclusive"
                        else set()
                    )
                    if (
                        origin_dependency is not None
                        and origin_dependency.get("status")
                        not in mismatch_statuses
                    ):
                        errors.append(
                            f"{issue_id}.origin_ref dependency use status "
                            f"{origin_dependency.get('status')!r} cannot establish "
                            "dependency_mismatch with finding_status "
                            f"{finding_status!r}"
                        )
                    if origin_dependency_edge is not None:
                        edge_status = origin_dependency_edge.get(
                            "effective_status",
                            origin_dependency_edge.get("status"),
                        )
                        if edge_status not in mismatch_statuses:
                            errors.append(
                                f"{issue_id}.origin_ref canonical dependency "
                                f"status {edge_status!r} cannot establish "
                                "dependency_mismatch with finding_status "
                                f"{finding_status!r}"
                            )
            if invalidation_kind == "statement_refuted" and status != "resolved":
                failure = (
                    origin_move.get("failure")
                    if isinstance(origin_move, dict)
                    else None
                )
                if (
                    origin_kind != "ledger_move"
                    or not isinstance(failure, dict)
                    or failure.get("kind") not in REFUTATION_FAILURE_KINDS
                    or failure.get("issue_id") != issue_id
                ):
                    errors.append(
                        f"{issue_id}.invalidation_kind statement_refuted "
                        "requires a refuting ledger_move origin_ref"
                    )
            if (
                invalidation_kind == "scope_inconclusive"
                and status != "resolved"
                and finding_status != "inconclusive"
            ):
                errors.append(
                    f"{issue_id}.invalidation_kind scope_inconclusive requires "
                    "finding_status inconclusive"
                )

            suggested_changes = issue.get("suggested_changes")
            if not isinstance(suggested_changes, list) or not suggested_changes:
                errors.append(f"{issue_id}.suggested_changes must be a nonempty list")
                suggested_changes = []
            for change_index, change in enumerate(suggested_changes, 1):
                change_prefix = f"{issue_id}.suggested_changes[{change_index}]"
                if not isinstance(change, dict):
                    errors.append(f"{change_prefix} must be an object")
                    continue
                target_ref = change.get("target_ref")
                if not isinstance(target_ref, dict) or target_ref.get("kind") != "source_span":
                    errors.append(
                        f"{change_prefix}.target_ref must be a source_span object"
                    )
                elif evidence_base is None:
                    errors.append(f"{change_prefix}.target_ref cannot be source-checked")
                else:
                    validate_locked_span(
                        target_ref,
                        evidence_base,
                        f"{change_prefix}.target_ref",
                        errors,
                    )
                change_action = change.get("action")
                if not is_enum_value(change_action, SUGGESTED_CHANGE_ACTIONS):
                    errors.append(f"{change_prefix}.action is invalid")
                if not is_substantive_string(change.get("proposal")):
                    errors.append(f"{change_prefix}.proposal must be substantive")
                errors.extend(
                    validate_repair_cost_fields(
                        change,
                        change_action if isinstance(change_action, str) else None,
                        repair_search if isinstance(repair_search, dict) else None,
                        change_prefix,
                    )
                )
                verification_status = change.get("verification_status")
                if not is_enum_value(
                    verification_status, SUGGESTED_CHANGE_STATUSES
                ):
                    errors.append(
                        f"{change_prefix}.verification_status is invalid"
                    )
                required_rechecks = validate_string_list(
                    change.get("required_rechecks"),
                    f"{change_prefix}.required_rechecks",
                    errors,
                )
                if required_rechecks != sorted(affected_results):
                    errors.append(
                        f"{change_prefix}.required_rechecks must equal the full "
                        "affected result closure"
                    )
                if verification_status == "verified_sufficient" and status != "resolved":
                    if evidence_base is None:
                        errors.append(f"{change_prefix}: verified_sufficient requires a resolved issue or a source-checked accepted supplemental review")
                    else:
                        errors.extend(checked_suggested_change_errors(issue, change, change_index, evidence_base, ledgers_by_unit))
            if status == "resolved" and isinstance(
                resolution_archive, dict
            ) and evidence_base is not None:
                resolution_requirements = validate_current_resolution(
                    issue,
                    resolution_archive,
                    evidence_base,
                    errors,
                    ledgers_by_unit,
                    list(dependency_edges or []),
                    interfaces,
                    global_checks,
                )
                for required_unit in resolution_requirements["required_units"]:
                    required_summary = summaries_by_unit.get(required_unit)
                    if (
                        not isinstance(required_summary, dict)
                        or required_summary.get("expected_unit_status")
                        not in {"verified", "conditionally_verified"}
                    ):
                        errors.append(
                            f"{issue_id}: resolved affected unit {required_unit} "
                            "has not been cleanly rechecked"
                        )
        scope = issue.get("scope")
        if not is_enum_value(scope, {"unit", "global"}):
            errors.append(f"{issue_id}: scope must be unit or global")
        if (
            scope == "unit"
            and status in {"open", "deferred"}
            and issue_id not in referenced
        ):
            errors.append(f"{issue_id}: unit issue is not referenced by any ledger step")
        if status == "resolved" and issue_id in all_referenced:
            errors.append(
                f"{issue_id}: resolved issue must use historical_origin and "
                "current_resolution, not current issue backlinks in "
                + ", ".join(sorted(backlink_sources[issue_id]))
            )

        interface_id = issue.get("interface_id")
        if interface_id is not None:
            if not isinstance(interface_id, str) or not INTERFACE_ID_RE.fullmatch(
                interface_id
            ):
                errors.append(f"{issue_id}: interface_id must match MI-001")
                interface = None
            else:
                interface = interfaces.get(interface_id) if interfaces is not None else None
                if interfaces is not None and interface is None:
                    errors.append(f"{issue_id}: unknown method interface {interface_id}")
            finding_class = issue.get("finding_class")
            affected_layer = issue.get("affected_layer")
            evidence_class = issue.get("evidence_class")
            estimator_target_status = issue.get("estimator_target_status")
            inspection_status = issue.get("implementation_inspection_status")
            code_to_documented = issue.get("code_to_documented_estimator")
            code_to_target = issue.get("code_to_required_target")
            provenance_status = issue.get("execution_provenance_status")
            if not is_enum_value(finding_class, INTERFACE_FINDING_CLASSES):
                errors.append(f"{issue_id}: invalid interface finding_class")
            if not is_enum_value(affected_layer, INTERFACE_AFFECTED_LAYERS):
                errors.append(f"{issue_id}: invalid affected_layer")
            if not is_enum_value(
                evidence_class, {"observed", "inferred", "not_established"}
            ):
                errors.append(f"{issue_id}: invalid evidence_class")
            if not is_enum_value(estimator_target_status, TARGET_RELATION_VERDICTS):
                errors.append(f"{issue_id}: invalid estimator_target_status")
            if not is_enum_value(inspection_status, IMPLEMENTATION_INSPECTION_STATUSES):
                errors.append(f"{issue_id}: invalid implementation_inspection_status")
            if not is_enum_value(code_to_documented, IMPLEMENTATION_COMPARISON_VERDICTS):
                errors.append(f"{issue_id}: invalid code_to_documented_estimator")
            if not is_enum_value(code_to_target, IMPLEMENTATION_COMPARISON_VERDICTS):
                errors.append(f"{issue_id}: invalid code_to_required_target")
            if not is_enum_value(provenance_status, EXECUTION_PROVENANCE_STATUSES):
                errors.append(f"{issue_id}: invalid execution_provenance_status")
            validate_string_list(
                issue.get("resolution_evidence_needed"),
                f"{issue_id}.resolution_evidence_needed",
                errors,
            )
            if interface is not None:
                target_relation = interface.get("target_relation")
                canonical_target = (
                    target_relation.get("verdict")
                    if isinstance(target_relation, dict)
                    else None
                )
                implementation_relation = interface.get("implementation_relation")
                canonical_inspection = None
                canonical_code_to_documented = None
                canonical_code_to_target = None
                canonical_provenance = None
                if isinstance(implementation_relation, dict):
                    canonical_inspection = implementation_relation.get(
                        "inspection_status"
                    )
                    comparisons = implementation_relation.get("comparisons")
                    if isinstance(comparisons, list):
                        comparison_verdicts = {
                            comparison.get("to"): comparison.get("verdict")
                            for comparison in comparisons
                            if isinstance(comparison, dict)
                        }
                        canonical_code_to_documented = comparison_verdicts.get(
                            "documented_estimator"
                        )
                        canonical_code_to_target = comparison_verdicts.get(
                            "required_target"
                        )
                    provenance = implementation_relation.get("execution_provenance")
                    if isinstance(provenance, dict):
                        canonical_provenance = provenance.get("status")
                if estimator_target_status != canonical_target:
                    errors.append(
                        f"{issue_id}: estimator_target_status disagrees with {interface_id}"
                    )
                if inspection_status != canonical_inspection:
                    errors.append(
                        f"{issue_id}: implementation_inspection_status disagrees with {interface_id}"
                    )
                if code_to_documented != canonical_code_to_documented:
                    errors.append(
                        f"{issue_id}: code_to_documented_estimator disagrees with {interface_id}"
                    )
                if code_to_target != canonical_code_to_target:
                    errors.append(
                        f"{issue_id}: code_to_required_target disagrees with {interface_id}"
                    )
                if provenance_status != canonical_provenance:
                    errors.append(
                        f"{issue_id}: execution_provenance_status disagrees with {interface_id}"
                    )
                interface_issue_ids = interface.get("issue_ids")
                if isinstance(interface_issue_ids, list):
                    if status == "resolved" and issue_id in interface_issue_ids:
                        errors.append(
                            f"{issue_id}: resolved interface issue must not retain "
                            f"a live {interface_id}.issue_ids backlink"
                        )
                    elif (
                        status in {"open", "deferred"}
                        and issue_id not in interface_issue_ids
                    ):
                        errors.append(
                            f"{issue_id}: not linked back from "
                            f"{interface_id}.issue_ids"
                        )
                specification = interface.get("interface_specification_status")
                if (
                    status != "resolved"
                    and issue.get("load_bearing") is True
                    and interface.get("load_bearing") is not True
                ):
                    errors.append(
                        f"{issue_id}: a load-bearing issue requires a load-bearing interface"
                    )
                if finding_class == "exposition_ambiguity":
                    if (
                        status != "resolved"
                        and not is_enum_value(
                            specification, {"ambiguous", "incomplete"}
                        )
                    ):
                        errors.append(
                            f"{issue_id}: exposition_ambiguity requires an ambiguous or incomplete specification"
                        )
                    if status != "resolved" and canonical_target == "mismatch":
                        errors.append(
                            f"{issue_id}: exposition ambiguity cannot be reported as a target mismatch"
                        )
                if (
                    status != "resolved"
                    and finding_class == "estimator_target_mismatch"
                    and canonical_target != "mismatch"
                ):
                    errors.append(
                        f"{issue_id}: estimator_target_mismatch requires an established target mismatch"
                    )
                if (
                    status != "resolved"
                    and
                    finding_class == "implementation_mismatch"
                    and canonical_code_to_documented != "inconsistent"
                ):
                    errors.append(
                        f"{issue_id}: implementation_mismatch requires code-to-documentation inconsistency"
                    )
                if (
                    status != "resolved"
                    and
                    finding_class == "implementation_mismatch"
                    and issue.get("load_bearing") is True
                    and interface.get("implementation_required_for_claim") is not True
                ):
                    errors.append(
                        f"{issue_id}: a load-bearing implementation mismatch must be required for the claim"
                    )
                if (
                    status != "resolved"
                    and finding_class == "scope_boundary"
                    and not is_enum_value(
                        canonical_inspection,
                        {"available_not_checked", "unavailable", "out_of_scope"},
                    )
                ):
                    errors.append(
                        f"{issue_id}: scope_boundary requires an uninspected implementation status"
                    )
                if (
                    status != "resolved"
                    and
                    finding_class == "reproducibility_gap"
                    and canonical_provenance == "matched"
                ):
                    errors.append(
                        f"{issue_id}: reproducibility_gap conflicts with matched execution provenance"
                    )
                if (
                    status != "resolved"
                    and
                    finding_class == "reproducibility_gap"
                    and issue.get("load_bearing") is True
                    and interface.get("execution_provenance_required_for_claim") is not True
                ):
                    errors.append(
                        f"{issue_id}: a load-bearing reproducibility gap must be required for the claim"
                    )
                if status == "resolved":
                    resolved_interface_ok = {
                        "exposition_ambiguity": specification == "clear",
                        "estimator_target_mismatch": canonical_target
                        in {"match", "conditional_match"},
                        "implementation_mismatch": canonical_code_to_documented
                        in {"consistent", "not_applicable"},
                        "scope_boundary": canonical_inspection
                        in {"inspected", "not_applicable"},
                        "reproducibility_gap": canonical_provenance
                        in {"matched", "not_applicable"},
                    }.get(finding_class, False)
                    if not resolved_interface_ok:
                        errors.append(
                            f"{issue_id}: resolved interface record does not show "
                            f"a clean current {finding_class} state"
                        )

        if final and not isinstance(issue.get("load_bearing"), bool):
            errors.append(f"{issue_id}: load_bearing must be true or false")
        if final and is_enum_value(severity, {"S0", "S1"}) and issue.get("load_bearing") is not True:
            errors.append(f"{issue_id}: S0 and S1 issues must be load-bearing")
        if repair_search is None:
            if final and is_enum_value(severity, {"S0", "S1"}):
                errors.append(
                    f"{issue_id}: severity {severity} requires a repair_search "
                    "record documenting the bounded repair attempts that "
                    "ground the S0/S1 boundary"
                )
        else:
            errors.extend(
                validate_repair_search(
                    repair_search,
                    severity if is_enum_value(severity, ISSUE_SEVERITIES) else None,
                    f"{issue_id}.repair_search",
                )
            )
        if status == "resolved" and final:
            if not is_substantive_string(issue.get("resolution")):
                errors.append(f"{issue_id}: resolved issue needs a substantive resolution")
            if not is_substantive_string(issue.get("source_revision")):
                errors.append(f"{issue_id}: resolved issue needs a substantive source_revision")
            validate_string_list(
                issue.get("recheck_evidence"),
                f"{issue_id}.recheck_evidence",
                errors,
                substantive=True,
            )
            if issue.get("source_snapshot_sha256") != source_snapshot_id:
                errors.append(
                    f"{issue_id}: resolved issue source_snapshot_sha256 is stale"
                )
            rechecked_units = validate_string_list(
                issue.get("rechecked_units"),
                f"{issue_id}.rechecked_units",
                errors,
            )
            if rechecked_units != resolution_requirements["required_units"]:
                errors.append(
                    f"{issue_id}.rechecked_units must equal the historical-current "
                    "affected union exactly"
                )
            rechecked_dependency_uses = validate_string_list(
                issue.get("rechecked_dependency_uses"),
                f"{issue_id}.rechecked_dependency_uses",
                errors,
                allow_empty=True,
            )
            if len(rechecked_dependency_uses) != len(
                set(rechecked_dependency_uses)
            ) or not all(
                DEPENDENCY_USE_ID_RE.fullmatch(use_id)
                for use_id in rechecked_dependency_uses
            ):
                errors.append(
                    f"{issue_id}.rechecked_dependency_uses must contain unique Dxxx IDs"
                )
            elif (
                rechecked_dependency_uses
                != resolution_requirements["required_dependency_uses"]
            ):
                errors.append(
                    f"{issue_id}.rechecked_dependency_uses must equal the "
                    "historical-current dependency-use union"
                )
            reconciled_deliverables = validate_string_list(
                issue.get("reconciled_deliverables"),
                f"{issue_id}.reconciled_deliverables",
                errors,
                allow_empty=True,
            )
            if len(reconciled_deliverables) != len(set(reconciled_deliverables)) or not all(
                REPORT_DELIVERABLE_ID_RE.fullmatch(deliverable_id)
                for deliverable_id in reconciled_deliverables
            ):
                errors.append(
                    f"{issue_id}.reconciled_deliverables must contain unique Rxxx IDs"
                )
            else:
                archived_deliverables = (
                    resolution_archive.get("required_closure", {}).get(
                        "report_deliverables", []
                    )
                    if isinstance(resolution_archive, dict)
                    else []
                )
                current_deliverables = [
                    item
                    for item in issue.get(
                        "reconciled_deliverables", []
                    )
                    if is_nonempty_string(item)
                ]
                required_deliverables = sorted(
                    set(archived_deliverables) | set(current_deliverables)
                )
                if reconciled_deliverables != required_deliverables:
                    errors.append(
                        f"{issue_id}.reconciled_deliverables must preserve the "
                        "historical deliverable closure"
                    )
            if interface_id is not None:
                contract = issue.get("semantic_contract")
                if not isinstance(contract, dict):
                    errors.append(
                        f"{issue_id}: resolved interface issue needs a semantic_contract"
                    )
                else:
                    if not is_nonempty_string(contract.get("protected_meaning")):
                        errors.append(
                            f"{issue_id}.semantic_contract.protected_meaning must be explicit"
                        )
                    validate_string_list(
                        contract.get("dependent_claims"),
                        f"{issue_id}.semantic_contract.dependent_claims",
                        errors,
                    )
                    validate_string_list(
                        contract.get("reopen_if"),
                        f"{issue_id}.semantic_contract.reopen_if",
                        errors,
                    )
                    if not is_nonempty_string(contract.get("regression_check")):
                        errors.append(
                            f"{issue_id}.semantic_contract.regression_check must be explicit"
                        )
                    contract_snapshot = contract.get("source_snapshot_sha256")
                    if not is_nonempty_string(contract_snapshot):
                        errors.append(
                            f"{issue_id}.semantic_contract.source_snapshot_sha256 must be explicit"
                        )
                    elif (
                        source_snapshot_id is not None
                        and contract_snapshot != source_snapshot_id
                    ):
                        errors.append(
                            f"{issue_id}: semantic contract refers to a stale source snapshot"
                        )
                    spans = contract.get("supporting_spans")
                    if evidence_base is None:
                        errors.append(
                            f"{issue_id}: cannot verify semantic_contract supporting spans"
                        )
                    else:
                        validated_spans = validate_locked_span_list(
                            spans,
                            evidence_base,
                            f"{issue_id}.semantic_contract.supporting_spans",
                            errors,
                        )
                        allowed_roles = {
                            "authoritative_definition",
                            "authoritative_algorithm",
                            "authoritative_configuration",
                        }
                        for span in validated_spans:
                            if span.get("role") not in allowed_roles:
                                errors.append(
                                    f"{issue_id}: semantic support must be an authoritative span"
                                )

    for issue_id in sorted(all_referenced - seen):
        errors.append(f"Current audit records reference undefined issue: {issue_id}")
    counts["total"] = len(issues)
    return errors, counts


def render_issue_summary(issues: list[dict[str, Any]]) -> str:
    severity_counts = Counter(
        issue.get("severity")
        for issue in issues
        if isinstance(issue, dict)
        and is_enum_value(issue.get("severity"), ISSUE_SEVERITIES)
    )
    status_counts = Counter(
        issue.get("status")
        for issue in issues
        if isinstance(issue, dict)
        and is_enum_value(issue.get("status"), ISSUE_STATUSES)
    )
    finding_counts = Counter(
        issue.get("finding_status")
        for issue in issues
        if isinstance(issue, dict)
        and is_enum_value(issue.get("finding_status"), ISSUE_FINDING_STATUSES)
    )
    rows = [
        "# Canonical Issue Summary",
        "",
        "This file is generated from `ISSUE_LOG.json`. Do not edit counts here.",
        "",
        "## Counts",
        "",
        "| Metric | Count |",
        "|---|---|",
        f"| Total | {len(issues)} |",
    ]
    rows.extend(f"| {level} | {severity_counts[level]} |" for level in sorted(ISSUE_SEVERITIES))
    rows.extend(f"| {status} | {status_counts[status]} |" for status in sorted(ISSUE_STATUSES))
    rows.extend(
        f"| finding_{status} | {finding_counts[status]} |"
        for status in sorted(ISSUE_FINDING_STATUSES)
    )
    rows.extend(
        [
            "",
            "## Issues",
            "",
            "| Issue | Severity | Load-bearing | Confidence | Lifecycle | Finding | Invalidation kind | Origin ref | Contract refs | Affected results |",
            "|---|---|---|---|---|---|---|---|---|---|",
        ]
    )
    if not issues:
        rows.append(
            "| None | None | None | None | None | None | None | None | None | None |"
        )
    else:
        for issue in sorted(
            (item for item in issues if isinstance(item, dict)),
            key=lambda item: str(item.get("id", "")),
        ):
            values = canonical_issue_row(issue)
            rows.append(
                "| "
                + " | ".join(
                    escape_markdown(value) for value in values
                )
                + " |"
            )
    rows.append("")
    return "\n".join(rows)


def audit_ledgers(
    root: Path, final: bool, *, primary_only: bool = False
) -> tuple[list[str], list[dict[str, Any]], set[str]]:
    errors: list[str] = []
    summaries: list[dict[str, Any]] = []
    referenced: set[str] = set()
    root = root.resolve()
    live_ledger_directory = (root / "audit" / "04_local_checks").resolve()
    for ledger_path in live_local_check_artifacts(root, ".ledger.json"):
        ledger_errors, summary = check_ledger_data(
            ledger_path, final, primary_only=primary_only
        )
        summaries.append(summary)
        referenced.update(summary.get("issue_references", []))
        errors.extend(f"{ledger_path}: {error}" for error in ledger_errors)
        if (
            final
            and not ledger_errors
            and ledger_path.parent.resolve() == live_ledger_directory
            and is_nonempty_string(summary.get("unit_id"))
        ):
            try:
                expected_packet = build_context_packet(
                    root, str(summary["unit_id"]), "primary"
                )
            except (OSError, UnicodeError, ValueError) as exc:
                errors.append(
                    f"{ledger_path}: cannot reconstruct current "
                    f"calibration-bound work context: {exc}"
                )
            else:
                if primary_only and expected_packet.get("semantic_review_ready") is not True:
                    errors.append(
                        f"{ledger_path}: primary context is not ready for independent "
                        "review: " + "; ".join(expected_packet.get("semantic_review_reasons", []))
                    )
                ledger, read_errors = load_json_object(
                    ledger_path, "proof-unit ledger"
                )
                if read_errors:
                    errors.extend(
                        f"{ledger_path}: {error}" for error in read_errors
                    )
                elif ledger.get("work_context_sha256") != expected_packet.get(
                    "work_context_sha256"
                ):
                    errors.append(
                        f"{ledger_path}: work_context_sha256 is stale; "
                        "regenerate the primary packet, fully recheck the unit, "
                        "and replace or recompile the ledger"
                    )
    return errors, summaries, referenced


def cmd_issues(args: argparse.Namespace) -> int:
    root = args.root.resolve()
    before_challenge = bool(getattr(args, "before_challenge", False))
    if before_challenge and (
        args.final or args.write_summary or getattr(args, "write_report_views", False)
    ):
        raise ValueError(
            "issues --before-challenge is read-only and cannot be combined with "
            "--final, --write-summary, or --write-report-views"
        )
    strict = args.final or before_challenge
    errors, summaries, referenced = audit_ledgers(
        root, strict, primary_only=before_challenge
    )
    errors = [*audit_internal_redirect_errors(root), *errors]
    if strict and not summaries:
        errors.append("Final issue reconciliation requires at least one ledger")
    issue_path, issues, issue_schema_version, issue_read_errors = load_issue_log(root)
    errors.extend(issue_read_errors)
    if strict and issue_schema_version != SCHEMA_VERSION:
        errors.append(
            "upgrade_required: final issue reconciliation requires "
            f"ISSUE_LOG.json schema_version {SCHEMA_VERSION}; schema "
            f"{issue_schema_version!r} is inspection-only"
        )
    _, manifest, manifest_errors = load_audit_manifest(root)
    errors.extend(manifest_errors)
    if before_challenge and not manifest_errors:
        source_errors, _ = check_audit_finalization(
            root, check_reports=False, source_inventory_only=True
        )
        errors.extend(source_errors)
    summaries_by_id = {
        summary.get("unit_id"): summary
        for summary in summaries
        if isinstance(summary, dict)
        and is_nonempty_string(summary.get("unit_id"))
    }
    interfaces: dict[str, dict[str, Any]] | None = None
    source_snapshot_id: str | None = None
    in_scope: list[str] | None = None
    reverse_graph: dict[str, set[str]] | None = None
    dependency_edges: list[dict[str, Any]] = []
    global_checks: dict[str, dict[str, Any]] | None = None
    if not manifest_errors:
        source_snapshot = manifest.get("source_snapshot")
        if isinstance(source_snapshot, dict) and is_nonempty_string(
            source_snapshot.get("sha256")
        ):
            source_snapshot_id = source_snapshot["sha256"]
        registry_path, registry_path_valid = manifest_canonical_artifact_path(
            manifest,
            root,
            "method_interface_registry",
            "method-interface registry",
            errors,
        )
        if registry_path_valid:
            registry, registry_errors = load_json_object(
                registry_path, "method-interface registry"
            )
            errors.extend(registry_errors)
            if not registry_errors:
                interfaces = validate_method_interface_registry(
                    registry, root, errors, final=strict
                )
                for interface in interfaces.values():
                    referenced.update(
                        issue_id
                        for issue_id in interface.get("issue_ids", [])
                        if is_nonempty_string(issue_id)
                    )
        if strict:
            errors.extend(source_snapshot_freshness_errors(root, manifest))
            scope = manifest.get("audit_scope")
            if not isinstance(scope, dict):
                errors.append(
                    "Final issue reconciliation requires audit_scope as an object"
                )
                scope = {}
            if scope.get("status") != "reviewed":
                errors.append(
                    "Final issue reconciliation requires reviewed audit_scope"
                )
            in_scope = validate_string_list(
                scope.get("in_scope_units"),
                "audit_scope.in_scope_units",
                errors,
            )
            if before_challenge:
                if not in_scope or len(in_scope) != len(set(in_scope)):
                    errors.append(
                        "Pre-challenge readiness requires unique nonempty in_scope_units"
                    )
                primary_units = [summary.get("unit_id") for summary in summaries]
                for unit_id in in_scope:
                    count = primary_units.count(unit_id)
                    if count != 1:
                        errors.append(
                            "Pre-challenge readiness requires exactly one completed "
                            f"primary ledger for in-scope unit {unit_id}; found {count}"
                        )
            inventory_path, inventory_path_valid = (
                manifest_canonical_artifact_path(
                    manifest,
                    root,
                    "inventory_file",
                    "proof-unit inventory",
                    errors,
                )
            )
            if inventory_path_valid and not inventory_path.is_file():
                errors.append(
                    "Final issue reconciliation cannot find the reviewed "
                    f"inventory: {inventory_path}"
                )
            dependency_registry_path, dependency_path_valid = (
                manifest_canonical_artifact_path(
                    manifest,
                    root,
                    "dependency_registry",
                    "dependency registry",
                    errors,
                )
            )
            dependency_registry, dependency_registry_errors = (
                load_json_object(
                    dependency_registry_path, "dependency registry"
                )
                if dependency_path_valid
                else ({}, [])
            )
            errors.extend(dependency_registry_errors)
            if dependency_path_valid and not dependency_registry_errors:
                closure_result = validate_dependency_closure(
                    dependency_registry,
                    root,
                    summaries_by_id,
                    source_snapshot_sha256=source_snapshot_id,
                    inventory_sha256=(
                        sha256_file(inventory_path)
                        if inventory_path_valid and inventory_path.is_file()
                        else ""
                    ),
                    in_scope=in_scope,
                    errors=errors,
                )
                dependency_edges = closure_result["edges"]
                apply_derived_use_site_sufficiency(
                    summaries_by_id, dependency_edges
                )
                referenced.update(closure_result["issue_ids"])
                reverse_graph = {
                    unit_id: set() for unit_id in summaries_by_id
                }
                for dependent, dependencies in closure_result[
                    "unit_graph"
                ].items():
                    for dependency in dependencies:
                        reverse_graph.setdefault(dependency, set()).add(
                            dependent
                        )
            if before_challenge and inventory_path_valid and inventory_path.is_file():
                inventory, inventory_errors = load_json_object(
                    inventory_path, "proof-unit inventory"
                )
                errors.extend(inventory_errors)
                if not inventory_errors:
                    errors.extend(primary_reference_readiness_errors(
                        root, manifest, inventory, summaries_by_id,
                        dependency_edges, in_scope,
                    ))
            completion = manifest.get("completion")
            if not isinstance(completion, dict):
                errors.append(
                    "Final issue reconciliation requires manifest completion "
                    "as an object"
                )
                completion = {}
            global_pass = completion.get("global_consistency_pass")
            global_result = validate_global_consistency_pass(
                global_pass, in_scope, errors
            )
            referenced.update(global_result.get("issue_ids", set()))
            checks = (
                global_pass.get("checks")
                if isinstance(global_pass, dict)
                else []
            )
            global_checks = {
                row.get("aspect"): row
                for row in checks
                if isinstance(row, dict)
                and is_nonempty_string(row.get("aspect"))
            }
    issue_errors, counts = validate_issues(
        issues,
        referenced,
        strict,
        evidence_base=root,
        interfaces=interfaces,
        source_snapshot_id=source_snapshot_id,
        in_scope=in_scope,
        reverse_graph=reverse_graph,
        ledger_summaries=summaries,
        dependency_edges=dependency_edges if strict else None,
        global_checks=global_checks,
    )
    errors.extend(issue_errors)

    summary_path, summary_path_valid = canonical_artifact_path(
        root,
        "audit/06_reports/ISSUE_SUMMARY.md",
        "issue summary",
        errors,
    )
    summary_candidate = (
        render_issue_summary(issues)
        if args.write_summary and not issue_read_errors and summary_path_valid
        else None
    )
    report_views_written = False
    report_path: Path | None = None
    report_candidate: str | None = None
    if getattr(args, "write_report_views", False) and not uses_html_report(manifest):
        if not args.final:
            errors.append("--write-report-views requires --final")
        elif not errors:
            report_path, report_path_valid = canonical_artifact_path(
                root,
                "audit/06_reports/FINAL_REPORT.md",
                "final report",
                errors,
            )
            if not report_path_valid:
                report_path = None
            elif not report_path.is_file():
                errors.append(f"Canonical final report not found: {report_path}")
            else:
                required_challenges, _ = required_challenge_requirements(
                    manifest, issues
                )
                report_deliverables = manifest.get("report_deliverables")
                if not isinstance(report_deliverables, list):
                    report_deliverables = []
                scope = manifest.get("audit_scope")
                assessment = (
                    scope.get("overall_assessment")
                    if isinstance(scope, dict)
                    else None
                )
                results_and_impact = render_results_and_impact(
                    summaries_by_id,
                    scope.get("in_scope_units", [])
                    if isinstance(scope, dict)
                    else [],
                )
                findings_and_repairs = render_findings_and_repairs(
                    issues,
                    summaries_by_id,
                    dependency_edges,
                    required_challenges,
                    report_deliverables,
                    assessment,
                    interfaces=interfaces,
                    global_checks=global_checks,
                )
                independent_verification = render_independent_verification(
                    summaries_by_id, required_challenges
                )
                declared_deliverables = render_declared_deliverables(
                    report_deliverables
                )
                summary_fields = canonical_report_summary_fields(
                    assessment,
                    summaries_by_id,
                    scope.get("in_scope_units", [])
                    if isinstance(scope, dict)
                    else [],
                    issues,
                )
                try:
                    report_text = read_text(report_path)
                except TextArtifactReadError as exc:
                    errors.append(str(exc))
                else:
                    for label, value in summary_fields.items():
                        report_text = replace_report_scalar_text(
                            report_text, label, value
                        )
                    report_text = replace_report_section_text(
                        report_text,
                        "## Results and impact",
                        results_and_impact,
                    )
                    report_text = replace_report_section_text(
                        report_text,
                        "## Findings and repairs",
                        findings_and_repairs,
                    )
                    report_text = replace_report_nested_section_text(
                        report_text,
                        "### Independent verification",
                        independent_verification,
                    )
                    report_text = replace_report_nested_section_text(
                        report_text,
                        "### Declared external deliverables",
                        declared_deliverables,
                    )
                    report_candidate = report_text

    if not errors and not before_challenge:
        pending_writes: list[tuple[Path, str]] = []
        if report_path is not None and report_candidate is not None:
            pending_writes.append((report_path, report_candidate))
        if summary_candidate is not None:
            pending_writes.append((summary_path, summary_candidate))
        transactional_write_texts(pending_writes)
        report_views_written = report_candidate is not None
        if getattr(args, "write_report_views", False) and uses_html_report(manifest):
            report_module("proofcheck_release").render_working(report_api(), root)
            report_views_written = True

    result = {
        "audit_root": str(root),
        "issue_log": str(issue_path),
        "ledgers": len(summaries),
        "ledger_issue_references": len(referenced),
        "issue_counts": dict(counts),
        "report_views_written": report_views_written,
        "errors": len(errors),
    }
    if before_challenge:
        result.update({
            "mode": "before_challenge",
            "readiness": "ready" if not errors else "not_ready",
            "delivery_status": "NONFINAL",
            "read_only": True,
            "note": "Primary evidence and issue closure only; independent review and finalization remain required.",
        })
    print(json.dumps(result, ensure_ascii=False, indent=2))
    if errors:
        for error in errors:
            print(f"ERROR: {error}", file=sys.stderr)
        return 1
    return 0


def historical_origin_from_archive(
    archive: dict[str, Any], archive_path: Path, root: Path
) -> dict[str, Any]:
    closure = archive.get("required_closure")
    if not isinstance(closure, dict):
        closure = {}
    dependency_rows = closure.get("dependency_uses")
    dependency_ids = [
        str(row.get("use_id"))
        for row in dependency_rows
        if isinstance(row, dict) and is_nonempty_string(row.get("use_id"))
    ] if isinstance(dependency_rows, list) else []
    return {
        "artifact": archive_path.relative_to(root).as_posix(),
        "sha256": sha256_file(archive_path),
        "source_snapshot_sha256": archive.get("source_snapshot_sha256"),
        "required_units": list(closure.get("units", []))
        if isinstance(closure.get("units"), list)
        else [],
        "required_dependency_uses": dependency_ids,
        "required_challenges": list(closure.get("challenges", []))
        if isinstance(closure.get("challenges"), list)
        else [],
        "required_report_deliverables": list(
            closure.get("report_deliverables", [])
        )
        if isinstance(closure.get("report_deliverables"), list)
        else [],
    }


def adopt_existing_issue_archive(
    root: Path,
    manifest: dict[str, Any],
    issue_path: Path,
    issue_log: dict[str, Any],
    issue: dict[str, Any],
    archive_path: Path,
) -> dict[str, Any]:
    """Recover a valid archive created just before an interrupted issue-log commit."""
    archive, archive_errors = load_json_object(
        archive_path, "existing resolution archive"
    )
    if archive_errors:
        raise ValueError("; ".join(archive_errors))
    historical_origin = historical_origin_from_archive(
        archive, archive_path, root
    )
    candidate_issue = json.loads(json.dumps(issue, ensure_ascii=False))
    candidate_issue["historical_origin"] = historical_origin
    validation_errors: list[str] = []
    load_resolution_archive(candidate_issue, root, validation_errors)
    validation_errors.extend(source_snapshot_freshness_errors(root, manifest))
    if sha256_file(issue_path) != archive.get("prior_issue_log_sha256"):
        validation_errors.append(
            "Live issue log no longer equals the archive's prior issue log"
        )

    prior_record = archive.get("prior_finalization_record")
    if not isinstance(prior_record, dict):
        validation_errors.append(
            "Existing archive has no valid prior finalization record"
        )
    else:
        record_path, record_path_errors = finalization_record_path(
            manifest, root
        )
        validation_errors.extend(record_path_errors)
        archive_relative = archive_path.relative_to(root).as_posix()
        current_rows = [
            row
            for row in audit_state_manifest(root, record_path)
            if row.get("file") != archive_relative
        ]
        manifest_errors, changes = artifact_manifest_changes(
            prior_record.get("artifact_manifest"), current_rows
        )
        validation_errors.extend(manifest_errors)
        if any(changes.values()):
            validation_errors.append(
                "Current audit state changed beyond the recoverable archive file"
            )
    if validation_errors:
        raise ValueError(
            "Existing resolution archive cannot be adopted: "
            + "; ".join(validation_errors[:10])
        )
    transaction_temp = proofcheck_temp_path(archive_path)
    transaction_lock = proofcheck_lock_path(archive_path)
    if transaction_temp.exists() and transaction_temp.is_symlink():
        raise ValueError(
            f"Refusing a symlinked proofcheck temp file: {transaction_temp}"
        )
    if transaction_lock.exists() and transaction_lock.is_symlink():
        raise ValueError(
            f"Refusing a symlinked proofcheck lock file: {transaction_lock}"
        )
    issue["historical_origin"] = historical_origin
    atomic_replace_text(
        issue_path,
        json.dumps(issue_log, ensure_ascii=False, indent=2) + "\n",
    )
    if transaction_temp.exists():
        transaction_temp.unlink()
    if transaction_lock.exists():
        try:
            lock_record = json.loads(read_text(transaction_lock))
        except (OSError, UnicodeError, json.JSONDecodeError):
            lock_record = None
        if (
            isinstance(lock_record, dict)
            and lock_record.get("transaction_schema_version") == 1
            and lock_record.get("target") == archive_path.name
            and lock_record.get("expected_sha256") == sha256_file(archive_path)
        ):
            transaction_lock.unlink()
    return historical_origin


def cmd_archive_issue(args: argparse.Namespace) -> int:
    """Seal one currently finalized unresolved issue before source repair."""
    root = args.root.resolve()
    issue_id = args.issue_id
    history_directory, history_errors = confined_history_directory(root)
    if history_errors:
        raise ValueError("; ".join(history_errors))
    freshness = check_finalization_freshness(root)
    _, manifest, manifest_errors = load_audit_manifest(root)
    if manifest_errors:
        raise ValueError("; ".join(manifest_errors))
    issue_path_errors: list[str] = []
    issue_path, issue_path_valid = canonical_artifact_path(
        root,
        "audit/06_reports/ISSUE_LOG.json",
        "issue log",
        issue_path_errors,
    )
    if not issue_path_valid:
        raise ValueError("; ".join(issue_path_errors))
    issue_log, issue_log_errors = load_json_object(issue_path, "issue log")
    if issue_log_errors:
        raise ValueError("; ".join(issue_log_errors))
    issues = issue_log.get("issues")
    if not isinstance(issues, list):
        raise ValueError("ISSUE_LOG.json must contain an issues list")
    matches = [
        issue
        for issue in issues
        if isinstance(issue, dict) and issue.get("id") == issue_id
    ]
    if len(matches) != 1:
        raise ValueError(f"archive-issue must resolve exactly one issue: {issue_id}")
    issue = matches[0]
    if issue.get("status") not in {"open", "deferred"}:
        raise ValueError("archive-issue accepts only an open or deferred issue")
    if "historical_origin" in issue:
        raise ValueError(f"{issue_id} already has historical_origin")

    archive_path = history_directory / f"{issue_id}-origin.json"
    if archive_path.exists():
        historical_origin = adopt_existing_issue_archive(
            root,
            manifest,
            issue_path,
            issue_log,
            issue,
            archive_path,
        )
        print(
            json.dumps(
                {
                    "audit_root": str(root),
                    "issue_id": issue_id,
                    "archive": str(archive_path),
                    "archive_sha256": historical_origin["sha256"],
                    "recovered_existing_archive": True,
                    "next_action": (
                        "Apply the source repair, rebuild affected ledgers and "
                        "dependencies, add current_resolution, run fresh "
                        "challenges, and regenerate issue/report views."
                    ),
                },
                ensure_ascii=False,
                indent=2,
            )
        )
        return 0
    if not freshness.get("usable_finalization"):
        raise ValueError(
            "archive-issue requires a current passed finalization record for "
            "the unresolved audit"
        )

    ledger_errors, summaries, _ = audit_ledgers(root, True)
    if ledger_errors:
        raise ValueError(
            "archive-issue found invalid ledgers: " + "; ".join(ledger_errors[:5])
        )
    summaries_by_id = {
        str(summary["unit_id"]): summary
        for summary in summaries
        if isinstance(summary, dict)
        and is_nonempty_string(summary.get("unit_id"))
    }
    scope = manifest.get("audit_scope")
    if not isinstance(scope, dict):
        raise ValueError("archive-issue requires audit_scope")
    in_scope = [
        unit_id
        for unit_id in scope.get("in_scope_units", [])
        if is_nonempty_string(unit_id)
    ]
    canonical_errors: list[str] = []
    inventory_path, inventory_path_valid = manifest_canonical_artifact_path(
        manifest,
        root,
        "inventory_file",
        "proof-unit inventory",
        canonical_errors,
    )
    registry_path, registry_path_valid = manifest_canonical_artifact_path(
        manifest,
        root,
        "dependency_registry",
        "dependency registry",
        canonical_errors,
    )
    if not inventory_path_valid or not registry_path_valid:
        raise ValueError("; ".join(canonical_errors))
    registry, registry_errors = load_json_object(
        registry_path, "dependency registry"
    )
    if registry_errors:
        raise ValueError("; ".join(registry_errors))
    closure_errors: list[str] = []
    snapshot = manifest.get("source_snapshot")
    closure = validate_dependency_closure(
        registry,
        root,
        summaries_by_id,
        source_snapshot_sha256=(
            snapshot.get("sha256") if isinstance(snapshot, dict) else None
        ),
        inventory_sha256=sha256_file(inventory_path),
        in_scope=in_scope,
        errors=closure_errors,
    )
    if closure_errors:
        raise ValueError(
            "archive-issue dependency closure failed: "
            + "; ".join(closure_errors[:5])
        )
    dependency_edges = closure["edges"]
    apply_derived_use_site_sufficiency(summaries_by_id, dependency_edges)
    required_challenges, _ = required_challenge_requirements(manifest, issues)
    report_deliverables = manifest.get("report_deliverables")
    if not isinstance(report_deliverables, list):
        report_deliverables = []
    context_errors: list[str] = []
    interfaces: dict[str, dict[str, Any]] | None = None
    interface_registry_path: Path | None = None
    interface_registry_path, interface_registry_path_valid = (
        manifest_canonical_artifact_path(
            manifest,
            root,
            "method_interface_registry",
            "method-interface registry",
            context_errors,
        )
    )
    if interface_registry_path_valid:
        interface_registry, interface_registry_errors = load_json_object(
            interface_registry_path,
            "method-interface registry",
        )
        context_errors.extend(interface_registry_errors)
        if not interface_registry_errors:
            interfaces = validate_method_interface_registry(
                interface_registry, root, context_errors, final=True
            )
    completion = manifest.get("completion")
    global_checks: dict[str, dict[str, Any]] | None = None
    if isinstance(completion, dict):
        global_pass = completion.get("global_consistency_pass")
        validate_global_consistency_pass(
            global_pass, in_scope, context_errors
        )
        checks = (
            global_pass.get("checks")
            if isinstance(global_pass, dict)
            else []
        )
        global_checks = {
            row.get("aspect"): row
            for row in checks
            if isinstance(row, dict)
            and is_nonempty_string(row.get("aspect"))
        }
    if context_errors:
        raise ValueError(
            "archive-issue canonical issue context failed: "
            + "; ".join(context_errors[:5])
        )
    if not interface_registry_path_valid:
        raise ValueError(
            "archive-issue requires method_interface_registry in the manifest"
        )
    projection = canonical_issue_detail_projection(
        issue,
        summaries_by_id,
        dependency_edges,
        required_challenges,
        report_deliverables,
        scope.get("overall_assessment"),
        evidence_base=root,
        interfaces=interfaces,
        global_checks=global_checks,
    )
    required = projection.get("required_closure")
    if not isinstance(required, dict):
        raise ValueError("archive-issue could not derive required closure")
    required_units = list(required.get("units", []))
    required_use_ids = list(required.get("dependency_uses", []))
    selected_edges = issue_recheck_edges(issue, dependency_edges)
    edges_by_use: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for edge in selected_edges:
        edges_by_use[str(edge.get("use_id"))].append(edge)
    dependency_rows: list[dict[str, str]] = []
    for use_id in required_use_ids:
        matches_for_use = edges_by_use.get(str(use_id), [])
        if len(matches_for_use) != 1:
            raise ValueError(
                f"archive-issue requires one canonical edge for {use_id}"
            )
        dependency_rows.append(
            {
                "use_id": str(use_id),
                "edge_sha256": canonical_sha256(matches_for_use[0]),
            }
        )

    ledger_sha256s: dict[str, str] = {}
    sealed_ledgers: list[dict[str, str]] = []
    sealed_support_reviews: dict[str, dict[str, str]] = {}
    support_units = {
        str(edge.get("dependency_id"))
        for edge in selected_edges
        if edge.get("use_id") in required_use_ids
        and edge.get("kind") == "internal_result"
        and is_nonempty_string(edge.get("dependency_id"))
    }
    sealed_unit_ids = sorted(set(required_units) | support_units)
    for unit_id in sealed_unit_ids:
        summary = summaries_by_id.get(str(unit_id))
        ledger_value = summary.get("ledger") if isinstance(summary, dict) else None
        if not is_nonempty_string(ledger_value):
            raise ValueError(f"archive-issue cannot find ledger for {unit_id}")
        ledger_path = Path(str(ledger_value)).resolve()
        try:
            stored_ledger = ledger_path.relative_to(root).as_posix()
        except ValueError as exc:
            raise ValueError(
                f"archive-issue ledger is outside the audit root: {ledger_path}"
            ) from exc
        record = sealed_file_record(ledger_path, stored_ledger)
        ledger_sha256s[str(unit_id)] = record["sha256"]
        sealed_ledgers.append(record)
        ledger, ledger_errors = load_json_object(ledger_path, "archived ledger")
        if ledger_errors:
            raise ValueError("; ".join(ledger_errors))
        if any("statement_support" in row for row in (ledger.get("review") or {}).get("conclusion_results", []) if isinstance(row, dict)):
            for field in ("initial_response", "statement_support_review"):
                reference = (ledger.get("independent_check") or {}).get(field)
                if not isinstance(reference, dict):
                    raise ValueError(f"archive-issue requires {field} for supplemental support")
                sealed_support_reviews[reference["artifact"]] = sealed_file_record(root / reference["artifact"], reference["artifact"])

    prior_record_path = Path(str(freshness.get("record")))
    prior_record, prior_record_errors = load_json_object(
        prior_record_path, "prior finalization record"
    )
    if prior_record_errors:
        raise ValueError("; ".join(prior_record_errors))
    source_records = (
        snapshot.get("files") if isinstance(snapshot, dict) else None
    )
    if not isinstance(source_records, list):
        raise ValueError("archive-issue requires source_snapshot.files")
    sealed_sources: list[dict[str, str]] = []
    for index, source_record in enumerate(source_records, 1):
        if not isinstance(source_record, dict):
            raise ValueError(
                f"archive-issue source_snapshot.files[{index}] is invalid"
            )
        file_value = source_record.get("file")
        digest = source_record.get("sha256")
        if not is_nonempty_string(file_value):
            raise ValueError(
                f"archive-issue source_snapshot.files[{index}].file is invalid"
            )
        source_path = resolve_stored_path(str(file_value), root)
        if not source_path.is_file() or sha256_file(source_path) != digest:
            raise ValueError(
                f"archive-issue source snapshot is stale: {file_value}"
            )
        sealed_sources.append(
            sealed_file_record(source_path, str(file_value))
        )
    prior_artifacts = {
        "manifest": sealed_file_record(
            root / "AUDIT_MANIFEST.json", "AUDIT_MANIFEST.json"
        ),
        "issue_log": sealed_file_record(
            issue_path, "audit/06_reports/ISSUE_LOG.json"
        ),
        "final_report": sealed_file_record(
            root / preferred_report_path(manifest),
            preferred_report_path(manifest),
        ),
        "inventory": sealed_file_record(
            inventory_path, str(manifest.get("inventory_file"))
        ),
        "dependency_registry": sealed_file_record(
            registry_path, str(manifest.get("dependency_registry"))
        ),
        "method_interface_registry": sealed_file_record(
            interface_registry_path,
            str(manifest.get("method_interface_registry")),
        ),
        "ledgers": sorted(
            sealed_ledgers, key=lambda record: record["file"]
        ),
    }
    if sealed_support_reviews:
        prior_artifacts["statement_support_reviews"] = [sealed_support_reviews[name] for name in sorted(sealed_support_reviews)]
    archived_issue = json.loads(json.dumps(issue, ensure_ascii=False))
    archive = {
        "archive_schema_version": RESOLUTION_ARCHIVE_SCHEMA_VERSION,
        "protocol": manifest.get("protocol"),
        "source_snapshot_sha256": (
            snapshot.get("sha256") if isinstance(snapshot, dict) else None
        ),
        "issue_record": archived_issue,
        "issue_record_sha256": canonical_sha256(archived_issue),
        "prior_issue_log_sha256": sha256_file(issue_path),
        "prior_finalization_record": prior_record,
        "prior_finalization_record_sha256": canonical_sha256(prior_record),
        "prior_artifacts": prior_artifacts,
        "prior_sources": sealed_sources,
        "ledger_sha256s": ledger_sha256s,
        "dependency_registry_sha256": sha256_file(registry_path),
        "inventory_sha256": sha256_file(inventory_path),
        "root_components": summaries_by_id.get(
            str(issue.get("affected_result")), {}
        ).get("review_components", {}),
        "projection": projection,
        "projection_sha256": canonical_sha256(projection),
        "required_closure": {
            "units": required_units,
            "dependency_uses": dependency_rows,
            "challenges": list(required.get("challenges", [])),
            "report_deliverables": list(
                required.get("report_deliverables", [])
            ),
        },
        # Bind retries to the unchanged finalized state so an interrupted
        # archive transaction regenerates byte-identical content.
        "generated_utc": prior_record.get("generated_utc"),
    }
    archive["archive_payload_sha256"] = resolution_archive_payload_sha256(
        archive
    )
    history_directory.mkdir(parents=True, exist_ok=True)
    atomic_create_text(
        archive_path,
        json.dumps(archive, ensure_ascii=False, indent=2) + "\n",
    )
    issue["historical_origin"] = historical_origin_from_archive(
        archive, archive_path, root
    )
    atomic_replace_text(
        issue_path,
        json.dumps(issue_log, ensure_ascii=False, indent=2) + "\n",
    )
    print(
        json.dumps(
            {
                "audit_root": str(root),
                "issue_id": issue_id,
                "archive": str(archive_path),
                "archive_sha256": issue["historical_origin"]["sha256"],
                "next_action": (
                    "Apply the source repair, rebuild affected ledgers and "
                    "dependencies, add current_resolution, run fresh challenges, "
                    "and regenerate issue/report views."
                ),
            },
            ensure_ascii=False,
            indent=2,
        )
    )
    return 0


def combine_dependency_statuses(statuses: Iterable[str]) -> str:
    """Combine source and applicability states using the strongest limitation."""
    values = {status for status in statuses if isinstance(status, str)}
    for status in ("incorrect", "gap", "unclear", "unchecked", "conditional"):
        if status in values:
            return status
    return "verified"


def derive_use_site_sufficiency(
    edges: Iterable[dict[str, Any]],
    dependency_id: str,
    conclusion_id: str | None = None,
) -> str:
    """Project actual outgoing support, keeping applicability distinct."""
    uses = [
        edge
        for edge in edges
        if isinstance(edge, dict)
        and edge.get("kind") == "internal_result"
        and edge.get("dependency_id") == dependency_id
        and (
            conclusion_id is None
            or edge.get("dependency_conclusion_id") == conclusion_id
        )
    ]
    if not uses:
        return "not_applicable"
    statuses = {
        str(edge.get(field, "unchecked"))
        for edge in uses
        for field in ("applicability_status", "effective_status")
    }
    if statuses & {"incorrect", "gap"}:
        return "insufficient"
    if "unclear" in statuses:
        return "unclear"
    if statuses - {"verified", "passed", "conditional", "not_applicable"}:
        return "not_checked"
    if "conditional" in statuses:
        return "conditional"
    return "sufficient"


def apply_derived_use_site_sufficiency(
    summaries_by_id: dict[str, dict[str, Any]],
    edges: Iterable[dict[str, Any]],
) -> None:
    """Attach audit-wide use-site projections to in-memory summaries only."""
    edge_rows = list(edges)
    for unit_id, summary in summaries_by_id.items():
        components = summary.get("review_components")
        if isinstance(components, dict):
            components["use_site_sufficiency"] = (
                derive_use_site_sufficiency(edge_rows, unit_id)
            )
        results = summary.get("conclusion_results")
        if not isinstance(results, list):
            continue
        for result in results:
            if not isinstance(result, dict):
                continue
            conclusion_id = result.get("conclusion_id")
            if is_nonempty_string(conclusion_id):
                result["use_site_sufficiency"] = (
                    derive_use_site_sufficiency(
                        edge_rows, unit_id, str(conclusion_id)
                    )
                )


def selected_statement_support(summary: dict[str, Any], conclusion_id: str, digest: Any) -> dict[str, Any] | None:
    result = next((row for row in summary.get("conclusion_results", []) if isinstance(row, dict) and row.get("conclusion_id") == conclusion_id), {})
    support = result.get("statement_support")
    return support if isinstance(support, dict) and support.get("valid") is True and support.get("sha256") == digest else None


def statement_support_use_status(
    summary: dict[str, Any], conclusion_id: str, use: dict[str, Any], root: Path,
    errors: list[str], *, dependent_summary: dict[str, Any] | None = None,
) -> tuple[str, dict[str, Any] | None]:
    support = selected_statement_support(summary, conclusion_id, use.get("statement_support_sha256"))
    prefix = f"dependency {use.get('use_id')}.statement_support"
    if support is None:
        errors.append(f"{prefix} selects stale, invalid, or missing checked support")
        return "unchecked", None
    rows = use.get("statement_support_conditions", [])
    if not isinstance(rows, list):
        errors.append(f"{prefix}_conditions must be an exact condition map")
        rows = []
    conditions = support["extra_conditions"]
    seen = []
    statuses = []
    for row in rows:
        if not isinstance(row, dict) or set(row) != {"condition", "status", "evidence", "evidence_spans"}:
            errors.append(f"{prefix} condition needs condition, status, evidence, and evidence_spans")
            continue
        seen.append(row.get("condition"))
        status = row.get("status")
        if not is_enum_value(status, {"satisfied", "not_satisfied", "partial", "unclear"}):
            errors.append(f"{prefix} condition status is invalid")
        statuses.append({"satisfied": "verified", "not_satisfied": "incorrect", "partial": "conditional", "unclear": "unclear"}.get(status, "unchecked"))
        if not is_substantive_string(row.get("evidence")):
            errors.append(f"{prefix} condition requires its mathematical discharge evidence")
        validate_locked_span_list(row.get("evidence_spans"), root, prefix + ".evidence_spans", errors, allow_empty=False)
        if dependent_summary is not None and isinstance(row.get("evidence_spans"), list):
            allowed = [
                {"file": dependent_summary.get("source_file"), "start_line": dependent_summary.get("source_start"), "end_line": dependent_summary.get("source_end")},
                *dependent_summary.get("obligation_statement_spans", []), *dependent_summary.get("obligation_context_spans", []),
            ]
            for span in row["evidence_spans"]:
                metadata = resolved_span_metadata(span, root)
                if metadata is None:
                    continue
                anchored = False
                for location in allowed:
                    if not isinstance(location, dict) or not is_nonempty_string(location.get("file")):
                        continue
                    base = root if location.get("file") == dependent_summary.get("source_file") else Path(dependent_summary.get("ledger", str(root))).parent
                    try:
                        file = resolve_stored_path(location["file"], base)
                    except ValueError:
                        continue
                    if (str(file.resolve()) == str(Path(metadata["file"]).resolve())
                            and is_int(location.get("start_line")) and is_int(location.get("end_line"))
                            and location["start_line"] <= metadata["start_line"] <= metadata["end_line"] <= location["end_line"]):
                        anchored = True
                if not anchored:
                    errors.append(f"{prefix} condition evidence must lie in the dependent unit's locked source or assumptions")
    if sorted(str(text) for text in seen) != sorted(conditions):
        errors.append(f"{prefix}_conditions must cover exactly its explicit extra conditions")
    if support.get("acceptance") != "accepted" and not support.get("provisional"):
        return "unchecked", support
    return combine_dependency_statuses(statuses or ["verified"]), support


def internal_dependency_status(
    summary: dict[str, Any], conclusion_id: str
) -> str:
    """Derive availability for one audited conclusion."""
    result = next(
        (
            row
            for row in summary.get("conclusion_results", [])
            if isinstance(row, dict)
            and row.get("conclusion_id") == conclusion_id
        ),
        None,
    )
    if not isinstance(result, dict):
        return "unchecked"
    statement_status = result.get("statement_status")
    if is_enum_value(statement_status, {"established", "conditional"}):
        supplied = result.get("statement_support")
        if isinstance(supplied, dict):
            if not supplied.get("valid") or (supplied.get("acceptance") != "accepted" and not supplied.get("provisional")):
                return "unchecked"
            if result.get("contract_fidelity") != "verified" or supplied.get("dependency_closure") != "verified":
                return "unchecked"
            return "conditional" if supplied.get("extra_conditions") else "verified"
        contract_value = result.get("contract_fidelity")
        argument_value = result.get("argument_status")
        closure_value = result.get("dependency_closure")
        component_statuses = [
            {
                "verified": "verified",
                "conditionally_verified": "conditional",
                "gap": "gap",
                "incorrect": "incorrect",
                "unclear": "unclear",
                "not_checked": "unchecked",
            }.get(contract_value, "unchecked")
            if isinstance(contract_value, str)
            else "unchecked",
            {
                "valid": "verified",
                "conditional": "conditional",
                "gap": "gap",
                "invalid": "gap",
                "unclear": "unclear",
                "not_checked": "unchecked",
            }.get(argument_value, "unchecked")
            if isinstance(argument_value, str)
            else "unchecked",
            {
                "verified": "verified",
                "conditionally_verified": "conditional",
                "gap": "gap",
                "incorrect": "incorrect",
                "unclear": "unclear",
                "not_checked": "unchecked",
            }.get(closure_value, "unchecked")
            if isinstance(closure_value, str)
            else "unchecked",
        ]
        if statement_status == "conditional":
            component_statuses.append("conditional")
        return combine_dependency_statuses(component_statuses)
    return ({
        "refuted": "incorrect",
        "not_established": "gap",
        "unclear": "unclear",
        "not_assessed": "unchecked",
    }.get(statement_status, "unchecked")
    if isinstance(statement_status, str)
    else "unchecked")


def validate_issue_id_list(
    value: Any,
    field: str,
    errors: list[str],
    *,
    allow_empty: bool = True,
) -> list[str]:
    issue_ids = validate_string_list(
        value,
        field,
        errors,
        allow_empty=allow_empty,
    )
    if len(issue_ids) != len(set(issue_ids)):
        errors.append(f"{field} contains duplicates")
    for issue_id in issue_ids:
        if not ISSUE_ID_RE.fullmatch(issue_id):
            errors.append(f"{field} contains invalid issue id {issue_id!r}")
    return issue_ids


def validate_compatibility_matrix(
    value: Any,
    field: str,
    errors: list[str],
) -> tuple[str, set[str]]:
    statuses = validate_aspect_matrix(
        value,
        field,
        NORMALIZATION_ASPECTS,
        COMPATIBILITY_STATUSES,
        True,
        errors,
    )
    issue_ids: set[str] = set()
    if isinstance(value, list):
        for index, row in enumerate(value, 1):
            if not isinstance(row, dict):
                continue
            prefix = f"{field}[{index}]"
            row_issues = validate_issue_id_list(
                row.get("issue_ids"),
                f"{prefix}.issue_ids",
                errors,
            )
            status = row.get("status")
            if is_enum_value(status, {"passed", "not_applicable"}) and row_issues:
                errors.append(f"{prefix}: a clean compatibility row cannot cite issues")
            if is_enum_value(status, {
                "conditional",
                "gap",
                "incorrect",
                "unclear",
                "unchecked",
            }) and not row_issues:
                errors.append(f"{prefix}: a non-clean compatibility row requires issue_ids")
            issue_ids.update(row_issues)
    nonclean = [
        status
        for status in statuses.values()
        if isinstance(status, str) and status not in {"passed", "not_applicable"}
    ]
    applicability = combine_dependency_statuses(nonclean) if nonclean else "passed"
    return applicability, issue_ids


def validate_locked_span_list(
    value: Any,
    base: Path,
    field: str,
    errors: list[str],
    *,
    allow_empty: bool = False,
) -> list[dict[str, Any]]:
    if not isinstance(value, list):
        errors.append(f"{field} must be a list")
        return []
    if not allow_empty and not value:
        errors.append(f"{field} must not be empty")
    for index, span in enumerate(value, 1):
        validate_locked_span(
            span,
            base,
            f"{field}[{index}]",
            errors,
            require_role=True,
        )
    return [span for span in value if isinstance(span, dict)]


def validate_method_interface_registry(
    registry: dict[str, Any],
    root: Path,
    errors: list[str],
    *,
    final: bool = True,
) -> dict[str, dict[str, Any]]:
    if registry.get("schema_version") != METHOD_INTERFACE_SCHEMA_VERSION:
        errors.append("Method-interface registry has an unsupported schema_version")

    scope = registry.get("scope")
    if not isinstance(scope, dict):
        errors.append("Method-interface registry scope must be an object")
        scope = {}
    if final and scope.get("status") != "reviewed":
        errors.append("Method-interface registry scope.status must be reviewed")
    trigger = scope.get("trigger")
    valid_triggers = {"required", "not_required"} if final else {
        "required",
        "not_required",
        "not_set",
    }
    if not is_enum_value(trigger, valid_triggers):
        errors.append(
            "Method-interface registry scope.trigger must be required or not_required"
        )
    if final and not is_nonempty_string(scope.get("reason")):
        errors.append("Method-interface registry scope.reason must be explicit")

    records = registry.get("interfaces")
    if not isinstance(records, list):
        errors.append("Method-interface registry must contain interfaces as a list")
        return {}
    if trigger == "required" and not records:
        errors.append("A required method-interface audit must contain an interface record")
    if trigger == "not_required" and records:
        errors.append("scope.trigger cannot be not_required when interfaces are recorded")

    result: dict[str, dict[str, Any]] = {}
    for index, record in enumerate(records, 1):
        prefix = f"Method interface {index}"
        if not isinstance(record, dict):
            errors.append(f"{prefix} must be an object")
            continue
        interface_id = record.get("id")
        if not isinstance(interface_id, str) or not INTERFACE_ID_RE.fullmatch(interface_id):
            errors.append(f"{prefix}.id must match MI-001")
            continue
        if interface_id in result:
            errors.append(f"Duplicate method interface id: {interface_id}")
        result[interface_id] = record
        prefix = interface_id

        if not is_enum_value(record.get("kind"), INTERFACE_KINDS):
            errors.append(f"{prefix}.kind is invalid")
        if not isinstance(record.get("load_bearing"), bool):
            errors.append(f"{prefix}.load_bearing must be true or false")
        if not isinstance(record.get("implementation_required_for_claim"), bool):
            errors.append(
                f"{prefix}.implementation_required_for_claim must be true or false"
            )
        if not isinstance(record.get("execution_provenance_required_for_claim"), bool):
            errors.append(
                f"{prefix}.execution_provenance_required_for_claim must be true or false"
            )
        validate_string_list(
            record.get("affected_results"), f"{prefix}.affected_results", errors
        )

        target = record.get("population_target")
        if not isinstance(target, dict):
            errors.append(f"{prefix}.population_target must be an object")
            target = {}
        for field in ("formula", "measure_and_support", "equality_notion"):
            if not is_nonempty_string(target.get(field)):
                errors.append(f"{prefix}.population_target.{field} must be explicit")
        if not is_nonempty_string(record.get("identification_identity")):
            errors.append(f"{prefix}.identification_identity must be explicit")

        sample_laws = record.get("fitting_sample_laws")
        sample_roles: list[str] = []
        if not isinstance(sample_laws, list) or not sample_laws:
            errors.append(f"{prefix}.fitting_sample_laws must be a nonempty list")
            sample_laws = []
        for law_index, law in enumerate(sample_laws, 1):
            law_prefix = f"{prefix}.fitting_sample_laws[{law_index}]"
            if not isinstance(law, dict):
                errors.append(f"{law_prefix} must be an object")
                continue
            role = law.get("role")
            if not is_nonempty_string(role):
                errors.append(f"{law_prefix}.role must be explicit")
            else:
                sample_roles.append(role)
            for field in ("law", "reference_law"):
                if not is_nonempty_string(law.get(field)):
                    errors.append(f"{law_prefix}.{field} must be explicit")
            validate_locked_span_list(
                law.get("evidence_spans"),
                root,
                f"{law_prefix}.evidence_spans",
                errors,
            )
        if len(sample_roles) != len(set(sample_roles)):
            errors.append(f"{prefix}.fitting_sample_laws has duplicate roles")
        if record.get("kind") == "density_ratio" and set(sample_roles) != {
            "numerator",
            "denominator",
        }:
            errors.append(
                f"{prefix}: density_ratio requires exactly numerator and denominator laws"
            )

        for field in ("marginal_relationships", "evaluation_sites", "downstream_uses"):
            validate_string_list(record.get(field), f"{prefix}.{field}", errors)

        specification = record.get("interface_specification_status")
        if not is_enum_value(specification, INTERFACE_SPECIFICATION_STATUSES):
            errors.append(f"{prefix}.interface_specification_status is invalid")
        derivation = record.get("derivation_status")
        if not is_enum_value(derivation, ARGUMENT_STATUSES):
            errors.append(f"{prefix}.derivation_status is invalid")

        target_relation = record.get("target_relation")
        if not isinstance(target_relation, dict):
            errors.append(f"{prefix}.target_relation must be an object")
            target_relation = {}
        target_verdict = target_relation.get("verdict")
        if not is_enum_value(target_verdict, TARGET_RELATION_VERDICTS):
            errors.append(f"{prefix}.target_relation.verdict is invalid")
        if not is_nonempty_string(target_relation.get("reason")):
            errors.append(f"{prefix}.target_relation.reason must be explicit")
        target_assumptions = validate_string_list(
            target_relation.get("assumptions"),
            f"{prefix}.target_relation.assumptions",
            errors,
            allow_empty=True,
        )
        target_spans = validate_locked_span_list(
            target_relation.get("evidence_spans"),
            root,
            f"{prefix}.target_relation.evidence_spans",
            errors,
        )
        if target_verdict == "conditional_match" and not target_assumptions:
            errors.append(f"{prefix}: conditional_match requires named assumptions")
        if is_enum_value(specification, {"ambiguous", "incomplete"}) and not is_enum_value(
            target_verdict, {"not_assessable", "not_checked"}
        ):
            errors.append(
                f"{prefix}: an ambiguous or incomplete specification cannot establish "
                f"target_relation {target_verdict!r}"
            )
        if target_verdict == "mismatch" and specification != "clear":
            errors.append(
                f"{prefix}: mismatch requires authoritative evidence fixing the estimator specification"
            )
        if target_verdict == "mismatch" and not any(
                is_enum_value(
                    span.get("role"),
                    {
                        "authoritative_definition",
                        "authoritative_algorithm",
                        "authoritative_configuration",
                    },
                )
            for span in target_spans
        ):
            errors.append(
                f"{prefix}: mismatch requires an authoritative source-locked span"
            )

        implementation = record.get("implementation_relation")
        if not isinstance(implementation, dict):
            errors.append(f"{prefix}.implementation_relation must be an object")
            implementation = {}
        inspection_status = implementation.get("inspection_status")
        if not is_enum_value(inspection_status, IMPLEMENTATION_INSPECTION_STATUSES):
            errors.append(
                f"{prefix}.implementation_relation.inspection_status is invalid"
            )
        inspection_mode = implementation.get("inspection_mode")
        if not is_enum_value(inspection_mode, IMPLEMENTATION_INSPECTION_MODES):
            errors.append(f"{prefix}.implementation_relation.inspection_mode is invalid")
        implementation_spans = validate_locked_span_list(
            implementation.get("evidence_spans"),
            root,
            f"{prefix}.implementation_relation.evidence_spans",
            errors,
            allow_empty=inspection_status != "inspected",
        )
        allowed_implementation_roles = {
            "implementation_snapshot",
            "algorithm_specification",
            "configuration",
        }
        if inspection_status == "inspected":
            if not is_nonempty_string(implementation.get("revision")):
                errors.append(
                    f"{prefix}: inspected implementation requires an exact revision"
                )
            if inspection_mode == "not_applicable":
                errors.append(
                    f"{prefix}: inspected implementation requires static, executed, or both"
                )
            if not implementation_spans:
                errors.append(
                    f"{prefix}: inspected implementation requires hash-locked evidence"
                )
            if any(
                not is_enum_value(span.get("role"), allowed_implementation_roles)
                for span in implementation_spans
            ):
                errors.append(
                    f"{prefix}: implementation evidence has an unsupported role"
                )
        elif inspection_mode != "not_applicable":
            errors.append(
                f"{prefix}: uninspected implementation must use inspection_mode not_applicable"
            )
        if not is_nonempty_string(implementation.get("reason")):
            errors.append(f"{prefix}.implementation_relation.reason must be explicit")

        comparisons = implementation.get("comparisons")
        comparison_by_target: dict[str, dict[str, Any]] = {}
        if not isinstance(comparisons, list):
            errors.append(f"{prefix}.implementation_relation.comparisons must be a list")
            comparisons = []
        for comparison_index, comparison in enumerate(comparisons, 1):
            comparison_prefix = (
                f"{prefix}.implementation_relation.comparisons[{comparison_index}]"
            )
            if not isinstance(comparison, dict):
                errors.append(f"{comparison_prefix} must be an object")
                continue
            target_name = comparison.get("to")
            verdict = comparison.get("verdict")
            if not is_enum_value(
                target_name, {"documented_estimator", "required_target"}
            ):
                errors.append(f"{comparison_prefix}.to is invalid")
                continue
            if target_name in comparison_by_target:
                errors.append(f"{prefix}: duplicate implementation comparison {target_name}")
            comparison_by_target[target_name] = comparison
            if not is_enum_value(verdict, IMPLEMENTATION_COMPARISON_VERDICTS):
                errors.append(f"{comparison_prefix}.verdict is invalid")
            if not is_nonempty_string(comparison.get("reason")):
                errors.append(f"{comparison_prefix}.reason must be explicit")
            comparison_spans = validate_locked_span_list(
                comparison.get("evidence_spans"),
                root,
                f"{comparison_prefix}.evidence_spans",
                errors,
                allow_empty=not is_enum_value(
                    verdict, {"consistent", "inconsistent"}
                ),
            )
            if is_enum_value(verdict, {"consistent", "inconsistent"}):
                if inspection_status != "inspected":
                    errors.append(
                        f"{comparison_prefix}: a definite comparison requires inspected evidence"
                    )
                if not comparison_spans:
                    errors.append(
                        f"{comparison_prefix}: a definite comparison requires locked evidence"
                    )
            if inspection_status != "inspected" and not is_enum_value(
                verdict, {"not_assessable", "not_checked", "not_applicable"}
            ):
                errors.append(
                    f"{comparison_prefix}: uninspected code cannot support a definite comparison"
                )
        if set(comparison_by_target) != {"documented_estimator", "required_target"}:
            errors.append(
                f"{prefix}: implementation comparisons must cover documented_estimator and required_target"
            )
        if inspection_status == "not_applicable" and any(
            comparison.get("verdict") != "not_applicable"
            for comparison in comparison_by_target.values()
        ):
            errors.append(
                f"{prefix}: not_applicable implementation inspection requires not_applicable comparisons"
            )

        provenance = implementation.get("execution_provenance")
        if not isinstance(provenance, dict):
            errors.append(
                f"{prefix}.implementation_relation.execution_provenance must be an object"
            )
            provenance = {}
        provenance_status = provenance.get("status")
        if not is_enum_value(provenance_status, EXECUTION_PROVENANCE_STATUSES):
            errors.append(
                f"{prefix}.implementation_relation.execution_provenance.status is invalid"
            )
        if not is_nonempty_string(provenance.get("reason")):
            errors.append(
                f"{prefix}.implementation_relation.execution_provenance.reason must be explicit"
            )
        provenance_spans = validate_locked_span_list(
            provenance.get("evidence_spans"),
            root,
            f"{prefix}.implementation_relation.execution_provenance.evidence_spans",
            errors,
            allow_empty=not is_enum_value(
                provenance_status, {"matched", "not_matched"}
            ),
        )
        if is_enum_value(provenance_status, {"matched", "not_matched"}):
            if inspection_status != "inspected":
                errors.append(
                    f"{prefix}: execution provenance requires an inspected implementation revision"
                )
            if not provenance_spans:
                errors.append(
                    f"{prefix}: execution provenance requires locked run-linkage evidence"
                )
            if any(
                not is_enum_value(
                    span.get("role"),
                    {"execution_provenance", "run_configuration"},
                )
                for span in provenance_spans
            ):
                errors.append(
                    f"{prefix}: execution provenance evidence has an unsupported role"
                )
        if inspection_status == "not_applicable" and provenance_status != "not_applicable":
            errors.append(
                f"{prefix}: not_applicable implementation inspection requires not_applicable provenance"
            )

        alternatives = record.get("alternative_interpretations")
        if not isinstance(alternatives, list):
            errors.append(f"{prefix}.alternative_interpretations must be a list")
            alternatives = []
        for alt_index, alternative in enumerate(alternatives, 1):
            alt_prefix = f"{prefix}.alternative_interpretations[{alt_index}]"
            if not isinstance(alternative, dict):
                errors.append(f"{alt_prefix} must be an object")
                continue
            for field in ("interpretation", "consequence"):
                if not is_nonempty_string(alternative.get(field)):
                    errors.append(f"{alt_prefix}.{field} must be explicit")
            validate_string_list(
                alternative.get("evidence"), f"{alt_prefix}.evidence", errors
            )
        if is_enum_value(specification, {"ambiguous", "incomplete"}) and len(alternatives) < 2:
            errors.append(
                f"{prefix}: ambiguous or incomplete interfaces require at least two interpretations"
            )

        resolution_needed = record.get("resolution_evidence_needed")
        unresolved_interface = (
            is_enum_value(
                specification, {"ambiguous", "incomplete", "not_checked"}
            )
            or is_enum_value(
                target_verdict,
                {"conditional_match", "not_assessable", "not_checked"},
            )
            or (
                record.get("implementation_required_for_claim") is True
                and (
                    is_enum_value(
                        inspection_status,
                        {"available_not_checked", "unavailable", "out_of_scope"},
                    )
                    or any(
                        comparison_by_target.get(target_name, {}).get("verdict")
                        != "consistent"
                        for target_name in {
                            "documented_estimator",
                            "required_target",
                        }
                    )
                )
            )
            or (
                record.get("execution_provenance_required_for_claim") is True
                and provenance_status != "matched"
            )
        )
        validate_string_list(
            resolution_needed,
            f"{prefix}.resolution_evidence_needed",
            errors,
            allow_empty=not unresolved_interface,
        )
        issue_ids = validate_string_list(
            record.get("issue_ids"), f"{prefix}.issue_ids", errors, allow_empty=True
        )
        for issue_id in issue_ids:
            if not ISSUE_ID_RE.fullmatch(issue_id):
                errors.append(f"{prefix}.issue_ids contains invalid issue id {issue_id!r}")
        finding_requires_issue = (
            specification != "clear"
            or target_verdict != "match"
            or any(
                comparison.get("verdict") == "inconsistent"
                for comparison in comparison_by_target.values()
            )
            or provenance_status == "not_matched"
            or (
                record.get("implementation_required_for_claim") is True
                and is_enum_value(
                    inspection_status,
                    {"available_not_checked", "unavailable", "out_of_scope"},
                )
            )
            or (
                record.get("execution_provenance_required_for_claim") is True
                and provenance_status != "matched"
            )
        )
        if finding_requires_issue and not issue_ids:
            errors.append(f"{prefix}: non-clean interface status requires a canonical issue")
    return result


EXTERNAL_CITATION_BINDING_KINDS = {
    "bibtex_entry",
    "bibitem",
    "rendered_reference",
}
BIBTEX_ENTRY_START_RE = re.compile(
    r"@(?P<entry_type>[A-Za-z]+)\s*(?P<open>[{(])\s*"
    r"(?P<key>[^,\s{}()]+)\s*,",
    re.IGNORECASE,
)
BIBTEX_DIRECTIVE_START_RE = re.compile(
    r"@(?P<entry_type>[A-Za-z]+)\s*(?P<open>[{(])",
    re.IGNORECASE,
)
BIBITEM_RE = re.compile(
    r"\\bibitem(?:\s*\[[^]]*\])?\s*\{(?P<key>[^}]+)\}"
)
BIBITEM_COMMAND_RE = re.compile(r"\\bibitem(?![A-Za-z@])")
BIBLIOGRAPHY_BEGIN_RE = re.compile(
    r"\\begin\s*\{thebibliography\}(?:\s*\{[^}]*\})?"
)
BIBLIOGRAPHY_END_RE = re.compile(r"\\end\s*\{thebibliography\}")


def external_result_core_contract(record: dict[str, Any]) -> dict[str, Any]:
    """Return the theorem-source contract, excluding bibliography bindings."""
    return {
        "source_identity": record.get("source_identity"),
        "version": record.get("version"),
        "theorem_location": record.get("theorem_location"),
        "exact_statement": record.get("exact_statement"),
        "source_evidence": record.get("source_evidence"),
    }


def external_result_identity_sha256(record: dict[str, Any]) -> str:
    """Bind bibliography evidence to one exact external theorem identity."""
    return canonical_sha256(
        {"id": record.get("id"), **external_result_core_contract(record)}
    )


def external_result_contract(record: dict[str, Any]) -> dict[str, Any]:
    """Return the immutable external-result identity used by every use edge."""
    contract = external_result_core_contract(record)
    bindings = record.get("citation_bindings")
    if isinstance(bindings, list) and bindings:
        contract["citation_bindings"] = bindings
    return contract


def _bibtex_entry_end(text: str, opening: int, opening_char: str) -> int | None:
    """Return the inclusive closing offset of one balanced BibTeX entry."""
    if opening_char == "{":
        depth = 1
        escaped = False
        for index in range(opening + 1, len(text)):
            if escaped:
                escaped = False
                continue
            if text[index] == "\\":
                escaped = True
                continue
            if text[index] == "{":
                depth += 1
            elif text[index] == "}":
                depth -= 1
                if depth == 0:
                    return index
        return None

    parenthesis_depth = 1
    brace_depth = 0
    quoted = False
    escaped = False
    for index in range(opening + 1, len(text)):
        character = text[index]
        if escaped:
            escaped = False
            continue
        if character == "\\":
            escaped = True
            continue
        if character == '"' and brace_depth == 0:
            quoted = not quoted
            continue
        if quoted:
            continue
        if character == "{":
            brace_depth += 1
        elif character == "}" and brace_depth:
            brace_depth -= 1
        elif brace_depth == 0 and character == "(":
            parenthesis_depth += 1
        elif brace_depth == 0 and character == ")":
            parenthesis_depth -= 1
            if parenthesis_depth == 0:
                return index
    return None


def bibtex_entry_spans(path: Path) -> list[dict[str, Any]]:
    """Index complete citation-bearing BibTeX entries by exact physical lines."""
    text = read_text(path)
    return _memoize_text(
        "bibtex_entry_spans", text, lambda: _bibtex_entry_spans_from_text(text)
    )


def _bibtex_entry_spans_from_text(text: str) -> list[dict[str, Any]]:
    masked = mask_latex_comments(text)
    entries: list[dict[str, Any]] = []
    cursor = 0
    while directive := BIBTEX_DIRECTIVE_START_RE.search(masked, cursor):
        end = _bibtex_entry_end(
            masked,
            directive.start("open"),
            directive.group("open"),
        )
        if end is None:
            start_line = text.count("\n", 0, directive.start()) + 1
            raise ValueError(
                f"unterminated BibTeX directive beginning at line {start_line}"
            )
        entry_type = directive.group("entry_type").lower()
        if entry_type not in {"comment", "preamble", "string"}:
            match = BIBTEX_ENTRY_START_RE.match(masked, directive.start())
            if (
                match is None
                or match.start("open") != directive.start("open")
            ):
                start_line = text.count("\n", 0, directive.start()) + 1
                raise ValueError(
                    f"malformed BibTeX entry header at line {start_line}"
                )
            entries.append(
                {
                    "key": match.group("key").strip(),
                    "start_line": text.count("\n", 0, match.start()) + 1,
                    "end_line": text.count("\n", 0, end) + 1,
                    "start_offset": match.start(),
                    "end_offset": end,
                }
            )
        cursor = end + 1
    return entries


def bibitem_entry_spans(path: Path) -> list[dict[str, Any]]:
    """Index complete \\bibitem entries in .bbl or inline bibliography text."""
    text = read_text(path)
    masked = mask_structural_tex(text)
    lines = text.splitlines()
    entries: list[dict[str, Any]] = []
    environments: list[tuple[int, int]] = []
    active_start: int | None = None
    environment_tokens = sorted(
        [
            *(
                ("begin", match)
                for match in BIBLIOGRAPHY_BEGIN_RE.finditer(masked)
            ),
            *(("end", match) for match in BIBLIOGRAPHY_END_RE.finditer(masked)),
        ],
        key=lambda item: item[1].start(),
    )
    for token_kind, token in environment_tokens:
        token_line = text.count("\n", 0, token.start()) + 1
        if token_kind == "begin":
            if active_start is not None:
                raise ValueError(
                    f"nested thebibliography environment beginning at line {token_line}"
                )
            active_start = token.end()
        elif active_start is None:
            raise ValueError(
                f"thebibliography end without a matching begin at line {token_line}"
            )
        else:
            environments.append((active_start, token.start()))
            active_start = None
    if active_start is not None:
        start_line = text.count("\n", 0, active_start) + 1
        raise ValueError(
            f"unterminated thebibliography environment beginning at line {start_line}"
        )

    for environment_start, environment_end in environments:
        matches = list(BIBITEM_RE.finditer(masked, environment_start, environment_end))
        matched_starts = {match.start() for match in matches}
        malformed = next(
            (
                command
                for command in BIBITEM_COMMAND_RE.finditer(
                    masked, environment_start, environment_end
                )
                if command.start() not in matched_starts
            ),
            None,
        )
        if malformed is not None:
            malformed_line = text.count("\n", 0, malformed.start()) + 1
            raise ValueError(f"malformed bibitem command at line {malformed_line}")
        for index, match in enumerate(matches):
            next_item = (
                matches[index + 1].start()
                if index + 1 < len(matches)
                else environment_end
            )
            start_line = text.count("\n", 0, match.start()) + 1
            end_line = text.count(
                "\n", 0, max(match.end() - 1, next_item - 1)
            ) + 1
            while end_line > start_line and not strip_latex_comment(
                lines[end_line - 1]
            ).strip():
                end_line -= 1
            entries.append(
                {
                    "key": match.group("key").strip(),
                    "start_line": start_line,
                    "end_line": end_line,
                }
            )
    return entries


def source_snapshot_bibliography_key_locations(
    root: Path,
    errors: list[str] | None = None,
) -> tuple[
    dict[str, list[dict[str, Any]]],
    dict[Path, str],
    str | None,
]:
    """Index citation keys across the authoritative manuscript source closure."""
    index_errors = errors if errors is not None else []
    _, manifest, manifest_errors = load_audit_manifest(root)
    if manifest_errors:
        index_errors.extend(
            f"Cannot index authoritative bibliography sources: {error}"
            for error in manifest_errors
        )
        return {}, {}, None
    snapshot = manifest.get("source_snapshot")
    rows = snapshot.get("files") if isinstance(snapshot, dict) else None
    if not isinstance(rows, list):
        index_errors.append(
            "Cannot index authoritative bibliography sources: "
            "manifest source_snapshot.files is missing"
        )
        return {}, {}, None

    locations: dict[str, list[dict[str, Any]]] = defaultdict(list)
    snapshot_files: dict[Path, str] = {}
    tex_suffixes = FLS_SOURCE_SUFFIXES | {".bbl"}
    for index, row in enumerate(rows, 1):
        file_value = row.get("file") if isinstance(row, dict) else None
        digest = row.get("sha256") if isinstance(row, dict) else None
        if not is_nonempty_string(file_value) or not is_nonempty_string(digest):
            index_errors.append(
                "Cannot index authoritative bibliography sources: "
                f"source_snapshot.files[{index}] needs file and sha256"
            )
            continue
        try:
            source_path = resolve_stored_path(file_value, root)
            resolved_source = source_path.resolve()
            suffix = source_path.suffix.lower()
            if resolved_source in snapshot_files:
                index_errors.append(
                    "Cannot index authoritative bibliography sources: duplicate "
                    f"snapshot path {relative_or_absolute(source_path, root)}"
                )
                continue
            snapshot_files[resolved_source] = digest
            if not source_path.is_file():
                if suffix == ".bib" or suffix in tex_suffixes:
                    index_errors.append(
                        "Cannot index authoritative bibliography source "
                        f"{relative_or_absolute(source_path, root)}: file does not exist"
                    )
                continue
            if suffix == ".bib":
                source_kind = "bibtex_entry"
                entries = bibtex_entry_spans(source_path)
            elif suffix in tex_suffixes:
                source_kind = "bibitem"
                entries = bibitem_entry_spans(source_path)
            else:
                continue
        except (OSError, UnicodeError, ValueError) as exc:
            index_errors.append(
                "Cannot index authoritative bibliography source "
                f"{file_value}: {exc}"
            )
            continue
        for entry in entries:
            key = entry.get("key")
            if not is_nonempty_string(key):
                continue
            locations[key].append(
                {
                    "file": resolved_source,
                    "source_kind": source_kind,
                    "start_line": entry["start_line"],
                    "end_line": entry["end_line"],
                }
            )
    snapshot_sha256 = (
        snapshot.get("sha256")
        if isinstance(snapshot, dict) and is_nonempty_string(snapshot.get("sha256"))
        else None
    )
    return dict(locations), snapshot_files, snapshot_sha256


def locked_json_span_object(
    span: Any,
    root: Path,
    prefix: str,
    errors: list[str],
) -> dict[str, Any] | None:
    """Load one already validated locked span as a JSON object."""
    if not isinstance(span, dict):
        return None
    file_value = span.get("file")
    start_line = span.get("start_line")
    end_line = span.get("end_line")
    if not (
        is_nonempty_string(file_value)
        and is_int(start_line)
        and is_int(end_line)
        and start_line >= 1
        and end_line >= start_line
    ):
        return None
    source_path = resolve_stored_path(file_value, root)
    if not source_path.is_file():
        return None
    try:
        lines = read_lines(source_path)
    except (OSError, UnicodeError, ValueError) as exc:
        errors.append(f"{prefix} cannot be read as UTF-8 JSON: {exc}")
        return None
    if end_line > len(lines):
        return None
    try:
        value = json.loads("\n".join(lines[start_line - 1 : end_line]))
    except (TypeError, ValueError) as exc:
        errors.append(f"{prefix} must contain exactly one JSON object: {exc}")
        return None
    if not isinstance(value, dict):
        errors.append(f"{prefix} must contain a JSON object")
        return None
    return value


def validate_external_citation_bindings(
    record: dict[str, Any],
    result_id: str,
    root: Path,
    errors: list[str],
    source_bibliography_index: dict[str, list[dict[str, Any]]] | None = None,
    source_snapshot_files: dict[Path, str] | None = None,
    source_snapshot_sha256: str | None = None,
) -> None:
    """Require each load-bearing citation key to resolve to one locked entry."""
    required_keys = sorted(
        {
            key
            for use in record.get("uses", [])
            if isinstance(use, dict) and isinstance(use.get("citation_keys"), list)
            for key in use["citation_keys"]
            if is_nonempty_string(key)
        }
    ) if isinstance(record.get("uses"), list) else []

    raw_bindings = record.get("citation_bindings")
    if raw_bindings is None and not required_keys:
        bindings: list[Any] = []
    elif not isinstance(raw_bindings, list):
        errors.append(f"{result_id}.citation_bindings must be a list")
        bindings = []
    else:
        bindings = raw_bindings

    expected_identity = external_result_identity_sha256(record)
    binding_keys: list[str] = []
    for index, binding in enumerate(bindings, 1):
        prefix = f"{result_id}.citation_bindings[{index}]"
        if not isinstance(binding, dict):
            errors.append(f"{prefix} must be an object")
            continue
        key = binding.get("key")
        authoritative_locations: list[dict[str, Any]] = []
        if not is_nonempty_string(key):
            errors.append(f"{prefix}.key must be a nonempty string")
        else:
            binding_keys.append(key)
            authoritative_locations = (
                source_bibliography_index.get(key, [])
                if source_bibliography_index is not None
                else []
            )
            if len(authoritative_locations) > 1:
                rendered_locations = ", ".join(
                    f"{relative_or_absolute(location['file'], root)}:"
                    f"{location['start_line']}-{location['end_line']}"
                    for location in authoritative_locations
                )
                errors.append(
                    f"{prefix}: bibliography key {key!r} is ambiguous across "
                    "the authoritative source snapshot: " + rendered_locations
                )
        source_kind = binding.get("source_kind")
        if not is_enum_value(source_kind, EXTERNAL_CITATION_BINDING_KINDS):
            errors.append(f"{prefix}.source_kind is invalid")
        if binding.get("external_result_id") != result_id:
            errors.append(f"{prefix}.external_result_id must equal {result_id}")
        if binding.get("external_identity_sha256") != expected_identity:
            errors.append(
                f"{prefix}.external_identity_sha256 is stale or belongs to another result"
            )
        if binding.get("role") != "bibliography_identity":
            errors.append(f"{prefix}.role must be bibliography_identity")
        if not is_substantive_string(binding.get("locator")):
            errors.append(f"{prefix}.locator must be nonempty and substantive")
        validate_locked_span(binding, root, prefix, errors, require_role=True)

        if source_bibliography_index is not None and is_nonempty_string(key):
            if source_kind == "rendered_reference":
                if authoritative_locations:
                    errors.append(
                        f"{prefix}: bibliography key {key!r} has an "
                        "authoritative machine-readable entry in the source "
                        "snapshot; bind that entry instead of a rendered "
                        "transcription"
                    )
            elif not authoritative_locations:
                errors.append(
                    f"{prefix}: bibliography key {key!r} does not resolve to "
                    "any authoritative entry in the source snapshot; a binding "
                    "must lock the snapshot's own bibliography source"
                )
        file_value = binding.get("file")
        start_line = binding.get("start_line")
        end_line = binding.get("end_line")
        if not (
            is_nonempty_string(file_value)
            and is_int(start_line)
            and is_int(end_line)
        ):
            continue
        source_path = resolve_stored_path(file_value, root)
        if (
            source_bibliography_index is not None
            and len(authoritative_locations) == 1
            and source_kind != "rendered_reference"
        ):
            authoritative = authoritative_locations[0]
            if (
                source_path.resolve() != authoritative["file"]
                or source_kind != authoritative["source_kind"]
                or (start_line, end_line)
                != (authoritative["start_line"], authoritative["end_line"])
            ):
                errors.append(
                    f"{prefix}: binding for key {key!r} must equal the unique "
                    "authoritative snapshot entry at "
                    f"{relative_or_absolute(authoritative['file'], root)}:"
                    f"{authoritative['start_line']}-{authoritative['end_line']} "
                    f"({authoritative['source_kind']})"
                )
        if not source_path.is_file():
            continue
        if source_kind == "rendered_reference":
            provenance = binding.get("rendered_provenance")
            if not isinstance(provenance, dict):
                errors.append(
                    f"{prefix}.rendered_provenance must be an object for a "
                    "rendered_reference binding"
                )
                continue
            if provenance.get("authority") != "source_snapshot":
                errors.append(
                    f"{prefix}.rendered_provenance.authority must be source_snapshot"
                )
            if (
                not is_nonempty_string(source_snapshot_sha256)
                or provenance.get("source_snapshot_sha256")
                != source_snapshot_sha256
            ):
                errors.append(
                    f"{prefix}.rendered_provenance.source_snapshot_sha256 is stale"
                )
            resolved_source = source_path.resolve()
            snapshot_digest = (
                source_snapshot_files.get(resolved_source)
                if source_snapshot_files is not None
                else None
            )
            if snapshot_digest is None:
                errors.append(
                    f"{prefix}: rendered_reference file must be an authoritative "
                    "source snapshot member"
                )
            elif provenance.get("source_file_sha256") != snapshot_digest:
                errors.append(
                    f"{prefix}.rendered_provenance.source_file_sha256 must equal "
                    "the snapshot file hash"
                )
            elif sha256_file(source_path) != snapshot_digest:
                errors.append(
                    f"{prefix}: rendered_reference snapshot file has drifted"
                )

            mapping_prefix = f"{prefix}.rendered_provenance.key_mapping"
            mapping_span = provenance.get("key_mapping")
            validate_locked_span(
                mapping_span,
                root,
                mapping_prefix,
                errors,
                require_role=True,
            )
            if (
                isinstance(mapping_span, dict)
                and mapping_span.get("role") != "rendered_reference_key_mapping"
            ):
                errors.append(
                    f"{mapping_prefix}.role must be rendered_reference_key_mapping"
                )
            mapping_file = (
                mapping_span.get("file") if isinstance(mapping_span, dict) else None
            )
            if is_nonempty_string(mapping_file):
                mapping_path = resolve_stored_path(mapping_file, root)
                mapping_snapshot_digest = (
                    source_snapshot_files.get(mapping_path.resolve())
                    if source_snapshot_files is not None
                    else None
                )
                if mapping_snapshot_digest is None:
                    errors.append(
                        f"{mapping_prefix}.file must be an authoritative source "
                        "snapshot member"
                    )
                elif (
                    mapping_path.is_file()
                    and sha256_file(mapping_path) != mapping_snapshot_digest
                ):
                    errors.append(f"{mapping_prefix}.file has drifted from the snapshot")

            mapping = locked_json_span_object(
                mapping_span, root, mapping_prefix, errors
            )
            if mapping is not None:
                if set(mapping) != {
                    "schema_version",
                    "citation_key",
                    "rendered_reference",
                }:
                    errors.append(
                        f"{mapping_prefix} JSON must contain exactly schema_version, "
                        "citation_key, and rendered_reference"
                    )
                if mapping.get("schema_version") != 1:
                    errors.append(f"{mapping_prefix}.schema_version must equal 1")
                if mapping.get("citation_key") != key:
                    errors.append(
                        f"{mapping_prefix}.citation_key must equal {key!r}"
                    )
                rendered_target = mapping.get("rendered_reference")
                if not isinstance(rendered_target, dict) or set(rendered_target) != {
                    "file",
                    "start_line",
                    "end_line",
                    "sha256",
                }:
                    errors.append(
                        f"{mapping_prefix}.rendered_reference must exactly identify "
                        "one locked span"
                    )
                else:
                    target_file = rendered_target.get("file")
                    target_matches = (
                        is_nonempty_string(target_file)
                        and resolve_stored_path(target_file, root).resolve()
                        == source_path.resolve()
                        and rendered_target.get("start_line") == start_line
                        and rendered_target.get("end_line") == end_line
                        and rendered_target.get("sha256") == binding.get("sha256")
                    )
                    if not target_matches:
                        errors.append(
                            f"{mapping_prefix}: citation key {key!r} does not map "
                            "to this rendered_reference span"
                        )
            continue
        if "rendered_provenance" in binding:
            errors.append(
                f"{prefix}.rendered_provenance is allowed only for rendered_reference"
            )
        try:
            candidates = (
                bibtex_entry_spans(source_path)
                if source_kind == "bibtex_entry"
                else bibitem_entry_spans(source_path)
            )
        except (OSError, UnicodeError, ValueError) as exc:
            errors.append(f"{prefix} cannot parse bibliography source: {exc}")
            continue
        same_key = [candidate for candidate in candidates if candidate["key"] == key]
        if len(same_key) != 1:
            errors.append(
                f"{prefix}: bibliography key {key!r} must resolve exactly once; "
                f"found {len(same_key)}"
            )
            continue
        candidate = same_key[0]
        if (candidate["start_line"], candidate["end_line"]) != (
            start_line,
            end_line,
        ):
            errors.append(
                f"{prefix}: locked span must equal the complete {source_kind} entry"
            )

    if len(binding_keys) != len(set(binding_keys)):
        errors.append(f"{result_id}.citation_bindings contains duplicate keys")
    if binding_keys != sorted(binding_keys):
        errors.append(f"{result_id}.citation_bindings must be sorted by key")
    if sorted(set(binding_keys)) != required_keys:
        errors.append(
            f"{result_id}.citation_bindings must exactly bind load-bearing citation "
            f"keys; expected {required_keys}, found {sorted(set(binding_keys))}"
        )

    review = record.get("citation_binding_review")
    if required_keys:
        if not isinstance(review, dict):
            errors.append(f"{result_id}.citation_binding_review must be an object")
        else:
            if review.get("status") != "reviewed":
                errors.append(
                    f"{result_id}.citation_binding_review.status must be reviewed"
                )
            if review.get("required_keys") != required_keys:
                errors.append(
                    f"{result_id}.citation_binding_review.required_keys is stale"
                )
            if not is_substantive_string(review.get("evidence")):
                errors.append(
                    f"{result_id}.citation_binding_review.evidence must be substantive"
                )
    elif review is not None:
        if not isinstance(review, dict):
            errors.append(f"{result_id}.citation_binding_review must be an object")
        else:
            if review.get("status") != "not_required":
                errors.append(
                    f"{result_id}.citation_binding_review.status must be not_required"
                )
            if review.get("required_keys") != []:
                errors.append(
                    f"{result_id}.citation_binding_review.required_keys must be empty"
                )
            if not is_substantive_string(review.get("evidence")):
                errors.append(
                    f"{result_id}.citation_binding_review.evidence must be substantive"
                )


def validate_external_source_evidence(
    value: Any,
    root: Path,
    field: str,
    errors: list[str],
) -> list[dict[str, Any]]:
    if not isinstance(value, list):
        errors.append(f"{field} must be a list")
        return []
    validated: list[dict[str, Any]] = []
    for index, row in enumerate(value, 1):
        prefix = f"{field}[{index}]"
        if not isinstance(row, dict):
            errors.append(f"{prefix} must be an object")
            continue
        validated.append(row)
        for name in ("file", "sha256", "locator", "role"):
            if not is_substantive_string(row.get(name)):
                errors.append(f"{prefix}.{name} must be nonempty and substantive")
        file_value = row.get("file")
        digest = row.get("sha256")
        if is_nonempty_string(file_value):
            source_path = resolve_stored_path(file_value, root)
            if not source_path.is_file():
                errors.append(f"{prefix}.file does not exist: {source_path}")
            elif not is_nonempty_string(digest) or sha256_file(source_path) != digest:
                errors.append(f"{prefix}: source drift; whole-file SHA-256 does not match")
    return validated


def validate_external_result_catalog(
    registry: dict[str, Any],
    root: Path,
    errors: list[str],
) -> tuple[dict[str, dict[str, Any]], dict[str, str]]:
    records = registry.get("external_results")
    if not isinstance(records, list):
        errors.append("Dependency registry must contain external_results as a list")
        return {}, {}
    results: dict[str, dict[str, Any]] = {}
    contract_hashes: dict[str, str] = {}
    if records:
        (
            source_bibliography_index,
            source_snapshot_files,
            source_snapshot_sha256,
        ) = source_snapshot_bibliography_key_locations(root, errors)
    else:
        source_bibliography_index = {}
        source_snapshot_files = {}
        source_snapshot_sha256 = None
    for index, record in enumerate(records, 1):
        prefix = f"external_results[{index}]"
        if not isinstance(record, dict):
            errors.append(f"{prefix} must be an object")
            continue
        result_id = record.get("id")
        status = record.get("status")
        if not is_nonempty_string(result_id):
            errors.append(f"{prefix}.id must be a nonempty string")
            continue
        if result_id in results:
            errors.append(f"Duplicate external result id: {result_id}")
        results[result_id] = record
        if not is_enum_value(status, DEPENDENCY_STATUSES - {"not_applicable"}):
            errors.append(f"{result_id}: invalid external result status {status!r}")
        for field in (
            "source_identity",
            "version",
            "theorem_location",
            "exact_statement",
        ):
            if not is_substantive_string(record.get(field)):
                errors.append(f"{result_id}.{field} must be nonempty and substantive")
        source_evidence = validate_external_source_evidence(
            record.get("source_evidence"),
            root,
            f"{result_id}.source_evidence",
            errors,
        )
        if status != "unchecked" and not source_evidence:
            errors.append(f"{result_id}.source_evidence must not be empty")
        validate_external_citation_bindings(
            record,
            result_id,
            root,
            errors,
            source_bibliography_index,
            source_snapshot_files,
            source_snapshot_sha256,
        )
        contract_hashes[result_id] = canonical_sha256(external_result_contract(record))
        if status == "unchecked" and not is_substantive_string(record.get("reason")):
            errors.append(f"{result_id}: unchecked external result needs a substantive reason")
        validate_issue_id_list(
            record.get("issue_ids"),
            f"{result_id}.issue_ids",
            errors,
        )
    return results, contract_hashes


def validate_dependency_registry_review(
    registry: dict[str, Any],
    *,
    source_snapshot_sha256: Any,
    inventory_sha256: str,
    in_scope: list[str],
    errors: list[str],
) -> None:
    if registry.get("schema_version") != SCHEMA_VERSION:
        errors.append("Dependency registry has an unsupported schema_version")
    if registry.get("closure_contract_version") != CLOSURE_CONTRACT_VERSION:
        errors.append(
            "Dependency registry closure_contract_version does not match the validator"
        )
    review = registry.get("review")
    if not isinstance(review, dict):
        errors.append("Dependency registry review must be an object")
        return
    if review.get("status") != "reviewed":
        errors.append("Dependency registry review.status must be reviewed")
    if review.get("source_snapshot_sha256") != source_snapshot_sha256:
        errors.append(
            "Dependency registry review.source_snapshot_sha256 is stale or incorrect"
        )
    if review.get("inventory_sha256") != inventory_sha256:
        errors.append("Dependency registry review.inventory_sha256 is stale or incorrect")
    if review.get("in_scope_units") != in_scope:
        errors.append(
            "Dependency registry review.in_scope_units must equal audit scope exactly"
        )
    validate_string_list(
        review.get("evidence"),
        "Dependency registry review.evidence",
        errors,
        substantive=True,
    )


def expected_result_uses(
    summaries_by_id: dict[str, dict[str, Any]],
    errors: list[str],
) -> dict[tuple[str, str], dict[str, Any]]:
    """Aggregate ledger invocations by stable dependency-use ID."""
    expected: dict[tuple[str, str], dict[str, Any]] = {}
    for dependent_unit, summary in summaries_by_id.items():
        direct_by_id = {
            row.get("use_id"): row
            for row in summary.get("direct_dependencies", [])
            if isinstance(row, dict) and is_nonempty_string(row.get("use_id"))
        }
        for claim in summary.get("result_dependency_claims", []):
            if (
                not isinstance(claim, dict)
                or not is_nonempty_string(claim.get("id"))
                or not is_nonempty_string(claim.get("use_id"))
            ):
                continue
            dependency_id = claim["id"]
            use_id = claim["use_id"]
            key = (dependent_unit, use_id)
            direct = direct_by_id.get(use_id)
            if direct is None:
                continue
            current = expected.setdefault(
                key,
                {
                    "dependent_unit": dependent_unit,
                    "use_id": use_id,
                    "dependency_id": dependency_id,
                    "kind": direct.get("kind"),
                    "dependency_conclusion_id": direct.get("conclusion_id"),
                    "status": direct.get("status"),
                    "needed_form": direct.get("needed_form"),
                    "compatibility_check": direct.get("compatibility_check"),
                    "statement_support_sha256": direct.get("statement_support_sha256"),
                    "step_ids": set(),
                },
            )
            for field in (
                "id",
                "use_id",
                "kind",
                "conclusion_id",
                "status",
                "needed_form",
                "compatibility_check",
                "statement_support_sha256",
            ):
                expected_field = {
                    "id": "dependency_id",
                    "conclusion_id": "dependency_conclusion_id",
                }.get(field, field)
                if current.get(expected_field) != direct.get(field):
                    errors.append(
                        f"{dependent_unit}: ledger dependency use {use_id} has "
                        f"inconsistent {field} values"
                    )
            step_id = claim.get("owner_step")
            if is_nonempty_string(step_id):
                current["step_ids"].add(step_id)
    for record in expected.values():
        record["step_ids"] = sorted(record["step_ids"])
    return expected


def validate_dependency_use_identity(
    use: Any,
    prefix: str,
    expected: dict[str, Any] | None,
    errors: list[str],
    *,
    allow_preliminary_step_ids: bool = False,
) -> dict[str, Any]:
    if not isinstance(use, dict):
        errors.append(f"{prefix} must be an object")
        return {}
    for field in ("dependent_unit", "use_id", "dependency_id"):
        if not is_nonempty_string(use.get(field)):
            errors.append(f"{prefix}.{field} must be a nonempty string")
    if (
        is_nonempty_string(use.get("use_id"))
        and not DEPENDENCY_USE_ID_RE.fullmatch(use["use_id"])
    ):
        errors.append(f"{prefix}.use_id must match D001")
    step_ids = validate_string_list(
        use.get("step_ids"),
        f"{prefix}.step_ids",
        errors,
        allow_empty=(
            allow_preliminary_step_ids and use.get("status") == "unchecked"
        ),
    )
    if len(step_ids) != len(set(step_ids)):
        errors.append(f"{prefix}.step_ids contains duplicates")
    if not all(STEP_ID_RE.fullmatch(step_id) for step_id in step_ids):
        errors.append(f"{prefix}.step_ids contains an invalid ledger step ID")
    for field in ("needed_form", "dependency_conclusion", "compatibility_check"):
        if not is_substantive_string(use.get(field)):
            errors.append(f"{prefix}.{field} must be nonempty and substantive")
    if not is_nonempty_string(use.get("dependency_contract_sha256")):
        errors.append(f"{prefix}.dependency_contract_sha256 must be nonempty")
    if not is_enum_value(use.get("status"), DEPENDENCY_STATUSES - {"not_applicable"}):
        errors.append(f"{prefix}.status is invalid")
    if expected is not None:
        for field in (
            "dependent_unit",
            "use_id",
            "dependency_id",
            "dependency_conclusion_id",
            "step_ids",
            "needed_form",
            "compatibility_check",
            "statement_support_sha256",
        ):
            if use.get(field) != expected.get(field):
                errors.append(f"{prefix}.{field} disagrees with the invoking ledger")
    return use


def validate_prerequisite_map(
    value: Any,
    root: Path,
    field: str,
    errors: list[str],
) -> tuple[str, set[str]]:
    if not isinstance(value, list):
        errors.append(f"{field} must be a list")
        return "unchecked", set()
    if not value:
        errors.append(f"{field} must not be empty")
        return "unchecked", set()
    mapped_statuses: list[str] = []
    issue_ids: set[str] = set()
    for index, row in enumerate(value, 1):
        prefix = f"{field}[{index}]"
        if not isinstance(row, dict):
            errors.append(f"{prefix} must be an object")
            continue
        for name in ("prerequisite", "manuscript_evidence"):
            if not is_substantive_string(row.get(name)):
                errors.append(f"{prefix}.{name} must be nonempty and substantive")
        status = row.get("status")
        if not is_enum_value(
            status, {"satisfied", "not_satisfied", "partial", "unclear"}
        ):
            errors.append(f"{prefix}.status is invalid")
        else:
            mapped_statuses.append(
                {
                    "satisfied": "passed",
                    "not_satisfied": "gap",
                    "partial": "conditional",
                    "unclear": "unclear",
                }[status]
            )
        row_issues = validate_issue_id_list(
            row.get("issue_ids"),
            f"{prefix}.issue_ids",
            errors,
        )
        if status == "satisfied" and row_issues:
            errors.append(f"{prefix}: a satisfied prerequisite cannot cite issues")
        if is_enum_value(
            status, {"not_satisfied", "partial", "unclear"}
        ) and not row_issues:
            errors.append(f"{prefix}: a non-clean prerequisite requires issue_ids")
        issue_ids.update(row_issues)
        validate_locked_span_list(
            row.get("evidence_spans"),
            root,
            f"{prefix}.evidence_spans",
            errors,
            allow_empty=status != "satisfied",
        )
    nonclean = [status for status in mapped_statuses if status != "passed"]
    applicability = combine_dependency_statuses(nonclean) if nonclean else "passed"
    return applicability, issue_ids


def external_prerequisite_source_errors(
    root: Path, result: dict[str, Any], use: dict[str, Any], prefix: str
) -> list[str]:
    """Bind textual hypothesis mappings to the inspected external source.

    PDF evidence stays available through its existing file hash and locator;
    this check cannot establish that a human transcription is complete.
    """
    errors: list[str] = []
    sources: dict[Path, dict[str, Any]] = {}
    for evidence in result.get("source_evidence", []):
        if isinstance(evidence, dict) and is_nonempty_string(evidence.get("file")):
            try:
                path = resolve_stored_path(evidence["file"], root)
                if path.is_file() and evidence.get("sha256") == sha256_file(path):
                    sources[path] = evidence
            except (OSError, ValueError):
                pass
    textual_sources = {path for path in sources if path.suffix.lower() in {".txt", ".tex", ".md"}}
    rows = use.get("prerequisite_map") or []
    for index, row in enumerate(rows, 1):
        if not isinstance(row, dict):
            continue
        spans = row.get("source_evidence_spans", [])
        field = f"{prefix}.prerequisite_map[{index}].source_evidence_spans"
        if not isinstance(spans, list):
            errors.append(f"{field} must be a list")
            continue
        anchored_text = False
        for span in spans:
            validate_locked_span(span, root, field, errors)
            if not isinstance(span, dict) or not is_nonempty_string(span.get("file")):
                continue
            try:
                path = resolve_stored_path(span["file"], root)
            except ValueError:
                continue
            if path not in sources:
                errors.append(f"{field} must reference the hash-locked external theorem source, not manuscript or metadata")
            if path in textual_sources:
                anchored_text = True
        if textual_sources and row.get("status") == "satisfied" and not anchored_text:
            errors.append(
                f"{field} must anchor the actual external hypothesis in the registered "
                "text theorem evidence before claiming satisfied; add its locked text "
                "span even when PDF evidence is also registered"
            )
    return errors


def validate_dependency_closure(
    registry: dict[str, Any],
    root: Path,
    summaries_by_id: dict[str, dict[str, Any]],
    *,
    source_snapshot_sha256: Any,
    inventory_sha256: str,
    in_scope: list[str],
    errors: list[str],
) -> dict[str, Any]:
    """Validate every ledger dependency against one current reviewed use row."""
    validate_dependency_registry_review(
        registry,
        source_snapshot_sha256=source_snapshot_sha256,
        inventory_sha256=inventory_sha256,
        in_scope=in_scope,
        errors=errors,
    )
    expected = expected_result_uses(summaries_by_id, errors)
    external_results, external_hashes = validate_external_result_catalog(
        registry, root, errors
    )
    _, challenge_manifest, challenge_manifest_errors = load_audit_manifest(root)
    require_hypothesis_sources = not challenge_manifest_errors and challenge_contract_version(challenge_manifest) >= 3
    collision = set(external_results) & set(summaries_by_id)
    if collision:
        errors.append(
            "Dependency IDs cannot be both internal and external: "
            + ", ".join(sorted(collision))
        )

    edges: list[dict[str, Any]] = []
    closure_issue_ids: set[str] = set()
    seen_internal: set[tuple[str, str]] = set()
    globally_seen_use_ids: dict[str, str] = {}
    internal_rows = registry.get("internal_uses")
    if not isinstance(internal_rows, list):
        errors.append("Dependency registry internal_uses must be a list")
        internal_rows = []
    for index, raw_use in enumerate(internal_rows, 1):
        prefix = f"internal_uses[{index}]"
        use = raw_use if isinstance(raw_use, dict) else {}
        key = (use.get("dependent_unit"), use.get("use_id"))
        valid_key = all(is_nonempty_string(item) for item in key)
        if valid_key and key in seen_internal:
            errors.append(
                f"Duplicate internal use for {key[0]} / {key[1]}"
            )
        if valid_key:
            seen_internal.add(key)
            use_id = str(key[1])
            owner = str(key[0])
            if use_id in globally_seen_use_ids:
                errors.append(
                    f"Dependency use ID {use_id} is not audit-globally unique: "
                    f"{globally_seen_use_ids[use_id]} and {owner}"
                )
            else:
                globally_seen_use_ids[use_id] = owner
        expected_use = expected.get(key) if valid_key else None
        if expected_use is None or expected_use.get("kind") != "internal_result":
            errors.append(f"{prefix}: stale or unused internal use")
            expected_use = None
        use = validate_dependency_use_identity(use, prefix, expected_use, errors)
        dependency_id = use.get("dependency_id")
        target = summaries_by_id.get(dependency_id)
        dependency_conclusion_id = use.get("dependency_conclusion_id")
        if (
            not isinstance(dependency_conclusion_id, str)
            or not CONCLUSION_ID_RE.fullmatch(dependency_conclusion_id)
        ):
            errors.append(
                f"{prefix}.dependency_conclusion_id must identify one conclusion"
            )
        source_status = (
            internal_dependency_status(target, str(dependency_conclusion_id))
            if target
            else "unchecked"
        )
        selected_support = None
        if "statement_support_sha256" in use and target is not None:
            source_status, selected_support = statement_support_use_status(
                target, str(dependency_conclusion_id), use, root, errors,
                dependent_summary=summaries_by_id.get(str(use.get("dependent_unit"))),
            )
        elif "statement_support_conditions" in use:
            errors.append(f"{prefix}.statement_support_conditions requires exact supplemental support selection")
        if target is None and is_nonempty_string(dependency_id):
            errors.append(f"{prefix}: unknown internal dependency {dependency_id}")
        target_conclusion = next(
            (
                row
                for row in target.get("obligation_conclusions", [])
                if isinstance(row, dict)
                and row.get("id") == dependency_conclusion_id
            ),
            None,
        ) if target else None
        if target is not None and target_conclusion is None:
            errors.append(
                f"{prefix}: unknown dependency conclusion "
                f"{dependency_conclusion_id}"
            )
        expected_conclusion = (
            target_conclusion.get("claim")
            if isinstance(target_conclusion, dict)
            else None
        )
        expected_hash = (
            target_conclusion.get("contract_sha256")
            if isinstance(target_conclusion, dict)
            else None
        )
        if use.get("dependency_conclusion") != expected_conclusion:
            errors.append(f"{prefix}.dependency_conclusion is stale or incorrect")
        if use.get("dependency_contract_sha256") != expected_hash:
            errors.append(f"{prefix}.dependency_contract_sha256 is stale or incorrect")
        applicability, matrix_issues = validate_compatibility_matrix(
            use.get("compatibility_checks"),
            f"{prefix}.compatibility_checks",
            errors,
        )
        source_issues = (
            set(
                next(
                    (
                        row.get("issue_ids", [])
                        for row in target.get("conclusion_results", [])
                        if isinstance(row, dict)
                        and row.get("conclusion_id")
                        == dependency_conclusion_id
                    ),
                    [],
                )
            )
            if target is not None and source_status != "verified"
            else set()
        )
        expected_issues = source_issues | matrix_issues
        use_issues = validate_issue_id_list(
            use.get("issue_ids"), f"{prefix}.issue_ids", errors
        )
        if use_issues != sorted(expected_issues):
            errors.append(f"{prefix}.issue_ids do not match source and compatibility findings")
        effective = combine_dependency_statuses((source_status, applicability))
        if use.get("status") != effective:
            errors.append(
                f"{prefix}.status disagrees with source and compatibility status; expected {effective}"
            )
        if expected_use is not None and expected_use.get("status") != effective:
            errors.append(
                f"{prefix}: ledger dependency status disagrees with effective status {effective}"
            )
        if effective != "verified" and not use_issues:
            errors.append(f"{prefix}: a nonverified internal use requires canonical issues")
        closure_issue_ids.update(use_issues)
        if valid_key:
            edges.append(
                {
                    "dependent_unit": key[0],
                    "use_id": key[1],
                    "dependency_id": dependency_id,
                    "dependency_conclusion_id": dependency_conclusion_id,
                    "kind": "internal_result",
                    "source_status": source_status,
                    "applicability_status": applicability,
                    "effective_status": effective,
                    "step_ids": use.get("step_ids", []),
                    "issue_ids": use_issues,
                    "compatibility_checks": use.get(
                        "compatibility_checks", []
                    ),
                    "prerequisite_map": [],
                    "source_evidence": [],
                }
            )
            if selected_support is not None:
                edges[-1]["statement_support"] = selected_support
                edges[-1]["statement_support_conditions"] = use.get("statement_support_conditions", [])

    expected_internal = {
        key for key, value in expected.items() if value.get("kind") == "internal_result"
    }
    for dependent, use_id in sorted(expected_internal):
        dependency = expected[(dependent, use_id)].get("dependency_id")
        if dependency not in summaries_by_id:
            errors.append(
                f"{dependent}: unknown internal dependency {dependency}"
            )
    missing_internal = expected_internal - seen_internal
    if missing_internal:
        errors.append(
            "Dependency registry is missing internal use rows: "
            + ", ".join(f"{unit}/{use_id}" for unit, use_id in sorted(missing_internal))
        )

    seen_external: set[tuple[str, str]] = set()
    for result_id, record in external_results.items():
        uses = record.get("uses")
        if not isinstance(uses, list):
            errors.append(f"{result_id}.uses must be a list")
            uses = []
        record_issues = validate_issue_id_list(
            record.get("issue_ids"), f"{result_id}.issue_ids", errors
        )
        source_status = record.get("status")
        if source_status != "verified" and not record_issues:
            errors.append(f"{result_id}: a nonverified external result requires issue_ids")
        expected_for_result = {
            key
            for key, value in expected.items()
            if value.get("kind") == "external_result"
            and value.get("dependency_id") == result_id
        }
        if not expected_for_result:
            errors.append(f"{result_id}: unused or stale external result record")
        for index, raw_use in enumerate(uses, 1):
            prefix = f"{result_id}.uses[{index}]"
            use = raw_use if isinstance(raw_use, dict) else {}
            key = (use.get("dependent_unit"), use.get("use_id"))
            valid_key = all(is_nonempty_string(item) for item in key)
            if use.get("dependency_id") != result_id:
                errors.append(f"{prefix}.dependency_id must equal parent external result ID")
            if valid_key and key in seen_external:
                errors.append(f"Duplicate external use for {key[0]} / {key[1]}")
            if valid_key:
                seen_external.add(key)
                use_id = str(key[1])
                owner = str(key[0])
                if use_id in globally_seen_use_ids:
                    errors.append(
                        f"Dependency use ID {use_id} is not audit-globally "
                        f"unique: {globally_seen_use_ids[use_id]} and {owner}"
                    )
                else:
                    globally_seen_use_ids[use_id] = owner
            expected_use = expected.get(key) if valid_key else None
            if expected_use is None or expected_use.get("kind") != "external_result":
                errors.append(f"{prefix}: stale or unused external use")
                expected_use = None
            use = validate_dependency_use_identity(use, prefix, expected_use, errors)
            if use.get("dependency_conclusion") != record.get("exact_statement"):
                errors.append(f"{prefix}.dependency_conclusion is stale or incorrect")
            if use.get("dependency_contract_sha256") != external_hashes.get(result_id):
                errors.append(f"{prefix}.dependency_contract_sha256 is stale or incorrect")
            compatibility, compatibility_issues = validate_compatibility_matrix(
                use.get("compatibility_checks"),
                f"{prefix}.compatibility_checks",
                errors,
            )
            prerequisite_status, prerequisite_issues = validate_prerequisite_map(
                use.get("prerequisite_map"),
                root,
                f"{prefix}.prerequisite_map",
                errors,
            )
            if require_hypothesis_sources:
                errors.extend(external_prerequisite_source_errors(root, record, use, prefix))
            applicability = combine_dependency_statuses(
                (compatibility, prerequisite_status)
            )
            if applicability == "verified":
                applicability = "passed"
            expected_issues = (
                set(record_issues) | compatibility_issues | prerequisite_issues
            )
            use_issues = validate_issue_id_list(
                use.get("issue_ids"), f"{prefix}.issue_ids", errors
            )
            if use_issues != sorted(expected_issues):
                errors.append(
                    f"{prefix}.issue_ids do not match source, prerequisite, and compatibility findings"
                )
            expected_citations = sorted(
                disposition.get("key")
                for disposition in summaries_by_id.get(
                    str(use.get("dependent_unit")), {}
                ).get("citation_dispositions", [])
                if isinstance(disposition, dict)
                and disposition.get("disposition") == "external_result"
                and disposition.get("dependency_id") == result_id
                and disposition.get("dependency_use_id") == use.get("use_id")
                and is_nonempty_string(disposition.get("key"))
            )
            citation_keys = validate_string_list(
                use.get("citation_keys"),
                f"{prefix}.citation_keys",
                errors,
                allow_empty=True,
            )
            if len(citation_keys) != len(set(citation_keys)):
                errors.append(f"{prefix}.citation_keys contains duplicates")
            if citation_keys != expected_citations:
                errors.append(f"{prefix}.citation_keys disagree with citation dispositions")
            effective = combine_dependency_statuses((str(source_status), applicability))
            if use.get("status") != effective:
                errors.append(
                    f"{prefix}.status disagrees with source and applicability status; expected {effective}"
                )
            if expected_use is not None and expected_use.get("status") != effective:
                errors.append(
                    f"{prefix}: ledger dependency status disagrees with effective status {effective}"
                )
            if effective != "verified" and not use_issues:
                errors.append(f"{prefix}: a nonverified external use requires canonical issues")
            closure_issue_ids.update(use_issues)
            if valid_key:
                edges.append(
                    {
                        "dependent_unit": key[0],
                        "use_id": key[1],
                        "dependency_id": result_id,
                        "dependency_conclusion_id": None,
                        "kind": "external_result",
                        "source_status": source_status,
                        "applicability_status": applicability,
                        "effective_status": effective,
                        "step_ids": use.get("step_ids", []),
                        "issue_ids": use_issues,
                        "compatibility_checks": use.get(
                            "compatibility_checks", []
                        ),
                        "prerequisite_map": use.get(
                            "prerequisite_map", []
                        ),
                        "source_evidence": record.get(
                            "source_evidence", []
                        ),
                    }
                )

    expected_external = {
        key for key, value in expected.items() if value.get("kind") == "external_result"
    }
    missing_external = expected_external - seen_external
    if missing_external:
        errors.append(
            "Dependency registry is missing external use rows: "
            + ", ".join(f"{unit}/{use_id}" for unit, use_id in sorted(missing_external))
        )

    graph: dict[str, set[str]] = {unit_id: set() for unit_id in summaries_by_id}
    statuses_by_unit: dict[str, list[str]] = defaultdict(list)
    for edge in edges:
        dependent = edge["dependent_unit"]
        if dependent in graph:
            statuses_by_unit[dependent].append(edge["effective_status"])
        if edge["kind"] == "internal_result" and dependent in graph:
            graph[dependent].add(edge["dependency_id"])
    cycle = find_cycle(graph)
    if cycle:
        errors.append("Proof-unit dependency cycle: " + " -> ".join(cycle))
    closure_map = {
        "verified": "verified",
        "conditional": "conditionally_verified",
        "gap": "gap",
        "incorrect": "incorrect",
        "unclear": "unclear",
        "unchecked": "not_checked",
    }
    for unit_id, summary in summaries_by_id.items():
        edge_status = combine_dependency_statuses(statuses_by_unit.get(unit_id, []))
        expected_closure = closure_map[edge_status]
        declared_closure = summary.get("review_components", {}).get(
            "dependency_closure"
        )
        if declared_closure != expected_closure:
            errors.append(
                f"{unit_id}: review.dependency_closure is {declared_closure!r}; expected {expected_closure!r} from effective uses"
            )
    return {
        "external_results": external_results,
        "edges": edges,
        "unit_graph": graph,
        "issue_ids": closure_issue_ids,
    }


def validate_completion_pass(
    value: Any, field: str, errors: list[str]
) -> None:
    if not isinstance(value, dict):
        errors.append(f"completion.{field} must be an object")
        return
    status = value.get("status")
    if not is_enum_value(status, PASS_STATUSES):
        errors.append(f"completion.{field}.status is invalid")
    elif status not in {"completed", "completed_with_findings"}:
        errors.append(f"completion.{field} has not been completed")
    validate_string_list(
        value.get("evidence"),
        f"completion.{field}.evidence",
        errors,
        substantive=True,
    )


def validate_global_consistency_pass(
    value: Any,
    in_scope: list[str],
    errors: list[str],
) -> dict[str, Any]:
    field = "completion.global_consistency_pass"
    if not isinstance(value, dict):
        errors.append(f"{field} must be an object")
        return {"defect": False, "inconclusive": True, "issue_ids": set()}
    checks = value.get("checks")
    statuses = validate_aspect_matrix(
        checks,
        f"{field}.checks",
        GLOBAL_CONSISTENCY_ASPECTS,
        GLOBAL_CONSISTENCY_STATUSES,
        True,
        errors,
    )
    issue_ids: set[str] = set()
    impacts: dict[str, dict[str, Any]] = {}
    if isinstance(checks, list):
        for index, row in enumerate(checks, 1):
            if not isinstance(row, dict):
                continue
            prefix = f"{field}.checks[{index}]"
            affected = row.get("affected_units")
            if not isinstance(affected, list) or not all(
                is_nonempty_string(item) for item in affected
            ):
                errors.append(f"{prefix}.affected_units must be a string list")
                affected = []
            elif len(affected) != len(set(affected)):
                errors.append(f"{prefix}.affected_units contains duplicates")
            unknown = set(affected) - set(in_scope)
            if unknown:
                errors.append(
                    f"{prefix}.affected_units names results outside scope: "
                    + ", ".join(sorted(unknown))
                )
            row_issues = validate_issue_id_list(
                row.get("issue_ids"), f"{prefix}.issue_ids", errors
            )
            issue_ids.update(row_issues)
            status = row.get("status")
            aspect = row.get("aspect")
            if aspect in GLOBAL_CONSISTENCY_ASPECTS:
                impacts[aspect] = {
                    "status": status,
                    "affected_units": set(affected),
                    "issue_ids": set(row_issues),
                }
            if is_enum_value(status, {"passed", "not_applicable"}):
                if affected or row_issues:
                    errors.append(
                        f"{prefix}: a clean global-consistency row requires empty affected_units and issue_ids"
                    )
            elif is_enum_value(status, {"defect", "inconclusive"}):
                if not affected or not row_issues:
                    errors.append(
                        f"{prefix}: {status} requires affected_units and issue_ids"
                    )
    has_findings = any(
        is_enum_value(status, {"defect", "inconclusive"})
        for status in statuses.values()
    )
    expected_status = "completed_with_findings" if has_findings else "completed"
    if value.get("status") != expected_status:
        errors.append(
            f"{field}.status must be {expected_status} for the recorded checks"
        )
    return {
        "defect": any(status == "defect" for status in statuses.values()),
        "inconclusive": any(
            status == "inconclusive" for status in statuses.values()
        ),
        "issue_ids": issue_ids,
        "statuses": statuses,
        "impacts": impacts,
    }


def canonical_id_field(values: Any) -> str:
    if isinstance(values, (str, bytes)):
        return "<invalid>"
    try:
        materialized = list(values)
    except (TypeError, ValueError):
        return "<invalid>"
    if not all(is_nonempty_string(value) for value in materialized):
        return "<invalid>"
    normalized = sorted(set(materialized))
    return ", ".join(normalized) if normalized else "none"


def canonical_challenge_issue_assessments(value: Any) -> list[dict[str, Any]]:
    fields = (
        "issue_id",
        "target_contract_sha256",
        "assessment",
        "target_assessment",
        "downstream_assessment",
    )
    rows = value if isinstance(value, list) else []
    return [
        {field: row.get(field) for field in fields}
        for row in sorted(
            (row for row in rows if isinstance(row, dict)),
            key=lambda row: str(row.get("issue_id", "")),
        )
    ]


LEGACY_CHALLENGE_BINDING_BEGIN = "<!-- proofcheck-challenge-binding-v1"
CHALLENGE_BINDING_BEGIN = "<!-- proofcheck-challenge-binding-v2"
CHALLENGE_BINDING_END = "-->"
CHALLENGE_ARTIFACT_SCAFFOLD_MARKER = "NONFINAL CHALLENGE SCAFFOLD"


def challenge_artifact_binding_payload(
    unit_id: str, challenge: dict[str, Any]
) -> dict[str, Any]:
    """Return the exact ledger facts that a challenge artifact must carry."""
    payload = {
        "schema_version": 2,
        "unit_id": unit_id,
        "challenge_context_sha256": challenge.get("challenge_context_sha256"),
        "independence_level": challenge.get("independence_level"),
        "challenger_verdict": challenge.get("challenger_verdict"),
        "reconciled_verdict": challenge.get("reconciled_verdict"),
        "artifact": challenge.get("artifact"),
        "disagreements": challenge.get("disagreements"),
        "resolution": challenge.get("resolution"),
        "generated_utc": challenge.get("generated_utc"),
        "issue_assessments": canonical_challenge_issue_assessments(
            challenge.get("issue_assessments", [])
        ),
    }
    if "initial_response" in challenge:
        payload["initial_response"] = challenge["initial_response"]
    if "statement_support_review" in challenge:
        payload["statement_support_review"] = challenge["statement_support_review"]
    if "statement_support_review_history" in challenge:
        payload["statement_support_review_history"] = challenge["statement_support_review_history"]
    return payload


def render_challenge_artifact_binding(
    unit_id: str, challenge: dict[str, Any]
) -> str:
    payload = challenge_artifact_binding_payload(unit_id, challenge)
    encoded = json.dumps(payload, ensure_ascii=False, indent=2)
    html_safe_encoded = encoded.replace("<", "\\u003c").replace(
        ">", "\\u003e"
    )
    return (
        f"{CHALLENGE_BINDING_BEGIN}\n"
        + html_safe_encoded
        + f"\n{CHALLENGE_BINDING_END}"
    )


def has_substantive_challenge_narrative(text: str) -> bool:
    """Return whether the artifact records actual checking rationale."""
    active_text = active_markdown_text(text)
    if ACTIVE_HIDDEN_HTML_MARKER in active_text:
        return False
    lines = active_text.splitlines()
    setext_heading_lines: set[int] = set()
    for index in range(1, len(lines)):
        if (
            lines[index - 1].strip()
            and re.fullmatch(r"\s*(?:=+|-+)\s*", lines[index])
        ):
            setext_heading_lines.update({index - 1, index})
    for index, line in enumerate(lines):
        if index in setext_heading_lines:
            continue
        candidate = line.strip()
        if not candidate or re.fullmatch(r"#{1,6}(?:\s+.*)?", candidate):
            continue
        candidate = re.sub(r"^(?:[-+*]|\d+[.)])\s+", "", candidate)
        if re.fullmatch(r"[|:\-\s]+", candidate):
            continue
        word_count = len(re.findall(r"\b\w+\b", candidate))
        alphanumeric_count = sum(
            character.isalnum() for character in candidate
        )
        if (
            is_substantive_string(candidate)
            and word_count >= 4
            and alphanumeric_count >= 20
        ):
            return True
    return False


def upsert_challenge_artifact_binding(
    text: str, unit_id: str, challenge: dict[str, Any]
) -> str:
    """Replace one prior binding block and preserve the narrative around it."""
    marker_count = text.count(CHALLENGE_BINDING_BEGIN)
    legacy_marker_count = text.count(LEGACY_CHALLENGE_BINDING_BEGIN)
    if marker_count + legacy_marker_count > 1:
        raise ValueError(
            "Challenger artifact contains duplicate challenge binding blocks"
        )
    binding_begin = (
        CHALLENGE_BINDING_BEGIN
        if marker_count == 1
        else LEGACY_CHALLENGE_BINDING_BEGIN
    )
    start = text.find(binding_begin)
    if start >= 0:
        end = text.find(CHALLENGE_BINDING_END, start)
        if end < 0:
            raise ValueError(
                "Challenger artifact contains an unterminated challenge "
                "binding block"
            )
        text = text[:start] + text[end + len(CHALLENGE_BINDING_END) :]
    narrative = text.strip()
    if CHALLENGE_ARTIFACT_SCAFFOLD_MARKER in narrative:
        raise ValueError(
            "Challenger artifact still contains the NONFINAL challenge scaffold"
        )
    if not has_substantive_challenge_narrative(narrative):
        raise ValueError(
            "Challenger artifact must contain substantive checking narrative"
        )
    binding = render_challenge_artifact_binding(unit_id, challenge)
    rendered = f"{narrative}\n\n{binding}\n"
    if rendered.count(CHALLENGE_BINDING_BEGIN) != 1:
        raise ValueError(
            "Challenger artifact binding could not be canonicalized"
        )
    return rendered


def challenge_artifact_binding_errors(
    artifact_path: Path,
    unit_id: str,
    challenge: dict[str, Any],
) -> list[str]:
    """Require one parseable artifact block equal to the ledger assessment."""
    prefix = f"In-scope unit {unit_id} challenger artifact"
    try:
        text = read_text(artifact_path)
    except (OSError, UnicodeError) as exc:
        return [f"{prefix} cannot be read as UTF-8 text: {exc}"]
    if text.count(CHALLENGE_BINDING_BEGIN) != 1:
        if text.count(LEGACY_CHALLENGE_BINDING_BEGIN) == 1:
            return [
                f"{prefix} uses obsolete v1 challenge binding; rerun "
                f"bind-challenge --root <audit-root> --unit-id {unit_id}"
            ]
        return [f"{prefix} must contain exactly one challenge binding block"]
    if LEGACY_CHALLENGE_BINDING_BEGIN in text:
        return [f"{prefix} must not retain an obsolete v1 challenge binding"]
    start = text.find(CHALLENGE_BINDING_BEGIN) + len(CHALLENGE_BINDING_BEGIN)
    end = text.find(CHALLENGE_BINDING_END, start)
    if end < 0:
        return [f"{prefix} challenge binding block is unterminated"]
    raw_payload = text[start:end].strip()
    try:
        payload = json.loads(raw_payload)
    except json.JSONDecodeError as exc:
        return [f"{prefix} challenge binding block is invalid JSON: {exc}"]
    expected = challenge_artifact_binding_payload(unit_id, challenge)
    if payload != expected:
        return [
            f"{prefix} challenge binding block disagrees with the exact "
            "ledger context, independent judgment, or issue assessments"
        ]
    narrative = text[: start - len(CHALLENGE_BINDING_BEGIN)] + text[
        end + len(CHALLENGE_BINDING_END) :
    ]
    if CHALLENGE_ARTIFACT_SCAFFOLD_MARKER in narrative:
        return [f"{prefix} still contains the NONFINAL challenge scaffold"]
    if not has_substantive_challenge_narrative(narrative):
        return [f"{prefix} must contain substantive checking narrative"]
    return []


def canonical_issue_row(issue: dict[str, Any]) -> list[str]:
    values = [
        str(issue.get("id", "")),
        str(issue.get("severity", "")),
        str(issue.get("load_bearing", "")),
        str(issue.get("confidence", "")),
        str(issue.get("status", "")),
        str(issue.get("finding_status", "")),
        str(issue.get("invalidation_kind", "")),
        compact_json_value(issue.get("origin_ref")),
        compact_json_value(issue.get("contract_refs")),
        canonical_id_field(issue.get("affected_results", [])),
    ]
    return [value.replace("\n", " ") for value in values]


def canonical_interface_issue_row(
    issue: dict[str, Any],
    interfaces: dict[str, dict[str, Any]] | None = None,
) -> list[str]:
    interface = (
        interfaces.get(str(issue.get("interface_id")))
        if interfaces is not None
        else None
    )
    target_status = issue.get("estimator_target_status")
    inspection_status = issue.get("implementation_inspection_status")
    inspection_mode = issue.get("implementation_inspection_mode")
    code_to_documented = issue.get("code_to_documented_estimator")
    code_to_target = issue.get("code_to_required_target")
    provenance_status = issue.get("execution_provenance_status")
    if isinstance(interface, dict):
        target_relation = interface.get("target_relation")
        if isinstance(target_relation, dict):
            target_status = target_relation.get("verdict")
        implementation = interface.get("implementation_relation")
        if isinstance(implementation, dict):
            inspection_status = implementation.get("inspection_status")
            inspection_mode = implementation.get("inspection_mode")
            comparisons = implementation.get("comparisons")
            if isinstance(comparisons, list):
                comparison_by_target = {
                    row.get("to"): row.get("verdict")
                    for row in comparisons
                    if isinstance(row, dict)
                }
                code_to_documented = comparison_by_target.get(
                    "documented_estimator"
                )
                code_to_target = comparison_by_target.get("required_target")
            provenance = implementation.get("execution_provenance")
            if isinstance(provenance, dict):
                provenance_status = provenance.get("status")
    return [
        str(issue.get("id", "")),
        str(issue.get("finding_class", "")),
        str(issue.get("interface_id", "")),
        str(target_status or ""),
        str(inspection_status or ""),
        str(inspection_mode or ""),
        str(code_to_documented or ""),
        str(code_to_target or ""),
        str(provenance_status or ""),
        str(issue.get("affected_layer", "")),
    ]


REPORT_SCALAR_FIELDS = (
    "Overall judgment",
    "Main reason",
    "Impact on paper conclusions/results",
    "Repair options and difficulty",
    "Overall assessment code",
    "Checked scope",
    "Target results",
    "Source revision",
    "Skill version",
    "Artifact schema version",
    "Evidence contract version",
    "Method-interface schema version",
    "Closure contract version",
    "Source snapshot ID",
    "Finalization record",
    "Highest-consequence issue",
    "Final confidence",
    "Files and results checked",
    "Results not checked",
    "External results checked",
    "External results not checked",
    "Tooling, extraction, or rendering limitations",
    "Independent check levels",
    "Declared external deliverables",
)
REPORT_SUMMARY_FIELDS = (
    "Overall judgment",
    "Main reason",
    "Impact on paper conclusions/results",
    "Repair options and difficulty",
)
REPORT_SCOPE_FIELDS = tuple(
    label for label in REPORT_SCALAR_FIELDS if label not in REPORT_SUMMARY_FIELDS
)
REPORT_REQUIRED_SECTIONS = (
    "Summary",
    "Results and impact",
    "Findings and repairs",
    "Scope and assurance",
)


REPORT_SCAFFOLD_MARKER = "NONFINAL SCAFFOLD"
WORKING_REPORT_TITLE = "# NONFINAL Proof-Check Working Report"
FINAL_REPORT_TITLE = "# Final Proof-Check Report"
CANONICAL_REPORT_MARKDOWN = frozenset({"FINAL_REPORT.md", "ISSUE_SUMMARY.md"})


def contains_report_scaffold_marker(text: str) -> bool:
    return REPORT_SCAFFOLD_MARKER.casefold() in text.casefold()


def markdown_h1_lines(text: str) -> list[str]:
    """Return active Markdown H1 lines in document order."""
    lines = text.splitlines()
    headings: list[str] = []
    for index, line in enumerate(lines):
        if re.fullmatch(r"[ ]{0,3}#(?!#)[ \t]+.*\S[ \t]*", line):
            headings.append(line.strip())
            continue
        if (
            re.fullmatch(r"[ ]{0,3}=+[ \t]*", line)
            and index > 0
            and lines[index - 1].strip()
            and re.fullmatch(
                r"[ ]{0,3}#{1,6}(?:[ \t]+.*)?",
                lines[index - 1],
            )
            is None
        ):
            headings.append(
                f"{lines[index - 1].strip()}\n{line.strip()}"
            )
    return headings


def report_has_exact_title(text: str, title: str) -> bool:
    return markdown_h1_lines(text) == [title]


def declared_report_paths(value: Any, root: Path) -> set[Path]:
    paths: set[Path] = set()
    if not isinstance(value, list):
        return paths
    for record in value:
        if not isinstance(record, dict) or not is_nonempty_string(record.get("path")):
            continue
        try:
            paths.add(resolve_stored_path(record["path"], root).resolve())
        except (OSError, ValueError):
            continue
    return paths


def undeclared_report_markdown_files(value: Any, root: Path) -> list[str]:
    reports_dir = root / "audit" / "06_reports"
    if not reports_dir.is_dir():
        return []
    allowed = {
        (reports_dir / name).resolve()
        for name in CANONICAL_REPORT_MARKDOWN
    }
    allowed.update(declared_report_paths(value, root))
    return [
        path.relative_to(root).as_posix()
        for path in sorted(reports_dir.iterdir(), key=lambda item: item.name.lower())
        if path.is_file()
        and path.suffix.lower() in {".md", ".html", ".htm"}
        and path.resolve() not in allowed
    ]


def undeclared_report_error(path: str) -> str:
    return (
        "Undeclared Markdown or HTML report artifact in audit/06_reports: "
        f"{path}. Move non-deliverable working notes outside audit/06_reports, "
        "or declare a complete user_facing_report in report_deliverables."
    )


def validate_report_deliverables(
    value: Any,
    root: Path,
    canonical_issue_ids: set[str],
    overall_verdict: Any,
    errors: list[str],
) -> list[dict[str, Any]]:
    if not isinstance(value, list):
        errors.append("report_deliverables must be a list")
        return []
    records: list[dict[str, Any]] = []
    seen_ids: set[str] = set()
    seen_paths: set[Path] = set()
    canonical_report_path, canonical_report_path_valid = canonical_artifact_path(
        root,
        "audit/06_reports/FINAL_REPORT.md",
        "final report",
        errors,
    )
    canonical_report_text: str | None = None
    if canonical_report_path_valid and canonical_report_path.is_file():
        try:
            canonical_report_text = active_markdown_text(
                read_text(canonical_report_path)
            )
        except TextArtifactReadError as exc:
            errors.append(str(exc))
        if (
            canonical_report_text is not None
            and ACTIVE_HIDDEN_HTML_MARKER in canonical_report_text
        ):
            errors.append(
                "Canonical final report contains active raw HTML"
            )
    semantic_sections = REPORT_REQUIRED_SECTIONS
    if canonical_report_path_valid and canonical_report_text is None and value:
        errors.append(
            "Declared reports cannot be reconciled because the canonical "
            f"FINAL_REPORT.md is missing: {canonical_report_path}"
        )
    for index, record in enumerate(value, 1):
        prefix = f"report_deliverables[{index}]"
        if not isinstance(record, dict):
            errors.append(f"{prefix} must be an object")
            continue
        deliverable_id = record.get("id")
        if (
            not isinstance(deliverable_id, str)
            or not REPORT_DELIVERABLE_ID_RE.fullmatch(deliverable_id)
        ):
            errors.append(f"{prefix}.id must match R001")
        elif deliverable_id in seen_ids:
            errors.append(f"Duplicate report deliverable id: {deliverable_id}")
        else:
            seen_ids.add(deliverable_id)
        if record.get("role") != "user_facing_report":
            errors.append(f"{prefix}.role must be user_facing_report")
        path_value = record.get("path")
        if not is_nonempty_string(path_value):
            errors.append(f"{prefix}.path must be nonempty")
            continue
        path = resolve_stored_path(path_value, root)
        if path in seen_paths:
            errors.append(f"Duplicate report deliverable path: {path}")
        seen_paths.add(path)
        if not path.is_file():
            errors.append(f"{prefix}.path is missing: {path}")
            continue
        if record.get("sha256") != sha256_file(path):
            errors.append(f"{prefix}.sha256 is stale")
        issue_ids = record.get("issue_ids")
        if not isinstance(issue_ids, list) or not all(
            isinstance(issue_id, str) and ISSUE_ID_RE.fullmatch(issue_id)
            for issue_id in issue_ids
        ):
            errors.append(f"{prefix}.issue_ids must contain canonical issue IDs")
            issue_ids = []
        if issue_ids != sorted(canonical_issue_ids):
            errors.append(
                f"{prefix}.issue_ids must equal the canonical issue set"
            )
        if record.get("overall_verdict") != overall_verdict:
            errors.append(
                f"{prefix}.overall_verdict disagrees with the canonical verdict"
            )
        try:
            raw_text = read_text(path)
        except TextArtifactReadError as exc:
            errors.append(f"{prefix}: {exc}")
            records.append(record)
            continue
        text = active_markdown_text(raw_text)
        if ACTIVE_HIDDEN_HTML_MARKER in text:
            errors.append(
                f"{prefix}: user-facing report contains active raw HTML"
            )
        if contains_report_scaffold_marker(text):
            errors.append(
                f"{prefix}: user-facing report still contains the "
                "NONFINAL scaffold marker"
            )
        first_h2 = re.search(r"^##\s+.*$", text, re.MULTILINE)
        if first_h2 is None or first_h2.group(0) != "## Summary":
            errors.append(
                f"{prefix}: user-facing report must begin its substantive "
                "content with ## Summary"
            )
        validate_report_assurance_language(
            raw_text, f"{prefix} user-facing report", errors
        )
        rendered_issue_ids = set(re.findall(r"\bI-[0-9]{3}\b", text))
        if rendered_issue_ids != canonical_issue_ids:
            errors.append(
                f"{prefix}: rendered issue IDs disagree with ISSUE_LOG.json"
            )
        for heading in re.findall(r"^#{2,4}\s+.*$", text, re.MULTILINE):
            if re.search(r"\bS[0-3]\b", heading) and not re.search(
                r"\bI-[0-9]{3}\b", heading
            ):
                errors.append(
                    f"{prefix}: severity-bearing finding heading lacks a "
                    "canonical issue ID: " + truncate(heading, 140)
                )
        verdict_matches = re.findall(
            r"^- (?:Overall assessment code|Overall verdict):\s*(.*?)\s*$",
            text,
            re.MULTILINE,
        )
        if len(verdict_matches) != 1 or verdict_matches[0] != overall_verdict:
            errors.append(
                f"{prefix}: rendered report needs exactly one canonical overall verdict"
            )
        if canonical_report_text is not None:
            for label in REPORT_SCALAR_FIELDS:
                canonical_values = re.findall(
                    rf"^- {re.escape(label)}:\s*(.*?)\s*$",
                    canonical_report_text,
                    re.MULTILINE,
                )
                rendered_values = re.findall(
                    rf"^- {re.escape(label)}:\s*(.*?)\s*$",
                    text,
                    re.MULTILINE,
                )
                if len(canonical_values) != 1:
                    errors.append(
                        f"{prefix}: canonical report field {label} is "
                        "missing or duplicated"
                    )
                elif rendered_values != canonical_values:
                    errors.append(
                        f"{prefix}: user-facing report field {label} "
                        "disagrees with the canonical report"
                    )
            for section_name in semantic_sections:
                heading = f"## {section_name}"
                canonical_count = len(
                    re.findall(
                        rf"^{re.escape(heading)}\s*$",
                        canonical_report_text,
                        re.MULTILINE,
                    )
                )
                rendered_count = len(
                    re.findall(
                        rf"^{re.escape(heading)}\s*$",
                        text,
                        re.MULTILINE,
                    )
                )
                if canonical_count == 0 and section_name == "Verdict":
                    # Early schema-5 reports place the canonical verdict fields
                    # directly below the title. Their exact overall verdict is
                    # already reconciled above, while extra orientation prose is
                    # intentionally allowed.
                    continue
                if canonical_count != 1:
                    errors.append(
                        f"{prefix}: canonical {section_name} section is "
                        "missing or duplicated"
                    )
                    continue
                if rendered_count != 1:
                    errors.append(
                        f"{prefix}: user-facing {section_name} section is "
                        "missing or duplicated"
                    )
                    continue
                canonical_section = (
                    report_section(canonical_report_text, heading) or ""
                ).strip()
                rendered_section = (
                    report_section(text, heading) or ""
                ).strip()
                if rendered_section != canonical_section:
                    errors.append(
                        f"{prefix}: user-facing {section_name} section "
                        "disagrees with the canonical report"
                    )
        records.append(record)
    return records


def report_section(text: str, heading: str) -> str | None:
    match = re.search(
        rf"^{re.escape(heading)}\s*$\n(.*?)(?=^##\s|\Z)",
        text,
        re.MULTILINE | re.DOTALL,
    )
    return match.group(1) if match is not None else None


def report_nested_section(text: str, heading: str) -> str | None:
    """Return a Markdown subsection until the next heading of equal rank."""
    level = len(heading) - len(heading.lstrip("#"))
    match = re.search(
        rf"^{re.escape(heading)}\s*$\n(.*?)(?=^#{{1,{level}}}\s|\Z)",
        text,
        re.MULTILINE | re.DOTALL,
    )
    return match.group(1) if match is not None else None


def markdown_table_rows(section: str) -> list[list[str]]:
    rows: list[list[str]] = []
    for line in section.splitlines():
        stripped = line.strip()
        if stripped.startswith("|") and stripped.endswith("|"):
            content = stripped[1:-1]
            cells: list[str] = []
            current: list[str] = []
            index = 0
            while index < len(content):
                if content[index] == "\\" and index + 1 < len(content) and content[
                    index + 1
                ] == "|":
                    current.append("|")
                    index += 2
                    continue
                if content[index] == "|":
                    cells.append("".join(current).strip())
                    current = []
                else:
                    current.append(content[index])
                index += 1
            cells.append("".join(current).strip())
            rows.append(cells)
    if len(rows) < 2:
        return []
    delimiter = rows[1]
    if len(delimiter) != len(rows[0]) or any(
        re.fullmatch(r":?-{3,}:?", cell) is None for cell in delimiter
    ):
        return []
    return rows


def markdown_tables(section: str) -> list[list[list[str]]]:
    tables: list[list[list[str]]] = []
    current_lines: list[str] = []
    for line in section.splitlines():
        stripped = line.strip()
        if stripped.startswith("|") and stripped.endswith("|"):
            current_lines.append(line)
            continue
        if current_lines:
            tables.append(markdown_table_rows("\n".join(current_lines)))
            current_lines = []
    if current_lines:
        tables.append(markdown_table_rows("\n".join(current_lines)))
    return tables


ACTIVE_HIDDEN_HTML_MARKER = "PROOFCHECK_ACTIVE_RAW_HTML"


def active_markdown_text(text: str) -> str:
    """Mask nonrendered Markdown and flag active raw HTML semantics."""
    characters = list(text)
    fence_character: str | None = None
    fence_length = 0
    in_comment = False
    offset = 0
    for line in text.splitlines(keepends=True):
        content = line.rstrip("\r\n")
        if fence_character is not None:
            mask_tex_range(characters, offset, offset + len(line))
            if re.fullmatch(
                rf"[ ]{{0,3}}{re.escape(fence_character)}"
                rf"{{{fence_length},}}[ \t]*",
                content,
            ):
                fence_character = None
                fence_length = 0
            offset += len(line)
            continue

        cursor = 0
        if in_comment:
            closing_comment = content.find("-->")
            if closing_comment < 0:
                mask_tex_range(characters, offset, offset + len(line))
                offset += len(line)
                continue
            mask_tex_range(
                characters, offset, offset + closing_comment + 3
            )
            cursor = closing_comment + 3
            in_comment = False

        if cursor == 0 and re.match(r"^(?: {4}|\t)", content):
            mask_tex_range(characters, offset, offset + len(line))
            offset += len(line)
            continue
        opening_fence = (
            re.match(r"^[ ]{0,3}(\x60{3,}|~{3,})", content)
            if cursor == 0
            else None
        )
        if opening_fence is not None:
            marker = opening_fence.group(1)
            fence_character = marker[0]
            fence_length = len(marker)
            mask_tex_range(characters, offset, offset + len(line))
            offset += len(line)
            continue

        while cursor < len(content):
            if content.startswith("<!--", cursor):
                closing_comment = content.find("-->", cursor + 4)
                if closing_comment < 0:
                    mask_tex_range(
                        characters, offset + cursor, offset + len(line)
                    )
                    in_comment = True
                    break
                mask_tex_range(
                    characters,
                    offset + cursor,
                    offset + closing_comment + 3,
                )
                cursor = closing_comment + 3
                continue
            if content[cursor] == "\x60":
                run_end = cursor + 1
                while (
                    run_end < len(content)
                    and content[run_end] == "\x60"
                ):
                    run_end += 1
                marker = content[cursor:run_end]
                closing_code = content.find(marker, run_end)
                if closing_code >= 0:
                    mask_tex_range(
                        characters,
                        offset + cursor,
                        offset + closing_code + len(marker),
                    )
                    cursor = closing_code + len(marker)
                    continue
            cursor += 1
        offset += len(line)

    visible = "".join(characters)
    html_scan = list(visible)

    for match in re.finditer(
        r"(?<!\\)\$\$(?:.|\n)*?(?<!\\)\$\$|"
        r"\\\[(?:.|\n)*?\\\]|\\\((?:.|\n)*?\\\)|"
        r"(?<!\\)\$(?!\$)[^\n]*?(?<!\\)\$",
        visible,
    ):
        mask_tex_range(html_scan, match.start(), match.end())
    for match in re.finditer(
        r"\\begin\{(?P<env>equation\*?|align\*?|alignat\*?|gather\*?|"
        r"multline\*?|displaymath)\}(?:.|\n)*?"
        r"\\end\{(?P=env)\}",
        visible,
    ):
        mask_tex_range(html_scan, match.start(), match.end())

    offset = 0
    table_start: int | None = None
    table_lines: list[str] = []

    def mask_quoted_evidence_rows() -> None:
        if table_start is None or len(table_lines) < 3:
            return
        rows = markdown_table_rows("".join(table_lines))
        exact_headers = {
            "Exact locked quote",
            "Failure evidence",
            "Exact use-site quote",
        }
        if rows and exact_headers.intersection(rows[0]):
            data_start = table_start + len(table_lines[0]) + len(table_lines[1])
            data_end = table_start + sum(len(line) for line in table_lines)
            mask_tex_range(html_scan, data_start, data_end)

    for line in visible.splitlines(keepends=True):
        content = line.rstrip("\r\n")
        stripped = content.strip()
        if re.match(r"^[ ]{0,3}>", content):
            mask_tex_range(html_scan, offset, offset + len(line))
        if stripped.startswith("|") and stripped.endswith("|"):
            if table_start is None:
                table_start = offset
            table_lines.append(line)
        else:
            mask_quoted_evidence_rows()
            table_start = None
            table_lines = []
        offset += len(line)
    mask_quoted_evidence_rows()

    active_html = re.search(
        r"<(?!(?:https?|mailto):)(?:"
        r"[A-Za-z][A-Za-z0-9:-]*(?=[\s/>])|![A-Za-z]|\?)",
        "".join(html_scan),
        re.IGNORECASE,
    )
    if active_html is not None:
        return visible + "\n" + ACTIVE_HIDDEN_HTML_MARKER + "\n"
    return visible


def authorial_report_text(text: str) -> str:
    """Return active report prose with quotations and exact evidence masked."""
    active = active_markdown_text(text)
    characters = list(active)
    generated_section_patterns = (
        r"^## Results and impact\s*$\n.*?(?=^##\s|\Z)",
        r"^## Findings and repairs\s*$\n.*?(?=^##\s|\Z)",
        (
            r"^### Independent verification\s*$\n.*?"
            r"(?=^#{1,3}\s|\Z)"
        ),
        (
            r"^### Declared external deliverables\s*$\n.*?"
            r"(?=^#{1,3}\s|\Z)"
        ),
    )
    for pattern in generated_section_patterns:
        for match in re.finditer(pattern, active, re.MULTILINE | re.DOTALL):
            mask_tex_range(characters, match.start(), match.end())
    offset = 0
    lines = active.splitlines(keepends=True)
    for line in lines:
        content = line.rstrip("\r\n")
        if re.match(r"^[ ]{0,3}>", content) or re.match(r"^(?: {4}|\t)", content):
            mask_tex_range(characters, offset, offset + len(line))
        else:
            for match in re.finditer(
                r"(?P<ticks>\x60+)[^\n]*?(?P=ticks)", content
            ):
                mask_tex_range(
                    characters, offset + match.start(), offset + match.end()
                )
        offset += len(line)

    active = "".join(characters)
    lines = active.splitlines(keepends=True)
    offset = 0
    table_start: int | None = None
    table_lines: list[str] = []

    def mask_exact_evidence_table() -> None:
        if table_start is None or not table_lines:
            return
        rows = markdown_table_rows("".join(table_lines))
        if not rows:
            return
        exact_headers = {
            "Exact locked quote",
            "Failure evidence",
            "Exact use-site quote",
        }
        if not exact_headers.intersection(rows[0]):
            return
        header_length = len(table_lines[0]) if table_lines else 0
        delimiter_length = len(table_lines[1]) if len(table_lines) > 1 else 0
        data_start = table_start + header_length + delimiter_length
        data_end = table_start + sum(len(item) for item in table_lines)
        mask_tex_range(characters, data_start, data_end)

    for line in lines:
        stripped = line.strip()
        if stripped.startswith("|") and stripped.endswith("|"):
            if table_start is None:
                table_start = offset
            table_lines.append(line)
        else:
            mask_exact_evidence_table()
            table_start = None
            table_lines = []
        offset += len(line)
    mask_exact_evidence_table()
    return "".join(characters)


def validate_report_assurance_language(
    text: str, prefix: str, errors: list[str]
) -> None:
    """Reject unsupported assurance claims in active authorial prose."""
    prose = authorial_report_text(text)
    if re.search(
        r"(?:complete proof certification|"
        r"certif(?:y|ies|ied).{0,80}proof.{0,40}(?:correct|valid))",
        prose,
        re.IGNORECASE | re.DOTALL,
    ):
        errors.append(f"{prefix} contains unsupported proof-certification language")
    if re.search(
        r"(?<!not )(?<!not a )\b(?:formally\s+(?:verified|checked|certified)|"
        r"(?:kernel|machine|proof[- ]assistant)[ -](?:checked|verified|certified))"
        r"\s+(?:mathematical\s+)?proof\b|"
        r"\bproof\b.{0,40}\b(?:is|was|has been)\s+(?!not\b)formally\s+"
        r"(?:verified|checked|certified)\b",
        prose,
        re.IGNORECASE | re.DOTALL,
    ):
        errors.append(f"{prefix} contains unsupported formal-verification language")
    calibrated_prose = prose
    for calibrated_context in (
        r"\b(?:this audit\s+|we\s+|the audit\s+)?"
        r"(?:do|does|did|can|could|should|would|will)\s+not\s+"
        r"(?:claim|assert|establish|show|mean)\s+(?:that\s+)?"
        r"[^.!?\n]{0,160}\b(?:correct|valid)\b",
        r"\b(?:it\s+is\s+)?(?:unclear|uncertain|unknown|unresolved)?\s*"
        r"whether\s+[^.!?\n]{0,160}\b(?:correct|valid)\b",
        r"\b(?:we\s+found\s+)?no\s+(?:evidence|basis)\s+"
        r"(?:that|to\s+(?:conclude|claim)\s+that)\s+"
        r"[^.!?\n]{0,160}\b(?:correct|valid)\b",
    ):
        calibrated_prose = re.sub(
            calibrated_context,
            "",
            calibrated_prose,
            flags=re.IGNORECASE,
        )
    overclaim_pattern = re.compile(
        r"\b(?:(?:the|this|that|our|each|every|all)\s+)?"
        r"(?:paper|appendix|theorem|proof|lemma|proposition|corollary|"
        r"result|argument|derivation|statement|conclusion)s?\b.{0,80}"
        r"\b(?:is|are|was|were|has been|have been)\s+"
        r"(?:mathematically\s+)?(?:correct|valid)\b",
        re.IGNORECASE | re.DOTALL,
    )
    for match in overclaim_pattern.finditer(calibrated_prose):
        errors.append(f"{prefix} contains an unsupported correctness overclaim")
        break


def report_subsection(text: str, heading: str) -> str | None:
    match = re.search(
        rf"^{re.escape(heading)}\s*$\n(.*?)(?=^####\s|\Z)",
        text,
        re.MULTILINE | re.DOTALL,
    )
    return match.group(1) if match is not None else None


def load_summary_ledger(summary: dict[str, Any]) -> tuple[dict[str, Any], Path] | None:
    ledger_value = summary.get("ledger")
    if not is_nonempty_string(ledger_value):
        return None
    ledger_path = Path(ledger_value)
    ledger, ledger_errors = load_json_object(ledger_path, "report ledger")
    return (ledger, ledger_path) if not ledger_errors else None


def ledger_step_projection(
    summary: dict[str, Any], step_id: Any
) -> dict[str, Any] | None:
    loaded = load_summary_ledger(summary)
    if loaded is None:
        return None
    ledger, ledger_path = loaded
    step = next(
        (
            row
            for row in ledger.get("steps", [])
            if isinstance(row, dict) and row.get("id") == step_id
        ),
        None,
    )
    if not isinstance(step, dict):
        return None
    if ledger.get("schema_version") == SCHEMA_VERSION:
        source_unit_id = step.get("source_unit_id")
        source_unit = next(
            (
                row
                for row in ledger.get("source_units", [])
                if isinstance(row, dict) and row.get("id") == source_unit_id
            ),
            None,
        )
        line_range = source_unit.get("lines") if isinstance(source_unit, dict) else None
    else:
        source_unit = None
        line_range = step.get("lines")
    if (
        not isinstance(line_range, list)
        or len(line_range) != 2
        or not all(is_int(value) for value in line_range)
    ):
        return None
    start_line, end_line = line_range
    locked_rows = {
        row.get("line"): row.get("text")
        for row in ledger.get("source_lines", [])
        if isinstance(row, dict)
        and is_int(row.get("line"))
        and isinstance(row.get("text"), str)
    }
    if any(line not in locked_rows for line in range(start_line, end_line + 1)):
        return None
    quote = "\n".join(
        locked_rows[line] for line in range(start_line, end_line + 1)
    )
    source = ledger.get("source", {})
    file_value = source.get("file") if isinstance(source, dict) else None
    if "source_fragments" in ledger:
        location = source_unit_location(ledger, source_unit)
        file_value, start_line, end_line = location["file"], location["start_line"], location["end_line"]
    return {
        "ledger": ledger,
        "ledger_path": ledger_path,
        "step": step,
        "file": str(file_value),
        "start_line": start_line,
        "end_line": end_line,
        "sha256": sha256_text(quote),
        "quote": quote,
    }


def locked_span_report_value(span: Any, ledger_path: Path) -> str:
    if not isinstance(span, dict):
        return "<invalid>"
    file_value = span.get("file")
    start_line = span.get("start_line")
    end_line = span.get("end_line")
    if (
        not is_nonempty_string(file_value)
        or not is_int(start_line)
        or not is_int(end_line)
    ):
        return "<invalid>"
    path = resolve_stored_path(file_value, ledger_path.parent)
    try:
        lines = read_lines(path)
        quote = "\n".join(lines[start_line - 1 : end_line])
    except (OSError, UnicodeError):
        return "<unavailable>"
    return json.dumps(
        {
            "file": file_value,
            "lines": [start_line, end_line],
            "sha256": sha256_text(quote),
            "quote": quote,
        },
        ensure_ascii=False,
        sort_keys=True,
    )


def infer_audit_root(
    summaries_by_id: dict[str, dict[str, Any]],
) -> Path | None:
    for summary in summaries_by_id.values():
        ledger_value = summary.get("ledger")
        if not is_nonempty_string(ledger_value):
            continue
        ledger_path = Path(ledger_value).resolve()
        for candidate in (ledger_path.parent, *ledger_path.parents):
            if (candidate / "AUDIT_MANIFEST.json").is_file():
                return candidate
    return None


def locked_span_projection(
    span: Any, base: Path | None
) -> dict[str, Any] | None:
    if not isinstance(span, dict) or base is None:
        return None
    file_value = span.get("file")
    start_line = span.get("start_line")
    end_line = span.get("end_line")
    if (
        not is_nonempty_string(file_value)
        or not is_int(start_line)
        or not is_int(end_line)
        or start_line < 1
        or end_line < start_line
    ):
        return None
    source = resolve_stored_path(file_value, base)
    try:
        lines = read_lines(source)
    except (OSError, UnicodeError):
        return None
    if end_line > len(lines):
        return None
    quote = "\n".join(lines[start_line - 1 : end_line])
    return {
        "file": str(file_value),
        "start_line": start_line,
        "end_line": end_line,
        "sha256": sha256_text(quote),
        "quote": quote,
    }


def canonical_nonledger_origin_diagnostic(
    issue: dict[str, Any],
    interfaces: dict[str, dict[str, Any]] | None,
    global_checks: dict[str, dict[str, Any]] | None,
) -> dict[str, str] | None:
    """Project the exact canonical diagnostic for interface/global origins."""
    origin = issue.get("origin_ref")
    if not isinstance(origin, dict):
        return None
    kind = origin.get("kind")
    if kind == "interface_record":
        interface_id = str(origin.get("interface_id"))
        interface = (
            interfaces.get(interface_id)
            if interfaces is not None
            else None
        )
        if not isinstance(interface, dict):
            return None
        target_relation = interface.get("target_relation")
        implementation = interface.get("implementation_relation")
        return {
            "claim": str(
                target_relation.get("required_target")
                if isinstance(target_relation, dict)
                else issue.get("summary", "none")
            ),
            "rule": "canonical method-interface comparison",
            "premises": json.dumps(
                {
                    "interface_id": interface_id,
                    "affected_results": interface.get("affected_results"),
                },
                ensure_ascii=False,
                sort_keys=True,
            ),
            "failure_evidence": json.dumps(
                {
                    "target_relation": target_relation,
                    "implementation_relation": implementation,
                    "issue_ids": interface.get("issue_ids"),
                },
                ensure_ascii=False,
                sort_keys=True,
            ),
            "failure_kind": str(
                issue.get("finding_class", issue.get("invalidation_kind", "none"))
            ),
        }
    if kind == "global_check":
        aspect = str(origin.get("aspect"))
        check = (
            global_checks.get(aspect)
            if global_checks is not None
            else None
        )
        if not isinstance(check, dict):
            return None
        return {
            "claim": f"Global consistency check: {aspect}",
            "rule": "canonical global-consistency check",
            "premises": json.dumps(
                {"affected_units": check.get("affected_units")},
                ensure_ascii=False,
                sort_keys=True,
            ),
            "failure_evidence": json.dumps(
                {
                    "aspect": check.get("aspect"),
                    "status": check.get("status"),
                    "evidence": check.get("evidence"),
                    "affected_units": check.get("affected_units"),
                    "issue_ids": check.get("issue_ids"),
                },
                ensure_ascii=False,
                sort_keys=True,
            ),
            "failure_kind": str(
                check.get("status", issue.get("invalidation_kind", "none"))
            ),
        }
    return None


def archived_nonledger_failure_rows(
    issue: dict[str, Any],
    interfaces: dict[str, dict[str, Any]] | None,
    global_checks: dict[str, dict[str, Any]] | None,
    sealed_sources: dict[str, bytes],
) -> list[list[str]] | None:
    """Recompute interface/global failure rows from sealed canonical bytes."""
    diagnostic = canonical_nonledger_origin_diagnostic(
        issue, interfaces, global_checks
    )
    if diagnostic is None:
        return None
    origin = issue.get("origin_ref")
    if not isinstance(origin, dict):
        return []
    affected_result = str(issue.get("affected_result"))
    origin_unit = str(origin.get("unit_id", affected_result))
    origin_reference = compact_json_value(
        {
            key: value
            for key, value in origin.items()
            if key != "evidence_spans"
        }
    )
    spans = origin.get("evidence_spans")
    if not isinstance(spans, list):
        return []
    rows: list[list[str]] = []
    for span in spans:
        if not isinstance(span, dict):
            continue
        file_value = span.get("file")
        start_line = span.get("start_line")
        end_line = span.get("end_line")
        if (
            not is_nonempty_string(file_value)
            or not is_int(start_line)
            or not is_int(end_line)
            or start_line < 1
            or end_line < start_line
        ):
            continue
        source_bytes = sealed_sources.get(str(file_value))
        try:
            source_lines = (
                source_bytes.decode("utf-8-sig").splitlines()
                if source_bytes is not None
                else []
            )
        except UnicodeError:
            source_lines = []
        if end_line > len(source_lines):
            continue
        quote = "\n".join(source_lines[start_line - 1 : end_line])
        rows.append(
            [
                f"{file_value}:{start_line}-{end_line}",
                sha256_text(quote),
                json.dumps(quote, ensure_ascii=False),
                origin_unit,
                origin_reference,
                diagnostic["claim"],
                diagnostic["rule"],
                diagnostic["premises"],
                diagnostic["failure_evidence"],
                diagnostic["failure_kind"],
            ]
        )
    return rows


def canonical_issue_detail_projection(
    issue: dict[str, Any],
    summaries_by_id: dict[str, dict[str, Any]],
    dependency_edges: list[dict[str, Any]],
    challenge_units: Iterable[str],
    report_deliverables: list[dict[str, Any]],
    overall_assessment: Any,
    evidence_base: Path | None = None,
    interfaces: dict[str, dict[str, Any]] | None = None,
    global_checks: dict[str, dict[str, Any]] | None = None,
) -> dict[str, Any]:
    issue_id = str(issue.get("id"))
    affected_result = str(issue.get("affected_result"))
    raw_affected_results = issue.get("affected_results")
    affected_results = (
        {
            item
            for item in raw_affected_results
            if is_nonempty_string(item)
        }
        if isinstance(raw_affected_results, list)
        else set()
    )
    contract_refs = issue.get("contract_refs")
    if not isinstance(contract_refs, list):
        contract_refs = []
    suggested_changes = issue.get("suggested_changes")
    if not isinstance(suggested_changes, list):
        suggested_changes = []
    origin = issue.get("origin_ref") if isinstance(issue.get("origin_ref"), dict) else {}
    origin_unit = str(origin.get("unit_id", affected_result))
    origin_summary = summaries_by_id.get(origin_unit, {})
    origin_projection = None
    origin_move: dict[str, Any] = {}
    origin_claim = "none"
    origin_rule = str(origin.get("kind", "none"))
    origin_premises = "none"
    origin_failure_evidence = "none"
    origin_failure_kind = str(issue.get("invalidation_kind", "none"))
    origin_reference = compact_json_value(
        {key: value for key, value in origin.items() if key != "evidence_spans"}
    )
    evidence_base = evidence_base or infer_audit_root(summaries_by_id)
    resolution_archive: dict[str, Any] | None = None
    if (
        issue.get("status") == "resolved"
        and evidence_base is not None
        and isinstance(issue.get("historical_origin"), dict)
    ):
        archive_errors: list[str] = []
        candidate_archive = load_resolution_archive(
            issue, evidence_base, archive_errors
        )
        if not archive_errors:
            resolution_archive = candidate_archive
    if origin.get("kind") == "ledger_move":
        origin_projection = ledger_step_projection(
            origin_summary, origin.get("step_id")
        )
        if origin_projection is not None:
            inference = origin_projection["step"].get("inference")
            moves = inference.get("moves", []) if isinstance(inference, dict) else []
            origin_move = next(
                (
                    move
                    for move in moves
                    if isinstance(move, dict)
                    and move.get("id") == origin.get("move_id")
                ),
                {},
            )
            origin_claim = str(origin_move.get("claim", "none"))
            origin_rule = str(origin_move.get("rule", "none"))
            failure = origin_move.get("failure")
            premise_by_id = {
                row.get("id"): row
                for row in origin_projection["step"].get("premise_uses", [])
                if isinstance(row, dict) and is_nonempty_string(row.get("id"))
            }
            origin_premises = json.dumps(
                {
                    "premises": [
                        {
                            "id": premise_id,
                            "claim": premise_by_id.get(premise_id, {}).get(
                                "claim"
                            ),
                            "origin": premise_by_id.get(premise_id, {}).get(
                                "origin"
                            ),
                        }
                        for premise_id in origin_move.get("premise_ids", [])
                    ],
                    "prior_moves": origin_move.get("prior_move_ids", []),
                },
                ensure_ascii=False,
            )
            origin_failure_evidence = (
                str(failure.get("evidence"))
                if isinstance(failure, dict)
                else "none"
            )
            origin_failure_kind = (
                str(failure.get("kind"))
                if isinstance(failure, dict)
                else origin_failure_kind
            )
    elif origin.get("kind") == "dependency_use":
        use_id = origin.get("use_id")
        dependency_claim = next(
            (
                row
                for row in origin_summary.get("result_dependency_claims", [])
                if isinstance(row, dict) and row.get("use_id") == use_id
            ),
            {},
        )
        origin_projection = ledger_step_projection(
            origin_summary, dependency_claim.get("owner_step")
        )
        direct_dependency = next(
            (
                row
                for row in origin_summary.get("direct_dependencies", [])
                if isinstance(row, dict) and row.get("use_id") == use_id
            ),
            {},
        )
        origin_claim = str(direct_dependency.get("needed_form", "none"))
        origin_premises = json.dumps(
            {
                "dependency_id": direct_dependency.get("id"),
                "conclusion_id": direct_dependency.get("conclusion_id"),
                "needed_form": direct_dependency.get("needed_form"),
            },
            ensure_ascii=False,
        )
        origin_rule = str(
            direct_dependency.get("compatibility_check", "dependency_use")
        )
        origin_edge = next(
            (
                edge
                for edge in dependency_edges
                if isinstance(edge, dict)
                and edge.get("dependent_unit") == affected_result
                and edge.get("use_id") == use_id
            ),
            {},
        )
        origin_failure_evidence = json.dumps(
            {
                "source_status": origin_edge.get("source_status"),
                "applicability_status": origin_edge.get(
                    "applicability_status"
                ),
                "effective_status": origin_edge.get("effective_status"),
                "issue_ids": origin_edge.get("issue_ids"),
                "nonpassing_compatibility_checks": [
                    {
                        "aspect": row.get("aspect"),
                        "status": row.get("status"),
                        "evidence": row.get("evidence"),
                        "issue_ids": row.get("issue_ids"),
                    }
                    for row in origin_edge.get(
                        "compatibility_checks", []
                    )
                    if isinstance(row, dict)
                    and row.get("status")
                    not in {"passed", "not_applicable"}
                ],
                "nonpassing_prerequisites": [
                    {
                        "prerequisite": row.get("prerequisite"),
                        "status": row.get("status"),
                        "manuscript_evidence": row.get(
                            "manuscript_evidence"
                        ),
                        "evidence_spans": row.get("evidence_spans"),
                        "issue_ids": row.get("issue_ids"),
                    }
                    for row in origin_edge.get("prerequisite_map", [])
                    if isinstance(row, dict)
                    and row.get("status") != "satisfied"
                ],
                "source_evidence": (
                    origin_edge.get("source_evidence", [])
                    if origin_edge.get("source_status") != "verified"
                    else []
                ),
            },
            ensure_ascii=False,
        )
        origin_failure_kind = str(
            direct_dependency.get("status", origin_failure_kind)
        )

    origin_span_projections: list[dict[str, Any]] = []
    if origin.get("kind") in {"interface_record", "global_check"}:
        origin_span_projections = [
            projection
            for span in (
                origin.get("evidence_spans")
                if isinstance(origin.get("evidence_spans"), list)
                else []
            )
            if (projection := locked_span_projection(span, evidence_base))
            is not None
        ]
        diagnostic = canonical_nonledger_origin_diagnostic(
            issue, interfaces, global_checks
        )
        if diagnostic is not None:
            origin_claim = diagnostic["claim"]
            origin_rule = diagnostic["rule"]
            origin_premises = diagnostic["premises"]
            origin_failure_evidence = diagnostic["failure_evidence"]
            origin_failure_kind = diagnostic["failure_kind"]
    elif origin.get("kind") == "obligation_pointer":
        loaded_origin = load_summary_ledger(origin_summary)
        if loaded_origin is not None:
            origin_ledger, origin_ledger_path = loaded_origin
            obligation = origin_ledger.get("obligation")
            if not isinstance(obligation, dict):
                obligation = {}
            found, pointer_value = resolve_json_pointer(
                obligation, origin.get("pointer")
            )
            origin_claim = (
                json.dumps(pointer_value, ensure_ascii=False)
                if found
                else "none"
            )
            origin_premises = json.dumps(
                {"obligation_pointer": origin.get("pointer")},
                ensure_ascii=False,
            )
            origin_failure_evidence = (
                "The issue is anchored to this exact normalized obligation "
                "field and its source-locked statement context."
            )
            candidate_spans = nested_locked_spans(pointer_value)
            if not candidate_spans:
                candidate_spans = [
                    span
                    for field in ("statement_spans", "context_spans")
                    for span in (
                        obligation.get(field)
                        if isinstance(obligation.get(field), list)
                        else []
                    )
                    if isinstance(span, dict)
                ]
            origin_span_projections = [
                projection
                for span in candidate_spans
                if (
                    projection := locked_span_projection(
                        span, origin_ledger_path.parent
                    )
                )
                is not None
            ]
    if origin_projection is not None:
        origin_span_projections = [origin_projection]
    failure_rows = [
        [
            f"{projection['file']}:{projection['start_line']}-{projection['end_line']}",
            str(projection["sha256"]),
            json.dumps(projection["quote"], ensure_ascii=False),
            origin_unit,
            (
                f"{origin.get('step_id')}/{origin.get('move_id')}"
                if origin.get("kind") == "ledger_move"
                else origin_reference
            ),
            origin_claim,
            origin_rule,
            origin_premises,
            origin_failure_evidence,
            origin_failure_kind,
        ]
        for projection in origin_span_projections
    ]
    if not failure_rows:
        failure_rows = [
            [
                origin_reference,
                "none",
                "none",
                origin_unit,
                (
                    f"{origin.get('step_id')}/{origin.get('move_id')}"
                    if origin.get("kind") == "ledger_move"
                    else origin_reference
                ),
                origin_claim,
                origin_rule,
                origin_premises,
                origin_failure_evidence,
                origin_failure_kind,
            ]
        ]

    contract_rows: list[list[str]] = []
    for contract_ref in contract_refs:
        if not isinstance(contract_ref, dict):
            continue
        unit_id = str(contract_ref.get("unit_id"))
        summary = summaries_by_id.get(unit_id, {})
        loaded = load_summary_ledger(summary)
        if loaded is None:
            continue
        ledger, ledger_path = loaded
        obligation = ledger.get("obligation")
        if not isinstance(obligation, dict):
            obligation = {}
        kind = contract_ref.get("kind")
        if kind == "conclusion":
            conclusions = obligation.get("conclusions")
            if not isinstance(conclusions, list):
                conclusions = []
            conclusion = next(
                (
                    row
                    for row in conclusions
                    if isinstance(row, dict)
                    and row.get("id") == contract_ref.get("conclusion_id")
                ),
                {},
            )
            resolved_scope = []
            applies_under = conclusion.get("applies_under")
            if not isinstance(applies_under, list):
                applies_under = []
            for pointer in applies_under:
                found, value = resolve_json_pointer(obligation, pointer)
                resolved_scope.append(
                    {"pointer": pointer, "value": value if found else "<unresolved>"}
                )
            source_spans = conclusion.get("source_spans")
            if not isinstance(source_spans, list):
                source_spans = []
            evidence = "; ".join(
                locked_span_report_value(span, ledger_path)
                for span in source_spans
            )
            contract_rows.append(
                [
                    compact_json_value(contract_ref),
                    str(conclusion.get("claim", "<unresolved>")),
                    json.dumps(resolved_scope, ensure_ascii=False, sort_keys=True),
                    evidence or "none",
                ]
            )
        elif kind == "obligation_pointer":
            found, value = resolve_json_pointer(
                obligation, contract_ref.get("pointer")
            )
            contract_rows.append(
                [
                    compact_json_value(contract_ref),
                    json.dumps(value if found else "<unresolved>", ensure_ascii=False),
                    json.dumps(
                        {
                            "probability_model": obligation.get("probability_model"),
                            "regime": obligation.get("regime"),
                        },
                        ensure_ascii=False,
                        sort_keys=True,
                    ),
                    str(contract_ref.get("pointer")),
                ]
            )
        elif kind == "dependency_use":
            use_id = contract_ref.get("use_id")
            review = ledger.get("review")
            if not isinstance(review, dict):
                review = {}
            direct_dependencies = review.get("direct_dependencies")
            if not isinstance(direct_dependencies, list):
                direct_dependencies = []
            dependency = next(
                (
                    row
                    for row in direct_dependencies
                    if isinstance(row, dict) and row.get("use_id") == use_id
                ),
                {},
            )
            contract_rows.append(
                [
                    compact_json_value(contract_ref),
                    str(dependency.get("needed_form", "<unresolved>")),
                    str(dependency.get("compatibility_check", "<unresolved>")),
                    f"use_id={use_id}",
                ]
            )

    propagation_rows: list[list[str]] = []
    origin_effect = str(issue.get("invalidation_kind"))
    propagation_rows.append(
        [
            affected_result,
            "origin",
            "none",
            "none",
            failure_rows[0][0],
            failure_rows[0][1],
            failure_rows[0][2],
            origin_effect,
        ]
    )
    origin_dependency_use = (
        str(origin.get("use_id"))
        if origin.get("kind") == "dependency_use"
        and is_nonempty_string(origin.get("use_id"))
        else None
    )
    for edge in dependency_edges:
        if not isinstance(edge, dict):
            continue
        dependent = edge.get("dependent_unit")
        dependency = edge.get("dependency_id")
        is_origin_use = bool(
            origin_dependency_use is not None
            and edge.get("use_id") == origin_dependency_use
            and dependent == affected_result
        )
        is_downstream_use = bool(
            dependent in affected_results and dependency in affected_results
        )
        if not is_origin_use and not is_downstream_use:
            continue
        dependent_summary = summaries_by_id.get(str(dependent), {})
        claim = next(
            (
                row
                for row in dependent_summary.get("result_dependency_claims", [])
                if isinstance(row, dict) and row.get("use_id") == edge.get("use_id")
            ),
            {},
        )
        use_projection = ledger_step_projection(
            dependent_summary, claim.get("owner_step")
        )
        components = dependent_summary.get("review_components", {})
        propagation_rows.append(
            [
                str(dependent),
                f"uses {dependency}",
                str(edge.get("use_id")),
                str(edge.get("dependency_conclusion_id") or "none"),
                (
                    f"{use_projection['file']}:"
                    f"{use_projection['start_line']}-{use_projection['end_line']}"
                    if use_projection is not None
                    else "unresolved"
                ),
                str(use_projection.get("sha256")) if use_projection else "none",
                (
                    json.dumps(use_projection["quote"], ensure_ascii=False)
                    if use_projection is not None
                    else "none"
                ),
                json.dumps(components, ensure_ascii=False, sort_keys=True),
            ]
        )

    root_components = summaries_by_id.get(affected_result, {}).get(
        "review_components", {}
    )
    conclusion_results = summaries_by_id.get(affected_result, {}).get(
        "conclusion_results"
    )
    if not isinstance(conclusion_results, list):
        conclusion_results = []
    conclusion_effect = "; ".join(
        f"{row.get('conclusion_id')}:{row.get('statement_status')}/"
        f"{row.get('argument_status')}"
        for row in conclusion_results
        if isinstance(row, dict)
    ) or "none"
    assessment_effect = (
        "blocks no_defect_found"
        if issue.get("status") in {"open", "deferred"}
        and issue.get("load_bearing") is True
        else f"current assessment: {overall_assessment}"
    )
    severity_rows = [
        [
            str(issue.get("severity")),
            str(issue.get("load_bearing")),
            str(issue.get("confidence")),
            str(issue.get("invalidation_kind")),
            json.dumps(root_components, ensure_ascii=False, sort_keys=True),
            conclusion_effect,
            assessment_effect,
        ]
    ]
    change_rows = [
        [
            compact_json_value(change.get("target_ref")),
            str(change.get("action")),
            str(change.get("repair_scope")),
            str(change.get("assumption_cost")),
            (
                str(change.get("claim_cost"))
                if "claim_cost" in change
                else "not_applicable"
            ),
            str(change.get("proposal")),
            str(change.get("verification_status")),
            canonical_id_field(change.get("required_rechecks", [])),
        ]
        for change in suggested_changes
        if isinstance(change, dict)
    ]
    repair_search = issue.get("repair_search")
    repair_search_rows: list[list[str]] | None = None
    repair_search_conclusion: str | None = None
    if isinstance(repair_search, dict):
        strategies = repair_search.get("strategies")
        repair_search_rows = [
            [
                str(strategy.get("name")),
                str(strategy.get("attempt")),
                str(strategy.get("outcome")),
                str(strategy.get("evidence")),
            ]
            for strategy in (strategies if isinstance(strategies, list) else [])
            if isinstance(strategy, dict)
        ]
        repair_search_conclusion = str(repair_search.get("conclusion"))
    current_required_uses = {
        str(edge.get("use_id"))
        for edge in issue_recheck_edges(issue, dependency_edges)
        if is_nonempty_string(edge.get("use_id"))
    }
    historical_origin = issue.get("historical_origin")
    historical_required_uses = (
        {
            item
            for item in historical_origin.get("required_dependency_uses", [])
            if is_nonempty_string(item)
        }
        if isinstance(historical_origin, dict)
        else set()
    )
    required_uses = sorted(current_required_uses | historical_required_uses)
    historical_required_units = (
        {
            item
            for item in historical_origin.get("required_units", [])
            if is_nonempty_string(item)
        }
        if isinstance(historical_origin, dict)
        else set()
    )
    required_units = sorted(affected_results | historical_required_units)
    historical_required_challenges = (
        {
            item
            for item in historical_origin.get("required_challenges", [])
            if is_nonempty_string(item)
        }
        if isinstance(historical_origin, dict)
        else set()
    )
    required_challenges = sorted(
        (set(challenge_units) & set(required_units))
        | historical_required_challenges
    )
    reconciled_challenges = [
        unit_id
        for unit_id in required_challenges
        if (
            summaries_by_id.get(unit_id, {}).get(
                "independent_check", {}
            ).get("status")
            in {"agreed", "resolved"}
            and (
                not (
                    issue.get("severity") in {"S0", "S1"}
                    and issue.get("load_bearing") is True
                )
                or issue_id
                in summaries_by_id.get(unit_id, {}).get(
                    "independent_check", {}
                ).get("covered_issue_ids", [])
            )
        )
    ]
    current_required_deliverables = {
        str(record.get("id"))
        for record in report_deliverables
        if isinstance(record, dict) and is_nonempty_string(record.get("id"))
    }
    historical_required_deliverables = (
        {
            item
            for item in historical_origin.get(
                "required_report_deliverables", []
            )
            if is_nonempty_string(item)
        }
        if isinstance(historical_origin, dict)
        else set()
    )
    required_deliverables = sorted(
        current_required_deliverables | historical_required_deliverables
    )
    raw_rechecked_units = issue.get("rechecked_units")
    rechecked_units = sorted(
        item
        for item in raw_rechecked_units
        if is_nonempty_string(item)
    ) if isinstance(raw_rechecked_units, list) else []
    raw_rechecked_uses = issue.get("rechecked_dependency_uses")
    rechecked_uses = sorted(
        item
        for item in raw_rechecked_uses
        if is_nonempty_string(item)
    ) if isinstance(raw_rechecked_uses, list) else []
    raw_reconciled_deliverables = issue.get("reconciled_deliverables")
    reconciled_deliverables = sorted(
        item
        for item in raw_reconciled_deliverables
        if is_nonempty_string(item)
    ) if isinstance(raw_reconciled_deliverables, list) else []
    closure_complete = (
        issue.get("status") == "resolved"
        and rechecked_units == required_units
        and rechecked_uses == required_uses
        and reconciled_challenges == required_challenges
        and reconciled_deliverables == required_deliverables
    )
    closure_rows = [
        [
            canonical_id_field(required_units),
            canonical_id_field(rechecked_units),
            canonical_id_field(required_uses),
            canonical_id_field(rechecked_uses),
            canonical_id_field(required_challenges),
            canonical_id_field(reconciled_challenges),
            canonical_id_field(required_deliverables),
            canonical_id_field(reconciled_deliverables),
            "complete" if closure_complete else "open",
        ]
    ]
    if isinstance(resolution_archive, dict):
        archived_projection = resolution_archive.get("projection")
        if isinstance(archived_projection, dict):
            if isinstance(archived_projection.get("failure"), list):
                failure_rows = archived_projection["failure"]
    return {
        "failure": failure_rows,
        "contract": contract_rows,
        "propagation": propagation_rows,
        "severity": severity_rows,
        "repair_search": repair_search_rows,
        "repair_search_conclusion": repair_search_conclusion,
        "changes": change_rows,
        "closure": closure_rows,
        "required_closure": {
            "units": required_units,
            "dependency_uses": required_uses,
            "challenges": required_challenges,
            "report_deliverables": required_deliverables,
        },
    }


def render_markdown_table(
    header: list[str], rows: Iterable[Iterable[Any]]
) -> str:
    lines = [
        "| " + " | ".join(escape_markdown(value) for value in header) + " |",
        "|" + "|".join("---" for _ in header) + "|",
    ]
    lines.extend(
        "| " + " | ".join(escape_markdown(value) for value in row) + " |"
        for row in rows
    )
    return "\n".join(lines)


REPAIR_SCOPE_LANGUAGE = {
    "local_step": "localized proof edit; the statement can remain unchanged",
    "unit_statement": (
        "the result statement changes; its downstream uses must be rechecked"
    ),
    "cross_unit": "the repair spans multiple results",
    "global": "the paper-wide argument or claim must be revised",
}
ASSUMPTION_COST_LANGUAGE = {
    "none": "no stronger assumption",
    "tightens_constant": "a tighter numerical condition",
    "adds_regularity_or_moment": "stronger regularity or moment assumptions",
    "changes_regime": "a different asymptotic or probabilistic regime",
    "structural": "a structural assumption change",
}
CLAIM_COST_LANGUAGE = {
    "none": "no additional weakening of the claim",
    "restricts_scope": "the result applies in a narrower setting",
    "weakens_rate": "the stated rate is weakened",
    "loses_uniformity": "uniformity is lost",
    "weakens_mode": "the convergence mode or guarantee is weakened",
}
REPAIR_OUTLOOK_LANGUAGE = {
    "candidate_repair_exists": (
        "A candidate repair is recorded below and still requires the listed "
        "rechecks."
    ),
    "no_local_repair_found": (
        "No local repair was found; a broader claim or assumption revision "
        "may be needed."
    ),
}


def canonical_report_summary_fields(
    assessment: Any,
    summaries_by_id: dict[str, dict[str, Any]],
    in_scope: Iterable[str],
    issues: Iterable[dict[str, Any]],
) -> dict[str, str]:
    judgments: list[tuple[str, dict[str, Any]]] = []
    affected: list[tuple[str, dict[str, Any]]] = []
    for result_id in in_scope:
        for result in summaries_by_id.get(str(result_id), {}).get(
            "conclusion_results", []
        ):
            if not isinstance(result, dict):
                continue
            key = f"{result_id}/{result.get('conclusion_id')}"
            judgments.append((key, result))
            if (
                result.get("contract_fidelity") != "verified"
                or result.get("argument_status") != "valid"
                or result.get("statement_status") != "established"
                or result.get("dependency_closure") != "verified"
                or result.get("use_site_sufficiency")
                not in {"sufficient", "not_applicable"}
            ):
                affected.append((key, result))
    active_issues = sorted(
        (
            issue
            for issue in issues
            if isinstance(issue, dict)
            and issue.get("status") in {"open", "deferred"}
        ),
        key=lambda issue: (
            ISSUE_SEVERITY_RANK.get(str(issue.get("severity")), 99),
            str(issue.get("id", "")),
        ),
    )
    canonical_judgments = {
        "no_defect_found": (
            "No load-bearing defect found under the stated non-formal protocol."
        ),
        "defects_found": "Defects found under the stated non-formal protocol.",
        "inconclusive": "Inconclusive under the stated non-formal protocol.",
    }
    if active_issues:
        lead_issue = active_issues[0]
        lead_text = (
            f"{lead_issue.get('id')}: "
            f"{escape_markdown_heading(lead_issue.get('summary'))}"
        )
        main_reason = (
            lead_text
            if len(active_issues) == 1
            else (
                f"{len(active_issues)} unresolved issues; the highest-priority "
                f"finding is {lead_text}"
            )
        )
    elif affected:
        verb = "has" if len(affected) == 1 else "have"
        main_reason = (
            f"{len(affected)} of {len(judgments)} checked conclusions {verb} "
            "a nonpassing or unresolved judgment."
        )
    else:
        main_reason = (
            "Every in-scope conclusion and recorded dependency use passed its "
            "required closure checks."
        )
    if affected:
        impact_rows = [
            (
                f"{key}: statement {result.get('statement_status')}, argument "
                f"{result.get('argument_status')}, dependencies "
                f"{result.get('dependency_closure')}, later use "
                f"{result.get('use_site_sufficiency')}"
            ).replace("_", " ")
            for key, result in affected
        ]
        verb = "is" if len(affected) == 1 else "are"
        impact = (
            f"{len(affected)} of {len(judgments)} checked conclusions {verb} "
            "affected: " + "; ".join(impact_rows) + "."
        )
    else:
        impact = (
            f"All {len(judgments)} checked conclusions are established with "
            "closed dependencies and sufficient or inapplicable later use."
        )
    if not active_issues:
        repairs = "No current repair is required by the canonical issue log."
    else:
        repair_rows: list[str] = []
        for issue in active_issues:
            raw_changes = issue.get("suggested_changes")
            changes = [
                change
                for change in (
                    raw_changes if isinstance(raw_changes, list) else []
                )
                if isinstance(change, dict)
            ]
            if not changes:
                repair_rows.append(
                    f"{issue.get('id')}: no concrete repair is recorded"
                )
                continue
            first = changes[0]
            option_label = (
                "1 option" if len(changes) == 1 else f"{len(changes)} options"
            )
            repair_rows.append(
                f"{issue.get('id')}: {option_label}; first option: "
                f"{repair_cost_language(first)}; status "
                f"{str(first.get('verification_status')).replace('_', ' ')}; "
                "recheck "
                + canonical_id_field(first.get("required_rechecks", []))
            )
        repairs = "; ".join(repair_rows) + "."
    return {
        "Overall judgment": canonical_judgments.get(
            str(assessment), "Inconclusive under the stated non-formal protocol."
        ),
        "Main reason": main_reason,
        "Impact on paper conclusions/results": impact,
        "Repair options and difficulty": repairs,
    }


def report_failure_anchor(issue: dict[str, Any]) -> str:
    origin = issue.get("origin_ref")
    if not isinstance(origin, dict):
        return "unresolved origin"
    kind = str(origin.get("kind", "origin")).replace("_", " ")
    if origin.get("kind") == "ledger_move":
        return f"{origin.get('step_id')}/{origin.get('move_id')}"
    for field, label in (
        ("use_id", "dependency use"),
        ("interface_id", "interface"),
        ("aspect", "global check"),
        ("pointer", "obligation field"),
    ):
        if is_nonempty_string(origin.get(field)):
            return f"{label} {origin[field]}"
    return kind


def plain_report_diagnostic(value: Any) -> str:
    """Translate canonical structured diagnostics into short report prose."""
    parsed = value
    if isinstance(value, str):
        try:
            parsed = json.loads(value)
        except json.JSONDecodeError:
            return value.replace("\n", " ")
    if not isinstance(parsed, dict):
        return str(parsed).replace("\n", " ")
    if "source_status" in parsed or "applicability_status" in parsed:
        parts = [
            f"dependency source status is {parsed.get('source_status')}",
            f"use-site applicability is {parsed.get('applicability_status')}",
            f"effective dependency status is {parsed.get('effective_status')}",
        ]
        for check in parsed.get("nonpassing_compatibility_checks", []):
            if isinstance(check, dict):
                parts.append(
                    f"{check.get('aspect')} is {check.get('status')}: "
                    f"{check.get('evidence')}"
                )
        for prerequisite in parsed.get("nonpassing_prerequisites", []):
            if isinstance(prerequisite, dict):
                parts.append(
                    f"prerequisite {prerequisite.get('prerequisite')} is "
                    f"{prerequisite.get('status')}"
                )
        return "; ".join(parts) + "."
    if "target_relation" in parsed or "implementation_relation" in parsed:
        target = parsed.get("target_relation")
        implementation = parsed.get("implementation_relation")
        target = target if isinstance(target, dict) else {}
        implementation = implementation if isinstance(implementation, dict) else {}
        return (
            f"target relation is {target.get('verdict')}: "
            f"{target.get('reason')}; implementation inspection is "
            f"{implementation.get('inspection_status')}: "
            f"{implementation.get('reason')}."
        )
    if "aspect" in parsed and "status" in parsed:
        return (
            f"global check {parsed.get('aspect')} is {parsed.get('status')}: "
            f"{parsed.get('evidence')}."
        )
    scalar_parts = [
        f"{str(key).replace('_', ' ')} is {item}"
        for key, item in parsed.items()
        if isinstance(item, (str, int, float, bool)) or item is None
    ]
    return (
        "; ".join(scalar_parts) + "."
        if scalar_parts
        else "The canonical record identifies a structured inconsistency."
    )


def render_results_and_impact(
    summaries_by_id: dict[str, dict[str, Any]],
    in_scope: Iterable[str],
) -> str:
    """Render one answer-oriented row per mathematical conclusion."""
    rows: list[list[str]] = []
    for result_id in in_scope:
        summary = summaries_by_id.get(result_id, {})
        claims = {
            row.get("id"): row.get("claim")
            for row in summary.get("obligation_conclusions", [])
            if isinstance(row, dict)
        }
        source_name = str(summary.get("source_reference") or "unknown")
        source_range = summary.get("source_range") or "unknown"
        for result in summary.get("conclusion_results", []):
            if not isinstance(result, dict):
                continue
            conclusion_id = str(result.get("conclusion_id"))
            claim = claims.get(conclusion_id)
            support = result.get("support")
            support_text = (
                f"{support.get('step_id')}/{support.get('move_id')}"
                if isinstance(support, dict)
                else "unresolved"
            )
            rows.append(
                [
                    result_id,
                    f"{conclusion_id}: {claim}",
                    str(result.get("contract_fidelity")),
                    str(result.get("argument_status")),
                    str(result.get("statement_status")),
                    str(result.get("dependency_closure")),
                    str(result.get("use_site_sufficiency")),
                    f"{source_name}:{source_range}; {support_text}",
                    canonical_id_field(result.get("issue_ids", [])),
                ]
            )
    return render_markdown_table(
        [
            "Result",
            "Conclusion",
            "Contract",
            "Argument",
            "Statement",
            "Dependencies",
            "Later use",
            "Evidence",
            "Issues",
        ],
        rows,
    )


def repair_cost_language(change: dict[str, Any]) -> str:
    parts = [
        REPAIR_SCOPE_LANGUAGE.get(
            str(change.get("repair_scope")),
            str(change.get("repair_scope")),
        ),
        ASSUMPTION_COST_LANGUAGE.get(
            str(change.get("assumption_cost")),
            str(change.get("assumption_cost")),
        ),
    ]
    if "claim_cost" in change:
        parts.append(
            CLAIM_COST_LANGUAGE.get(
                str(change.get("claim_cost")),
                str(change.get("claim_cost")),
            )
        )
    return "; ".join(part for part in parts if part and part != "None")


def issue_result_impact(
    issue: dict[str, Any],
    summaries_by_id: dict[str, dict[str, Any]],
) -> str:
    impacts: list[str] = []
    raw_affected_results = issue.get("affected_results")
    affected_results = (
        raw_affected_results
        if isinstance(raw_affected_results, list)
        else []
    )
    for result_id in affected_results:
        summary = summaries_by_id.get(str(result_id), {})
        conclusions = [
            (
                f"{row.get('conclusion_id')} is "
                f"{row.get('statement_status')} "
                f"(argument {row.get('argument_status')})"
            )
            for row in summary.get("conclusion_results", [])
            if isinstance(row, dict)
        ]
        impacts.append(
            f"{result_id}: "
            + (
                "; ".join(conclusions)
                if conclusions
                else str(summary.get("declared_unit_status", "unknown"))
            )
        )
    return "; ".join(impacts) or "No result-level impact recorded."


def render_findings_and_repairs(
    issues: Iterable[dict[str, Any]],
    summaries_by_id: dict[str, dict[str, Any]],
    dependency_edges: list[dict[str, Any]],
    challenge_units: Iterable[str],
    report_deliverables: list[dict[str, Any]],
    overall_assessment: Any,
    interfaces: dict[str, dict[str, Any]] | None = None,
    global_checks: dict[str, dict[str, Any]] | None = None,
) -> str:
    canonical_issues = sorted(
        (issue for issue in issues if isinstance(issue, dict)),
        key=lambda issue: (
            ISSUE_SEVERITY_RANK.get(str(issue.get("severity")), 99),
            str(issue.get("id", "")),
        ),
    )
    if not canonical_issues:
        return "No issues."
    blocks: list[str] = []
    for issue in canonical_issues:
        projection = canonical_issue_detail_projection(
            issue,
            summaries_by_id,
            dependency_edges,
            challenge_units,
            report_deliverables,
            overall_assessment,
            interfaces=interfaces,
            global_checks=global_checks,
        )
        failures = projection["failure"]
        failure = failures[0] if failures else []
        failure_sites = [
            row[0] for row in failures if isinstance(row, list) and row
        ]
        rule = failure[6] if len(failure) > 6 else "unresolved"
        failure_evidence = plain_report_diagnostic(
            failure[8] if len(failure) > 8 else str(
            issue.get("summary")
            )
        )
        evidence_rows: list[list[str]] = []
        for row in failures:
            quote_value: Any = row[2] if len(row) > 2 else "unavailable"
            try:
                quote_value = json.loads(quote_value)
            except (json.JSONDecodeError, TypeError):
                pass
            evidence_rows.append(
                [
                    str(row[0]) if row else "unresolved",
                    report_failure_anchor(issue),
                    str(quote_value).replace("\n", " "),
                ]
            )
        raw_changes = issue.get("suggested_changes")
        changes = [
            change
            for change in (
                raw_changes if isinstance(raw_changes, list) else []
            )
            if isinstance(change, dict)
        ]
        repair_rows = [
            [
                str(change.get("proposal")),
                repair_cost_language(change),
                str(change.get("verification_status")).replace("_", " "),
                canonical_id_field(change.get("required_rechecks", [])),
            ]
            for change in changes
        ]
        repair_search = issue.get("repair_search")
        repair_outlook = (
            REPAIR_OUTLOOK_LANGUAGE.get(
                str(repair_search.get("conclusion")),
                str(repair_search.get("conclusion")).replace("_", " "),
            )
            if isinstance(repair_search, dict)
            and is_substantive_string(repair_search.get("conclusion"))
            else (
                "The recorded options below require validation."
                if repair_rows
                else "No repair option is currently recorded."
            )
        )
        blocks.extend(
            [
                (
                    f"### {issue.get('id')} [{issue.get('severity')}] "
                    f"{escape_markdown_heading(issue.get('summary'))}"
                ),
                "",
                (
                    f"- Status: {issue.get('status')}; confidence: "
                    f"{issue.get('confidence')}; load-bearing: "
                    f"{str(issue.get('load_bearing')).lower()}."
                ),
                "- Failure site: "
                + ("; ".join(failure_sites) if failure_sites else "unresolved")
                + ".",
                "",
                render_markdown_table(
                    ["Location", "Step or move", "Exact locked quote"],
                    evidence_rows,
                ),
                "",
                f"- Why it fails: {failure_evidence} Rule checked: {rule}.",
                f"- Impact: {issue_result_impact(issue, summaries_by_id)}",
                f"- Repair outlook: {repair_outlook}",
                "",
                (
                    render_markdown_table(
                        [
                            "Repair option",
                            "Scope and scientific cost",
                            "Status",
                            "Required rechecks",
                        ],
                        repair_rows,
                    )
                    if repair_rows
                    else "No concrete repair proposal is recorded."
                ),
            ]
        )
        blocks.append("")
    return "\n".join(blocks).strip()


def render_independent_verification(
    summaries_by_id: dict[str, dict[str, Any]],
    required_challenges: Iterable[str],
) -> str:
    rows: list[list[str]] = []
    for unit_id in required_challenges:
        check = summaries_by_id.get(str(unit_id), {}).get(
            "independent_check", {}
        )
        resolution = check.get("resolution")
        rows.append(
            [
                str(unit_id),
                str(check.get("status")),
                str(check.get("independence_level")),
                str(check.get("challenger_verdict")),
                str(check.get("reconciled_verdict")),
                (
                    str(resolution).replace("\n", " ")
                    if check.get("status") == "resolved"
                    and is_substantive_string(resolution)
                    else "agreed"
                ),
            ]
        )
    return render_markdown_table(
        [
            "Result",
            "Check status",
            "Independence",
            "Challenger verdict",
            "Final verdict",
            "Reconciliation",
        ],
        rows,
    )


def render_declared_deliverables(
    report_deliverables: Iterable[dict[str, Any]],
) -> str:
    rows = [
        [
            str(record.get("id")),
            str(record.get("role")),
            str(record.get("path")),
            canonical_id_field(record.get("issue_ids", [])),
            str(record.get("overall_verdict")),
        ]
        for record in report_deliverables
        if isinstance(record, dict)
    ]
    if not rows:
        return "None."
    return render_markdown_table(
        [
            "Deliverable ID",
            "Role",
            "Path",
            "Issue IDs",
            "Overall verdict",
        ],
        rows,
    )


def replace_report_section_text(text: str, heading: str, body: str) -> str:
    pattern = re.compile(
        rf"^{re.escape(heading)}\s*$\n.*?(?=^##\s|\Z)",
        re.MULTILINE | re.DOTALL,
    )
    matches = list(pattern.finditer(text))
    if len(matches) != 1:
        raise ValueError(
            f"Final report must contain exactly one {heading} section"
        )
    replacement = f"{heading}\n\n{body.strip()}\n\n"
    return pattern.sub(lambda _: replacement, text, count=1)


def replace_report_nested_section_text(
    text: str, heading: str, body: str
) -> str:
    pattern = re.compile(
        rf"^{re.escape(heading)}\s*$\n.*?(?=^###\s|^##\s|\Z)",
        re.MULTILINE | re.DOTALL,
    )
    matches = list(pattern.finditer(text))
    if len(matches) != 1:
        raise ValueError(
            f"Final report must contain exactly one {heading} section"
        )
    trailing = "\n" if matches[0].end() == len(text) else "\n\n"
    replacement = f"{heading}\n\n{body.strip()}{trailing}"
    return pattern.sub(lambda _: replacement, text, count=1)


def replace_report_scalar_text(text: str, label: str, value: str) -> str:
    pattern = re.compile(
        rf"^- {re.escape(label)}:[ \t]*[^\r\n]*$", re.MULTILINE
    )
    matches = list(pattern.finditer(text))
    if len(matches) != 1:
        raise ValueError(
            f"Final report must contain exactly one {label} field"
        )
    return pattern.sub(lambda _: f"- {label}: {value}", text, count=1)



def finalization_target_is_safe(path: Path) -> bool:
    return path_redirect_kind(path) is None and path.parent.resolve() == path.parent


def finalization_record_path(
    manifest: dict[str, Any], root: Path
) -> tuple[Path, list[str]]:
    errors: list[str] = []
    canonical, _ = manifest_canonical_artifact_path(
        manifest,
        root,
        "finalization_record",
        "finalization record",
        errors,
    )
    return canonical, errors


def validate_input_provenance(
    manifest: dict[str, Any], root: Path, errors: list[str], *, final: bool
) -> str:
    """Validate additive input metadata without breaking legacy schema-5 audits."""
    provenance = manifest.get("input_provenance")
    if provenance is None:
        return "latex"
    if not isinstance(provenance, dict):
        errors.append("manifest.input_provenance must be an object")
        return "latex"
    kind = provenance.get("kind")
    if kind not in {"latex", "pdf_transcription"}:
        errors.append("input_provenance.kind must be latex or pdf_transcription")
        kind = "latex"
    authoritative = provenance.get("authoritative_source")
    if not is_nonempty_string(authoritative):
        errors.append("input_provenance.authoritative_source must be a path")
    elif authoritative != manifest.get("paper_file"):
        errors.append("input_provenance.authoritative_source must equal paper_file")
    portable = provenance.get("portable_sources")
    if not isinstance(portable, bool):
        errors.append("input_provenance.portable_sources must be boolean")
        portable = False
    original = provenance.get("original_locations")
    if not isinstance(original, dict) or original.get("authoritative") is not False:
        errors.append(
            "input_provenance.original_locations must be nonauthoritative provenance"
        )
    if portable and is_nonempty_string(authoritative):
        if (
            re.match(r"^(?:[A-Za-z]:[\\/]|\\\\)", authoritative)
            or authoritative.startswith("/")
            or "\\" in authoritative
        ):
            errors.append(
                "Portable authoritative_source must be a relative POSIX path"
            )
        authoritative_path = resolve_stored_path(authoritative, root)
        try:
            authoritative_path.relative_to(root / "audit" / "00_sources")
        except ValueError:
            errors.append(
                "Portable authoritative source must be inside audit/00_sources"
            )
    if kind != "pdf_transcription":
        return kind
    if provenance.get("manual_inventory_required") is not True:
        errors.append("pdf_transcription must require manual inventory")
    publisher = provenance.get("publisher_pdf")
    if not isinstance(publisher, dict):
        errors.append("pdf_transcription requires publisher_pdf provenance")
    else:
        file_value = publisher.get("file")
        digest = publisher.get("sha256")
        size = publisher.get("size_bytes")
        if not is_nonempty_string(file_value):
            errors.append("publisher_pdf.file must be a path")
        else:
            if portable and (
                re.match(r"^(?:[A-Za-z]:[\\/]|\\\\)", file_value)
                or file_value.startswith("/")
                or "\\" in file_value
            ):
                errors.append("Portable publisher_pdf.file must be a relative POSIX path")
            publisher_path = resolve_stored_path(file_value, root)
            if not publisher_path.is_file():
                errors.append(f"Publisher PDF not found: {publisher_path}")
            else:
                if publisher_path.suffix.lower() != ".pdf":
                    errors.append("publisher_pdf.file must name a PDF")
                if digest != sha256_file(publisher_path):
                    errors.append("Publisher PDF drift: SHA-256 does not match")
                if not is_int(size) or size != publisher_path.stat().st_size:
                    errors.append("Publisher PDF size_bytes does not match")
            if portable:
                try:
                    publisher_path.relative_to(root / "audit" / "00_sources")
                except ValueError:
                    errors.append(
                        "Portable publisher PDF must be inside audit/00_sources"
                    )
        if not is_nonempty_string(publisher.get("original_location")):
            errors.append("publisher_pdf.original_location must record provenance")
    visual = provenance.get("visual_review")
    if not isinstance(visual, dict):
        errors.append("pdf_transcription requires visual_review provenance")
    elif final:
        if visual.get("status") != "complete":
            errors.append(
                "pdf_transcription requires visual_review.status complete before finalization"
            )
        reviewed_pages = visual.get("reviewed_pages")
        if (
            not isinstance(reviewed_pages, list)
            or not reviewed_pages
            or not all(is_nonempty_string(item) for item in reviewed_pages)
        ):
            errors.append(
                "pdf_transcription visual_review.reviewed_pages must be a nonempty string list"
            )
        if not is_substantive_string(visual.get("notes")):
            errors.append("pdf_transcription visual_review.notes must be substantive")
        if not is_utc_timestamp(visual.get("completed_utc")):
            errors.append(
                "pdf_transcription visual_review.completed_utc must be a UTC timestamp"
            )
    return kind


def rediscover_portable_source_closure(
    paper: Path,
    recorded_files: Iterable[Path],
    additional_files: Iterable[Path],
    root: Path,
    recorded_warnings: Iterable[str] = (),
) -> tuple[list[Path], list[str]]:
    """Expand bundle-local includes while retaining recorded FLS-only members."""
    recorded = list(dict.fromkeys(path.resolve() for path in recorded_files))
    seeds = list(
        dict.fromkeys(
            [
                *(path.resolve() for path in additional_files),
                *(path for path in recorded if path != paper.resolve()),
            ]
        )
    )
    closure = discover_source_closure(
        paper,
        additional_files=seeds,
        fls_file=None,
        project_root=root / "audit" / "00_sources" / "project",
        warning_path_base=paper.parent,
    )
    files = list(dict.fromkeys([*recorded, *closure["files"]]))
    warnings = sorted(set(recorded_warnings) | set(closure["warnings"]))
    return files, warnings


def annotate_primary_reference_errors(
    errors: list[str], start: int, unit: dict[str, Any],
    summary: dict[str, Any], occurrences: list[dict[str, Any]],
    field: str, identity_field: str,
) -> None:
    """Attach the manuscript location and editable record pointer to a diagnostic."""
    rows = summary.get(field, [])
    for index in range(start, len(errors)):
        message = errors[index]
        row_index = next((i for i, row in enumerate(rows)
                          if isinstance(row, dict)
                          and is_nonempty_string(row.get(identity_field))
                          and re.search(
                              r"(?<![\w:./-])" + re.escape(str(row[identity_field]))
                              + r"(?![\w:./-])", message)), None)
        row = rows[row_index] if row_index is not None else {}
        occurrence = next((item for item in occurrences
                           if (identity_field == "occurrence_id"
                               and item.get("occurrence_id") == row.get(identity_field))
                           or (identity_field == "candidate_id"
                               and item.get("owner_unit_id") == row.get(identity_field))), {})
        location = occurrence or unit.get("statement") or {}
        file_name = location.get("file", "source")
        line = location.get("line", location.get("start_line", "?"))
        pointer = f"/review/{field}"
        if row_index is not None:
            pointer += f"/{row_index}"
        errors[index] = f"{message} [{file_name}:{line}; {pointer}]"


def validate_primary_reference_roles(
    unit_id: str, unit: dict[str, Any], summary: dict[str, Any],
    reviewed_occurrences: list[dict[str, Any]],
    unit_inventory: dict[str, dict[str, Any]], paper_base: Path,
    errors: list[str],
) -> None:
    """Reconcile primary occurrence roles without independent-review evidence."""
    first_error = len(errors)
    proof_location = unit.get("proof")
    direct_by_use = {
        record.get("use_id"): record
        for record in summary.get("direct_dependencies", [])
        if isinstance(record, dict)
        and is_nonempty_string(record.get("use_id"))
    }
    dispositions_by_occurrence = {
        record.get("occurrence_id"): record
        for record in summary.get("source_reference_dispositions", [])
        if isinstance(record, dict)
        and is_nonempty_string(record.get("occurrence_id"))
    }
    source_occurrences = {
        record.get("occurrence_id"): record
        for record in reviewed_occurrences
        if isinstance(record, dict)
        and is_nonempty_string(record.get("occurrence_id"))
    }
    step_result_claims = {
        claim.get("use_id"): claim
        for claim in summary.get("result_dependency_claims", [])
        if isinstance(claim, dict)
        and is_nonempty_string(claim.get("use_id"))
    }
    missing_dispositions = set(source_occurrences) - set(
        dispositions_by_occurrence
    )
    if missing_dispositions:
        errors.append(
            f"{unit_id}: source occurrences lack reviewed dispositions: "
            + ", ".join(sorted(missing_dispositions))
        )
    stale_dispositions = set(dispositions_by_occurrence) - set(
        source_occurrences
    )
    if stale_dispositions:
        errors.append(
            f"{unit_id}: source-reference dispositions are not present in "
            "the reviewed statement or proof: "
            + ", ".join(sorted(stale_dispositions))
        )
    proof_path: Path | None = None
    proof_start = proof_end = proof_last_line = 0
    if isinstance(proof_location, dict):
        try:
            proof_path = resolve_stored_path(
                str(proof_location["file"]), paper_base
            )
            proof_start = proof_location["start_line"]
            proof_end = proof_location["end_line"]
            if is_int(proof_start) and is_int(proof_end):
                proof_last_line = last_substantive_line(
                    proof_path, proof_start, proof_end
                )
                expanded_proof = source_fragment_support().expand(report_api(), proof_path, proof_start, proof_end, paper_base)
                if expanded_proof["has_inclusion"]:
                    proof_last_line = expanded_last_substantive_position(expanded_proof)
        except (KeyError, TypeError, ValueError, OSError, UnicodeError):
            proof_path = None
    for occurrence_id, disposition in dispositions_by_occurrence.items():
        occurrence = source_occurrences.get(occurrence_id)
        if occurrence is None:
            continue
        if (
            disposition.get("target") != occurrence.get("target")
            or disposition.get("command") != occurrence.get("command")
        ):
            errors.append(
                f"{unit_id}: disposition {occurrence_id} does not match the "
                "canonical occurrence target and command"
            )
        role = disposition.get("disposition")
        target = occurrence.get("target")
        owner_status = occurrence.get("resolution_status")
        owner_unit_id = occurrence.get("owner_unit_id")
        owner_region = occurrence.get("owner_region")
        if role == "internal_result":
            use_id = disposition.get("dependency_use_id")
            dependency = direct_by_use.get(use_id)
            claim = step_result_claims.get(use_id)
            foreign_owner = unit_inventory.get(str(owner_unit_id), {})
            if (
                owner_status != "unique"
                or not is_nonempty_string(owner_unit_id)
                or owner_unit_id == unit_id
                or (
                    foreign_owner.get("proof_required") is False
                    and (foreign_owner.get("semantic_kind") or foreign_owner.get("environment"))
                    in OBLIGATION_CONTEXT_ENVIRONMENTS
                )
            ):
                errors.append(
                    f"{unit_id}: occurrence {occurrence_id} cannot be an "
                    "internal result because it has no unique other-unit owner"
                )
            if (
                dependency is None
                or dependency.get("kind") != "internal_result"
                or dependency.get("id") != owner_unit_id
            ):
                errors.append(
                    f"{unit_id}: occurrence {occurrence_id} does not resolve "
                    "through its exact dependency use to the label owner"
                )
            if (
                claim is None
                or claim.get("kind") != "internal_result"
                or claim.get("id") != owner_unit_id
            ):
                errors.append(
                    f"{unit_id}: occurrence {occurrence_id} is not mapped to "
                    "an exact proof-step dependency use"
                )
        elif role == "local_step":
            if owner_status != "unique" or owner_unit_id != unit_id:
                errors.append(
                    f"{unit_id}: local-step occurrence {occurrence_id} must "
                    "resolve to a label owned by the same unit"
                )
        elif role == "obligation_context":
            if owner_status == "unique":
                foreign_owner = unit_inventory.get(str(owner_unit_id), {})
                owned_statement = (
                    owner_unit_id == unit_id
                    and owner_region == "statement"
                )
                reviewed_foreign_context = (
                    owner_unit_id != unit_id
                    and foreign_owner.get("proof_required") is False
                    and (foreign_owner.get("semantic_kind") or foreign_owner.get("environment"))
                    in OBLIGATION_CONTEXT_ENVIRONMENTS
                    and owner_region == "statement"
                )
                if not owned_statement and not reviewed_foreign_context:
                    errors.append(
                        f"{unit_id}: obligation occurrence {occurrence_id} "
                        "must name this result's statement or a reviewed "
                        "foreign non-proof unit"
                    )
        elif role == "own_result_identification":
            closing_occurrence = bool(
                occurrence.get("structural_context") == "proof_header"
                or (
                    proof_path is not None
                    and is_int(occurrence.get("source_position", occurrence.get("line")))
                    and occurrence.get("source_position", occurrence.get("line")) >= max(
                        proof_start, proof_last_line - 2
                    )
                )
            )
            if (
                owner_status != "unique"
                or owner_unit_id != unit_id
                or target != unit_id
                or not closing_occurrence
            ):
                errors.append(
                    f"{unit_id}: own-result occurrence {occurrence_id} is "
                    "not a proof header or reviewed closing identification"
                )
        elif role == "navigation":
            if occurrence.get("command") != "hyperref":
                errors.append(
                    f"{unit_id}: navigation occurrence {occurrence_id} must "
                    "use an explicit hyperref command"
                )
        elif role == "non_load_bearing":
            if (
                owner_status == "unique"
                and owner_unit_id == unit_id
                and target == unit_id
                and occurrence.get("structural_context") != "proof_header"
                and (
                    not is_int(occurrence.get("source_position", occurrence.get("line")))
                    or occurrence.get("source_position", occurrence.get("line")) < max(
                        proof_start, proof_last_line - 2
                    )
                )
            ):
                errors.append(
                    f"{unit_id}: a mid-proof self-reference "
                    f"{occurrence_id} cannot be hidden as non-load-bearing"
                )
        if (
            role == "unresolved"
            and summary.get("declared_unit_status") == "verified"
        ):
            errors.append(
                f"{unit_id}: verified unit has unresolved source occurrence "
                f"{occurrence_id}"
            )
        if (
            owner_status
            in {"missing", "duplicate", "ambiguous", "dynamic", "unowned"}
            and role not in {"unresolved", "navigation", "non_load_bearing"}
            and not (
                owner_status == "unowned"
                and role == "obligation_context"
            )
        ):
            errors.append(
                f"{unit_id}: unresolved occurrence {occurrence_id} cannot "
                f"serve the premise-bearing role {role}"
            )

    annotate_primary_reference_errors(
        errors, first_error, unit, summary, reviewed_occurrences,
        "source_reference_dispositions", "occurrence_id",
    )


def validate_primary_candidate_references(
    root: Path, inventory: dict[str, Any], unit_id: str,
    unit: dict[str, Any], summary: dict[str, Any],
    unit_inventory: dict[str, dict[str, Any]], paper_base: Path,
    reviewed_occurrences: list[dict[str, Any]],
    candidate_source_members: list[tuple[Path, dict[str, Any]]],
    internal_uses: list[dict[str, Any]], errors: list[str], *,
    candidate_paths: list[dict[str, Any]] | None = None,
) -> None:
    """Apply the same exact candidate/use reconciliation at handoff and release."""
    first_error = len(errors)
    internal_edge_by_pair = {
        (
            str(edge.get("dependent_unit")),
            str(edge.get("dependency_id")),
        ): edge
        for edge in internal_uses
        if isinstance(edge, dict)
        and edge.get("kind", "internal_result") == "internal_result"
        and is_nonempty_string(edge.get("dependent_unit"))
        and is_nonempty_string(edge.get("dependency_id"))
    }
    candidate_ids = {
        str(value)
        for value in unit.get("candidate_internal_dependencies", [])
        if is_nonempty_string(value)
    }
    disposition_rows = summary.get(
        "candidate_dependency_dispositions", []
    )
    dispositions_by_id = {
        str(row.get("candidate_id")): row
        for row in disposition_rows
        if isinstance(row, dict)
        and is_nonempty_string(row.get("candidate_id"))
    }
    if set(dispositions_by_id) != candidate_ids:
        missing = sorted(candidate_ids - set(dispositions_by_id))
        stale = sorted(set(dispositions_by_id) - candidate_ids)
        if missing:
            errors.append(
                f"{unit_id}: candidate dependency dispositions are missing "
                + ", ".join(missing)
            )
        if stale:
            errors.append(
                f"{unit_id}: candidate dependency dispositions are stale "
                + ", ".join(stale)
            )
    if not candidate_ids or (not candidate_source_members and candidate_paths is None):
        annotate_primary_reference_errors(
            errors, first_error, unit, summary, reviewed_occurrences,
            "candidate_dependency_dispositions", "candidate_id",
        )
        return
    if candidate_paths is None:
        try:
            candidate_paths = packet_candidate_dependency_paths(
                inventory,
                unit,
                paper_base,
                root,
                candidate_source_members,
                reviewed_occurrences,
            )
        except (OSError, UnicodeError, ValueError) as exc:
            errors.append(
                f"{unit_id}: cannot reconstruct dependency-candidate paths: {exc}"
            )
            annotate_primary_reference_errors(
                errors, first_error, unit, summary, reviewed_occurrences,
                "candidate_dependency_dispositions", "candidate_id",
            )
            return
    path_ids_by_candidate: dict[str, list[str]] = defaultdict(list)
    paths_by_id: dict[str, dict[str, Any]] = {}
    for path in candidate_paths:
        if (
            isinstance(path, dict)
            and is_nonempty_string(path.get("candidate_id"))
            and is_nonempty_string(path.get("path_id"))
        ):
            path_ids_by_candidate[str(path["candidate_id"])].append(
                str(path["path_id"])
            )
            paths_by_id[str(path["path_id"])] = path
    for candidate_id in sorted(candidate_ids):
        disposition = dispositions_by_id.get(candidate_id)
        if not isinstance(disposition, dict):
            continue
        expected_paths = sorted(
            path_ids_by_candidate.get(candidate_id, [])
        )
        if (
            not expected_paths
            or sorted(disposition.get("path_ids", [])) != expected_paths
        ):
            errors.append(
                f"{unit_id}: candidate {candidate_id} path_ids disagree "
                "with canonical parser provenance"
            )
        edge = internal_edge_by_pair.get((unit_id, candidate_id))
        if edge is not None:
            dependency_unit = unit_inventory.get(candidate_id, {})
            if (
                disposition.get("disposition") != "internal_result"
                or disposition.get("dependency_use_id")
                != edge.get("use_id")
                or (
                    dependency_unit.get("proof_required") is False
                    and (dependency_unit.get("semantic_kind") or dependency_unit.get("environment"))
                    in OBLIGATION_CONTEXT_ENVIRONMENTS
                )
            ):
                errors.append(
                    f"{unit_id}: candidate {candidate_id} must map to its "
                    "exact registry dependency use"
                )
        elif disposition.get("disposition") == "obligation_context":
            for path_id in expected_paths:
                path = paths_by_id.get(path_id, {})
                chain = path.get("reference_chain")
                root_occurrence = (
                    chain[0]
                    if isinstance(chain, list)
                    and chain
                    and isinstance(chain[0], dict)
                    else {}
                )
                root_disposition = summary.get(
                    "source_reference_dispositions", []
                )
                root_disposition = next(
                    (
                        row
                        for row in root_disposition
                        if isinstance(row, dict)
                        and row.get("occurrence_id")
                        == root_occurrence.get("occurrence_id")
                    ),
                    None,
                )
                if (
                    root_occurrence.get("owner_unit_id") != candidate_id
                    or root_occurrence.get("owner_proof_required") is not False
                    or root_occurrence.get("owner_environment")
                    not in OBLIGATION_CONTEXT_ENVIRONMENTS
                    or root_occurrence.get("owner_region") != "statement"
                    or not isinstance(root_disposition, dict)
                    or root_disposition.get("disposition")
                    != "obligation_context"
                ):
                    errors.append(
                        f"{unit_id}: candidate {candidate_id} must bind "
                        "directly to its exact formal-context occurrence"
                    )
        elif disposition.get("disposition") not in {
            "navigation",
            "non_load_bearing",
        }:
            errors.append(
                f"{unit_id}: unmapped foreign candidate {candidate_id} "
                "must be obligation_context, navigation, or "
                "non_load_bearing"
            )
    annotate_primary_reference_errors(
        errors, first_error, unit, summary, reviewed_occurrences,
        "candidate_dependency_dispositions", "candidate_id",
    )


def primary_reference_readiness_errors(
    root: Path, manifest: dict[str, Any], inventory: dict[str, Any],
    summaries_by_id: dict[str, dict[str, Any]],
    internal_uses: list[dict[str, Any]], in_scope: list[str],
) -> list[str]:
    """Inspect primary reference meaning; completion and challenges are not inputs."""
    errors: list[str] = []
    paper = resolve_stored_path(str(manifest.get("paper_file", "")), root)
    units = {unit["id"]: unit for unit in inventory.get("units", [])
             if isinstance(unit, dict) and is_nonempty_string(unit.get("id"))}
    owners = inventory.get("label_owners") or {}
    try:
        members = packet_source_members(root, manifest)
    except (OSError, UnicodeError, ValueError) as exc:
        errors.append(f"Cannot reconstruct dependency-candidate provenance: {exc}")
        members = []
    for unit_id in sorted(set(in_scope) & set(units) & set(summaries_by_id)):
        unit, summary = units[unit_id], summaries_by_id[unit_id]
        try:
            occurrences = reviewed_unit_reference_occurrences(unit, paper.parent, owners)
            validate_primary_reference_roles(
                unit_id, unit, summary, occurrences, units, paper.parent, errors,
            )
            validate_primary_candidate_references(
                root, inventory, unit_id, unit, summary, units, paper.parent,
                occurrences, members, internal_uses, errors,
            )
        except (OSError, UnicodeError, ValueError) as exc:
            errors.append(f"{unit_id}: cannot reconstruct primary references: {exc}")
    return errors


def _check_audit_finalization(
    root: Path, *, progress_override: dict[str, Any] | None = None,
    check_reports: bool = True,
    manifest_override: dict[str, Any] | None = None,
    report_outputs_override: dict[str, str] | None = None,
    source_inventory_only: bool = False,
) -> tuple[list[str], dict[str, Any]]:
    root = root.resolve()
    errors: list[str] = []
    manifest_path, manifest, manifest_errors = load_audit_manifest(root)
    errors.extend(manifest_errors)
    if manifest_errors:
        return errors, {"audit_root": str(root), "errors": len(errors)}
    if manifest_override is not None:
        manifest = manifest_override
    if "report_contract" in manifest and not uses_html_report(manifest):
        errors.append("Unsupported report_contract; explicit migration is required")
    errors.extend(audit_internal_redirect_errors(root))
    errors.extend(checker_calibration_errors(root))
    if manifest.get("schema_version") != SCHEMA_VERSION:
        errors.append("AUDIT_MANIFEST.json has an unsupported schema_version")
    protocol = manifest.get("protocol")
    if not isinstance(protocol, dict):
        errors.append("AUDIT_MANIFEST.json protocol must be an object")
        protocol = {}
    expected_protocol = protocol_identity()
    try:
        challenge_contract_version(manifest)
    except ValueError as exc:
        errors.append(str(exc))
    for field, expected in expected_protocol.items():
        if protocol.get(field) != expected:
            errors.append(
                f"protocol.{field} does not match the validator in use"
            )
    inventory_path, inventory_path_valid = manifest_canonical_artifact_path(
        manifest,
        root,
        "inventory_file",
        "proof-unit inventory",
        errors,
    )
    registry_path, registry_path_valid = manifest_canonical_artifact_path(
        manifest,
        root,
        "dependency_registry",
        "dependency registry",
        errors,
    )
    interface_registry_path, interface_registry_path_valid = (
        manifest_canonical_artifact_path(
            manifest,
            root,
            "method_interface_registry",
            "method-interface registry",
            errors,
        )
    )
    input_kind = validate_input_provenance(manifest, root, errors, final=True)
    _, finalization_path_errors = finalization_record_path(manifest, root)
    errors.extend(finalization_path_errors)

    paper_value = manifest.get("paper_file")
    paper = (
        resolve_stored_path(paper_value, root)
        if is_nonempty_string(paper_value)
        else root / "__missing_paper__"
    )
    if not paper.is_file():
        errors.append(f"Paper source not found: {paper}")

    snapshot = manifest.get("source_snapshot")
    recorded_files: dict[Path, str] = {}
    recorded_snapshot_rows: list[dict[str, str]] = []
    if not isinstance(snapshot, dict) or not isinstance(snapshot.get("files"), list):
        errors.append("Manifest source_snapshot.files must be a list")
    else:
        for index, record in enumerate(snapshot["files"], 1):
            prefix = f"source_snapshot.files[{index}]"
            if not isinstance(record, dict):
                errors.append(f"{prefix} must be an object")
                continue
            file_value = record.get("file")
            digest = record.get("sha256")
            if not is_nonempty_string(file_value) or not is_nonempty_string(digest):
                errors.append(f"{prefix} needs nonempty file and sha256 values")
                continue
            path = resolve_stored_path(file_value, root)
            if path in recorded_files:
                errors.append(f"Duplicate source snapshot entry: {path}")
            recorded_files[path] = digest
            recorded_snapshot_rows.append({"file": file_value, "sha256": digest})
        snapshot_id = snapshot.get("sha256")
        expected_snapshot_id = canonical_sha256(recorded_snapshot_rows)
        if not is_nonempty_string(snapshot_id) or snapshot_id != expected_snapshot_id:
            errors.append("Manifest source_snapshot.sha256 is missing or inconsistent")

    provenance = manifest.get("input_provenance")
    portable_fixed = bool(
        isinstance(provenance, dict) and provenance.get("portable_sources") is True
    )
    discovery_record = manifest.get("source_discovery")
    recorded_warnings: list[str] = []
    if portable_fixed:
        if not isinstance(discovery_record, dict) or discovery_record.get(
            "portable_fixed_closure"
        ) is not True:
            errors.append(
                "Portable audit requires source_discovery.portable_fixed_closure"
            )
        warning_value = (
            discovery_record.get("recorded_warnings", [])
            if isinstance(discovery_record, dict)
            else []
        )
        if not isinstance(warning_value, list) or not all(
            isinstance(item, str) for item in warning_value
        ):
            errors.append("source_discovery.recorded_warnings must be a string list")
        else:
            recorded_warnings = warning_value
        for source_path in recorded_files:
            try:
                source_path.relative_to(root / "audit" / "00_sources")
            except ValueError:
                errors.append(
                    "Portable source snapshot contains a file outside audit/00_sources: "
                    + str(source_path)
                )
    current_files: list[Path] = []
    current_warnings: list[str] = []
    fresh_inventory: dict[str, Any] = {"units": [], "warnings": []}
    fresh_cross_references: dict[str, Any] = {"warnings": []}
    additional_files, fls_path, discovered_project_root, recorded_outside = (
        parse_manifest_source_discovery(manifest, root, errors)
    )
    if paper.is_file() and portable_fixed and input_kind == "latex":
        current_files, current_warnings = rediscover_portable_source_closure(
            paper,
            recorded_files,
            additional_files,
            root,
            recorded_warnings,
        )
        fresh_inventory = scan_formal_units(
            paper,
            source_files=current_files,
            source_warnings=current_warnings,
            path_identity_base=paper.parent,
        )
        fresh_cross_references = scan_cross_references(
            paper,
            source_files=current_files,
            source_warnings=current_warnings,
            path_identity_base=paper.parent,
        )
    elif paper.is_file() and portable_fixed:
        current_files = list(recorded_files)
        current_warnings = recorded_warnings
        fresh_inventory = scan_formal_units(
            paper,
            source_files=current_files,
            source_warnings=current_warnings,
            path_identity_base=paper.parent,
        )
        fresh_cross_references = scan_cross_references(
            paper,
            source_files=current_files,
            source_warnings=current_warnings,
            path_identity_base=paper.parent,
        )
    elif paper.is_file():
        closure = discover_source_closure(
            paper,
            additional_files=additional_files,
            fls_file=fls_path,
            project_root=discovered_project_root or paper.parent,
        )
        current_files = closure["files"]
        current_warnings = closure["warnings"]
        if closure["outside_project_inputs"] != recorded_outside:
            errors.append(
                "source_discovery.fls.outside_project_inputs does not match "
                "the current recorder trace"
            )
        fresh_inventory = scan_formal_units(
            paper,
            source_files=current_files,
            source_warnings=current_warnings,
        )
        fresh_cross_references = scan_cross_references(
            paper,
            source_files=current_files,
            source_warnings=current_warnings,
        )
    if set(recorded_files) != set(current_files):
        missing = sorted(str(path) for path in set(current_files) - set(recorded_files))
        stale = sorted(str(path) for path in set(recorded_files) - set(current_files))
        if missing:
            errors.append("Source closure has new or unrecorded files: " + ", ".join(missing))
        if stale:
            errors.append("Source closure no longer contains: " + ", ".join(stale))
    for path, digest in recorded_files.items():
        if not path.is_file():
            errors.append(f"Snapshotted source file not found: {path}")
        elif sha256_file(path) != digest:
            errors.append(f"Source drift in included file: {path}")

    crossref_json_path, crossref_json_path_valid = canonical_artifact_path(
        root,
        "audit/01_index/cross_reference_audit.json",
        "cross-reference audit JSON",
        errors,
    )
    stored_cross_references, crossref_read_errors = (
        load_json_object(crossref_json_path, "cross_reference_audit.json")
        if crossref_json_path_valid
        else ({}, [])
    )
    errors.extend(crossref_read_errors)
    if crossref_read_errors:
        errors.append("Cannot read canonical cross-reference audit; " + crossref_refresh_hint(root))
    if (
        crossref_json_path_valid
        and not crossref_read_errors
        and stored_cross_references != fresh_cross_references
    ):
        errors.append(
            "cross_reference_audit.json is stale or disagrees with the fresh scan; "
            + crossref_refresh_hint(root)
        )
    crossref_markdown_path, crossref_markdown_path_valid = canonical_artifact_path(
        root,
        "audit/01_index/cross_reference_audit.md",
        "cross-reference audit Markdown",
        errors,
    )
    if crossref_markdown_path_valid and not crossref_markdown_path.is_file():
        errors.append(
            f"cross_reference_audit.md not found: {crossref_markdown_path}; "
            + crossref_refresh_hint(root)
        )
    elif (
        crossref_markdown_path_valid
        and paper.is_file()
        and read_text(crossref_markdown_path)
        != crossref_markdown(fresh_cross_references)
    ):
        errors.append(
            "cross_reference_audit.md is stale or disagrees with the fresh scan; "
            + crossref_refresh_hint(root)
        )

    inventory, inventory_errors = (
        load_json_object(inventory_path, "proof-unit inventory")
        if inventory_path_valid
        else ({}, [])
    )
    errors.extend(inventory_errors)
    units = inventory.get("units", []) if not inventory_errors else []
    if not isinstance(units, list):
        errors.append("Proof-unit inventory must contain a units list")
        units = []
    if input_kind == "pdf_transcription" and not units:
        errors.append(
            "pdf_transcription requires a nonempty manually reviewed theorem/proof inventory"
        )
    unit_inventory: dict[str, dict[str, Any]] = {}
    for index, unit in enumerate(units, 1):
        if not isinstance(unit, dict) or not is_nonempty_string(unit.get("id")):
            errors.append(f"Inventory unit {index} has no valid id")
            continue
        unit_id = unit["id"]
        if not isinstance(unit.get("proof_required"), bool):
            errors.append(f"Inventory unit {unit_id} must declare proof_required")
        if unit_id in unit_inventory:
            errors.append(f"Duplicate inventory unit id: {unit_id}")
        unit_inventory[unit_id] = unit
    fresh_units_by_id = {
        unit.get("id"): unit
        for unit in fresh_inventory.get("units", [])
        if isinstance(unit, dict) and is_nonempty_string(unit.get("id"))
    }
    fresh_unit_ids = set(fresh_units_by_id)
    required_inventory_overrides: set[tuple[str, str]] = {
        (unit_id, "manual_unit") for unit_id in set(unit_inventory) - fresh_unit_ids
    }
    missing_discovered_units = fresh_unit_ids - set(unit_inventory)
    if missing_discovered_units:
        errors.append(
            "Reviewed inventory omits parser-discovered units: "
            + ", ".join(sorted(missing_discovered_units))
        )
    for unit_id in sorted(fresh_unit_ids & set(unit_inventory)):
        fresh_unit = fresh_units_by_id[unit_id]
        reviewed_unit = unit_inventory[unit_id]
        for field in ("environment", "label", "environment_declaration", "statement_title", "restatable", "restatements"):
            if reviewed_unit.get(field) != fresh_unit.get(field):
                errors.append(
                    f"Reviewed inventory changes parser-discovered {field} for {unit_id}"
                )
        if any(reviewed_unit.get(field) != fresh_unit.get(field) for field in ("proof_required", "semantic_kind")):
            required_inventory_overrides.add((unit_id, "environment_classification"))
        if canonical_location(reviewed_unit.get("statement")) != canonical_location(
            fresh_unit.get("statement")
        ):
            errors.append(
                f"Reviewed inventory changes parser-discovered statement for {unit_id}"
            )
        proof_changed = canonical_location(
            reviewed_unit.get("proof")
        ) != canonical_location(fresh_unit.get("proof"))
        if proof_changed:
            required_inventory_overrides.add((unit_id, "proof_location"))
            if reviewed_unit.get("proof_redirects") not in (None, []):
                errors.append(
                    f"{unit_id}: a replaced or rejected proof cannot retain "
                    "parser redirect spans"
                )
        elif reviewed_unit.get("proof_redirects") != fresh_unit.get(
            "proof_redirects"
        ):
            errors.append(
                f"{unit_id}: reviewed proof_redirects disagree with the parser"
            )
        fresh_association = fresh_unit.get("proof_association")
        reviewed_association = reviewed_unit.get("proof_association")
        if (
            proof_changed
            or (
                isinstance(fresh_association, dict)
                and fresh_association.get("status") == "review_required"
            )
            or reviewed_association != fresh_association
        ):
            required_inventory_overrides.add((unit_id, "proof_association"))

    scope = manifest.get("audit_scope")
    if not isinstance(scope, dict):
        errors.append("audit_scope must be a reviewed object")
        scope = {}
    if scope.get("status") != "reviewed":
        errors.append("audit_scope.status must be reviewed")
    if not is_enum_value(scope.get("depth"), {"focused", "full"}):
        errors.append("audit_scope.depth must be focused or full")
    assessment = scope.get("overall_assessment")
    if not is_enum_value(
        assessment, {"no_defect_found", "defects_found", "inconclusive"}
    ):
        errors.append("audit_scope.overall_assessment is not set")
    in_scope = validate_string_list(
        scope.get("in_scope_units"), "audit_scope.in_scope_units", errors
    )
    if len(set(in_scope)) != len(in_scope):
        errors.append("audit_scope.in_scope_units contains duplicates")
    target_units = validate_string_list(
        scope.get("target_units"), "audit_scope.target_units", errors
    )
    if not target_units:
        errors.append("audit_scope.target_units must name at least one result")
    if len(set(target_units)) != len(target_units):
        errors.append("audit_scope.target_units contains duplicates")
    if not set(target_units).issubset(in_scope):
        errors.append("Every target unit must also be in scope")
    critical = validate_string_list(
        scope.get("critical_units", []), "audit_scope.critical_units", errors,
        allow_empty=True,
    )
    if len(set(critical)) != len(critical):
        errors.append("audit_scope.critical_units contains duplicates")
    if not set(critical).issubset(in_scope):
        errors.append("Every critical unit must also be in scope")
    if "verified_challenge_sample_rate" in scope:
        errors.append(
            "audit_scope.verified_challenge_sample_rate is obsolete; remove "
            "the field because every in-scope unit now requires an independent check"
        )
    in_scope_interfaces = validate_string_list(
        scope.get("in_scope_interfaces"),
        "audit_scope.in_scope_interfaces",
        errors,
        allow_empty=True,
    )
    if len(set(in_scope_interfaces)) != len(in_scope_interfaces):
        errors.append("audit_scope.in_scope_interfaces contains duplicates")
    validate_string_list(
        scope.get("source_or_parser_limits"),
        "audit_scope.source_or_parser_limits",
        errors,
        allow_empty=True,
    )
    overrides = scope.get("inventory_overrides")
    override_keys: set[tuple[str, str]] = set()
    external_restatements: dict[str, str] = {}
    if not isinstance(overrides, list):
        errors.append("audit_scope.inventory_overrides must be a list")
        overrides = []
    for index, override in enumerate(overrides, 1):
        prefix = f"audit_scope.inventory_overrides[{index}]"
        if not isinstance(override, dict):
            errors.append(f"{prefix} must be an object")
            continue
        unit_id = override.get("unit_id")
        kind = override.get("kind")
        if not is_nonempty_string(unit_id) or not is_enum_value(
            kind,
            {
                "manual_unit",
                "proof_location",
                "proof_association",
                "external_restatement",
                "environment_classification",
            },
        ):
            errors.append(f"{prefix} needs a valid unit_id and kind")
            continue
        key = (unit_id, kind)
        if key in override_keys:
            errors.append(f"Duplicate inventory override: {unit_id}/{kind}")
        override_keys.add(key)
        for field in ("reason", "evidence"):
            if not is_substantive_string(override.get(field)):
                errors.append(
                    f"{prefix}.{field} must be nonempty and substantive"
                )
        fresh_unit = fresh_units_by_id.get(str(unit_id))
        reviewed_unit = unit_inventory.get(str(unit_id))
        if kind == "environment_classification":
            if fresh_unit is None or reviewed_unit is None:
                errors.append(f"{prefix}: environment_classification requires a parser-discovered unit")
                continue
            if fresh_unit.get("semantic_kind") is not None:
                errors.append(f"{prefix}: an explicit declared theorem role cannot be reclassified")
            for field in ("proof_required", "semantic_kind"):
                if override.get("parser_" + field) != fresh_unit.get(field):
                    errors.append(f"{prefix}.parser_{field} is stale")
                if override.get("reviewed_" + field) != reviewed_unit.get(field):
                    errors.append(f"{prefix}.reviewed_{field} is stale")
            reviewed_kind = reviewed_unit.get("semantic_kind")
            if not is_enum_value(reviewed_kind, FORMAL_ENVIRONMENTS) or reviewed_unit.get("proof_required") != (reviewed_kind not in NON_PROOF_ENVIRONMENTS):
                errors.append(f"{prefix}: reviewed semantic_kind and proof_required must agree")
            statement = reviewed_unit.get("statement", {})
            try:
                statement_path = resolve_stored_path(statement["file"], paper.parent)
                digest = source_span_sha256(statement_path, statement["start_line"], statement["end_line"])
            except (KeyError, TypeError, OSError, UnicodeError, ValueError):
                errors.append(f"{prefix}: classification statement cannot be source-locked")
            else:
                if override.get("statement_sha256") != digest:
                    errors.append(f"{prefix}.statement_sha256 is stale")
            if override.get("environment_declaration") != fresh_unit.get("environment_declaration"):
                errors.append(f"{prefix}.environment_declaration must match its source-bound declaration")
        elif kind == "manual_unit":
            if fresh_unit is not None or reviewed_unit is None:
                errors.append(
                    f"{prefix}: manual_unit must bind one parser-omitted reviewed unit"
                )
            elif override.get("reviewed_unit_sha256") != canonical_sha256(
                reviewed_unit
            ):
                errors.append(f"{prefix}.reviewed_unit_sha256 is stale")
            elif isinstance(reviewed_unit.get("proof"), dict):
                manual_proof = reviewed_unit["proof"]
                try:
                    manual_path = resolve_stored_path(
                        str(manual_proof["file"]), paper.parent
                    )
                    manual_start = manual_proof["start_line"]
                    manual_end = manual_proof["end_line"]
                except (KeyError, TypeError, ValueError):
                    errors.append(f"{prefix}: manual proof range is invalid")
                else:
                    try:
                        safe_manual_boundary = bool(
                            is_int(manual_start)
                            and is_int(manual_end)
                            and manual_path.is_file()
                            and proof_span_has_safe_boundary(
                                manual_path,
                                manual_start,
                                manual_end,
                                target_unit_id=str(unit_id),
                                source_files=current_files,
                            )
                        )
                    except (OSError, UnicodeError, ValueError):
                        safe_manual_boundary = False
                    if not safe_manual_boundary:
                        errors.append(
                            f"{prefix}: manual proof must equal a complete proof "
                            "environment or bounded proof region"
                        )
        elif kind == "proof_location":
            if fresh_unit is None or reviewed_unit is None:
                errors.append(
                    f"{prefix}: proof_location requires a parser-discovered unit"
                )
                continue
            parser_proof = canonical_location(fresh_unit.get("proof"))
            reviewed_proof = canonical_location(reviewed_unit.get("proof"))
            if override.get("parser_proof") != parser_proof:
                errors.append(f"{prefix}.parser_proof is stale")
            if override.get("reviewed_proof") != reviewed_proof:
                errors.append(f"{prefix}.reviewed_proof is stale")
            reviewed_association = reviewed_unit.get("proof_association")
            reviewed_method = (
                reviewed_association.get("method")
                if isinstance(reviewed_association, dict)
                else None
            )
            if (
                not is_nonempty_string(override.get("association_method"))
                or override.get("association_method") != reviewed_method
            ):
                errors.append(
                    f"{prefix}.association_method must match the reviewed association"
                )
            if reviewed_proof is None:
                if override.get("reviewed_proof_sha256") is not None:
                    errors.append(
                        f"{prefix}.reviewed_proof_sha256 must be null when the "
                        "reviewed proof is null"
                    )
            elif reviewed_proof == {}:
                errors.append(f"{prefix}.reviewed_proof is malformed")
            else:
                try:
                    reviewed_path = resolve_stored_path(
                        str(reviewed_proof["file"]), paper.parent
                    )
                    reviewed_start = reviewed_proof["start_line"]
                    reviewed_end = reviewed_proof["end_line"]
                except (KeyError, TypeError, ValueError):
                    errors.append(f"{prefix}.reviewed_proof has an invalid range")
                else:
                    if reviewed_path not in recorded_files:
                        errors.append(
                            f"{prefix}.reviewed_proof is outside the source snapshot"
                        )
                    if not is_int(reviewed_start) or not is_int(reviewed_end):
                        errors.append(
                            f"{prefix}.reviewed_proof needs integer line bounds"
                        )
                    elif reviewed_path.is_file():
                        try:
                            digest = source_span_sha256(
                                reviewed_path, reviewed_start, reviewed_end
                            )
                        except (OSError, UnicodeError, ValueError) as exc:
                            errors.append(f"{prefix}.reviewed_proof: {exc}")
                        else:
                            if override.get("reviewed_proof_sha256") != digest:
                                errors.append(
                                    f"{prefix}.reviewed_proof_sha256 is stale"
                                )
                            if not proof_span_has_safe_boundary(
                                reviewed_path,
                                reviewed_start,
                                reviewed_end,
                                target_unit_id=str(unit_id),
                                source_files=current_files,
                            ):
                                errors.append(
                                    f"{prefix}.reviewed_proof must equal a complete "
                                    "proof environment or a bounded proof region"
                                )
                    else:
                        errors.append(
                            f"{prefix}.reviewed_proof source file is missing"
                        )
        elif kind == "proof_association":
            if fresh_unit is None or reviewed_unit is None:
                errors.append(
                    f"{prefix}: proof_association requires a parser-discovered unit"
                )
                continue
            parser_association = fresh_unit.get("proof_association")
            reviewed_association = reviewed_unit.get("proof_association")
            if override.get("parser_association") != parser_association:
                errors.append(f"{prefix}.parser_association is stale")
            if override.get("reviewed_association") != reviewed_association:
                errors.append(f"{prefix}.reviewed_association is stale")
            if not isinstance(reviewed_association, dict):
                errors.append(f"{prefix}.reviewed_association must be an object")
                continue
            association_occurrences = validate_string_list(
                reviewed_association.get("evidence_occurrence_ids"),
                f"{prefix}.reviewed_association.evidence_occurrence_ids",
                errors,
                allow_empty=True,
            )
            if len(association_occurrences) != len(
                set(association_occurrences)
            ):
                errors.append(
                    f"{prefix}.reviewed_association.evidence_occurrence_ids "
                    "contains duplicates"
                )
            if not all(
                occurrence_id.startswith("R-")
                for occurrence_id in association_occurrences
            ):
                errors.append(
                    f"{prefix}.reviewed_association.evidence_occurrence_ids "
                    "must contain parser occurrence IDs"
                )
            reviewed_status = reviewed_association.get("status")
            reviewed_method = reviewed_association.get("method")
            valid_association = bool(
                reviewed_status == "associated"
                and reviewed_method
                in {"reviewed_redirect_anchor", "reviewed_manual"}
            )
            valid_rejection = bool(
                reviewed_status == "rejected"
                and reviewed_method == "reviewed_rejection"
                and reviewed_unit.get("proof") is None
                and not association_occurrences
            )
            if (
                reviewed_association.get("target") != unit_id
                or not (valid_association or valid_rejection)
            ):
                errors.append(
                    f"{prefix}.reviewed_association must explicitly confirm or "
                    "reject the parser association"
                )
            if not is_substantive_string(
                override.get("rendered_source_evidence")
            ):
                errors.append(
                    f"{prefix}.rendered_source_evidence must be substantive"
                )
            parser_status = (
                parser_association.get("status")
                if isinstance(parser_association, dict)
                else None
            )
            parser_method = (
                parser_association.get("method")
                if isinstance(parser_association, dict)
                else None
            )
            if parser_status == "review_required" and valid_association:
                if (
                    parser_method != "redirect_anchor"
                    or reviewed_method != "reviewed_redirect_anchor"
                    or canonical_location(reviewed_unit.get("proof"))
                    != canonical_location(fresh_unit.get("proof"))
                    or reviewed_association.get("evidence_occurrence_ids")
                    != parser_association.get("evidence_occurrence_ids")
                ):
                    errors.append(
                        f"{prefix}: redirected proof confirmation must preserve the "
                        "parser candidate and its exact evidence occurrences"
                    )
            elif valid_association and canonical_location(
                reviewed_unit.get("proof")
            ) != canonical_location(
                fresh_unit.get("proof")
            ) and reviewed_method != "reviewed_manual":
                errors.append(
                    f"{prefix}: a changed proof span requires reviewed_manual"
                )
        elif kind == "external_restatement":
            valid_external_restatement = True
            if unit_id not in in_scope:
                errors.append(
                    f"{prefix}: external_restatement unit must be in scope"
                )
                valid_external_restatement = False
            if fresh_unit is None or reviewed_unit is None:
                errors.append(
                    f"{prefix}: external_restatement requires one "
                    "parser-discovered reviewed unit"
                )
                valid_external_restatement = False
            elif (
                fresh_unit.get("proof_required") is not True
                or reviewed_unit.get("proof_required") is not True
                or fresh_unit.get("proof") is not None
                or reviewed_unit.get("proof") is not None
            ):
                errors.append(
                    f"{prefix}: external_restatement requires a proof-required "
                    "unit with no local proof"
                )
                valid_external_restatement = False
            elif reviewed_unit.get("proof_association") != fresh_unit.get(
                "proof_association"
            ):
                errors.append(
                    f"{prefix}: external_restatement cannot alter the parser "
                    "proof association"
                )
                valid_external_restatement = False
            external_use_id = override.get("external_dependency_use_id")
            if (
                not is_nonempty_string(external_use_id)
                or not DEPENDENCY_USE_ID_RE.fullmatch(str(external_use_id))
            ):
                errors.append(
                    f"{prefix}.external_dependency_use_id must match D001"
                )
                valid_external_restatement = False
            statement = (
                reviewed_unit.get("statement")
                if isinstance(reviewed_unit, dict)
                else None
            )
            if not isinstance(statement, dict):
                errors.append(
                    f"{prefix}: external_restatement statement range is invalid"
                )
                valid_external_restatement = False
            else:
                try:
                    statement_path = resolve_stored_path(
                        str(statement["file"]), paper.parent
                    )
                    statement_start = statement["start_line"]
                    statement_end = statement["end_line"]
                    statement_sha256 = source_span_sha256(
                        statement_path, statement_start, statement_end
                    )
                except (KeyError, TypeError, OSError, UnicodeError, ValueError):
                    errors.append(
                        f"{prefix}: external_restatement statement range "
                        "cannot be source-locked"
                    )
                    valid_external_restatement = False
                else:
                    if override.get("statement_sha256") != statement_sha256:
                        errors.append(f"{prefix}.statement_sha256 is stale")
                        valid_external_restatement = False
            if valid_external_restatement:
                external_restatements[str(unit_id)] = str(external_use_id)
    missing_overrides = required_inventory_overrides - override_keys
    if missing_overrides:
        errors.append(
            "Reviewed inventory additions lack explicit overrides: "
            + ", ".join(f"{unit_id}/{kind}" for unit_id, kind in sorted(missing_overrides))
        )
    reviewed_exception_overrides = {
        key for key in override_keys if key[1] == "external_restatement"
    }
    stale_overrides = (
        override_keys
        - required_inventory_overrides
        - reviewed_exception_overrides
    )
    if stale_overrides:
        errors.append(
            "Inventory overrides do not match a parser omission: "
            + ", ".join(f"{unit_id}/{kind}" for unit_id, kind in sorted(stale_overrides))
        )

    label_owners = reviewed_label_owners(
        fresh_cross_references, unit_inventory, paper.parent
    )
    support_source_lines = readable_source_lines(current_files, [])
    support_index = build_unowned_label_support_index(
        support_source_lines,
        unit_inventory.values(),
        label_owners,
        paper.parent,
    )
    canonical_evidence_by_unit: dict[str, dict[str, Any]] = {}
    reviewed_reference_occurrences_by_unit: dict[
        str, list[dict[str, Any]]
    ] = {}
    reviewed_proof_spans: list[tuple[str, Path, int, int]] = []
    global_occurrence_ids = {
        occurrence.get("occurrence_id")
        for occurrence in fresh_cross_references.get("occurrences", [])
        if isinstance(occurrence, dict)
        and is_nonempty_string(occurrence.get("occurrence_id"))
    }
    for unit_id, unit in sorted(unit_inventory.items()):
        statement_location = unit.get("statement")
        if not isinstance(statement_location, dict):
            errors.append(f"{unit_id}: reviewed statement location is invalid")
        else:
            try:
                statement_path = resolve_stored_path(
                    str(statement_location["file"]), paper.parent
                )
                statement_start = statement_location["start_line"]
                statement_end = statement_location["end_line"]
            except (KeyError, TypeError, ValueError):
                errors.append(f"{unit_id}: reviewed statement range is invalid")
            else:
                if statement_path not in recorded_files:
                    errors.append(
                        f"{unit_id}: reviewed statement is outside the source snapshot"
                    )
                if (
                    not is_int(statement_start)
                    or not is_int(statement_end)
                    or not statement_path.is_file()
                ):
                    errors.append(
                        f"{unit_id}: reviewed statement has invalid source bounds"
                    )
                else:
                    try:
                        source_span_sha256(
                            statement_path, statement_start, statement_end
                        )
                    except (OSError, UnicodeError, ValueError) as exc:
                        errors.append(f"{unit_id}: reviewed statement: {exc}")

        proof_location = unit.get("proof")
        proof_association = unit.get("proof_association")
        if isinstance(proof_association, dict):
            association_occurrences = proof_association.get(
                "evidence_occurrence_ids"
            )
            if isinstance(association_occurrences, list):
                unknown_association_occurrences = {
                    occurrence_id
                    for occurrence_id in association_occurrences
                    if is_nonempty_string(occurrence_id)
                    and occurrence_id not in global_occurrence_ids
                }
                if unknown_association_occurrences:
                    errors.append(
                        f"{unit_id}: proof_association names stale source "
                        "occurrences: "
                        + ", ".join(sorted(unknown_association_occurrences))
                    )
        if isinstance(proof_location, dict):
            if (
                not isinstance(proof_association, dict)
                or proof_association.get("status") != "associated"
                or proof_association.get("target") != unit_id
            ):
                errors.append(
                    f"{unit_id}: every reviewed proof span requires an explicitly "
                    "associated proof_association"
                )
            try:
                proof_path = resolve_stored_path(
                    str(proof_location["file"]), paper.parent
                )
                proof_start = proof_location["start_line"]
                proof_end = proof_location["end_line"]
            except (KeyError, TypeError, ValueError):
                errors.append(f"{unit_id}: reviewed proof range is invalid")
                continue
            if proof_path not in recorded_files:
                errors.append(
                    f"{unit_id}: reviewed proof is outside the source snapshot"
                )
            if (
                not is_int(proof_start)
                or not is_int(proof_end)
                or not proof_path.is_file()
            ):
                errors.append(f"{unit_id}: reviewed proof has invalid source bounds")
                continue
            try:
                source_span_sha256(proof_path, proof_start, proof_end)
                if not proof_span_has_safe_boundary(
                    proof_path,
                    proof_start,
                    proof_end,
                    target_unit_id=unit_id,
                    source_files=current_files,
                ):
                    errors.append(
                        f"{unit_id}: reviewed proof must equal a complete proof "
                        "environment or a bounded proof region"
                    )
                evidence = reviewed_span_evidence(
                    unit_id,
                    unit,
                    paper.parent,
                    label_owners,
                    support_index,
                    source_files=current_files,
                )
            except (OSError, UnicodeError, ValueError) as exc:
                errors.append(f"{unit_id}: cannot rescan reviewed proof span: {exc}")
                continue
            canonical_evidence_by_unit[unit_id] = evidence
            inventory_evidence = evidence
            reviewed_proof_spans.append(
                (unit_id, proof_path.resolve(), proof_start, proof_end)
            )
        elif proof_location is not None:
            errors.append(f"{unit_id}: reviewed proof must be an object or null")
            evidence = {
                "reference_occurrences": [],
                "dependencies": [],
                "candidate_internal_dependencies": [],
                "citations": [],
                "warnings": [],
            }
            canonical_evidence_by_unit[unit_id] = evidence
            inventory_evidence = evidence
        else:
            if (
                isinstance(proof_association, dict)
                and proof_association.get("status") == "associated"
            ):
                errors.append(
                    f"{unit_id}: proof_association cannot be associated without a proof span"
                )
            try:
                evidence = reviewed_span_evidence(
                    unit_id,
                    unit,
                    paper.parent,
                    label_owners,
                    support_index,
                    statement_as_primary=unit_id in external_restatements,
                    source_files=current_files,
                )
                inventory_evidence = (
                    reviewed_span_evidence(
                        unit_id,
                        unit,
                        paper.parent,
                        label_owners,
                        support_index,
                        source_files=current_files,
                    )
                    if unit_id in external_restatements
                    else evidence
                )
            except (OSError, UnicodeError, ValueError) as exc:
                errors.append(
                    f"{unit_id}: cannot rescan reviewed statement span: {exc}"
                )
                continue
            canonical_evidence_by_unit[unit_id] = evidence

        try:
            reviewed_reference_occurrences_by_unit[unit_id] = (
                reviewed_unit_reference_occurrences(
                    unit, paper.parent, label_owners
                )
            )
        except (OSError, UnicodeError, ValueError) as exc:
            errors.append(
                f"{unit_id}: cannot rescan statement and proof references: {exc}"
            )
            reviewed_reference_occurrences_by_unit[unit_id] = []

        for field in (
            "reference_occurrences",
            "dependencies",
            "candidate_internal_dependencies",
            "citations",
        ):
            if unit.get(field) != inventory_evidence.get(field):
                errors.append(
                    f"{unit_id}: reviewed inventory {field} disagrees with the "
                    "canonical rescan"
                )
        unrecorded_span_warnings = set(evidence.get("warnings", [])) - (
            set(current_warnings)
            | set(fresh_inventory.get("warnings", []))
            | set(fresh_cross_references.get("warnings", []))
        )
        if unrecorded_span_warnings:
            errors.append(
                f"{unit_id}: reviewed unit rescan introduced warnings absent "
                "from the reviewed parser-warning set: "
                + "; ".join(sorted(unrecorded_span_warnings))
            )

    for index, (unit_id, path, start, end) in enumerate(reviewed_proof_spans):
        for other_id, other_path, other_start, other_end in reviewed_proof_spans[
            index + 1 :
        ]:
            if (
                path == other_path
                and max(start, other_start) <= min(end, other_end)
            ):
                errors.append(
                    f"Reviewed proof spans overlap: {unit_id} and {other_id} at "
                    f"{path}"
                )
    recorded_warnings = manifest.get("parser_warnings")
    if not isinstance(recorded_warnings, list) or not all(
        is_nonempty_string(item) for item in recorded_warnings
    ):
        errors.append("manifest.parser_warnings must contain nonempty strings")
        recorded_warnings = []
    if len(recorded_warnings) != len(set(recorded_warnings)):
        errors.append("manifest.parser_warnings contains duplicates")
    fresh_warning_set = (
        set(current_warnings)
        | set(fresh_inventory.get("warnings", []))
        | set(fresh_cross_references.get("warnings", []))
    )
    if set(recorded_warnings) != fresh_warning_set:
        errors.append(
            "manifest.parser_warnings does not match the current parser warning set"
        )

    warning_reviews = manifest.get("parser_warning_reviews", [])
    if not isinstance(warning_reviews, list):
        errors.append("manifest.parser_warning_reviews must be a list")
        warning_reviews = []
    reviewed_warning_messages: list[str] = []
    reviewed_external_restatement_warnings: set[str] = set()
    for index, review in enumerate(warning_reviews, 1):
        prefix = f"parser_warning_reviews[{index}]"
        if not isinstance(review, dict):
            errors.append(f"{prefix} must be an object")
            continue
        warning = review.get("warning")
        disposition = review.get("disposition")
        if not is_nonempty_string(warning):
            errors.append(f"{prefix}.warning must be a nonempty string")
            continue
        reviewed_warning_messages.append(warning)
        if not is_enum_value(
            disposition,
            {
                "unreviewed",
                "confirmed_non_load_bearing",
                "external_restatement",
                "scope_limitation",
                "unresolved",
            },
        ):
            errors.append(f"{prefix}.disposition is invalid")
        affected_units = review.get("affected_units")
        if not isinstance(affected_units, list) or not all(
            is_nonempty_string(item) for item in affected_units
        ):
            errors.append(f"{prefix}.affected_units must be a string list")
            affected_units = []
        elif len(affected_units) != len(set(affected_units)):
            errors.append(f"{prefix}.affected_units contains duplicates")
        unknown_affected = set(affected_units) - set(unit_inventory)
        if unknown_affected:
            errors.append(
                f"{prefix}.affected_units names unknown units: "
                + ", ".join(sorted(unknown_affected))
            )
        if not is_nonempty_string(review.get("evidence")):
            errors.append(f"{prefix}.evidence must be a nonempty string")
        if disposition == "unreviewed":
            errors.append(f"{prefix} has not been reviewed")
        if disposition == "unresolved" and assessment == "no_defect_found":
            errors.append(
                f"{prefix}: an unresolved parser warning blocks no_defect_found"
            )
        if disposition == "external_restatement":
            invalid_external_warning = bool(
                len(affected_units) != 1
                or affected_units[0] not in external_restatements
                or not warning.startswith(
                    "Proof-required result has no associated proof: "
                    f"{affected_units[0] if affected_units else ''} at "
                )
            )
            if invalid_external_warning:
                errors.append(
                    f"{prefix}: external_restatement must review the "
                    "missing-proof warning for exactly one explicitly "
                    "overridden unit"
                )
            else:
                reviewed_external_restatement_warnings.add(
                    affected_units[0]
                )
        if disposition == "scope_limitation":
            if not scope.get("source_or_parser_limits"):
                errors.append(
                    f"{prefix}: scope_limitation requires "
                    "audit_scope.source_or_parser_limits"
                )
            if assessment == "no_defect_found" and (
                not affected_units or set(affected_units) & set(in_scope)
            ):
                errors.append(
                    f"{prefix}: an in-scope parser limitation blocks no_defect_found"
                )
    if len(reviewed_warning_messages) != len(set(reviewed_warning_messages)):
        errors.append("manifest.parser_warning_reviews contains duplicate warnings")
    if set(reviewed_warning_messages) != set(recorded_warnings):
        errors.append(
            "manifest.parser_warning_reviews must be a one-to-one review of "
            "manifest.parser_warnings"
        )
    missing_external_warning_reviews = (
        set(external_restatements)
        - reviewed_external_restatement_warnings
    )
    if missing_external_warning_reviews:
        errors.append(
            "External restatement overrides lack matching missing-proof "
            "warning reviews: "
            + ", ".join(sorted(missing_external_warning_reviews))
        )

    exclusions = scope.get("excluded_units")
    excluded_ids: set[str] = set()
    if not isinstance(exclusions, list):
        errors.append("audit_scope.excluded_units must be a list")
        exclusions = []
    for index, exclusion in enumerate(exclusions, 1):
        prefix = f"audit_scope.excluded_units[{index}]"
        if not isinstance(exclusion, dict):
            errors.append(f"{prefix} must be an object")
            continue
        excluded_id = exclusion.get("id")
        if not is_nonempty_string(excluded_id) or not is_nonempty_string(
            exclusion.get("reason")
        ):
            errors.append(f"{prefix} needs nonempty id and reason")
            continue
        if excluded_id in excluded_ids:
            errors.append(f"Duplicate excluded unit: {excluded_id}")
        excluded_ids.add(excluded_id)
    if set(in_scope) & excluded_ids:
        errors.append("A proof unit cannot be both in scope and excluded")
    unknown_scope = (set(in_scope) | excluded_ids) - set(unit_inventory)
    if unknown_scope:
        errors.append("Scope names unknown inventory units: " + ", ".join(sorted(unknown_scope)))
    omitted_inventory = set(unit_inventory) - set(in_scope) - excluded_ids
    if omitted_inventory:
        errors.append(
            "Inventory units lack an in-scope or explicit-exclusion decision: "
            + ", ".join(sorted(omitted_inventory))
        )
    if scope.get("depth") == "full":
        excluded_proof_units = {
            unit_id
            for unit_id, unit in unit_inventory.items()
            if unit.get("proof_required") is True and unit_id not in set(in_scope)
        }
        if excluded_proof_units:
            errors.append(
                "A full audit cannot exclude proof-required units: "
                + ", ".join(sorted(excluded_proof_units))
            )

    cross_reference_result = validate_cross_reference_reviews(
        manifest.get("cross_reference_reviews"),
        fresh_cross_references,
        in_scope,
        errors,
    )

    if source_inventory_only:
        # Pre-challenge issues reuses this source consistency boundary while
        # its existing primary ledger, dependency and issue checks run there.
        return errors, {"audit_root": str(root), "errors": len(errors)}

    completion = manifest.get("completion")
    if not isinstance(completion, dict):
        errors.append("completion must be an object")
        completion = {}
    for field in (
        "inventory_reviewed",
        "parser_warnings_reviewed",
        "dependency_registry_reviewed",
        "method_interface_registry_reviewed",
    ):
        if completion.get(field) is not True:
            errors.append(f"completion.{field} must be true")
    if check_reports and completion.get("final_report_ready") is not True:
        errors.append("completion.final_report_ready must be true")
    global_consistency_result = validate_global_consistency_pass(
        completion.get("global_consistency_pass"), in_scope, errors
    )
    source_resolution = global_consistency_result.get("impacts", {}).get(
        "source_resolution", {}
    )
    anomaly_status = (
        "defect"
        if cross_reference_result.get("defect")
        else "inconclusive"
        if cross_reference_result.get("inconclusive")
        else "clean"
    )
    source_status = source_resolution.get("status")
    if anomaly_status == "defect" and source_status != "defect":
        errors.append(
            "global source_resolution status must be defect for defect cross-reference reviews"
        )
    if anomaly_status == "inconclusive" and not is_enum_value(
        source_status, {"defect", "inconclusive"}
    ):
        errors.append(
            "global source_resolution status must cover inconclusive cross-reference reviews"
        )
    if not set(cross_reference_result.get("affected_units", set())).issubset(
        source_resolution.get("affected_units", set())
    ):
        errors.append(
            "global source_resolution affected_units omit cross-reference impacts"
        )
    if not set(cross_reference_result.get("issue_ids", set())).issubset(
        source_resolution.get("issue_ids", set())
    ):
        errors.append("global source_resolution issue_ids omit cross-reference issues")
    validate_completion_pass(
        completion.get("adversarial_pass"), "adversarial_pass", errors
    )
    report_text = ""
    if check_reports and not uses_html_report(manifest):
        final_report, final_report_path_valid = canonical_artifact_path(
            root,
            "audit/06_reports/FINAL_REPORT.md",
            "final report",
            errors,
        )
        report_assessment: str | None = None
        report_text = ""
        raw_report_text = ""
        report_fields: dict[str, str] = {}
        if final_report_path_valid and not final_report.is_file():
            errors.append(f"Final report not found: {final_report}")
        elif (
            final_report_path_valid
            and completion.get("final_report_ready") is not True
        ):
            nonfinal_report_text = active_markdown_text(read_text(final_report))
            if not contains_report_scaffold_marker(nonfinal_report_text):
                errors.append(
                    "Final report removed the NONFINAL scaffold marker before "
                    "completion.final_report_ready is true"
                )
            if (
                not report_has_exact_title(
                    nonfinal_report_text, WORKING_REPORT_TITLE
                )
            ):
                errors.append(
                    "Nonfinal report must use the working title as its sole H1: "
                    f"{WORKING_REPORT_TITLE}"
                )
        elif final_report_path_valid and completion.get("final_report_ready") is True:
            raw_report_text = read_text(final_report)
            report_text = active_markdown_text(raw_report_text)
            if contains_report_scaffold_marker(report_text):
                errors.append(
                    "Final report still contains the NONFINAL scaffold marker"
                )
            if (
                not report_has_exact_title(report_text, FINAL_REPORT_TITLE)
            ):
                errors.append(
                    "Final report must use the final title as its sole H1: "
                    f"{FINAL_REPORT_TITLE}"
                )
            if ACTIVE_HIDDEN_HTML_MARKER in report_text:
                errors.append(
                    "Final report contains active raw HTML"
                )
            for label in REPORT_SCALAR_FIELDS:
                matches = list(re.finditer(
                    rf"^- {re.escape(label)}:\s*(.*?)\s*$", report_text, re.MULTILINE
                ))
                if not matches:
                    errors.append(f"Final report is missing the {label} field")
                elif len(matches) != 1:
                    errors.append(f"Final report has a duplicate {label} field")
                elif not matches[0].group(1):
                    errors.append(f"Final report still has an empty {label} field")
                else:
                    report_fields[label] = matches[0].group(1)
                    if label == "Overall assessment code":
                        report_assessment = matches[0].group(1)
            first_h2 = re.search(r"^##\s+.*$", report_text, re.MULTILINE)
            if first_h2 is None or first_h2.group(0) != "## Summary":
                errors.append("Final report must begin its substantive content with ## Summary")
            summary_text = report_section(report_text, "## Summary") or ""
            for label in REPORT_SUMMARY_FIELDS:
                summary_matches = re.findall(
                    rf"^- {re.escape(label)}:\s*(.*?)\s*$",
                    summary_text,
                    re.MULTILINE,
                )
                if len(summary_matches) != 1:
                    errors.append(
                        f"Final report {label} must appear exactly once within ## Summary"
                    )
            scope_text = report_section(
                report_text, "## Scope and assurance"
            ) or ""
            for label in REPORT_SCOPE_FIELDS:
                scope_matches = re.findall(
                    rf"^- {re.escape(label)}:\s*(.*?)\s*$",
                    scope_text,
                    re.MULTILINE,
                )
                if len(scope_matches) != 1:
                    errors.append(
                        f"Final report {label} must appear exactly once within "
                        "## Scope and assurance"
                    )
            for label in (
                "Main reason",
                "Impact on paper conclusions/results",
                "Repair options and difficulty",
            ):
                if not is_substantive_string(report_fields.get(label)):
                    errors.append(f"Final report {label} must be substantive")
            actual_h2 = re.findall(r"^##\s+(.+?)\s*$", report_text, re.MULTILINE)
            if actual_h2 != list(REPORT_REQUIRED_SECTIONS):
                errors.append(
                    "Final report must contain exactly these four H2 sections in "
                    "order: " + ", ".join(REPORT_REQUIRED_SECTIONS)
                )
            if report_assessment is not None and report_assessment != assessment:
                errors.append(
                    "Final report assessment disagrees with audit_scope.overall_assessment"
                )
            expected_report_protocol = {
                "Skill version": SKILL_VERSION,
                "Artifact schema version": str(SCHEMA_VERSION),
                "Evidence contract version": str(EVIDENCE_CONTRACT_VERSION),
                "Method-interface schema version": str(METHOD_INTERFACE_SCHEMA_VERSION),
                "Closure contract version": str(CLOSURE_CONTRACT_VERSION),
                "Source snapshot ID": (
                    snapshot.get("sha256") if isinstance(snapshot, dict) else None
                ),
                "Finalization record": manifest.get("finalization_record"),
            }
            for label, expected in expected_report_protocol.items():
                if report_fields.get(label) != expected:
                    errors.append(f"Final report {label} disagrees with the manifest")
            canonical_judgments = {
                "no_defect_found": (
                    "No load-bearing defect found under the stated non-formal protocol."
                ),
                "defects_found": "Defects found under the stated non-formal protocol.",
                "inconclusive": "Inconclusive under the stated non-formal protocol.",
            }
            canonical_judgment = (
                canonical_judgments.get(assessment)
                if isinstance(assessment, str)
                else None
            )
            if report_fields.get("Overall judgment") != canonical_judgment:
                errors.append("Final report Overall judgment is not the canonical judgment")
            if report_fields.get("Checked scope") != canonical_id_field(in_scope):
                errors.append("Final report Checked scope disagrees with audit scope")
            if report_fields.get("Target results") != canonical_id_field(
                target_units
            ):
                errors.append("Final report Target results disagrees with audit scope")
            if report_fields.get("Results not checked") != canonical_id_field(excluded_ids):
                errors.append("Final report Results not checked disagrees with exclusions")
            expected_limits = canonical_id_field(scope.get("source_or_parser_limits", []))
            if report_fields.get(
                "Tooling, extraction, or rendering limitations"
            ) != expected_limits:
                errors.append(
                    "Final report Tooling, extraction, or rendering limitations disagree with audit scope"
                )
            if "This is a non-formal audit." not in report_text:
                errors.append("Final report must state the non-formal assurance boundary")
            validate_report_assurance_language(
                raw_report_text, "Final report", errors
            )

    ledger_errors, summaries, referenced = audit_ledgers(root, True)
    errors.extend(ledger_errors)
    referenced.update(global_consistency_result.get("issue_ids", set()))
    referenced.update(cross_reference_result.get("issue_ids", set()))
    if not summaries:
        errors.append("Finalization requires at least one proof-unit ledger")
    summaries_by_id: dict[str, dict[str, Any]] = {}
    for summary in summaries:
        unit_id = summary.get("unit_id")
        if not is_nonempty_string(unit_id):
            continue
        if unit_id in summaries_by_id:
            errors.append(f"Duplicate ledger unit_id: {unit_id}")
        summaries_by_id[unit_id] = summary
    missing_ledgers = set(in_scope) - set(summaries_by_id)
    extra_ledgers = set(summaries_by_id) - set(in_scope)
    if missing_ledgers:
        errors.append("In-scope units missing ledgers: " + ", ".join(sorted(missing_ledgers)))
    if extra_ledgers:
        errors.append("Ledgers exist outside declared scope: " + ", ".join(sorted(extra_ledgers)))

    for unit_id in sorted(set(in_scope) & set(summaries_by_id) & set(unit_inventory)):
        summary = summaries_by_id[unit_id]
        unit = unit_inventory[unit_id]
        external_restatement_use_id = external_restatements.get(unit_id)
        statement = unit.get("statement")
        if not isinstance(statement, dict):
            errors.append(f"{unit_id}: invalid inventory statement location")
            continue
        loaded_for_fragments = load_summary_ledger(summary)
        if loaded_for_fragments is not None:
            fragment_ledger, fragment_ledger_path = loaded_for_fragments
            errors.extend(f"{unit_id}: {message}" for message in source_fragment_support().statement_binding_errors(
                report_api(), statement, paper.parent,
                (fragment_ledger.get("obligation") or {}).get("statement_spans"), fragment_ledger_path.parent))
        try:
            statement_source = resolve_stored_path(str(statement["file"]), paper.parent)
            statement_start = statement["start_line"]
            statement_end = statement["end_line"]
        except (KeyError, TypeError, ValueError):
            errors.append(f"{unit_id}: invalid inventory statement range")
            continue
        exact_contract_anchor = any(
            Path(span.get("file", "")).resolve() == statement_source
            and span.get("start_line") == statement_start
            and span.get("end_line") == statement_end
            for span in summary.get("obligation_statement_spans", [])
        )
        if not exact_contract_anchor:
            errors.append(
                f"{unit_id}: obligation statement span does not exactly match the inventory"
            )
        for span in summary.get("obligation_statement_spans", []) + summary.get(
            "obligation_context_spans", []
        ):
            span_path = Path(span.get("file", "")).resolve()
            if span_path not in recorded_files:
                errors.append(
                    f"{unit_id}: obligation span is outside the snapshotted source closure: "
                    f"{span_path}"
                )

        proof_location = unit.get("proof")
        if (
            unit.get("proof_required") is True
            and proof_location is None
            and external_restatement_use_id is None
            and not is_enum_value(
                summary.get("declared_unit_status"),
                {"gap", "incorrect", "unclear"},
            )
        ):
            errors.append(
                f"{unit_id}: proof-required result has no inventoried proof range"
            )
        coverage_target = proof_location if isinstance(proof_location, dict) else statement
        try:
            target_source = resolve_stored_path(
                str(coverage_target["file"]), paper.parent
            )
            target_start = coverage_target["start_line"]
            target_end = coverage_target["end_line"]
            if (
                isinstance(proof_location, dict)
                and target_source == statement_source
                and summary.get("coverage_mode") == "statement_and_proof"
            ):
                target_start = min(target_start, statement_start)
                target_end = max(target_end, statement_end)
        except (KeyError, TypeError, ValueError):
            errors.append(f"{unit_id}: invalid inventoried proof range")
        else:
            if external_restatement_use_id is not None:
                if summary.get("coverage_mode") != "external_restatement":
                    errors.append(
                        f"{unit_id}: explicit external_restatement override "
                        "requires matching ledger coverage"
                    )
                if (
                    summary.get("external_restatement_use_id")
                    != external_restatement_use_id
                ):
                    errors.append(
                        f"{unit_id}: ledger external_dependency_use_id does "
                        "not match the reviewed override"
                    )
                if (
                    Path(summary.get("source_file", "")).resolve()
                    != statement_source
                    or summary.get("source_start") != statement_start
                    or summary.get("source_end") != statement_end
                ):
                    errors.append(
                        f"{unit_id}: external_restatement ledger range must "
                        "exactly equal the formal statement span"
                    )
            elif summary.get("coverage_mode") == "external_restatement":
                errors.append(
                    f"{unit_id}: external_restatement ledger coverage requires "
                    "an explicit reviewed inventory override"
                )
            if (
                target_source != statement_source
                and summary.get("coverage_mode") != "proof_with_separate_statement"
            ):
                errors.append(
                    f"{unit_id}: cross-file statement and proof require "
                    "proof_with_separate_statement coverage"
                )
            if target_source != Path(summary.get("source_file", "")).resolve():
                errors.append(
                    f"{unit_id}: ledger does not cover the inventoried proof source file"
                )
            elif not (
                summary.get("source_start", 0) <= target_start
                and summary.get("source_end", 0) >= target_end
            ):
                errors.append(
                    f"{unit_id}: ledger range omits part of the required statement/proof source"
                )

        validate_primary_reference_roles(
            unit_id, unit, summary,
            reviewed_reference_occurrences_by_unit.get(unit_id, []),
            unit_inventory, paper.parent, errors,
        )
        direct_by_use = {
            row.get("use_id"): row for row in summary.get("direct_dependencies", [])
            if isinstance(row, dict) and is_nonempty_string(row.get("use_id"))
        }
        step_result_claims = {
            row.get("use_id"): row for row in summary.get("result_dependency_claims", [])
            if isinstance(row, dict) and is_nonempty_string(row.get("use_id"))
        }

        citation_dispositions = {
            record.get("key"): record
            for record in summary.get("citation_dispositions", [])
            if isinstance(record, dict) and is_nonempty_string(record.get("key"))
        }
        source_citations = {
            citation
            for citation in canonical_evidence_by_unit.get(unit_id, {}).get(
                "citations", []
            )
            if is_nonempty_string(citation)
        }
        missing_citation_dispositions = source_citations - set(citation_dispositions)
        if missing_citation_dispositions:
            errors.append(
                f"{unit_id}: citations lack reviewed dispositions: "
                + ", ".join(sorted(missing_citation_dispositions))
            )
        stale_citation_dispositions = set(citation_dispositions) - source_citations
        if stale_citation_dispositions:
            errors.append(
                f"{unit_id}: citation dispositions are not present in the proof: "
                + ", ".join(sorted(stale_citation_dispositions))
            )
        for citation, disposition in citation_dispositions.items():
            disposition_status = disposition.get("disposition")
            if disposition_status == "external_result":
                dependency_id = disposition.get("dependency_id")
                dependency_use_id = disposition.get("dependency_use_id")
                dependency = direct_by_use.get(dependency_use_id)
                claim = step_result_claims.get(dependency_use_id)
                if (
                    dependency is None
                    or dependency.get("kind") != "external_result"
                    or dependency.get("id") != dependency_id
                ):
                    errors.append(
                        f"{unit_id}: citation {citation} does not resolve to an external "
                        "direct dependency use"
                    )
                if (
                    claim is None
                    or claim.get("kind") != "external_result"
                    or claim.get("id") != dependency_id
                ):
                    errors.append(
                        f"{unit_id}: citation dependency use {dependency_use_id} "
                        "is not mapped to a proof step"
                    )
            if (
                disposition_status == "unresolved"
                and summary.get("declared_unit_status") == "verified"
            ):
                errors.append(f"{unit_id}: verified unit has unresolved citation {citation}")
        if external_restatement_use_id is not None:
            designated_dependency = direct_by_use.get(
                external_restatement_use_id
            )
            designated_dependency_id = (
                designated_dependency.get("id")
                if isinstance(designated_dependency, dict)
                and designated_dependency.get("kind") == "external_result"
                else None
            )
            for citation in sorted(source_citations):
                disposition = citation_dispositions.get(citation)
                if (
                    not isinstance(disposition, dict)
                    or disposition.get("disposition") != "external_result"
                    or disposition.get("dependency_use_id")
                    != external_restatement_use_id
                    or disposition.get("dependency_id")
                    != designated_dependency_id
                ):
                    errors.append(
                        f"{unit_id}: external_restatement citation {citation} "
                        "must map to its designated external dependency use "
                        f"{external_restatement_use_id}"
                    )

        occurrence_context = {
            occurrence.get("occurrence_id"): occurrence.get(
                "structural_context"
            )
            for evidence in canonical_evidence_by_unit.values()
            for occurrence in evidence.get("reference_occurrences", [])
            if isinstance(occurrence, dict)
            and is_nonempty_string(occurrence.get("occurrence_id"))
        }
        redirect_spans = [
            redirect
            for reviewed_unit in unit_inventory.values()
            for redirect in reviewed_unit.get("proof_redirects", [])
            if isinstance(reviewed_unit, dict)
            and isinstance(reviewed_unit.get("proof_redirects"), list)
            and isinstance(redirect, dict)
        ]
        expected_use_sites: set[str] = set()
        for occurrence in fresh_cross_references.get("occurrences", []):
            if not isinstance(occurrence, dict):
                continue
            occurrence_owner = label_owners.get(occurrence.get("target"), {})
            refers_to_unit = bool(
                occurrence.get("target") == unit_id
                or (
                    occurrence_owner.get("status") == "unique"
                    and occurrence_owner.get("owner_unit_id") == unit_id
                )
            )
            if not refers_to_unit:
                continue
            if span_contains_location(
                unit.get("statement"),
                occurrence.get("file"),
                occurrence.get("line"),
                paper.parent,
            ) or span_contains_location(
                unit.get("proof"),
                occurrence.get("file"),
                occurrence.get("line"),
                paper.parent,
            ):
                continue
            if occurrence_context.get(
                occurrence.get("occurrence_id")
            ) == "proof_header":
                continue
            if any(
                span_contains_location(
                    redirect,
                    occurrence.get("file"),
                    occurrence.get("line"),
                    paper.parent,
                )
                for redirect in redirect_spans
            ):
                continue
            if (
                is_nonempty_string(occurrence.get("file"))
                and is_int(occurrence.get("line"))
            ):
                expected_use_sites.add(
                    f"{occurrence['file']}:{occurrence['line']}"
                )
        recorded_use_sites = {
            value for value in summary.get("use_sites", []) if is_nonempty_string(value)
        }
        if recorded_use_sites != expected_use_sites:
            errors.append(
                f"{unit_id}: review.use_sites disagrees with canonical downstream "
                "uses; expected " + canonical_id_field(expected_use_sites)
            )
    registry, registry_errors = (
        load_json_object(registry_path, "dependency registry")
        if registry_path_valid
        else ({}, [])
    )
    errors.extend(registry_errors)
    closure_result = (
        validate_dependency_closure(
            registry,
            root,
            summaries_by_id,
            source_snapshot_sha256=(
                snapshot.get("sha256") if isinstance(snapshot, dict) else None
            ),
            inventory_sha256=(
                sha256_file(inventory_path) if inventory_path.is_file() else ""
            ),
            in_scope=in_scope,
            errors=errors,
        )
        if registry_path_valid and not registry_errors
        else {
            "external_results": {},
            "edges": [],
            "unit_graph": {unit_id: set() for unit_id in summaries_by_id},
            "issue_ids": set(),
        }
    )
    external_results = closure_result["external_results"]
    dependency_edges = closure_result["edges"]
    apply_derived_use_site_sufficiency(summaries_by_id, dependency_edges)
    unit_graph = closure_result["unit_graph"]
    referenced.update(closure_result["issue_ids"])
    try:
        candidate_source_members = packet_source_members(root, manifest)
    except (OSError, UnicodeError, ValueError) as exc:
        errors.append(
            f"Cannot reconstruct dependency-candidate provenance: {exc}"
        )
        candidate_source_members = []
    for unit_id in sorted(set(in_scope) & set(unit_inventory) & set(summaries_by_id)):
        validate_primary_candidate_references(
            root, inventory, unit_id, unit_inventory[unit_id],
            summaries_by_id[unit_id], unit_inventory, paper.parent,
            reviewed_reference_occurrences_by_unit.get(unit_id, []),
            candidate_source_members, dependency_edges, errors,
        )
    for unit_id, external_use_id in sorted(external_restatements.items()):
        if unit_id not in in_scope:
            continue
        summary = summaries_by_id.get(unit_id, {})
        matching_edges = [
            edge
            for edge in dependency_edges
            if isinstance(edge, dict)
            and edge.get("dependent_unit") == unit_id
            and edge.get("use_id") == external_use_id
            and edge.get("kind") == "external_result"
        ]
        if len(matching_edges) != 1:
            errors.append(
                f"{unit_id}: external_restatement requires exactly one "
                f"canonical external dependency edge for {external_use_id}"
            )
        elif (
            summary.get("declared_unit_status") == "verified"
            and matching_edges[0].get("effective_status") != "verified"
        ):
            errors.append(
                f"{unit_id}: verified external_restatement requires a "
                "verified external dependency edge"
            )
        for result in summary.get("conclusion_results", []):
            if (
                isinstance(result, dict)
                and result.get("statement_status")
                in {"established", "conditional"}
                and external_use_id not in result.get("dependency_use_ids", [])
            ):
                errors.append(
                    f"{unit_id}:{result.get('conclusion_id')}: "
                    "external_restatement dependency is absent from the "
                    "conclusion support closure"
                )
    if scope.get("depth") == "focused":
        required_scope: set[str] = set()
        pending_targets = list(target_units)
        while pending_targets:
            current_unit = pending_targets.pop()
            if current_unit in required_scope:
                continue
            required_scope.add(current_unit)
            pending_targets.extend(
                dependency
                for dependency in unit_graph.get(current_unit, set())
                if dependency not in required_scope
            )
        missing_scope = required_scope - set(in_scope)
        unrelated_scope = set(in_scope) - required_scope
        if missing_scope:
            errors.append(
                "Focused audit omits transitive target dependencies: "
                + ", ".join(sorted(missing_scope))
            )
        if unrelated_scope:
            errors.append(
                "Focused audit includes units outside the exact target closure: "
                + ", ".join(sorted(unrelated_scope))
            )
    interface_registry, interface_registry_errors = (
        load_json_object(interface_registry_path, "method-interface registry")
        if interface_registry_path_valid
        else ({}, [])
    )
    errors.extend(interface_registry_errors)
    interfaces = (
        validate_method_interface_registry(interface_registry, root, errors)
        if interface_registry_path_valid and not interface_registry_errors
        else {}
    )
    if set(in_scope_interfaces) != set(interfaces):
        missing_interfaces = set(interfaces) - set(in_scope_interfaces)
        unknown_interfaces = set(in_scope_interfaces) - set(interfaces)
        if missing_interfaces:
            errors.append(
                "audit_scope.in_scope_interfaces omits registry interfaces: "
                + ", ".join(sorted(missing_interfaces))
            )
        if unknown_interfaces:
            errors.append(
                "audit_scope.in_scope_interfaces names unknown interfaces: "
                + ", ".join(sorted(unknown_interfaces))
            )
    for interface_id, interface in interfaces.items():
        affected_results = interface.get("affected_results")
        if isinstance(affected_results, list):
            unknown_results = {
                result_id
                for result_id in affected_results
                if is_nonempty_string(result_id) and result_id not in in_scope
            }
            if unknown_results:
                errors.append(
                    f"{interface_id}.affected_results names results outside scope: "
                    + ", ".join(sorted(unknown_results))
                )
    issue_path, issues, issue_schema_version, issue_read_errors = load_issue_log(root)
    errors.extend(issue_read_errors)
    if issue_schema_version != SCHEMA_VERSION:
        errors.append(
            "upgrade_required: finalization requires ISSUE_LOG.json "
            f"schema_version {SCHEMA_VERSION}; schema "
            f"{issue_schema_version!r} is inspection-only"
        )
    source_snapshot_id = (
        snapshot.get("sha256") if isinstance(snapshot, dict) else None
    )
    reverse_graph: dict[str, set[str]] = {
        unit_id: set() for unit_id in summaries_by_id
    }
    for dependent, dependencies in unit_graph.items():
        for dependency in dependencies:
            reverse_graph.setdefault(dependency, set()).add(dependent)
    global_checks_by_aspect = {
        row.get("aspect"): row
        for row in completion.get("global_consistency_pass", {}).get(
            "checks", []
        )
        if isinstance(row, dict) and is_nonempty_string(row.get("aspect"))
    }
    issue_errors, _ = validate_issues(
        issues,
        referenced,
        True,
        evidence_base=root,
        interfaces=interfaces,
        source_snapshot_id=source_snapshot_id,
        in_scope=in_scope,
        reverse_graph=reverse_graph,
        ledger_summaries=summaries,
        dependency_edges=dependency_edges,
        global_checks=global_checks_by_aspect,
    )
    errors.extend(issue_errors)
    issues_by_id = {
        issue.get("id"): issue
        for issue in issues
        if isinstance(issue, dict) and is_nonempty_string(issue.get("id"))
    }
    report_deliverables = manifest.get("report_deliverables", [])
    if check_reports and not uses_html_report(manifest):
        report_deliverables = validate_report_deliverables(
            report_deliverables, root, set(issues_by_id), assessment, errors)
    if check_reports:
        for report_path in undeclared_report_markdown_files(
            manifest.get("report_deliverables"), root
        ):
            errors.append(undeclared_report_error(report_path))
    required_challenges, severe_issue_ids_by_unit = required_challenge_requirements(
        manifest, issues_by_id.values()
    )
    for unit_id in required_challenges:
        summary = summaries_by_id.get(unit_id)
        if summary is None:
            errors.append(f"In-scope unit has no ledger: {unit_id}")
            continue
        challenge = summary.get("independent_check", {})
        triggering_issue_ids = sorted(severe_issue_ids_by_unit.get(unit_id, set()))
        if not challenge.get("required"):
            errors.append(
                f"In-scope unit {unit_id} requires an independent "
                "challenger pass"
            )
            continue
        if not is_enum_value(challenge.get("status"), {"agreed", "resolved"}):
            errors.append(
                f"In-scope unit {unit_id} has no reconciled challenger verdict"
            )
        if challenge.get("covered_issue_ids") != triggering_issue_ids:
            errors.append(
                f"In-scope unit {unit_id} covered_issue_ids must equal "
                "its current severe triggering issues: "
                + canonical_id_field(triggering_issue_ids)
            )
        if challenge.get("source_snapshot_sha256") != source_snapshot_id:
            errors.append(
                f"In-scope unit {unit_id} challenger source snapshot is stale"
            )
        errors.extend(
            challenge_semantic_freshness_errors(
                root,
                unit_id,
                challenge,
                triggering_issue_ids,
            )
        )
        artifact = challenge.get("artifact")
        if is_nonempty_string(artifact):
            artifact_path, artifact_path_valid = canonical_challenge_artifact_path(
                root,
                artifact,
                f"In-scope unit {unit_id} challenger artifact",
                errors,
            )
            if not artifact_path_valid or artifact_path is None:
                pass
            elif not artifact_path.is_file() or artifact_path.stat().st_size == 0:
                errors.append(
                    f"In-scope unit {unit_id} challenger artifact is "
                    f"missing or empty: {artifact_path}"
                )
            elif challenge.get("challenge_artifact_sha256") != sha256_file(
                artifact_path
            ):
                errors.append(
                    f"In-scope unit {unit_id} challenger artifact hash is stale"
                )
            else:
                errors.extend(
                    challenge_artifact_binding_errors(
                        artifact_path, unit_id, challenge
                    )
                )
    issue_summary_path, issue_summary_path_valid = canonical_artifact_path(
        root,
        "audit/06_reports/ISSUE_SUMMARY.md",
        "issue summary",
        errors,
    )
    expected_issue_summary = render_issue_summary(issues)
    if not issue_summary_path_valid:
        pass
    elif not issue_summary_path.is_file():
        errors.append(f"Canonical issue summary not found: {issue_summary_path}")
    elif read_text(issue_summary_path) != expected_issue_summary:
        errors.append("ISSUE_SUMMARY.md is stale or disagrees with ISSUE_LOG.json")
    for interface_id, interface in interfaces.items():
        issue_ids = interface.get("issue_ids")
        if not isinstance(issue_ids, list):
            continue
        for issue_id in issue_ids:
            issue = issues_by_id.get(issue_id)
            if issue is None:
                errors.append(f"{interface_id}: references undefined issue {issue_id}")
            elif issue.get("interface_id") != interface_id:
                errors.append(
                    f"{interface_id}: issue {issue_id} does not link back to the interface"
                )
    if report_text:
        checked_external = {
            result_id
            for result_id, record in external_results.items()
            if record.get("status") != "unchecked"
        }
        unchecked_external = {
            result_id
            for result_id, record in external_results.items()
            if record.get("status") == "unchecked"
        }
        if report_fields.get("External results checked") != canonical_id_field(
            checked_external
        ):
            errors.append(
                "Final report External results checked disagrees with the "
                "dependency registry"
            )
        if report_fields.get(
            "External results not checked"
        ) != canonical_id_field(unchecked_external):
            errors.append(
                "Final report External results not checked disagrees with the "
                "dependency registry"
            )
        unresolved_issues = [
            issue
            for issue in issues_by_id.values()
            if is_enum_value(issue.get("status"), {"open", "deferred"})
            and is_enum_value(issue.get("severity"), ISSUE_SEVERITIES)
        ]
        if unresolved_issues:
            highest_rank = min(
                ISSUE_SEVERITY_RANK[str(issue.get("severity"))]
                for issue in unresolved_issues
            )
            highest_issue_ids = {
                str(issue.get("id"))
                for issue in unresolved_issues
                if ISSUE_SEVERITY_RANK[str(issue.get("severity"))]
                == highest_rank
            }
        else:
            highest_issue_ids = set()
        if report_fields.get(
            "Highest-consequence issue"
        ) != canonical_id_field(highest_issue_ids):
            errors.append(
                "Final report Highest-consequence issue disagrees with the "
                "issue log"
            )
        independence_levels = [
            summaries_by_id[unit_id].get("independent_check", {}).get(
                "independence_level"
            )
            for unit_id in required_challenges
            if unit_id in summaries_by_id
        ]
        expected_independence = canonical_id_field(
            level
            for level in independence_levels
            if is_enum_value(level, INDEPENDENCE_LEVELS)
        )
        if report_fields.get(
            "Independent check levels"
        ) != expected_independence:
            errors.append(
                "Final report Independent check levels disagree with in-scope "
                "ledgers"
            )
        checked_description = report_fields.get(
            "Files and results checked", ""
        )
        if paper.name not in checked_description or any(
            re.search(
                rf"(?<![A-Za-z0-9:_-]){re.escape(unit_id)}"
                rf"(?![A-Za-z0-9:_-])",
                checked_description,
            )
            is None
            for unit_id in in_scope
        ):
            errors.append(
                "Final report Files and results checked omits the paper or an "
                "in-scope result"
            )

        expected_summary_fields = canonical_report_summary_fields(
            assessment, summaries_by_id, in_scope, issues
        )
        for label, expected_value in expected_summary_fields.items():
            if report_fields.get(label) != expected_value:
                errors.append(
                    f"Final report {label} disagrees with the canonical "
                    "conclusion and issue records"
                )

        expected_results = render_results_and_impact(
            summaries_by_id, in_scope
        ).strip()
        actual_results = (
            report_section(report_text, "## Results and impact") or ""
        ).strip()
        if actual_results != expected_results:
            errors.append(
                "Final report Results and impact disagrees with the canonical "
                "per-conclusion judgments"
            )

        expected_findings = render_findings_and_repairs(
            issues,
            summaries_by_id,
            dependency_edges,
            required_challenges,
            report_deliverables,
            assessment,
            interfaces=interfaces,
            global_checks=global_checks_by_aspect,
        ).strip()
        actual_findings = (
            report_section(report_text, "## Findings and repairs") or ""
        ).strip()
        if actual_findings != expected_findings:
            errors.append(
                "Final report Findings and repairs disagrees with canonical "
                "issues and repair records"
            )
        for issue in issues_by_id.values():
            projection = canonical_issue_detail_projection(
                issue,
                summaries_by_id,
                dependency_edges,
                required_challenges,
                report_deliverables,
                assessment,
                interfaces=interfaces,
                global_checks=global_checks_by_aspect,
            )
            if (
                issue.get("status") == "resolved"
                and projection["closure"][0][-1] != "complete"
            ):
                errors.append(
                    f"{issue.get('id')}: resolved issue has an incomplete "
                    "recheck closure"
                )

        scope_section = (
            report_section(report_text, "## Scope and assurance") or ""
        )
        challenge_section = report_nested_section(
            scope_section, "### Independent verification"
        )
        challenge_rows = markdown_table_rows(challenge_section or "")
        challenge_header = [
            "Result",
            "Check status",
            "Independence",
            "Challenger verdict",
            "Final verdict",
            "Reconciliation",
        ]
        expected_challenge_rows: list[list[str]] = []
        for unit_id in required_challenges:
            check = summaries_by_id.get(unit_id, {}).get(
                "independent_check", {}
            )
            resolution = check.get("resolution")
            expected_challenge_rows.append(
                [
                    unit_id,
                    str(check.get("status")),
                    str(check.get("independence_level")),
                    str(check.get("challenger_verdict")),
                    str(check.get("reconciled_verdict")),
                    (
                        str(resolution).replace("\n", " ")
                        if check.get("status") == "resolved"
                        and is_substantive_string(resolution)
                        else "agreed"
                    ),
                ]
            )
        challenge_data = (
            challenge_rows[2:] if len(challenge_rows) >= 2 else []
        )
        if (
            not challenge_rows
            or challenge_rows[0] != challenge_header
            or sorted(challenge_data) != sorted(expected_challenge_rows)
        ):
            errors.append(
                "Final report Independent verification disagrees with "
                "in-scope ledgers"
            )

        expected_declared_deliverables = canonical_id_field(
            record.get("id")
            for record in report_deliverables
            if isinstance(record, dict)
            and is_nonempty_string(record.get("id"))
        )
        if report_fields.get(
            "Declared external deliverables"
        ) != expected_declared_deliverables:
            errors.append(
                "Final report Declared external deliverables field disagrees "
                "with the manifest"
            )
        deliverable_section = report_nested_section(
            scope_section, "### Declared external deliverables"
        )
        if report_deliverables:
            deliverable_rows = markdown_table_rows(deliverable_section or "")
            deliverable_header = [
                "Deliverable ID",
                "Role",
                "Path",
                "Issue IDs",
                "Overall verdict",
            ]
            expected_deliverable_rows = sorted(
                [
                    str(record.get("id")),
                    str(record.get("role")),
                    str(record.get("path")),
                    canonical_id_field(record.get("issue_ids", [])),
                    str(record.get("overall_verdict")),
                ]
                for record in report_deliverables
            )
            deliverable_data = (
                deliverable_rows[2:] if len(deliverable_rows) >= 2 else []
            )
            if (
                not deliverable_rows
                or deliverable_rows[0] != deliverable_header
                or sorted(deliverable_data) != expected_deliverable_rows
            ):
                errors.append(
                    "Final report Declared external deliverables disagree with "
                    "the manifest"
                )
        elif deliverable_section is not None and deliverable_section.strip() not in {
            "",
            "None.",
        }:
            errors.append(
                "Final report Declared external deliverables must be absent or "
                "state exactly None. when none are declared"
            )

    for unit_id, summary in summaries_by_id.items():
        links_by_step: dict[str, list[dict[str, Any]]] = defaultdict(list)
        for link in summary.get("issue_links", []):
            issue = issues_by_id.get(link.get("issue_id"))
            if issue is None:
                continue
            links_by_step[link.get("step_id")].append(issue)
            if (
                issue.get("scope") == "unit"
                and unit_id not in issue.get("affected_results", [])
            ):
                errors.append(
                    f"{issue.get('id')}: affected_results omits linked "
                    f"ledger {unit_id}"
                )
            elif (
                issue.get("scope") == "unit"
                and issue.get("affected_result") != unit_id
                and not any(
                    edge.get("dependent_unit") == unit_id
                    and link.get("step_id") in edge.get("step_ids", [])
                    and issue.get("id") in edge.get("issue_ids", [])
                    for edge in dependency_edges
                    if isinstance(edge, dict)
                )
            ):
                errors.append(
                    f"{issue.get('id')}: downstream ledger issue link "
                    f"{unit_id}:{link.get('step_id')} lacks a matching "
                    "canonical dependency edge"
                )
            if (
                is_enum_value(issue.get("status"), {"open", "deferred"})
                and issue.get("load_bearing") is True
                and (
                    (
                        issue.get("finding_status") == "defect"
                        and is_enum_value(
                            link.get("step_status"),
                            {"verified", "conditionally_verified"},
                        )
                    )
                    or (
                        issue.get("finding_status") == "inconclusive"
                        and link.get("step_status") == "verified"
                    )
                )
            ):
                errors.append(
                    f"{unit_id}:{link.get('step_id')} cannot be {link.get('step_status')} "
                    f"while load-bearing {issue.get('id')} remains {issue.get('status')}"
                )
        for link in summary.get("issue_links", []):
            if not is_enum_value(
                link.get("step_status"), {"gap", "incorrect", "unclear"}
            ):
                continue
            related = links_by_step.get(link.get("step_id"), [])
            if related and all(issue.get("status") == "resolved" for issue in related):
                errors.append(
                    f"{unit_id}:{link.get('step_id')} has a failure status but only resolved issues"
                )

    if progress_override is None:
        progress_path, progress_path_valid = canonical_artifact_path(
            root,
            "PROGRESS.json",
            "progress record",
            errors,
        )
        progress, progress_errors = (
            load_json_object(progress_path, "progress state")
            if progress_path_valid
            else ({}, [])
        )
    else:
        progress = progress_override
        progress_errors = []
    errors.extend(progress_errors)
    if not progress_errors:
        if progress.get("schema_version") != SCHEMA_VERSION:
            errors.append("PROGRESS.json has an unsupported schema_version")
        if progress.get("paper_file") != paper_value:
            errors.append("PROGRESS.json paper_file disagrees with the manifest")
        if progress.get("source_snapshot_sha256") != source_snapshot_id:
            errors.append("PROGRESS.json source_snapshot_sha256 is stale")
        if progress.get("status") != "complete":
            errors.append("PROGRESS.json status must be complete")
        if progress.get("current_pass") != 8 or not is_int(
            progress.get("current_pass")
        ):
            errors.append("PROGRESS.json current_pass must be integer 8 at finalization")
        if progress.get("active_unit") is not None:
            errors.append("PROGRESS.json active_unit must be null at finalization")
        completed_units = progress.get("completed_units")
        if not isinstance(completed_units, list) or not all(
            is_nonempty_string(item) for item in completed_units
        ):
            errors.append("PROGRESS.json completed_units must contain unit IDs")
        elif completed_units != in_scope:
            errors.append(
                "PROGRESS.json completed_units must equal in-scope units exactly"
            )
        expected_conditional = sorted(
            unit_id
            for unit_id, summary in summaries_by_id.items()
            if unit_id in in_scope
            and summary.get("declared_unit_status") == "conditionally_verified"
        )
        conditional_units = progress.get("conditional_units")
        if conditional_units != expected_conditional:
            errors.append(
                "PROGRESS.json conditional_units does not match conditional ledgers"
            )
        if progress.get("blocked_units") != {}:
            errors.append("PROGRESS.json blocked_units must be empty at finalization")
        if progress.get("in_progress_units", []) != []:
            errors.append("PROGRESS.json in_progress_units must be empty at finalization")
        if progress.get("not_started_units") != []:
            errors.append("PROGRESS.json not_started_units must be empty at finalization")
        expected_high_priority = sorted(
            issue.get("id")
            for issue in issues
            if isinstance(issue, dict)
            and is_enum_value(issue.get("status"), {"open", "deferred"})
            and is_enum_value(issue.get("severity"), {"S0", "S1"})
            and is_nonempty_string(issue.get("id"))
        )
        if progress.get("open_high_priority_issues") != expected_high_priority:
            errors.append(
                "PROGRESS.json open_high_priority_issues does not match the issue log"
            )
        expected_limits = scope.get("source_or_parser_limits")
        if progress.get("source_or_parser_limits") != expected_limits:
            errors.append(
                "PROGRESS.json source_or_parser_limits disagrees with audit scope"
            )
        if not is_substantive_string(progress.get("next_action")):
            errors.append("PROGRESS.json next_action must be substantive")

    open_load_bearing = [
        issue
        for issue in issues
        if isinstance(issue, dict)
        and is_enum_value(issue.get("severity"), ISSUE_SEVERITIES)
        and is_enum_value(issue.get("status"), {"open", "deferred"})
        and issue.get("load_bearing") is True
    ]
    unit_statuses = {
        unit_id: summary.get("declared_unit_status")
        for unit_id, summary in summaries_by_id.items()
        if unit_id in in_scope
    }
    def implementation_components(
        interface: dict[str, Any],
    ) -> tuple[Any, dict[str, Any], Any]:
        implementation = interface.get("implementation_relation")
        if not isinstance(implementation, dict):
            return None, {}, None
        comparisons = implementation.get("comparisons")
        comparison_rows = comparisons if isinstance(comparisons, list) else []
        comparison_verdicts = {
            comparison.get("to"): comparison.get("verdict")
            for comparison in comparison_rows
            if isinstance(comparison, dict)
        }
        provenance = implementation.get("execution_provenance")
        provenance_status = (
            provenance.get("status") if isinstance(provenance, dict) else None
        )
        return (
            implementation.get("inspection_status"),
            comparison_verdicts,
            provenance_status,
        )

    interface_defect = False
    interface_inconclusive = False
    for interface in interfaces.values():
        inspection_status, comparison_verdicts, provenance_status = (
            implementation_components(interface)
        )
        target_relation = interface.get("target_relation")
        target_verdict = (
            target_relation.get("verdict")
            if isinstance(target_relation, dict)
            else None
        )
        if (
            target_verdict == "mismatch"
            or (
                interface.get("implementation_required_for_claim") is True
                and "inconsistent" in comparison_verdicts.values()
            )
            or (
                interface.get("execution_provenance_required_for_claim") is True
                and provenance_status == "not_matched"
            )
        ):
            interface_defect = True
        if interface.get("load_bearing") is not True:
            continue
        if (
            is_enum_value(
                interface.get("interface_specification_status"),
                {"ambiguous", "incomplete", "not_checked"},
            )
            or is_enum_value(
                target_verdict,
                {"conditional_match", "not_assessable", "not_checked"},
            )
            or (
                interface.get("implementation_required_for_claim") is True
                and (
                    inspection_status != "inspected"
                    or comparison_verdicts.get("documented_estimator") != "consistent"
                    or comparison_verdicts.get("required_target") != "consistent"
                )
            )
            or (
                interface.get("execution_provenance_required_for_claim") is True
                and provenance_status != "matched"
            )
        ):
            interface_inconclusive = True
    for issue in open_load_bearing:
        allowed = (
            {"gap", "incorrect", "unclear", "not_checked"}
            if issue.get("finding_status") == "defect"
            else {
                "conditionally_verified",
                "gap",
                "incorrect",
                "unclear",
                "not_checked",
            }
            if issue.get("finding_status") == "inconclusive"
            else set(UNIT_STATUSES)
        )
        for unit_id in issue.get("affected_results", []):
            unit_status = unit_statuses.get(unit_id)
            if unit_status is not None and not is_enum_value(unit_status, allowed):
                errors.append(
                    f"{issue.get('id')}: load-bearing {issue.get('finding_status')} finding has not weakened affected result {unit_id}"
                )

    parser_inconclusive = False
    for warning_review in warning_reviews:
        if not isinstance(warning_review, dict):
            parser_inconclusive = True
            continue
        disposition = warning_review.get("disposition")
        if disposition == "unresolved":
            parser_inconclusive = True
            continue
        if disposition != "scope_limitation":
            continue
        affected = warning_review.get("affected_units")
        if (
            not isinstance(affected, list)
            or not affected
            or bool(
                {
                    item for item in affected if is_nonempty_string(item)
                }
                & set(in_scope)
            )
        ):
            parser_inconclusive = True
    dependency_defect = any(
        is_enum_value(edge.get("effective_status"), {"gap", "incorrect"})
        for edge in dependency_edges
    )
    dependency_inconclusive = any(
        is_enum_value(
            edge.get("effective_status"), {"conditional", "unclear", "unchecked"}
        )
        for edge in dependency_edges
    )
    has_defect = any(
        is_enum_value(status, {"gap", "incorrect"})
        for status in unit_statuses.values()
    ) or any(
        issue.get("finding_status") == "defect" for issue in open_load_bearing
    ) or interface_defect or dependency_defect or global_consistency_result.get(
        "defect", False
    ) or cross_reference_result.get("defect", False)
    has_inconclusive = any(
        is_enum_value(status, {"conditionally_verified", "unclear", "not_checked"})
        for status in unit_statuses.values()
    ) or any(
        issue.get("finding_status") == "inconclusive"
        for issue in open_load_bearing
    ) or interface_inconclusive or dependency_inconclusive or bool(
        global_consistency_result.get("inconclusive", False)
    ) or cross_reference_result.get("inconclusive", False) or parser_inconclusive
    derived_assessment = (
        "defects_found"
        if has_defect
        else "inconclusive"
        if has_inconclusive
        else "no_defect_found"
    )
    if is_enum_value(
        assessment, {"no_defect_found", "defects_found", "inconclusive"}
    ):
        if assessment != derived_assessment:
            errors.append(
                f"overall_assessment {assessment} contradicts the evidence; "
                f"expected {derived_assessment}"
            )

    if assessment == "no_defect_found":
        for unit_id, summary in summaries_by_id.items():
            if unit_id not in in_scope:
                continue
            components = summary.get("review_components", {})
            if components.get("statement_status") != "established":
                errors.append(f"{unit_id}: statement is not established")
            if not is_enum_value(
                components.get("use_site_sufficiency"),
                {"sufficient", "not_applicable"},
            ):
                errors.append(f"{unit_id}: use-site sufficiency is not established")

    if uses_html_report(manifest):
        for issue in issues_by_id.values():
            projection = canonical_issue_detail_projection(
                issue, summaries_by_id, dependency_edges, required_challenges,
                report_deliverables, assessment, interfaces=interfaces,
                global_checks=global_checks_by_aspect)
            if issue.get("status") == "resolved" and projection["closure"][0][-1] != "complete":
                errors.append(f"{issue.get('id')}: resolved issue has an incomplete recheck closure")
        if check_reports:
            errors.extend(report_module("proofcheck_release").validate(
                report_api(), root, manifest, outputs_override=report_outputs_override))

    result = {
        "audit_root": str(root),
        "schema_version": SCHEMA_VERSION,
        "assessment": assessment,
        "derived_assessment": derived_assessment,
        "source_files": len(recorded_files),
        "parser_warnings": len(fresh_warning_set),
        "inventory_units": len(unit_inventory),
        "target_units": len(target_units),
        "in_scope_units": len(in_scope),
        "ledgers": len(summaries),
        "external_results": len(external_results),
        "method_interfaces": len(interfaces),
        "issue_log": str(issue_path),
        "issues": len(issues),
        "errors": len(errors),
        "assurance_boundary": (
            "Non-formal audit only. Success means the required evidence and closure "
            "gates passed; it is not a kernel-checked proof certificate."
        ),
    }
    return errors, result


def check_audit_finalization(
    root: Path, *, progress_override: dict[str, Any] | None = None,
    check_reports: bool = True,
    manifest_override: dict[str, Any] | None = None,
    report_outputs_override: dict[str, str] | None = None,
    source_inventory_only: bool = False,
) -> tuple[list[str], dict[str, Any]]:
    """Run the full gate without allowing unreadable artifacts to crash it."""
    try:
        with gate_context_snapshot(root):
            lock_error = migration_update_lock_error(root)
            if lock_error is not None:
                return [lock_error], {
                    "audit_root": str(root.resolve()),
                    "errors": 1,
                    "read_error": lock_error,
                }
            return _check_audit_finalization(
                root, progress_override=progress_override, check_reports=check_reports,
                manifest_override=manifest_override, report_outputs_override=report_outputs_override,
                source_inventory_only=source_inventory_only,
            )
    except (TextArtifactReadError, OSError, UnicodeError, ValueError) as exc:
        message = str(exc)
        return [message], {
            "audit_root": str(root.resolve()),
            "errors": 1,
            "read_error": message,
        }


def finalization_payload_sha256(record: dict[str, Any]) -> str:
    payload = dict(record)
    payload.pop("record_payload_sha256", None)
    return canonical_sha256(payload)



def cmd_finalize(args: argparse.Namespace) -> int:
    root = args.root.resolve()
    lock_error = migration_update_lock_error(root)
    if lock_error is not None:
        raise ValueError(lock_error)
    current = unchanged_final_delivery(root)
    if current is not None:
        print(json.dumps(current, ensure_ascii=False, indent=2))
        return 0
    _, report_manifest, report_manifest_errors = load_audit_manifest(root)
    if not report_manifest_errors and uses_html_report(report_manifest):
        errors, result = report_module("proofcheck_release").finalize(report_api(), root)
        print(json.dumps(result, ensure_ascii=False, indent=2))
        for error in errors:
            print(f"ERROR: {error}", file=sys.stderr)
        return 1 if errors else 0
    view_errors: list[str] = []
    _, preflight_manifest, preflight_manifest_errors = load_audit_manifest(root)
    preflight_protocol = preflight_manifest.get("protocol")
    generated_view_contract_current = bool(
        not preflight_manifest_errors
        and preflight_manifest.get("schema_version") == SCHEMA_VERSION
        and isinstance(preflight_protocol, dict)
        and preflight_protocol.get("artifact_schema_version") == SCHEMA_VERSION
        and preflight_protocol.get("evidence_contract_version")
        == EVIDENCE_CONTRACT_VERSION
    )
    if generated_view_contract_current:
        try:
            sync_workflow_views(root)
            freshness = workflow_view_freshness(root)
            if freshness["status"] != "current":
                view_errors.append(
                    "Generated workflow views are not current: "
                    + ", ".join([*freshness["missing"], *freshness["stale"]])
                )
        except (TextArtifactReadError, OSError, UnicodeError, ValueError) as exc:
            view_errors.append(
                f"Generated workflow views could not be synchronized: {exc}"
            )
    else:
        view_errors.append(
            "Generated workflow views were not synchronized because the audit "
            "does not declare the current generated-view contract"
        )
    errors, result = check_audit_finalization(root)
    errors.extend(error for error in view_errors if error not in errors)
    _, manifest, manifest_errors = load_audit_manifest(root)
    record_path, record_path_errors = finalization_record_path(manifest, root)
    if not finalization_target_is_safe(record_path):
        raise ValueError(
            "Refusing to write through a symlinked finalization-record location"
        )
    if not manifest_errors:
        for error in record_path_errors:
            if error not in errors:
                errors.append(error)
    source_snapshot = manifest.get("source_snapshot") if not manifest_errors else None
    redirect_errors = audit_internal_redirect_errors(root)
    for error in redirect_errors:
        if error not in errors:
            errors.append(error)
    result["errors"] = len(errors)
    result["generated_views"] = (
        {"status": "failed", "errors": view_errors}
        if view_errors
        else {"status": "current", "errors": []}
    )
    artifact_manifest = (
        [] if redirect_errors else audit_state_manifest(root, record_path)
    )
    record = {
        "finalization_schema_version": 1,
        "status": "passed" if not errors else "failed",
        "generated_utc": utc_now(),
        "protocol": protocol_identity(),
        "source_snapshot_sha256": (
            source_snapshot.get("sha256")
            if isinstance(source_snapshot, dict)
            else None
        ),
        "artifact_manifest": artifact_manifest,
        "audit_state_sha256": canonical_sha256(artifact_manifest),
        "errors": errors,
    }
    record["record_payload_sha256"] = finalization_payload_sha256(record)
    atomic_write_json(record_path, record)
    result["finalization_record"] = str(record_path)
    print(json.dumps(result, ensure_ascii=False, indent=2))
    if errors:
        for error in errors:
            print(f"ERROR: {error}", file=sys.stderr)
        return 1
    return 0


def artifact_manifest_changes(
    recorded: Any, current: list[dict[str, str]]
) -> tuple[list[str], dict[str, list[str]]]:
    changes = {"added": [], "removed": [], "changed": []}
    if recorded is None:
        return [], changes
    if not isinstance(recorded, list):
        return ["FINALIZATION.json artifact_manifest must be a list"], changes
    recorded_map: dict[str, str] = {}
    errors: list[str] = []
    for index, row in enumerate(recorded, 1):
        prefix = f"FINALIZATION.json artifact_manifest[{index}]"
        if not isinstance(row, dict):
            errors.append(f"{prefix} must be an object")
            continue
        file_value = row.get("file")
        digest = row.get("sha256")
        if not is_nonempty_string(file_value) or not is_nonempty_string(digest):
            errors.append(f"{prefix} needs nonempty file and sha256 values")
            continue
        if file_value in recorded_map:
            errors.append(f"Duplicate finalization artifact: {file_value}")
        recorded_map[file_value] = digest
    current_map = {row["file"]: row["sha256"] for row in current}
    changes["added"] = sorted(set(current_map) - set(recorded_map))
    changes["removed"] = sorted(set(recorded_map) - set(current_map))
    changes["changed"] = sorted(
        path
        for path in set(recorded_map) & set(current_map)
        if recorded_map[path] != current_map[path]
    )
    return errors, changes


def check_finalization_freshness(
    root: Path, *, gate_errors: list[str] | None = None
) -> dict[str, Any]:
    root = root.resolve()
    if gate_errors is None:
        gate_errors, _ = check_audit_finalization(root)
    result: dict[str, Any] = {
        "record_status": "missing",
        "freshness": "not_applicable",
        "usable_finalization": False,
        "preflight_status": "failed" if gate_errors else "passed",
        "finalizable_now": not gate_errors,
        "record": None,
        "stale_reasons": [],
        "current_gate_errors": gate_errors,
        "artifact_changes": {"added": [], "removed": [], "changed": []},
    }
    _, manifest, manifest_errors = load_audit_manifest(root)
    if manifest_errors:
        result["record_status"] = "invalid"
        result["freshness"] = "unknown"
        result["stale_reasons"] = manifest_errors
        return result
    record_path, record_path_errors = finalization_record_path(manifest, root)
    if record_path_errors:
        result["record_status"] = "invalid"
        result["freshness"] = "unknown"
        result["stale_reasons"] = record_path_errors
        return result
    result["record"] = str(record_path)
    if not record_path.is_file():
        return result

    record, record_errors = load_json_object(record_path, "finalization record")
    if record_errors:
        result["record_status"] = "invalid"
        result["freshness"] = "unknown"
        result["stale_reasons"] = record_errors
        return result
    status = record.get("status")
    if not is_enum_value(status, {"passed", "failed"}):
        result["record_status"] = "invalid"
        result["freshness"] = "unknown"
        result["stale_reasons"] = [
            "FINALIZATION.json status must be passed or failed"
        ]
        return result
    record_schema = record.get("finalization_schema_version")
    if record_schema is not None and not (type(record_schema) is int and record_schema == 1):
        result["record_status"] = "invalid"
        result["freshness"] = "unknown"
        result["stale_reasons"] = [
            "FINALIZATION.json has an unsupported finalization_schema_version"
        ]
        return result
    if type(record_schema) is int and record_schema == 1:
        schema_errors: list[str] = []
        generated_utc = record.get("generated_utc")
        if not is_nonempty_string(generated_utc):
            schema_errors.append(
                "Schema 1 FINALIZATION.json requires generated_utc"
            )
        else:
            try:
                generated_time = datetime.fromisoformat(generated_utc)
            except ValueError:
                schema_errors.append(
                    "Schema 1 FINALIZATION.json generated_utc must be ISO 8601"
                )
            else:
                if generated_time.tzinfo is None:
                    schema_errors.append(
                        "Schema 1 FINALIZATION.json generated_utc needs a timezone"
                    )
        if not isinstance(record.get("artifact_manifest"), list):
            schema_errors.append(
                "Schema 1 FINALIZATION.json requires an artifact_manifest list"
            )
        if not is_nonempty_string(record.get("record_payload_sha256")):
            schema_errors.append(
                "Schema 1 FINALIZATION.json requires record_payload_sha256"
            )
        if schema_errors:
            result["record_status"] = "invalid"
            result["freshness"] = "unknown"
            result["stale_reasons"] = schema_errors
            return result
    result["record_status"] = status
    reasons: list[str] = []

    payload_digest = record.get("record_payload_sha256")
    if payload_digest is not None and (
        not is_nonempty_string(payload_digest)
        or payload_digest != finalization_payload_sha256(record)
    ):
        reasons.append("Finalization record payload hash does not match")

    redirect_errors = audit_internal_redirect_errors(root)
    reasons.extend(redirect_errors)
    current_artifacts = (
        [] if redirect_errors else audit_state_manifest(root, record_path)
    )
    current_state_digest = canonical_sha256(current_artifacts)
    if record.get("audit_state_sha256") != current_state_digest:
        reasons.append("Audit artifacts changed after finalization")
    artifact_errors, changes = artifact_manifest_changes(
        record.get("artifact_manifest"), current_artifacts
    )
    reasons.extend(artifact_errors)
    result["artifact_changes"] = changes

    if not protocol_matches_current(record.get("protocol")):
        reasons.append("Finalization protocol does not match the current validator")
    snapshot = manifest.get("source_snapshot")
    manifest_snapshot = snapshot.get("sha256") if isinstance(snapshot, dict) else None
    if record.get("source_snapshot_sha256") != manifest_snapshot:
        reasons.append("Finalization source snapshot does not match the manifest")

    recorded_errors = record.get("errors")
    if not isinstance(recorded_errors, list):
        reasons.append("FINALIZATION.json errors must be a list")
    elif recorded_errors != gate_errors:
        reasons.append("Current finalization-gate result differs from the recorded result")
    if status == "passed" and gate_errors:
        reasons.append("A passed finalization record no longer passes the full gate")

    result["stale_reasons"] = list(dict.fromkeys(reasons))
    result["freshness"] = "stale" if result["stale_reasons"] else "current"
    result["usable_finalization"] = (
        status == "passed"
        and result["freshness"] == "current"
        and not gate_errors
    )
    return result


FATAL_LEDGER_ERROR_MARKERS = (
    "Cannot read ledger",
    "Ledger root must be an object",
    "Missing source object",
    "Invalid source specification",
    "Unsupported ledger schema_version",
    "Unsupported evidence_contract_version",
    "Source file not found",
    "Source drift:",
    "Source now has only",
    "Invalid locked text or hash",
    "Locked source mismatch",
    "source_lines must contain exactly",
)


def is_fatal_ledger_error(error: str) -> bool:
    return any(marker in error for marker in FATAL_LEDGER_ERROR_MARKERS)


def progress_scope_units(
    root: Path, manifest: dict[str, Any], errors: list[str]
) -> list[str]:
    scope = manifest.get("audit_scope")
    if isinstance(scope, dict) and scope.get("status") == "reviewed":
        values = scope.get("in_scope_units")
        if (
            isinstance(values, list)
            and values
            and all(is_nonempty_string(value) for value in values)
            and len(values) == len(set(values))
        ):
            return list(values)
        errors.append("Reviewed audit scope needs unique nonempty in_scope_units")
        return []

    inventory_path, inventory_path_valid = manifest_canonical_artifact_path(
        manifest,
        root,
        "inventory_file",
        "proof-unit inventory",
        errors,
    )
    if not inventory_path_valid:
        return []
    inventory, inventory_errors = load_json_object(
        inventory_path, "proof-unit inventory"
    )
    errors.extend(inventory_errors)
    if inventory_errors:
        return []
    units = inventory.get("units")
    if not isinstance(units, list):
        errors.append("Proof-unit inventory must contain a units list")
        return []
    unit_ids = [
        unit.get("id")
        for unit in units
        if isinstance(unit, dict) and is_nonempty_string(unit.get("id"))
    ]
    if len(unit_ids) != len(units) or len(unit_ids) != len(set(unit_ids)):
        errors.append("Proof-unit inventory needs unique nonempty unit IDs")
        return []
    return unit_ids


def validated_blocked_units(
    recorded_progress: dict[str, Any],
    scope_units: list[str],
    errors: list[str],
) -> dict[str, Any]:
    blocked = recorded_progress.get("blocked_units", {})
    if not isinstance(blocked, dict):
        errors.append("PROGRESS.json blocked_units must be an object")
        return {}
    scope_set = set(scope_units)
    for unit_id, reason in blocked.items():
        if unit_id not in scope_set:
            errors.append(f"PROGRESS.json blocked unit is outside scope: {unit_id}")
        if not (
            is_substantive_string(reason)
            or (
                isinstance(reason, dict)
                and is_substantive_string(reason.get("reason"))
            )
        ):
            errors.append(
                f"PROGRESS.json blocked unit {unit_id} needs a substantive reason"
            )
    return dict(blocked)


def source_snapshot_freshness_errors(
    root: Path, manifest: dict[str, Any]
) -> list[str]:
    root = root.resolve()
    errors: list[str] = []
    input_kind = validate_input_provenance(manifest, root, errors, final=False)
    paper_value = manifest.get("paper_file")
    paper = (
        resolve_stored_path(paper_value, root)
        if is_nonempty_string(paper_value)
        else root / "__missing_paper__"
    )
    if not paper.is_file():
        errors.append(f"Paper source not found: {paper}")

    snapshot = manifest.get("source_snapshot")
    recorded_files: dict[Path, str] = {}
    recorded_rows: list[dict[str, str]] = []
    if not isinstance(snapshot, dict) or not isinstance(snapshot.get("files"), list):
        errors.append("Manifest source_snapshot.files must be a list")
    else:
        for index, record in enumerate(snapshot["files"], 1):
            prefix = f"source_snapshot.files[{index}]"
            if not isinstance(record, dict):
                errors.append(f"{prefix} must be an object")
                continue
            file_value = record.get("file")
            digest = record.get("sha256")
            if not is_nonempty_string(file_value) or not is_nonempty_string(digest):
                errors.append(f"{prefix} needs nonempty file and sha256 values")
                continue
            path = resolve_stored_path(file_value, root)
            if path in recorded_files:
                errors.append(f"Duplicate source snapshot entry: {path}")
            recorded_files[path] = digest
            recorded_rows.append({"file": file_value, "sha256": digest})
        snapshot_id = snapshot.get("sha256")
        if (
            not is_nonempty_string(snapshot_id)
            or snapshot_id != canonical_sha256(recorded_rows)
        ):
            errors.append("Manifest source_snapshot.sha256 is missing or inconsistent")

    additional_files, fls_path, project_root, recorded_outside = (
        parse_manifest_source_discovery(manifest, root, errors)
    )
    current_files: list[Path] = []
    provenance = manifest.get("input_provenance")
    portable_fixed = bool(
        isinstance(provenance, dict) and provenance.get("portable_sources") is True
    )
    if paper.is_file() and portable_fixed and input_kind == "latex":
        current_files, _ = rediscover_portable_source_closure(
            paper, recorded_files, additional_files, root
        )
    elif paper.is_file() and portable_fixed:
        current_files = list(recorded_files)
    elif paper.is_file():
        closure = discover_source_closure(
            paper,
            additional_files=additional_files,
            fls_file=fls_path,
            project_root=project_root or paper.parent,
        )
        current_files = closure["files"]
        if closure["outside_project_inputs"] != recorded_outside:
            errors.append(
                "source_discovery.fls.outside_project_inputs does not match "
                "the current recorder trace"
            )

    if set(recorded_files) != set(current_files):
        missing = sorted(str(path) for path in set(current_files) - set(recorded_files))
        stale = sorted(str(path) for path in set(recorded_files) - set(current_files))
        if missing:
            errors.append("Source closure has new or unrecorded files: " + ", ".join(missing))
        if stale:
            errors.append("Source closure no longer contains: " + ", ".join(stale))
    for path, digest in recorded_files.items():
        if not path.is_file():
            errors.append(f"Snapshotted source file not found: {path}")
        elif sha256_file(path) != digest:
            errors.append(f"Source drift in included file: {path}")
    return list(dict.fromkeys(errors))


def required_challenge_requirements(
    manifest: dict[str, Any], issues: Iterable[dict[str, Any]]
) -> tuple[list[str], dict[str, set[str]]]:
    """Return every in-scope unit and its severe issue triggers.

    Challenge coverage is exhaustive. Critical declarations can affect only
    work priority, never whether a proof unit receives an independent check.
    """
    scope = manifest.get("audit_scope")
    if not isinstance(scope, dict):
        return [], {}
    in_scope_value = scope.get("in_scope_units")
    in_scope = {
        unit_id
        for unit_id in in_scope_value
        if is_nonempty_string(unit_id)
    } if isinstance(in_scope_value, list) else set()
    severe_by_unit: dict[str, set[str]] = defaultdict(set)
    for issue in issues:
        if not isinstance(issue, dict) or not (
            issue.get("status") in {"open", "deferred", "resolved"}
            and issue.get("load_bearing") is True
            and issue.get("severity") in {"S0", "S1"}
        ):
            continue
        issue_id = issue.get("id")
        affected_results = issue.get("affected_results")
        if not is_nonempty_string(issue_id) or not isinstance(
            affected_results, list
        ):
            continue
        historical_origin = issue.get("historical_origin")
        historical_challenges = (
            historical_origin.get("required_challenges", [])
            if isinstance(historical_origin, dict)
            else []
        )
        promoted_units = [
            *affected_results,
            *(
                historical_challenges
                if isinstance(historical_challenges, list)
                else []
            ),
        ]
        for unit_id in promoted_units:
            if is_nonempty_string(unit_id) and unit_id in in_scope:
                severe_by_unit[unit_id].add(issue_id)
    return sorted(in_scope), dict(severe_by_unit)


def challenge_semantic_freshness_errors(
    root: Path,
    unit_id: str,
    challenge: Any,
    triggering_issue_ids: Iterable[str],
) -> list[str]:
    """Check that a challenger record binds the current neutral target packet."""
    prefix = f"In-scope unit {unit_id}"
    if not isinstance(challenge, dict):
        return [f"{prefix} independent check is malformed"]
    required_ids = sorted(set(triggering_issue_ids))
    try:
        packet = build_context_packet(root, unit_id, "challenge")
    except (OSError, UnicodeError, ValueError) as exc:
        return [
            f"{prefix} challenge context cannot be reconstructed: {exc}"
        ]

    errors: list[str] = []
    _, manifest, manifest_errors = load_audit_manifest(root)
    errors.extend(manifest_errors)
    if not manifest_errors and challenge_contract_version(manifest) >= 2:
        initial, reference, initial_errors = load_initial_challenge(root, unit_id, packet, challenge)
        errors.extend(initial_errors)
        if challenge.get("initial_response") != reference or not reference:
            errors.append(f"{prefix} must bind its preserved initial challenge response")
        response = initial.get("response")
        if isinstance(response, dict):
            for field in ("challenger_verdict", "independence_level"):
                if challenge.get(field) != response.get(field):
                    errors.append(f"{prefix} {field} differs from the initial response")
            _, ledger = packet_ledger(root, unit_id)
            if isinstance(ledger, dict):
                errors.extend(initial_conclusion_reconciliation_errors(initial, ledger, challenge))
            initial_assessments = response.get("issue_assessments")
            final_assessments = [{key: value for key, value in row.items() if key != "target_contract_sha256"}
                                 for row in challenge.get("issue_assessments", []) if isinstance(row, dict)]
            if final_assessments != initial_assessments and (not challenge.get("disagreements") or not is_substantive_string(challenge.get("resolution"))):
                errors.append(f"{prefix}: changed issue assessments require explicit disagreement and resolution")
    if challenge.get("challenge_context_sha256") != packet.get(
        "context_binding_sha256"
    ):
        errors.append(f"{prefix} challenger context is stale")

    trigger_rows = packet.get("issue_triggers")
    trigger_rows = trigger_rows if isinstance(trigger_rows, list) else []
    trigger_ids = [
        str(row.get("id"))
        for row in trigger_rows
        if isinstance(row, dict) and is_nonempty_string(row.get("id"))
    ]
    if sorted(trigger_ids) != required_ids:
        errors.append(
            f"{prefix} challenge packet trigger set disagrees with current "
            "severe triggering issues"
        )
    trigger_by_id = {
        str(row.get("id")): row
        for row in trigger_rows
        if isinstance(row, dict) and is_nonempty_string(row.get("id"))
    }

    assessment_rows = challenge.get("issue_assessments")
    assessment_rows = assessment_rows if isinstance(assessment_rows, list) else []
    assessment_ids = [
        str(row.get("issue_id"))
        for row in assessment_rows
        if isinstance(row, dict) and is_nonempty_string(row.get("issue_id"))
    ]
    if sorted(assessment_ids) != required_ids:
        errors.append(
            f"{prefix} issue_assessments do not cover exactly its "
            "current severe triggering issues"
        )
    assessment_by_id = {
        str(row.get("issue_id")): row
        for row in assessment_rows
        if isinstance(row, dict) and is_nonempty_string(row.get("issue_id"))
    }
    for issue_id in required_ids:
        trigger = trigger_by_id.get(issue_id)
        assessment = assessment_by_id.get(issue_id)
        if (
            not isinstance(trigger, dict)
            or not isinstance(assessment, dict)
            or assessment.get("target_contract_sha256")
            != trigger.get("target_contract_sha256")
        ):
            errors.append(
                f"{prefix} challenger assessment for {issue_id} is stale "
                "or does not bind its target"
            )
    return errors


def independent_checks_complete(
    root: Path,
    manifest: dict[str, Any],
    summaries_by_id: dict[str, dict[str, Any]],
    issues: list[dict[str, Any]],
) -> bool:
    scope = manifest.get("audit_scope")
    if not isinstance(scope, dict) or not isinstance(
        scope.get("in_scope_units"), list
    ):
        return False
    required_units, severe_by_unit = required_challenge_requirements(
        manifest, issues
    )
    if not required_units:
        return False
    source_snapshot = manifest.get("source_snapshot")
    snapshot_id = (
        source_snapshot.get("sha256")
        if isinstance(source_snapshot, dict)
        else None
    )
    for unit_id in required_units:
        summary = summaries_by_id.get(unit_id)
        check = summary.get("independent_check") if isinstance(summary, dict) else None
        if (
            not isinstance(check, dict)
            or check.get("required") is not True
            or check.get("status") not in {"agreed", "resolved"}
            or check.get("covered_issue_ids")
            != sorted(severe_by_unit.get(unit_id, set()))
            or check.get("source_snapshot_sha256") != snapshot_id
        ):
            return False
        artifact = check.get("artifact")
        if not is_nonempty_string(artifact):
            return False
        artifact_errors: list[str] = []
        artifact_path, artifact_path_valid = canonical_challenge_artifact_path(
            root,
            artifact,
            f"In-scope unit {unit_id} challenger artifact",
            artifact_errors,
        )
        if (
            not artifact_path_valid
            or artifact_path is None
            or not artifact_path.is_file()
            or artifact_path.stat().st_size == 0
            or check.get("challenge_artifact_sha256") != sha256_file(artifact_path)
            or challenge_artifact_binding_errors(
                artifact_path, unit_id, check
            )
        ):
            return False
        if challenge_semantic_freshness_errors(
            root,
            unit_id,
            check,
            severe_by_unit.get(unit_id, set()),
        ):
            return False
    return True


def derived_current_pass(
    root: Path,
    manifest: dict[str, Any],
    scope_units: list[str],
    normalized_units: list[str],
    incomplete_units: list[str],
    blocked_units: dict[str, Any],
    summaries_by_id: dict[str, dict[str, Any]],
    issues: list[dict[str, Any]],
) -> int:
    scope = manifest.get("audit_scope")
    if not isinstance(scope, dict):
        return 0
    if scope.get("status") != "reviewed":
        return 1

    completion = manifest.get("completion")
    if (
        not isinstance(completion, dict)
        or completion.get("inventory_reviewed") is not True
        or completion.get("parser_warnings_reviewed") is not True
    ):
        return 2
    if set(scope_units) - set(normalized_units):
        return 3
    if incomplete_units or blocked_units:
        return 4

    global_pass = completion.get("global_consistency_pass")
    adversarial_pass = completion.get("adversarial_pass")
    completed_passes = {"completed", "completed_with_findings", "not_applicable"}
    if (
        completion.get("dependency_registry_reviewed") is not True
        or completion.get("method_interface_registry_reviewed") is not True
        or not isinstance(global_pass, dict)
        or global_pass.get("status") not in completed_passes
        or not isinstance(adversarial_pass, dict)
        or adversarial_pass.get("status") not in completed_passes
    ):
        return 5
    if not independent_checks_complete(
        root, manifest, summaries_by_id, issues
    ):
        return 6
    if completion.get("final_report_ready") is not True:
        return 7
    return 8


def derive_progress_records(
    root: Path,
    manifest: dict[str, Any],
    recorded_progress: dict[str, Any],
    issues: list[dict[str, Any]],
) -> tuple[dict[str, Any], list[str]]:
    errors: list[str] = []
    errors.extend(source_snapshot_freshness_errors(root, manifest))
    scope_units = progress_scope_units(root, manifest, errors)
    blocked_units = validated_blocked_units(recorded_progress, scope_units, errors)
    scope_set = set(scope_units)

    summaries_by_id: dict[str, dict[str, Any]] = {}
    stages: dict[str, str] = {}
    fatal_ledger_errors: list[str] = []
    for ledger_path in live_local_check_artifacts(root, ".ledger.json"):
        ledger_errors, summary = check_ledger_data(ledger_path, True)
        if not summary:
            fatal_ledger_errors.extend(
                f"{ledger_path}: {error}" for error in ledger_errors
            )
            continue
        unit_id = summary.get("unit_id")
        if not is_nonempty_string(unit_id):
            fatal_ledger_errors.append(f"{ledger_path}: ledger has no valid unit_id")
            continue
        if unit_id in summaries_by_id:
            fatal_ledger_errors.append(f"Duplicate ledger unit_id: {unit_id}")
            continue
        summaries_by_id[unit_id] = summary
        fatal_ledger_errors.extend(
            f"{ledger_path}: {error}"
            for error in ledger_errors
            if is_fatal_ledger_error(error)
        )
        if not ledger_errors and summary.get("declared_unit_status") != "not_checked":
            stages[unit_id] = "completed"
        elif (
            summary.get("steps") == 0
            and summary.get("declared_unit_status") == "not_checked"
        ):
            stages[unit_id] = "not_started"
        else:
            stages[unit_id] = "in_progress"

    if (
        isinstance(manifest.get("audit_scope"), dict)
        and manifest["audit_scope"].get("status") == "reviewed"
    ):
        extra_units = set(summaries_by_id) - scope_set
        if extra_units:
            errors.append(
                "Ledgers exist outside reviewed scope: "
                + ", ".join(sorted(extra_units))
            )

    completed_units: list[str] = []
    conditional_units: list[str] = []
    in_progress_units: list[str] = []
    not_started_units: list[str] = []
    for unit_id in scope_units:
        if unit_id in blocked_units:
            continue
        stage = stages.get(unit_id, "not_started")
        if stage == "completed":
            completed_units.append(unit_id)
            if (
                summaries_by_id[unit_id].get("declared_unit_status")
                == "conditionally_verified"
            ):
                conditional_units.append(unit_id)
        elif stage == "in_progress":
            in_progress_units.append(unit_id)
        else:
            not_started_units.append(unit_id)

    conditional_units.sort()
    normalized_units = [
        unit_id
        for unit_id in scope_units
        if summaries_by_id.get(unit_id, {}).get("obligation_ready") is True
    ]
    incomplete_units = in_progress_units + not_started_units
    current_pass = derived_current_pass(
        root,
        manifest,
        scope_units,
        normalized_units,
        incomplete_units,
        blocked_units,
        summaries_by_id,
        issues,
    )
    completion = manifest.get("completion")
    final_report_ready = (
        isinstance(completion, dict)
        and completion.get("final_report_ready") is True
    )
    active_unit = recorded_progress.get("active_unit")
    ready_for_completion = (
        current_pass == 8
        and final_report_ready
        and not incomplete_units
        and not blocked_units
        and active_unit is None
    )
    source_snapshot = manifest.get("source_snapshot")
    source_snapshot_sha256 = (
        source_snapshot.get("sha256") if isinstance(source_snapshot, dict) else None
    )
    scope = manifest.get("audit_scope")
    source_limits = (
        scope.get("source_or_parser_limits", [])
        if isinstance(scope, dict)
        else []
    )
    open_high_priority = sorted(
        issue.get("id")
        for issue in issues
        if isinstance(issue, dict)
        and issue.get("status") in {"open", "deferred"}
        and issue.get("severity") in {"S0", "S1"}
        and is_nonempty_string(issue.get("id"))
    )
    completion_gate_errors: list[str] = []
    reusable_full_gate_errors: list[str] | None = None
    if ready_for_completion and not errors and not fatal_ledger_errors:
        candidate_progress = {
            "schema_version": SCHEMA_VERSION,
            "paper_file": manifest.get("paper_file"),
            "source_snapshot_sha256": source_snapshot_sha256,
            "status": "complete",
            "current_pass": current_pass,
            "active_unit": active_unit,
            "completed_units": completed_units,
            "conditional_units": conditional_units,
            "in_progress_units": in_progress_units,
            "blocked_units": blocked_units,
            "not_started_units": not_started_units,
            "open_high_priority_issues": open_high_priority,
            "source_or_parser_limits": source_limits,
            "next_action": recorded_progress.get("next_action"),
            "updated_utc": recorded_progress.get("updated_utc"),
        }
        completion_gate_errors, _ = check_audit_finalization(
            root, progress_override=candidate_progress
        )
        ready_for_completion = not completion_gate_errors
        if candidate_progress == recorded_progress:
            # The override equals the loaded record byte-for-byte, so this
            # gate result is exactly what a plain gate on the same state
            # returns; callers may reuse it instead of running a second one.
            reusable_full_gate_errors = completion_gate_errors
    elif ready_for_completion:
        ready_for_completion = False

    expected_status = (
        "complete"
        if ready_for_completion
        else "bootstrap"
        if current_pass == 0
        else "in_progress"
    )
    errors.extend(fatal_ledger_errors)
    return (
        {
            "scope_units": scope_units,
            "normalized_units": normalized_units,
            "completed_units": completed_units,
            "conditional_units": conditional_units,
            "in_progress_units": in_progress_units,
            "not_started_units": not_started_units,
            "blocked_units": blocked_units,
            "open_high_priority_issues": open_high_priority,
            "source_or_parser_limits": source_limits,
            "source_snapshot_sha256": source_snapshot_sha256,
            "current_pass": current_pass,
            "expected_status": expected_status,
            "completion_gate_errors": completion_gate_errors,
            "reusable_full_gate_errors": reusable_full_gate_errors,
            "fatal_ledger_errors": fatal_ledger_errors,
        },
        errors,
    )


def progress_drift(
    manifest: dict[str, Any],
    recorded: dict[str, Any],
    derived: dict[str, Any],
) -> list[str]:
    drift: list[str] = []
    expected_values = {
        "paper_file": manifest.get("paper_file"),
        "source_snapshot_sha256": derived.get("source_snapshot_sha256"),
        "status": derived.get("expected_status"),
        "current_pass": derived.get("current_pass"),
        "completed_units": derived.get("completed_units"),
        "conditional_units": derived.get("conditional_units"),
        "in_progress_units": derived.get("in_progress_units"),
        "not_started_units": derived.get("not_started_units"),
        "blocked_units": derived.get("blocked_units"),
        "open_high_priority_issues": derived.get("open_high_priority_issues"),
        "source_or_parser_limits": derived.get("source_or_parser_limits"),
    }
    if recorded.get("schema_version") != SCHEMA_VERSION:
        drift.append(
            f"schema_version: recorded={recorded.get('schema_version')!r}, "
            f"expected={SCHEMA_VERSION!r}"
        )
    for field, expected in expected_values.items():
        actual = (
            []
            if field == "in_progress_units" and field not in recorded
            else recorded.get(field)
        )
        if actual != expected:
            drift.append(
                f"{field}: recorded={compact_json_value(actual)}, "
                f"expected={compact_json_value(expected)}"
            )
    active_unit = recorded.get("active_unit")
    if active_unit is not None and active_unit not in derived.get("scope_units", []):
        drift.append(f"active_unit is outside scope: {active_unit!r}")
    elif active_unit in derived.get("completed_units", []):
        drift.append(f"active_unit is already completed: {active_unit!r}")
    if not is_substantive_string(recorded.get("next_action")):
        drift.append("next_action is missing or non-substantive")
    return drift


STATUS_PRIORITY_ERROR_MARKERS = (
    "source drift",
    "source closure",
    "snapshotted source file",
    "finalization requires at least one proof-unit ledger",
    "in-scope units missing ledgers",
    "progress.json",
    "final report",
    "dependency registry",
    "issue_log.json",
)


def bounded_errors(
    errors: list[str],
    limit: int = 24,
    preferred_markers: tuple[str, ...] = (),
) -> tuple[list[str], int]:
    if len(errors) <= limit:
        return list(errors), 0
    preferred_indices = [
        index
        for marker in preferred_markers
        for index, error in enumerate(errors)
        if marker in error.lower()
    ]
    selected_indices: list[int] = []
    seen: set[int] = set()
    for index in [*preferred_indices, *range(len(errors))]:
        if index in seen:
            continue
        selected_indices.append(index)
        seen.add(index)
        if len(selected_indices) == limit:
            break
    visible = [errors[index] for index in selected_indices]
    omitted = len(errors) - len(visible)
    return (
        [
            *visible,
            f"{omitted} additional errors omitted; rerun status --verbose.",
        ],
        omitted,
    )


def cmd_checkpoint(args: argparse.Namespace) -> int:
    root = args.root.resolve()
    lock_error = migration_update_lock_error(root)
    if lock_error is not None:
        raise ValueError(lock_error)
    current = unchanged_final_delivery(root)
    if current is not None:
        recorded, errors = load_json_object(root / "PROGRESS.json", "progress state")
        if errors:
            raise ValueError("; ".join(errors))
        current.update({key: recorded.get(key) for key in (
            "status", "current_pass", "active_unit", "completed_units", "next_action")})
        current["note"] = "Delivered audit is unchanged. Use a working copy for deliberate repairs."
        print(json.dumps(current, ensure_ascii=False, indent=2))
        return 0
    redirect_errors = audit_internal_redirect_errors(root)
    if redirect_errors:
        raise ValueError("; ".join(redirect_errors))
    _, manifest, manifest_errors = load_audit_manifest(root)
    if manifest_errors:
        raise ValueError("; ".join(manifest_errors))
    progress_path_errors: list[str] = []
    progress_path, progress_path_valid = canonical_artifact_path(
        root,
        "PROGRESS.json",
        "progress record",
        progress_path_errors,
    )
    if not progress_path_valid:
        raise ValueError("; ".join(progress_path_errors))
    recorded, progress_errors = load_json_object(progress_path, "progress state")
    if progress_errors:
        raise ValueError("; ".join(progress_errors))
    _, issues, _, issue_errors = load_issue_log(root)
    if issue_errors:
        raise ValueError("; ".join(issue_errors))

    clear_active = bool(getattr(args, "clear_active_unit", False))
    active_unit = getattr(args, "active_unit", None)
    if clear_active:
        active_unit = None
    elif not is_nonempty_string(active_unit):
        raise ValueError(
            "checkpoint requires --active-unit UNIT or --clear-active-unit"
        )
    next_action = getattr(args, "next_action", None)
    if not is_substantive_string(next_action):
        raise ValueError("checkpoint --next-action must be substantive")
    checkpoint_time = utc_now()

    staged_record = dict(recorded)
    staged_record["active_unit"] = active_unit
    staged_record["next_action"] = next_action.strip()
    staged_record["updated_utc"] = checkpoint_time
    derived, derive_errors = derive_progress_records(
        root, manifest, staged_record, issues
    )
    if derive_errors:
        concise, omitted = bounded_errors(derive_errors, 8)
        suffix = f"; {omitted} additional errors" if omitted else ""
        raise ValueError("Cannot checkpoint: " + "; ".join(concise) + suffix)
    if active_unit is not None and active_unit not in derived["scope_units"]:
        raise ValueError(f"checkpoint active unit is outside scope: {active_unit}")
    if active_unit is not None and active_unit in derived["completed_units"]:
        raise ValueError(
            f"checkpoint active unit is already completed: {active_unit}"
        )

    updated = dict(recorded)
    updated.update(
        {
            "schema_version": SCHEMA_VERSION,
            "paper_file": manifest.get("paper_file"),
            "source_snapshot_sha256": derived["source_snapshot_sha256"],
            "status": derived["expected_status"],
            "current_pass": derived["current_pass"],
            "active_unit": active_unit,
            "completed_units": derived["completed_units"],
            "conditional_units": derived["conditional_units"],
            "in_progress_units": derived["in_progress_units"],
            "blocked_units": derived["blocked_units"],
            "not_started_units": derived["not_started_units"],
            "open_high_priority_issues": derived["open_high_priority_issues"],
            "source_or_parser_limits": derived["source_or_parser_limits"],
            "next_action": staged_record["next_action"],
            "updated_utc": checkpoint_time,
        }
    )
    view_records = load_workflow_records(root)
    view_records["progress"] = updated
    rendered_views = render_workflow_views(view_records)
    view_writes: list[tuple[Path, str]] = []
    unchanged_views: list[str] = []
    for relative, text in rendered_views.items():
        view_path = root / Path(relative)
        if view_path.is_file() and read_text(view_path) == text:
            unchanged_views.append(relative)
        else:
            view_writes.append((view_path, text))
    transactional_write_texts(
        [
            (
                progress_path,
                json.dumps(updated, ensure_ascii=False, indent=2) + "\n",
            ),
            *view_writes,
        ]
    )
    view_sync = {
        "status": "synchronized",
        "changed": [
            path.relative_to(root).as_posix() for path, _ in view_writes
        ],
        "unchanged": unchanged_views,
    }
    print(
        json.dumps(
            {
                "audit_root": str(root),
                "progress_file": str(progress_path),
                "status": updated["status"],
                "current_pass": updated["current_pass"],
                "active_unit": updated["active_unit"],
                "completed_units": updated["completed_units"],
                "conditional_units": updated["conditional_units"],
                "in_progress_units": updated["in_progress_units"],
                "not_started_units": updated["not_started_units"],
                "next_action": updated["next_action"],
                "generated_views": view_sync,
            },
            ensure_ascii=False,
            indent=2,
        )
    )
    return 0


def status_protocol_view(
    manifest: dict[str, Any], summaries: Iterable[dict[str, Any]]
) -> dict[str, Any]:
    protocol = manifest.get("protocol")
    if not isinstance(protocol, dict):
        protocol = {}
    identity = protocol_identity()
    recorded = {
        field: protocol.get(field)
        for field in identity
        if field != "validator_sha256"
    }
    current = {
        field: value
        for field, value in identity.items()
        if field != "validator_sha256"
    }
    recorded_validator = protocol.get("validator_sha256")
    current_validator = identity["validator_sha256"]
    legacy = (
        manifest.get("schema_version") == LEGACY_SCHEMA_VERSION
        and recorded["artifact_schema_version"] == LEGACY_SCHEMA_VERSION
        and recorded["evidence_contract_version"]
        == LEGACY_EVIDENCE_CONTRACT_VERSION
        and recorded["closure_contract_version"]
        == LEGACY_CLOSURE_CONTRACT_VERSION
    )
    evidence_upgrade = (
        manifest.get("schema_version") == SCHEMA_VERSION
        and recorded["artifact_schema_version"] == SCHEMA_VERSION
        and recorded["evidence_contract_version"]
        == PREVIOUS_EVIDENCE_CONTRACT_VERSION
        and recorded["closure_contract_version"]
        in {CLOSURE_CONTRACT_VERSION, PREVIOUS_CLOSURE_CONTRACT_VERSION}
    )
    closure_upgrade = (
        manifest.get("schema_version") == SCHEMA_VERSION
        and recorded["artifact_schema_version"] == SCHEMA_VERSION
        and recorded["evidence_contract_version"] == EVIDENCE_CONTRACT_VERSION
        and recorded["closure_contract_version"]
        == PREVIOUS_CLOSURE_CONTRACT_VERSION
    )
    legacy_ledgers = sorted(
        str(summary.get("ledger"))
        for summary in summaries
        if isinstance(summary, dict)
        and (
            summary.get("schema_version") == LEGACY_SCHEMA_VERSION
            or summary.get("evidence_contract_version")
            == LEGACY_EVIDENCE_CONTRACT_VERSION
        )
        and is_nonempty_string(summary.get("ledger"))
    )
    contracts_current = manifest.get("schema_version") == SCHEMA_VERSION and all(
        recorded[field] == current[field]
        for field in (
            "artifact_schema_version",
            "evidence_contract_version",
            "closure_contract_version",
            "method_interface_schema_version",
        )
    )
    # Full protocol identity, exactly what finalization enforces; a release
    # bump (skill_version and validator hash) with unchanged contracts is the
    # one drift revalidate-protocol repairs mechanically.
    versions_current = (
        contracts_current
        and recorded["skill_name"] == current["skill_name"]
        and recorded["skill_version"] == current["skill_version"]
        and recorded_validator == current_validator
    )
    release_identity_well_formed = bool(
        is_nonempty_string(recorded["skill_version"])
        and isinstance(recorded_validator, str)
        and SHA256_RE.fullmatch(recorded_validator)
    )
    validator_revalidation_required = bool(
        contracts_current
        and recorded["skill_name"] == current["skill_name"]
        and release_identity_well_formed
        and not versions_current
    )
    status = (
        "upgrade_required"
        if legacy
        else "evidence_upgrade_required"
        if evidence_upgrade
        else "closure_upgrade_required"
        if closure_upgrade
        else "validator_revalidation_required"
        if validator_revalidation_required
        else "current"
        if versions_current
        else "mismatch"
    )
    if legacy:
        next_action = (
            "Run migrate-ledger for every schema-4 ledger, rebuild the audit "
            "records under schema 5, and manually recheck every proof before "
            "finalization."
        )
    elif evidence_upgrade:
        next_action = (
            "Run migrate-evidence --root <audit-root>. Then author the "
            "evidence-contract-5 records the gates will demand: a "
            "failure.computation for every counterexample or contradiction "
            "failure, a repair_search on every S0 or S1 issue, repair-cost "
            "fields on every suggested change, and source-anchored step "
            "evidence. Recheck the affected ledgers, run migrate-closure if "
            "the closure contract is still "
            f"{PREVIOUS_CLOSURE_CONTRACT_VERSION}, and rerun finalization."
        )
    elif closure_upgrade:
        next_action = (
            "Run migrate-closure --root <audit-root>. Then manually bind every "
            "pending load-bearing citation key, refresh the affected external "
            "contract hashes, review the dependency registry, and rerun finalization."
        )
    elif validator_revalidation_required:
        next_action = (
            "Run revalidate-protocol after resolving any reported source, "
            "record, or ledger errors; it stamps the current skill version "
            "and validator hash. Then rerun status and finalization."
        )
    elif status == "mismatch":
        next_action = (
            "The recorded protocol identity is malformed or incompatible with the "
            "current validator. Re-scaffold or use the documented migration "
            "workflow, then manually recheck affected records."
        )
    else:
        next_action = "Continue the current audit workflow."
    return {
        "status": status,
        "recorded": recorded,
        "current": current,
        "recorded_validator_sha256": recorded_validator,
        "current_validator_sha256": current_validator,
        "legacy_ledgers": legacy_ledgers,
        "next_action": next_action,
    }


def status_markdown(data: dict[str, Any]) -> str:
    finalization = data["finalization"]
    progress = data["progress"]
    rows = [
        "# Proof-Check Status",
        "",
        f"- Audit root: {escape_markdown(data['audit_root'])}",
        f"- Workflow state: {data['workflow_state']}",
        f"- Audit complete: {str(data['audit_complete']).lower()}",
        f"- Delivery status: {data['delivery_status']}",
        f"- Finalization-gate errors: {data['finalization_gate_error_count']}",
        f"- Candidate completion-gate errors: {progress.get('candidate_completion_gate_error_count', 0)}",
        f"- Report integrity: {data['report_integrity']['status']}",
        f"- Generated views: {data['generated_views']['status']}",
        f"- Active unit: {escape_markdown(progress.get('active_unit') or 'none')}",
        f"- Current pass: {progress.get('current_pass')}",
        f"- Next action: {escape_markdown(progress.get('next_action') or 'none')}",
        f"- Normalized units: {len(progress.get('normalized_units', []))}",
        f"- Completed units: {len(progress.get('completed_units', []))}",
        f"- Conditional units: {len(progress.get('conditional_units', []))}",
        f"- In-progress units: {len(progress.get('in_progress_units', []))}",
        f"- Not-started units: {len(progress.get('not_started_units', []))}",
        f"- Ledgers: {data['ledgers']}",
        f"- Ledger validation errors: {data['ledger_errors']}",
        f"- Issues: {data['issues']}",
        f"- Finalization record status: {finalization['record_status']}",
        f"- Finalization freshness: {finalization['freshness']}",
        f"- Usable finalization: {str(finalization['usable_finalization']).lower()}",
        f"- Preflight status: {finalization['preflight_status']}",
        f"- Finalizable now: {str(finalization['finalizable_now']).lower()}",
        "",
        "## Unit statuses",
        "",
        "| Status | Count |",
        "|---|---|",
    ]
    rows.extend(
        f"| {status} | {count} |"
        for status, count in sorted(data["unit_statuses"].items())
    )
    rows.append("")
    protocol = data.get("protocol")
    if isinstance(protocol, dict) and protocol.get("status") in {
        "upgrade_required",
        "evidence_upgrade_required",
        "closure_upgrade_required",
        "validator_revalidation_required",
        "mismatch",
    }:
        heading = (
            "Protocol upgrade required"
            if protocol.get("status") == "upgrade_required"
            else "Evidence contract upgrade required"
            if protocol.get("status") == "evidence_upgrade_required"
            else "Closure contract upgrade required"
            if protocol.get("status") == "closure_upgrade_required"
            else (
                "Release identity revalidation required"
                if protocol.get("status") == "validator_revalidation_required"
                else "Protocol mismatch"
            )
        )
        rows.extend(
            [
                f"## {heading}",
                "",
                f"- Recorded protocol: {escape_markdown(compact_json_value(protocol.get('recorded')))}",
                f"- Current protocol: {escape_markdown(compact_json_value(protocol.get('current')))}",
                f"- Recorded validator SHA256: {escape_markdown(protocol.get('recorded_validator_sha256'))}",
                f"- Current validator SHA256: {escape_markdown(protocol.get('current_validator_sha256'))}",
                f"- Next action: {escape_markdown(protocol.get('next_action'))}",
                "",
            ]
        )
    if progress.get("drift"):
        rows.extend(["## Checkpoint drift", ""])
        rows.extend(f"- {escape_markdown(item)}" for item in progress["drift"])
        rows.append("")
    if progress.get("in_progress_units"):
        rows.extend(["## In-progress units", ""])
        rows.extend(
            f"- {escape_markdown(unit_id)}"
            for unit_id in progress["in_progress_units"]
        )
        rows.append("")
    if progress.get("not_started_units"):
        rows.extend(["## Not-started units", ""])
        rows.extend(
            f"- {escape_markdown(unit_id)}"
            for unit_id in progress["not_started_units"]
        )
        rows.append("")
    if data["invalid_ledgers"]:
        rows.extend(["## Ledgers requiring work", ""])
        rows.extend(f"- {escape_markdown(path)}" for path in data["invalid_ledgers"])
        rows.append("")
    if data.get("structural_errors"):
        rows.extend(["## Malformed or stale state", ""])
        rows.extend(
            f"- {escape_markdown(error)}" for error in data["structural_errors"]
        )
        rows.append("")
    if finalization["stale_reasons"]:
        rows.extend(["## Finalization problems", ""])
        rows.extend(
            f"- {escape_markdown(reason)}"
            for reason in finalization["stale_reasons"]
        )
        rows.append("")
    if finalization["current_gate_errors"]:
        rows.extend(["## Current finalization-gate errors", ""])
        rows.extend(
            f"- {escape_markdown(error)}"
            for error in finalization["current_gate_errors"]
        )
        rows.append("")
    changes = finalization["artifact_changes"]
    if any(changes.values()):
        rows.extend(["## Changed audit artifacts", ""])
        for kind in ("added", "removed", "changed"):
            for path in changes[kind]:
                rows.append(f"- {kind}: {escape_markdown(path)}")
        rows.append("")
    return "\n".join(rows)


def cmd_status(args: argparse.Namespace) -> int:
    root = args.root.resolve()
    lock_error = migration_update_lock_error(root)
    if lock_error is not None:
        raise ValueError(lock_error)
    structural_errors: list[str] = audit_internal_redirect_errors(root)
    manifest_path, manifest_path_valid = canonical_artifact_path(
        root, "AUDIT_MANIFEST.json", "audit manifest", structural_errors
    )
    manifest, manifest_errors = (
        load_json_object(manifest_path, "audit manifest")
        if manifest_path_valid
        else ({}, [])
    )
    structural_errors.extend(manifest_errors)
    progress_path, progress_path_valid = canonical_artifact_path(
        root, "PROGRESS.json", "progress record", structural_errors
    )
    recorded_progress, progress_read_errors = (
        load_json_object(progress_path, "progress state")
        if progress_path_valid
        else ({}, [])
    )
    structural_errors.extend(progress_read_errors)
    _, issues, _, issue_read_errors = load_issue_log(root)
    structural_errors.extend(issue_read_errors)
    ledger_errors, summaries, _ = audit_ledgers(root, False)
    if not manifest_errors and manifest_path_valid:
        for field, label in (
            ("inventory_file", "proof-unit inventory"),
            ("dependency_registry", "dependency registry"),
            ("method_interface_registry", "method-interface registry"),
        ):
            manifest_canonical_artifact_path(
                manifest, root, field, label, structural_errors
            )
    if (
        manifest_errors
        or progress_read_errors
        or not manifest_path_valid
        or not progress_path_valid
    ):
        derived = {
            "normalized_units": [],
            "completed_units": [],
            "conditional_units": [],
            "in_progress_units": [],
            "not_started_units": [],
            "current_pass": None,
            "completion_gate_errors": [],
            "fatal_ledger_errors": [],
        }
        drift: list[str] = []
    else:
        try:
            derived, derive_errors = derive_progress_records(
                root, manifest, recorded_progress, issues
            )
        except (TextArtifactReadError, OSError, UnicodeError, ValueError) as exc:
            structural_errors.append(f"Cannot derive progress safely: {exc}")
            derived = {
                "normalized_units": [],
                "completed_units": [],
                "conditional_units": [],
                "in_progress_units": [],
                "not_started_units": [],
                "current_pass": None,
                "completion_gate_errors": [],
                "fatal_ledger_errors": [],
            }
            drift = []
        else:
            structural_errors.extend(derive_errors)
            drift = progress_drift(manifest, recorded_progress, derived)

    report_deliverables_value = manifest.get("report_deliverables")
    undeclared_report_files = undeclared_report_markdown_files(
        report_deliverables_value, root
    )
    for report_path in undeclared_report_files:
        error = undeclared_report_error(report_path)
        if error not in structural_errors:
            structural_errors.append(error)
    canonical_report = root / preferred_report_path(manifest)
    canonical_report_scaffold = uses_html_report(manifest) and manifest.get("report_release", {}).get("status") != "FINAL"
    prematurely_unmarked_report = False
    invalid_nonfinal_report_title = False
    if canonical_report.is_file() and not uses_html_report(manifest):
        try:
            canonical_report_text = active_markdown_text(
                read_text(canonical_report)
            )
            canonical_report_scaffold = contains_report_scaffold_marker(
                canonical_report_text
            )
            completion = manifest.get("completion")
            report_ready = bool(
                isinstance(completion, dict)
                and completion.get("final_report_ready") is True
            )
            prematurely_unmarked_report = bool(
                not canonical_report_scaffold and not report_ready
            )
            if prematurely_unmarked_report:
                structural_errors.append(
                    "Final report removed the NONFINAL scaffold marker before "
                    "completion.final_report_ready is true"
                )
            invalid_nonfinal_report_title = bool(
                not report_ready
                and not report_has_exact_title(
                    canonical_report_text, WORKING_REPORT_TITLE
                )
            )
            if invalid_nonfinal_report_title:
                structural_errors.append(
                    "Nonfinal report must use the working title as its sole H1: "
                    f"{WORKING_REPORT_TITLE}"
                )
        except TextArtifactReadError as exc:
            structural_errors.append(str(exc))

    try:
        generated_views = workflow_view_freshness(root)
    except (TextArtifactReadError, OSError, UnicodeError, ValueError) as exc:
        generated_views = {
            "status": "unavailable",
            "missing": [],
            "stale": [],
            "errors": [str(exc)],
        }
    finalization = check_finalization_freshness(
        root, gate_errors=derived.get("reusable_full_gate_errors")
    )
    protocol_view = status_protocol_view(manifest, summaries)
    protocol_registry_errors: list[str] = []
    if (
        protocol_view["status"]
        in {"evidence_upgrade_required", "closure_upgrade_required"}
        and not manifest_errors
    ):
        protocol_registry_path, protocol_registry_path_valid = (
            manifest_canonical_artifact_path(
                manifest,
                root,
                "dependency_registry",
                "dependency registry",
                protocol_registry_errors,
            )
        )
        protocol_registry, protocol_registry_read_errors = (
            load_json_object(protocol_registry_path, "dependency registry")
            if protocol_registry_path_valid
            else ({}, [])
        )
        protocol_registry_errors.extend(protocol_registry_read_errors)
        if protocol_registry_path_valid and not protocol_registry_read_errors:
            recorded_protocol = manifest.get("protocol")
            recorded_protocol = (
                recorded_protocol if isinstance(recorded_protocol, dict) else {}
            )
            if protocol_registry.get("schema_version") != recorded_protocol.get(
                "artifact_schema_version"
            ):
                protocol_registry_errors.append(
                    "Dependency registry schema_version does not match the "
                    "manifest protocol"
                )
            if protocol_registry.get(
                "closure_contract_version"
            ) != recorded_protocol.get("closure_contract_version"):
                protocol_registry_errors.append(
                    "Dependency registry closure_contract_version does not "
                    "match the manifest protocol"
                )
    for error in protocol_registry_errors:
        if error not in structural_errors:
            structural_errors.append(error)
    protocol_mismatch = protocol_view["status"] == "mismatch"
    if protocol_mismatch:
        structural_errors.append(
            "Manifest schema or contract identity is incompatible with the "
            "current validator."
        )
    protocol_source_errors: list[str] = []
    if (
        protocol_view["status"]
        in {
            "upgrade_required",
            "evidence_upgrade_required",
            "closure_upgrade_required",
            "validator_revalidation_required",
        }
        and not manifest_errors
    ):
        try:
            protocol_source_errors = source_snapshot_freshness_errors(
                root, manifest
            )
        except (TextArtifactReadError, OSError, UnicodeError, ValueError) as exc:
            protocol_source_errors = [
                f"Cannot check source snapshot freshness safely: {exc}"
            ]
    for error in protocol_source_errors:
        if error not in structural_errors:
            structural_errors.append(error)
    output = getattr(args, "output", None)
    if (
        output is not None
        and finalization["record_status"] != "missing"
        and output.resolve().is_relative_to(root)
    ):
        raise ValueError(
            "Refusing to write status output inside an audit root that has "
            "a finalization record"
        )

    finalization_view = dict(finalization)
    full_gate_errors = list(finalization.get("current_gate_errors", []))
    finalization_view["current_gate_error_count"] = len(full_gate_errors)
    verbose = bool(getattr(args, "verbose", False))
    if verbose:
        finalization_view["current_gate_errors_omitted"] = 0
    else:
        visible_errors, omitted = bounded_errors(
            full_gate_errors, preferred_markers=STATUS_PRIORITY_ERROR_MARKERS
        )
        finalization_view["current_gate_errors"] = visible_errors
        finalization_view["current_gate_errors_omitted"] = omitted

    coherent_legacy_upgrade = bool(
        protocol_view["status"] == "upgrade_required"
        and not structural_errors
        and not ledger_errors
        and not protocol_source_errors
        and not any(finalization.get("artifact_changes", {}).values())
    )
    coherent_evidence_upgrade = bool(
        protocol_view["status"] == "evidence_upgrade_required"
        and not structural_errors
        and not any(
            is_fatal_ledger_error(error) for error in ledger_errors
        )
        and not protocol_source_errors
        and not any(finalization.get("artifact_changes", {}).values())
    )
    coherent_closure_upgrade = bool(
        protocol_view["status"] == "closure_upgrade_required"
        and not structural_errors
        and not ledger_errors
        and not protocol_source_errors
        and not any(finalization.get("artifact_changes", {}).values())
    )
    if coherent_legacy_upgrade:
        finalization_view.update(
            {
                "freshness": "legacy_protocol",
                "usable_finalization": False,
                "preflight_status": "upgrade_required",
                "finalizable_now": False,
                "stale_reasons": (
                    list(finalization.get("stale_reasons", []))
                    if verbose
                    else [
                        "The recorded finalization is historical evidence under "
                        "artifact/evidence/closure protocol 4/3/2."
                    ]
                ),
            }
        )
        if not verbose:
            finalization_view["current_gate_errors"] = [
                "Protocol upgrade required: recorded artifact/evidence/closure "
                f"versions are {LEGACY_SCHEMA_VERSION}/"
                f"{LEGACY_EVIDENCE_CONTRACT_VERSION}/"
                f"{LEGACY_CLOSURE_CONTRACT_VERSION}; current finalization "
                f"requires {SCHEMA_VERSION}/{EVIDENCE_CONTRACT_VERSION}/"
                f"{CLOSURE_CONTRACT_VERSION}.",
                "Run migrate-ledger for every legacy ledger and manually recheck "
                "the proof records before finalization.",
            ]
            finalization_view["current_gate_errors_omitted"] = len(
                full_gate_errors
            )

    if coherent_evidence_upgrade:
        finalization_view.update(
            {
                "freshness": "evidence_contract_changed",
                "usable_finalization": False,
                "preflight_status": "evidence_upgrade_required",
                "finalizable_now": False,
                "stale_reasons": [
                    "The schema-5 audit predates evidence contract "
                    f"{EVIDENCE_CONTRACT_VERSION}: instantiated failure "
                    "computations, repair-search records, repair-cost fields, "
                    "and source-anchored step evidence."
                ],
            }
        )
        if not verbose:
            finalization_view["current_gate_errors"] = [
                "Evidence upgrade required: recorded artifact/evidence/closure "
                f"versions are {SCHEMA_VERSION}/"
                f"{PREVIOUS_EVIDENCE_CONTRACT_VERSION}/"
                f"{protocol_view['recorded']['closure_contract_version']}; "
                f"current finalization requires {SCHEMA_VERSION}/"
                f"{EVIDENCE_CONTRACT_VERSION}/{CLOSURE_CONTRACT_VERSION}.",
                "Run migrate-evidence, author the newly required evidence "
                "records, recheck the affected ledgers, then run "
                "migrate-closure if the closure contract is still "
                f"{PREVIOUS_CLOSURE_CONTRACT_VERSION}.",
            ]
            finalization_view["current_gate_errors_omitted"] = len(
                full_gate_errors
            )

    if coherent_closure_upgrade:
        finalization_view.update(
            {
                "freshness": "closure_contract_changed",
                "usable_finalization": False,
                "preflight_status": "closure_upgrade_required",
                "finalizable_now": False,
                "stale_reasons": [
                    "The schema-5 audit predates mandatory bibliography identity "
                    "bindings for load-bearing citation keys."
                ],
            }
        )
        if not verbose:
            finalization_view["current_gate_errors"] = [
                "Closure upgrade required: recorded artifact/evidence/closure "
                f"versions are {SCHEMA_VERSION}/{EVIDENCE_CONTRACT_VERSION}/"
                f"{PREVIOUS_CLOSURE_CONTRACT_VERSION}; current finalization "
                f"requires {SCHEMA_VERSION}/{EVIDENCE_CONTRACT_VERSION}/"
                f"{CLOSURE_CONTRACT_VERSION}.",
                "Run migrate-closure, then manually complete every pending "
                "citation binding and refresh affected dependency contracts.",
            ]
            finalization_view["current_gate_errors_omitted"] = len(full_gate_errors)

    coherent_validator_revalidation = bool(
        protocol_view["status"] == "validator_revalidation_required"
        and not structural_errors
        and not protocol_source_errors
        and not any(finalization.get("artifact_changes", {}).values())
    )
    if coherent_validator_revalidation:
        finalization_view.update(
            {
                "freshness": "validator_changed",
                "usable_finalization": False,
                "preflight_status": "validator_revalidation_required",
                "finalizable_now": False,
                "stale_reasons": [
                    "The audit records a different release identity under the "
                    "current schema and contract versions."
                ],
            }
        )
        if not verbose:
            finalization_view["current_gate_errors"] = [
                "Release identity revalidation required: the schema and contract "
                "versions are current, but the release identity changed.",
                "Run revalidate-protocol, then rerun status and finalization.",
            ]
            finalization_view["current_gate_errors_omitted"] = len(
                full_gate_errors
            )

    malformed_or_stale = bool(
        structural_errors
        or drift
        or derived.get("completion_gate_errors")
        or (
            finalization["record_status"] in {"failed", "invalid"}
            or finalization["freshness"] in {"stale", "unknown"}
        )
    )
    if coherent_legacy_upgrade:
        workflow_state = "upgrade_required"
    elif coherent_evidence_upgrade:
        workflow_state = "evidence_upgrade_required"
    elif coherent_closure_upgrade:
        workflow_state = "closure_upgrade_required"
    elif coherent_validator_revalidation:
        workflow_state = "validator_revalidation_required"
    elif malformed_or_stale:
        workflow_state = "malformed_or_stale"
    elif finalization["finalizable_now"]:
        workflow_state = "finalizable"
    else:
        workflow_state = "healthy_wip"

    counts = Counter(
        summary.get("expected_unit_status", "unknown") for summary in summaries
    )
    invalid = [summary["ledger"] for summary in summaries if summary.get("errors")]
    progress_view = {
        "recorded_status": recorded_progress.get("status"),
        "expected_status": derived.get("expected_status"),
        "recorded_current_pass": recorded_progress.get("current_pass"),
        "current_pass": derived.get("current_pass"),
        "active_unit": recorded_progress.get("active_unit"),
        "normalized_units": derived.get("normalized_units", []),
        "completed_units": derived.get("completed_units", []),
        "conditional_units": derived.get("conditional_units", []),
        "in_progress_units": derived.get("in_progress_units", []),
        "not_started_units": derived.get("not_started_units", []),
        "blocked_units": derived.get("blocked_units", {}),
        "next_action": (
            protocol_view["next_action"]
            if (
                coherent_legacy_upgrade
                or coherent_evidence_upgrade
                or coherent_closure_upgrade
                or coherent_validator_revalidation
                or protocol_mismatch
            )
            else f"Audit finalized. Deliver {preferred_report_path(manifest)} "
            "(delivery-check re-verifies the release)."
            if finalization_view.get("usable_finalization") is True
            else recorded_progress.get("next_action")
        ),
        "drift": (
            []
            if (
                coherent_legacy_upgrade
                or coherent_evidence_upgrade
                or coherent_closure_upgrade
                or coherent_validator_revalidation
            )
            else drift
        ),
        "candidate_completion_gate_error_count": len(
            derived.get("completion_gate_errors", [])
        ),
        "completion_gate_error_count": len(derived.get("completion_gate_errors", [])),
    }
    visible_structural, structural_omitted = (
        (list(structural_errors), 0)
        if verbose
        else bounded_errors(structural_errors, 12)
    )
    audit_complete = finalization_view.get("usable_finalization") is True
    report_integrity = {
        "status": (
            "failed"
            if (
                undeclared_report_files
                or prematurely_unmarked_report
                or invalid_nonfinal_report_title
            )
            else "scaffold"
            if canonical_report_scaffold
            else "clear"
        ),
        "canonical_report_scaffold": canonical_report_scaffold,
        "prematurely_unmarked": prematurely_unmarked_report,
        "invalid_nonfinal_title": invalid_nonfinal_report_title,
        "undeclared_markdown_files": undeclared_report_files,
    }
    result = {
        "audit_root": str(root),
        "workflow_state": workflow_state,
        "audit_complete": audit_complete,
        "delivery_status": "FINAL" if audit_complete else "NONFINAL",
        "finalization_gate_error_count": len(full_gate_errors),
        "report_integrity": report_integrity,
        "generated_views": generated_views,
        "protocol": protocol_view,
        "progress": progress_view,
        "ledgers": len(summaries),
        "ledger_errors": len(ledger_errors),
        "invalid_ledgers": invalid,
        "unit_statuses": dict(counts),
        "issues": len(issues),
        "issue_log_errors": len(issue_read_errors),
        "structural_errors": visible_structural,
        "structural_errors_omitted": structural_omitted,
        "finalization": finalization_view,
    }
    text = (
        status_markdown(result)
        if getattr(args, "format", "json") == "markdown"
        else json.dumps(result, ensure_ascii=False, indent=2) + "\n"
    )
    write_or_print(text, output, getattr(args, "force", False))
    status_code = 1 if workflow_state in {
        "malformed_or_stale",
        "upgrade_required",
        "evidence_upgrade_required",
        "closure_upgrade_required",
        "validator_revalidation_required",
    } else 0
    if getattr(args, "require_finalized", False) and not audit_complete:
        return 1
    return status_code


@audit_migration_locked
def cmd_migrate_closure(args: argparse.Namespace) -> int:
    """Upgrade prior-closure state without transferring citation judgments."""
    root = args.root.resolve()
    errors: list[str] = audit_internal_redirect_errors(root)
    manifest_path, manifest_path_valid = canonical_artifact_path(
        root, "AUDIT_MANIFEST.json", "audit manifest", errors
    )
    manifest_baseline_sha256 = (
        sha256_file(manifest_path)
        if manifest_path_valid and manifest_path.is_file()
        else None
    )
    manifest, manifest_errors = (
        load_json_object(manifest_path, "audit manifest")
        if manifest_path_valid
        else ({}, [])
    )
    errors.extend(manifest_errors)
    if (
        manifest_baseline_sha256 is not None
        and sha256_file(manifest_path) != manifest_baseline_sha256
    ):
        errors.append("Audit manifest changed while migration preflight read it")
    registry_path, registry_path_valid = (
        manifest_canonical_artifact_path(
            manifest,
            root,
            "dependency_registry",
            "dependency registry",
            errors,
        )
        if not manifest_errors
        else (root / "audit" / "03_dependencies" / "DEPENDENCY_REGISTRY.json", False)
    )
    registry_baseline_sha256 = (
        sha256_file(registry_path)
        if registry_path_valid and registry_path.is_file()
        else None
    )
    registry, registry_errors = (
        load_json_object(registry_path, "dependency registry")
        if registry_path_valid
        else ({}, [])
    )
    errors.extend(registry_errors)
    if (
        registry_baseline_sha256 is not None
        and not registry_errors
        and sha256_file(registry_path) != registry_baseline_sha256
    ):
        errors.append(
            "Dependency registry changed while migration preflight read it"
        )

    recorded_protocol = manifest.get("protocol")
    if not isinstance(recorded_protocol, dict):
        errors.append("AUDIT_MANIFEST.json protocol must be an object")
        recorded_protocol = {}
    current_protocol = protocol_identity()
    recorded_closure = recorded_protocol.get("closure_contract_version")
    registry_closure = registry.get("closure_contract_version")
    closure_already_current = bool(
        manifest.get("schema_version") == SCHEMA_VERSION
        and all(
            recorded_protocol.get(field) == expected
            for field, expected in current_protocol.items()
        )
        and registry.get("schema_version") == SCHEMA_VERSION
        and registry_closure == CLOSURE_CONTRACT_VERSION
    )
    if manifest.get("schema_version") != SCHEMA_VERSION:
        errors.append("migrate-closure requires schema-5 audit state")
    if recorded_protocol.get("artifact_schema_version") != SCHEMA_VERSION:
        errors.append(
            "protocol.artifact_schema_version is incompatible with migrate-closure"
        )
    if (
        recorded_protocol.get("evidence_contract_version")
        == PREVIOUS_EVIDENCE_CONTRACT_VERSION
    ):
        errors.append(
            "protocol.evidence_contract_version is "
            f"{PREVIOUS_EVIDENCE_CONTRACT_VERSION}; run migrate-evidence "
            "before migrate-closure"
        )
    elif (
        recorded_protocol.get("evidence_contract_version")
        != EVIDENCE_CONTRACT_VERSION
    ):
        errors.append(
            "protocol.evidence_contract_version is incompatible with migrate-closure"
        )
    expected_closure = (
        CLOSURE_CONTRACT_VERSION
        if closure_already_current
        else PREVIOUS_CLOSURE_CONTRACT_VERSION
    )
    if recorded_closure != expected_closure:
        errors.append(
            "migrate-closure requires protocol.closure_contract_version "
            f"{expected_closure}"
        )
    if registry.get("schema_version") != SCHEMA_VERSION:
        errors.append("migrate-closure requires a schema-5 dependency registry")
    if registry_closure != expected_closure:
        errors.append(
            "migrate-closure requires dependency registry "
            "closure_contract_version "
            f"{expected_closure}"
        )
    external_results = registry.get("external_results")
    if not isinstance(external_results, list):
        errors.append("Dependency registry external_results must be a list")
        external_results = []
    for result_index, result in enumerate(external_results, 1):
        prefix = f"external_results[{result_index}]"
        if not isinstance(result, dict):
            errors.append(f"{prefix} must be an object")
            continue
        if not is_nonempty_string(result.get("id")):
            errors.append(f"{prefix}.id must be a nonempty string")
        uses = result.get("uses")
        if not isinstance(uses, list):
            errors.append(f"{prefix}.uses must be a list")
            continue
        for use_index, use in enumerate(uses, 1):
            if not isinstance(use, dict):
                errors.append(f"{prefix}.uses[{use_index}] must be an object")
                continue
            keys = use.get("citation_keys")
            if not isinstance(keys, list) or not all(
                is_nonempty_string(key) for key in keys
            ):
                errors.append(
                    f"{prefix}.uses[{use_index}].citation_keys must be a string list"
                )
            elif len(keys) != len(set(keys)):
                errors.append(
                    f"{prefix}.uses[{use_index}].citation_keys contains duplicates"
                )
        if "citation_bindings" in result and not isinstance(
            result.get("citation_bindings"), list
        ):
            errors.append(f"{prefix}.citation_bindings must be a list when present")
    if not manifest_errors:
        try:
            errors.extend(source_snapshot_freshness_errors(root, manifest))
        except (TextArtifactReadError, OSError, UnicodeError, ValueError) as exc:
            errors.append(f"Cannot check source snapshot freshness safely: {exc}")

    errors = list(dict.fromkeys(errors))
    if errors:
        result = {
            "command": "migrate-closure",
            "audit_root": str(root),
            "status": "failed",
            "updated": False,
            "errors": errors,
        }
        print(json.dumps(result, ensure_ascii=False, indent=2))
        for error in errors:
            print(f"ERROR: {error}", file=sys.stderr)
        return 1

    if closure_already_current:
        print(
            json.dumps(
                {
                    "command": "migrate-closure",
                    "audit_root": str(root),
                    "status": "already_current",
                    "updated": False,
                    "finalization_invalidated": False,
                    "next_action": "Continue the current audit workflow.",
                },
                ensure_ascii=False,
                indent=2,
            )
        )
        return 0

    migrated_registry = json.loads(json.dumps(registry, ensure_ascii=False))
    migrated_external = migrated_registry["external_results"]
    pending_results: list[str] = []
    for result in migrated_external:
        result_id = str(result["id"])
        required_keys = sorted(
            {
                key
                for use in result["uses"]
                for key in use["citation_keys"]
            }
        )
        # The prior closure contract did not carry reviewed citation-identity
        # judgments. Preserve any experimental rows only in the byte-exact
        # legacy backup and require a fresh current-contract binding review.
        result["citation_bindings"] = []
        if required_keys:
            pending_results.append(result_id)
            result["citation_binding_review"] = {
                "status": "pending",
                "required_keys": required_keys,
                "evidence": (
                    "Migrated from closure contract "
                    f"{PREVIOUS_CLOSURE_CONTRACT_VERSION}; exact bibliography "
                    "identity bindings require manual review."
                ),
            }
        else:
            result["citation_binding_review"] = {
                "status": "not_required",
                "required_keys": [],
                "evidence": (
                    "No load-bearing citation key is recorded for this external result."
                ),
            }
    migrated_registry["closure_contract_version"] = CLOSURE_CONTRACT_VERSION
    review = migrated_registry.get("review")
    if isinstance(review, dict):
        review["status"] = "not_reviewed"
    if not isinstance(registry_baseline_sha256, str) or not isinstance(
        manifest_baseline_sha256, str
    ):
        raise ValueError("Cannot bind closure migration to stable live inputs")
    legacy_digest = registry_baseline_sha256
    migration_time = utc_now()
    history_directory = registry_path.parent / "history"
    backup_path = history_directory / (
        "DEPENDENCY_REGISTRY.closure-"
        f"{PREVIOUS_CLOSURE_CONTRACT_VERSION}.{legacy_digest}.json"
    )
    migrated_registry["closure_migration"] = {
        "from_version": PREVIOUS_CLOSURE_CONTRACT_VERSION,
        "to_version": CLOSURE_CONTRACT_VERSION,
        "migrated_utc": migration_time,
        "legacy_registry_sha256": legacy_digest,
        "legacy_registry_backup": relative_or_absolute(backup_path, root),
        "pending_external_results": pending_results,
    }

    migrated_manifest = json.loads(json.dumps(manifest, ensure_ascii=False))
    migrated_manifest["protocol"] = retain_challenge_contract(current_protocol, manifest)
    completion = migrated_manifest.get("completion")
    if isinstance(completion, dict):
        completion["dependency_registry_reviewed"] = False
        completion["final_report_ready"] = False
    history_directory_existed = history_directory.exists()
    backup_created = False
    try:
        if backup_path.exists():
            if backup_path.is_symlink() or not backup_path.is_file():
                raise ValueError(
                    "Refusing a non-regular closure registry backup path"
                )
            if sha256_file(backup_path) != legacy_digest:
                raise ValueError(
                    "Refusing to replace a conflicting prior-closure registry backup"
                )
        else:
            history_directory.mkdir(parents=True, exist_ok=True)
            temporary_backup = _unique_sibling_temp_path(backup_path)
            try:
                with registry_path.open("rb") as source, temporary_backup.open(
                    "wb"
                ) as destination:
                    shutil.copyfileobj(source, destination, length=1024 * 1024)
                    destination.flush()
                    os.fsync(destination.fileno())
                if sha256_file(temporary_backup) != legacy_digest:
                    raise ValueError(
                        "Dependency registry changed during closure migration"
                    )
                try:
                    publish_no_overwrite(
                        temporary_backup,
                        backup_path,
                        "closure registry backup",
                    )
                except FileExistsError as publish_exc:
                    if (
                        backup_path.is_symlink()
                        or not backup_path.is_file()
                        or sha256_file(backup_path) != legacy_digest
                    ):
                        raise FileExistsError(
                            "A conflicting closure registry backup appeared "
                            f"during publication: {backup_path}"
                        ) from publish_exc
                else:
                    backup_created = True
            finally:
                if temporary_backup.exists():
                    temporary_backup.unlink()
        transactional_write_texts(
            [
                (
                    registry_path,
                    json.dumps(migrated_registry, ensure_ascii=False, indent=2)
                    + "\n",
                ),
                (
                    manifest_path,
                    json.dumps(migrated_manifest, ensure_ascii=False, indent=2)
                    + "\n",
                ),
            ],
            expected_sha256={
                registry_path: registry_baseline_sha256,
                manifest_path: manifest_baseline_sha256,
            },
        )
    except BaseException as exc:
        if isinstance(exc, MigrationRecoveryRequired):
            raise
        cleanup_errors: list[str] = []
        if backup_created and backup_path.exists():
            try:
                backup_path.unlink()
            except OSError as cleanup_exc:
                cleanup_errors.append(f"{backup_path}: {cleanup_exc}")
        if not history_directory_existed and history_directory.exists():
            try:
                history_directory.rmdir()
            except OSError as cleanup_exc:
                try:
                    directory_nonempty = any(history_directory.iterdir())
                except OSError:
                    directory_nonempty = False
                if not directory_nonempty:
                    cleanup_errors.append(f"{history_directory}: {cleanup_exc}")
        if cleanup_errors:
            raise MigrationRecoveryRequired(
                "Closure migration failed and backup cleanup was incomplete: "
                + "; ".join(cleanup_errors)
            ) from exc
        raise
    print(
        json.dumps(
            {
                "command": "migrate-closure",
                "audit_root": str(root),
                "status": "migrated",
                "updated": True,
                "legacy_registry_backup": str(backup_path),
                "pending_external_results": pending_results,
                "finalization_invalidated": True,
                "next_action": (
                    "Manually complete citation_bindings and set each pending "
                    "citation_binding_review to reviewed; refresh affected external "
                    "dependency_contract_sha256 values and review the registry."
                ),
            },
            ensure_ascii=False,
            indent=2,
        )
    )
    return 0


@audit_migration_locked
def cmd_migrate_evidence(args: argparse.Namespace) -> int:
    """Advance a schema-5, evidence-contract-4 audit onto evidence contract 5.

    The command validates and byte-backs up live proof artifacts, then stamps
    versions only. It cannot author the judgments contract 5 demands, including
    instantiated failure computations, repair-search records, repair-cost fields,
    and source-anchored step evidence. After migration, the current gates fail
    closed until those records are added and rechecked.
    """
    configure_console_errors()
    root = args.root.resolve()
    errors: list[str] = audit_internal_redirect_errors(root)
    manifest_path, manifest_path_valid = canonical_artifact_path(
        root, "AUDIT_MANIFEST.json", "audit manifest", errors
    )
    manifest_baseline_sha256 = (
        sha256_file(manifest_path)
        if manifest_path_valid and manifest_path.is_file()
        else None
    )
    manifest, manifest_errors = (
        load_json_object(manifest_path, "audit manifest")
        if manifest_path_valid
        else ({}, [])
    )
    errors.extend(manifest_errors)
    if (
        manifest_baseline_sha256 is not None
        and sha256_file(manifest_path) != manifest_baseline_sha256
    ):
        errors.append("Audit manifest changed while migration preflight read it")
    recorded_protocol = manifest.get("protocol")
    if not isinstance(recorded_protocol, dict):
        errors.append("AUDIT_MANIFEST.json protocol must be an object")
        recorded_protocol = {}
    if manifest.get("schema_version") != SCHEMA_VERSION:
        errors.append("migrate-evidence requires schema-5 audit state")
    if recorded_protocol.get("artifact_schema_version") != SCHEMA_VERSION:
        errors.append(
            "protocol.artifact_schema_version is incompatible with migrate-evidence"
        )
    recorded_evidence = recorded_protocol.get("evidence_contract_version")
    evidence_already_current = recorded_evidence == EVIDENCE_CONTRACT_VERSION
    if (
        not evidence_already_current
        and recorded_evidence != PREVIOUS_EVIDENCE_CONTRACT_VERSION
    ):
        errors.append(
            "migrate-evidence requires protocol.evidence_contract_version "
            f"{PREVIOUS_EVIDENCE_CONTRACT_VERSION} or "
            f"{EVIDENCE_CONTRACT_VERSION}"
        )
    recorded_closure = recorded_protocol.get("closure_contract_version")
    if recorded_closure not in {
        CLOSURE_CONTRACT_VERSION,
        PREVIOUS_CLOSURE_CONTRACT_VERSION,
    }:
        errors.append(
            "migrate-evidence requires closure_contract_version "
            f"{PREVIOUS_CLOSURE_CONTRACT_VERSION} or {CLOSURE_CONTRACT_VERSION}"
        )
    dependency_registry_path, dependency_registry_path_valid = (
        manifest_canonical_artifact_path(
            manifest,
            root,
            "dependency_registry",
            "dependency registry",
            errors,
        )
        if not manifest_errors
        else (root / "audit" / "03_dependencies" / "DEPENDENCY_REGISTRY.json", False)
    )
    dependency_registry_baseline_sha256 = (
        sha256_file(dependency_registry_path)
        if dependency_registry_path_valid and dependency_registry_path.is_file()
        else None
    )
    dependency_registry, dependency_registry_errors = (
        load_json_object(dependency_registry_path, "dependency registry")
        if dependency_registry_path_valid
        else ({}, [])
    )
    errors.extend(dependency_registry_errors)
    if (
        dependency_registry_baseline_sha256 is not None
        and not dependency_registry_errors
        and sha256_file(dependency_registry_path)
        != dependency_registry_baseline_sha256
    ):
        errors.append(
            "Dependency registry changed while migration preflight read it"
        )
    if dependency_registry_path_valid and not dependency_registry_errors:
        if dependency_registry.get("schema_version") != recorded_protocol.get(
            "artifact_schema_version"
        ):
            errors.append(
                "Dependency registry schema_version does not match the "
                "manifest protocol"
            )
        if dependency_registry.get(
            "closure_contract_version"
        ) != recorded_closure:
            errors.append(
                "Dependency registry closure_contract_version does not match "
                "the manifest protocol"
            )
    if not manifest_errors:
        try:
            errors.extend(source_snapshot_freshness_errors(root, manifest))
        except (TextArtifactReadError, OSError, UnicodeError, ValueError) as exc:
            errors.append(f"Cannot check source snapshot freshness safely: {exc}")

    artifact_updates: list[tuple[Path, dict[str, Any], str, Path]] = []
    local_checks_directory = root / "audit" / "04_local_checks"
    evidence_history_directory = local_checks_directory / "history"
    if not errors:
        if not local_checks_directory.is_dir():
            errors.append(
                "migrate-evidence requires the canonical audit/04_local_checks "
                "directory"
            )
        live_artifacts = sorted(
            [
                *local_checks_directory.glob("*.ledger.json"),
                *local_checks_directory.glob("*.skeleton.json"),
            ]
        )
        for artifact_path in live_artifacts:
            relative = artifact_path.relative_to(root).as_posix()
            if artifact_path.is_symlink() or not artifact_path.is_file():
                errors.append(
                    f"Canonical proof artifact is not a regular file: {relative}"
                )
                continue
            prior_sha = sha256_file(artifact_path)
            artifact, artifact_errors = load_json_object(
                artifact_path, f"canonical proof artifact {relative}"
            )
            if artifact_errors:
                errors.extend(artifact_errors)
                continue
            compatible = True
            expected_artifact_evidence = (
                EVIDENCE_CONTRACT_VERSION
                if evidence_already_current
                else PREVIOUS_EVIDENCE_CONTRACT_VERSION
            )
            if artifact.get("schema_version") != SCHEMA_VERSION:
                errors.append(
                    f"{relative} schema_version must be {SCHEMA_VERSION} for "
                    "migrate-evidence"
                )
                compatible = False
            if (
                artifact.get("evidence_contract_version")
                != expected_artifact_evidence
            ):
                errors.append(
                    f"{relative} evidence_contract_version must be "
                    f"{expected_artifact_evidence} for migrate-evidence"
                )
                compatible = False
            if not is_nonempty_string(artifact.get("unit_id")):
                errors.append(f"{relative} unit_id must be a nonempty string")
                compatible = False
            artifact_validation_errors, _ = check_ledger_data(
                artifact_path, False
            )
            fatal_artifact_errors = [
                error
                for error in artifact_validation_errors
                if is_fatal_ledger_error(error)
            ]
            if fatal_artifact_errors:
                errors.extend(
                    f"{relative}: {error}" for error in fatal_artifact_errors
                )
                compatible = False
            if sha256_file(artifact_path) != prior_sha:
                errors.append(
                    "Canonical proof artifact changed while migration preflight "
                    f"read it: {relative}"
                )
                compatible = False
            if not compatible:
                continue
            if evidence_already_current:
                continue
            backup_path = evidence_history_directory / (
                f"{artifact_path.name}.evidence-"
                f"{PREVIOUS_EVIDENCE_CONTRACT_VERSION}.{prior_sha}.json"
            )
            if backup_path.exists():
                if backup_path.is_symlink() or not backup_path.is_file():
                    errors.append(
                        f"Evidence migration backup is not a regular file: "
                        f"{relative_or_absolute(backup_path, root)}"
                    )
                    continue
                if sha256_file(backup_path) != prior_sha:
                    errors.append(
                        "Refusing a conflicting evidence-contract backup: "
                        f"{relative_or_absolute(backup_path, root)}"
                    )
                    continue
            artifact["evidence_contract_version"] = EVIDENCE_CONTRACT_VERSION
            artifact_updates.append(
                (artifact_path, artifact, prior_sha, backup_path)
            )

    errors = list(dict.fromkeys(errors))
    if errors:
        result = {
            "command": "migrate-evidence",
            "audit_root": str(root),
            "status": "failed",
            "updated": False,
            "errors": errors,
        }
        print(json.dumps(result, ensure_ascii=False, indent=2))
        for error in errors:
            print(f"ERROR: {error}", file=sys.stderr)
        return 1

    if evidence_already_current:
        next_action = (
            "Run migrate-closure --root <audit-root>."
            if recorded_closure == PREVIOUS_CLOSURE_CONTRACT_VERSION
            else "Continue the current audit workflow."
        )
        print(
            json.dumps(
                {
                    "command": "migrate-evidence",
                    "audit_root": str(root),
                    "status": "already_current",
                    "updated": False,
                    "finalization_invalidated": False,
                    "closure_contract_version": recorded_closure,
                    "next_action": next_action,
                },
                ensure_ascii=False,
                indent=2,
            )
        )
        return 0

    migrated_manifest = json.loads(json.dumps(manifest, ensure_ascii=False))
    migrated_protocol = dict(protocol_identity())
    migrated_protocol["closure_contract_version"] = recorded_closure
    migrated_manifest["protocol"] = retain_challenge_contract(migrated_protocol, manifest)
    completion = migrated_manifest.get("completion")
    if isinstance(completion, dict):
        completion["final_report_ready"] = False
    migrated_manifest["evidence_migration"] = {
        "from_version": PREVIOUS_EVIDENCE_CONTRACT_VERSION,
        "to_version": EVIDENCE_CONTRACT_VERSION,
        "migrated_utc": utc_now(),
        "restamped_artifacts": [
            {
                "file": relative_or_absolute(path, root),
                "prior_sha256": prior_sha,
                "legacy_backup": relative_or_absolute(backup_path, root),
            }
            for path, _, prior_sha, backup_path in artifact_updates
        ],
        "note": (
            "Version stamp only. Evidence-contract-5 judgments must be "
            "authored and rechecked before finalization."
        ),
    }
    writes = list(
        (path, json.dumps(artifact, ensure_ascii=False, indent=1) + "\n")
        for path, artifact, _, _ in artifact_updates
    )
    writes.append(
        (
            manifest_path,
            json.dumps(migrated_manifest, ensure_ascii=False, indent=2) + "\n",
        )
    )
    evidence_history_existed = evidence_history_directory.exists()
    created_backups: list[Path] = []
    try:
        if artifact_updates:
            evidence_history_directory.mkdir(parents=True, exist_ok=True)
        for artifact_path, _, prior_sha, backup_path in artifact_updates:
            if sha256_file(artifact_path) != prior_sha:
                raise ValueError(
                    "Canonical proof artifact changed during evidence migration: "
                    f"{relative_or_absolute(artifact_path, root)}"
                )
            if backup_path.exists():
                continue
            temporary_backup = _unique_sibling_temp_path(backup_path)
            try:
                with artifact_path.open("rb") as source, temporary_backup.open(
                    "wb"
                ) as destination:
                    shutil.copyfileobj(source, destination, length=1024 * 1024)
                    destination.flush()
                    os.fsync(destination.fileno())
                if sha256_file(temporary_backup) != prior_sha:
                    raise ValueError(
                        "Canonical proof artifact changed during backup: "
                        f"{relative_or_absolute(artifact_path, root)}"
                    )
                try:
                    publish_no_overwrite(
                        temporary_backup,
                        backup_path,
                        "evidence-contract proof-artifact backup",
                    )
                except FileExistsError as publish_exc:
                    if (
                        backup_path.is_symlink()
                        or not backup_path.is_file()
                        or sha256_file(backup_path) != prior_sha
                    ):
                        raise FileExistsError(
                            "A conflicting evidence-contract backup appeared "
                            f"during publication: {backup_path}"
                        ) from publish_exc
                else:
                    created_backups.append(backup_path)
            finally:
                if temporary_backup.exists():
                    temporary_backup.unlink()
        if not isinstance(manifest_baseline_sha256, str) or not isinstance(
            dependency_registry_baseline_sha256, str
        ):
            raise ValueError("Cannot bind evidence migration to stable live inputs")
        transactional_write_texts(
            writes,
            expected_sha256={
                manifest_path: manifest_baseline_sha256,
                dependency_registry_path: dependency_registry_baseline_sha256,
                **{
                    artifact_path: prior_sha
                    for artifact_path, _, prior_sha, _ in artifact_updates
                },
            },
        )
    except BaseException as exc:
        if isinstance(exc, MigrationRecoveryRequired):
            raise
        cleanup_errors: list[str] = []
        for backup_path in reversed(created_backups):
            if not backup_path.exists():
                continue
            try:
                backup_path.unlink()
            except OSError as cleanup_exc:
                cleanup_errors.append(f"{backup_path}: {cleanup_exc}")
        if not evidence_history_existed and evidence_history_directory.exists():
            try:
                evidence_history_directory.rmdir()
            except OSError as cleanup_exc:
                try:
                    directory_nonempty = any(
                        evidence_history_directory.iterdir()
                    )
                except OSError:
                    directory_nonempty = False
                if not directory_nonempty:
                    cleanup_errors.append(
                        f"{evidence_history_directory}: {cleanup_exc}"
                    )
        if cleanup_errors:
            raise MigrationRecoveryRequired(
                "Evidence migration failed and backup cleanup was incomplete: "
                + "; ".join(cleanup_errors)
            ) from exc
        raise
    print(
        json.dumps(
            {
                "command": "migrate-evidence",
                "audit_root": str(root),
                "status": "migrated",
                "updated": True,
                "restamped_artifacts": len(artifact_updates),
                "legacy_artifact_backups": [
                    str(backup_path)
                    for _, _, _, backup_path in artifact_updates
                ],
                "closure_contract_version": recorded_closure,
                "finalization_invalidated": True,
                "next_action": (
                    "Author the evidence-contract-5 records the gates now "
                    "demand (failure computations, repair searches, "
                    "repair-cost fields, anchored step evidence), recheck the "
                    "restamped ledgers with ledger-check --final, run "
                    "migrate-closure if the closure contract is still "
                    f"{PREVIOUS_CLOSURE_CONTRACT_VERSION}, and rerun the "
                    "full gates."
                ),
            },
            ensure_ascii=False,
            indent=2,
        )
    )
    return 0


def cmd_revalidate_protocol(args: argparse.Namespace) -> int:
    """Rebind a current-schema WIP audit to the current validator safely."""
    root = args.root.resolve()
    lock_error = migration_update_lock_error(root)
    if lock_error is not None:
        raise ValueError(lock_error)
    errors: list[str] = audit_internal_redirect_errors(root)
    manifest_path, manifest_path_valid = canonical_artifact_path(
        root, "AUDIT_MANIFEST.json", "audit manifest", errors
    )
    manifest, manifest_errors = (
        load_json_object(manifest_path, "audit manifest")
        if manifest_path_valid
        else ({}, [])
    )
    errors.extend(manifest_errors)
    original_manifest_bytes = manifest_path.read_bytes() if manifest_path_valid and not manifest_errors else b""
    baseline = audit_state_manifest(root) if not errors else []
    if original_manifest_bytes:
        captured = json.loads(original_manifest_bytes.decode("utf-8-sig"))
        if captured != manifest or not any(
            row["file"] == "AUDIT_MANIFEST.json" and row["sha256"] == hashlib.sha256(original_manifest_bytes).hexdigest()
            for row in baseline
        ):
            errors.append("Audit manifest changed while capturing protocol revalidation inputs")
    current_protocol = protocol_identity()
    previous_validator: Any = None
    previous_skill_version: Any = None

    if not manifest_errors:
        if manifest.get("schema_version") != SCHEMA_VERSION:
            errors.append(
                "revalidate-protocol requires the current manifest schema_version"
            )
        recorded_protocol = manifest.get("protocol")
        if not isinstance(recorded_protocol, dict):
            errors.append("AUDIT_MANIFEST.json protocol must be an object")
            recorded_protocol = {}
        if set(recorded_protocol) - (set(current_protocol) | {"challenge_contract_version"}):
            errors.append("protocol has unknown identity fields")
        try:
            challenge_contract_version(manifest)
        except ValueError as exc:
            errors.append(str(exc))
        if "context_protocol" in manifest:
            try:
                context_protocol_identity(root, manifest)
            except (OSError, ValueError, UnicodeError) as exc:
                errors.append(str(exc))
        previous_validator = recorded_protocol.get("validator_sha256")
        previous_skill_version = recorded_protocol.get("skill_version")
        # skill_version is release identity, not record compatibility: a
        # version bump with unchanged contracts is exactly the drift this
        # command exists to repair, and the stamp below rewrites it.
        for field, expected in current_protocol.items():
            if field in {"validator_sha256", "skill_version"}:
                continue
            if type(recorded_protocol.get(field)) is not type(expected) or recorded_protocol.get(field) != expected:
                errors.append(
                    f"protocol.{field} is not compatible with the current validator"
                )
        if not is_nonempty_string(previous_skill_version):
            errors.append("protocol.skill_version must be a nonempty string")
        if not (
            isinstance(previous_validator, str)
            and SHA256_RE.fullmatch(previous_validator)
        ):
            errors.append("protocol.validator_sha256 must be a SHA-256 digest")

        canonical_records: dict[str, tuple[Path, bool]] = {}
        for field, label in (
            ("inventory_file", "proof-unit inventory"),
            ("dependency_registry", "dependency registry"),
            ("method_interface_registry", "method-interface registry"),
        ):
            canonical_records[field] = manifest_canonical_artifact_path(
                manifest, root, field, label, errors
            )
        finalization_path, finalization_path_errors = finalization_record_path(
            manifest, root
        )
        errors.extend(finalization_path_errors)
        if not finalization_path_errors and finalization_path.is_file():
            _, finalization_read_errors = load_json_object(
                finalization_path, "finalization record"
            )
            errors.extend(finalization_read_errors)

        inventory_path, inventory_path_valid = canonical_records["inventory_file"]
        inventory, inventory_errors = (
            load_json_object(inventory_path, "proof-unit inventory")
            if inventory_path_valid
            else ({}, [])
        )
        errors.extend(inventory_errors)
        if inventory_path_valid and not inventory_errors:
            if inventory.get("schema_version") != SCHEMA_VERSION:
                errors.append(
                    "Proof-unit inventory has an unsupported schema_version"
                )
            inventory_units = inventory.get("units")
            if not isinstance(inventory_units, list):
                errors.append("Proof-unit inventory must contain a units list")
            else:
                inventory_unit_ids = [
                    unit.get("id")
                    for unit in inventory_units
                    if isinstance(unit, dict)
                    and is_nonempty_string(unit.get("id"))
                ]
                if len(inventory_unit_ids) != len(inventory_units):
                    errors.append(
                        "Proof-unit inventory needs object rows with nonempty unit IDs"
                    )
                elif len(inventory_unit_ids) != len(set(inventory_unit_ids)):
                    errors.append(
                        "Proof-unit inventory needs unique nonempty unit IDs"
                    )

        registry_path, registry_path_valid = canonical_records[
            "dependency_registry"
        ]
        dependency_registry, dependency_registry_errors = (
            load_json_object(registry_path, "dependency registry")
            if registry_path_valid
            else ({}, [])
        )
        errors.extend(dependency_registry_errors)
        if registry_path_valid and not dependency_registry_errors:
            if dependency_registry.get("schema_version") != SCHEMA_VERSION:
                errors.append(
                    "Dependency registry has an unsupported schema_version"
                )
            if (
                dependency_registry.get("closure_contract_version")
                != CLOSURE_CONTRACT_VERSION
            ):
                errors.append(
                    "Dependency registry closure_contract_version does not match "
                    "the validator"
                )
            dependency_review = dependency_registry.get("review")
            if not isinstance(dependency_review, dict):
                errors.append("Dependency registry review must be an object")
            elif dependency_review.get("status") not in {
                "not_reviewed",
                "reviewed",
            }:
                errors.append(
                    "Dependency registry review.status must be not_reviewed or reviewed"
                )
            for field in ("internal_uses", "external_results"):
                rows = dependency_registry.get(field)
                if not isinstance(rows, list):
                    errors.append(f"Dependency registry {field} must be a list")
                elif not all(isinstance(row, dict) for row in rows):
                    errors.append(
                        f"Dependency registry {field} rows must be objects"
                    )

        interface_path, interface_path_valid = canonical_records[
            "method_interface_registry"
        ]
        interface_registry, interface_registry_errors = (
            load_json_object(interface_path, "method-interface registry")
            if interface_path_valid
            else ({}, [])
        )
        errors.extend(interface_registry_errors)
        if interface_path_valid and not interface_registry_errors:
            try:
                validate_method_interface_registry(
                    interface_registry, root, errors, final=False
                )
            except (OSError, UnicodeError, ValueError) as exc:
                errors.append(
                    "Cannot validate the method-interface registry safely: "
                    f"{exc}"
                )

        report_path, report_path_valid = canonical_artifact_path(
            root,
            preferred_report_path(manifest),
            "final report",
            errors,
        )
        if report_path_valid:
            if not report_path.is_file():
                errors.append(f"Final report not found: {report_path}")
            else:
                try:
                    read_text(report_path)
                except TextArtifactReadError as exc:
                    errors.append(str(exc))

        progress_path, progress_path_valid = canonical_artifact_path(
            root, "PROGRESS.json", "progress record", errors
        )
        if progress_path_valid:
            _, progress_errors = load_json_object(
                progress_path, "progress state"
            )
            errors.extend(progress_errors)
        _, _, issue_schema_version, issue_errors = load_issue_log(root)
        errors.extend(issue_errors)
        if issue_schema_version != SCHEMA_VERSION:
            errors.append(
                "revalidate-protocol requires the current ISSUE_LOG.json schema_version"
            )
        ledger_errors, _, _ = audit_ledgers(root, False)
        errors.extend(
            error for error in ledger_errors if is_fatal_ledger_error(error)
        )
        try:
            errors.extend(source_snapshot_freshness_errors(root, manifest))
        except (TextArtifactReadError, OSError, UnicodeError, ValueError) as exc:
            errors.append(f"Cannot check source snapshot freshness safely: {exc}")

    errors = list(dict.fromkeys(errors))
    if errors:
        result = {
            "command": "revalidate-protocol",
            "audit_root": str(root),
            "status": "failed",
            "updated": False,
            "errors": errors,
        }
        print(json.dumps(result, ensure_ascii=False, indent=2))
        for error in errors:
            print(f"ERROR: {error}", file=sys.stderr)
        return 1

    current_validator = current_protocol["validator_sha256"]
    if (
        previous_validator == current_validator
        and previous_skill_version == current_protocol["skill_version"]
    ):
        status = "already_current"
        updated = False
    else:
        updated_manifest = dict(manifest)
        updated_manifest["protocol"] = retain_challenge_contract(current_protocol, manifest)
        writes: list[tuple[Path, str | bytes]] = []
        absent: list[Path] = []
        if "context_protocol" not in manifest:
            origin_digest = hashlib.sha256(original_manifest_bytes).hexdigest()
            origin_relative = f"audit/06_reports/history/context-protocol-{origin_digest}.json"
            origin_errors: list[str] = []
            origin_path, valid = canonical_artifact_path(root, origin_relative, "Context protocol origin", origin_errors)
            if not valid or origin_path is None:
                raise ValueError("Cannot preserve context protocol: " + "; ".join(origin_errors))
            origin_path.parent.mkdir(parents=True, exist_ok=True)
            if origin_path.exists():
                if origin_path.read_bytes() != original_manifest_bytes:
                    raise ValueError("Context protocol origin history differs from the original manifest")
            else:
                writes.append((origin_path, original_manifest_bytes))
                absent.append(origin_path)
            identity = dict(recorded_protocol)
            identity.pop("challenge_contract_version", None)
            updated_manifest["context_protocol"] = {
                "protocol": identity, "original_manifest_file": origin_relative,
                "original_manifest_sha256": origin_digest,
            }
        writes.append((manifest_path, json.dumps(updated_manifest, ensure_ascii=False, indent=2) + "\n"))
        lock, payload = acquire_migration_update_lock(root, "cmd_revalidate_protocol")
        release = True
        try:
            if audit_state_manifest(root, lock) != baseline:
                raise ValueError("Audit changed during protocol revalidation; retry against current evidence")
            guards = {root / row["file"]: row["sha256"] for row in baseline}
            guards.update({resolve_stored_path(row["file"], root): row["sha256"]
                           for row in manifest["source_snapshot"]["files"]})
            transactional_write_texts(writes, expected_sha256=guards,
                                      expected_absent=absent)
        except MigrationRecoveryRequired:
            release = False
            raise
        finally:
            if release:
                release_migration_update_lock(lock, payload)
        status = "revalidated"
        updated = True
    result = {
        "command": "revalidate-protocol",
        "audit_root": str(root),
        "status": status,
        "updated": updated,
        "previous_skill_version": previous_skill_version,
        "current_skill_version": current_protocol["skill_version"],
        "previous_validator_sha256": previous_validator,
        "current_validator_sha256": current_validator,
        "finalization_invalidated": updated,
        "context_protocol_retained": updated or "context_protocol" in manifest,
        "next_action": (
            "Run status, resolve every current gate error, and rerun finalize."
            if updated
            else "Continue the current audit workflow."
        ),
    }
    print(json.dumps(result, ensure_ascii=False, indent=2))
    return 0


def cmd_doctor(args: argparse.Namespace) -> int:
    """Classify preflight failures without suggesting platform-specific repair."""
    checks: list[dict[str, str]] = []

    def record(check_id: str, category: str, status: str, detail: str) -> None:
        checks.append(
            {
                "id": check_id,
                "category": category,
                "status": status,
                "detail": detail,
            }
        )

    mode = getattr(args, "mode", "new")
    mode_ok = mode in {"new", "resume"}
    record(
        "mode",
        "input",
        "passed" if mode_ok else "failed",
        str(mode),
    )
    version_ok = sys.version_info >= (3, 10)
    record(
        "interpreter",
        "environment",
        "passed" if version_ok else "failed",
        f"{sys.executable} ({sys.version.split()[0]}); Python >= 3.10 required",
    )
    skill_root = Path(__file__).resolve().parent.parent
    template_names = (
        "CHECK_PLAN.md",
        "EXECUTION_ORDER.md",
        "DEPENDENCY_GRAPH.md",
        "FINAL_REPORT.md",
    )
    unreadable_templates: list[str] = []
    for name in template_names:
        template = skill_root / "assets" / "templates" / name
        try:
            if not template.is_file():
                raise FileNotFoundError(template)
            read_text(template)
        except (OSError, UnicodeError):
            unreadable_templates.append(name)
    record(
        "templates",
        "environment",
        "failed" if unreadable_templates else "passed",
        (
            "Missing or unreadable: " + ", ".join(unreadable_templates)
            if unreadable_templates
            else "All required scaffold templates are readable UTF-8 text"
        ),
    )
    math_info = report_renderer().math_renderer().renderer_info()
    record(
        "math_renderer",
        "environment",
        "passed" if math_info["available"] else "warning",
        (
            f"Offline LaTeX rendering available: {math_info['engine']} {math_info['version']}"
            if math_info["available"]
            else "Offline LaTeX converter unavailable; reports retain labeled literal LaTeX. "
            "Install latex2mathml once in the shared interpreter listed above using "
            "that interpreter's -m pip install --user latex2mathml."
        ),
    )
    input_kind = getattr(args, "input_kind", None)
    kind_ok = input_kind in {"latex", "pdf_transcription"}
    record(
        "input_kind",
        "input",
        "passed" if kind_ok else "failed",
        str(input_kind),
    )
    paper = args.paper.resolve()
    raw_pdf = paper.suffix.lower() == ".pdf"
    source_ok = paper.is_file() and not raw_pdf
    source_detail = (
        "Raw PDF is not parsed source"
        if raw_pdf
        else (paper.as_posix() if paper.is_file() else f"Source not found: {paper.as_posix()}")
    )
    record(
        "source_path",
        "input",
        "passed" if source_ok else "failed",
        source_detail,
    )
    source_digest: str | None = None
    if source_ok:
        try:
            source_text = read_text(paper)
            if not source_text.strip():
                raise ValueError("Source is empty")
            source_digest = sha256_file(paper)
        except (OSError, UnicodeError, ValueError) as exc:
            record("source_read", "source_read", "failed", str(exc))
        else:
            record(
                "source_read",
                "source_read",
                "passed",
                f"Readable nonempty UTF-8 text; sha256={source_digest}",
            )
    else:
        record("source_read", "source_read", "skipped", "Source path check failed")

    publisher_arg = getattr(args, "publisher_pdf", None)
    publisher_digest: str | None = None
    publisher_size: int | None = None
    if input_kind == "pdf_transcription":
        publisher = publisher_arg.resolve() if isinstance(publisher_arg, Path) else None
        if publisher is None or not publisher.is_file() or publisher.suffix.lower() != ".pdf":
            record(
                "publisher_pdf",
                "source_read",
                "failed",
                publisher.as_posix() if publisher is not None else "Missing --publisher-pdf",
            )
        else:
            try:
                publisher_digest = sha256_file(publisher)
                publisher_size = publisher.stat().st_size
            except OSError as exc:
                record("publisher_pdf", "source_read", "failed", str(exc))
            else:
                record(
                    "publisher_pdf",
                    "source_read",
                    "passed",
                    f"Readable PDF; size={publisher_size}; sha256={publisher_digest}",
                )
    elif publisher_arg is not None:
        record(
            "publisher_pdf",
            "input",
            "failed",
            "--publisher-pdf applies only to pdf_transcription",
        )
    else:
        record("publisher_pdf", "source_read", "skipped", "Not required for LaTeX")
    record(
        "portable_sources",
        "input",
        "passed",
        "enabled" if getattr(args, "portable_sources", False) else "disabled",
    )
    discovery_inputs_ok = False
    discovery_project_root: Path | None = None
    discovery_additional: list[tuple[Path, str, str]] = []
    discovery_fls: Path | None = None
    discovery_report: dict[str, Any] = {
        "status": "skipped",
        "files": [],
        "warnings": [],
        "outside_project_inputs": [],
        "closure_sha256": None,
    }
    if source_ok and kind_ok:
        try:
            (
                discovery_project_root,
                discovery_additional,
                discovery_fls,
            ) = resolve_source_discovery_inputs(
                paper,
                str(input_kind),
                additional_source=getattr(args, "additional_source", None),
                fls=getattr(args, "fls", None),
                project_root=getattr(args, "project_root", None),
            )
        except (OSError, ValueError) as exc:
            record("source_discovery_inputs", "input", "failed", str(exc))
        else:
            discovery_inputs_ok = True
            record(
                "project_root",
                "input",
                "passed",
                discovery_project_root.as_posix(),
            )
            record(
                "additional_sources",
                "input",
                "passed" if discovery_additional else "skipped",
                (
                    f"{len(discovery_additional)} validated"
                    if discovery_additional
                    else "None supplied"
                ),
            )
            record(
                "recorder_file",
                "input",
                "passed" if discovery_fls is not None else "skipped",
                discovery_fls.as_posix() if discovery_fls is not None else "None supplied",
            )
    else:
        record(
            "source_discovery_inputs",
            "input",
            "skipped",
            "Input-kind or source-path check failed",
        )

    if discovery_inputs_ok and input_kind == "latex":
        try:
            discovery = discover_source_closure(
                paper,
                additional_files=[entry[0] for entry in discovery_additional],
                fls_file=discovery_fls,
                project_root=discovery_project_root,
                warning_path_base=(
                    paper.parent
                    if getattr(args, "portable_sources", False)
                    else None
                ),
            )
            discovered_files = [
                path.resolve() for path in discovery.get("files", [])
            ]
            if getattr(args, "portable_sources", False):
                outside = [
                    path
                    for path in discovered_files
                    if discovery_project_root is not None
                    and not path.is_relative_to(discovery_project_root)
                ]
                if outside:
                    raise ValueError(
                        "--portable-sources cannot preserve relative source "
                        "topology outside --project-root; rerun with a broader "
                        "--project-root containing: "
                        + ", ".join(path.as_posix() for path in outside)
                    )
            closure_rows = [
                {
                    "file": source_path_identity(path, paper.parent),
                    "sha256": sha256_file(path),
                }
                for path in discovered_files
            ]
            inventory = scan_formal_units(
                paper, source_files=discovered_files,
                source_warnings=discovery.get("warnings", []),
                path_identity_base=(paper.parent if getattr(args, "portable_sources", False) else None),
            )
            identity_errors = inventory_identity_errors(inventory["units"])
            if identity_errors:
                raise ValueError("; ".join(identity_errors))
        except (OSError, UnicodeError, ValueError) as exc:
            discovery_report["status"] = "failed"
            discovery_report["error"] = str(exc)
            record("source_discovery", "source_read", "failed", str(exc))
        else:
            discovery_report = {
                "status": "passed",
                "files": [row["file"] for row in closure_rows],
                "warnings": list(dict.fromkeys(inventory["warnings"])),
                "outside_project_inputs": list(
                    discovery.get("outside_project_inputs", [])
                ),
                "closure_sha256": canonical_sha256(closure_rows),
            }
            record(
                "source_discovery",
                "source_read",
                "passed",
                (
                    f"{len(discovered_files)} source file(s), "
                    f"{len(discovery_report['warnings'])} review warning(s); "
                    f"closure_sha256={canonical_sha256(closure_rows)}"
                ),
            )
    elif discovery_inputs_ok:
        record(
            "source_discovery",
            "source_read",
            "skipped",
            "LaTeX discovery does not apply to PDF transcription",
        )
    else:
        record(
            "source_discovery",
            "source_read",
            "skipped",
            "Source-discovery input check failed",
        )

    output = args.output.resolve()
    resume_valid = False
    if mode == "resume":
        if not output.is_dir():
            record(
                "resume_audit",
                "input",
                "failed",
                f"Resume audit root is not a directory: {output.as_posix()}",
            )
        else:
            _, resume_manifest, resume_errors = load_audit_manifest(output)
            resume_errors = [
                *audit_internal_redirect_errors(output),
                *resume_errors,
            ]
            manifest_input_kind = "latex"
            if not resume_errors:
                try:
                    manifest_input_kind = validate_input_provenance(
                        resume_manifest,
                        output,
                        resume_errors,
                        final=False,
                    )
                except (OSError, UnicodeError, ValueError) as exc:
                    resume_errors.append(
                        f"Resume input provenance could not be validated: {exc}"
                    )
            if not resume_errors:
                try:
                    provenance_errors = source_snapshot_freshness_errors(
                        output, resume_manifest
                    )
                except (OSError, UnicodeError, ValueError) as exc:
                    provenance_errors = [
                        f"Resume source provenance could not be validated: {exc}"
                    ]
                record(
                    "resume_source_provenance",
                    "source_read",
                    "failed" if provenance_errors else "passed",
                    (
                        "; ".join(provenance_errors)
                        if provenance_errors
                        else "Recorded source snapshot and discovery provenance are current."
                    ),
                )
                resume_errors.extend(provenance_errors)
            if manifest_input_kind != input_kind:
                resume_errors.append(
                    "The supplied input kind does not match the recorded audit "
                    f"input kind ({manifest_input_kind})."
                )
            if manifest_input_kind == "pdf_transcription":
                provenance = resume_manifest.get("input_provenance")
                recorded_publisher = (
                    provenance.get("publisher_pdf")
                    if isinstance(provenance, dict)
                    else None
                )
                recorded_digest = (
                    recorded_publisher.get("sha256")
                    if isinstance(recorded_publisher, dict)
                    else None
                )
                recorded_size = (
                    recorded_publisher.get("size_bytes")
                    if isinstance(recorded_publisher, dict)
                    else None
                )
                if (
                    publisher_digest != recorded_digest
                    or publisher_size != recorded_size
                ):
                    resume_errors.append(
                        "The supplied publisher PDF does not match the recorded "
                        "publisher PDF hash and size."
                    )
            if resume_errors:
                record(
                    "resume_audit",
                    "input",
                    "failed",
                    "; ".join(resume_errors),
                )
            else:
                snapshot = resume_manifest.get("source_snapshot")
                rows = snapshot.get("files") if isinstance(snapshot, dict) else None
                authoritative_value = resume_manifest.get("paper_file")
                authoritative_normalized = (
                    authoritative_value.replace("\\", "/")
                    if is_nonempty_string(authoritative_value)
                    else None
                )
                authoritative_digest = next(
                    (
                        row.get("sha256")
                        for row in rows
                        if isinstance(row, dict)
                        and is_nonempty_string(row.get("file"))
                        and row["file"].replace("\\", "/")
                        == authoritative_normalized
                        and is_nonempty_string(row.get("sha256"))
                    ),
                    None,
                ) if isinstance(rows, list) else None
                supplied_digest = source_digest
                if supplied_digest != authoritative_digest:
                    record(
                        "resume_audit",
                        "input",
                        "failed",
                        "The supplied paper hash does not match the recorded "
                        "authoritative paper.",
                    )
                else:
                    resume_valid = True
                    record(
                        "resume_audit",
                        "input",
                        "passed",
                        "Existing audit manifest and supplied paper hash agree.",
                    )
        probe_parent = output
        parent_ok = output.is_dir() and resume_valid
    else:
        probe_parent = output.parent
        while not probe_parent.exists() and probe_parent != probe_parent.parent:
            probe_parent = probe_parent.parent
        parent_ok = probe_parent.is_dir() and not output.exists()
    record(
        "output_parent",
        "output_write",
        "passed" if parent_ok else "failed",
        (
            f"Existing audit directory probe: {output.as_posix()}"
            if mode == "resume" and output.is_dir()
            else (
                f"Probe parent: {probe_parent.as_posix()}"
                if not output.exists()
                else (
                    f"New audit output already exists: {output.as_posix()}"
                    if mode == "new"
                    else f"Resume output is not usable: {output.as_posix()}"
                )
            )
        ),
    )
    probe_directory: Path | None = None
    if parent_ok:
        try:
            probe_directory = Path(
                tempfile.mkdtemp(prefix=".proofcheck-doctor-", dir=str(probe_parent))
            )
            staged = probe_directory / "write.tmp"
            committed = probe_directory / "rename.ok"
            with staged.open("wb") as stream:
                stream.write(b"proofcheck-doctor\n")
                stream.flush()
                os.fsync(stream.fileno())
            record("output_write", "output_write", "passed", staged.as_posix())
            os.replace(staged, committed)
            record("output_rename", "output_write", "passed", committed.as_posix())
        except OSError as exc:
            if not any(row["id"] == "output_write" for row in checks):
                record("output_write", "output_write", "failed", str(exc))
                record(
                    "output_rename", "output_write", "skipped", "Write probe failed"
                )
            else:
                record("output_rename", "output_write", "failed", str(exc))
        finally:
            if probe_directory is not None and probe_directory.exists():
                try:
                    shutil.rmtree(probe_directory)
                except OSError as exc:
                    record("output_cleanup", "output_write", "failed", str(exc))
    else:
        record(
            "output_write", "output_write", "skipped", "Output-parent check failed"
        )
        record(
            "output_rename", "output_write", "skipped", "Output-parent check failed"
        )

    categories = ("environment", "input", "source_read", "output_write")
    failures = {
        category: sum(
            row["status"] == "failed" and row["category"] == category
            for row in checks
        )
        for category in categories
    }
    ready = not any(failures.values())
    result = {
        "command": "doctor",
        "status": "passed" if ready else "failed",
        "ready": ready,
        "mode": mode,
        "input_kind": input_kind,
        "source_discovery": discovery_report,
        "checks": checks,
        "failures_by_category": failures,
    }
    print(json.dumps(result, ensure_ascii=False, indent=2))
    return 0 if ready else 1


CANARY_ARGUMENT_STATUSES = {"valid", "gap", "invalid", "unclear"}
CANARY_STATEMENT_STATUSES = {
    "established",
    "refuted",
    "not_established",
    "unclear",
}
CANARY_RESPONSE_FIELDS = {
    "canary_id",
    "argument_status",
    "statement_status",
    "defect_lines",
    "justification",
}
CANARY_MAX_DEFECT_LINES = 6
CALIBRATION_SCHEMA_VERSION = 2
CANARY_BUNDLE_SCHEMA_VERSION = 1
CHECKER_BINDING_SCOPE = "prospective_local_proof_checks"
CHECKER_BINDING_LIMITATION = (
    "Checker profile, configuration, and context identifiers are reviewed "
    "coordinator declarations; proofcheck.py cannot independently verify "
    "runtime checker identity. Calibration currency is the declared profile "
    "and configuration; the context identifier records only the canary-run "
    "context. A profile or configuration change requires a new balanced "
    "calibration before further local checking."
)


def canaries_directory() -> Path:
    return Path(__file__).resolve().parent.parent / "assets" / "canaries"


def load_canary_index() -> list[dict[str, Any]]:
    index_path = canaries_directory() / "index.json"
    index, errors = load_json_object(index_path, "canary index")
    if errors:
        raise ValueError(errors[0])
    if index.get("canary_index_schema_version") != 1:
        raise ValueError("Unsupported canary_index_schema_version")
    rows = index.get("canaries")
    if not isinstance(rows, list) or not rows:
        raise ValueError("canary index must list at least one canary")
    validated: list[dict[str, Any]] = []
    seen: set[str] = set()
    for row in rows:
        if not isinstance(row, dict):
            raise ValueError("canary index rows must be objects")
        canary_id = row.get("id")
        if not is_nonempty_string(canary_id) or canary_id in seen:
            raise ValueError("canary index rows need unique nonempty ids")
        seen.add(str(canary_id))
        for field in ("title", "source", "key"):
            if not is_nonempty_string(row.get(field)):
                raise ValueError(f"canary {canary_id} index row needs {field}")
        validated.append(dict(row))
    return validated


def load_canary_key(canary_id: str) -> dict[str, Any]:
    rows = {row["id"]: row for row in load_canary_index()}
    row = rows.get(canary_id)
    if row is None:
        raise ValueError(f"Unknown canary id: {canary_id}")
    key_path = canaries_directory() / str(row["key"])
    key, errors = load_json_object(key_path, "canary answer key")
    if errors:
        raise ValueError(errors[0])
    expected = key.get("expected")
    if (
        key.get("canary_id") != canary_id
        or not isinstance(expected, dict)
        or not isinstance(expected.get("argument_status"), list)
        or not isinstance(expected.get("statement_status"), list)
        or not isinstance(expected.get("defect_line_ranges"), list)
    ):
        raise ValueError(f"Malformed canary answer key: {key_path}")
    return key


def canary_bundle_identity() -> dict[str, Any]:
    """Hash-bind the blinded sources, sealed keys, and public index."""
    directory = canaries_directory().resolve()
    rows = load_canary_index()
    relative_files = {"index.json"}
    for row in rows:
        relative_files.add(str(row["source"]))
        relative_files.add(str(row["key"]))
    files: list[dict[str, str]] = []
    for relative in sorted(relative_files):
        path = (directory / relative).resolve()
        if not path.is_relative_to(directory) or not path.is_file():
            raise ValueError(f"Unsafe or missing canary bundle file: {relative}")
        files.append(
            {
                "file": path.relative_to(directory).as_posix(),
                "sha256": sha256_portable_text_file(path),
            }
        )
    payload = {
        "canary_bundle_schema_version": CANARY_BUNDLE_SCHEMA_VERSION,
        "files": files,
    }
    return {**payload, "sha256": canonical_sha256(payload)}


def calibration_proof_artifacts(root: Path) -> list[dict[str, str]]:
    """Snapshot checker-authored ledgers already present at calibration."""
    local_root = root / "audit" / "04_local_checks"
    if not local_root.is_dir():
        return []
    root_resolved = root.resolve()
    rows: list[dict[str, str]] = []
    for path in live_local_check_artifacts(root, ".ledger.json"):
        resolved = path.resolve()
        if not resolved.is_relative_to(root_resolved):
            raise ValueError(f"Proof artifact escapes audit root: {path}")
        rows.append(
            {
                "file": resolved.relative_to(root_resolved).as_posix(),
                "sha256": sha256_file(resolved),
            }
        )
    return rows


def archive_calibration_record(calibration_path: Path) -> Path:
    """Preserve a stale calibration byte-for-byte under its content hash."""
    redirect_kind = path_redirect_kind(calibration_path)
    if redirect_kind is not None:
        raise ValueError(
            "Refusing to archive a redirected calibration record "
            f"({redirect_kind}): {calibration_path}"
        )
    if not calibration_path.is_file():
        raise ValueError(
            "Calibration recovery requires an existing regular non-symlink "
            f"file: {calibration_path}"
        )
    source_bytes = calibration_path.read_bytes()
    digest = hashlib.sha256(source_bytes).hexdigest()
    history = calibration_path.parent / "calibration-history"
    history_redirect = path_redirect_kind(history)
    if history_redirect is not None:
        raise ValueError(
            "Refusing a redirected calibration history location "
            f"({history_redirect}): {history}"
        )
    if history.exists() and not history.is_dir():
        raise ValueError(
            f"Calibration history location is not a directory: {history}"
        )
    history.mkdir(parents=True, exist_ok=True)
    archive = history / f"CALIBRATION.{digest}.json"
    archive_redirect = path_redirect_kind(archive)
    if archive_redirect is not None:
        raise ValueError(
            "Refusing a redirected calibration history record "
            f"({archive_redirect}): {archive}"
        )
    if archive.exists() and not archive.is_file():
        raise ValueError(
            f"Calibration history record is not a regular file: {archive}"
        )
    if archive.is_file():
        if archive.read_bytes() != source_bytes:
            raise OSError(
                "Hash-addressed calibration archive exists with different bytes: "
                f"{archive}"
            )
        return archive
    temporary = _unique_sibling_temp_path(archive)
    created_archive = False
    try:
        with temporary.open("wb") as target:
            target.write(source_bytes)
            target.flush()
            os.fsync(target.fileno())
        publish_no_overwrite(temporary, archive, "Calibration history record")
        created_archive = True
        if archive.read_bytes() != source_bytes:
            raise OSError(f"Calibration archive hash verification failed: {archive}")
    except Exception:
        if created_archive and archive.is_file():
            archive.unlink()
        raise
    finally:
        if temporary.exists():
            temporary.unlink()
    return archive


def archived_calibration_checker_context_ids(
    root: Path,
) -> tuple[set[str], list[str]]:
    """Read declared context IDs from intact schema-2 history records."""
    history = root / "audit" / "07_runtime" / "calibration-history"
    errors: list[str] = []
    redirect_kind = path_redirect_kind(history)
    if redirect_kind is not None:
        return set(), [
            "checker calibration history is redirected "
            f"({redirect_kind}): {history}"
        ]
    if not history.exists():
        return set(), []
    if not history.is_dir():
        return set(), [f"checker calibration history is not a directory: {history}"]
    try:
        entries = sorted(history.iterdir())
    except OSError as exc:
        return set(), [f"cannot read checker calibration history {history}: {exc}"]
    context_ids: set[str] = set()
    prefix = "CALIBRATION."
    suffix = ".json"
    for archive in entries:
        archive_redirect = path_redirect_kind(archive)
        if archive_redirect is not None:
            errors.append(
                "checker calibration history entry is redirected "
                f"({archive_redirect}): {archive}"
            )
            continue
        if not archive.is_file():
            errors.append(
                f"checker calibration history entry is not a regular file: {archive}"
            )
            continue
        name = archive.name
        expected_digest = (
            name[len(prefix) : -len(suffix)]
            if name.startswith(prefix) and name.endswith(suffix)
            else ""
        )
        if not SHA256_RE.fullmatch(expected_digest):
            errors.append(
                "checker calibration history entry has a noncanonical name: "
                f"{archive}"
            )
            continue
        try:
            source_bytes = archive.read_bytes()
        except OSError as exc:
            errors.append(f"cannot read checker calibration history entry {archive}: {exc}")
            continue
        if hashlib.sha256(source_bytes).hexdigest() != expected_digest:
            errors.append(
                f"checker calibration history entry hash is stale: {archive}"
            )
            continue
        try:
            record = json.loads(source_bytes.decode("utf-8-sig"))
        except (UnicodeDecodeError, json.JSONDecodeError):
            continue
        if (
            not isinstance(record, dict)
            or record.get("calibration_schema_version")
            != CALIBRATION_SCHEMA_VERSION
            or not isinstance(record.get("sessions"), list)
        ):
            continue
        for session in record["sessions"]:
            checker = (
                session.get("checker_binding")
                if isinstance(session, dict)
                else None
            )
            context_id = (
                checker.get("checker_context_id")
                if isinstance(checker, dict)
                else None
            )
            if is_substantive_string(context_id):
                context_ids.add(str(context_id))
    return context_ids, errors


def calibration_update_lock_path(root: Path) -> Path:
    return (
        root.resolve()
        / "audit"
        / "07_runtime"
        / ".CALIBRATION.json.proofcheck.lock"
    )


def calibration_update_lock_error(root: Path) -> str | None:
    lock = calibration_update_lock_path(root)
    redirect_kind = path_redirect_kind(lock)
    if redirect_kind is not None:
        return (
            "checker calibration update lock is redirected "
            f"({redirect_kind}): {lock}"
        )
    if lock.exists():
        return (
            "checker calibration update is in progress or a stale lock remains: "
            f"{lock}. If canary-grade is not running, inspect the lock and "
            "CALIBRATION.json, then remove the lock manually and rerun; it is "
            "never cleared automatically after a crash"
        )
    return None


def acquire_calibration_update_lock(
    root: Path, session_id: str
) -> tuple[Path, bytes]:
    lock = calibration_update_lock_path(root)
    lock.parent.mkdir(parents=True, exist_ok=True)
    redirect_kind = path_redirect_kind(lock)
    if redirect_kind is not None:
        raise ValueError(
            "Refusing a redirected checker calibration update lock "
            f"({redirect_kind}): {lock}"
        )
    record = {
        "transaction_schema_version": 1,
        "target": "CALIBRATION.json",
        "session_id": session_id,
        "process_id": os.getpid(),
        "created_utc": datetime.now(timezone.utc).isoformat(
            timespec="microseconds"
        ),
        "recovery": (
            "If canary-grade is not running, inspect this lock and "
            "CALIBRATION.json, remove the lock manually, and rerun."
        ),
    }
    payload = (json.dumps(record, sort_keys=True) + "\n").encode("utf-8")
    try:
        descriptor = os.open(
            lock,
            os.O_CREAT
            | os.O_EXCL
            | os.O_WRONLY
            | getattr(os, "O_BINARY", 0),
        )
    except FileExistsError as exc:
        raise ValueError(
            calibration_update_lock_error(root)
            or f"checker calibration update lock appeared concurrently: {lock}"
        ) from exc
    try:
        offset = 0
        while offset < len(payload):
            written = os.write(descriptor, payload[offset:])
            if written <= 0:
                raise OSError(f"Cannot write checker calibration lock: {lock}")
            offset += written
        os.fsync(descriptor)
    finally:
        os.close(descriptor)
    return lock, payload


def release_calibration_update_lock(lock: Path, payload: bytes) -> None:
    if (
        path_redirect_kind(lock) is not None
        or not lock.is_file()
        or lock.read_bytes() != payload
    ):
        raise OSError(
            "Checker calibration update lock changed during the transaction; "
            f"inspect and remove it manually only after recovery: {lock}"
        )
    lock.unlink()


def calibration_audit_binding(root: Path) -> dict[str, Any]:
    root = root.resolve()
    lock_error = migration_update_lock_error(root)
    if lock_error is not None:
        raise ValueError(lock_error)
    manifest, errors = load_json_object(
        root / "AUDIT_MANIFEST.json", "audit manifest"
    )
    if errors:
        raise ValueError(errors[0])
    protocol = manifest.get("protocol")
    current_protocol = protocol_identity()
    if not isinstance(protocol, dict) or any(
        protocol.get(field) != expected
        for field, expected in current_protocol.items()
    ):
        raise ValueError(
            "Audit protocol is not current; run status and the required "
            "migration or revalidate-protocol before canary-grade"
        )
    snapshot = manifest.get("source_snapshot")
    snapshot_sha256 = snapshot.get("sha256") if isinstance(snapshot, dict) else None
    if not isinstance(snapshot_sha256, str) or not SHA256_RE.fullmatch(
        snapshot_sha256
    ):
        raise ValueError("Audit manifest has no valid source snapshot binding")
    return {
        "source_snapshot_sha256": snapshot_sha256,
        "validator_sha256": current_protocol["validator_sha256"],
        "preexisting_proof_artifacts": calibration_proof_artifacts(root),
    }


def calibration_checker_binding(args: argparse.Namespace) -> dict[str, Any]:
    fields = {
        "checker_profile_id": getattr(args, "checker_profile_id", None),
        "checker_configuration_id": getattr(
            args, "checker_configuration_id", None
        ),
        "checker_context_id": getattr(args, "checker_context_id", None),
    }
    for field, value in fields.items():
        if not is_substantive_string(value):
            raise ValueError(f"{field.replace('_', '-')} must be substantive")
    if getattr(args, "reviewed_binding", False) is not True:
        raise ValueError(
            "--reviewed-binding is required to record the explicit checker "
            "profile/configuration qualification and context provenance"
        )
    return {
        **fields,
        "reviewed": True,
        "scope": CHECKER_BINDING_SCOPE,
        "automatic_identity_verification": False,
        "limitation": CHECKER_BINDING_LIMITATION,
    }


def cmd_canary_list(args: argparse.Namespace) -> int:
    configure_console_errors()
    rows = load_canary_index()
    print(
        json.dumps(
            {
                "command": "canary-list",
                "canaries": [
                    {"id": row["id"], "title": row["title"]} for row in rows
                ],
                "note": (
                    "Grade with canary-grade. Never open a key file in a "
                    "checking context."
                ),
            },
            ensure_ascii=True,
            indent=2,
        )
    )
    return 0


def cmd_canary_packet(args: argparse.Namespace) -> int:
    configure_console_errors()
    rows = {row["id"]: row for row in load_canary_index()}
    row = rows.get(args.canary_id)
    if row is None:
        raise ValueError(f"Unknown canary id: {args.canary_id}")
    source_path = canaries_directory() / str(row["source"])
    lines = read_lines(source_path)
    output_path = args.output.resolve()
    if containing_audit_root(output_path) is not None:
        raise ValueError("Canary packets must be written outside any audit root")
    packet = {
        "kind": "canary_packet",
        "canary_packet_schema_version": 1,
        "canary_id": row["id"],
        "title": row["title"],
        "instructions": (
            "Audit the single lemma and proof below as a fresh checker, using "
            "only this packet. Judge the written argument against the exact "
            "stated hypotheses: do not repair it, and do not import outside "
            "facts beyond standard definitions. Use mathematical derivations; "
            "do not run numerical experiments or computational searches. "
            "Explain unresolved mathematics as unable to verify, using the "
            "existing unclear statuses. Then respond with exactly one "
            "JSON object matching response_schema. argument_status judges the "
            "written proof; statement_status judges the stated conclusion "
            "itself, where refuted requires an exact counterexample you "
            "verified and established requires the written proof to be valid. "
            "defect_lines lists the physical line numbers of the defective "
            "source sentences, or [] when you find no defect. Never open any "
            "file under assets/canaries."
        ),
        "response_schema": {
            "canary_id": row["id"],
            "argument_status": sorted(CANARY_ARGUMENT_STATUSES),
            "statement_status": sorted(CANARY_STATEMENT_STATUSES),
            "defect_lines": "list of physical source line numbers, [] if none",
            "justification": "2-6 sentences of paper-specific reasoning",
        },
        "source": [
            {"line": index, "text": text}
            for index, text in enumerate(lines, 1)
        ],
    }
    atomic_create_json(output_path, packet, "Canary packet")
    print(
        json.dumps(
            {
                "command": "canary-packet",
                "status": "written",
                "canary_id": row["id"],
                "packet": output_path.as_posix(),
            },
            ensure_ascii=True,
            indent=2,
        )
    )
    return 0


def grade_canary_response(
    response: Any, key: dict[str, Any]
) -> tuple[bool, list[str], dict[str, Any]]:
    reasons: list[str] = []
    got: dict[str, Any] = {}
    if not isinstance(response, dict):
        return False, ["response must be a JSON object"], got
    got = dict(response)
    unknown = set(response) - CANARY_RESPONSE_FIELDS
    missing = CANARY_RESPONSE_FIELDS - set(response)
    if unknown:
        reasons.append(f"unknown fields: {', '.join(sorted(unknown))}")
    if missing:
        reasons.append(f"missing fields: {', '.join(sorted(missing))}")
    if response.get("canary_id") != key.get("canary_id"):
        reasons.append("canary_id does not match the graded canary")
    argument = response.get("argument_status")
    statement = response.get("statement_status")
    defect_lines = response.get("defect_lines")
    if not is_enum_value(argument, CANARY_ARGUMENT_STATUSES):
        reasons.append("argument_status is not a valid enum value")
    if not is_enum_value(statement, CANARY_STATEMENT_STATUSES):
        reasons.append("statement_status is not a valid enum value")
    if not isinstance(defect_lines, list) or not all(
        is_int(line) and line >= 1 for line in defect_lines
    ):
        reasons.append("defect_lines must be a list of positive line numbers")
        defect_lines = None
    elif len(defect_lines) != len(set(defect_lines)):
        reasons.append("defect_lines contains duplicates")
    if not is_substantive_string(response.get("justification")):
        reasons.append("justification must be nonempty and substantive")
    if reasons:
        return False, reasons, got
    expected = key["expected"]
    if argument not in expected["argument_status"]:
        reasons.append("argument_status is not an accepted judgment")
    if statement not in expected["statement_status"]:
        reasons.append("statement_status is not an accepted judgment")
    ranges = expected["defect_line_ranges"]
    if ranges:
        in_range = any(
            any(
                isinstance(span, list)
                and len(span) == 2
                and span[0] <= line <= span[1]
                for span in ranges
            )
            for line in defect_lines
        )
        if not defect_lines or not in_range:
            reasons.append("defect_lines do not locate the defective sentence")
        if len(defect_lines) > CANARY_MAX_DEFECT_LINES:
            reasons.append("defect_lines flags too many lines to be a location")
    elif defect_lines:
        reasons.append("defect_lines flags a defect where none exists")
    return not reasons, reasons, got


def canary_session_composition_errors(
    canary_ids: list[str], prefix: str
) -> list[str]:
    """Require a session to grade at least one flawed-style and one
    correct-style canary, judged from the sealed keys without disclosing
    which submitted canary is which."""
    flawed = 0
    correct = 0
    for canary_id in canary_ids:
        try:
            key = load_canary_key(str(canary_id))
        except (OSError, UnicodeError, ValueError) as exc:
            return [f"{prefix}: cannot verify canary {canary_id!r}: {exc}"]
        if key["expected"]["defect_line_ranges"]:
            flawed += 1
        else:
            correct += 1
    if not flawed or not correct:
        return [
            f"{prefix} must grade at least one flawed-style and one "
            "correct-style canary in the same session"
        ]
    return []


def calibration_exact_fields(
    value: Any, expected: set[str], prefix: str, errors: list[str]
) -> bool:
    if not isinstance(value, dict):
        errors.append(f"{prefix} must be an object")
        return False
    actual = set(value)
    if actual != expected:
        errors.append(
            f"{prefix} must have exact fields: {', '.join(sorted(expected))}"
        )
        return False
    return True


def calibration_record_errors(root: Path, calibration: Any) -> list[str]:
    """Validate every deterministic calibration receipt without gating pass."""
    errors: list[str] = []
    if not calibration_exact_fields(
        calibration,
        {"calibration_schema_version", "canary_bundle", "sessions"},
        "CALIBRATION.json",
        errors,
    ):
        return errors
    if calibration.get("calibration_schema_version") != CALIBRATION_SCHEMA_VERSION:
        return ["CALIBRATION.json has an unsupported calibration_schema_version"]
    try:
        current_bundle = canary_bundle_identity()
    except (OSError, UnicodeError, ValueError) as exc:
        return [f"Cannot verify the sealed canary bundle: {exc}"]
    if calibration.get("canary_bundle") != current_bundle:
        errors.append(
            "CALIBRATION.json canary_bundle does not match the sealed bundle "
            "in the validator; run a new balanced calibration"
        )
    sessions = calibration.get("sessions")
    if not isinstance(sessions, list) or not sessions:
        errors.append("CALIBRATION.json must record at least one session")
        return errors
    seen_sessions: set[str] = set()
    seen_checker_contexts, history_errors = (
        archived_calibration_checker_context_ids(root)
    )
    errors.extend(history_errors)
    session_fields = {
        "session_id",
        "graded_utc",
        "checker_binding",
        "audit_binding",
        "results",
        "passed",
    }
    checker_fields = {
        "checker_profile_id",
        "checker_configuration_id",
        "checker_context_id",
        "reviewed",
        "scope",
        "automatic_identity_verification",
        "limitation",
    }
    audit_fields = {
        "source_snapshot_sha256",
        "validator_sha256",
        "preexisting_proof_artifacts",
    }
    result_fields = {
        "canary_id",
        "passed",
        "reasons",
        "got",
        "response_sha256",
    }
    previous_graded: datetime | None = None
    for session_index, session in enumerate(sessions, 1):
        prefix = f"CALIBRATION.json sessions[{session_index}]"
        if not calibration_exact_fields(session, session_fields, prefix, errors):
            continue
        session_id = session.get("session_id")
        if not is_substantive_string(session_id):
            errors.append(f"{prefix}.session_id must be substantive")
        elif session_id in seen_sessions:
            errors.append(f"{prefix}.session_id is duplicated")
        else:
            seen_sessions.add(str(session_id))
        if not is_utc_timestamp(session.get("graded_utc")):
            errors.append(f"{prefix}.graded_utc must be UTC")
        else:
            graded = datetime.fromisoformat(
                str(session["graded_utc"]).replace("Z", "+00:00")
            )
            if previous_graded is not None and graded <= previous_graded:
                errors.append(
                    f"{prefix}.graded_utc is not strictly later than the "
                    "preceding session"
                )
            previous_graded = graded

        checker = session.get("checker_binding")
        if calibration_exact_fields(
            checker, checker_fields, f"{prefix}.checker_binding", errors
        ):
            for field in (
                "checker_profile_id",
                "checker_configuration_id",
                "checker_context_id",
            ):
                if not is_substantive_string(checker.get(field)):
                    errors.append(
                        f"{prefix}.checker_binding.{field} must be substantive"
                    )
            context_id = checker.get("checker_context_id")
            if is_substantive_string(context_id):
                if context_id in seen_checker_contexts:
                    errors.append(
                        f"{prefix}.checker_binding.checker_context_id is reused "
                        "across sessions"
                    )
                else:
                    seen_checker_contexts.add(str(context_id))
            if (
                checker.get("reviewed") is not True
                or checker.get("scope") != CHECKER_BINDING_SCOPE
                or checker.get("automatic_identity_verification") is not False
                or checker.get("limitation") != CHECKER_BINDING_LIMITATION
            ):
                errors.append(
                    f"{prefix}.checker_binding does not match the reviewed "
                    "binding contract"
                )

        audit_binding = session.get("audit_binding")
        artifact_rows: list[Any] = []
        if calibration_exact_fields(
            audit_binding, audit_fields, f"{prefix}.audit_binding", errors
        ):
            # The snapshot and validator hashes are recorded provenance, not
            # currency requirements: calibration attests the CHECKER, and the
            # canaries are self-contained, so a paper edit or validator
            # release does not invalidate a session. Requiring equality with
            # the current audit here would force a full recalibration (and,
            # through the receipt binding, a mandated re-review of every
            # ledger) after every routine source repair. Currency is enforced
            # where it belongs: the canary-bundle digest stales sessions when
            # the canaries change, per-response re-grading under the current
            # grader stales them when grading semantics change, and a changed
            # A changed checker profile or configuration requires a new
            # session by contract. The context ID is run provenance only.
            for field in ("source_snapshot_sha256", "validator_sha256"):
                value = audit_binding.get(field)
                if not isinstance(value, str) or not SHA256_RE.fullmatch(value):
                    errors.append(
                        f"{prefix}.audit_binding.{field} must be a SHA-256 digest"
                    )
            artifact_rows = audit_binding.get("preexisting_proof_artifacts")
            if not isinstance(artifact_rows, list):
                errors.append(
                    f"{prefix}.audit_binding.preexisting_proof_artifacts "
                    "must be a list"
                )
                artifact_rows = []
            seen_files: set[str] = set()
            for artifact_index, artifact in enumerate(artifact_rows, 1):
                artifact_prefix = (
                    f"{prefix}.audit_binding.preexisting_proof_artifacts"
                    f"[{artifact_index}]"
                )
                if not calibration_exact_fields(
                    artifact, {"file", "sha256"}, artifact_prefix, errors
                ):
                    continue
                file_value = artifact.get("file")
                digest = artifact.get("sha256")
                if (
                    not is_nonempty_string(file_value)
                    or "\\" in file_value
                    or not file_value.startswith("audit/04_local_checks/")
                    or not file_value.endswith(".ledger.json")
                    or "/"
                    in file_value.removeprefix("audit/04_local_checks/")
                ):
                    errors.append(f"{artifact_prefix}.file is not canonical")
                elif file_value in seen_files:
                    errors.append(f"{artifact_prefix}.file is duplicated")
                else:
                    seen_files.add(str(file_value))
                    resolved = (root / str(file_value)).resolve()
                    if not resolved.is_relative_to(root.resolve()):
                        errors.append(f"{artifact_prefix}.file escapes audit root")
                if not isinstance(digest, str) or not SHA256_RE.fullmatch(digest):
                    errors.append(f"{artifact_prefix}.sha256 is invalid")

        results = session.get("results")
        if not isinstance(results, list) or not results:
            errors.append(f"{prefix}.results must be a nonempty list")
            continue
        seen_canaries: set[str] = set()
        recomputed_passes: list[bool] = []
        for result_index, result in enumerate(results, 1):
            result_prefix = f"{prefix}.results[{result_index}]"
            if not calibration_exact_fields(
                result, result_fields, result_prefix, errors
            ):
                continue
            canary_id = result.get("canary_id")
            if not is_nonempty_string(canary_id):
                errors.append(f"{result_prefix}.canary_id must be nonempty")
                continue
            if canary_id in seen_canaries:
                errors.append(f"{result_prefix}.canary_id is duplicated")
                continue
            seen_canaries.add(str(canary_id))
            got = result.get("got")
            if not isinstance(got, dict):
                errors.append(f"{result_prefix}.got must be an object")
                continue
            expected_response_sha256 = canonical_sha256(got)
            if result.get("response_sha256") != expected_response_sha256:
                errors.append(f"{result_prefix}.response_sha256 is stale")
            try:
                key = load_canary_key(str(canary_id))
                recomputed_passed, recomputed_reasons, _ = grade_canary_response(
                    got, key
                )
            except (OSError, UnicodeError, ValueError) as exc:
                errors.append(f"{result_prefix} cannot be re-graded: {exc}")
                continue
            recomputed_passes.append(recomputed_passed)
            if result.get("passed") is not recomputed_passed:
                errors.append(f"{result_prefix}.passed disagrees with re-grading")
            if result.get("reasons") != recomputed_reasons:
                errors.append(f"{result_prefix}.reasons disagree with re-grading")
        recomputed_session_passed = bool(recomputed_passes) and all(
            recomputed_passes
        )
        if session.get("passed") is not recomputed_session_passed:
            errors.append(f"{prefix}.passed disagrees with its result receipts")
        errors.extend(
            canary_session_composition_errors(sorted(seen_canaries), prefix)
        )
    return errors


def current_calibration_receipt(root: Path) -> dict[str, Any]:
    """Return the validated checker-profile qualification identity."""
    lock_error = calibration_update_lock_error(root)
    if lock_error is not None:
        raise ValueError(
            "Cannot generate packet while checker calibration is locked: "
            + lock_error
        )
    calibration_path = root / "audit" / "07_runtime" / "CALIBRATION.json"
    calibration, read_errors = load_json_object(
        calibration_path, "checker calibration record"
    )
    if read_errors:
        raise ValueError(
            "Cannot generate packet without a current checker calibration: "
            + read_errors[0]
        )
    record_errors = calibration_record_errors(root, calibration)
    if record_errors:
        raise ValueError(
            "Cannot generate packet without a current checker calibration: "
            + record_errors[0]
        )
    latest = calibration["sessions"][-1]
    if latest["passed"] is not True:
        raise ValueError(
            "Cannot generate packet until the latest balanced checker "
            "calibration session passes"
        )
    identity = {
        "calibration_schema_version": CALIBRATION_SCHEMA_VERSION,
        "canary_bundle_sha256": calibration["canary_bundle"]["sha256"],
        "checker_profile_id": latest["checker_binding"]["checker_profile_id"],
        "checker_configuration_id": latest["checker_binding"][
            "checker_configuration_id"
        ],
    }
    return {**identity, "sha256": canonical_sha256(identity)}


def checker_calibration_errors(root: Path) -> list[str]:
    """Gate finalization on a current, passing, auditable calibration."""
    lock_error = calibration_update_lock_error(root)
    if lock_error is not None:
        return [lock_error]
    calibration_path = root / "audit" / "07_runtime" / "CALIBRATION.json"
    if not calibration_path.is_file():
        return [
            "checker calibration required: no calibration session is "
            "recorded; run canary-grade --root with a balanced session "
            "before finalization"
        ]
    calibration, errors = load_json_object(
        calibration_path, "checker calibration record"
    )
    if errors:
        return errors
    errors = calibration_record_errors(root, calibration)
    if errors:
        return errors
    latest = calibration["sessions"][-1]
    if latest["passed"] is not True:
        return [
            "checker calibration failed: the most recent recorded canary "
            f"session {latest['session_id']!r} did not pass; rerun "
            "canary-grade with a passing session before finalization"
        ]
    latest_ids = [str(result["canary_id"]) for result in latest["results"]]
    errors = canary_session_composition_errors(
        latest_ids,
        "checker calibration: the most recent session "
        f"{latest['session_id']!r}",
    )
    return errors


def commit_calibration_session(
    root: Path,
    calibration_path: Path,
    bundle: dict[str, Any],
    session: dict[str, Any],
) -> None:
    """Append one session while the exclusive calibration lock is held."""
    if calibration_path.exists() and not calibration_path.is_file():
        raise ValueError(
            "Checker calibration record must be a regular non-symlink file"
        )
    if calibration_path.is_file():
        calibration, errors = load_json_object(
            calibration_path, "checker calibration record"
        )
        if errors:
            archive_calibration_record(calibration_path)
            calibration = {
                "calibration_schema_version": CALIBRATION_SCHEMA_VERSION,
                "canary_bundle": bundle,
                "sessions": [],
            }
        elif calibration.get("calibration_schema_version") == 1:
            archive_calibration_record(calibration_path)
            calibration = {
                "calibration_schema_version": CALIBRATION_SCHEMA_VERSION,
                "canary_bundle": bundle,
                "sessions": [],
            }
        else:
            record_errors = calibration_record_errors(root, calibration)
            if record_errors:
                archive_calibration_record(calibration_path)
                calibration = {
                    "calibration_schema_version": CALIBRATION_SCHEMA_VERSION,
                    "canary_bundle": bundle,
                    "sessions": [],
                }
        sessions = calibration["sessions"]
    else:
        calibration = {
            "calibration_schema_version": CALIBRATION_SCHEMA_VERSION,
            "canary_bundle": bundle,
            "sessions": [],
        }
        sessions = calibration["sessions"]
    if any(
        row.get("session_id") == session["session_id"] for row in sessions
    ):
        raise ValueError(
            f"Calibration session {session['session_id']!r} already exists"
        )
    sessions.append(session)
    post_append_errors = calibration_record_errors(root, calibration)
    if post_append_errors:
        raise ValueError(post_append_errors[0])
    atomic_write_json(calibration_path, calibration)


def cmd_canary_grade(args: argparse.Namespace) -> int:
    configure_console_errors()
    root = args.root.resolve()
    if not (root / "AUDIT_MANIFEST.json").is_file():
        raise ValueError(f"No audit manifest under {root}")
    audit_binding = calibration_audit_binding(root)
    checker_binding = calibration_checker_binding(args)
    bundle = canary_bundle_identity()
    results: list[dict[str, Any]] = []
    seen_ids: list[str] = []
    for response_path in args.response:
        resolved = response_path.resolve()
        response, errors = load_json_object(resolved, "canary response")
        if errors:
            raise ValueError(errors[0])
        canary_id = response.get("canary_id")
        if not is_nonempty_string(canary_id):
            raise ValueError(f"{resolved} does not name a canary_id")
        if canary_id in seen_ids:
            raise ValueError(f"Duplicate response for canary {canary_id}")
        seen_ids.append(str(canary_id))
        key = load_canary_key(str(canary_id))
        passed, reasons, got = grade_canary_response(response, key)
        results.append(
            {
                "canary_id": canary_id,
                "passed": passed,
                "reasons": reasons,
                "got": got,
                "response_sha256": canonical_sha256(got),
            }
        )
    composition_errors = canary_session_composition_errors(
        seen_ids, "a calibration session"
    )
    if composition_errors:
        raise ValueError(composition_errors[0])
    session_passed = all(result["passed"] for result in results)
    session = {
        "session_id": args.session_id,
        "graded_utc": datetime.now(timezone.utc).isoformat(timespec="microseconds"),
        "checker_binding": checker_binding,
        "audit_binding": audit_binding,
        "results": results,
        "passed": session_passed,
    }
    path_errors: list[str] = []
    calibration_path, path_valid = canonical_artifact_path(
        root,
        "audit/07_runtime/CALIBRATION.json",
        "checker calibration record",
        path_errors,
    )
    if not path_valid:
        raise ValueError(path_errors[0])
    if calibration_path.exists() and not calibration_path.is_file():
        raise ValueError(
            "Checker calibration record must be a regular non-symlink file"
        )
    lock, lock_payload = acquire_calibration_update_lock(root, args.session_id)
    try:
        commit_calibration_session(
            root, calibration_path, bundle, session
        )
    finally:
        release_calibration_update_lock(lock, lock_payload)
    recorded_to = calibration_path.as_posix()
    print(
        json.dumps(
            {
                "command": "canary-grade",
                "session_id": args.session_id,
                "passed": session_passed,
                "results": results,
                "recorded_to": recorded_to,
                "preexisting_proof_artifacts": audit_binding[
                    "preexisting_proof_artifacts"
                ],
                "note": (
                    "A recorded failing session blocks finalization until a "
                    "later session passes. Listed preexisting proof artifacts "
                    "are historical provenance only. Expected verdicts are "
                    "never disclosed by this command."
                ),
            },
            ensure_ascii=True,
            indent=2,
        )
    )
    return 0 if session_passed else 1


def cmd_delivery_check(args: argparse.Namespace) -> int:
    """Return FINAL only for a current usable passed finalization record."""
    root = args.root.resolve()
    freshness = None
    try:
        freshness = check_finalization_freshness(root)
        usable = freshness.get("usable_finalization") is True
        reasons = list(freshness.get("stale_reasons", []))
        if not usable:
            reasons.extend(freshness.get("current_gate_errors", []))
            if not reasons:
                reasons.append("No current usable passed FINALIZATION record")
        record_status = str(freshness.get("record_status", "unknown"))
        freshness_status = str(freshness.get("freshness", "unknown"))
    except Exception as exc:
        usable = False
        record_status = "invalid"
        freshness_status = "unknown"
        reasons = [f"Delivery preflight could not be completed: {exc}"]
    result = {
        "command": "delivery-check",
        "audit_root": root.as_posix(),
        "delivery_status": "FINAL" if usable else "NONFINAL",
        "usable_finalization": usable,
        "record_status": record_status,
        "freshness": freshness_status,
        "reasons": list(dict.fromkeys(str(reason) for reason in reasons)),
        "report": (
            (root / preferred_report_path(load_audit_manifest(root)[1])).as_posix()
            if usable
            else None
        ),
    }
    if not usable and freshness is not None:
        diagnosis = report_module("proofcheck_release").presentation_refresh_note(
            report_api(), root, freshness)
        if diagnosis:
            result["diagnosis"] = diagnosis
    print(json.dumps(result, ensure_ascii=False, indent=2))
    return 0 if usable else 1


def add_output_arguments(parser: argparse.ArgumentParser) -> None:
    parser.add_argument("--format", choices=("json", "markdown"), default="json")
    parser.add_argument("--output", type=Path)
    parser.add_argument("--force", action="store_true", help="Replace an existing output file")


