def main() -> int:
    configure_console_errors()
    parser = build_parser()
    args = parser.parse_args()
    try:
        return int(args.func(args))
    except (
        FileExistsError,
        FileNotFoundError,
        ValueError,
        OSError,
        UnicodeError,
    ) as exc:
        print(f"ERROR: {exc}", file=sys.stderr)
        return 2


if __name__ == "__main__":
    sys.exit(main())
